VALUES ('tpl_resellerapplicationform', 'reseller-application-form', 'Reseller application form', 'Form', 'Screen potential resellers on how and where they sell before anyone gets on a call.', 'Built for a partner manager who gets more reseller requests than they can call back. It asks the questions that separate a real sales channel from a curious buyer, stops early for businesses that are not registered yet, and only asks about competing brands when the applicant already sells some.', '["application","reseller application","reseller program","partner application","dealer application","branching"]', 'Store', 'contact', 4, 14, '{"schemaVersion":9,"title":"Reseller application","description":"Screen potential resellers on how and where they sell before anyone gets on a call.","blocks":[{"id":"blk_reseller00","ref":"welcome","title":"Thanks for your interest in reselling with us. This takes about four minutes and helps us reply with something useful.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_reseller01","ref":"contact","title":"Who should we get back to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_reseller02","ref":"business_name","title":"What is your business called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_reseller03","ref":"website","title":"Where can we see your business online?","description":"A website, marketplace store or social page all work.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_reseller04","ref":"registered","title":"Is the business legally registered, with a tax or company number?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, it is","noLabel":"Not yet"},{"id":"blk_reseller05","ref":"business_type","title":"Which best describes how you sell?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_online_store_of","label":"Online store of my own","image_key":null},{"id":"opt_marketplace_seller","label":"Marketplace seller","image_key":null},{"id":"opt_physical_shop_or","label":"Physical shop or showroom","image_key":null},{"id":"opt_distributor_or_wholesaler","label":"Distributor or wholesaler","image_key":null},{"id":"opt_agency_or_consultant","label":"Agency or consultant reselling to clients","image_key":null}],"allowOther":true},{"id":"blk_reseller06","ref":"years_trading","title":"How long have you been trading?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_less_than_a","label":"Less than a year","image_key":null},{"id":"opt_1_to_3","label":"1 to 3 years","image_key":null},{"id":"opt_3_to_10","label":"3 to 10 years","image_key":null},{"id":"opt_more_than_10","label":"More than 10 years","image_key":null}]},{"id":"blk_reseller07","ref":"location","title":"Where is the business based?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["city","state","country"],"location":"off"},{"id":"blk_reseller08","ref":"channels","title":"Which channels would you use to sell our products?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_own_website","label":"Own website","image_key":null},{"id":"opt_online_marketplaces","label":"Online marketplaces","image_key":null},{"id":"opt_retail_shop","label":"Retail shop","image_key":null},{"id":"opt_trade_shows_and","label":"Trade shows and events","image_key":null},{"id":"opt_direct_sales_team","label":"Direct sales team","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":true},{"id":"blk_reseller09","ref":"target_market","title":"Who are your customers, and which regions do you cover?","description":"For example: small cafes across the north of the country, or home cooks buying online nationwide.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_reseller10","ref":"sells_similar","title":"Do you already sell products similar to ours?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_reseller11","ref":"similar_brands","title":"Which brands, and how are they selling for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_reseller12","ref":"expected_volume","title":"Roughly how many units could you sell in a typical month once you are set up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_50","label":"Under 50","image_key":null},{"id":"opt_50_to_200","label":"50 to 200","image_key":null},{"id":"opt_200_to_1","label":"200 to 1,000","image_key":null},{"id":"opt_more_than_1","label":"More than 1,000","image_key":null},{"id":"opt_too_early_to","label":"Too early to say","image_key":null}],"allowOther":false},{"id":"blk_reseller13","ref":"support_needed","title":"What would help you sell well?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_product_training","label":"Product training","image_key":null},{"id":"opt_marketing_materials_and","label":"Marketing materials and photos","image_key":null},{"id":"opt_demo_or_sample","label":"Demo or sample stock","image_key":null},{"id":"opt_co_marketing","label":"Co-marketing","image_key":null},{"id":"opt_a_dedicated_account","label":"A dedicated account contact","image_key":null}],"minSelections":0,"maxSelections":6,"allowOther":false},{"id":"blk_reseller14","ref":"why_join","title":"Why do you want to resell our products in particular?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false}],"endings":[{"id":"end_reseller01","ref":"end_thanks","title":"Application received 🤝","bodyMd":"Our partner team reviews every application and will reply by email within a few working days, either way.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_reseller02","ref":"end_not_registered","title":"Thanks for getting in touch","bodyMd":"Our reseller program is open to registered businesses only, so we can''t take this application further for now. Once your business is registered, come back and apply again. We''d be glad to hear from you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_reseller01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"registered"},"op":"eq","value":false}],"groups":[]},"from":"registered","target":"end_not_registered","targetKind":"ending","branch":"true"},{"id":"rl_reseller02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"registered"},"op":"eq","value":true}],"groups":[]},"from":"registered","target":"business_type","targetKind":"block","branch":"true"},{"id":"rl_reseller03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"sells_similar"},"op":"eq","value":true}],"groups":[]},"from":"sells_similar","target":"similar_brands","targetKind":"block","branch":"true"},{"id":"rl_reseller04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"sells_similar"},"op":"eq","value":false}],"groups":[]},"from":"sells_similar","target":"expected_volume","targetKind":"block","branch":"true"},{"id":"rl_reseller05","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"similar_brands","target":"support_needed","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
