VALUES ('tpl_speakersubmission', 'speaker-submission', 'Call for speakers form', 'Form', 'Take talk proposals in a shape a review committee can compare at a glance.', 'Proposals tend to arrive as essays when a committee needs a title, an abstract, a length and a bio side by side. This asks for exactly that, then branches: workshop proposals are asked what only a workshop needs, like room setup and what attendees must install, and first-time speakers are offered a mentor.', '["application","call for speakers","cfp form","conference speaker application","talk proposal","branching"]', 'Mic', 'contact', 5, 17, '{"schemaVersion":9,"title":"Call for speakers","description":"Take talk proposals in a shape a review committee can compare at a glance.","blocks":[{"id":"blk_speakers00","ref":"welcome","title":"Got a talk in you? Tell us about it. Most people finish in about five minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_speakers01","ref":"contact","title":"Who is proposing the talk?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_speakers02","ref":"pronouns","title":"Which pronouns should we use in the programme?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_speakers03","ref":"talk_title","title":"What is the talk called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_speakers04","ref":"abstract","title":"Give us the abstract. What is the talk about, and why now?","description":"This is what attendees will read in the programme, so write it for them.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_speakers05","ref":"takeaways","title":"Name three things someone will be able to do after your session.","description":"One per line. Reviewers weigh this more than anything else, so make it concrete.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_speakers06","ref":"format","title":"Which format fits the talk best?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_lightning_talk_10","label":"Lightning talk (10 min)","image_key":null},{"id":"opt_standard_talk_30","label":"Standard talk (30 min)","image_key":null},{"id":"opt_workshop_90_min","label":"Workshop (90 min)","image_key":null}],"allowOther":false},{"id":"blk_speakers07","ref":"workshop_prereqs","title":"What must attendees install or know before they arrive?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_speakers08","ref":"workshop_capacity","title":"How many people can you teach at once?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":5,"max":200,"integerOnly":true},{"id":"blk_speakers09","ref":"workshop_room","title":"What room setup do you need?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_tables_in_groups","label":"Tables in groups","image_key":null},{"id":"opt_theatre_rows","label":"Theatre rows","image_key":null},{"id":"opt_horseshoe","label":"Horseshoe","image_key":null},{"id":"opt_doesn_t_matter","label":"Doesn''t matter","image_key":null}],"allowOther":false},{"id":"blk_speakers10","ref":"level","title":"Who is the talk for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_beginners","label":"Beginners","image_key":null},{"id":"opt_intermediate","label":"Intermediate","image_key":null},{"id":"opt_advanced","label":"Advanced","image_key":null},{"id":"opt_everyone","label":"Everyone","image_key":null}],"allowOther":false},{"id":"blk_speakers11","ref":"bio","title":"Write a short speaker bio, in the third person.","description":"Two or three sentences, as it would appear on the website.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_speakers12","ref":"headshot","title":"Add a headshot for the programme, if you have one.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*"],"maxFiles":1,"maxSizeMB":10},{"id":"blk_speakers13","ref":"spoken_before","title":"Have you spoken at a conference before?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"This would be my first"},{"id":"blk_speakers14","ref":"previous_talk","title":"Share a link to a previous talk, video or slides.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_speakers15","ref":"wants_mentor","title":"Would you like a mentor to help you prepare?","description":"We pair first-time speakers with someone who has done it before.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes please","noLabel":"No thanks"},{"id":"blk_speakers16","ref":"travel_support","title":"Would you need help with travel costs?","description":"We ask everyone, and it never counts against a proposal.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_speakers17","ref":"recording","title":"Recording","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"If my talk is accepted, I agree that it may be recorded and the video and slides published after the event.","allowDecline":true,"agreeLabel":"Happy to be recorded","declineLabel":"Please don''t record"}],"endings":[{"id":"end_speakers01","ref":"end_thanks","title":"Proposal submitted 🎤","bodyMd":"Thank you. We review proposals in batches after the deadline and reply to everyone, accepted or not.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_speakers01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"previous_talk","target":"travel_support","targetKind":"block"},{"id":"rl_speakers02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"format"},"op":"eq","value":"opt_lightning_talk_10"}],"groups":[]},"from":"format","target":"level","targetKind":"block","branch":"true"},{"id":"rl_speakers03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"format"},"op":"eq","value":"opt_standard_talk_30"}],"groups":[]},"from":"format","target":"level","targetKind":"block","branch":"true"},{"id":"rl_speakers04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"format"},"op":"eq","value":"opt_workshop_90_min"}],"groups":[]},"from":"format","target":"workshop_prereqs","targetKind":"block","branch":"true"},{"id":"rl_speakers05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"spoken_before"},"op":"eq","value":true}],"groups":[]},"from":"spoken_before","target":"previous_talk","targetKind":"block","branch":"true"},{"id":"rl_speakers06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"spoken_before"},"op":"eq","value":false}],"groups":[]},"from":"spoken_before","target":"wants_mentor","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#221d44","surface":"#2d2757","text":"#f5f3ff","accent":"#ff8a4c","accentText":"#1c1917","botBubble":"#332c5e","userBubble":"#ff8a4c","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
