,"required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_a_friend_or","label":"A friend or colleague","image_key":null},{"id":"opt_search_engine","label":"Search engine","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_an_event","label":"An event","image_key":null},{"id":"opt_advertising","label":"Advertising","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_customer11","ref":"marketing_consent","title":"Updates and offers","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I''m happy to receive occasional news and offers by email. I can unsubscribe at any time. Account and service messages are sent either way.","allowDecline":true,"agreeLabel":"Yes, send me updates","declineLabel":"No thanks"},{"id":"blk_customer12","ref":"notes","title":"Anything we should note on your account?","description":"Access instructions, accessibility needs, a second contact.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"You''re all set ✅","bodyMd":"Your details are saved. If anything changes, just reply to any email from us.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"customer_type"},"op":"eq","value":"opt_for_myself"}],"groups":[]},"from":"customer_type","target":"address","targetKind":"block","branch":"true"},{"id":"rl_customer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"customer_type"},"op":"eq","value":"opt_for_a_business"}],"groups":[]},"from":"customer_type","t