VALUES ('tpl_bookingrequestform', 'booking-request-form', 'Booking request form', 'Form', 'Gather everything you need to check availability before you confirm a booking.', 'Built for places that confirm by hand: a venue, studio, rental or service with limited slots. It collects the preferred date and time, how long, how many people and what extras they need. Anyone who says their date is flexible is asked for a second choice straight away, which saves a round of emails when the first date is taken.', '["business","booking request","venue booking","reservation request","availability","branching"]', 'CalendarCheck', 'scale', 3, 9, '{"schemaVersion":9,"title":"Booking request","description":"Gather everything you need to check availability before you confirm a booking.","blocks":[{"id":"blk_bookingr00","ref":"welcome","title":"Hi! Tell us what you''d like to book and we''ll check availability.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_bookingr01","ref":"booking_for","title":"What''s the booking for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_private_event","label":"A private event","image_key":null},{"id":"opt_a_meeting_or","label":"A meeting or workshop","image_key":null},{"id":"opt_a_class_or","label":"A class or rehearsal","image_key":null},{"id":"opt_a_photo_or","label":"A photo or video shoot","image_key":null}],"allowOther":true},{"id":"blk_bookingr02","ref":"preferred_date","title":"Which date and start time would you like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":30,"timeMin":"08:00","timeMax":"21:00"},{"id":"blk_bookingr03","ref":"duration","title":"How long do you need it for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_up_to_2","label":"Up to 2 hours","image_key":null},{"id":"opt_half_a_day","label":"Half a day","image_key":null},{"id":"opt_a_full_day","label":"A full day","image_key":null},{"id":"opt_more_than_one","label":"More than one day","image_key":null}],"allowOther":false},{"id":"blk_bookingr04","ref":"date_flexible","title":"If that date is taken, could you do another?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, I''m flexible","noLabel":"No, it has to be that date"},{"id":"blk_bookingr05","ref":"backup_date","title":"What would your second choice be?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":30,"timeMin":"08:00","timeMax":"21:00"},{"id":"blk_bookingr06","ref":"group_size","title":"How many people, including you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"integerOnly":true},{"id":"blk_bookingr07","ref":"extras","title":"Would you like any of these added?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_food_or_drinks","label":"Food or drinks","image_key":null},{"id":"opt_screen_sound_or","label":"Screen, sound or projector","image_key":null},{"id":"opt_tables_and_chairs","label":"Tables and chairs set up for you","image_key":null},{"id":"opt_extra_time_to","label":"Extra time to set up or pack down","image_key":null},{"id":"opt_parking","label":"Parking","image_key":null},{"id":"opt_none_of_these","label":"None of these","image_key":null}],"minSelections":0,"maxSelections":6,"allowOther":false},{"id":"blk_bookingr08","ref":"details","title":"Tell us a little about what you have planned","description":"Layout, accessibility needs, anything unusual.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_bookingr09","ref":"contact","title":"Who should we send the confirmation to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]}],"endings":[{"id":"end_bookingr01","ref":"end_thanks","title":"Request received 📅","bodyMd":"This isn''t confirmed yet. We''ll check availability and get back to you with a yes, or with the nearest dates we have.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_bookingr01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"date_flexible"},"op":"eq","value":true}],"groups":[]},"from":"date_flexible","target":"backup_date","targetKind":"block","branch":"true"},{"id":"rl_bookingr02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"date_flexible"},"op":"eq","value":false}],"groups":[]},"from":"date_flexible","target":"group_size","targetKind":"block","branch":"true"},{"id":"rl_bookingr03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"backup_date","target":"extras","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f3e6ff","surface":"#ffffff","text":"#2b1638","accent":"#9333ea","accentText":"#fdf9ff","botBubble":"#ffffff","userBubble":"#9333ea","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"confetti","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
