VALUES ('tpl_cateringinquiryform', 'catering-inquiry-form', 'Catering inquiry form', 'Form', 'Everything a caterer needs to write a proposal, gathered in one conversation.', 'Written the way a caterer runs a first planning call, with the logistics a quote depends on. It asks about the event, the guests, the venue and whether food is served indoors or out, then the service style decides what comes next: a drop-off order skips the staffing questions, while a staffed event is asked about the venue kitchen and what equipment you need to bring. Dietary needs and a ranked list of priorities help you pitch the right menu.', '["business","catering inquiry","catering request form","event catering","catering quote","branching"]', 'ChefHat', 'scale', 4, 14, '{"schemaVersion":9,"title":"Catering inquiry","description":"Everything a caterer needs to write a proposal, gathered in one conversation.","blocks":[{"id":"blk_catering00","ref":"welcome","title":"Hello! Walk us through your event and we''ll build a menu and quote around it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_catering01","ref":"occasion","title":"What''s the occasion?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_wedding","label":"Wedding","image_key":null},{"id":"opt_corporate_event","label":"Corporate event","image_key":null},{"id":"opt_birthday_or_private","label":"Birthday or private party","image_key":null},{"id":"opt_memorial_or_wake","label":"Memorial or wake","image_key":null},{"id":"opt_conference_or_meeting","label":"Conference or meeting","image_key":null}],"allowOther":true},{"id":"blk_catering02","ref":"event_date","title":"When is it, and roughly what time should food be served?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":30,"timeMin":"07:00","timeMax":"22:00"},{"id":"blk_catering03","ref":"guests","title":"How many guests are you expecting?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"integerOnly":true},{"id":"blk_catering04","ref":"venue","title":"Where is the event?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal"],"location":"off"},{"id":"blk_catering05","ref":"venue_setting","title":"Will food be served indoors, outdoors or both?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_indoors","label":"Indoors","image_key":null},{"id":"opt_outdoors","label":"Outdoors","image_key":null},{"id":"opt_a_mix_of","label":"A mix of both","image_key":null},{"id":"opt_not_decided_yet","label":"Not decided yet","image_key":null}],"allowOther":false},{"id":"blk_catering06","ref":"service_style","title":"What kind of service are you picturing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_drop_off","label":"Drop-off","description":"We deliver, you serve","image_key":null},{"id":"opt_buffet_with_staff","label":"Buffet with staff","image_key":null},{"id":"opt_plated_sit_down","label":"Plated sit-down meal","image_key":null},{"id":"opt_canap_s_and","label":"Canapés and drinks reception","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}],"allowOther":false},{"id":"blk_catering07","ref":"venue_kitchen","title":"Is there a kitchen at the venue we can use?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_a_full","label":"Yes, a full kitchen","image_key":null},{"id":"opt_just_a_small","label":"Just a small prep area","image_key":null},{"id":"opt_no_kitchen","label":"No kitchen","image_key":null},{"id":"opt_i_don_t","label":"I don''t know","image_key":null}],"allowOther":false},{"id":"blk_catering08","ref":"equipment","title":"Should we bring or provide any of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_plates_cutlery_and","label":"Plates, cutlery and glasses","image_key":null},{"id":"opt_tables_and_linen","label":"Tables and linen","image_key":null},{"id":"opt_bar_service","label":"Bar service","image_key":null},{"id":"opt_clearing_up_afterwards","label":"Clearing up afterwards","image_key":null},{"id":"opt_the_venue_provides","label":"The venue provides all of it","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_catering09","ref":"menu_style","title":"What sort of food would suit the event?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_light_bites_and","label":"Light bites and finger food","image_key":null},{"id":"opt_classic_comfort_food","label":"Classic comfort food","image_key":null},{"id":"opt_mediterranean","label":"Mediterranean","image_key":null},{"id":"opt_asian","label":"Asian","image_key":null},{"id":"opt_barbecue","label":"Barbecue","image_key":null},{"id":"opt_desserts_and_cake","label":"Desserts and cake","image_key":null}],"minSelections":0,"maxSelections":4,"allowOther":true},{"id":"blk_catering10","ref":"dietary","title":"Which dietary needs should the menu cover?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_vegetarian","label":"Vegetarian","image_key":null},{"id":"opt_vegan","label":"Vegan","image_key":null},{"id":"opt_gluten_free","label":"Gluten-free","image_key":null},{"id":"opt_dairy_free","label":"Dairy-free","image_key":null},{"id":"opt_nut_allergy","label":"Nut allergy","image_key":null},{"id":"opt_halal","label":"Halal","image_key":null},{"id":"opt_kosher","label":"Kosher","image_key":null},{"id":"opt_none_that_i","label":"None that I know of","image_key":null}],"minSelections":0,"maxSelections":8,"allowOther":false},{"id":"blk_catering11","ref":"priorities","title":"Put these in order of what matters most to you","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_the_food","label":"The food itself"},{"id":"opt_item_staying_on","label":"Staying on budget"},{"id":"opt_item_how_it","label":"How it looks on the table"},{"id":"opt_item_everything_arriving","label":"Everything arriving and running on time"}]},{"id":"blk_catering12","ref":"budget","title":"Roughly what''s your budget per guest?","description":"A ballpark is fine. It helps us suggest a realistic menu.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_catering13","ref":"contact","title":"Where should we send the proposal?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_catering14","ref":"notes","title":"Anything else we should know?","description":"A theme, a dish you loved at another event, timings for speeches.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_catering01","ref":"end_thanks","title":"Thanks, this is plenty to start 🍽️","bodyMd":"We''ll check the date and come back with menu ideas and a quote.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_catering01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service_style"},"op":"eq","value":"opt_drop_off"}],"groups":[]},"from":"service_style","target":"menu_style","targetKind":"block","branch":"true"},{"id":"rl_catering02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service_style"},"op":"eq","value":"opt_buffet_with_staff"}],"groups":[]},"from":"service_style","target":"venue_kitchen","targetKind":"block","branch":"true"},{"id":"rl_catering03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service_style"},"op":"eq","value":"opt_plated_sit_down"}],"groups":[]},"from":"service_style","target":"venue_kitchen","targetKind":"block","branch":"true"},{"id":"rl_catering04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service_style"},"op":"eq","value":"opt_canap_s_and"}],"groups":[]},"from":"service_style","target":"venue_kitchen","targetKind":"block","branch":"true"},{"id":"rl_catering05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service_style"},"op":"eq","value":"opt_not_sure_yet"}],"groups":[]},"from":"service_style","target":"venue_kitchen","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":tru