noon"},{"id":"opt_col_evening","label":"Evening"}],"multiplePerRow":true},{"id":"blk_interact08","ref":"context","title":"Is there anything that would help us prepare?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_interact09","ref":"attachments","title":"Any photos or documents to share beforehand?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":3,"maxSizeMB":10},{"id":"blk_interact10","ref":"contact","title":"How can we reach you to confirm?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_interact11","ref":"reminder","title":"How would you like your reminder?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_text_message","label":"Text message","image_key":null},{"id":"opt_no_reminder_thanks","label":"No reminder, thanks","image_key":null}],"allowOther":false}],"endings":[{"id":"end_interact01","ref":"end_thanks","title":"Thanks! We''ll be in touch 👋","bodyMd":"We''ll look at your availability and send you a time to confirm.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_interact01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service"},"op":"eq","value":"opt_i_m_not"}],"groups":[]},"from":"service","target":"not_sure_detail","targetKind":"block","branch":"true"},{"id":"rl_interact02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service"},"op":"eq","value":"opt_initial_consultation"}],"groups":[]},"from":"service","target":"returning",