INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_partnershipinquiry', 'partnership-inquiry', 'Partnership inquiry form', 'Form', 'Hear what a would-be partner offers and whether the timing is right, in one conversation.', 'A partnerships inbox fills with pitches that were never going to fit. Each kind of partnership is asked the one thing that makes it credible: an integration for which way the API calls go, a reseller for the market it sells into, co-marketing for the size of its audience, an agency for its client base. Proposals looking to move in the next few weeks go to their own ending with a faster reply.', '["business","partnership inquiry","partner application","business development","reseller","branching"]', 'Handshake', 'scale', 3, 16, '{"schemaVersion":9,"title":"Partnership inquiry","description":"Hear what a would-be partner offers and whether the timing is right, in one conversation.","blocks":[{"id":"blk_partners00","ref":"welcome","title":"Thinking of working together? Tell us what you have in mind.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_partners01","ref":"contact","title":"Who are we talking to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_partners02","ref":"company_name","title":"And which company?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":160},{"id":"blk_partners03","ref":"website","title":"Link to your website","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_partners04","ref":"partnership_type","title":"What kind of partnership?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_technology_integration","lab