ts":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"17:30"},{"id":"blk_appointm12","ref":"access_needs","title":"Anything we should arrange for your visit?","description":"Step-free access, an interpreter, a longer appointment: just say.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_appointm13","ref":"reminder","title":"How should we remind you the day before?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_text_message","label":"Text message","image_key":null},{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_no_reminder","label":"No reminder","image_key":null}],"allowOther":false}],"endings":[{"id":"end_appointm01","ref":"end_thanks","title":"Request received 🗓️","bodyMd":"We''ll confirm your time by text or email shortly.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_appointm02","ref":"end_urgent","title":"We''ll call you back as soon as we can ☎️","bodyMd":"Keep your phone nearby. If it''s an emergency, please don''t wait for us. Call your local emergency number.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_appointm01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"date_of_birth","target":"preferred_slot","targetKind":"block"},{"id":"rl_appointm02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"since_then","target":"preferred_slot","targetKind":"block"},{"id":"rl_appointm03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_first_consultation"}],"groups":[]},"from":"reason","target":"first_concern","targetKind":"block","branch":"true"},{"id":"rl_appointm04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_follow_up"}],"groups":[]},"from":"reason","target":"previous_visit","targetKind":"block","branch":"true"},{"id":"rl_appointm05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_routine_check"}],"groups":[]},"from":"reason","target":"preferred_slot","targetKind":"block","branch":"true"},{"id":"rl_appointm06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_something_urgent"}],"groups":[]},"from":"reason","target":"urgent_detail","targetKind":"block","branch":"true"},{"id":"rl_appointm07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"urgent_today"},"op":"eq","value":true}],"groups":[]},"from":"urgent_today","target":"end_urgent","targetKind":"ending","branch":"true"},{"id":"rl_appointm08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"urgent_today"},"op":"eq","value":false}],"groups":[]},"from":"urgent_today","target":"preferred_slot","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for 