VALUES ('tpl_giveawayentryform', 'giveaway-entry-form', 'Giveaway entry form', 'Form', 'A short, fair entry path that checks eligibility first and records rule acceptance.', 'Entrants answer the eligibility question before anything else, so anyone under 18 is told kindly and never fills in the rest. Everyone else gets a quick run through contact details, how they would like the prize delivered and a separate newsletter opt-in, so a giveaway entry is never mistaken for marketing consent.', '["business","giveaway entry form","contest entry","sweepstakes form","prize draw","competition entry"]', 'Gift', 'scale', 3, 8, '{"schemaVersion":9,"title":"Giveaway entry","description":"A short, fair entry path that checks eligibility first and records rule acceptance.","blocks":[{"id":"blk_giveaway00","ref":"welcome","title":"You''re a couple of minutes away from being entered. Let''s check you''re eligible first.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_giveaway01","ref":"over_18","title":"Are you 18 or older?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, I am","noLabel":"No, not yet"},{"id":"blk_giveaway02","ref":"contact","title":"Where should we contact you if you win?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_giveaway03","ref":"location","title":"Which country and city do you live in?","description":"The rules say where the giveaway is open, and we check before announcing a winner.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["city","country"],"location":"off"},{"id":"blk_giveaway04","ref":"prize_choice","title":"If you win, how would you like to receive the prize?","description":"We''ll confirm the details with the winner before anything is sent.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_posted_to_my","label":"Posted to my address","image_key":null},{"id":"opt_collected_in_person","label":"Collected in person","image_key":null},{"id":"opt_a_digital_voucher","label":"A digital voucher instead","image_key":null},{"id":"opt_whatever_s_easiest","label":"Whatever''s easiest","image_key":null}],"allowOther":false},{"id":"blk_giveaway05","ref":"heard_about","title":"How did you hear about the giveaway?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_instagram","label":"Instagram","image_key":null},{"id":"opt_tiktok","label":"TikTok","image_key":null},{"id":"opt_facebook","label":"Facebook","image_key":null},{"id":"opt_email_newsletter","label":"Email newsletter","image_key":null},{"id":"opt_a_friend_told","label":"A friend told me","image_key":null},{"id":"opt_in_store","label":"In store","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}]},{"id":"blk_giveaway06","ref":"why_win","title":"In a sentence or two, what would winning mean to you?","description":"Optional, and it has no effect on who wins. The draw is random.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":400,"aiQualityCheck":false},{"id":"blk_giveaway07","ref":"newsletter","title":"Would you also like our newsletter? Saying no won''t affect your entry.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, sign me up","noLabel":"Just the giveaway"},{"id":"blk_giveaway08","ref":"rules","title":"Official rules","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I have read the official giveaway rules, I am entering once, and I understan