INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_onlinesuggestionbox', 'online-suggestion-box', 'Online suggestion box', 'Form', 'Collect improvement ideas with enough context to act on, named or anonymous.', 'A good suggestion names a problem, not just a wish, so this asks for both. People who raised the idea before are asked what happened to it, which is often the most useful answer you''ll get. Anyone who wants to stay anonymous can finish without a name, and named contributors are asked if they''d help make it happen.', '["business","online suggestion box","employee suggestions","anonymous feedback","idea submission","branching"]', 'Lightbulb', 'scale', 3, 10, '{"schemaVersion":9,"title":"Suggestion box","description":"Collect improvement ideas with enough context to act on, named or anonymous.","blocks":[{"id":"blk_onlinesu00","ref":"welcome","title":"Got an idea that would make things better here? We''d like to hear it, big or small.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_onlinesu01","ref":"area","title":"What is your suggestion about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_how_we_work","label":"How we work day to day","image_key":null},{"id":"opt_tools_and_equipment","label":"Tools and equipment","image_key":null},{"id":"opt_the_customer_experience","label":"The customer experience","image_key":null},{"id":"opt_the_building_or","label":"The building or workspace","image_key":null},{"id":"opt_team_culture_and","label":"Team culture and communication","image_key":null}],"allowOther":true},{"id":"blk_onlinesu02","ref":"suggestion","title":"What''s your suggestion?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_onlinesu03","ref":"problem","title":"What problem would it fix, or what would it make better?","description":"An example of when you ran into it helps a lot.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_onlinesu04","ref":"who_benefits","title":"Who would it help?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_me","label":"Me","image_key":null},{"id":"opt_my_team","label":"My team","image_key":null},{"id":"opt_everyone_here","label":"Everyone here","image_key":null},{"id":"opt_customers","label":"Customers","image_key":null},{"id":"opt_visitors_or_the","label":"Visitors or the wider community","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_onlinesu05","ref":"impact","title":"How big a difference do you think it would make?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"A small tweak","labelHigh":"A big change"},{"id":"blk_onlinesu06","ref":"raised_before","title":"Have you suggested this before, anywhere?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_onlinesu07","ref":"what_happened","title":"What happened when you raised it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_onlinesu08","ref":"anonymous","title":"Would you like to stay anonymous?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Keep me anonymous","noLabel":"Add my name"},{"id":"blk_onlinesu09","ref":"contact","title":"Who should we credit and follow up with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_onlinesu10","ref":"help","title":"If we go ahead, would you like to help put it in place?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Count me in","noLabel":"Just sharing the idea"}],"endings":[{"id":"end_onlinesu01","ref":"end_thanks","title":"Thanks for the idea 💡","bodyMd":"We review suggestions regularly and will let you know what happens with yours, whether or not we go ahead.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_onlinesu02","ref":"end_anonymous","title":"Thanks, received anonymously","bodyMd":"Your suggestion arrived without your name. We review every one and share what we decide to act on with everyone.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_onlinesu01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"raised_before"},"op":"eq","value":true}],"groups":[]},"from":"raised_before","target":"what_happened","targetKind":"block","branch":"true"},{"id":"rl_onlinesu02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"raised_before"},"op":"eq","value":false}],"groups":[]},"from":"raised_before","target":"anonymous","targetKind":"block","branch":"true"},{"id":"rl_onlinesu03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"anonymous"},"op":"eq","value":true}],"groups":[]},"from":"anonymous","target":"end_anonymous","targetKind":"ending","branch":"true"},{"id":"rl_onlinesu04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"anonymous"},"op":"eq","value":false}],"groups":[]},"from":"anonymous","target":"contact","targetKind":"block","branch":"true"},{"id":"rl_onlinesu05","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"what_happened","target":"help","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#5b2ee6","surface":"#4a22c9","text":"#ffffff","accent":"#ffd166","accentText":"#1c1917","botBubble":"#4a22c9","userBubble":"#ffd166","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundPatternColor":"#ffffff","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
