VALUES ('tpl_softwareincidentreportfo', 'software-incident-report-form', 'Software incident report form', 'Form', 'Record what broke, when, how badly and for whom, in a shape your on-call team can triage.', 'Written for the person who notices a problem, not the engineer who fixes it, so it asks plain questions and turns them into a triage-ready record. A critical report asks for a number the on-call engineer can ring right away, and an incident that has already stopped is asked how it resolved.', '["business","software incident report","it incident form","outage report","service disruption","branching"]', 'Bug', 'scale', 4, 13, '{"schemaVersion":9,"title":"Software incident report","description":"Record what broke, when, how badly and for whom, in a shape your on-call team can triage.","blocks":[{"id":"blk_software00","ref":"welcome","title":"Something not working? Tell us what you''re seeing and we''ll get the right person on it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_software01","ref":"reporter","title":"Who is reporting this?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_software02","ref":"service","title":"Which system, app or service is affected?","description":"As specific as you can, for example the billing page in the customer portal.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_software03","ref":"environment","title":"Where is it happening?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_live_for_real","label":"Live, for real users","image_key":null},{"id":"opt_staging_or_test","label":"Staging or test","image_key":null},{"id":"opt_my_own_device","label":"My own device only","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null}],"allowOther":false},{"id":"blk_software04","ref":"started_at","title":"When did it start, as best you know?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":15,"timeMin":"00:00","timeMax":"23:45"},{"id":"blk_software05","ref":"severity","title":"How bad is it right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_critical_it_s","label":"Critical: it''s down or data is at risk","description":"Nobody can use it, or something is being lost or exposed.","image_key":null},{"id":"opt_major_a_key","label":"Major: a key feature is broken","description":"People can work around it, but not for long.","image_key":null},{"id":"opt_minor_annoying_but","label":"Minor: annoying but workable","image_key":null},{"id":"opt_already_fixed_just","label":"Already fixed, just logging it","image_key":null}],"allowOther":false},{"id":"blk_software06","ref":"callback_phone","title":"What number can the on-call engineer reach you on right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_software07","ref":"ongoing","title":"Is it still happening?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_software08","ref":"resolution","title":"What made it stop, and roughly when?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_software09","ref":"what_happened","title":"What exactly are you seeing?","description":"Include any error message word for word, and what you were doing when it happened.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":true},{"id":"blk_software10","ref":"who_affected","title":"Who is affected?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_all_users","label":"All users","image_key":null},{"id":"opt_some_users_or","label":"Some users or one region","image_key":null},{"id":"opt_only_our_internal","label":"Only our internal team","image_key":null},{"id":"opt_just_me_as","label":"Just me, as far as I know","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null}],"allowOther":false},{"id":"blk_software11","ref":"impact","title":"What is it getting in the way of?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_signing_in","label":"Signing in","image_key":null},{"id":"opt_taking_payments_or","label":"Taking payments or orders","image_key":null},{"id":"opt_saving_or_loading","label":"Saving or loading data","image_key":null},{"id":"opt_sending_emails_or","label":"Sending emails or notifications","image_key":null},{"id":"opt_internal_work_only","label":"Internal work only","image_key":null}],"minSelections":0,"maxSelections":6,"allowOther":true},{"id":"blk_software12","ref":"tried","title":"What have you or anyone else already tried?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_software13","ref":"evidence","title":"Add a screenshot, recording or log file if you have one.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","video/*","text/plain","application/pdf"],"maxFiles":5,"maxSizeMB":25}],"endings":[{"id":"end_software01","ref":"end_thanks","title":"Incident logged 🛠️","bodyMd":"Thanks. The team has your report and will follow up by email. If it gets worse before then, report it again with the new details.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_software01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"callback_phone","target":"what_happened","targetKind":"block"},{"id":"rl_software02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"severity"},"op":"eq","value":"opt_critical_it_s"}],"groups":[]},"from":"severity","target":"callback_phone","targetKind":"block","branch":"true"},{"id":"rl_software03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"severity"},"op":"eq","value":"opt_major_a_key"}],"groups":[]},"from":"severity","target":"ongoing","targetKind":"block","branch":"true"},{"id":"rl_software04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"severity"},"op":"eq","value":"opt_minor_annoying_but"}],"groups":[]},"from":"severity","target":"ongoing","targetKind":"block","branch":"true"},{"id":"rl_software05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"severity"},"op":"eq","value":"opt_already_fixed_just"}],"groups":[]},"from":"severity","target":"resolution","targetKind":"block","branch":"true"},{"id":"rl_software06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"ongoing"},"op":"eq","value":false}],"groups":[]},"from":"ongoing","target":"resolution","targetKind":"block","branch":"true"},{"id":"rl_software07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"ongoing"},"op":"eq","value":true}],"groups":[]},"from":"ongoing","target":"what_happened","targetKind":"block","branch":"true"},{"id":"rl_software08","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"resolution","target":"who_affected","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffff