INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_clientinformationform', 'client-information-form', 'Client information form', 'Form', 'One record of who your client is, who to bill and who else to keep in the loop.', 'Built for agencies and freelancers to send once a client signs, so kickoff doesn''t start with a week of emails. It records who approves work and which accounts you''ll need access to, asks for a separate billing contact only when someone else pays the invoices, and gathers everyone else on the project in one repeating list.', '["business","client information form","client intake","new client form","client onboarding","customer information form"]', 'Building2', 'scale', 5, 16, '{"schemaVersion":9,"title":"Client information","description":"One record of who your client is, who to bill and who else to keep in the loop.","blocks":[{"id":"blk_clientin00","ref":"welcome","title":"Welcome aboard! A few details now saves a lot of back and forth later. It takes about five minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_clientin01","ref":"contact","title":"Who will be our main contact?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_clientin02","ref":"job_title","title":"What is your role or job title?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":100},{"id":"blk_clientin03","ref":"company","title":"What is the company''s legal name?","description":"As it should appear on contracts and invoices.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_clientin04","ref":"website","title":"What is the company website?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_clientin05","ref":"address","title":"What is the company''s registered address?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","state","postal","country"],"location":"off"},{"id":"blk_clientin06","ref":"tax_id","title":"Do you have a tax or VAT number we should put on invoices?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_clientin07","ref":"industry","title":"Which industry are you in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_retail_and_ecommerce","label":"Retail and ecommerce","image_key":null},{"id":"opt_software_and_technology","label":"Software and technology","image_key":null},{"id":"opt_professional_services","label":"Professional services","image_key":null},{"id":"opt_health_and_wellness","label":"Health and wellness","image_key":null},{"id":"opt_education","label":"Education","image_key":null},{"id":"opt_hospitality_and_food","label":"Hospitality and food","image_key":null},{"id":"opt_manufacturing","label":"Manufacturing","image_key":null},{"id":"opt_non_profit","label":"Non-profit","image_key":null},{"id":"opt_real_estate","label":"Real estate","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_clientin08","ref":"approver","title":"Who has the final say when work needs approving?","description":"A name and role. If it''s you, just say so.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_clientin09","ref":"access_needed","title":"Which of these will we probably need access to?","description":"Just tick them for now. Never send passwords in this form; we''l