ions":[],"businessOnly":false,"allowedDomains":[]},{"id":"fld_ocrole","key":"role","label":"Role on the project","kind":"short_text","required":false,"options":[],"businessOnly":false,"allowedDomains":[]},{"id":"fld_ocmail","key":"email","label":"Email","kind":"email","required":true,"options":[],"businessOnly":false,"allowedDomains":[]}],"itemLabel":"Contact","minEntries":1,"maxEntries":6},{"id":"blk_clientin15","ref":"comms","title":"How do you prefer to hear from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_phone_calls","label":"Phone calls","image_key":null},{"id":"opt_video_calls","label":"Video calls","image_key":null},{"id":"opt_a_shared_chat","label":"A shared chat channel","image_key":null}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_clientin16","ref":"notes","title":"Anything else we should know before we start?","description":"Working hours, approval steps, people who must sign off, anything that tends to trip projects up.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false}],"endings":[{"id":"end_clientin01","ref":"end_thanks","title":"All set, thank you 🙌","bodyMd":"We''ve saved your details. Your project lead will be in touch shortly with the next steps and a kickoff time.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_clientin01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"handles_billing"},"op":"eq","value":true}],"groups":[]},"from":"handles_billing","target":"po_number","targetKind":"block","branch":"true"},{"id":"rl_clientin02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"handles_billing"},"op":"eq","value":false}],"groups":[]}