VALUES ('tpl_estimateform', 'estimate-form', 'Estimate form', 'Form', 'Get the job details, photos and timing you need to send a realistic estimate.', 'For trades and service businesses that lose hours to vague enquiries. It asks what the job is, where, how big and how soon, with room for photos, so you can price it or decide a visit is needed. Urgent jobs are asked for a phone number, and flexible ones skip the start-date question.', '["business","estimate form","estimate request","job estimate","free estimate form","service quote request"]', 'Calculator', 'scale', 4, 12, '{"schemaVersion":9,"title":"Estimate request","description":"Get the job details, photos and timing you need to send a realistic estimate.","blocks":[{"id":"blk_estimate00","ref":"welcome","title":"Hi! Tell us about the job and we''ll come back with an estimate. It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_estimate01","ref":"contact","title":"Who is the estimate for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_estimate02","ref":"job_type","title":"What kind of job is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_repair","label":"A repair","image_key":null},{"id":"opt_a_new_installation","label":"A new installation","image_key":null},{"id":"opt_a_renovation_or","label":"A renovation or upgrade","image_key":null},{"id":"opt_regular_maintenance","label":"Regular maintenance","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet, I need advice","image_key":null}],"allowOther":true},{"id":"blk_estimate03","ref":"job_details","title":"Describe the job in your own words.","description":"What needs doing, what''s there now, and anything you already know you want, like materials or finish.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":true},{"id":"blk_estimate04","ref":"property_type","title":"What type of property is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_house","label":"House","image_key":null},{"id":"opt_apartment_or_flat","label":"Apartment or flat","image_key":null},{"id":"opt_office_or_shop","label":"Office or shop","image_key":null},{"id":"opt_industrial_or_warehouse","label":"Industrial or warehouse","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_estimate05","ref":"site_address","title":"Where is the job?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal"],"location":"off"},{"id":"blk_estimate06","ref":"size","title":"Roughly how big is the area or job?","description":"For example: two rooms, 30 square metres, or 12 windows. A rough guess is fine.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_estimate07","ref":"photos","title":"Add photos of the area, if you can.","description":"Photos often let us price a job without a visit.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":6,"maxSizeMB":20},{"id":"blk_estimate08","ref":"timing","title":"When do you need it done?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_as_soon_as","label":"As soon as possible","image_key":null},{"id":"opt_within_a_month","label":"Within a month","image_key":null},{"id":"opt_in_1_to","label":"In 1 to 3 months","image_key":null},{"id":"opt_i_m_flexible","label":"I''m flexible","image_key":null}],"allowOther":false},{"id":"blk_estimate09","ref":"urgent_phone","title":"What''s the best number for a quick call about it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_estimate10","ref":"start_date","title":"Is there a date you''d like the work to start by?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_estimate11","ref":"budget","title":"Do you have a budget in mind?","description":"It helps us suggest options that fit. Pick not sure if you''re still exploring.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_under_500","label":"Under 500","image_key":null},{"id":"opt_500_to_2","label":"500 to 2,000","image_key":null},{"id":"opt_2_000_to","label":"2,000 to 10,000","image_key":null},{"id":"opt_more_than_10","label":"More than 10,000","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}]},{"id":"blk_estimate12","ref":"visit_ok","title":"If we need to see it before pricing, is a site visit okay?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"}],"endings":[{"id":"end_estimate01","ref":"end_thanks","title":"Request received 📋","bodyMd":"Thanks! We''ll review the details and send your estimate, or get in touch to arrange a visit if the job needs one.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_estimate01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"urgent_phone","target":"budget","targetKind":"block"},{"id":"