VALUES ('tpl_insurancequoteform', 'insurance-quote-form', 'Insurance quote form', 'Form', 'An insurance enquiry that asks different questions for each type of cover.', 'One form for every line you sell. The first answer decides the next few questions, so a driver is asked about their car, age and claims while a traveller is asked about their trip, and nobody wades through the rest. Everyone then ranks what matters most to them, which tells your advisers where to start the conversation.', '["business","insurance quote form","insurance enquiry","insurance lead form","quote request","branching"]', 'ShieldCheck', 'scale', 4, 21, '{"schemaVersion":9,"title":"Insurance quote request","description":"An insurance enquiry that asks different questions for each type of cover.","blocks":[{"id":"blk_insuranc00","ref":"welcome","title":"Looking for cover? Answer a few questions and one of our advisers will come back with a quote.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_insuranc01","ref":"cover_type","title":"What would you like cover for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_home","label":"Home","image_key":null},{"id":"opt_car","label":"Car","image_key":null},{"id":"opt_life","label":"Life","image_key":null},{"id":"opt_health","label":"Health","image_key":null},{"id":"opt_business","label":"Business","image_key":null},{"id":"opt_travel","label":"Travel","image_key":null}],"allowOther":false},{"id":"blk_insuranc02","ref":"home_status","title":"Do you own or rent the home?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_own_it","label":"I own it","image_key":null},{"id":"opt_i_rent_it","label":"I rent it","image_key":null},{"id":"opt_i_m_a","label":"I''m a landlord letting it out","image_key":null}],"allowOther":false},{"id":"blk_insuranc03","ref":"home_cover","title":"What should the policy cover?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_the_building","label":"The building","image_key":null},{"id":"opt_contents_and_belongings","label":"Contents and belongings","image_key":null}],"minSelections":1,"maxSelections":2,"allowOther":false},{"id":"blk_insuranc04","ref":"car_details","title":"What is the make, model and year of the car?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_insuranc05","ref":"car_driver_dob","title":"What is the main driver''s date of birth?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_insuranc06","ref":"car_licence_years","title":"How many years has the main driver held a full licence?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":80,"integerOnly":true},{"id":"blk_insuranc07","ref":"car_claims","title":"How many claims have you made in the last five years?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":20,"integerOnly":true},{"id":"blk_insuranc08","ref":"life_dob","title":"What is your date of birth?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_insuranc09","ref":"life_smoker","title":"Have you smoked or used nicotine in the last 12 months?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_insuranc10","ref":"health_who","title":"Who needs to be covered?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_me_and_a","label":"Me and a partner","image_key":null},{"id":"opt_my_family_with","label":"My family, with children","image_key":null},{"id":"opt_employees_of_my","label":"Employees of my business","image_key":null}],"allowOther":false},{"id":"blk_insuranc11","ref":"biz_activity","title":"What does the business do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_insuranc12","ref":"biz_staff","title":"How many people does it employ?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":true},{"id":"blk_insuranc13","ref":"trip_type","title":"What kind of travel cover?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_single_trip","label":"A single trip","image_key":null},{"id":"opt_annual_cover_for","label":"Annual cover for several trips","image_key":null}],"allowOther":false},{"id":"blk_insuranc14","ref":"destinations","title":"Where are you going?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_insuranc15","ref":"currently_insured","title":"Do you have this kind of cover already?","description":"If so, we can aim for a start date that matches your renewal.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_insuranc16","ref":"start_date","title":"When would you like the new cover to start?","required":true,"v