VALUES ('tpl_salescalllogform', 'sales-call-log-form', 'Sales call log', 'Form', 'A quick log reps fill in after each call, with a next step every time.', 'Reps fill it in straight after a call, so it has to be quick. The outcome decides the path: a missed call just needs a retry date, a lost deal records why, and a live opportunity captures the summary, objections, lead warmth and an agreed next step with a date.', '["business","sales call log","call log form","sales activity log","call report","branching"]', 'Phone', 'scale', 4, 16, '{"schemaVersion":9,"title":"Sales call log","description":"A quick log reps fill in after each call, with a next step every time.","blocks":[{"id":"blk_salescal00","ref":"welcome","title":"Just off a call? Log it now while it''s fresh. Two minutes, tops.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_salescal01","ref":"rep","title":"Who made the call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_salescal02","ref":"call_date","title":"When was the call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":15,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_salescal03","ref":"prospect","title":"Who did you call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","phone"]},{"id":"blk_salescal04","ref":"company","title":"Which company are they with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_salescal05","ref":"call_type","title":"What kind of call was it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_first_outreach","label":"First outreach","image_key":null},{"id":"opt_discovery","label":"Discovery","image_key":null},{"id":"opt_demo","label":"Demo","image_key":null},{"id":"opt_follow_up","label":"Follow-up","image_key":null},{"id":"opt_negotiation","label":"Negotiation","image_key":null},{"id":"opt_existing_customer_check","label":"Existing customer check-in","image_key":null}],"allowOther":false},{"id":"blk_salescal06","ref":"outcome","title":"How did it go?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_moving_forward","label":"Moving forward","image_key":null},{"id":"opt_interested_needs_more","label":"Interested, needs more time","image_key":null},{"id":"opt_not_interested","label":"Not interested","image_key":null},{"id":"opt_no_answer_or","label":"No answer or voicemail","image_key":null}],"allowOther":false},{"id":"blk_salescal07","ref":"retry_date","title":"When will you try again?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_salescal08","ref":"lost_reason","title":"What was the main reason?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_price","label":"Price","image_key":null},{"id":"opt_went_with_a","label":"Went with a competitor","image_key":null},{"id":"opt_bad_timing","label":"Bad timing","image_key":null},{"id":"opt_no_real_need","label":"No real need","image_key":null},{"id":"opt_missing_a_feature","label":"Missing a feature they need","image_key":null}],"allowOther":true},{"id":"blk_salescal09","ref":"lost_notes","title":"Anything worth remembering if they come back later?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_salescal10","ref":"summary","title":"What did you talk about?","description":"Their situation, what they need, and anything that surprised you.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_salescal11","ref":"warmth","title":"How warm is this lead now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Cold","labelHigh":"Ready to buy"},{"id":"blk_salescal12","ref":"decision_maker","title":"Did you speak to the person who makes the buying decision?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_salescal13","ref":"objections","title":"Which objections came up?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_price_or_budget","label":"Price or budget","image_key":null},{"id":"opt_timing","label":"Timing","image_key":null},{"id":"opt_needs_sign_off","label":"Needs sign-off from someone else","image_key":null},{"id":"opt_happy_with_current","label":"Happy with current supplier","image_key":null},{"id":"opt_missing_feature","label":"Missing feature","image_key":null}],"minSelections":0,"maxSelections":6,"allowOther":true},{"id":"blk_salescal14","ref":"next_step","title":"What is the agreed next step?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_another_call","label":"Another call","image_key":null},{"id":"opt_demo","label":"Demo","image_key":null},{"id":"opt_send_a_proposal","label":"Send a proposal","image_key":null},{"id":"opt_start_a_trial","label":"Start a trial","image_key":null},{"id":"opt_close_the_deal","label":"Close the deal","image_key":null}],"allowOther":false},{"id":"blk_salescal15","ref":"next_date","title":"When is the next step due?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_salescal16","ref":"deal_value","title":"What is the rough deal value, if you know it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false}],"endings":[{"id":"end_salescal01","ref":"end_thanks","title":"Call logged 📞","bodyMd":"Saved with the next step and its date. Good luck with the follow-up.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_salescal02","ref":"end_no_answer","title":"Logged as no answer","bodyMd":"Your retry date is saved. A short voicemail and a follow-up email usually help the next attempt land.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_salescal03","ref":"end_lost","title":"Logged as lost","bodyMd":"Thanks for recording why. Those reasons are how the team spots patterns in lost deals.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_salescal01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"retry_date","target":"end_no_answer","targetKind":"ending"},{"id":"rl_salescal02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"lost_notes","target":"end_lost","targetKind":"ending"},{"id":"rl_salescal03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"outcome"},"op":"eq","value":"opt_no_answer_or"}],"groups":[]},"from":"outcome","target":"retry_date","targetKind":"block","branch":"true"},{"id":"rl_salescal04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"outcome"},"op":"eq","value":"opt_not_interested"}],"groups":[]},"from":"outcome","target":"lost_reason","targetKind":"block","branch":"true"},{"id":"rl_salescal05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"outcome"},"op":"eq","value":"opt_moving_forward"}],"groups":[]},"from":"outcome","target":"summary","targetKind":"block","branch":"true"},{"id":"rl_salescal06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"outcome"},"op":"eq","value":"opt_interested_needs_more"}],"groups":[]},"from":"outcome","target":"summary","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ece3ff","surface":"#ffffff","text":"#2a1f3d","accent":"#6d3fc7","accentText":"#fbf8ff","botBubble":"#ffffff","userBubble":"#6d3fc7","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
