VALUES ('tpl_inquiryform', 'inquiry-form', 'Inquiry form', 'Form', 'Take any question from your website and know who should answer it before you open it.', 'Reads like an email with the useful parts filled in: a topic, a one-line subject, the question, how soon it needs an answer and how to reply. A question about prices or availability asks for the date in mind, one about an existing booking asks for its reference, and only people who want a call are asked for a number.', '["contact","inquiry form","enquiry form","website inquiry","general questions","branching"]', 'Inbox', 'advanced', 3, 11, '{"schemaVersion":9,"title":"General inquiry","description":"Take any question from your website and know who should answer it before you open it.","blocks":[{"id":"blk_inquiryf00","ref":"welcome","title":"Hi there. Ask us anything and we''ll get it to the right person.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_inquiryf01","ref":"name","title":"First, what''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":100},{"id":"blk_inquiryf02","ref":"topic","title":"What''s your inquiry about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_our_products_or","label":"Our products or services","image_key":null},{"id":"opt_prices_and_availability","label":"Prices and availability","image_key":null},{"id":"opt_a_booking_or","label":"A booking or order I''ve already made","image_key":null},{"id":"opt_jobs_or_volunteering","label":"Jobs or volunteering","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_inquiryf03","ref":"reference","title":"What''s the order, booking or account number?","description":"It''s on your confirmation email or invoice. Skip this if you can''t find it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_inquiryf04","ref":"wanted_date","title":"Is there a date you''re asking about?","description":"Skip this if your question isn''t tied to a date.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_inquiryf05","ref":"subject","title":"In a few words, what''s the subject?","description":"Like the subject line of an email.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_inquiryf06","ref":"message","title":"Go ahead, what would you like to know?","description":"The more detail you give, the fewer emails it takes to answer.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_inquiryf07","ref":"urgency","title":"How soon do you need an answer?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_today_if_possible","label":"Today if possible","image_key":null},{"id":"opt_this_week","label":"This week","image_key":null},{"id":"opt_no_rush","label":"No rush","image_key":null}],"allowOther":false},{"id":"blk_inquiryf08","ref":"reply_by","title":"How should we reply?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_phone_call","label":"Phone call","image_key":null}],"allowOther":false},{"id":"blk_inquiryf09","ref":"phone","title":"What number should we call?","required":true,"visibility":