VALUES ('tpl_cateringcontactform', 'catering-contact-form', 'Catering contact form', 'Form', 'Hear about the event, the guests and the food before you pick up the phone.', 'Asks what a caterer needs to judge fit and price a job: the occasion, date, venue, headcount, service style and dietary needs. Wedding enquiries are also asked whether they want a tasting, and a budget question stops you proposing a plated dinner to someone who wanted sandwiches.', '["contact","catering contact form","catering enquiry","event catering","caterer","branching"]', 'ChefHat', 'advanced', 4, 11, '{"schemaVersion":9,"title":"Catering contact","description":"Hear about the event, the guests and the food before you pick up the phone.","blocks":[{"id":"blk_catering00","ref":"welcome","title":"Planning an event? Tell us a bit about it and we''ll come back with ideas and a quote.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_catering01","ref":"occasion","title":"What''s the occasion?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_wedding","label":"Wedding","image_key":null},{"id":"opt_work_event_or","label":"Work event or meeting","image_key":null},{"id":"opt_birthday_or_private","label":"Birthday or private party","image_key":null},{"id":"opt_memorial_or_wake","label":"Memorial or wake","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_catering02","ref":"tasting","title":"Would you like to come in for a tasting before you decide?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, please","noLabel":"Not needed"},{"id":"blk_catering03","ref":"event_date","title":"When is the event?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":t