VALUES ('tpl_designercontactform', 'designer-contact-form', 'Designer contact form', 'Form', 'Get a usable design brief out of every enquiry, not a two-line email.', 'Asks what a designer needs before quoting: the deliverables, where the work will live, the look the client is after, the deadline and the budget. Clients with an existing brand are asked to upload their files, and those starting fresh are asked for designs they admire instead.', '["contact","designer contact form","graphic design enquiry","freelance designer","design brief","branching"]', 'Palette', 'advanced', 3, 10, '{"schemaVersion":9,"title":"Design project enquiry","description":"Get a usable design brief out of every enquiry, not a two-line email.","blocks":[{"id":"blk_designer00","ref":"welcome","title":"Hi! Tell me about the project and I''ll get back to you with next steps.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_designer01","ref":"deliverables","title":"What would you like designed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_logo_or_brand","label":"Logo or brand identity","image_key":null},{"id":"opt_website_or_app","label":"Website or app screens","image_key":null},{"id":"opt_packaging","label":"Packaging","image_key":null},{"id":"opt_print_like_flyers","label":"Print, like flyers or brochures","image_key":null},{"id":"opt_social_media_graphics","label":"Social media graphics","image_key":null},{"id":"opt_illustration","label":"Illustration","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_designer02","ref":"where_used","title":"Where will people see it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_online","label":"Online","image_key":null},{"id":"opt_in_print","label":"In print","image_key":null},{"id":"opt_on_products_or","label":"On products or packaging","image_key":null},{"id":"opt_signs_or_at","label":"Signs or at events","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_designer03","ref":"about","title":"Tell me about the business or project behind it.","description":"Who it''s for and what you want them to feel or do.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_designer04","ref":"look","title":"What kind of look are you after?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Quiet and minimal","labelHigh":"Bold and loud"},{"id":"blk_designer05","ref":"has_brand","title":"Do you already have brand guidelines, a logo or colours to work with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_designer06","ref":"brand_files","title":"Upload what you have: logo files, guidelines or past work.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf",".ai",".eps",".svg",".zip"],"maxFiles":5,"maxSizeMB":50},{"id":"blk_designer07","ref":"references","title":"Any designs you love, or hate? Links or names are perfect.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_designer08","ref":"deadline","title":"When do you need it by?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_designer09","ref":"budget","title":"Which best describes your budget?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_small_one_piece","label":"Small, one piece done well","image_key":null},{"id":"opt_medium_a_few","label":"Medium, a few connected pieces","image_key":null},{"id":"opt_larger_a_full","label":"Larger, a full identity or site","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet, I''d like a quote","image_key":null}],"allowOther":false},{"id":"blk_designer10","ref":"contact","title":"How can I reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]}],"endings":[{"id":"end_designer01","ref":"end_thanks","title":"Thanks, this is a great start ✏️","bodyMd":"I''ll look through everything and reply with questions or a proposal.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_designer01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_brand"},"op":"eq","value":true}],"groups":[]},"from":"has_brand","target":"brand_files","targetKind":"block","branch":"true"},{"id":"rl_designer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_brand"},"op":"eq","value":false}],"groups":[]},"from":"has_brand","target":"references","targetKind":"block","branch":"true"},{"id":"rl_designer03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"brand_files","target":"deadline","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
