VALUES ('tpl_photographycontactform', 'photography-contact-form', 'Photography contact form', 'Form', 'Check your calendar and send a quote from the first message.', 'Starts with the type of shoot, because a wedding and a product shoot need different answers. Couples are asked how much of the day to cover, commercial clients are asked where the images will be used and how many they need, and everyone gives the date, place and style.', '["contact","photography contact form","photographer enquiry","photo shoot booking","wedding photography","branching"]', 'Camera', 'advanced', 4, 12, '{"schemaVersion":9,"title":"Photography enquiry","description":"Check your calendar and send a quote from the first message.","blocks":[{"id":"blk_photogra00","ref":"welcome","title":"Hi! Tell me about the shoot you have in mind and I''ll check my availability.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_photogra01","ref":"shoot_type","title":"What kind of shoot is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_wedding_or_elopement","label":"Wedding or elopement","image_key":null},{"id":"opt_portrait_couple_or","label":"Portrait, couple or family","image_key":null},{"id":"opt_event","label":"Event","image_key":null},{"id":"opt_product_or_commercial","label":"Product or commercial","image_key":null},{"id":"opt_headshots","label":"Headshots","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_photogra02","ref":"coverage","title":"How much of the day would you like covered?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_ceremony_only","label":"Ceremony only","image_key":null},{"id":"opt_ceremony_and_portraits","label":"Ceremony and portraits","image_key":null},{"id":"opt_getting_ready_through","label":"Getting ready through to first dance","image_key":null},{"id":"opt_the_whole_day","label":"The whole day","image_key":null}],"allowOther":false},{"id":"blk_photogra03","ref":"usage","title":"Where will the photos be used?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_website_or_online","label":"Website or online shop","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_print_ads_or","label":"Print ads or brochures","image_key":null},{"id":"opt_packaging","label":"Packaging","image_key":null},{"id":"opt_press","label":"Press","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_photogra04","ref":"image_count","title":"Roughly how many final images do you need?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"integerOnly":true},{"id":"blk_photogra05","ref":"shoot_date","title":"What date are you thinking of?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_photogra06","ref":"date_flexible","title":"Is the date flexible?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, a little","noLabel":"No, it''s fixed"},{"id":"blk_photogra07","ref":"location","title":"Where will the shoot be?","description":"A town is fine if you haven''t picked the spot yet.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["city","state","country"],"location":"off"},{"id":"blk_photogra08","ref":"people","title":"How many people will be in the photos?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":true},{"id":"blk_photogra09","ref":"style","title":"Describe the feel you want, or share a link to photos you love.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_photogra10","ref":"budget","title":"Do you have a budget in mind?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_i_have","label":"Yes, I have a set amount","image_key":null},{"id":"opt_roughly_but_i","label":"Roughly, but I''m flexible","image_key":null},{"id":"opt_not_yet_i","label":"Not yet, I''d like your packages","image_key":null}],"allowOther":false},{"id":"blk_photogra11","ref":"contact","title":"Who should I send availability and prices to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_photogra12","ref":"heard_from","title":"How did you find me?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_search_engine","label":"Search engine","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_a_friend_or","label":"A friend or past client","image_key":null},{"id":"opt_a_venue_or","label":"A venue or planner","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}]}],"endings":[{"id":"end_photogra01","ref":"end_thanks","title":"Thanks, I''ll check the date 📸","bodyMd":"You''ll hear back soon with availability and the packages that fit your shoot.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_photogra01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"coverage","target":"shoot_date","targetKind":"block"},{"id":"rl_photogra02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"shoot_type"},"op":"eq","value":"opt_wedding_or_elopement"}],"groups":[]},"from":"shoot_type","target":"coverage","targetKind":"block","branch":"true"},{"id":"rl_photogra03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"shoot_type"},"op":"eq","value":"opt_portrait_couple_or"}],"groups":[]},"from":"shoot_type","target":"shoot_date","targetKind":"block","branch":"true"},{"id":"rl_photogra04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"shoot_type"},"op":"eq","value":"opt_event"}],"groups":[]},"from":"shoot_type","target":"shoot_date","targetKind":"block","branch":"true"},{"id":"rl_photogra05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"shoot_type"},"op":"eq","value":"opt_product_or_commercial"}],"groups":[]},"from":"shoot_type","target":"usage","targetKind":"block","branch":"true"},{"id":"rl_photogra06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"shoot_type"},"op":"eq","value":"opt_headshots"}],"groups":[]},"from":"shoot_type","target":"shoot_date","targetKind":"block","branch":"true"},{"id":"rl_photogra07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"shoot_type"},"op":"eq","value":"opt_something_else"}],"groups":[]},"from":"shoot_type","target":"shoot_date","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"v