VALUES ('tpl_responsivecontactform', 'responsive-contact-form', 'Responsive contact form', 'Form', 'A contact form built for thumbs: few questions, big choices, no tiny fields.', 'Kept short for small screens: one question at a time, tap answers wherever possible, and the message is the only long answer. Someone reporting a problem is asked which device they are on and can attach a screenshot, and only people who want a call are asked for a number.', '["contact","responsive contact form","mobile contact form","website contact","contact us","branching"]', 'Smartphone', 'advanced', 3, 8, '{"schemaVersion":9,"title":"Mobile-friendly contact","description":"A contact form built for thumbs: few questions, big choices, no tiny fields.","blocks":[{"id":"blk_responsi00","ref":"welcome","title":"Hello! This will only take a minute.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_responsi01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":100},{"id":"blk_responsi02","ref":"reason","title":"What can we help with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_question","label":"A question","image_key":null},{"id":"opt_something_isn_t","label":"Something isn''t working","image_key":null},{"id":"opt_feedback_or_an","label":"Feedback or an idea","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_responsi03","ref":"device","title":"What are you using?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_phone","label":"Phone","image_key":null},{"id":"opt_tablet","label":"Tablet","image_key":null},{"id":"opt_computer","label":"Computer","image_key":null}],"allowOther":false},{"id":"blk_responsi04","ref":"screenshot","title":"Got a screenshot? Add it here.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*"],"maxFiles":3,"maxSizeMB":10},{"id":"blk_responsi05","ref":"message","title":"Tell us more.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_responsi06","ref":"reply_by","title":"How would you like to hear back?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_phone_call","label":"Phone call","image_key":null},{"id":"opt_no_reply_needed","label":"No reply needed","image_key":null}],"allowOther":false},{"id":"blk_responsi07","ref":"phone","title":"What''s the best number?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_responsi08","ref":"email","title":"What''s your email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_responsi01","ref":"end_thanks","title":"Thanks, message received","bodyMd":"We''ll get back to you the way you asked.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_responsi02","ref":"end_no_reply","title":"Thanks for letting us know","bodyMd":"Your message has reached the team, and we read every one.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_responsi01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_a_question"}],"groups"