VALUES ('tpl_contactus', 'contact-us', 'Contact us form', 'Form', 'A general contact form that sorts the inbox as it fills it.', 'The one form every site needs. The topic decides which follow-ups are worth asking: a buyer says whether they want a price, a demo or just an answer, support asks for the account email, feedback starts with a star rating, and job seekers share the role and a profile link. A call back is offered to everyone, with a time slot.', '["contact","contact us form","website contact form","general enquiry","contact page","branching"]', 'MessageCircle', 'advanced', 3, 12, '{"schemaVersion":9,"title":"Contact us","description":"A general contact form that sorts the inbox as it fills it.","blocks":[{"id":"blk_contactu00","ref":"welcome","title":"Hi! What can we help you with?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_contactu01","ref":"contact","title":"Let''s start with your name and email.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_contactu02","ref":"topic","title":"What''s it about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_buying_from_us","label":"Buying from us","image_key":null},{"id":"opt_help_with_something","label":"Help with something","image_key":null},{"id":"opt_feedback","label":"Feedback","image_key":null},{"id":"opt_working_here","label":"Working here","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_contactu03","ref":"next_step","title":"What would help you most right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_price_or","label":"A price or a quote","image_key":null},{"id":"opt_a_demo_