call back?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, please call","noLabel":"Email is fine"},{"id":"blk_contactu11","ref":"phone","title":"What''s the best number?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_contactu12","ref":"call_time","title":"When should we try you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_morning","label":"Morning","image_key":null},{"id":"opt_afternoon","label":"Afternoon","image_key":null},{"id":"opt_evening","label":"Evening","image_key":null},{"id":"opt_any_time","label":"Any time","image_key":null}],"allowOther":false}],"endings":[{"id":"end_contactu01","ref":"end_thanks","title":"Message sent 📨","bodyMd":"Thanks for getting in touch. The right person will reply soon.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_contactu01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"company","target":"message","targetKind":"block"},{"id":"rl_contactu02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"account_email","target":"message","targetKind":"block"},{"id":"rl_contactu03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"experience","target":"message","targetKind":"block"},{"id":"rl_contactu04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_buying_from_us"}],"groups":[]},"from":"topic","target":"next_step","targetKind":"block","branch":"true"},{"id":"rl_contactu05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_help_with_something"}],"groups":[]},"from":"topic","target":"account_email","targetK