VALUES ('tpl_businesscontactform', 'business-contact-form', 'Business contact form', 'Form', 'One contact form for buyers, customers, partners and press, each asked only what their enquiry needs.', 'Built for company websites where buyers, customers, would-be partners and journalists all use the same contact page. It asks which of those the person is first, then branches: a buyer is asked what they need, for how big a team and when, an existing customer for a reference and how urgent it is, a partner what they''re proposing, and a journalist for their deadline.', '["contact","business contact form","company contact form","contact us page","b2b contact form","branching"]', 'Building2', 'advanced', 3, 15, '{"schemaVersion":9,"title":"Business contact","description":"One contact form for buyers, customers, partners and press, each asked only what their enquiry needs.","blocks":[{"id":"blk_business00","ref":"welcome","title":"Hello, and thanks for getting in touch. Pick what your message is about and we''ll pass it to the team that handles it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_business01","ref":"contact","title":"First, who are we talking to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_business02","ref":"company","title":"Which company or organisation are you with?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_business03","ref":"topic","title":"What''s your message about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_buying_from_us","label":"Buying from us","image_key":null},{"id":"opt_help_with_something","label":"Help with something you already have","image_key":null},{"id":"opt_a_partnership_or","label":"A partnership or supplier offer","image_key":null},{"id":"opt_press_or_media","label":"Press or media","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_business04","ref":"interest","title":"Which product or service are you interested in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_business05","ref":"team_size","title":"How many people would be using it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_2_10","label":"2–10","image_key":null},{"id":"opt_11_50","label":"11–50","image_key":null},{"id":"opt_51_250","label":"51–250","image_key":null},{"id":"opt_more_than_250","label":"More than 250","image_key":null}]},{"id":"blk_business06","ref":"timeline","title":"When are you hoping to get started?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_as_soon_as","label":"As soon as possible","image_key":null},{"id":"opt_in_the_next","label":"In the next few months","image_key":null},{"id":"opt_just_exploring_for","label":"Just exploring for now","image_key":null}],"allowOther":false},{"id":"blk_business07","ref":"reference","title":"Do you have an order, account or ticket number?","description":"Leave it blank if you don''t have one to hand.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_business08","ref":"urgency","title":"How urgent is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_s_stopping","label":"It''s stopping us working","image_key":null},{"id":"opt_it_s_getting","label":"It''s getting in the way","image_key":null},{"id":"opt_it_can_wait","label":"It can wait a few days","image_key":null}],"allowOther":false},{"id":"blk_business09","ref":"partner_type","title":"What kind of partnership are you proposing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_reselling_or_referring","label":"Reselling or referring our products","image_key":null},{"id":"opt_supplying_us","label":"Supplying us","image_key":null},{"id":"opt_working_together_on","label":"Working together on something","image_key":null},{"id":"opt_sponsorship_or_an","label":"Sponsorship or an event","image_key":null}],"allowOther":false},{"id":"blk_business10","ref":"partner_site","title":"What''s your website, so we can read up before replying?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_business11","ref":"outlet","title":"Which publication or outlet are you writing for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_business12","ref":"press_deadline","title":"When is your deadline?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_business13","ref":"message","title":"Tell us a bit more. What would you like to happen next?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_business14","ref":"reply_by","title":"How would you like us to reply?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_email_is_fine","label":"Email is fine","image_key":null},{"id":"opt_please_give_me","label":"Please give me a call","image_key":null}],"allowOther":false},{"id":"blk_business15","ref":"phone","title":"What number should we call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false}],"endings":[{"id":"end_business01","ref":"end_thanks","title":"Thanks, your message is with us","bodyMd":"It''s gone to the person who handles this kind of enquiry, and they''ll reply the way you asked.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_business01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"timeline","target":"message","targetKind":"block"},{"id":"rl_business02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"urgency","target":"message","targetKind":"block"},{"id":"rl_business03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"partner_site","target":"message","targetKind":"block"},{"id":"rl_business04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_buying_from_us"}],"groups":[]},"from":"topic","target":"interest","targetKind":"block","branch":"true"},{"id":"rl_business05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_help_with_something"}],"groups":[]},"from":"topic","target":"reference","targetKind":"block","branch":"true"},{"id":"rl_business06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_a_partnership_or"}],"groups":[]},"from":"topic","target":"partner_type","targetKind":"block","branch":"true"},{"id":"rl_business07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_press_or_media"}],"groups":[]},"from":"topic","target":"outlet","targetKind":"block","branch":"true"},{"id":"rl_business08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_something_else"}],"groups":[]},"from":"topic","target":"message","targetKind":"block","branch":"true"},{"id":"rl_business09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reply_by"},"op":"eq","value":"opt_email_is_fine"}],"groups":[]},"from":"reply_by","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_business10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reply_by"},"op":"eq","value":"opt_please_give_me"}],"groups":[]},"from":"reply_by","target":"phone","targetKind":"block","branch":"true"},{"id":"rl_business11","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"press_deadline","target":"reply_by","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#5b2ee6","surface":"#4a22c9","text":"#ffffff","accent":"#ffd166","accentText":"#1c1917","botBubble":"#4a22c9","userBubble":"#ffd166","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundPatternColor":"#ffffff","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
