INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_callbackform', 'callback-form', 'Callback request form', 'Form', 'Take callback requests with the number, the reason and a time that suits the caller.', 'Everything your team needs before dialling: who to ask for, the number, what the call is about and when to ring. People calling about an existing order or a bill are asked for its reference, so the agent can pull it up first. Anyone who needs a call today skips the day picker, says when today suits them and lands on an ending that says they are first in line.', '["contact","callback form","request a call back","call me back form","phone callback","customer service"]', 'Phone', 'advanced', 3, 11, '{"schemaVersion":9,"title":"Callback request","description":"Take callback requests with the number, the reason and a time that suits the caller.","blocks":[{"id":"blk_callback00","ref":"welcome","title":"Rather talk it through? Leave your number and we''ll call you back.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_callback01","ref":"name","title":"Who should we ask for when we call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_callback02","ref":"phone","title":"What''s the best number to reach you on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_callback03","ref":"topic","title":"What would you like to talk about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_new_order","label":"A new order or a quote","image_key":null},{"id":"opt_an_order_i","label":"An order I''ve already placed","image_key":null},{"id":"opt_a_problem_or","label":"A problem or complaint","image_key":null},{"id":"opt_billing_or_payments","label":"Billing or payment