VALUES ('tpl_clientcontactform', 'client-contact-form', 'Client contact form', 'Form', 'Give clients one place to send requests, with the project and context already attached.', 'Built for agencies, freelancers and service teams whose clients message them across email, chat and calls. Every message arrives tied to a project. A problem report asks how badly it is blocking the client and takes screenshots, a billing question asks for the invoice number, and clients who want a call are asked when suits them, with a number only for phone calls.', '["contact","client contact form","client request form","agency client portal","project support","branching"]', 'Briefcase', 'advanced', 3, 12, '{"schemaVersion":9,"title":"Client contact","description":"Give clients one place to send requests, with the project and context already attached.","blocks":[{"id":"blk_clientco00","ref":"welcome","title":"Hi. Send us anything about your project here and it''ll reach the right person on the team.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_clientco01","ref":"contact","title":"Your name and email","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_clientco02","ref":"company","title":"Which company are you with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_clientco03","ref":"project","title":"Which project is this about?","description":"The project name or reference we use with you.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_clientco04","ref":"request_type","title":"What kind of message is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"