VALUES ('tpl_salesinquiryform', 'sales-inquiry-form', 'Sales inquiry form', 'Form', 'Learn what a buyer needs and how soon, and fast-track the ones ready to buy now.', 'Asks the things a salesperson needs before replying: what the buyer is after, rough quantity, budget position and timing. Anyone who wants to start this month is asked for a phone number and a good time, and lands on an ending that promises a call. Everyone else is asked who makes the decision.', '["contact","sales inquiry form","sales enquiry form","product inquiry","request for information","lead qualification"]', 'Handshake', 'advanced', 3, 11, '{"schemaVersion":9,"title":"Sales inquiry","description":"Learn what a buyer needs and how soon, and fast-track the ones ready to buy now.","blocks":[{"id":"blk_salesinq00","ref":"welcome","title":"Thanks for your interest. A few questions and we''ll come back with something useful, not a brochure.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_salesinq01","ref":"contact","title":"Who should we reply to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_salesinq02","ref":"company","title":"Which company are you buying for?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_salesinq03","ref":"interest","title":"What are you looking for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_one_of_our","label":"One of our standard products","image_key":null},{"id":"opt_a_bulk_or","label":"A bulk or wholesale order","image_key":null},{"id":"opt_an_ongoing_supply","label":"An ongoing supply arrangement","image_key":null},{"id":"opt_something_custom_made","label":"Something custom-made","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet, I''d like advice","image_key":null}],"allowOther":false},{"id":"blk_salesinq04","ref":"needs","title":"Describe what you need. Sizes, specs or the problem you''re solving all help.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_salesinq05","ref":"quantity","title":"Roughly what quantity are you thinking of?","description":"Units, seats or hours. A ballpark is fine.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_salesinq06","ref":"budget","title":"Where are you with budget?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_we_have_a","label":"We have a set budget","image_key":null},{"id":"opt_we_have_a_2","label":"We have a rough figure in mind","image_key":null},{"id":"opt_we_need_a","label":"We need a price before we can decide","image_key":null}],"allowOther":false},{"id":"blk_salesinq07","ref":"timeline","title":"When do you want to get started?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_this_month","label":"This month","image_key":null},{"id":"opt_in_1_3","label":"In 1–3 months","image_key":null},{"id":"opt_later_this_year","label":"Later this year","image_key":null},{"id":"opt_just_researching_for","label":"Just researching for now","image_key":null}],"allowOther":false},{"id":"blk_salesinq08","ref":"phone","title":"What''s the best number for a quick call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_salesinq09","ref":"call_time","title":"When''s a good time to ring?","required":false,"visibility":null,"image_key":