VALUES ('tpl_complaintform', 'complaint-form', 'Complaint form', 'Form', 'Record what happened, its impact and the outcome the person wants, in their own words.', 'A complaint form that takes the person seriously. It records what happened and when, how serious it was and what they want done. A safety concern gets its own follow-up, anyone who has complained before is asked who they spoke to, and someone who only wants it on record gets an ending that says it has been.', '["contact","complaint form","formal complaint","report a problem","grievance form","complaints procedure"]', 'Flag', 'advanced', 4, 12, '{"schemaVersion":9,"title":"Complaint form","description":"Record what happened, its impact and the outcome the person wants, in their own words.","blocks":[{"id":"blk_complain00","ref":"welcome","title":"We''re sorry something went wrong. Tell us what happened and we''ll look into it properly.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_complain01","ref":"contact","title":"Your name and email, so we can reply","description":"We use these only to respond to your complaint.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_complain02","ref":"about","title":"What is your complaint about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_product","label":"A product","image_key":null},{"id":"opt_a_service_or","label":"A service or appointment","image_key":null},{"id":"opt_how_a_member","label":"How a member of staff treated me","image_key":null},{"id":"opt_a_delivery","label":"A delivery","image_key":null},{"id":"opt_a_charge_or","label":"A charge or bill","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_complain03","ref":"happened_on","title":"When did it happen?","description":"If you''re not sure of the exact day, your best guess is fine.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_complain04","ref":"reference","title":"Any order, booking or account number we should look up?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_complain05","ref":"what_happened","title":"What happened? Include names, places and times if you have them.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":4000,"aiQualityCheck":false},{"id":"blk_complain06","ref":"seriousness","title":"How serious was it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_someone_s_health","label":"Someone''s health or safety was put at risk","image_key":null},{"id":"opt_it_cost_me","label":"It cost me money or a lot of time","image_key":null},{"id":"opt_it_was_upsetting","label":"It was upsetting or unfair","image_key":null},{"id":"opt_it_was_frustrating","label":"It was frustrating but minor","image_key":null}],"allowOther":false},{"id":"blk_complain07","ref":"safety_detail","title":"Is anyone still at risk? Tell us what we need to know to act on it now.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_complain08","ref":"evidence","title":"Photos, receipts or emails that support your complaint","description":"Optional. If you don''t have any, your account of it is enough.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":10},{"id":"blk_complain09","ref":"raised_before","title":"Have you already raised this with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_complain10","ref":"previous_contact","title":"Who did you speak to, and what were you told?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_complain11","ref":"resolution","title":"What would you like us to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_refund_me","label":"Refund me","image_key":null},{"id":"opt_repair_or_replace","label":"Repair or replace it","image_key":null},{"id":"opt_apologise","label":"Apologise","image_key":null},{"id":"opt_change_things_so","label":"Change things so it doesn''t happen again","image_key":null},{"id":"opt_nothing_i_want","label":"Nothing, I want it on record","image_key":null}],"allowOther":false},{"id":"blk_complain12","ref":"resolution_detail","title":"Anything else we should know about what would put this right?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_complain01","ref":"end_thanks","title":"Thank you for telling us","bodyMd":"Your complaint has been logged. Someone responsible for this area will look into it and reply by email.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_complain02","ref":"end_record","title":"It''s on record","bodyMd":"Thank you. Your complaint has been logged and will be reviewed, even though you haven''t asked for anything back.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_complain01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"seriousness"},"op":"eq","value":"opt_someone_s_health"}],"groups":[]},"from":"seriousness","target":"safety_detail","targetKind":"block","branch":"true"},{"id":"rl_complain02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"seriousness"},"op":"eq","value":"opt_it_cost_me"}],"groups":[]},"from":"seriousness","target":"evidence","targetKind":"block","branch":"true"},{"id":"rl_complain03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"seriousness"},"op":"eq","value":"opt_it_was_upsetting"}],"groups":[]},"from":"seriousness","target":"evidence","targetKind":"block","branch":"true"},{"id":"rl_complain04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"seriousness"},"op":"eq","value":"opt_it_was_frustrating"}],"groups":[]},"from":"seriousness","target":"evidence","targetKind":"block","branch":"true"},{"id":"rl_complain05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"raised_before"},"op":"eq","value":true}],"groups":[]},"from":"raised_before","target":"previous_contact","targetKind":"block","branch":"true"},{"id":"rl_complain06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"raised_before"},"op":"eq","value":false}],"groups":[]},"from":"raised_before","target":"resolution","targetKind":"block","branch":"true"},{"id":"rl_complain07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolution"},"op":"eq","value":"opt_refund_me"}],"groups":[]},"from":"resolution","target":"resolution_detail","targetKind":"block","branch":"true"},{"id":"rl_complain08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolution"},"op":"eq","value":"opt_repair_or_replace"}],"groups":[]},"from":"resolution","target":"resolution_detail","targetKind":"block","branch":"true"},{"id":"rl_complain09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolution"},"op":"eq","value":"opt_apologise"}],"groups":[]},"from":"resolution","target":"resolution_detail","targetKind":"block","branch":"true"},{"id":"rl_complain10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolution"},"op":"eq","value":"opt_change_things_so"}],"groups":[]},"from":"resolution","target":"resolution_detail","targetKind":"block","branch":"true"},{"id":"rl_complain11","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolution"},"op":"eq","value":"opt_nothing_i_want"}],"groups":[]},"from":"resolution","target":"end_record","targetKind":"ending","branch":"true"},{"id":"rl_complain12","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"previous_contact","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#f26b1d","surface":"#fff7f0","text":"#1c1917","accent":"#1c1917","accentText":"#ffffff","botBubble":"#fff7f0","userBubble":"#1c1917","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundPatternColor":"#1c1917","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
