VALUES ('tpl_customercontactform', 'customer-contact-form', 'Customer contact form', 'Form', 'Let customers ask a question and include the order or product it''s about.', 'Customers rarely know what your team needs from them, so this form asks for them. A question about an order asks for the order number and lets them add photos. A question before buying asks which product it is. A phone number is only requested from customers who want a call.', '["contact","customer contact form","contact us form","customer enquiry form","order question","customer support"]', 'MessageCircle', 'advanced', 3, 8, '{"schemaVersion":9,"title":"Customer contact","description":"Let customers ask a question and include the order or product it''s about.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"Hi! What can we help you with today?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"contact","title":"Your name and email","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","email"]},{"id":"blk_customer02","ref":"topic","title":"What''s your question about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_an_order_i","label":"An order I''ve placed","image_key":null},{"id":"opt_a_return_or","label":"A return or refund","image_key":null},{"id":"opt_a_product_before","label":"A product, before I buy","image_key":null},{"id":"opt_my_account","label":"My account","image_key":null},{"id":"opt_feedback_or_an","label":"Feedback or an idea","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_customer03","ref":"order_number","title":"What''s your order number?","description":"You''ll find it in your confirmation email.","required":false,"visibility":null,"image_key":nu