order_number","targetKind":"block","branch":"true"},{"id":"rl_customer03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_a_return_or"}],"groups":[]},"from":"topic","target":"order_number","targetKind":"block","branch":"true"},{"id":"rl_customer04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_a_product_before"}],"groups":[]},"from":"topic","target":"product","targetKind":"block","branch":"true"},{"id":"rl_customer05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_my_account"}],"groups":[]},"from":"topic","target":"message","targetKind":"block","branch":"true"},{"id":"rl_customer06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_feedback_or_an"}],"groups":[]},"from":"topic","target":"message","targetKind":"block","branch":"true"},{"id":"rl_customer07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_something_else"}],"groups":[]},"from":"topic","target":"message","targetKind":"block","branch":"true"},{"id":"rl_customer08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reply_by"},"op":"eq","value":"opt_by_email"}],"groups":[]},"from":"reply_by","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_customer09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reply_by"},"op":"eq","value":"opt_call_me"}],"groups":[]},"from":"reply_by","target":"phone","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":