VALUES ('tpl_customerprofileform', 'customer-profile-form', 'Customer profile form', 'Form', 'Learn who a customer is, what they want from you and how they like to be contacted.', 'A profile that goes further than name and address. Customers rank what matters most to them, say what they want help with and choose how you may contact them, with marketing consent asked separately and clearly. Business customers get a few extra questions about their company.', '["contact","customer profile form","customer information form","customer onboarding","customer preferences","marketing consent"]', 'UserCheck', 'advanced', 4, 12, '{"schemaVersion":9,"title":"Customer profile","description":"Learn who a customer is, what they want from you and how they like to be contacted.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"Welcome! A few questions so we can look after you properly.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"contact","title":"Your contact details","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_customer02","ref":"customer_type","title":"Are you buying for yourself or for a business?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_for_myself","label":"For myself","image_key":null},{"id":"opt_for_a_business","label":"For a business","image_key":null}],"allowOther":false},{"id":"blk_customer03","ref":"company","title":"What''s the business called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_customer04","ref":"job_title","title":"And what''s your role there?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_customer05","ref":"company_size","title":"How many people work there?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_2_10","label":"2–10","image_key":null},{"id":"opt_11_50","label":"11–50","image_key":null},{"id":"opt_51_250","label":"51–250","image_key":null},{"id":"opt_more_than_250","label":"More than 250","image_key":null}]},{"id":"blk_customer06","ref":"goals","title":"What are you hoping we can help with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_finding_the_right","label":"Finding the right product","image_key":null},{"id":"opt_regular_orders_i","label":"Regular orders I don''t have to think about","image_key":null},{"id":"opt_advice_from_someone","label":"Advice from someone who knows the area","image_key":null},{"id":"opt_help_setting_things","label":"Help setting things up","image_key":null},{"id":"opt_getting_a_better","label":"Getting a better price","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_customer07","ref":"priorities","title":"Rank what matters most to you when you choose who to buy from.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_price","label":"Price"},{"id":"opt_item_quality","label":"Quality"},{"id":"opt_item_speed_of","label":"Speed of delivery"},{"id":"opt_item_friendly_service","label":"Friendly service"},{"id":"opt_item_sustainability","label":"Sustainability"}]},{"id":"blk_customer08","ref":"frequency","title":"How often do you expect to buy from us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_weekly","label":"Weekly","image_key":null},{"id":"opt_monthly","label":"Monthly","image_key":null},{"id":"opt_a_few_times","label":"A few times a year","image_key":null},{"id":"opt_just_this_once","label":"Just this once for now","image_key":null}],"allowOther":false},{"id":"blk_customer09","ref":"channels","title":"How do you prefer we contact you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_phone_call","label":"Phone call","image_key":null},{"id":"opt_text_message","label":"Text message","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_customer10","ref":"birthday","title":"When''s your birthday? Only if you''d like us to mark it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_customer11","ref":"anything_else","title":"Anything else we should know, such as access needs or preferences?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_customer12","ref":"marketing_consent","title":"Would you like to hear about offers and news?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I agree to receive occasional offers and news by the contact methods I chose above. I can unsubscribe at any time.","allowDecline":true,"agreeLabel":"Yes, keep me posted","declineLabel":"No thanks"}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"Thanks, your profile is set up","bodyMd":"We''ll use this to make sure what you hear from us is actually relevant to you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"customer_type"},"op":"eq","value":"opt_for_myself"}],"groups":[]},"from":"customer_type","target":"goals","targetKind":"block","branch":"true"},{"id":"rl_customer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"customer_type"},"op":"eq","value":"opt_for_a_business"}],"groups":[]},"from":"customer_type","target":"company","targetKind":"block","branch":"true"},{"id":"rl_customer03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"company_size","target":"priorities","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#5b2ee6","surface":"#4a22c9","text":"#ffffff","accent":"#ffd166","accentText":"#1c1917","botBubble":"#4a22c9","userBubble":"#ffd166","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundPatternColor":"#ffffff","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
