VALUES ('tpl_clientonboardingform', 'client-onboarding-form', 'Client onboarding form', 'Form', 'Everything you need from a new client before kickoff, asked in the order a good project lead would.', 'Collects the brief, the contacts, how the client likes to work and the materials you need before day one. Clients who sign off as a group are asked who else approves the work, and anyone with nothing ready yet skips the upload step instead of being asked for files they don''t have.', '["customer success","client onboarding","client intake","agency onboarding","project kickoff","new client questionnaire"]', 'Handshake', 'number', 5, 15, '{"schemaVersion":9,"title":"Client onboarding","description":"Everything you need from a new client before kickoff, asked in the order a good project lead would.","blocks":[{"id":"blk_clienton00","ref":"welcome","title":"Welcome aboard! A few questions now will save us a lot of back and forth later.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_clienton01","ref":"contact","title":"Who will be our main point of contact?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_clienton02","ref":"company","title":"What''s your company or brand called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_clienton03","ref":"website","title":"Your website, if you have one","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_clienton04","ref":"project_summary","title":"In a few sentences, what are we working on together?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_clienton05","ref":"success","title":"Three months from now, what would make this project a clear win for you?","description":"A number, a launch, a feeling. Whatever you''d point to.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_clienton06","ref":"priorities","title":"Put these in order of what matters most on this project","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_getting_it","label":"Getting it live quickly"},{"id":"opt_item_polish_and","label":"Polish and quality"},{"id":"opt_item_staying_on","label":"Staying on budget"},{"id":"opt_item_measurable_results","label":"Measurable results"}]},{"id":"blk_clienton07","ref":"deadline","title":"Is there a date this has to be ready by?","description":"Skip this if there''s no fixed date.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_clienton08","ref":"sign_off","title":"Who signs off on the work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_me_and_one","label":"Me and one other person","image_key":null},{"id":"opt_a_group_or","label":"A group or committee","image_key":null}],"allowOther":false},{"id":"blk_clienton09","ref":"approvers","title":"Who else needs to approve things, and how do they like to review?","description":"Names and roles are enough. Tell us if anyone only wants to see the final version.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_clienton10","ref":"channel","title":"How do you prefer to hear from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_phone_calls","label":"Phone calls","image_key":null},{"id":"opt_video_calls","label":"Video calls","image_key":null},{"id":"opt_a_shared_chat","label":"A shared chat channel","image_key":null}],"allowOther":false},{"id":"blk_clienton11","ref":"cadence","title":"How often would you like a progress update?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_twice_a_week","label":"Twice a week","image_key":null},{"id":"opt_once_a_week","label":"Once a week","image_key":null},{"id":"opt_every_two_weeks","label":"Every two weeks","image_key":null},{"id":"opt_only_at_milestones","label":"Only at milestones","image_key":null}],"allowOther":false},{"id":"blk_clienton12","ref":"materials","title":"Which of these can you share with us now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_logos_and_brand","label":"Logos and brand guidelines","image_key":null},{"id":"opt_logins_or_access","label":"Logins or access to tools we''ll need","image_key":null},{"id":"opt_copy_or_written","label":"Copy or written content","image_key":null},{"id":"opt_examples_of_work","label":"Examples of work you like","image_key":null},{"id":"opt_nothing_is_ready","label":"Nothing is ready yet","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_clienton13","ref":"files","title":"Upload whatever is ready","description":"Please don''t upload passwords. We''ll arrange access to accounts separately.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf","application/zip"],"maxFiles":10,"maxSizeMB":50},{"id":"blk_clienton14","ref":"first_need","title":"What''s the first thing you need from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_clienton15","ref":"avoid","title":"Has anything gone wrong with a past agency or supplier that we should make sure to avoid?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_clienton01","ref":"end_thanks","title":"You''re all set 🙌","bodyMd":"Thanks! We''ll read this before our kickoff call and come with a plan for the first two weeks.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_clienton01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"sign_off"},"op":"eq","value":"opt_just_me"}],"groups":[]},"from":"sign_off","target":"channel","targetKind":"block","branch":"true"},{"id":"rl_clienton02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"sign_off"},"op":"eq","value":"opt_me_and_one"}],"groups":[]},"from":"sign_off","target":"approvers","targetKind":"block","branch":"true"},{"id":"rl_clienton03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"sign_off"},"op":"eq","value":"opt_a_group_or"}],"groups":[]},"from":"sign_off","target":"approvers","targetKind":"block","branch":"true"},{"id":"rl_clienton04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"materials"},"op":"includes","value":"opt_nothing_is_ready"}],"groups":[]},"from":"materials","target":"first_need","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#5b2ee6","surface":"#4a22c9","text":"#ffffff","accent":"#ffd166","accentText":"#1c1917","botBubble":"#4a22c9","userBubble":"#ffd166","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundPatternColor":"#ffffff","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
