INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_bugreport', 'bug-report', 'Bug report form', 'Form', 'Reproducible bug reports instead of "it''s broken".', 'Asks for the three things an engineer needs and a reporter often forgets: what they expected, what happened, and the exact steps between. Where the bug happened decides what comes next (a browser is asked about the console, a phone about its model and app version, an API call about the status code), and anyone who can''t work at all lands on an urgent ending.', '["customer success","bug report","bug tracker","issue reporting","QA","software support","branching"]', 'Bug', 'number', 4, 19, '{"schemaVersion":9,"title":"Bug report","description":"Reproducible bug reports instead of \"it''s broken\".","blocks":[{"id":"blk_bugrepor00","ref":"welcome","title":"Sorry something''s broken. Let''s get the details down so we can fix it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_bugrepor01","ref":"summary","title":"In one line, what went wrong?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":160},{"id":"blk_bugrepor02","ref":"steps","title":"What steps lead to it? Number them if you can.","description":"Start from a page or screen we can find, like \"1. Open Settings\".","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_bugrepor03","ref":"expected","title":"What did you expect to happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_bugrepor04","ref":"actual","title":"What happened instead?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_bugrepor05","ref":"frequency","title":"How often does it happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_time","label":"Every time","image_key":null},{"id":"opt_most_times","label":"Most times","image_key":null},{"id":"opt_now_and_then","label":"Now and then","image_key":null},{"id":"opt_it_happened_once","label":"It happened once","image_key":null}],"allowOther":false},{"id":"blk_bugrepor06","ref":"regression","title":"Did this use to work for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, it broke recently","noLabel":"No, or not sure"},{"id":"blk_bugrepor07","ref":"environment","title":"Where did it happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_a_desktop","label":"In a desktop browser","image_key":null},{"id":"opt_in_the_mobile","label":"In the mobile app","image_key":null},{"id":"opt_through_the_api","label":"Through the API","image_key":null}],"allowOther":false},{"id":"blk_bugrepor08","ref":"browser","title":"Which browser?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_chrome","label":"Chrome","image_key":null},{"id":"opt_safari","label":"Safari","image_key":null},{"id":"opt_firefox","label":"Firefox","image_key":null},{"id":"opt_edge","label":"Edge","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_bugrepor09","ref":"console_errors","title":"Anything red in the developer console?","description":"Right-click the page, choose Inspect, then open Console. Paste what''s there, or say it''s empty.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_bugrepor10","ref":"private_window","title":"Does it still happen in a private window?","description":"This quickly tells a browser extension apart from a real bug.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, still broken","noLabel":"No, it works there"},{"id":"blk_bugrepor11","ref":"device_model","title":"Which phone or tablet?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_bugrepor12","ref":"os_version","title":"Which OS version?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_bugrepor13","ref":"app_version","title":"Which app version? It''s usually at the bottom of Settings.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_bugrepor14","ref":"endpoint","title":"Which endpoint, and which method?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_bugrepor15","ref":"status_code","title":"What status code came back?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":100,"max":599,"integerOnly":true},{"id":"blk_bugrepor16","ref":"request_id","title":"The request ID from the response headers, if you have it","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_bugrepor17","ref":"screenshot","title":"A screenshot or screen recording, if you have one","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","video/*"],"ma