VALUES ('tpl_customercomplaintform', 'customer-complaint-form', 'Customer complaint form', 'Form', 'For shops and service businesses: a complaint about a purchase, with the order and the fix the customer wants.', 'Built around a purchase rather than a general grievance. It asks where the customer bought, so a store visit is asked which branch while an online order goes straight to the order number, then lets them tick every problem at once. It closes by asking whether they''d buy again if it were put right, and customers who want a phone call get a number question and an ending that says so.', '["customer success","customer complaint form","order complaint","product complaint","retail complaint","service recovery"]', 'MessageCircle', 'number', 4, 13, '{"schemaVersion":9,"title":"Customer complaint","description":"For shops and service businesses: a complaint about a purchase, with the order and the fix the customer wants.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"Sorry your order didn''t go the way it should. Tell us what happened and we''ll work out how to put it right.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"contact","title":"First, your name and the email you used when you bought","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_customer02","ref":"where_bought","title":"Where did you buy from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_on_our_website","label":"On our website or app","image_key":null},{"id":"opt_in_one_of","label":"In one of our stores","image_key":null},{"id":"opt_over_the_phone","label":"Over the phone","image_key":null},{"id":"opt_through_another_shop","label":"Through another shop or marketplace","image_key":null}],"allowOther":false},{"id":"blk_customer03","ref":"store","title":"Which store was it, and roughly what time were you there?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":160},{"id":"blk_customer04","ref":"order_number","title":"Your order or receipt number, if you have it","description":"It''s on your confirmation email or the bottom of your receipt.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_customer05","ref":"item","title":"What did you buy or book?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":160},{"id":"blk_customer06","ref":"when","title":"When did the problem happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_customer07","ref":"problems","title":"What went wrong? Pick everything that applies.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_it_arrived_late","label":"It arrived late or not at all","image_key":null},{"id":"opt_it_was_faulty","label":"It was faulty or damaged","image_key":null},{"id":"opt_it_wasn_t","label":"It wasn''t what I ordered","image_key":null},{"id":"opt_i_was_charged","label":"I was charged the wrong amount","image_key":null},{"id":"opt_staff_were_unhelpful","label":"Staff were unhelpful or rude","image_key":null},{"id":"opt_i_couldn_t","label":"I couldn''t get hold of anyone","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_customer08","ref":"what_happened","title":"Tell us what happened, in your own words.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":3000,"aiQualityCheck":false},{"id":"blk_customer09","ref":"evidence","title":"Photos of the item, or a screenshot of the order or charge","description":"Optional, but it usually means fewer questions from us.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":20},{"id":"blk_customer10","ref":"resolution","title":"What would put this right for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_full_refund","label":"A full refund","image_key":null},{"id":"opt_a_replacement_or","label":"A replacement or repair","image_key":null},{"id":"opt_a_partial_refund","label":"A partial refund or credit","image_key":null},{"id":"opt_doing_the_job","label":"Doing the job or service again","image_key":null},{"id":"opt_an_apology_and","label":"An apology and an explanation","image_key":null}],"allowOther":true},{"id":"blk_customer11","ref":"come_back","title":"If we sort this out, how likely are you to buy from us again?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not likely at all","labelHigh":"Very likely"},{"id":"blk_customer12","ref":"reply_by","title":"How would you like us to get back to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_by_email","label":"By email","image_key":null},{"id":"opt_a_phone_call","label":"A phone call","image_key":null}],"allowOther":false},{"id":"blk_customer13","ref":"phone","title":"What number should we call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"Complaint received","bodyMd":"Thank you for telling us. We''ll look into your order and email you with what we''re going to do about it.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_customer02","ref":"end_call","title":"We''ll call you","bodyMd":"Thank you for telling us. Someone who can sort this out will look at your order and call you on the number you gave.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"phone","target":"end_call","targetKind":"ending"},{"id":"rl_customer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"where_bought"},"op":"eq","value":"opt_in_one_of"}],"groups":[]},"from":"where_bought","target":"store","targetKind":"block","branch":"true"},{"id":"rl_customer03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"where_bought"},"op":"eq","value":"opt_on_our_website"}],"groups":[]},"from":"where_bought","target":"order_number","targetKind":"block","branch":"true"},{"id":"rl_customer04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"where_bought"},"op":"eq","value":"opt_over_the_phone"}],"groups":[]},"from":"where_bought","target":"order_number","targetKind":"block","branch":"true"},{"id":"rl_customer05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"where_bought"},"op":"eq","value":"opt_through_another_shop"}],"groups":[]},"from":"where_bought","target":"order_number","targetKind":"block","branch":"true"},{"id":"rl_customer06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reply_by"},"op":"eq","value":"opt_by_email"}],"groups":[]},"from":"reply_by","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody"