VALUES ('tpl_customerinquiryform', 'customer-inquiry-form', 'Customer inquiry form', 'Form', 'Questions from shoppers and customers, each arriving with the product or order it''s about.', 'Made for businesses that sell something: each topic asks for the one detail your team would otherwise reply to ask for. A product question asks which product and how close the person is to buying, a delivery question asks where it''s going, and an order, return or account question asks for the order number. Only people who want a call are asked for a phone number.', '["customer success","customer inquiry form","product inquiry","order inquiry","customer questions","shop enquiry form"]', 'Inbox', 'number', 3, 12, '{"schemaVersion":9,"title":"Customer inquiry","description":"Questions from shoppers and customers, each arriving with the product or order it''s about.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"Hi! Ask us anything about our products or your order.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_customer02","ref":"email","title":"And your email address?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_customer03","ref":"topic","title":"What''s your question about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_product_sizes","label":"A product: sizes, specs or stock","image_key":null},{"id":"opt_delivery_times_and","label":"Delivery times and costs","image_key":null},{"id":"opt_an_order_i","label":"An order I''ve placed","image_key":null},{"id":"opt_a