","ref":"topic"},"op":"eq","value":"opt_an_order_i"}],"groups":[]},"from":"topic","target":"reference","targetKind":"block","branch":"true"},{"id":"rl_customer06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_a_return_or"}],"groups":[]},"from":"topic","target":"reference","targetKind":"block","branch":"true"},{"id":"rl_customer07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_my_account"}],"groups":[]},"from":"topic","target":"reference","targetKind":"block","branch":"true"},{"id":"rl_customer08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"topic"},"op":"eq","value":"opt_something_else"}],"groups":[]},"from":"topic","target":"message","targetKind":"block","branch":"true"},{"id":"rl_customer09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reply_by"},"op":"eq","value":"opt_by_email"}],"groups":[]},"from":"reply_by","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email",