VALUES ('tpl_customerservicerequestfo', 'customer-service-request-form', 'Customer service request form', 'Form', 'One form for every kind of service request, with the right follow-up questions for each.', 'The request type decides what is asked next. A repair is asked which product and what''s wrong, an installation visit is asked what it''s for, the address, the earliest date and any access notes, and a cancellation is asked why, so every request arrives ready to act on.', '["customer success","service request","customer service form","repair request","installation request","branching"]', 'Wrench', 'number', 3, 15, '{"schemaVersion":9,"title":"Service request","description":"One form for every kind of service request, with the right follow-up questions for each.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"Hi! Tell us what you need and we''ll get the right person on it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"contact","title":"Who is the request for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_customer02","ref":"account_ref","title":"Your customer, order or account number","description":"Skip this if you don''t have it to hand.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_customer03","ref":"request_type","title":"What do you need help with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_repair_or_fix","label":"Repair or fix something","image_key":null},{"id":"opt_an_installation_or","label":"An installation or setup visit","image_key":null},{"id":"opt_return_or_exchange","label":"Return or exchange an item","image_key":null},{"id":"opt_a_change_to","label":"A change to my account or plan","image_key":null},{"id":"opt_cancel_a_service","label":"Cancel a service","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_customer04","ref":"item","title":"Which product needs attention?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_customer05","ref":"fault","title":"What''s wrong with it, and when did it start?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_customer06","ref":"warranty","title":"Is it still under warranty?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No or not sure"},{"id":"blk_customer07","ref":"install_what","title":"What are we installing or setting up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":160},{"id":"blk_customer08","ref":"visit_address","title":"Where should we come?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal","country"],"location":"off"},{"id":"blk_customer09","ref":"visit_date","title":"What''s the earliest date that suits you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_customer10","ref":"access_notes","title":"Anything our technician should know about access or parking?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_customer11","ref":"cancel_reason","title":"What''s the main reason you''re cancelling?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_costs_too","label":"It costs too much","image_key":null},{"id":"opt_i_don_t","label":"I don''t use it enough","image_key":null},{"id":"opt_i_m_switching","label":"I''m switching to another provider","image_key":null},{"id":"opt_i_m_moving","label":"I''m moving or closing","image_key":null},{"id":"opt_i_ve_had","label":"I''ve had problems with the service","image_key":null}],"allowOther":true},{"id":"blk_customer12","ref":"request_details","title":"Tell us what you''d like us to do.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_customer13","ref":"photos","title":"Any photos or documents that would help?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":20},{"id":"blk_customer14","ref":"priority","title":"How soon do you need this sorted?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_as_soon_as","label":"As soon as possible","image_key":null},{"id":"opt_within_the_week","label":"Within the week","image_key":null},{"id":"opt_whenever_suits_you","label":"Whenever suits you","image_key":null}],"allowOther":false},{"id":"blk_customer15","ref":"contact_time","title":"When is the best time to reach you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_mornings","label":"Mornings","image_key":null},{"id":"opt_afternoons","label":"Afternoons","image_key":null},{"id":"opt_evenings","label":"Evenings","image_key":null},{"id":"opt_any_time","label":"Any time","image_key":null}],"allowOther":false}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"Request received 🛠️","bodyMd":"Thanks. We''ll confirm the next step by email, or ring you if it''s quicker to talk it through.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"warranty","target":"photos","targetKind":"block"},{"id":"rl_customer02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"access_notes","target":"contact_time","targetKind":"block"},{"id":"rl_customer03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"cancel_reason","target":"priority","targetKind":"block"},{"id":"rl_customer04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"request_type"},"op":"eq","value":"opt_repair_or_fix"}],"groups":[]},"from":"request_type","target":"item","targetKind":"block","branch":"true"},{"id":"rl_customer05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"request_type"},"op":"eq","value":"opt_an_installation_or"}],"groups":[]},"from":"request_type","target":"install_what","targetKind":"block","branch":"true"},{"id":"rl_customer06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"request_type"},"op":"eq","value":"opt_cancel_a_service"}],"groups":[]},"from":"request_type","target":"cancel_reason","targetKind":"block","branch":"true"},{"id":"rl_customer07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"request_type"},"op":"eq","value":"opt_return_or_exchange"}],"groups":[]},"from":"request_type","target":"request_details","targetKind":"block","branch":"true"},{"id":"rl_customer08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"request_type"},"op":"eq","value":"opt_a_change_to"}],"groups":[]},"from":"request_type","target":"request_details","targetKind":"block","branch":"true"},{"id":"rl_customer09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"request_type"},"op":"eq","value":"opt_something_else"}],"groups":[]},"from":"request_type","target":"request_details","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it 