VALUES ('tpl_faqform', 'faq-form', 'FAQ form', 'Form', 'Collect the questions your FAQ doesn''t answer yet, in your customers'' own words.', 'Put it at the bottom of your help pages to catch the questions they miss. It records where people looked first and how much the gap is holding them up, asks what was confusing when an answer existed but didn''t help, and only asks for an email when someone wants a personal reply.', '["customer success","FAQ form","help center feedback","knowledge base","customer questions","content gaps"]', 'Search', 'number', 3, 8, '{"schemaVersion":9,"title":"Missing FAQ question","description":"Collect the questions your FAQ doesn''t answer yet, in your customers'' own words.","blocks":[{"id":"blk_faqform00","ref":"welcome","title":"Couldn''t find what you were looking for? Ask here and we''ll use it to improve our answers.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_faqform01","ref":"question","title":"What question couldn''t you find an answer to?","description":"Write it the way you''d ask a friend. Your wording helps us name things better.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_faqform02","ref":"area","title":"Which area is it about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_getting_started","label":"Getting started","image_key":null},{"id":"opt_prices_and_billing","label":"Prices and billing","image_key":null},{"id":"opt_orders_and_delivery","label":"Orders and delivery","image_key":null},{"id":"opt_account_privacy_and","label":"Account, privacy and security","image_key":null},{"id":"opt_using_the_product","label":"Using the product","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_faqform03","ref":"looked","title":"Where did you look before asking?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_the_faq_or","label":"The FAQ or help pages","image_key":null},{"id":"opt_the_search_on","label":"The search on this site","image_key":null},{"id":"opt_a_search_engine","label":"A search engine","image_key":null},{"id":"opt_someone_on_your","label":"Someone on your team","image_key":null},{"id":"opt_nowhere_yet","label":"Nowhere yet","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_faqform04","ref":"found","title":"Did you find anything close?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_nothing_at_all","label":"Nothing at all","image_key":null},{"id":"opt_something_related_but","label":"Something related, but not my question","image_key":null},{"id":"opt_an_answer_but","label":"An answer, but it was confusing or out of date","image_key":null}],"allowOther":false},{"id":"blk_faqform05","ref":"confusing","title":"Which page was it, and what didn''t make sense?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_faqform06","ref":"stuck","title":"How much is this holding you up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Just curious","labelHigh":"I''m stuck until I know"},{"id":"blk_faqform07","ref":"wants_reply","title":"Would you like a personal reply as well?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_faqform08","ref":"email","title":"Where should we send it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_faqform01","ref":"end_thanks","title":"Thanks for asking 💡","bodyMd":"Every question here is read by the people who write our help pages. If you asked for a reply, it will come by email.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_faqform01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"looked"},"op":"includes","value":"opt_nowhere_yet"}],"groups":[]},"from":"looked","target":"stuck","targetKind":"block","branch":"true"},{"id":"rl_faqform02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"found"},"op":"eq","value":"opt_an_answer_but"}],"groups":[]},"from":"found","target":"confusing","targetKind":"block","branch":"true"},{"id":"rl_faqform03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"found"},"op":"eq","value":"opt_nothing_at_all"}],"groups":[]},"from":"found","target":"stuck","targetKind":"block","branch":"true"},{"id":"rl_faqform04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"found"},"op":"eq","value":"opt_something_related_but"}],"groups":[]},"from":"found","target":"stuck","targetKind":"block","branch":"true"},{"id":"rl_faqform05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"wants_reply"},"op":"eq","value":false}],"groups":[]},"from":"wants_reply","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
