VALUES ('tpl_gdprdataremovalrequestfo', 'gdpr-data-removal-request-form', 'GDPR data removal request form', 'Form', 'A clear route for right-to-erasure requests, with enough detail to find the records.', 'Collects who is asking, how they know you and what they want erased, then asks for a signed-off declaration before anything is deleted. People who only want to stop marketing emails get their own ending, and anyone asking on someone else''s behalf is asked for their own contact details and proof they can act.', '["customer success","GDPR","data deletion request","right to erasure","privacy request","data removal","branching"]', 'ShieldCheck', 'number', 4, 12, '{"schemaVersion":9,"title":"Data deletion request","description":"A clear route for right-to-erasure requests, with enough detail to find the records.","blocks":[{"id":"blk_gdprdata00","ref":"welcome","title":"You can ask us to delete the personal data we hold about you. It only takes a few minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_gdprdata01","ref":"full_name","title":"What''s your full name?","description":"Asking for someone else? Give their name here, and yours at the end.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_gdprdata02","ref":"email","title":"Which email address do we know you by?","description":"Theirs, if you''re asking for someone else. We''ll use it to find the records and confirm the request.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_gdprdata03","ref":"relationship","title":"How have you dealt with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_have_or","label":"I have or had an account","image_key":null},{"id":"opt_i_bought_something","label":"I bought something without an account","image_key":null},{"id":"opt_i_m_on","label":"I''m on a mailing list","image_key":null},{"id":"opt_i_applied_for","label":"I applied for a job","image_key":null},{"id":"opt_i_m_not","label":"I''m not sure","image_key":null}],"allowOther":false},{"id":"blk_gdprdata04","ref":"account_id","title":"Your username or account ID, if it''s different from your email","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_gdprdata05","ref":"other_details","title":"Anything else that could help us find your records?","description":"Old email addresses, a phone number or an order number all help.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_gdprdata06","ref":"scope","title":"What would you like us to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_delete_all_the","label":"Delete all the personal data you hold about me","image_key":null},{"id":"opt_delete_only_some","label":"Delete only some of it","image_key":null},{"id":"opt_just_stop_sending","label":"Just stop sending me marketing","image_key":null}],"allowOther":false},{"id":"blk_gdprdata07","ref":"which_data","title":"Which data would you like deleted?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_gdprdata08","ref":"reason","title":"Would you like to tell us why?","description":"You don''t have to give a reason.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_no_longer","label":"I no longer use your service","image_key":null},{"id":"opt_i_m_worried","label":"I''m worried about how my data is used","image_key":null},{"id":"opt_i_never_agreed","label":"I never agreed to you having it","image_key":null},{"id":"opt_i_d_rather","label":"I''d rather not say","image_key":null}],"allowOther":false},{"id":"blk_gdprdata09","ref":"acting_for","title":"Are you asking for yourself?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_the_data","label":"Yes, the data is about me","image_key":null},{"id":"opt_no_i_m","label":"No, I''m asking for someone else","image_key":null}],"allowOther":false},{"id":"blk_gdprdata10","ref":"requester","title":"Your own name and email, so we can reply to you","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_gdprdata11","ref":"authority","title":"Please upload proof that you can act for them","description":"For example a signed letter of authority or a power of attorney.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":3,"maxSizeMB":10},{"id":"blk_gdprdata12","ref":"declaration","title":"Declaration","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I confirm the information I''ve given is accurate and that I am the person the data is about, or am authorised to act for them. I understand you may contact me to confirm my identity before acting on this request.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_gdprdata01","ref":"end_thanks","title":"Request received 🔒","bodyMd":"We''ll email you to confirm, and may ask you to verify your identity first. We''ll tell you once your data has been deleted, or explain anything we''re required to keep.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_gdprdata02","ref":"end_marketing","title":"We''ll stop the marketing emails","bodyMd":"We''ll remove this address from our marketing lists. If you later want your data deleted as well, you can fill in this form again.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_gdprdata01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"relationship"},"op":"eq","value":"opt_i_bought_something"}],"groups":[]},"from":"relationship","target":"other_details","targetKind":"block","branch":"true"},{"id":"rl_gdprdata02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"relationship"},"op":"eq","value":"opt_i_m_on"}],"groups":[]},"from":"relationship","target":"other_details","targetKind":"block","branch":"true"},{"id":"rl_gdprdata03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"relationship"},"op":"eq","value":"opt_i_applied_for"}],"groups":[]},"from":"relationship","target":"other_details","targetKind":"block","branch":"true"},{"id":"rl_gdprdata04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"relationship"},"op":"eq","value":"opt_i_m_not"}],"groups":[]},"from":"relationship","target":"other_details","targetKind":"block","branch":"true"},{"id":"rl_gdprdata05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"scope"},"op":"eq","value":"opt_delete_all_the"}],"groups":[]},"from":"scope","target":"reason","targetKind":"block","branch":"true"},{"id":"rl_gdprdata06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"scope"},"op":"eq","value":"opt_delete_only_some"}],"groups":[]},"from":"scope","target":"which_data","targetKind":"block","branch":"true"},{"id":"rl_gdprdata07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"scope"},"op":"eq","value":"opt_just_stop_sending"}],"groups":[]},"from":"scope","target":"end_marketing","targetKind":"ending","branch":"true"},{"id":"rl_gdprdata08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"acting_for"},"op":"eq","value":"opt_yes_the_data"}],"groups":[]},"from":"acting_for","target":"declaration","targetKind":"block","branch":"true"},{"id":"rl_gdprdata09","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"which_data","target":"acting_for","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
