VALUES ('tpl_refundrequest', 'refund-request', 'Refund request form', 'Form', 'Refund requests with the evidence your team needs, collected once.', 'Order reference, reason and preferred outcome, asked once so nobody has to email back for them. A damaged item is asked for photos, a missing parcel for its tracking status, and a double charge goes straight to finance with its own ending. The reason list also becomes a running count of why people ask for their money back.', '["customer success","refund request","return form","ecommerce","billing","branching"]', 'ReceiptText', 'number', 3, 14, '{"schemaVersion":9,"title":"Refund request","description":"Refund requests with the evidence your team needs, collected once.","blocks":[{"id":"blk_refundre00","ref":"welcome","title":"Let''s sort this out. First, a few details about the order.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_refundre01","ref":"email","title":"Which email did you use for the order?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_refundre02","ref":"order_reference","title":"Your order or invoice number","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_refundre03","ref":"order_date","title":"Roughly when did you order?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_refundre04","ref":"amount","title":"How much did you pay?","description":"An estimate is fine.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_refundre05","ref":"reason","title":"Why are you asking for a refund?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_arrived_damaged","label":"It arrived damaged or faulty","image_key":null},{"id":"opt_it_never_arrived","label":"It never arrived","image_key":null},{"id":"opt_i_was_charged","label":"I was charged twice","image_key":null},{"id":"opt_it_wasn_t","label":"It wasn''t what I expected","image_key":null},{"id":"opt_i_changed_my","label":"I changed my mind","image_key":null}],"allowOther":false},{"id":"blk_refundre06","ref":"damage_photos","title":"Photos of the damage","description":"One of the item and one of the packaging is usually enough.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*"],"maxFiles":5,"maxSizeMB":20},{"id":"blk_refundre07","ref":"damage_when","title":"When did you notice?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_as_soon_as","label":"As soon as I opened it","image_key":null},{"id":"opt_within_a_few","label":"Within a few days","image_key":null},{"id":"opt_after_using_it","label":"After using it for a while","image_key":null}],"allowOther":false},{"id":"blk_refundre08","ref":"tracking_status","title":"What does the tracking say?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_delivered_but_it","label":"Delivered, but it isn''t here","image_key":null},{"id":"opt_still_in_transit","label":"Still in transit","image_key":null},{"id":"opt_no_updates_at","label":"No updates at all","image_key":null},{"id":"opt_i_don_t","label":"I don''t have a tracking number","image_key":null}],"allowOther":false},{"id":"blk_refundre09","ref":"delivery_address","title":"Please confirm the delivery address","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal","country"],"location":"off"},{"id":"blk_refundre10","ref":"duplicate_charges","title":"Which amounts and dates do you see on your statement?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_refundre11","ref":"expectation_gap","title":"What made it the wrong fit for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_refundre12","ref":"condition","title":"What condition is it in now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_unopened","label":"Unopened","image_key":null},{"id":"opt_opened_but_unused","label":"Opened but unused","image_key":null},{"id":"opt_used","label":"Used","image_key":null},{"id":"opt_damaged","label":"Damaged","image_key":null}],"allowOther":false},{"id":"blk_refundre13","ref":"resolution","title":"What would you like us to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_refund_to_my","label":"Refund to my original payment method","image_key":null},{"id":"opt_store_credit","label":"Store credit","image_key":null},{"id":"opt_send_a_replacement","label":"Send a replacement","image_key":null}],"allowOther":false},{"id":"blk_refundre14","ref":"detail","title":"Anything else we should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_refundre01","ref":"end_thanks","title":"Refund request received","bodyMd":"Thanks. We''ll review it and email you with the outcome, and with return instructions if we need the item back.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_refundre02","ref":"end_finance","title":"Sent to our finance team 💳","bodyMd":"We''ll check the duplicate charge against your order and reverse it if it''s ours. You don''t need to do anything else.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_refundre01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"damage_when","target":"condition","targetKind":"block"},{"id":"rl_refundre02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"delivery_address","target":"resolution","targetKind":"block"},{"id":"rl_refundre03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"duplicate_charges","target":"end_finance","targetKind":"ending"},{"id":"rl_refundre04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_it_arrived_damaged"}],"groups":[]},"from":"reason","target":"damage_photos","targetKind":"block","branch":"true"},{"id":"rl_refundre05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_it_never_arrived"}],"groups":[]},"from":"reason","target":"tracking_status","targetKind":"block","branch":"true"},{"id":"rl_refundre06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_i_was_charged"}],"groups":[]},"from":"reason","target":"duplicate_charges","targetKind":"block","branch":"true"},{"id":"rl_refundre07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_it_wasn_t"}],"groups":[]},"from":"reason","target":"expectation_gap","targetKind":"block","branch":"true"},{"id":"rl_refundre08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_i_changed_my"}],"groups":[]},"from":"reason","target":"expectation_gap","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#221d44","surface":"#2d2757","text":"#f5f3ff","accent":"#ff8a4c","accentText":"#1c1917","botBubble":"#332c5e","userBubble":"#ff8a4c","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
