VALUES ('tpl_supportticket', 'support-ticket', 'Support ticket form', 'Form', 'Route requests to the right queue, with the details that queue needs.', 'Asking for the category up front sends each ticket to the right person without a triage pass, and each category asks its own questions: billing gets an invoice number, login gets the exact error, a how-to question gets asked about the goal instead of the button. Blocking tickets get their own ending so the customer knows they were flagged.', '["customer success","support ticket","help desk form","customer support","ticketing","branching"]', 'LifeBuoy', 'number', 3, 15, '{"schemaVersion":9,"title":"Support ticket","description":"Route requests to the right queue, with the details that queue needs.","blocks":[{"id":"blk_supportt00","ref":"welcome","title":"How can we help? Tell us what''s going on.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_supportt01","ref":"email","title":"What''s the email on your account?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_supportt02","ref":"category","title":"What''s this about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_billing_or_invoices","label":"Billing or invoices","image_key":null},{"id":"opt_account_and_sign","label":"Account and sign-in","image_key":null},{"id":"opt_something_isn_t","label":"Something isn''t working","image_key":null},{"id":"opt_how_do_i","label":"How do I do something?","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_supportt03","ref":"invoice_number","title":"Which invoice? The number is usually at the top.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_supportt04","ref":"billing_issue","title":"What do you need?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_was_charged","label":"I was charged the wrong amount","image_key":null},{"id":"opt_i_was_charged_2","label":"I was charged twice","image_key":null},{"id":"opt_a_tax_number","label":"A tax number or address added to an invoice","image_key":null},{"id":"opt_to_change_my","label":"To change my plan","image_key":null},{"id":"opt_help_with_a","label":"Help with a declined card","image_key":null}],"allowOther":false},{"id":"blk_supportt05","ref":"login_error","title":"What does the error say, word for word?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_supportt06","ref":"login_method","title":"How do you normally sign in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_email_and_password","label":"Email and password","image_key":null},{"id":"opt_google","label":"Google","image_key":null},{"id":"opt_a_magic_link","label":"A magic link","image_key":null},{"id":"opt_single_sign_on","label":"Single sign-on","image_key":null}],"allowOther":false},{"id":"blk_supportt07","ref":"broken_where","title":"Where in the product?","description":"The page name or the URL is perfect.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_supportt08","ref":"broken_since","title":"Since when?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_now","label":"Just now","image_key":null},{"id":"opt_today","label":"Today","image_key":null},{"id":"opt_this_week","label":"This week","image_key":null},{"id":"opt_it_s_never","label":"It''s never worked","image_key":null}],"allowOther":false},{"id":"blk_supportt09","ref":"broken_what","title":"What happens, and what did you expect to happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_supportt10","ref":"trying_to_do","title":"What are you trying to get done?","description":"Describe the result you want, not the button. There''s often a shorter way.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_supportt11","ref":"other_issue","title":"Tell us what''s going on.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_supportt12","ref":"tried","title":"What have you already tried?","description":"Even \"nothing yet\" helps, so we don''t suggest what you''ve done.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_supportt13","ref":"details","title":"Anything else we should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_supportt14","ref":"attachment","title":"Anything to attach? A screenshot is often worth a paragraph.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":3,"maxSizeMB":10},{"id":"blk_supportt15","ref":"urgency","title":"How urgent is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_blocking_i_can","label":"Blocking: I can''t work","image_key":null},{"id":"opt_important_but_it","label":"Important, but it can wait a day","image_key":null},{"id":"opt_whenever_you_get","label":"Whenever you get to it","image_key":null}],"allowOther":false}],"endings":[{"id":"end_supportt01","ref":"end_thanks","title":"Ticket created 🎫","bodyMd":"Thanks. We''ll reply to your account email, usually within a working day.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_supportt02","ref":"end_urgent","title":"Flagged as urgent 🚨","bodyMd":"Your ticket is at the top of the queue. We''ll reply to your account email as soon as someone picks it up.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_supportt01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"billing_issue","target":"tried","targetKind":"block"},{"id":"rl_supportt02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"login_method","target":"tried","targetKind":"block"},{"id":"rl_supportt03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"broken_what","target":"tried","targetKind":"block"},{"id":"rl_supportt04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"trying_to_do","target":"tried","targetKind":"block"},{"id":"rl_supportt05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"category"},"op":"eq","value":"opt_billing_or_invoices"}],"groups":[]},"from":"category","target":"invoice_number","targetKind":"block","branch":"true"},{"id":"rl_supportt06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"category"},"op":"eq","value":"opt_account_and_sign"}],"groups":[]},"from":"category","target":"login_error","targetKind":"block","branch":"true"},{"id":"rl_supportt07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"category"},"op":"eq","value":"opt_something_isn_t"}],"groups":[]},"from":"category","target":"broken_where","targetKind":"block","branch":"true"},{"id":"rl_supportt08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"category"},"op":"eq","value":"opt_how_do_i"}],"groups":[]},"from":"category","target":"trying_to_do","targetKind":"block","branch":"true"},{"id":"rl_supportt09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"category"},"op":"eq","value":"opt_something_else"}],"groups":[]},"from":"category","target":"other_issue","targetKind":"block","branch":"true"},{"id":"rl_supportt10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"urgency"},"op":"eq","value":"opt_blocking_i_can"}],"groups":[]},"from":"urgency","target":"end_urgent","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffdce8","surface":"#ffffff","text":"#3d1424","accent":"#be185d","accentText":"#fff7fa","botBubble":"#ffffff","userBubble":"#be185d","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"scallops","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
