VALUES ('tpl_productonboardingform', 'product-onboarding-form', 'Product onboarding form', 'Form', 'Find out what a new customer needs to get started, before they get lost.', 'Asks new customers for their goal, their team and what they want to set up first, so your welcome can be about their job instead of a generic tour. People switching from another tool are asked what they''re leaving and whether data needs to come across, and anyone who wants a walkthrough is asked for a number and a date.', '["customer success","product onboarding","customer onboarding","welcome survey","SaaS onboarding","branching"]', 'Rocket', 'number', 4, 14, '{"schemaVersion":9,"title":"Product onboarding","description":"Find out what a new customer needs to get started, before they get lost.","blocks":[{"id":"blk_producto00","ref":"welcome","title":"Welcome! Tell us a little about what you''re here to do and we''ll help you get started.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_producto01","ref":"contact","title":"What''s your name and email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_producto02","ref":"company","title":"Which company or team are you with?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_producto03","ref":"role","title":"What''s your role?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_founder_or_owner","label":"Founder or owner","image_key":null},{"id":"opt_manager_or_team","label":"Manager or team lead","image_key":null},{"id":"opt_individual_contributor","label":"Individual contributor","image_key":null},{"id":"opt_it_or_admin","label":"IT or admin","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_producto04","ref":"team_size","title":"How many people will use it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_2_10","label":"2–10","image_key":null},{"id":"opt_11_50","label":"11–50","image_key":null},{"id":"opt_more_than_50","label":"More than 50","image_key":null}],"allowOther":false},{"id":"blk_producto05","ref":"starting_point","title":"Which of these sounds most like you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_we_re_replacing","label":"We''re replacing a tool we use today","image_key":null},{"id":"opt_we_re_setting","label":"We''re setting up something new","image_key":null},{"id":"opt_i_m_trying","label":"I''m trying it out before we decide","image_key":null}],"allowOther":false},{"id":"blk_producto06","ref":"current_tool","title":"What are you using today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_producto07","ref":"migrate","title":"Do you need to bring existing data across?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_producto08","ref":"goal","title":"What would make your first month with us a success?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_producto09","ref":"first_setup","title":"Put these in the order you''d like to set them up","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_inviting_my","label":"Inviting my team"},{"id":"opt_item_getting_our","label":"Getting our data in"},{"id":"opt_item_connecting_other","label":"Connecting other tools we use"},{"id":"opt_item_settings_and","label":"Settings and branding"},{"id":"opt_item_reports","label":"Reports"}]},{"id":"blk_producto10","ref":"comfort","title":"How comfortable are you with tools like this?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Brand new to it","labelHigh":"I''ve used plenty"},{"id":"blk_producto11","ref":"go_live","title":"Is there a date you need to be up and running by?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_producto12","ref":"setup_help","title":"How would you like to get set up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_ll_find","label":"I''ll find my way around","image_key":null},{"id":"opt_send_me_a","label":"Send me a short setup guide","image_key":null},{"id":"opt_i_d_like","label":"I''d like a walkthrough call","image_key":null}],"allowOther":false},{"id":"blk_producto13","ref":"phone","title":"What number should we call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_producto14","ref":"call_date","title":"Which day suits you for the call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"}],"endings":[{"id":"end_producto01","ref":"end_thanks","title":"You''re ready to go 🚀","bodyMd":"Thanks! We''ll send tips that match what you told us, starting with the first thing on your list.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_producto02","ref":"end_call","title":"Walkthrough requested 📞","bodyMd":"We''ll confirm a time by email. Bring your questions, and we''ll set up the first thing on your list together.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_producto01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"call_date","target":"end_call","targetKind":"ending"},{"id":"rl_producto02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"starting_point"},"op":"eq","value":"opt_we_re_setting"}],"groups":[]},"from":"starting_point","target":"goal","targetKind":"block","branch":"true"},{"id":"rl_producto03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"starting_point"},"op":"eq","value":"opt_i_m_trying"}],"groups":[]},"from":"starting_point","target":"goal","targetKind":"block","branch":"true"},{"id":"rl_producto04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"setup_help"},"op":"eq","value":"opt_i_ll_find"}],"groups":[]},"from":"setup_help","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_producto05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"setup_help"},"op":"eq","value":"opt_send_me_a"}],"groups":[]},"from":"setup_help","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
