INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_productevaluationform', 'product-evaluation-form', 'Product evaluation form', 'Form', 'Score a product on the job it has to do, and find out exactly where it falls short.', 'Starts from the job the product was used for, then scores it on the same criteria for every reviewer so products can be compared fairly. If it falls even slightly short, the form asks what is missing and whether that rules it out, instead of asking for praise it has not earned.', '["evaluation","product evaluation","product review","product testing","evaluation criteria","branching"]', 'ClipboardCheck', 'scale', 4, 13, '{"schemaVersion":9,"title":"Product evaluation","description":"Score a product on the job it has to do, and find out exactly where it falls short.","blocks":[{"id":"blk_producte00","ref":"welcome","title":"Thanks for trying the product. A few questions on how it held up in real use.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_producte01","ref":"product","title":"Which product are you evaluating?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_producte02","ref":"use_case","title":"What did you use it for?","description":"The actual task or situation, so your scores have context.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_producte03","ref":"time_used","title":"How long have you been using it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a week","image_key":null},{"id":"opt_1_4_weeks","label":"1–4 weeks","image_key":null},{"id":"opt_1_6_months","label":"1–6 months","image_key":null},{"id":"opt_longer_than_6","label":"Longer than 6 months","image_key":null}],"allowOther":false},{"id":"blk_producte04","ref":"criteria","title":"How does it score on each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_usefulness_for","label":"Usefulness for the job"},{"id":"opt_row_ease_of","label":"Ease of use"},{"id":"opt_row_quality_and","label":"Quality and reliability"},{"id":"opt_row_design_and","label":"Design and finish"},{"id":"opt_row_value_for","label":"Value for money"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_producte05","ref":"overall","title":"Overall, how would you rate it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_producte06","ref":"fit","title":"Does it do everything you need it to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_fully","label":"Yes, fully","image_key":null},{"id":"opt_mostly","label":"Mostly","image_key":null},{"id":"opt_no_something_important","label":"No, something important is missing","image_key":null}],"allowOther":false},{"id":"blk_producte07","ref":"strengths","title":"What does it do best?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_producte08","ref":"gaps","title":"What is missing, or what got in your way?","description":"A specific example is more useful than a general complaint.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_producte09","ref":"dealbreaker","title":"Is that a dealbreaker for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, it rules it out","noLabel":"No, I can work around it"},{"id":"blk_producte10","ref":"compared","title":"Compared with what you used before, is it better or worse?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_better","label":"Better","image_key":null},{"id":"opt_about_the_same","label":"About the same","image_key":null},{"id":"opt_worse","label":"Worse","image_key":null},{"id":"opt_i_had_nothing","label":"I had nothing before this","image_key":null}],"allowOther":false},{"id":"blk_producte11","ref":"improvements","title":"Rank these by how much they would improve the product for you","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_simpler_to","label":"Simpler to use"},{"id":"opt_item_better_quality","label":"Better quality"},{"id":"opt_item_more_features","label":"More features"},{"id":"opt_item_lower_price","label":"Lower price"},{"id":"opt_item_better_instructions","label":"Better instructions and support"}]},{"id":"blk_producte12","ref":"keep_using","title":"How likely are you to keep using it, or to buy it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Very unlikely","labelHigh":"Very likely"},{"id":"blk_producte13","ref":"email","title":"If we have a follow-up question, where can we reach you?","description":"Optional. Leave it blank to stay anonymous.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_producte01","ref":"end_thanks","title":"Thanks for the honest review","bodyMd":"Your scores go next to everyone else''s, and the written answers are what we read first.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_producte01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"strengths","target":"compared","targetKind":"block"},{"id":"rl_producte02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"fit"},"op":"eq","value":"opt_yes_fully"}],"groups":[]},"from":"fit","target":"strengths","targetKind":"block","branch":"true"},{"id":"rl_producte03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"fit"},"op":"eq","value":"opt_mostly"}],"groups":[]},"from":"fit","target":"gaps","targetKind":"block","branch":"true"},{"id":"rl_producte04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"fit"},"op":"eq","value":"opt_no_something_important"}],"groups":[]},"from":"fit","target":"gaps","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
