INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_softwareevaluationform', 'software-evaluation-form', 'Software evaluation form', 'Form', 'Test software on real work and get a recommendation each reviewer can explain.', 'Built for a team trial: each reviewer records what they tested, how the tool met each requirement and what broke. Security concerns get their own follow-up, and the final recommendation branches so a conditional yes says what the conditions are and a no says why.', '["evaluation","software evaluation","software selection","tool comparison","vendor evaluation","requirements","IT"]', 'Laptop', 'scale', 4, 15, '{"schemaVersion":9,"title":"Software evaluation","description":"Test software on real work and get a recommendation each reviewer can explain.","blocks":[{"id":"blk_software00","ref":"welcome","title":"You''ve had time with the tool. Let''s capture what you found while it''s fresh.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_software01","ref":"software","title":"Which software are you evaluating?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_software02","ref":"reviewer_role","title":"Which best describes your part in this evaluation?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_d_use","label":"I''d use it every day","image_key":null},{"id":"opt_i_manage_the","label":"I manage the people who''d use it","image_key":null},{"id":"opt_it_security_or","label":"IT, security or admin","image_key":null},{"id":"opt_finance_or_purchasing","label":"Finance or purchasing","image_key":null}],"allowOther":false},{"id":"blk_software03","ref":"tasks","title":"Which tasks did you try in it?","description":"The real work you''d use it for, not the vendor''s demo.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_software04","ref":"hours","title":"Roughly how many hours did you spend testing it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":500,"integerOnly":false},{"id":"blk_software05","ref":"requirements","title":"How well does it meet each requirement?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_covers_our","label":"Covers our core workflow"},{"id":"opt_row_works_with","label":"Works with the tools we already use"},{"id":"opt_row_reporting_and","label":"Reporting and exports"},{"id":"opt_row_user_permissions","label":"User permissions and admin controls"},{"id":"opt_row_speed_and","label":"Speed and reliability"}],"columns":[{"id":"opt_col_doesn_t","label":"Doesn''t meet"},{"id":"opt_col_partly_meets","label":"Partly meets"},{"id":"opt_col_fully_meets","label":"Fully meets"},{"id":"opt_col_didn_t","label":"Didn''t test"}],"multiplePerRow":false},{"id":"blk_software06","ref":"ease","title":"How easy was it to finish your tasks without help?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Needed help constantly","labelHigh":"No help needed"},{"id":"blk_software07","ref":"ramp_up","title":"How long before you felt productive in it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_an_hour","label":"Under an hour","image_key":null},{"id":"opt_about_a_day","label":"About a day","image_key":null},{"id":"opt_about_a_week","label":"About a week","image_key":null},{"id":"opt_i_m_still","label":"I''m still not there","image_key":null}],"allowOther":false},{"id":"blk_software08","ref":"limitations","title":"What limitations, bugs or workarounds did you run into?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_software09","ref":"security_concern","title":"Did anything raise a security, privacy or compliance concern?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_software10","ref":"security_detail","title":"What was it? Include where you saw it, so someone can check.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_software11","ref":"verdict","title":"What''s your recommendation?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_adopt_it","label":"Adopt it","image_key":null},{"id":"opt_adopt_it_with","label":"Adopt it, with conditions","image_key":null},{"id":"opt_keep_looking","label":"Keep looking","image_key":null},{"id":"opt_don_t_adopt","label":"Don''t adopt it","image_key":null}],"allowOther":false},{"id":"blk_software12","ref":"conditions","title":"What would need to be true before we adopt it?","description":"A missing feature, a contract term, training, anything.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_software13","ref":"reason_against","title":"What''s the main reason against it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_software14","ref":"confidence","title":"How confident are you in that recommendation?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not very","labelHigh":"Completely"},{"id":"blk_software15","ref":"evidence","title":"Any screenshots or notes to attach?","description":"Optional. Screenshots of bugs or missing features help the most.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":10}],"endings":[{"id":"end_software01","ref":"end_thanks","title":"Evaluation recorded","bodyMd":"Thanks. Your notes go to whoever is making the final call, alongside the other reviewers''.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_software01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"conditions","target":"confidence","targetKind":"block"},{"id":"rl_software02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"security_concern"},"op":"eq","value":true}],"groups":[]},"from":"security_concern","target":"security_detail","targetKind":"block","branch":"true"},{"id":"rl_software03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"security_concern"},"op":"eq","value":false}],"groups":[]},"from":"security_concern","target":"verdict","targetKind":"block","branch":"true"},{"id":"rl_software04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"verdict"},"op":"eq","value":"opt_adopt_it"}],"groups":[]},"from":"verdict","target":"confidence","targetKind":"block","branch":"true"},{"id":"rl_software05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"verdict"},"op":"eq","value":"opt_adopt_it_with"}],"groups":[]},"from":"verdict","target":"conditions","targetKind":"block","branch":"true"},{"id":"rl_software06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"verdict"},"op":"eq","value":"opt_keep_looking"}],"groups":[]},"from":"verdict","target":"reason_against","targetKind":"block","branch":"true"},{"id":"rl_software07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"verdict"},"op":"eq","value":"opt_don_t_adopt"}],"groups":[]},"from":"verdict","target":"reason_against","targetKind":"block","branch":"true"},{"id":"rl_software08","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"security_detail","target":"evidence","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffdce8","surface":"#ffffff","text":"#3d1424","accent":"#be185d","accentText":"#fff7fa","botBubble":"#ffffff","userBubble":"#be185d","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"scallops","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
