INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_selfevaluationform', 'self-evaluation-form', 'Self evaluation form', 'Form', 'A reflective self-review that gives the review conversation real examples to work from.', 'Asks for evidence rather than adjectives: a win with an example, how goals actually went and a challenge handled. Missed goals and a heavy workload each get a follow-up question, so the manager walks into the review knowing what got in the way.', '["evaluation","self evaluation","self assessment","performance review","employee review","HR"]', 'UserCheck', 'scale', 4, 14, '{"schemaVersion":9,"title":"Self evaluation","description":"A reflective self-review that gives the review conversation real examples to work from.","blocks":[{"id":"blk_selfeval00","ref":"welcome","title":"This is your space to reflect before your review. Honest beats polished.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_selfeval01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_selfeval02","ref":"role","title":"What''s your role, and which team are you on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_selfeval03","ref":"review_type","title":"Which review is this for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_quarterly_check_in","label":"Quarterly check-in","image_key":null},{"id":"opt_mid_year_review","label":"Mid-year review","image_key":null},{"id":"opt_annual_review","label":"Annual review","image_key":null},{"id":"opt_end_of_probation","label":"End of probation","image_key":null}],"allowOther":false},{"id":"blk_selfeval04","ref":"proudest","title":"What are you proudest of from this period?","description":"Give one or two concrete examples: what you did and what changed because of it.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_selfeval05","ref":"goals_met","title":"How did you do against the goals set at the start of the period?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_met_or_beat","label":"Met or beat all of them","image_key":null},{"id":"opt_met_most","label":"Met most","image_key":null},{"id":"opt_met_some","label":"Met some","image_key":null},{"id":"opt_met_few_or","label":"Met few or none","image_key":null}],"allowOther":false},{"id":"blk_selfeval06","ref":"goals_blockers","title":"What got in the way of the ones you missed?","description":"Priorities changing, resources, skills, anything. This is not about blame.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_selfeval07","ref":"self_rating","title":"How would you rate yourself on each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_quality_of","label":"Quality of work"},{"id":"opt_row_communication","label":"Communication"},{"id":"opt_row_working_with","label":"Working with others"},{"id":"opt_row_ownership_and","label":"Ownership and follow-through"},{"id":"opt_row_learning_new","label":"Learning new skills"}],"columns":[{"id":"opt_col_needs_work","label":"Needs work"},{"id":"opt_col_solid","label":"Solid"},{"id":"opt_col_a_real","label":"A real strength"}],"multiplePerRow":false},{"id":"blk_selfeval08","ref":"challenge","title":"Describe a challenge you faced and how you handled it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_selfeval09","ref":"workload","title":"How manageable has your workload been?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Unsustainable","labelHigh":"Very manageable"},{"id":"blk_selfeval10","ref":"workload_detail","title":"What''s making it hard to manage?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_selfeval11","ref":"growth","title":"Where do you most want to grow next? Pick up to three.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_technical_or_craft","label":"Technical or craft skills","image_key":null},{"id":"opt_leading_people","label":"Leading people","image_key":null},{"id":"opt_communication_and_presenti","label":"Communication and presenting","image_key":null},{"id":"opt_planning_and_prioritising","label":"Planning and prioritising","image_key":null},{"id":"opt_strategic_thinking","label":"Strategic thinking","image_key":null},{"id":"opt_knowledge_of_the","label":"Knowledge of the wider business","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_selfeval12","ref":"next_goals","title":"What do you want to achieve next period?","description":"Two or three goals in your own words. You''ll agree the final version with your manager.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_selfeval13","ref":"support","title":"What support would help you most next period?","description":"From your manager, the team, training, tools or time.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLeng