VALUES ('tpl_onlineeventregistrationf', 'online-event-registration-form', 'Online event registration form', 'Form', 'Sign people up for the sessions they want and send the right access details to each.', 'Built for an online event with several sessions: attendees pick the ones they want, so you know which rooms will fill. Anyone who chooses the hands-on workshop is asked what device they will use and how experienced they are, since that session needs more from them than watching.', '["event registration","online event registration","virtual event registration","virtual conference","online workshop","branching"]', 'MonitorPlay', 'choice', 3, 10, '{"schemaVersion":9,"title":"Online event registration","description":"Sign people up for the sessions they want and send the right access details to each.","blocks":[{"id":"blk_onlineev00","ref":"welcome","title":"Welcome! Let''s get you registered and tell you where to join.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_onlineev01","ref":"contact","title":"Who''s registering?","description":"We''ll send your joining links to this email.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_onlineev02","ref":"organisation","title":"Which organisation are you with, if any?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_onlineev03","ref":"sessions","title":"Which sessions would you like to join?","description":"Pick as many as you like. You''ll get a separate link for each.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_opening_keynote","label":"Opening keynote","image_key":null},{"id":"opt_panel_discussion","label":"Panel discussion","image_key":null},{"id":"opt_hands_on_workshop","label":"Hands-on workshop (limited places)","image_key":null},{"id":"opt_breakout_discussions","label":"Breakout discussions","image_key":null},{"id":"opt_closing_q_a","label":"Closing Q&A","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_onlineev04","ref":"workshop_device","title":"The workshop is hands-on. What will you join it from?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_laptop_or","label":"A laptop or desktop","image_key":null},{"id":"opt_a_tablet","label":"A tablet","image_key":null},{"id":"opt_a_phone","label":"A phone","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}],"allowOther":false},{"id":"blk_onlineev05","ref":"workshop_level","title":"How much do you already know about the workshop topic?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Starting from scratch","labelHigh":"I use it every day"},{"id":"blk_onlineev06","ref":"timezone","title":"Which city or timezone will you join from?","description":"So your reminders arrive at a sensible hour.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_onlineev07","ref":"access","title":"Would any of these help you take part?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_live_captions","label":"Live captions","image_key":null},{"id":"opt_a_transcript_afterwards","label":"A transcript afterwards","image_key":null},{"id":"opt_sign_language_interpretati","label":"Sign language interpretation","image_key":null},{"id":"opt_the_recording_to","label":"The recording, to watch later","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_onlineev08","ref":"speaker_question","title":"Is there anything you''d like the speakers to cover?","description":"Say which session it''s for. We pass these to each speaker before the day.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_onlineev09","ref":"heard_from","title":"How did you hear about the event?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_a_colleague_or","label":"A colleague or friend","image_key":null},{"id":"opt_search_engine","label":"Search engine","image_key":null},{"id":"opt_a_partner_or","label":"A partner or community group","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}]},{"id":"blk_onlineev10","ref":"future_events","title":"Can we let you know about future online events?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"}],"endings":[{"id":"end_onlineev01","ref":"end_thanks","title":"You''re registered 💻","bodyMd":"Your joining links are on their way. We''ll send a reminder before each session you picked.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_onlineev01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"sessions"},"op":"not_contains","value":"opt_hands_on_workshop"}],"groups":[]},"from":"sessions","target":"timezone","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
