VALUES ('tpl_eventvolunteerform', 'event-volunteer-form', 'Event volunteer form', 'Form', 'Find out who can help, when, and with what, before you draw up the rota.', 'Collects exactly what you need to build a volunteer rota: available shifts, a ranking of preferred roles, and skills like first aid that change where someone is most useful. First aiders are asked when their certificate runs out, so you only roster ones who are current on the day. Volunteers under 18 give a parent or guardian contact, and everyone agrees to the volunteer code at the end.', '["event registration","event volunteer form","volunteer signup","volunteer registration","volunteer rota","branching"]', 'HandHeart', 'choice', 4, 12, '{"schemaVersion":9,"title":"Event volunteer signup","description":"Find out who can help, when, and with what, before you draw up the rota.","blocks":[{"id":"blk_eventvol00","ref":"welcome","title":"Thanks for offering to help! This takes a few minutes and helps us put you in the right place.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventvol01","ref":"contact","title":"How can we reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_eventvol02","ref":"adult","title":"Are you 18 or over?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_eventvol03","ref":"guardian","title":"What''s the name and phone number of a parent or guardian who can approve this?","description":"We''ll check with them before confirming your shifts.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":160},{"id":"blk_eventvol04","ref":"shifts","title":"Which shifts can you cover?","description":"Pick every one you could do. We won''t give you all of them.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_setup_the_day","label":"Setup, the day before","image_key":null},{"id":"opt_event_day_morning","label":"Event day, morning","image_key":null},{"id":"opt_event_day_afternoon","label":"Event day, afternoon","image_key":null},{"id":"opt_event_day_evening","label":"Event day, evening","image_key":null},{"id":"opt_pack_down_after","label":"Pack-down after close","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_eventvol05","ref":"roles","title":"Rank these roles from the one you''d most like to the least","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_welcome_and","label":"Welcome and registration desk"},{"id":"opt_item_guiding_and","label":"Guiding and helping guests"},{"id":"opt_item_setup_and","label":"Setup and pack-down"},{"id":"opt_item_food_and","label":"Food and drink"},{"id":"opt_item_looking_after","label":"Looking after speakers or performers"},{"id":"opt_item_photos_and","label":"Photos and social media"}]},{"id":"blk_eventvol06","ref":"skills","title":"Do any of these apply to you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_first_aid_trained","label":"First aid trained","image_key":null},{"id":"opt_speak_another_language","label":"Speak another language","image_key":null},{"id":"opt_comfortable_lifting_and","label":"Comfortable lifting and carrying","image_key":null},{"id":"opt_have_a_driving","label":"Have a driving licence","image_key":null},{"id":"opt_experience_with_photograph","label":"Experience with photography","image_key":null},{"id":"opt_have_volunteered_at","label":"Have volunteered at events before","image_key":null}],"minSelections":0,"maxSelections":6,"allowOther":false},{"id":"blk_eventvol07","ref":"first_aid_expiry","title":"When does your first aid certificate run out?","description":"First aiders are placed before anyone else, so we need to know it''s current on the day.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_eventvol08","ref":"experience","title":"Tell us about any experience that would help us place you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_eventvol09","ref":"tshirt","title":"What size volunteer T-shirt should we save for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_xs","label":"XS","image_key":null},{"id":"opt_s_2","label":"S","image_key":null},{"id":"opt_m_3","label":"M","image_key":null},{"id":"opt_l_4","label":"L","image_key":null},{"id":"opt_xl","label":"XL","image_key":null},{"id":"opt_xxl","label":"XXL","image_key":null}]},{"id":"blk_eventvol10","ref":"needs","title":"Any dietary, access or health needs we should know about on the day?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_eventvol11","ref":"emergency","title":"Who should we call in an emergency? Name, relationship and phone number.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_eventvol12","ref":"code","title":"Please read and agree to the volunteer code","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I will arrive on time for the shifts I''m given, or let the volunteer coordinator know as early as possible if I can''t. I will follow instructions from event staff, treat guests and other volunteers with respect, and report any safety concern straight away.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_eventvol01","ref":"end_thanks","title":"Thank you for volunteering 🙌","bodyMd":"We''ll email your shifts and a briefing before the event.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_eventvol01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"adult"},"op":"eq","value":true}],"groups":[]},"from":"adult","target":"shifts","targetKind":"block","branch":"true"},{"id":"rl_eventvol02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"adult"},"op":"eq","value":false}],"groups":[]},"from":"adult","target":"guardian","targetKind":"block","branch":"true"},{"id":"rl_eventvol03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"skills"},"op":"not_contains","value":"opt_first_aid_trained"}],"groups":[]},"from":"skills","target":"experience","targetKind":"block","branch":"true"},{"id":"rl_eventvol04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"guardian","target":"roles","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#f26b1d","surface":"#fff7f0","text":"#1c1917","accent":"#1c1917","accentText":"#ffffff","botBubble":"#fff7f0","userBubble":"#1c1917","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundPatternColor":"#1c1917","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
