VALUES ('tpl_webinarregistration', 'webinar-registration', 'Webinar registration form', 'Form', 'Register attendees, and ask the ones who can''t join live what would have helped.', 'The best webinar Q&A is written before the webinar starts. This asks what attendees want covered, and splits the people joining live from the ones who only want the recording, because those two get different emails afterwards and each reaches its own ending that says so.', '["event registration","webinar registration","webinar signup","online event","lead generation","branching"]', 'Video', 'choice', 3, 11, '{"schemaVersion":9,"title":"Webinar registration","description":"Register attendees, and ask the ones who can''t join live what would have helped.","blocks":[{"id":"blk_webinarr00","ref":"welcome","title":"Save your seat. It takes about a minute.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_webinarr01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":100},{"id":"blk_webinarr02","ref":"email","title":"Where should we send the joining link?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_webinarr03","ref":"company","title":"Which company are you with?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_webinarr04","ref":"job_title","title":"And your job title?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_webinarr05","ref":"familiarity","title":"How familiar are you with the topic?","description":"So the speaker knows how much ground to cover before the interesting part.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_new_to_it","label":"New to it","image_key":null},{"id":"opt_i_know_the","label":"I know the basics","image_key":null},{"id":"opt_i_work_with","label":"I work with it regularly","image_key":null}],"allowOther":false},{"id":"blk_webinarr06","ref":"attendance","title":"Will you join live?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_live","label":"Yes, live","image_key":null},{"id":"opt_no_send_me","label":"No, send me the recording","image_key":null}],"allowOther":false},{"id":"blk_webinarr07","ref":"question","title":"Anything you''d like the speaker to cover?","description":"Questions sent in advance are answered first.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_webinarr08","ref":"reminder","title":"When should we remind you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_day_before","label":"A day before","image_key":null},{"id":"opt_an_hour_before","label":"An hour before","image_key":null},{"id":"opt_both","label":"Both","image_key":null},{"id":"opt_no_reminder_needed","label":"No reminder needed","image_key":null}],"allowOther":false},{"id":"blk_webinarr09","ref":"cannot_attend_reason","title":"What''s getting in the way?","description":"If it''s the time, we may run it again at a better hour for you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_wrong_time_of","label":"Wrong time of day for me","image_key":null},{"id":"opt_wrong_day","label":"Wrong day","image_key":null},{"id":"opt_i_just_prefer","label":"I just prefer recordings","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_webinarr10","ref":"recording_question","title":"Anything you''d like the speaker to cover? We''ll make sure it''s in the recording.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_webinarr11","ref":"timezone","title":"Which timezone are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80}],"endings":[{"id":"end_webinarr01","ref":"end_thanks","title":"See you there 🎥","bodyMd":"Your joining link and calendar invite are on their way.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_webinarr02","ref":"end_recording","title":"We''ll send the recording 📼","bodyMd":"It goes out soon after the session. No need to be anywhere.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_webinarr01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"reminder","target":"end_thanks","targetKind":"ending"},{"id":"rl_webinarr02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"timezone","target":"end_recording","targetKind":"ending"},{"id":"rl_webinarr03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"attendance"},"op":"eq","value":"opt_yes_live"}],"groups":[]},"from":"attendance","target":"question","targetKind":"block","branch":"true"},{"id":"rl_webinarr04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"attendance"},"op":"eq","value":"opt_no_send_me"}],"groups":[]},"from":"attendance","target":"cannot_attend_reason","targetKind":"block","branch":"true"}],"layout":{},