VALUES ('tpl_workshopregistration', 'workshop-registration', 'Workshop registration form', 'Form', 'Sign people up and check they''re ready for the day.', 'A hands-on workshop goes badly when half the room hasn''t installed anything. This asks about experience and setup so the right prep email goes to the right people: beginners are asked what they have tried and offered pre-reading, while experienced attendees say what they want to go deep on.', '["event registration","workshop registration","training registration","class signup","hands-on workshop","branching"]', 'Users', 'choice', 3, 11, '{"schemaVersion":9,"title":"Workshop registration","description":"Sign people up and check they''re ready for the day.","blocks":[{"id":"blk_workshop00","ref":"welcome","title":"Let''s get you registered. A few details and you''re set.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_workshop01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":100},{"id":"blk_workshop02","ref":"email","title":"What email should the prep instructions go to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_workshop03","ref":"organisation","title":"Which organisation are you with, if any?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_workshop04","ref":"session","title":"Which session would you like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_morning_9_00","label":"Morning (9:00–12:00)","image_key":null},{"id":"opt_afternoon_13_00","label":"Afternoon (13:00–16: