VALUES ('tpl_eventsignupform', 'event-signup-form', 'Event signup form', 'Form', 'A quick signup that tells you who is coming, how, and what they want from the day.', 'Asks early whether someone is coming in person or joining online, then only asks what matters for that choice: group size and access needs for the venue, a timezone for the stream. Everyone finishes by picking the parts of the programme they are most interested in, which helps you plan rooms and reminders.', '["event","event signup","event sign up sheet","meetup signup","attendee list","branching"]', 'CalendarCheck', 'number', 3, 9, '{"schemaVersion":9,"title":"Event signup","description":"A quick signup that tells you who is coming, how, and what they want from the day.","blocks":[{"id":"blk_eventsig00","ref":"welcome","title":"Glad you''re interested! Let''s get you on the list. It takes about a minute.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventsig01","ref":"contact","title":"Who should we put on the list?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_eventsig02","ref":"mode","title":"How are you planning to join?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_person","label":"In person","image_key":null},{"id":"opt_online","label":"Online","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}],"allowOther":false},{"id":"blk_eventsig03","ref":"party_size","title":"How many people are coming, including you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":10,"integerOnly":true},{"id":"blk_eventsig04","ref":"access_needs","title":"Anything we should arrange so the venue works for your group?","description":"Step-free access, seating, a quiet space, dietary needs. Leave blank if nothing.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_eventsig05","ref":"timezone","title":"Which city or timezone will you join from?","description":"So reminders arrive at a sensible time for you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_eventsig06","ref":"interests","title":"Which parts of the event are you most interested in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_talks","label":"Talks","image_key":null},{"id":"opt_hands_on_workshops","label":"Hands-on workshops","image_key":null},{"id":"opt_meeting_other_attendees","label":"Meeting other attendees","image_key":null},{"id":"opt_demos_and_exhibitors","label":"Demos and exhibitors","image_key":null},{"id":"opt_the_social_afterwards","label":"The social afterwards","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_eventsig07","ref":"heard_from","title":"How did you hear about it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_friend_or","label":"A friend or colleague","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_email_newsletter","label":"Email newsletter","image_key":null},{"id":"opt_i_came_last","label":"I came last time","image_key":null}],"allowOther":true},{"id":"blk_eventsig08","ref":"question","title":"Anything you''d like to ask the organisers or the speakers?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_eventsig09","ref":"future_events","title":"Can we email you about future events like this one?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, keep me posted","noLabel":"Just this one"}],"endings":[{"id":"end_eventsig01","ref":"end_thanks","title":"You''re on the list 🎉","bodyMd":"We''ll email you the details and a reminder before the day.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_eventsig01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"access_needs","target":"interests","targetKind":"block"},{"id":"rl_eventsig02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"mode"},"op":"eq","value":"opt_in_person"}],"groups":[]},"from":"mode","target":"party_size","targetKind":"block","branch":"true"},{"id":"rl_eventsig03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"mode"},"op":"eq","value":"opt_online"}],"groups":[]},"from":"mode","target":"timezone","targetKind":"block","branch":"true"},{"id":"rl_eventsig04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"mode"},"op":"eq","value":"opt_not_sure_yet"}],"groups":[]},"from":"mode","target":"interests","targetKind":"block","branch":"true"},{"id":"rl_eventsig05","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"timezone","target":"heard_from","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
