VALUES ('tpl_eventrsvp', 'event-rsvp', 'Event RSVP form', 'Form', 'Collect RSVPs with plus-ones, dietary notes and travel.', 'Everything the caterer and the door list need, in the order a guest thinks about it, and nothing else. Someone who can''t come is asked one kind question and reaches their own ending in seconds; someone who is coming is walked through guests, food and arrival. Guest names are only asked for when someone brings guests, and the kitchen follow-up only appears if a dietary need needs explaining.', '["event","rsvp form","party rsvp","wedding rsvp","guest list","dietary requirements","branching"]', 'PartyPopper', 'number', 3, 11, '{"schemaVersion":9,"title":"Event RSVP","description":"Collect RSVPs with plus-ones, dietary notes and travel.","blocks":[{"id":"blk_eventrsv00","ref":"welcome","title":"You''re invited! 🎉 Let us know if you can make it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventrsv01","ref":"name","title":"What''s your full name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":100},{"id":"blk_eventrsv02","ref":"email","title":"What email should we send the details to nearer the time?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_eventrsv03","ref":"attending","title":"Will you be joining us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Count me in","noLabel":"Can''t make it"},{"id":"blk_eventrsv04","ref":"guests","title":"How many guests are you bringing?","description":"Not counting yourself. Put 0 if you''re coming alone.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":10,"integerOnly":true},{"id":"blk_eventrsv05","ref":"guest_names","title":"Who are they? One name per line.","description":"For the door list and the place cards.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_eventrsv06","ref":"dietary","title":"Any dietary requirements in your party?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_none","label":"None","image_key":null},{"id":"opt_vegetarian","label":"Vegetarian","image_key":null},{"id":"opt_vegan","label":"Vegan","image_key":null},{"id":"opt_gluten_free","label":"Gluten-free","image_key":null},{"id":"opt_dairy_free","label":"Dairy-free","image_key":null},{"id":"opt_nut_allergy","label":"Nut allergy","image_key":null},{"id":"opt_other_i_ll","label":"Other (I''ll explain)","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_eventrsv07","ref":"dietary_detail","title":"Tell us more, so the kitchen gets it right","description":"Include who it''s for if you''re bringing guests.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_eventrsv08","ref":"arrival","title":"How are you getting here?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_driving_i_ll","label":"Driving (I''ll need parking)","image_key":null},{"id":"opt_public_transport","label":"Public transport","image_key":null},{"id":"opt_taxi_or_lift","label":"Taxi or lift","image_key":null},{"id":"opt_walking","label":"Walking","image_key":null}],"allowOther":false},{"id":"blk_eventrsv09","ref":"song","title":"One song that would get you on the dance floor?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_eventrsv10","ref":"cannot_reason","title":"Sorry to hear that. Anything we should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_away_that_week","label":"Away that week","image_key":null},{"id":"opt_work","label":"Work","image_key":null},{"id":"opt_too_far_to","label":"Too far to travel","image_key":null},{"id":"opt_i_d_rather","label":"I''d rather not say","image_key":null}],"allowOther":false},{"id":"blk_eventrsv11","ref":"message","title":"Want to leave a message for the hosts?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_eventrsv01","ref":"end_thanks","title":"See you there 🥂","bodyMd":"We''ll send the final details a week before.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_eventrsv02","ref":"end_sorry","title":"We''ll miss you 💛","bodyMd":"Thanks for letting us know. It genuinely helps with the numbers.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_eventrsv01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"song","target":"end_thanks","targetKind":"ending"},{"id":"rl_eventrsv02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"message","target":"end_sorry","targetKind":"ending"},{"id":"rl_eventrsv03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"attending"},"op":"eq","value":true}],"groups":[]},"from":"attending","target":"guests","targetKind":"block","branch":"true"},{"id":"rl_eventrsv04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"attending"},"op":"eq","value":false}],"groups":[]},"from":"attending","target":"cannot_reason","targetKind":"block","branch":"true"},{"id":"rl_eventrsv05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"guests"},"op":"eq","value":0}],"groups":[]},"from":"guests","target":"dietary","targetKind":"block","branch":"true"},{"id":"rl_eventrsv06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"dietary"},"op":"not_contains","value":"opt_other_i_ll"}],"groups":[]},"from":"dietary","target":"arrival","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
