INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_websitedesignfeedbackfor', 'website-design-feedback-form', 'Website design feedback form', 'Form', 'Structured comments on a page design, ranked by what should change first.', 'Built for design reviews that usually end in a messy email thread. Reviewers who can''t tell what the page is for are asked what confused them, everyone ranks what should change first, and anyone who wants to talk it through leaves an email and lands on their own ending.', '["feedback","website feedback","design review","web design","client review","usability feedback"]', 'Laptop', 'text', 4, 12, '{"schemaVersion":9,"title":"Website design feedback","description":"Structured comments on a page design, ranked by what should change first.","blocks":[{"id":"blk_websited00","ref":"welcome","title":"Thanks for looking over the new design. A few quick questions and your comments will be in one tidy place.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_websited01","ref":"page_url","title":"Which page are you reviewing?","description":"Paste the link to the page or the design preview.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_websited02","ref":"reviewer_role","title":"Which best describes you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_client_or","label":"The client or a stakeholder","image_key":null},{"id":"opt_someone_on_the","label":"Someone on the project team","image_key":null},{"id":"opt_a_potential_visitor","label":"A potential visitor or customer","image_key":null}],"allowOther":true},{"id":"blk_websited03","ref":"first_impression","title":"What was your first impression of the page?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Put me off","labelHigh":"Loved it"},{"id":"blk_websited04","ref":"purpose_clear","title":"Within a few seconds, could you tell what this page is for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_websited05","ref":"purpose_confusion","title":"What did you think it was for, and what threw you off?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_websited06","ref":"aspects","title":"How does the design do on each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_look_and","label":"Look and feel"},{"id":"opt_row_readability_of","label":"Readability of the text"},{"id":"opt_row_navigation_and","label":"Navigation and menus"},{"id":"opt_row_layout_on","label":"Layout on a phone"},{"id":"opt_row_how_fast","label":"How fast it loads"}],"columns":[{"id":"opt_col_needs_work","label":"Needs work"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_great","label":"Great"}],"multiplePerRow":false},{"id":"blk_websited07","ref":"find_info","title":"How easy was it to find what you were looking for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_very_easy","label":"Very easy","image_key":null},{"id":"opt_took_a_moment","label":"Took a moment","image_key":null},{"id":"opt_i_couldn_t","label":"I couldn''t find it","image_key":null}],"allowOther":false},{"id":"blk_websited08","ref":"change_order","title":"Put these in order of what should change first.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_headlines_and","label":"Headlines and copy"},{"id":"opt_item_layout_and","label":"Layout and spacing"},{"id":"opt_item_colours_and","label":"Colours and fonts"},{"id":"opt_item_images","label":"Images"},{"id":"opt_item_navigation","label":"Navigation"}]},{"id":"blk_websited09","ref":"specific_changes","title":"Which specific changes would you like to see?","description":"Point to the section if you can, for example \"the pricing table\" or \"the footer\".","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_websited10","ref":"screenshot","title":"Want to attach a marked-up screenshot?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":3,"maxSizeMB":10},{"id":"blk_websited11","ref":"discuss","title":"Would you like a call to talk the changes through?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, let''s talk","noLabel":"No, this covers it"},{"id":"blk_websited12","ref":"call_email","title":"What''s the best email to arrange that?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_websited01","ref":"end_thanks","title":"Thanks for the review","bodyMd":"Your comments go straight to the designer, and you''ll see the changes in the next round.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_websited02","ref":"end_call","title":"Let''s talk it through 📞","bodyMd":"We''ll email you to find a time, and bring your notes to the call.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_websited01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"call_email","target":"end_call","targetKind":"ending"},{"id":"rl_websited02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"purpose_clear"},"op":"eq","value":true}],"groups":[]},"from":"purpose_clear","target":"aspects","targetKind":"block","branch":"true"},{"id":"rl_websited03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"purpose_clear"},"op":"eq","value":false}],"groups":[]},"from":"purpose_clear","target":"purpose_confusion","targetKind":"block","branch":"true"},{"id":"rl_websited04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"discuss"},"op":"eq","value":false}],"groups":[]},"from":"discuss","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_websited05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"discuss"},"op":"eq","value":true}],"groups":[]},"from":"discuss","target":"call_email","targetKind":"block","branch":"true"},{"id":"rl_websited06","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"purpose_confusion","target":"find_info","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#5b2ee6","surface":"#4a22c9","text":"#ffffff","accent":"#ffd166","accentText":"#1c1917","botBubble":"#4a22c9","userBubble":"#ffd166","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundPatternColor":"#ffffff","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
