VALUES ('tpl_callcenteremployeeevalua', 'call-center-employee-evaluation-form', 'Call center employee evaluation form', 'Form', 'A consistent call review that turns each score into coaching or recognition.', 'A call review for team leads and QA reviewers that sticks to what can be heard on the recording. A low overall score opens a short coaching plan with a follow-up date, a strong one asks what the agent did well and whether the call belongs in training, and unresolved calls are asked what got in the way.', '["feedback","call center evaluation","call quality monitoring","QA scorecard","agent review","contact center"]', 'Phone', 'text', 4, 14, '{"schemaVersion":9,"title":"Call review","description":"A consistent call review that turns each score into coaching or recognition.","blocks":[{"id":"blk_callcent00","ref":"welcome","title":"Let''s review a call. Have the recording or transcript open while you go.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_callcent01","ref":"agent_name","title":"Which agent took the call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_callcent02","ref":"call_date","title":"When was the call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_callcent03","ref":"call_id","title":"What''s the call or ticket ID?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_callcent04","ref":"call_type","title":"What was the call about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_billing_question","label":"Billing question","image_key":null},{"id":"opt_technical_support","label":"Technical support","image_key":null},{"id":"opt_complaint","label":"Complaint","image_key":null},{"id":"opt_new_order_or","label":"New order or booking","image_key":null},{"id":"opt_cancellation_request","label":"Cancellation request","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_callcent05","ref":"behaviours","title":"How did the agent do on each part of the call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_greeting_and","label":"Greeting and identifying the customer"},{"id":"opt_row_listening_without","label":"Listening without interrupting"},{"id":"opt_row_giving_accurate","label":"Giving accurate information"},{"id":"opt_row_tone_and","label":"Tone and courtesy"},{"id":"opt_row_following_the","label":"Following the process and compliance steps"},{"id":"opt_row_closing_with","label":"Closing with clear next steps"}],"columns":[{"id":"opt_col_below_standard","label":"Below standard"},{"id":"opt_col_meets_standard","label":"Meets standard"},{"id":"opt_col_above_standard","label":"Above standard"}],"multiplePerRow":false},{"id":"blk_callcent06","ref":"resolution","title":"How was the customer''s issue handled?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_resolved_on_the","label":"Resolved on the call","image_key":null},{"id":"opt_escalated_to_the","label":"Escalated to the right place","image_key":null},{"id":"opt_left_unresolved","label":"Left unresolved","image_key":null}],"allowOther":false},{"id":"blk_callcent07","ref":"what_blocked","title":"What stopped it being resolved?","description":"Say whether it was the agent, a missing tool or a policy.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_callcent08","ref":"overall","title":"Overall, how well was this call handled?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_callcent09","ref":"coaching_focus","title":"What should coaching focus on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_product_knowledge","label":"Product knowledge","image_key":null},{"id":"opt_active_listening","label":"Active listening","image_key":null},{"id":"opt_tone_and_empathy","label":"Tone and empathy","image_key":null},{"id":"opt_following_the_process","label":"Following the process","image_key":null},{"id":"opt_handling_an_upset","label":"Handling an upset customer","image_key":null},{"id":"opt_call_control_and","label":"Call control and timing","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":false},{"id":"blk_callcent10","ref":"review_date","title":"When will you review another of their calls?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_callcent11","ref":"strengths","title":"What did the agent do especially well?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_callcent12","ref":"training_example","title":"Would this call make a good example for training?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_callcent13","ref":"notes","title":"Anything else the agent should hear about this call?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength"