VALUES ('tpl_restaurantfeedbackform', 'restaurant-feedback-form', 'Restaurant feedback form', 'Form', 'Hear what diners thought of the meal, and reach the unhappy ones quickly.', 'A short post-visit form that works for dine-in, takeaway and delivery. Guests who rate the visit three stars or less are asked what went wrong and can leave their details for the manager, while happy guests name the dish they''d come back for, which is exactly what you want to feature.', '["feedback","restaurant feedback","diner survey","guest feedback","customer comment card","hospitality"]', 'Utensils', 'text', 3, 10, '{"schemaVersion":9,"title":"Restaurant feedback","description":"Hear what diners thought of the meal, and reach the unhappy ones quickly.","blocks":[{"id":"blk_restaura00","ref":"welcome","title":"Thanks for eating with us. How was it? This takes about a minute.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_restaura01","ref":"visit_type","title":"How did you eat with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_dined_in","label":"Dined in","image_key":null},{"id":"opt_takeaway","label":"Takeaway","image_key":null},{"id":"opt_delivery","label":"Delivery","image_key":null}],"allowOther":false},{"id":"blk_restaura02","ref":"visit_date","title":"When was your visit?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_restaura03","ref":"aspects","title":"How would you rate each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_taste_of","label":"Taste of the food"},{"id":"opt_row_portion_size","label":"Portion size"},{"id":"opt_row_friendliness_of