VALUES ('tpl_retailstorefeedbackform', 'retail-store-feedback-form', 'Retail store feedback form', 'Form', 'What shoppers found, who helped and how checkout went, from the shop floor.', 'A store feedback form that covers the three places a visit goes wrong: finding the product, getting help and paying. Shoppers who couldn''t find what they came for are asked what it was, and anyone who scores the visit low can ask the store manager to follow up.', '["feedback","retail feedback","store survey","in-store experience","shopper feedback","customer satisfaction"]', 'Store', 'text', 4, 12, '{"schemaVersion":9,"title":"Store visit feedback","description":"What shoppers found, who helped and how checkout went, from the shop floor.","blocks":[{"id":"blk_retailst00","ref":"welcome","title":"Thanks for shopping with us. Tell us how your visit went, it takes about a minute.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_retailst01","ref":"store","title":"Which store did you visit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_retailst02","ref":"visit_reason","title":"What brought you in today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_to_buy_something","label":"To buy something specific","image_key":null},{"id":"opt_just_browsing","label":"Just browsing","image_key":null},{"id":"opt_a_return_or","label":"A return or exchange","image_key":null},{"id":"opt_collecting_an_online","label":"Collecting an online order","image_key":null}],"allowOther":false},{"id":"blk_retailst03","ref":"found_it","title":"Did you find what you were looking for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_easily","label":"Yes, easily"