VALUES ('tpl_coachingfeedbackform', 'coaching-feedback-form', 'Coaching feedback form', 'Form', 'Check in with coaching clients on progress, and shape the next session around it.', 'A mid-programme check-in for coaches, not an end-of-course survey. Clients who say coaching isn''t giving them what they hoped for are asked what''s missing and whether to talk before the next session, and those who would strongly recommend you are asked for a testimonial.', '["feedback","coaching feedback","coaching evaluation","client check-in","life coaching","executive coaching"]', 'Compass', 'text', 4, 14, '{"schemaVersion":9,"title":"Coaching feedback","description":"Check in with coaching clients on progress, and shape the next session around it.","blocks":[{"id":"blk_coaching00","ref":"welcome","title":"Thanks for taking a few minutes. Your answers shape how we spend our next sessions.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_coaching01","ref":"client_name","title":"What''s your first name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_coaching02","ref":"goal","title":"What''s the main goal you''re working on with me?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_coaching03","ref":"sessions_so_far","title":"How many sessions have we had so far?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_1_1","label":"1","image_key":null},{"id":"opt_2_5","label":"2–5","image_key":null},{"id":"opt_6_10","label":"6–10","image_key":null},{"id":"opt_more_than_10","label":"More than 10","image_key":null}],"allowOther":false},{"id":"blk_coaching04","ref":"progress","title":"How much progress have you made