VALUES ('tpl_softwareupdatefeedbackfo', 'software-update-feedback-form', 'Software update feedback form', 'Form', 'Hear how a new release changed people''s work, and catch what broke.', 'A post-release form that treats three kinds of user differently. People who used the new features rate the change, people who noticed but didn''t try them say why, and people who missed it entirely say where they''d expect to hear. Anyone who hit a bug describes it, rates how badly it hurts and can attach a screenshot.', '["feedback","release feedback","product update survey","software feedback","feature feedback","bug report"]', 'Rocket', 'text', 4, 14, '{"schemaVersion":9,"title":"Release feedback","description":"Hear how a new release changed people''s work, and catch what broke.","blocks":[{"id":"blk_software00","ref":"welcome","title":"We''ve just shipped an update. Tell us how it''s going for you, it takes about two minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_software01","ref":"version","title":"Which version are you using, if you know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"prefillParam":"version","type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_software02","ref":"usage","title":"How often do you use the product?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_a_few_times","label":"A few times a week","image_key":null},{"id":"opt_about_once_a","label":"About once a week","image_key":null},{"id":"opt_less_often","label":"Less often","image_key":null}]},{"id":"blk_software03","ref":"noticed","title":"Have you noticed what''s changed in this update?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_and_i","label":"Yes, and I''ve used the new parts","image_key":null},{"id":"opt_i_noticed_but","label":"I noticed, but haven''t tried them","image_key":null},{"id":"opt_i_haven_t","label":"I haven''t noticed anything new","image_key":null}],"allowOther":false},{"id":"blk_software04","ref":"impact","title":"Has the update made your work easier or harder?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Much harder","labelHigh":"Much easier"},{"id":"blk_software05","ref":"needs_explaining","title":"Was anything confusing, or in need of a better explanation?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_software06","ref":"why_not_tried","title":"What''s kept you from trying them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_don_t","label":"I don''t need them","image_key":null},{"id":"opt_i_m_not","label":"I''m not sure how they work","image_key":null},{"id":"opt_haven_t_had","label":"Haven''t had time yet","image_key":null},{"id":"opt_they_don_t","label":"They don''t look useful to me","image_key":null}],"allowOther":true},{"id":"blk_software07","ref":"where_hear","title":"Where would you expect to hear about new features?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_a_message_inside","label":"A message inside the app","image_key":null},{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_release_notes_or","label":"Release notes or a changelog","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_software08","ref":"problems","title":"Have you run into any bugs or problems since the update?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_software09","ref":"problem_detail","title":"What happened, and what were you trying to do at the time?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_software10","ref":"severity","title":"How much is it getting in your way?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_blocks_my","label":"It blocks my work","image_key":null},{"id":"opt_annoying_but_i","label":"Annoying, but I can work around it","image_key":null},{"id":"opt_minor","label":"Minor","image_key":null}],"allowOther":false},{"id":"blk_software11","ref":"problem_screenshot","title":"A screenshot or screen recording helps a lot, if you have one.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","video/*"],"maxFiles":3,"maxSizeMB":50},{"id":"blk_software12","ref":"missing","title":"Did anything you relied on change or disappear?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_software13","ref":"satisfaction","title":"Overall, how do you feel about this update?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_software14","ref":"follow_up_email","title":"Leave your email if we can follow up with you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_software01","ref":"end_thanks","title":"Thanks, this goes straight to the team 🛠️","bodyMd":"Bug reports are read first, and we''ll be in touch if you left your email.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_software01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"needs_explaining","target":"problems","targetKind":"block"},{"id":"rl_software02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"why_not_tried","target":"problems","targetKind":"block"},{"id":"rl_software03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"noticed"},"op":"eq","value":"opt_yes_and_i"}],"groups":[]},"from":"noticed","target":"impact","targetKind":"block","branch":"true"},{"id":"rl_software04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"noticed"},"op":"eq","value":"opt_i_noticed_but"}],"groups":[]},"from":"noticed","target":"why_not_tried","targetKind":"block","branch":"true"},{"id":"rl_software05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"noticed"},"op":"eq","value":"opt_i_haven_t"}],"groups":[]},"from":"noticed","target":"where_hear","targetKind":"block","branch":"true"},{"id":"rl_software06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"problems"},"op":"eq","value":false}],"groups":[]},"from":"problems","target":"missing","targetKind":"block","branch":"true"},{"id":"rl_software07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"problems"},"op":"eq","value":true}],"groups":[]},"from":"problems","target":"problem_detail","targetKind":"block","branch":"true"},{"id":"rl_software08","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"problem_screenshot","target":"satisfaction","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset