VALUES ('tpl_clientfeedbackform', 'client-feedback-form', 'Client feedback form', 'Form', 'Hear how the project really went, and route happy and unhappy clients differently.', 'A short debrief to send when a project wraps. The overall score decides the next question: a client who loved the work is asked for a quote you can publish, and one who didn''t is asked what went wrong and whether they want a call about it.', '["feedback","client feedback","project review","agency","testimonial","branching"]', 'MessagesSquare', 'text', 3, 10, '{"schemaVersion":9,"title":"Client feedback","description":"Hear how the project really went, and route happy and unhappy clients differently.","blocks":[{"id":"blk_clientfe00","ref":"welcome","title":"Thanks for working with us. Got two minutes to tell us how it went?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_clientfe01","ref":"project","title":"Which project are you reviewing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_clientfe02","ref":"overall","title":"Overall, how happy are you with the result?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_clientfe03","ref":"aspects","title":"How did we do on each of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_quality_of","label":"Quality of the work"},{"id":"opt_row_communication","label":"Communication"},{"id":"opt_row_hitting_deadlines","label":"Hitting deadlines"},{"id":"opt_row_value_for","label":"Value for money"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_great","label":"Great"}],"multiplePerRow":false},{"id":"blk_clientfe04","ref":"met_goals","title":"Did the project do what you hired us for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_fully","label":"Yes, fully","image_key":null},{"id":"opt_mostly","label":"Mostly","image_key":null},{"id":"opt_not_really","label":"Not really","image_key":null}],"allowOther":false},{"id":"blk_clientfe05","ref":"best_part","title":"What did we do especially well?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_clientfe06","ref":"quote_ok","title":"Could we quote what you just wrote on our website?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_clientfe07","ref":"what_went_wrong","title":"What fell short? The specifics help us most.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_clientfe08","ref":"call_back","title":"Would you like the project lead to call you about it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_clientfe09","ref":"recommend","title":"How likely are you to recommend us to a friend or colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_clientfe10","ref":"next_time","title":"Anything we should do differently on the next project?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_clientfe01","ref":"end_thanks","title":"Thank you, this really helps","bodyMd":"We read every answer, and the project lead will see yours this week.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_clientfe01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"quote_ok","target":"recommend","targetKind":"block"},{"id":"rl_clientfe02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"met_goals"},"op":"eq","value":"opt_yes_fully"}],"groups":[]},"from":"met_goals","target":"best_part","targetKind":"block","branch":"true"},{"id":"rl_clientfe03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"met_goals"},"op":"eq","value":"opt_mostly"}],"groups":[]},"from":"met_goals","target":"best_part","targetKind":"block","branch":"true"},{"id":"rl_clientfe04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"met_goals"},"op":"eq","value":"opt_not_really"}],"groups":[]},"from":"met_goals","target":"what_went_wrong","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":