VALUES ('tpl_musicsubmissionform', 'music-submission-form', 'Music submission form', 'Form', 'Collect tracks and artist details in one consistent format for review.', 'For playlists, venues, labels and events that are tired of links scattered across inboxes. Artists upload the track and describe it the same way every time, released tracks add a streaming link, upcoming ones give a release date, and anyone asking for a live slot describes their setup.', '["file upload","music submission","demo submission","artist submission","playlist submission","band booking"]', 'Music', 'scale', 4, 15, '{"schemaVersion":9,"title":"Music submission","description":"Collect tracks and artist details in one consistent format for review.","blocks":[{"id":"blk_musicsub00","ref":"welcome","title":"Thanks for sending us your music. This takes about five minutes, and every track gets listened to.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_musicsub01","ref":"artist_name","title":"What''s your artist or band name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_musicsub02","ref":"contact","title":"Who should we contact about this submission?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_musicsub03","ref":"based_in","title":"Where are you based?","description":"City and country is plenty.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_musicsub04","ref":"submitting_for","title":"What are you submitting for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_playlist_or_radio","label":"Playlist or radio consideration","image_key":null},{"id":"opt_a_live_booking","label":"A live booking","image_key":null},{"id":"opt_a_release_on","label":"A release on our label","image_key":null},{"id":"opt_a_feature_or","label":"A feature or review","image_key":null}],"allowOther":false},{"id":"blk_musicsub05","ref":"live_setup","title":"Tell us about your live show: how many people on stage, set length and anything you need technically.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_musicsub06","ref":"genre","title":"Which genre fits best?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_pop","label":"Pop","image_key":null},{"id":"opt_rock","label":"Rock","image_key":null},{"id":"opt_hip_hop_or","label":"Hip-hop or rap","image_key":null},{"id":"opt_r_b_or","label":"R&B or soul","image_key":null},{"id":"opt_electronic","label":"Electronic","image_key":null},{"id":"opt_folk_or_acoustic","label":"Folk or acoustic","image_key":null},{"id":"opt_jazz","label":"Jazz","image_key":null},{"id":"opt_classical","label":"Classical","image_key":null},{"id":"opt_metal","label":"Metal","image_key":null},{"id":"opt_country","label":"Country","image_key":null},{"id":"opt_world","label":"World","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_musicsub07","ref":"track_title","title":"What''s the track called?","description":"Sending more than one? List the titles in the order you upload them.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_musicsub08","ref":"track_file","title":"Upload the track","description":"MP3 or WAV. You can add up to three tracks, strongest first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["audio/*"],"maxFiles":3,"maxSizeMB":50},{"id":"blk_musicsub09","ref":"release_status","title":"Has your main track been released?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_it_s","label":"Yes, it''s out","image_key":null},{"id":"opt_it_s_coming","label":"It''s coming out soon","image_key":null},{"id":"opt_no_it_s","label":"No, it''s unreleased","image_key":null}],"allowOther":false},{"id":"blk_musicsub10","ref":"streaming_link","title":"Where can we listen to it online?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_musicsub11","ref":"release_date","title":"When does it come out?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_musicsub12","ref":"bio","title":"Tell us about yourself and the track in a few sentences.","description":"What it''s about, who you sound like and anything we should know.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_musicsub13","ref":"press_photo","title":"A press photo or artwork, if you have one","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*"],"maxFiles":2,"maxSizeMB":15},{"id":"blk_musicsub14","ref":"socials","title":"Your main social or website link","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_musicsub15","ref":"rights","title":"Rights to the music","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I wrote this music or have permission from everyone who owns it, including any samples, and I agree that you may listen to and review it. Nothing is published or broadcast without a separate agreement.","allowDecline":false,"agreeLabel":"I confirm","declineLabel":"I do not agree"}],"endings":[{"id":"end_musicsub01","ref":"end_thanks","title":"Got it, thank you 🎧","bodyMd":"We listen to every submission. If it''s a fit, we''ll email you at the address you gave.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_musicsub01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"streaming_link","target":"bio","targetKind":"block"},{"id":"rl_musicsub02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"submitting_for"},"op":"eq","value":"opt_a_live_booking"}],"groups":[]},"from":"submitting_for","target":"live_setup","targetKind":"block","branch":"true"},{"id":"rl_musicsub03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"submitting_for"},"op":"eq","value":"opt_playlist_or_radio"}],"groups":[]},"from":"submitting_for","target":"genre","targetKind":"block","branch":"true"},{"id":"rl_musicsub04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"submitting_for"},"op":"eq","value":"opt_a_release_on"}],"groups":[]},"from":"submitting_for","target":"genre","targetKind":"block","branch":"true"},{"id":"rl_musicsub05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"submitting_for"},"op":"eq","value":"opt_a_feature_or"}],"groups":[]},"from":"submitting_for","target":"genre","targetKind":"block","branch":"true"},{"id":"rl_musicsub06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"release_status"},"op":"eq","value":"opt_yes_it_s"}],"groups":[]},"from":"release_status","target":"streaming_link","targetKind":"block","branch":"true"},{"id":"rl_musicsub07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"release_status"},"op":"eq","value":"opt_it_s_coming"}],"groups":[]},"from":"release_status","target":"release_date","targetKind":"block","branch":"true"},{"id":"rl_musicsub08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"release_status"},"op":"eq","value":"opt_no_it_s"}],"groups":[]},"from":"release_status","target":"bio","targetKind":"block","branch":"true"},{"id":"rl_musicsub09","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"release_date","target":"press_photo","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
