VALUES ('tpl_photocontestentryform', 'photo-contest-entry-form', 'Photo contest entry form', 'Form', 'Take contest entries with everything the judges need, and screen out ineligible ones.', 'Collects the photo along with what judges actually look at: the category, a title, where and when it was taken and the story behind it. Entrants under 18 give a parent or guardian''s details, and anyone who has composited their image is told politely before they upload that it isn''t eligible.', '["file upload","photo contest","photography competition","contest entry","photo submission","image upload"]', 'Camera', 'scale', 4, 13, '{"schemaVersion":9,"title":"Photo contest entry","description":"Take contest entries with everything the judges need, and screen out ineligible ones.","blocks":[{"id":"blk_photocon00","ref":"welcome","title":"Welcome to the photo contest. Entering takes about three minutes. Have your photo ready.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_photocon01","ref":"entrant","title":"Who''s entering?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_photocon02","ref":"age_group","title":"How old are you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_18","label":"Under 18","image_key":null},{"id":"opt_18_or_over","label":"18 or over","image_key":null}],"allowOther":false},{"id":"blk_photocon03","ref":"guardian_name","title":"What''s the name of your parent or guardian?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_photocon04","ref":"guardian_email","title":"And their email, so we can confirm they''re happy for you to enter?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_photocon05","ref":"category","title":"Which category are you entering?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_landscape","label":"Landscape","image_key":null},{"id":"opt_people_and_portraits","label":"People and portraits","image_key":null},{"id":"opt_street","label":"Street","image_key":null},{"id":"opt_wildlife_and_nature","label":"Wildlife and nature","image_key":null},{"id":"opt_black_and_white","label":"Black and white","image_key":null}],"allowOther":false},{"id":"blk_photocon06","ref":"editing","title":"How much has the photo been edited?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_not_at_all","label":"Not at all","image_key":null},{"id":"opt_basic_adjustments_like","label":"Basic adjustments like exposure, crop and colour","image_key":null},{"id":"opt_things_added_removed","label":"Things added, removed or combined from several photos","image_key":null}],"allowOther":false},{"id":"blk_photocon07","ref":"photo","title":"Upload your photo","description":"A JPEG or PNG at full resolution, with no watermark or name on it.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/jpeg","image/png"],"maxFiles":1,"maxSizeMB":25},{"id":"blk_photocon08","ref":"photo_title","title":"What''s the photo called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":100},{"id":"blk_photocon09","ref":"taken_on","title":"When did you take it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_photocon10","ref":"taken_at","title":"Where was it taken?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_photocon11","ref":"story","title":"What''s the story behind the shot?","description":"A few sentences for the judges.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_photocon12","ref":"camera","title":"What did you shoot it on?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":100,"placeholder":"Camera and lens, or phone"},{"id":"blk_photocon13","ref":"entry_terms","title":"Entry terms","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I took this photo myself, I own the rights to it, and anyone recognisable in it is happy for it to be entered. I agree that the organisers may show the photo, credited to me, in connection with this contest. I keep the copyright.","allowDecline":false,"agreeLabel":"I agree and want to enter","declineLabel":"I do not agree"}],"endings":[{"id":"end_photocon01","ref":"end_thanks","title":"Your entry is in 📸","bodyMd":"Good luck. We''ll email you once the judges have made their decision.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_photocon02","ref":"end_ineligible","title":"This one can''t be entered","bodyMd":"The contest only accepts photos without added, removed or combined elements. You''re welcome to enter again with a different shot.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_photocon01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"age_group"},"op":"eq","value":"opt_18_or_over"}],"groups":[]},"from":"age_group","target":"category","targetKind":"block","branch":"true"},{"id":"rl_photocon02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"age_group"},"op":"eq","value":"opt_under_18"}],"groups":[]},"from":"age_group","target":"guardian_name","targetKind":"block","branch":"true"},{"id":"rl_photocon03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"editing"},"op":"eq","value":"opt_things_added_removed"}],"groups":[]},"from":"editing","target":"end_ineligible","targetKind":"ending","branch":"true"},{"id":"rl_photocon04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"guardian_email","target":"editing","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#d9f2e6","surface":"#ffffff","text":"#12342a","accent":"#0f766e","accentText":"#f5fffb","botBubble":"#ffffff","userBubble":"#0f766e","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"plus","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
