INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_projectsubmissionform', 'project-submission-form', 'Project submission form', 'Form', 'Take proposals and finished projects in one consistent format for review.', 'Works for course projects, grant rounds, hackathons and internal pitches. Solo and team submissions are handled separately, proposals are asked for a start date and budget, and completed work is asked what it achieved, so reviewers get what they need for each without one long form.', '["file upload","project submission","proposal form","assignment submission","hackathon submission"]', 'FileUp', 'scale', 4, 13, '{"schemaVersion":9,"title":"Project submission","description":"Take proposals and finished projects in one consistent format for review.","blocks":[{"id":"blk_projects00","ref":"welcome","title":"Ready to submit your project? This takes about five minutes. Have your files and links to hand.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_projects01","ref":"submitter","title":"Who''s submitting?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_projects02","ref":"project_title","title":"What''s the project called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_projects03","ref":"is_team","title":"Is this a team project?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, a team","noLabel":"No, just me"},{"id":"blk_projects04","ref":"team_members","title":"Who else is on the team, and what did each person do?","description":"One person per line, with their email.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_projects05","ref":"summary","title":"Summarise the project in a few sentences.","description":"What problem it tackles, what you did or plan to do, and who it''s for.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_projects06","ref":"submission_type","title":"What are you submitting?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_proposal_for","label":"A proposal for new work","image_key":null},{"id":"opt_finished_work_for","label":"Finished work for review","image_key":null}],"allowOther":false},{"id":"blk_projects07","ref":"start_date","title":"When would you want to start?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_projects08","ref":"budget","title":"What budget would you need, if any?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false,"currency":"USD"},{"id":"blk_projects09","ref":"results","title":"What did the project achieve, and what would you do differently?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_projects10","ref":"files","title":"Upload your project files","description":"Documents, slides, images or a zip. Up to five files.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["application/pdf","application/zip","image/*","application/vnd.openxmlformats-officedocument.wordprocessingml.document","application/vnd.openxmlformats-officedocument.presentationml.presentation"],"maxFiles":5,"maxSizeMB":25},{"id":"blk_projects11","ref":"project_link","title":"Is there a link we should see, like a demo, repository or video?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_projects12","ref":"anything_else","title":"Anything else reviewers should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_projects13","ref":"originality","title":"Your confirmation","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"This submission is my own work, or my team''s, and anything taken from others is credited. I understand it will be shared with the people reviewing it.","allowDecline":false,"agreeLabel":"I confirm","declineLabel":"I do not agree"}],"endings":[{"id":"end_projects01","ref":"end_thanks","title":"Submitted, thank you 🚀","bodyMd":"Your project is with the reviewers. We''ll email you about next steps.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_projects01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"budget","target":"files","targetKind":"block"},{"id":"rl_projects02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"is_team"},"op":"eq","value":false}],"groups":[]},"from":"is_team","target":"summary","targetKind":"block","branch":"true"},{"id":"rl_projects03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"is_team"},"op":"eq","value":true}],"groups":[]},"from":"is_team","target":"team_members","targetKind":"block","branch":"true"},{"id":"rl_projects04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"submission_type"},"op":"eq","value":"opt_a_proposal_for"}],"groups":[]},"from":"submission_type","target":"start_date","targetKind":"block","branch":"true"},{"id":"rl_projects05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"submission_type"},"op":"eq","value":"opt_finished_work_for"}],"groups":[]},"from":"submission_type","target":"results","targetKind":"block","branch":"true"},{"id":"rl_projects06","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"team_members","target":"submission_type","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friend