VALUES ('tpl_artsubmissionform', 'art-submission-form', 'Art submission form', 'Form', 'Receive artwork and the context a curator or editor needs to review it.', 'An open call form for galleries, exhibitions and publications. Artists upload images of the work and give the details a curator needs to picture it in the room: medium, size, year and an artist statement. The asking price is only asked when the work is for sale, and three-dimensional work gets a question about handling.', '["file upload","art submission","open call","artist application","exhibition submission","artwork upload"]', 'Palette', 'scale', 4, 13, '{"schemaVersion":9,"title":"Art submission","description":"Receive artwork and the context a curator or editor needs to review it.","blocks":[{"id":"blk_artsubmi00","ref":"welcome","title":"Thanks for submitting your work. This takes about five minutes. Have images of the piece ready.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_artsubmi01","ref":"artist","title":"Who''s the artist?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_artsubmi02","ref":"portfolio","title":"Your website or online portfolio, if you have one","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_artsubmi03","ref":"work_title","title":"What''s the title of the work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_artsubmi04","ref":"medium","title":"What medium is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_painting","label":"Painting","image_key":null},{"id":"opt_drawing","label":"Drawing","image_key":null},{"id":"opt_printmaking","label":"Printmaking","image_key":null},{"id":"opt_photography","label":"Photography","image_key":null},{"id":"opt_digital","label":"Digital","image_key":null},{"id":"opt_mixed_media","label":"Mixed media","image_key":null},{"id":"opt_textile_or_fibre","label":"Textile or fibre","image_key":null},{"id":"opt_sculpture","label":"Sculpture","image_key":null},{"id":"opt_ceramics","label":"Ceramics","image_key":null},{"id":"opt_installation","label":"Installation","image_key":null}]},{"id":"blk_artsubmi05","ref":"handling","title":"Anything we should know about installing or handling it?","description":"Weight, how it stands or hangs, power, or anything fragile.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_artsubmi06","ref":"dimensions","title":"What are its dimensions?","description":"For digital work, give the pixel size or the size you''d print it.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80,"placeholder":"Height x width x depth, in cm or inches"},{"id":"blk_artsubmi07","ref":"year","title":"What year was it made?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1900,"max":2100,"integerOnly":true},{"id":"blk_artsubmi08","ref":"images","title":"Upload images of the work","description":"The full piece first, then details or other angles. JPEG or PNG.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/jpeg","image/png"],"maxFiles":5,"maxSizeMB":20},{"id":"blk_artsubmi09","ref":"statement","title":"Tell us about this piece.","description":"What it''s about and how you made it, in your own words.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_artsubmi10","ref":"for_sale","title":"Is the work for sale?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_artsubmi11","ref":"price","title":"What''s the asking price?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false,"currency":"USD"},{"id":"blk_artsubmi12","ref":"bio","title":"A short bio we could print alongside the work","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_artsubmi13","ref":"image_permission","title":"Use of images","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I made this work and own the rights to it. If it is selected, the organisers may reproduce these images, credited to me, to present and promote the show or publication. I keep the copyright.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_artsubmi01","ref":"end_thanks","title":"Your work has been submitted 🎨","bodyMd":"Thank you for sharing it. We''ll email you once the selection has been made.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_artsubmi01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"medium"},"op":"eq","value":"opt_sculpture"}],"groups":[]},"from":"medium","target":"handling","targetKind":"block","branch":"true"},{"id":"rl_artsubmi02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"medium"},"op":"eq","value":"opt_ceramics"}],"groups":[]},"from":"medium","target":"handling","targetKind":"block","branch":"true"},{"id":