INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_modelapplicationform', 'model-application-form', 'Model application form', 'Form', 'Collect photos, experience and availability from aspiring and working models.', 'Built for agencies and casting teams who are tired of applications arriving as DMs with one blurry photo. It asks for the kind of work first, then recent unretouched shots and a portfolio. Applicants under 18 are routed to a parent or guardian contact before they continue, and people with no experience are asked what draws them in rather than for credits they do not have.', '["job application","model application","casting call","modelling agency","talent application","branching"]', 'Camera', 'choice', 4, 14, '{"schemaVersion":9,"title":"Model application","description":"Collect photos, experience and availability from aspiring and working models.","blocks":[{"id":"blk_modelapp00","ref":"welcome","title":"Thanks for your interest in working with us. This takes about four minutes, and it helps to have two or three recent photos on your phone.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_modelapp01","ref":"contact","title":"First, who are we talking to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_modelapp02","ref":"age_group","title":"How old are you?","description":"We ask because anyone under 18 needs a parent or guardian involved.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_16","label":"Under 16","image_key":null},{"id":"opt_16_or_17","label":"16 or 17","image_key":null},{"id":"opt_18_to_24","label":"18 to 24","image_key":null},{"id":"opt_25_or_older","label":"25 or older","image_key":null}],"allowOther":false},{"id":"blk_modelapp03","ref":"guardian","title":"Please add a parent or guardian we can contact","description":"We only discuss work with minors when a parent or guardian is part of the conversation.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_modelapp04","ref":"city","title":"Which city are you based in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_modelapp05","ref":"work_types","title":"What kind of modelling are you interested in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_editorial_and_fashion","label":"Editorial and fashion","image_key":null},{"id":"opt_runway","label":"Runway","image_key":null},{"id":"opt_commercial_and_advertising","label":"Commercial and advertising","image_key":null},{"id":"opt_fitness_and_sportswear","label":"Fitness and sportswear","image_key":null},{"id":"opt_parts_hands_feet","label":"Parts (hands, feet, hair)","image_key":null},{"id":"opt_promotional_and_events","label":"Promotional and events","image_key":null},{"id":"opt_content_creation_for","label":"Content creation for brands","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_modelapp06","ref":"experience","title":"How much modelling have you done so far?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_none_yet","label":"None yet","image_key":null},{"id":"opt_test_shoots_or","label":"Test shoots or a few small jobs","image_key":null},{"id":"opt_regular_paid_work","label":"Regular paid work","image_key":null},{"id":"opt_signed_with_an","label":"Signed with an agency now or before","image_key":null}],"allowOther":false},{"id":"blk_modelapp07","ref":"why_model","title":"What draws you to modelling, and what would you like to be doing a year from now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_modelapp08","ref":"credits","title":"Tell us about two or three jobs you are proudest of","description":"The client, the kind of shoot or show, and roughly when.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_modelapp09","ref":"portfolio","title":"Link to your portfolio, comp card or modelling Instagram","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_modelapp10","ref":"photos","title":"Upload two to four recent photos","description":"Natural light, little or no makeup, no filters. One headshot, one full length and one profile work best.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/jpeg","image/png","image/heic"],"maxFiles":4,"maxSizeMB":10},{"id":"blk_modelapp11","ref":"height","title":"How tall are you, in centimetres?","description":"Some briefs have height requirements, so this helps us match you to the right ones.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":100,"max":230,"integerOnly":true},{"id":"blk_modelapp12","ref":"availability","title":"When are you usually free to work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_weekdays","label":"Weekdays"},{"id":"opt_row_weekends","label":"Weekends"},{"id":"opt_row_evenings","label":"Evenings"}],"columns":[{"id":"opt_col_usually_free","label":"Usually free"},{"id":"opt_col_sometimes","label":"Sometimes"},{"id":"opt_col_rarely","label":"Rarely"}],"multiplePerRow":false},{"id":"blk_modelapp13","ref":"travel","title":"Could you travel for a job outside your city?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_modelapp14","ref":"consent","title":"Your photos and details","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I confirm the photos are of me and that I can share them. I understand they will only be used to review this application and will not be published without my permission.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_modelapp01","ref":"end_thanks","title":"Application received 📸","bodyMd":"Our team looks at every application. If your look fits a current brief, we will get in touch to arrange a meeting or test shoot. Sending an application does not mean you are booked or represented.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_modelapp01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"why_model","target":"photos","targetKind":"block"},{"id":"rl_modelapp02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"age_group"},"op":"eq","value":"opt_under_16"}],"groups":[]},"from":"age_group","target":"guardian","targetKind":"block","branch":"true"},{"id":"rl_modelapp03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"age_group"},"op":"eq","value":"opt_16_or_17"}],"groups":[]},"from":"age_group","target":"guardian","targetKind":"block","branch":"true"},{"id":"rl_modelapp04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"age_group"},"op":"eq","value":"opt_18_to_24"}],"groups":[]},"from":"age_group","target":"city","targetKind":"block","branch":"true"},{"id":"rl_modelapp05","action_kind":"goto","when":{"op":"and","conditions":[{"