VALUES ('tpl_jobapplication', 'job-application', 'Job application form', 'Form', 'Screen candidates, and ask each discipline its own questions.', 'Everything a first-pass review needs and nothing it doesn''t. The role someone picks decides what they are asked next: engineers get a code sample question, designers a portfolio walkthrough, sales their deal sizes. One form serves five hiring managers, and anyone without the right to work where the role is based is told straight away rather than after an interview.', '["job application","hiring","recruiting","candidate screening","branching"]', 'Briefcase', 'choice', 4, 24, '{"schemaVersion":9,"title":"Job application","description":"Screen candidates, and ask each discipline its own questions.","blocks":[{"id":"blk_jobappli00","ref":"welcome","title":"Glad you''re interested in joining us. This takes a few minutes, and you can attach your CV near the end.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_jobappli01","ref":"contact","title":"Let''s start with your details","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_jobappli02","ref":"location","title":"Where are you based?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":100},{"id":"blk_jobappli03","ref":"right_to_work","title":"Do you have the right to work where this role is based?","description":"We can''t sponsor visas for this role, so this saves us both time.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_jobappli04","ref":"role","title":"Which team are you applying to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_engineering","label":"Engineering","image_key":null},{"id":"opt_design","label":"Design","image_key":null},{"id":"opt_product","label":"Product","image_key":null},{"id":"opt_sales","label":"Sales","image_key":null},{"id":"opt_operations","label":"Operations","image_key":null}],"allowOther":false},{"id":"blk_jobappli05","ref":"eng_stack","title":"What do you work in most?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_typescript_javascript","label":"TypeScript / JavaScript","image_key":null},{"id":"opt_python","label":"Python","image_key":null},{"id":"opt_go","label":"Go","image_key":null},{"id":"opt_rust","label":"Rust","image_key":null},{"id":"opt_java_or_kotlin","label":"Java or Kotlin","image_key":null},{"id":"opt_swift","label":"Swift","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":true},{"id":"blk_jobappli06","ref":"eng_code_sample","title":"A link to something you''ve built or shipped","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_jobappli07","ref":"eng_debugged","title":"What''s the hardest bug you''ve tracked down, and how did you find it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_jobappli08","ref":"design_portfolio","title":"Link to your portfolio","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_jobappli09","ref":"design_focus","title":"Where are you strongest?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_product_and_interaction","label":"Product and interaction","image_key":null},{"id":"opt_visual_and_brand","label":"Visual and brand","image_key"