INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_datacaptureform', 'data-capture-form', 'Data capture form', 'Form', 'One tidy contact record per person, whether they are new or updating details you hold.', 'Made for keeping a contact list you can trust, not just catching a message. New contacts give a full record in fixed formats, while existing contacts say which email you had and what changed, so you can merge instead of duplicating. A phone number is asked only of people who prefer calls.', '["lead generation","data capture","contact details form","update your details","customer record","CRM data","branching"]', 'ClipboardList', 'text', 4, 13, '{"schemaVersion":9,"title":"Contact data capture","description":"One tidy contact record per person, whether they are new or updating details you hold.","blocks":[{"id":"blk_datacapt00","ref":"welcome","title":"Hi. This takes about two minutes and keeps the details we hold for you accurate.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_datacapt01","ref":"record_type","title":"Are you new to us, or updating details we already have?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_m_new","label":"I''m new here","image_key":null},{"id":"opt_i_m_updating","label":"I''m updating my details","image_key":null}],"allowOther":false},{"id":"blk_datacapt02","ref":"previous_email","title":"Which email address did we have for you before?","description":"We use it to find your existing record, so nothing gets duplicated.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_datacapt03","ref":"what_changed","title":"What has changed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_my_name","label":"My name","image_key":null},{"id":"opt_my_email","label":"My email","image_key":null},{"id":"opt_my_job_or","label":"My job or organisation","image_key":null},{"id":"opt_my_address","label":"My address","image_key":null},{"id":"opt_how_i_d","label":"How I''d like to be contacted","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_datacapt04","ref":"contact","title":"What''s your name and current email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_datacapt05","ref":"organisation","title":"Which organisation are you with, if any?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_datacapt06","ref":"job_title","title":"What''s your job title?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_datacapt07","ref":"sector","title":"Which sector do you work in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_retail_and_e","label":"Retail and e-commerce","image_key":null},{"id":"opt_professional_services","label":"Professional services","image_key":null},{"id":"opt_technology","label":"Technology","image_key":null},{"id":"opt_health_and_care","label":"Health and care","image_key":null},{"id":"opt_education","label":"Education","image_key":null},{"id":"opt_manufacturing","label":"Manufacturing","image_key":null},{"id":"opt_charity_or_public","label":"Charity or public sector","image_key":null},{"id":"opt_other","label":"Other","image_key":null}]},{"id":"blk_datacapt08","ref":"org_size","title":"How many people work there?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_2_10","label":"2–10","image_key":null},{"id":"opt_11_50","label":"11–50","image_key":null},{"id":"opt_51_250","label":"51–250","image_key":null},{"id":"opt_more_than_250","label":"More than 250","image_key":null}],"allowOther":false},{"id":"blk_datacapt09","ref":"address","title":"What''s your postal address?","description":"Needed if you''d like to hear from us by post. Otherwise you can leave it out.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","state","postal","country"],"location":"off"},{"id":"blk_datacapt10","ref":"topics","title":"Which of these are relevant to you?","description":"Swap these for the lists or areas your team actually keeps.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_product_updates","label":"Product updates","image_key":null},{"id":"opt_events","label":"Events","image_key":null},{"id":"opt_guides_and_research","label":"Guides and research","image_key":null},{"id":"opt_offers","label":"Offers","image_key":null}],"minSelections":0,"maxSelections":4,"allowOther":false},{"id":"blk_datacapt11","ref":"channel","title":"How do you prefer to be contacted?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_phone","label":"Phone","image_key":null},{"id":"opt_post","label":"Post","image_key":null}],"allowOther":false},{"id":"blk_datacapt12","ref":"phone","title":"Which number should we use?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_datacapt13","ref":"consent","title":"Keeping your details","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I agree that you can store these details to keep my contact record up to date. You will only use them for the purposes I picked, and I can ask you to correct or delete them at any time.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_datacapt01","ref":"end_thanks","title":"Thanks, your details are saved","bodyMd":"We''ll use them only in the ways you chose. If anything changes again, just fill this in once more.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_datacapt01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"record_type"},"op":"eq","value":"opt_i_m_new"}],"groups":[]},"from":"record_type","target":"contact","targetKind":"block","branch":"true"},{"id":"rl_datacapt02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"record_type"},"op":"eq","value":"opt_i_m_updating"}],"groups":[]},"from":"record_type","target":"previous_email","targetKind":"block","branch":"true"},{"id":"rl_datacapt03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"channel"},"op":"eq","value":"opt_email"}],"groups":[]},"from":"channel","target":"consent","targetKind":"block","branch":"true"},{"id":"rl_datacapt04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"channel"},"op":"eq","value":"opt_post"}],"groups":[]},"from":"channel","target":"consent","targetKind":"block","branch":"true"},{"id":"rl_datacapt05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"channel"},"op":"eq","value":"opt_phone"}],"groups":[]},"from":"channel","target":"phone","targetKind":"block","branch":"true"},{"id":"rl_datacapt06","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"what_changed","target":"organisation","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
