VALUES ('tpl_hotelsalesleadform', 'hotel-sales-lead-form', 'Hotel sales lead form', 'Form', 'Group stays, meetings and weddings, each asked the details that decide availability.', 'Built for a hotel sales team handling group business. A group stay goes straight to room counts, while meetings and weddings are asked about headcount, layout and event space first. Guests who say they are ready to book land on their own ending, so they can be called before the rest.', '["lead generation","hotel sales","group booking enquiry","event venue enquiry","hospitality","room block","branching"]', 'Hotel', 'text', 5, 16, '{"schemaVersion":9,"title":"Hotel group and event enquiry","description":"Group stays, meetings and weddings, each asked the details that decide availability.","blocks":[{"id":"blk_hotelsal00","ref":"welcome","title":"Planning a group stay or an event with us? Tell us what you have in mind and we''ll check availability.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_hotelsal01","ref":"arrival","title":"What is your arrival date, or the date the event starts?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_hotelsal02","ref":"nights","title":"How many nights?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":60,"integerOnly":true},{"id":"blk_hotelsal03","ref":"flexible","title":"Could your dates move a little if it gets you a better rate or room?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, we''re flexible","noLabel":"No, the dates are fixed"},{"id":"blk_hotelsal04","ref":"enquiry_type","title":"What are you planning?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_group_stay","label":"A group stay","image_key":null},{"id":"opt_a_meeting_or","label":"A meeting or conference","image_key":null},{"id":"opt_a_wedding_or","label":"A wedding or celebration","image_key":null}],"allowOther":false},{"id":"blk_hotelsal05","ref":"guests","title":"Roughly how many people will attend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":5000,"integerOnly":true},{"id":"blk_hotelsal06","ref":"layout","title":"How should the main room be set up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_theatre_rows_of","label":"Theatre, rows of chairs","image_key":null},{"id":"opt_classroom_with_tables","label":"Classroom, with tables","image_key":null},{"id":"opt_boardroom_one_table","label":"Boardroom, one table","image_key":null},{"id":"opt_banquet_round_tables","label":"Banquet, round tables","image_key":null},{"id":"opt_standing_reception","label":"Standing reception","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}],"allowOther":false},{"id":"blk_hotelsal07","ref":"event_needs","title":"What else will the event need?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_breakout_rooms","label":"Breakout rooms","image_key":null},{"id":"opt_projector_and_screen","label":"Projector and screen","image_key":null},{"id":"opt_microphones_and_sound","label":"Microphones and sound","image_key":null},{"id":"opt_coffee_breaks","label":"Coffee breaks","image_key":null},{"id":"opt_lunch_or_dinner","label":"Lunch or dinner","image_key":null},{"id":"opt_a_drinks_reception","label":"A drinks reception","image_key":null},{"id":"opt_accessible_access_througho","label":"Accessible access throughout","image_key":null}],"minSelections":0,"maxSelections":7,"allowOther":false},{"id":"blk_hotelsal08","ref":"needs_rooms","title":"Will any guests need bedrooms?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_hotelsal09","ref":"rooms","title":"How many rooms per night, roughly?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":1000,"integerOnly":true},{"id":"blk_hotelsal10","ref":"room_mix","title":"Which room types do you need?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_single","label":"Single","image_key":null},{"id":"opt_double","label":"Double","image_key":null},{"id":"opt_twin","label":"Twin","image_key":null},{"id":"opt_suite","label":"Suite","image_key":null},{"id":"opt_accessible_room","label":"Accessible room","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_hotelsal11","ref":"priorities","title":"Put these in order of what matters most to you.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_price","label":"Price"},{"id":"opt_item_location","label":"Location"},{"id":"opt_item_room_quality","label":"Room quality"},{"id":"opt_item_event_space","label":"Event space"},{"id":"opt_item_food_and","label":"Food and drink"},{"id":"opt_item_flexible_cancellation","label":"Flexible cancellation"}]},{"id":"blk_hotelsal12","ref":"budget","title":"Do you have a budget in mind? A rough figure is fine.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_hotelsal13","ref":"requests","title":"Anything else we should know, such as dietary needs, parking or dates you must avoid?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_hotelsal14","ref":"contact","title":"Who should our sales team contact?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_hotelsal15","ref":"organisation","title":"Is this for a company or organisation? If so, which one?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_hotelsal16","ref":"stage","title":"Where are you in your planning?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_ready_to_book","label":"Ready to book if the proposal fits","image_key":null},{"id":"opt_comparing_a_few","label":"Comparing a few venues","image_key":null},{"id":"opt_early_research","label":"Early research","image_key":null}],"allowOther":false}],"endings":[{"id":"end_hotelsal01","ref":"end_thanks","title":"Thanks, your enquiry is with our sales team","bodyMd":"We''ll check availability for your dates and email you a proposal within two working days.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_hotelsal02","ref":"end_ready","title":"We''ll move quickly on this 🛎️","bodyMd":"A member of our sales team will call you within one working day with availability and a proposal.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_hotelsal01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"enquiry_type"},"op":"eq","value":"opt_a_group_stay"}],"groups":[]},"from":"enquiry_type","target":"rooms","targetKind":"block","branch":"true"},{"id":"rl_hotelsal02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"enquiry_type"},"op":"eq","value":"opt_a_meeting_or"}],"groups":[]},"from":"enquiry_type","target":"guests","targetKind":"block","branch":"true"},{"id":"rl_hotelsal03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"enquiry_type"},"op":"eq","value":"opt_a_wedding_or"}],"groups":[]},"from":"enquiry_type","target":"guests","targetKind":"block","branch":"true"},{"id":"rl_hotelsal04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"needs_rooms"},"op":"eq","value":true}],"groups":[]},"from":"needs_rooms","target":"rooms","targetKind":"block","branch":"true"},{"id":"rl_hotelsal05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"needs_rooms"},"op":"eq","value":false}],"groups":[]},"from":"needs_rooms","target":"priorities","targetKind":"block","branch":"true"},{"id":"rl_hotelsal06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"stage"},"op":"eq","value":"opt_ready_to_book"}],"groups":[]},"from":"stage","target":"end_ready","targetKind":"ending","branch":"true"},{"id":"rl_hotelsal07","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"room_mix","target":"budget","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
