VALUES ('tpl_prospectiveclientform', 'prospective-client-form', 'Prospective client form', 'Form', 'Understand a potential client''s need, history and timing before you talk.', 'Written for consultants, coaches and small agencies who want the first conversation to be useful. People who have tried to fix the problem before are asked what happened, and anyone who would rather not talk on the phone gets a reply by email instead of a call request.', '["lead generation","prospective client","client inquiry","discovery call","consultant","new client","branching"]', 'Handshake', 'text', 4, 14, '{"schemaVersion":9,"title":"Prospective client","description":"Understand a potential client''s need, history and timing before you talk.","blocks":[{"id":"blk_prospect00","ref":"welcome","title":"Thanks for thinking of us. A few questions now means our first conversation can get straight to the useful part.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_prospect01","ref":"contact","title":"Let''s start with your name and email.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_prospect02","ref":"company","title":"Which company or project is this for?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_prospect03","ref":"help_with","title":"What would you like help with?","description":"A few sentences in your own words is perfect.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_prospect04","ref":"tried_before","title":"Have you tried to tackle this before?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_no_this_is","label":"No, this is new","image_key":null},{"id":"opt_yes_we_tried","label":"Yes, we tried it ourselves","image_key":null},{"id":"opt_yes_with_another","label":"Yes, with another provider","image_key":null}],"allowOther":false},{"id":"blk_prospect05","ref":"what_happened","title":"What happened, and what is still not working?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_prospect06","ref":"success","title":"If this goes well, what will be different for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_prospect07","ref":"urgency","title":"How pressing is this right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Nice to have","labelHigh":"Urgent"},{"id":"blk_prospect08","ref":"start","title":"When would you like to start?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_as_soon_as","label":"As soon as possible","image_key":null},{"id":"opt_within_the_next","label":"Within the next month","image_key":null},{"id":"opt_in_two_to","label":"In two to three months","image_key":null},{"id":"opt_just_exploring_for","label":"Just exploring for now","image_key":null}],"allowOther":false},{"id":"blk_prospect09","ref":"budget","title":"Where are you with budget?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_budget_is","label":"A budget is approved","image_key":null},{"id":"opt_i_have_a","label":"I have a rough figure in mind","image_key":null},{"id":"opt_not_decided_yet","label":"Not decided yet","image_key":null}],"allowOther":false},{"id":"blk_prospect10","ref":"deciders","title":"Who else will be involved in choosing someone?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_me_and_a","label":"Me and a partner or colleague","image_key":null},{"id":"opt_a_team_or","label":"A team or board","image_key":null}],"allowOther":false},{"id":"blk_prospect11","ref":"source","title":"How did you find us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_a_referral","label":"A referral","image_key":null},{"id":"opt_search_engine","label":"Search engine","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_an_article_or","label":"An article or podcast","image_key":null},{"id":"opt_other","label":"Other","image_key":null}]},{"id":"blk_prospect12","ref":"call","title":"Would you like a short call to talk it through?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, let''s talk","noLabel":"Email is better for me"},{"id":"blk_prospect13","ref":"phone","title":"What''s the best number to reach you on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_prospect14","ref":"best_time","title":"When are you usually free for a call?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_mornings","label":"Mornings","image_key":null},{"id":"opt_afternoons","label":"Afternoons","image_key":null},{"id":"opt_early_evenings","label":"Early evenings","image_key":null}],"minSelections":0,"maxSelections":3,"allowOther":false}],"endings":[{"id":"end_prospect01","ref":"end_thanks","title":"Thanks, talk soon","bodyMd":"We''ll call you within two working days, at one of the times you picked if you gave any. Your answers will be in front of us when we do.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_prospect02","ref":"end_email","title":"Thanks, we''ll reply by email ✉️","bodyMd":"We''ll read your answers properly and write back within two working days, including whether we think we''re the right fit.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_prospect01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"tried_before"},"op":"eq","value":"opt_no_this_is"}],"groups":[]},"from":"tried_before","target":"success","targetKind":"block","branch":"true"},{"id":"rl_prospect02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"tried_before"},"op":"eq","value":"opt_yes_we_tried"}],"groups":[]},"from":"tried_before","target":"what_happened","targetKind":"block","branch":"true"},{"id":"rl_prospect03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"tried_before"},"op":"eq","value":"opt_yes_with_another"}],"groups":[]},"from":"tried_before","target":"what_happened","targetKind":"block","branch":"true"},{"id":"rl_prospect04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"call"},"op":"eq","value":false}],"groups":[]},"from":"call","target":"end_email","targetKind":"ending","branch":"true"},{"id":"rl_prospect05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"call"},"op":"eq","value":true}],"groups":[]},"from":"call","target":"phone","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f3e6ff","surface":"#ffffff","text":"#2b1638","accent":"#9333ea","accentText":"#fdf9ff","botBubble":"#ffffff","userBubble":"#9333ea","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"confetti","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
