VALUES ('tpl_websitedesignquoteform', 'website-design-quote-form', 'Website design quote form', 'Form', 'Gather the pages, features and content a web design quote depends on.', 'Asks the questions that actually move a website price. A redesign is asked for the current site and what is wrong with it, an online shop is asked how many products it will sell, and everyone is asked about pages, features and whether the content is ready, which is where most projects slip.', '["lead generation","website design quote","web design inquiry","website project brief","web agency","freelance web designer","branching"]', 'Laptop', 'text', 5, 17, '{"schemaVersion":9,"title":"Website design quote","description":"Gather the pages, features and content a web design quote depends on.","blocks":[{"id":"blk_websited00","ref":"welcome","title":"Thinking about a new website? Tell us about the project and we''ll come back with a proposal.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_websited01","ref":"contact","title":"Who are we putting the quote together for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_websited02","ref":"business","title":"Tell us about your business in a sentence or two.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_websited03","ref":"project_type","title":"What kind of project is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_brand_new","label":"A brand new website","image_key":null},{"id":"opt_a_redesign_of","label":"A redesign of our current site","image_key":null},{"id":"opt_an_online_shop","label":"An online shop","image_key":null}],"allowOther":false},{"id":"blk_websited04","ref":"current_url","title":"What''s the address of your current site?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_websited05","ref":"whats_wrong","title":"What''s not working about it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_it_looks_dated","label":"It looks dated","image_key":null},{"id":"opt_it_s_hard","label":"It''s hard for us to update","image_key":null},{"id":"opt_it_loads_slowly","label":"It loads slowly","image_key":null},{"id":"opt_it_doesn_t","label":"It doesn''t work well on phones","image_key":null},{"id":"opt_it_doesn_t_2","label":"It doesn''t bring in enquiries or sales","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_websited06","ref":"product_count","title":"Roughly how many products will you sell?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_20","label":"Under 20","image_key":null},{"id":"opt_20_100","label":"20–100","image_key":null},{"id":"opt_100_1_000","label":"100–1,000","image_key":null},{"id":"opt_more_than_1","label":"More than 1,000","image_key":null}],"allowOther":false},{"id":"blk_websited07","ref":"site_goal","title":"What''s the main thing a visitor should do on the site?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_contact_us_or","label":"Contact us or ask for a quote","image_key":null},{"id":"opt_book_an_appointment","label":"Book an appointment","image_key":null},{"id":"opt_buy_something","label":"Buy something","image_key":null},{"id":"opt_read_and_learn","label":"Read and learn about us","image_key":null},{"id":"opt_sign_up_or","label":"Sign up or create an account","image_key":null}],"allowOther":false},{"id":"blk_websited08","ref":"pages","title":"Which pages do you expect to need?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_home","label":"Home","image_key":null},{"id":"opt_about","label":"About","image_key":null},{"id":"opt_services","label":"Services","image_key":null},{"id":"opt_portfolio_or_case","label":"Portfolio or case studies","image_key":null},{"id":"opt_blog_or_news","label":"Blog or news","image_key":null},{"id":"opt_shop_and_product","label":"Shop and product pages","image_key":null},{"id":"opt_pricing","label":"Pricing","image_key":null},{"id":"opt_faq","label":"FAQ","image_key":null},{"id":"opt_contact","label":"Contact","image_key":null},{"id":"opt_careers","label":"Careers","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_websited09","ref":"features","title":"Any of these features?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_online_booking","label":"Online booking","image_key":null},{"id":"opt_newsletter_signup","label":"Newsletter signup","image_key":null},{"id":"opt_member_login_area","label":"Member login area","image_key":null},{"id":"opt_more_than_one","label":"More than one language","image_key":null},{"id":"opt_site_search","label":"Site search","image_key":null},{"id":"opt_events_calendar","label":"Events calendar","image_key":null},{"id":"opt_none_of_these","label":"None of these","image_key":null}],"minSelections":0,"maxSelections":8,"allowOther":false},{"id":"blk_websited10","ref":"content_ready","title":"Who''s providing the words and photos?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_we_have_them","label":"We have them ready","image_key":null},{"id":"opt_we_have_some","label":"We have some, and need help with the rest","image_key":null},{"id":"opt_we_need_you","label":"We need you to create them","image_key":null}],"allowOther":false},{"id":"blk_websited11","ref":"has_brand","title":"Do you already have a logo and brand colours?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_websited12","ref":"brand_files","title":"Upload a logo, brand guide or brief if you have one.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":20},{"id":"blk_websited13","ref":"examples","title":"Are there sites you like? Paste links and tell us what you like about them.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_websited14","ref":"domain","title":"Do you already own a domain name for the site?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, we have one","noLabel":"Not yet"},{"id":"blk_websited15","ref":"launch","title":"When would you like the site to go live?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_websited16","ref":"budget","title":"Do you have a budget range in mind?","description":"It helps us suggest the right scope. Leave blank if you''re unsure.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_websited17","ref":"aftercare","title":"Will you want help looking after the site once it''s live?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no