VALUES ('tpl_demorequest', 'demo-request', 'Demo request form', 'Form', 'Take a demo request and learn exactly what to show before the call.', 'Half of a good demo is knowing what to skip. This asks what the prospect most wants to see, and each answer opens the one follow-up that makes the demo specific: which tools it must connect to, which compliance rules apply, or what they are moving off. Prospects who want to go live this month land on their own ending so sales can call them first.', '["lead generation","demo request","book a demo","sales demo","lead qualification","SaaS sales","branching"]', 'MonitorPlay', 'text', 3, 13, '{"schemaVersion":9,"title":"Demo request","description":"Take a demo request and learn exactly what to show before the call.","blocks":[{"id":"blk_demorequ00","ref":"welcome","title":"Let''s set up your demo. Two minutes of questions so we can show you what matters and skip what doesn''t.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_demorequ01","ref":"contact","title":"Who should we be speaking to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"],"fieldOptions":{"email":{"businessOnly":true,"allowedDomains":[]}}},{"id":"blk_demorequ02","ref":"company","title":"Which company are you with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_demorequ03","ref":"company_size","title":"How many people work there?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_1_10","label":"1–10","image_key":null},{"id":"opt_11_50","label":"11–50","image_key":null},{"id":"opt_51_200","label":"51–200","image_key":null},{"id":"opt_201_1_000","label":"201–1,000","image_key":null},{"id":"opt_more_than_1","label":"More than 1,000","image_key":null}],"allowOther":false},{"id":"blk_demorequ04","ref":"decision_role","title":"What''s your part in the decision?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_make_the","label":"I make the call","image_key":null},{"id":"opt_i_recommend_to","label":"I recommend to whoever does","image_key":null},{"id":"opt_i_m_researching","label":"I''m researching for someone else","image_key":null}],"allowOther":false},{"id":"blk_demorequ05","ref":"demo_focus","title":"What would you most like to see?","description":"Pick the one that matters most. We''ll cover the rest if there''s time.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_basics_end","label":"The basics, end to end","image_key":null},{"id":"opt_how_it_connects","label":"How it connects to our tools","image_key":null},{"id":"opt_security_and_compliance","label":"Security and compliance","image_key":null},{"id":"opt_moving_over_from","label":"Moving over from what we use now","image_key":null}],"allowOther":false},{"id":"blk_demorequ06","ref":"stack","title":"What does it need to work with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_our_crm","label":"Our CRM","image_key":null},{"id":"opt_team_chat","label":"Team chat","image_key":null},{"id":"opt_email_and_calendar","label":"Email and calendar","image_key":null},{"id":"opt_docs_and_wikis","label":"Docs and wikis","image_key":null},{"id":"opt_automation_tools","label":"Automation tools","image_key":null},{"id":"opt_our_own_systems","label":"Our own systems, through an API","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_demorequ07","ref":"compliance","title":"Which of these will you be held to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_soc_2","label":"SOC 2","image_key":null},{"id":"opt_iso_27001","label":"ISO 27001","image_key":null},{"id":"opt_gdpr","label":"GDPR","image_key":null},{"id":"opt_hipaa","label":"HIPAA","image_key":null},{"id":"opt_an_internal_security","label":"An internal security review","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_demorequ08","ref":"security_contact","title":"Who runs the security review on your side?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_demorequ09","ref":"migrating_from","title":"What are you moving off?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_demorequ10","ref":"migration_volume","title":"Roughly how much data would come with you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_handful_of","label":"A handful of records","image_key":null},{"id":"opt_hundreds","label":"Hundreds","image_key":null},{"id":"opt_thousands","label":"Thousands","image_key":null},{"id":"opt_millions","label":"Millions","image_key":null}],"allowOther":false},{"id":"blk_demorequ11","ref":"pain","title":"What''s prompting the search right now?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_demorequ12","ref":"anything_else","title":"Anything the demo should definitely cover?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_demorequ13","ref":"timeline","title":"When would you want this live?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_this_month","label":"This month","image_key":null},{"id":"opt_this_quarter","label":"This quarter","image_key":null},{"id":"opt_later_this_year","label":"Later this year","image_key":null},{"id":"opt_no_date_yet","label":"No date yet","image_key":null}],"allowOther":false}],"endings":[{"id":"end_demorequ01","ref":"end_thanks","title":"Thanks, we''ll set up your demo","bodyMd":"We''ll email you within one working day to find a time. Your answers will be open on the call.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_demorequ02","ref":"end_priority","title":"You''re at the front of the queue 🚀","bodyMd":"Since you''re aiming to go live this month, someone from our team will contact you within a few working hours to book the demo.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_demorequ01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"stack","target":"pain","targetKind":"block"},{"id":"rl_demorequ02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"security_contact","target":"pain","targetKind":"block"},{"id":"rl_demorequ03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"demo_focus"},"op":"eq","value":"opt_the_basics_end"}],"groups":[]},"from":"demo_focus","target":"pain","targetKind":"block","branch":"true"},{"id":"rl_demorequ04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"demo_focus"},"op":"eq","value":"opt_how_it_connects"}],"groups":[]},"from":"demo_focus","target":"stack","targetKind":"block","branch":"true"},{"id":"rl_demorequ05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"demo_focus"},"op":"eq","value":"opt_security_and_compliance"}],"groups":[]},"from":"demo_focus","target":"compliance","targetKind":"block","branch":"true"},{"id":"rl_demorequ06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"demo_focus"},"op":"eq","value":"opt_moving_over_from"}],"groups":[]},"from":"demo_focus","target":"migrating_from","targetKind":"block","branch":"true"},{"id":"rl_demorequ07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"timeline"},"op":"eq","value":"opt_this_month"}],"groups":[]},"from":"timeline","target":"end_priority","targetKind":"ending","branch":"true"},{"id":"rl_demorequ08","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"migration_volume","target":"anything_else","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffe4d3","surface":"#ffffff","text":"#3a2418","accent":"#c2410c","accentText":"#fffaf5","botBubble":"#ffffff","userBubble":"#c2410c","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
