VALUES ('tpl_contentdownload', 'content-download', 'Gated content form', 'Form', 'Gate a guide without making it feel like a toll booth.', 'Every extra field costs downloads, so the essentials come first and the rest depends on why someone came. Readers researching a purchase are asked about timing and whether they want to talk, which sends them to their own ending, while people who are just learning get their guide and are left alone.', '["lead generation","gated content","lead magnet","ebook download","content marketing","whitepaper","branching"]', 'Download', 'text', 3, 10, '{"schemaVersion":9,"title":"Content download","description":"Gate a guide without making it feel like a toll booth.","blocks":[{"id":"blk_contentd00","ref":"welcome","title":"Your guide is nearly ready. Tell us where to send it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_contentd01","ref":"email","title":"What''s your work email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":true,"allowedDomains":[],"verify":false},{"id":"blk_contentd02","ref":"name","title":"And your first name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_contentd03","ref":"company","title":"Which company are you with?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_contentd04","ref":"role","title":"Which best describes your role?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_founder_or_owner","label":"Founder or owner","image_key":null},{"id":"opt_manager_or_team","label":"Manager or team lead","image_key":null},{"id":"opt_individual_contributor","label":"Individual contributor","image_key":null},{"id":"opt_consultant_or_agency","label":"Consultant or agency","image_key":null},{"id":"opt_student","label":"Student","image_key":null},{"id":"opt_other","label":"Other","image_key":null}]},{"id":"blk_contentd05","ref":"interest","title":"What brought you to this guide?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_researching_a_purchase","label":"Researching a purchase","image_key":null},{"id":"opt_solving_a_specific","label":"Solving a specific problem","image_key":null},{"id":"opt_general_learning","label":"General learning","image_key":null}],"allowOther":false},{"id":"blk_contentd06","ref":"buying_timeline","title":"How soon would you want something in place?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_this_month","label":"This month","image_key":null},{"id":"opt_this_quarter","label":"This quarter","image_key":null},{"id":"opt_later_this_year","label":"Later this year","image_key":null},{"id":"opt_no_date_yet","label":"No date yet","image_key":null}],"allowOther":false},{"id":"blk_contentd07","ref":"wants_call","title":"Would you like someone to walk you through it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, get in touch","noLabel":"No thanks, just the guide"},{"id":"blk_contentd08","ref":"the_problem","title":"What are you trying to fix?","description":"If the guide doesn''t answer it, we''ll send something that does.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_contentd09","ref":"learning_focus","title":"Which part are you most curious about?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_how_it_works","label":"How it works","image_key":null},{"id":"opt_what_it_costs","label":"What it costs to run","image_key":null},{"id":"opt_how_other_teams","label":"How other teams use it","image_key":null},{"id":"opt_all_of_it","label":"All of it, really","image_key":null}],"allowOther":false},{"id":"blk_contentd10","ref":"consent","title":"Staying in touch","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"Send me related guides and resources now and then. I can unsubscribe at any time.","allowDecline":true,"agreeLabel":"Yes, send them","declineLabel":"No thanks"}],"endings":[{"id":"end_contentd01","ref":"end_thanks","title":"On its way 📄","bodyMd":"Check your inbox. The guide should arrive within a minute.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_contentd02","ref":"end_contact","title":"Guide sent, and we''ll be in touch 📄","bodyMd":"Check your inbox for the download. Someone who knows this subject well will email you within a working day.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_contentd01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"the_problem","target":"consent","targetKind":"block"},{"id":"rl_contentd02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"interest"},"op":"eq","value":"opt_researching_a_purchase"}],"groups":[]},"from":"interest","target":"buying_timeline","targetKind":"block","branch":"true"},{"id":"rl_contentd03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"interest"},"op":"eq","value":"opt_solving_a_specific"}],"groups":[]},"from":"interest","target":"the_problem","targetKind":"block","branch":"true"},{"id":"rl_contentd04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"interest"},"op":"eq","value":"opt_general_learning"}],"groups":[]},"from":"interest","target":"learning_focus","targetKind":"block","branch":"true"},{"id":"rl_contentd05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"wants_call"},"op":"eq","value":true}],"groups":[]},"from":"wants_call","target":"end_contact","targetKind":"ending","branch":"true"},{"id":"rl_contentd06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"wants_call"},"op":"eq","value":false}],"groups":[]},"from":"wants_call","target":"consent","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding"