VALUES ('tpl_leadcapture', 'lead-capture', 'Lead capture form', 'Form', 'Qualify visitors, and send the big ones to sales and the rest to a trial.', 'Ask who they are and what they are trying to solve before you ask for a meeting. Team size decides the middle of the conversation: larger teams are asked about the decision and their requirements, smaller ones where they are up to. Timeline is the last question and decides the ending, so a team buying this quarter is handed to sales and everyone else is pointed at a trial they can start today.', '["lead generation","lead capture form","b2b lead generation","website lead form","sales qualification","branching"]', 'UserPlus', 'text', 3, 11, '{"schemaVersion":9,"title":"Lead capture","description":"Qualify visitors, and send the big ones to sales and the rest to a trial.","blocks":[{"id":"blk_leadcapt00","ref":"welcome","title":"Hi! Interested in what we do? A few quick questions and we''ll point you to the right next step.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_leadcapt01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_leadcapt02","ref":"email","title":"What''s your work email?","description":"We''ll only use it to follow up on this.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":true,"allowedDomains":[],"verify":false},{"id":"blk_leadcapt03","ref":"company","title":"Where do you work?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_leadcapt04","ref":"team_size","title":"How big is your team?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"sing