VALUES ('tpl_customerleadform', 'customer-lead-form', 'Customer lead form', 'Form', 'Turn an interested visitor into a conversation, with the context to reply well.', 'For the enquiry button on a small business website. It asks what someone needs in their own words, then the practical details that shape a good first reply: budget range, timing and the way they want to be contacted. People who would rather have a call are asked for a number and a good time, and nobody else is.', '["lead generation","customer lead form","enquiry form","small business leads","sales enquiry","branching"]', 'Inbox', 'text', 3, 10, '{"schemaVersion":9,"title":"Customer lead","description":"Turn an interested visitor into a conversation, with the context to reply well.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"Hi there! Tell us a little about what you''re after and we''ll come back to you with something useful.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_customer02","ref":"email","title":"What email should we reply to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_customer03","ref":"interest","title":"What are you interested in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_product_we","label":"A product we sell","image_key":null},{"id":"opt_a_service_we","label":"A service we offer","image_key":null},{"id":"opt_a_custom_project","label":"A custom project","image_key":null},{"id":"opt_just_a_question","label":"Just a question for now","image_key":null}],"allowO