VALUES ('tpl_freegiveawayform', 'free-giveaway-form', 'Free giveaway form', 'Form', 'Let people claim a free item and choose how they receive it, one per person.', 'For giveaways where everyone who asks gets something, not a prize draw: free samples, a book, a starter kit or event merch. Repeat claimers are stopped politely before they give an address, and the delivery choice decides the rest, so only people who want it posted are asked where they live. It closes by asking what they want to hear about, which turns a freebie into a lead you can follow up.', '["lead generation","free giveaway form","freebie request form","free sample form","claim form","lead magnet","branching"]', 'Gift', 'text', 3, 9, '{"schemaVersion":9,"title":"Free giveaway claim","description":"Let people claim a free item and choose how they receive it, one per person.","blocks":[{"id":"blk_freegive00","ref":"welcome","title":"Thanks for claiming your free gift! Tell us who you are and how you''d like to receive it, and we''ll take care of the rest.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_freegive01","ref":"contact","title":"Who''s claiming?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_freegive02","ref":"claimed_before","title":"Have you claimed this giveaway from us before?","description":"It''s one per person, so there''s enough to go round while stock lasts.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_freegive03","ref":"delivery","title":"How would you like to get it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_post_it_to","label":"Post it to me","image_key":null},{"id":"opt_i_ll_collect","label":"I''ll collect it in person","image_key":null},{"id":"opt_send_me_the","label":"Send me the digital version","image_key":null}],"allowOther":false},{"id":"blk_freegive04","ref":"address","title":"Where should we send it?","description":"We only use this to post your gift.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","state","postal","country"],"location":"off"},{"id":"blk_freegive05","ref":"pickup_day","title":"Which day are you planning to come by?","description":"We''ll have yours set aside with your name on it.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_freegive06","ref":"interests","title":"What would you like to hear from us about?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_new_products","label":"New products","image_key":null},{"id":"opt_tips_and_how","label":"Tips and how-tos","image_key":null},{"id":"opt_offers_and_discounts","label":"Offers and discounts","image_key":null},{"id":"opt_events_near_me","label":"Events near me","image_key":null},{"id":"opt_nothing_for_now","label":"Nothing for now","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":true},{"id":"blk_freegive07","ref":"heard_from","title":"Where did you find out about the giveaway?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_our_newsletter","label":"Our newsletter","image_key":null},{"id":"opt_our_website","label":"Our website","image_key":null},{"id":"opt_in_store_or","label":"In store or at an event","image_key":null},{"id":"opt_a_friend","label":"A friend","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}]},{"id":"blk_freegive08","ref":"follow_up","title":"Could we ask what you thought of it in a couple of weeks?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Sure","noLabel":"Rather not"},{"id":"blk_freegive09","ref":"newsletter","title":"Newsletter","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"Yes, add me to your newsletter. I can unsubscribe at any time, and leaving this unticked doesn''t affect my free gift.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_freegive01","ref":"end_thanks","title":"It''s yours 🎁","bodyMd":"We''ll email you to confirm. Posted gifts usually go out within a few days, digital versions arrive by email, and collections are held under your name.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_freegive02","ref":"end_already","title":"You''ve already got one","bodyMd":"This giveaway is one per person, so we can''t send another. Thanks for coming back, and keep an eye on our newsletter and socials for the next one.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_freegive01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"address","target":"interests","targetKind":"block"},{"id":"rl_freegive02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"claimed_before"},"op":"eq","value":true}],"groups":[]},"from":"claimed_before","target":"end_already","targetKind":"ending","branch":"true"},{"id":"rl_freegive03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"delivery"},"op":"eq","value":"opt_post_it_to"}],"groups":[]},"from":"delivery","target":"address","targetKind":"block","branch":"true"},{"id":"rl_freegive04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"delivery"},"op":"eq","value":"opt_i_ll_collect"}],"groups":[]},"from":"delivery","target":"pickup_day","targetKind":"block","branch":"true"},{"id":"rl_freegive05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"delivery"},"op":"eq","value":"opt_send_me_the"}],"groups":[]},"from":"delivery","target":"interests","targetKind":"block","branch":"true"},{"id":"rl_freegive06","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"pickup_day","target":"heard_from","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#d9f2e6","surface":"#ffffff","text":"#12342a","accent":"#0f766e","accentText":"#f5fffb","botBubble":"#ffffff","userBubble":"#0f766e","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"plus","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
