INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_kycform', 'kyc-form', 'KYC form', 'Form', 'Gather identity, address and ownership details for an initial customer review.', 'Individuals and businesses answer different questions, so a sole customer is never asked for a registration number and a company is asked who owns it. Each request says why it is needed, which makes people more willing to share. Anyone who says they hold a public position gets one extra question, and nobody else sees it.', '["lead generation","KYC form","know your customer","customer due diligence","client onboarding","identity verification"]', 'ShieldCheck', 'text', 5, 20, '{"schemaVersion":9,"title":"KYC form","description":"Gather identity, address and ownership details for an initial customer review.","blocks":[{"id":"blk_kycform00","ref":"welcome","title":"Before we can open your account we need to confirm a few details about you. It takes about five minutes, and it helps to have an ID and a recent bill or bank statement nearby.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_kycform01","ref":"contact","title":"Let''s start with your contact details","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_kycform02","ref":"customer_type","title":"Are you applying as an individual or on behalf of a business?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_as_an_individual","label":"As an individual","image_key":null},{"id":"opt_on_behalf_of","label":"On behalf of a business","image_key":null}],"allowOther":false},{"id":"blk_kycform03","ref":"dob","title":"What is your date of birth?","description":"We use it together with your ID to confirm who you are.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_kycform04","ref":"nationality","title":"What is your nationality?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_kycform05","ref":"id_type","title":"Which photo ID will you upload?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_passport","label":"Passport","image_key":null},{"id":"opt_national_id_card","label":"National ID card","image_key":null},{"id":"opt_driving_licence","label":"Driving licence","image_key":null}],"allowOther":false},{"id":"blk_kycform06","ref":"id_upload","title":"Upload a clear photo or scan of that ID","description":"All four corners visible, no glare, and not expired.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/jpeg","image/png","application/pdf"],"maxFiles":2,"maxSizeMB":10},{"id":"blk_kycform07","ref":"company_name","title":"What is the business''s registered name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_kycform08","ref":"registration_number","title":"What is its company registration number?","description":"This lets us look the business up in the official company register.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_kycform09","ref":"business_activity","title":"What does the business do, in a few words?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_kycform10","ref":"applicant_role","title":"What is your role in the business?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_director","label":"Director","image_key":null},{"id":"opt_owner_or_shareholder","label":"Owner or shareholder","image_key":null},{"id":"opt_authorised_employee","label":"Authorised employee","image_key":null}],"allowOther":true},{"id":"blk_kycform11","ref":"owners","title":"Who owns or controls the business?","description":"List each person with a significant share or control, with their full name and roughly what they hold.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_kycform12","ref":"company_docs","title":"Upload the certificate of incorporation or a recent register extract","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["application/pdf","image/jpeg","image/png"],"maxFiles":3,"maxSizeMB":10},{"id":"blk_kycform13","ref":"business_ids","title":"Upload photo ID for yourself and for each owner you listed","description":"A passport, national ID card or driving licence for each person, with all four corners visible.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/jpeg","image/png","application/pdf"],"maxFiles":10,"maxSizeMB":10},{"id":"blk_kycform14","ref":"address","title":"What is your residential or registered business address?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","state","postal","country"],"location":"off"},{"id":"blk_kycform15","ref":"address_proof","title":"Upload proof of that address","description":"A utility bill, bank statement or official letter from the last three months.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["application/pdf","image/jpeg","image/png"],"maxFiles":1,"maxSizeMB":10},{"id":"blk_kycform16","ref":"source_of_funds","title":"Where will the money you use with us mainly come from?","description":"We ask everyone this, as part of checks against fraud and money laundering.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_salary_or_wages","label":"Salary or wages","image_key":null},{"id":"opt_business_revenue","label":"Business revenue","image_key":null},{"id":"opt_savings","label":"Savings","image_key":null},{"id":"opt_investments","label":"Investments","image_key":null},{"id":"opt_sale_of_property","label":"Sale of property or assets","image_key":null},{"id":"opt_inheritance_or_gift","label":"Inheritance or gift","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":true},{"id":"blk_kycform17","ref":"expected_activity","title":"Roughly how much do you expect to move through the account each month?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_1_000","label":"Under $1,000","image_key":null},{"id":"opt_1_000_10","label":"$1,000–$10,000","image_key":null},{"id":"opt_10_000_100","label":"$10,000–$100,000","image_key":null},{"id":"opt_over_100_000","label":"Over $100,000","image_key":null}],"allowOther":false},{"id":"blk_kycform18","ref":"pep","title":"Do you, or anyone connected to this application, hold, or have recently held, a prominent public position?","description":"For example a senior government, judicial or military role, or a close family member of someone who does.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_kycform19","ref":"pep_details","title":"Please tell us who holds the position, what it is and when they held it","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_kycform20","ref":"declaration","title":"Declaration","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I confirm that the information and documents I have provided are true and complete. I understand they will be used to verify my identity and assess this application, and that I must tell you if any of it changes.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_kycform01","ref":"end_thanks","title":"Thank you, we''ve received your details","bodyMd":"We''ll review everything and contact you if we need anything else. You''ll hear from us by email once the review is complete.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_kycform01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"id_upload","target":"address","targetKind":"block"},{"id":"rl_kycform02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"customer_type"},"op":"eq","value":"opt_as_an_individual"}],"groups":[]},"from":"customer_type","target":"dob","targetKind":"block","branch":"true"},{"id":"rl_kycform03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"customer_type"},"op":"eq","value":"opt_on_behalf_of"}],"groups":[]},"from":"customer_type","target":"company_name","targetKind":"block","branch":"true"},{"id":"rl_kycform04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"pep"},"op":"eq","value":false}],"groups":[]},"from":"pep","target":"declaration","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffdce8","surface":"#ffffff","text":"#3d1424","accent":"#be185d","accentText":"#fff7fa","botBubble":"#ffffff","userBubble":"#be185d","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"scallops","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
