INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_productrecommendationfor', 'product-recommendation-form', 'Product recommendation form', 'Form', 'Learn what a shopper needs so your team can suggest the right product.', 'The questions a good shop assistant asks, in the order they ask them. Intended use comes first, then a ranking of what matters most, so a tie between two products is easy to break. Gift buyers are asked who the gift is for and by when, and people who want a call rather than an email give a number, while everyone else skips it.', '["lead generation","product recommendation form","personal shopper","product finder","gift recommendation","branching"]', 'ShoppingBag', 'text', 4, 12, '{"schemaVersion":9,"title":"Product recommendation","description":"Learn what a shopper needs so your team can suggest the right product.","blocks":[{"id":"blk_productr00","ref":"welcome","title":"Not sure what to choose? Answer a few questions and one of our team will send you a personal recommendation.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_productr01","ref":"looking_for","title":"What are you looking for?","description":"Rough is fine: a type of product, a problem you want solved or something you''ve seen.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productr02","ref":"for_whom","title":"Who is it for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_me","label":"Me","image_key":null},{"id":"opt_someone_else_as","label":"Someone else, as a gift","image_key":null},{"id":"opt_my_team_or","label":"My team or business","image_key":null}],"allowOther":false},{"id":"blk_productr03","ref":"recipient","title":"Tell us a little about them: age, interests, anything they already have","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_productr04","ref":"needed_by","title":"When do you need it by?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_productr05","ref":"use","title":"How will it mostly be used?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_now_and_then","label":"Now and then","image_key":null},{"id":"opt_outdoors_or_on","label":"Outdoors or on the move","image_key":null},{"id":"opt_at_home","label":"At home","image_key":null},{"id":"opt_at_work","label":"At work","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":true},{"id":"blk_productr06","ref":"priorities","title":"Put these in order of what matters most to you","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_price","label":"Price"},{"id":"opt_item_quality_and","label":"Quality and durability"},{"id":"opt_item_looks_and","label":"Looks and design"},{"id":"opt_item_ease_of","label":"Ease of use"},{"id":"opt_item_sustainability","label":"Sustainability"}]},{"id":"blk_productr07","ref":"experience","title":"How familiar are you with this kind of product?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Complete beginner","labelHigh":"I know exactly what I want"},{"id":"blk_productr08","ref":"budget","title":"What''s the most you''d like to spend?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false,"currency":"USD"},{"id":"blk_produ