VALUES ('tpl_clientintake', 'client-intake', 'Client intake form', 'Form', 'Everything you need before the first client session, asked in the right order.', 'Replaces the intake PDF nobody fills in. What someone is here for decides what they are asked next: a one-off project gets scope, deadline and budget, an ongoing engagement gets cadence and decision-makers, and a second opinion gets asked what was said the first time. Everyone ends on the same background, goals and terms.', '["marketing","client intake","new client questionnaire","agency onboarding","consultant intake","branching"]', 'ClipboardList', 'content', 4, 17, '{"schemaVersion":9,"title":"New client intake","description":"Everything you need before the first client session, asked in the right order.","blocks":[{"id":"blk_clientin00","ref":"welcome","title":"Welcome! A few questions now means we can spend our first session on the real work.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_clientin01","ref":"contact","title":"First, your details","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_clientin02","ref":"organisation","title":"Which organisation are you with, if any?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_clientin03","ref":"service","title":"What are you here for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_an_initial_consultation","label":"An initial consultation","description":"You want to talk it through before committing","image_key":null},{"id":"opt_a_one_off","label":"A one-off project","description":"A defined piece of work with an end date","image_key":null},{"id":"opt_an_ongoing_engagement","label":"An ongoing engagement","description":"Regular support over months","image_key":null},{"id":"opt_a_second_opinion","label":"A second opinion","description":"You already have advice and want it checked","image_key":null}],"allowOther":false},{"id":"blk_clientin04","ref":"consult_topic","title":"What''s the one thing you most want to walk away with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_clientin05","ref":"project_scope","title":"What needs to be delivered?","description":"A rough list is fine. We''ll shape it together.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_clientin06","ref":"project_deadline","title":"Is there a date it has to be done by?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_clientin07","ref":"project_budget","title":"What budget are you working with?","description":"A range is fine. It tells us what''s realistic before we spend your time.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_5k","label":"Under $5k","image_key":null},{"id":"opt_5k_15k","label":"$5k–$15k","image_key":null},{"id":"opt_15k_50k","label":"$15k–$50k","image_key":null},{"id":"opt_50k","label":"$50k+","image_key":null},{"id":"opt_i_d_rather","label":"I''d rather you suggest","image_key":null}],"allowOther":false},{"id":"blk_clientin08","ref":"ongoing_cadence","title":"How often would we work together?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_weekly","label":"Weekly","image_key":null},{"id":"opt_fortnightly","label":"Fortnightly","image_key":null},{"id":"opt_monthly","label":"Monthly","image_key":null},{"id":"opt_as_needed","label":"As needed","image_key":null}],"allowOther":false},{"id":"blk_clientin09","ref":"ongoing_stakeholders","title":"Who else would be involved, and who signs things off?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_clientin10","ref":"prior_advice","title":"What were you told, and by whom?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_clientin11","ref":"prior_doubt","title":"What about it didn''t sit right?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_clientin12","ref":"background","title":"Tell us the background in your own words","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_clientin13","ref":"goals","title":"What would a good outcome look like six months from now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_clientin14","ref":"urgency","title":"How soon do you need to start?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_this_week","label":"This week","image_key":null},{"id":"opt_this_month","label":"This month","image_key":null},{"id":"opt_this_quarter","label":"This quarter","image_key":null},{"id":"opt_no_rush","label":"No rush","image_key":null}],"allowOther":false},{"id":"blk_clientin15","ref":"referral","title":"How did you find us?","requi