VALUES ('tpl_demofeedbackform', 'demo-feedback-form', 'Demo feedback form', 'Form', 'Hear what landed in the demo, what didn''t, and what the buyer wants next.', 'Sent right after a sales demo, it rates the session, pins down what went unanswered and asks what should happen next. Buyers who want a technical deep dive are asked what to cover, keen buyers share their timeline and who else decides, and anyone who isn''t a fit is asked why and gets a polite ending of their own.', '["marketing","demo feedback","sales demo survey","product demo follow-up","post-demo form","branching"]', 'MonitorPlay', 'content', 3, 11, '{"schemaVersion":9,"title":"Demo feedback","description":"Hear what landed in the demo, what didn''t, and what the buyer wants next.","blocks":[{"id":"blk_demofeed00","ref":"welcome","title":"Thanks for joining the demo today. Could you spare two minutes to tell us how it went?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_demofeed01","ref":"attendee","title":"Your name and work email","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_demofeed02","ref":"company","title":"Which company are you with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_demofeed03","ref":"usefulness","title":"How useful was the demo for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Not useful","labelHigh":"Very useful"},{"id":"blk_demofeed04","ref":"needs_covered","title":"Did we show what you came to see?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_all_of","label":"Yes, all of it","image_key":null},{"id":"opt_some_of_it","label":"Some of it","image_key":null},{"id":"opt_not_really","label":"Not really","image_key":null}],"allowOther":false},{"id":"blk_demofeed05","ref":"aspects","title":"How was each part of the session?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_how_clearly","label":"How clearly things were explained"},{"id":"opt_row_relevance_to","label":"Relevance to your use case"},{"id":"opt_row_pace","label":"Pace"},{"id":"opt_row_answers_to","label":"Answers to your questions"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_great","label":"Great"}],"multiplePerRow":false},{"id":"blk_demofeed06","ref":"unanswered","title":"What questions do you still have, or what didn''t we show?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_demofeed07","ref":"next_step","title":"What would you like to happen next?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_start_a_trial","label":"Start a trial","image_key":null},{"id":"opt_a_proposal_with","label":"A proposal with pricing","image_key":null},{"id":"opt_a_technical_deep","label":"A technical deep dive","image_key":null},{"id":"opt_share_it_with","label":"Share it with my team first","image_key":null},{"id":"opt_not_a_fit","label":"Not a fit right now","image_key":null}],"allowOther":false},{"id":"blk_demofeed08","ref":"tech_topics","title":"What should the technical session cover?","description":"Security, data, integrations with your stack, anything your engineers will ask.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_demofeed09","ref":"timeline","title":"When are you hoping to decide?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_within_a_month","label":"Within a month","image_key":null},{"id":"opt_in_the_next","label":"In the next quarter","image_key":null},{"id":"opt_later_this_year","label":"Later this year","image_key":null},{"id":"opt_no_set_date","label":"No set date","image_key":null}],"allowOther":false},{"id":"blk_demofeed10","ref":"decision_makers","title":"Who else has a say in the decision?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_my_manager","label":"My manager","image_key":null},{"id":"opt_finance","label":"Finance","image_key":null},{"id":"opt_it_or_security","label":"IT or security","image_key":null},{"id":"opt_procurement","label":"Procurement","image_key":null},{"id":"opt_the_people_who","label":"The people who will use it","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_demofeed11","ref":"not_fit_reason","title":"What''s the main reason it isn''t a fit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_s_missing","label":"It''s missing something we need","image_key":null},{"id":"opt_it_costs_more","label":"It costs more than we can spend","image_key":null},{"id":"opt_the_timing_is","label":"The timing is wrong","image_key":null},{"id":"opt_we_re_going","label":"We''re going with another option","image_key":null}],"allowOther":true}],"endings":[{"id":"end_demofeed01","ref":"end_thanks","title":"Thanks, we''ll be in touch 🚀","bodyMd":"Your account contact will follow up with the next step you picked, usually within one working day.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_demofeed02","ref":"end_not_fit","title":"Thanks for being straight with us","bodyMd":"That helps us more than you''d think. If things change, just reply to our last email.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_demofeed01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"decision_makers","target":"end_thanks","targetKind":"ending"},{"id":"rl_demofeed02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"not_fit_reason","target":"end_not_fit","targetKind":"ending"},{"id":"rl_demofeed03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"next_step"},"op":"eq","value":"opt_start_a_trial"}],"groups":[]},"from":"next_step","target":"timeline","targetKind":"block","branch":"true"},{"id":"rl_demofeed04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"next_step"},"op":"eq","value":"opt_a_proposal_with"}],"groups":[]},"from":"next_step","target":"timeline","targetKind":"block","branch":"true"},{"id":"rl_demofeed05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"next_step"},"op":"eq","value":"opt_a_technical_deep"}],"groups":[]},"from":"next_step","target":"tech_topics","targetKind":"block","branch":"true"},{"id":"rl_demofeed06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"next_step"},"op":"eq","value":"opt_share_it_with"}],"groups":[]},"from":"next_step","target":"timeline","targetKind":"block","branch":"true"},{"id":"rl_demofeed07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"next_step"},"op":"eq","value":"opt_not_a_fit"}],"groups":[]},"from":"next_step","target":"not_fit_reason","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffe4d3","surface":"#ffffff","text":"#3a2418","accent":"#c2410c","accentText":"#fffaf5","botBubble":"#ffffff","userBubble":"#c2410c","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NUL