VALUES ('tpl_eventplannerconsultation', 'event-planner-consultation-form', 'Event planner consultation form', 'Form', 'The occasion, numbers, venue and priorities, gathered before the first meeting.', 'Built for planners who want the first meeting to be about ideas, not logistics. It covers the occasion, date, guest count, budget and services, then asks the client to rank what matters most. Clients who already have a venue name it; clients who don''t describe the area and the kind of place they have in mind.', '["marketing","event planner questionnaire","event planning consultation","event inquiry form","party planning form","branching"]', 'PartyPopper', 'content', 4, 14, '{"schemaVersion":9,"title":"Event planning consultation","description":"The occasion, numbers, venue and priorities, gathered before the first meeting.","blocks":[{"id":"blk_eventpla00","ref":"welcome","title":"Planning something? Tell us about the event and we''ll come to the consultation with ideas ready.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventpla01","ref":"contact","title":"Your name, email and phone","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_eventpla02","ref":"occasion","title":"What''s the occasion?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_wedding","label":"Wedding","image_key":null},{"id":"opt_birthday_or_anniversary","label":"Birthday or anniversary","image_key":null},{"id":"opt_company_party","label":"Company party","image_key":null},{"id":"opt_conference_or_offsite","label":"Conference or offsite","image_key":null},{"id":"opt_product_launch","label":"Product launch","image_key":null}],"allowOther":true},{"id":"blk_eventpla03","ref":"event_date","title":"When is it?","description":"Your best guess is fine.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_eventpla04","ref":"date_flexible","title":"Is the date flexible?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_eventpla05","ref":"guests","title":"About how many guests?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":5000,"integerOnly":true},{"id":"blk_eventpla06","ref":"has_venue","title":"Have you already booked a venue?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_eventpla07","ref":"venue_name","title":"Which venue, and where?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_eventpla08","ref":"area","title":"Which town or area should we look in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_eventpla09","ref":"venue_style","title":"What kind of place do you picture?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_hotel_or_ballroom","label":"Hotel or ballroom","image_key":null},{"id":"opt_restaurant","label":"Restaurant","image_key":null},{"id":"opt_outdoors_or_garden","label":"Outdoors or garden","image_key":null},{"id":"opt_barn_or_countryside","label":"Barn or countryside","image_key":null},{"id":"opt_city_rooftop_or","label":"City rooftop or loft","image_key":null},{"id":"opt_at_home","label":"At home","image_key":null}],"minSelections":0,"maxSelections":4,"allowOther":false},{"id":"blk_eventpla10","ref":"services","title":"What would you like help with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_full_planning_from","label":"Full planning from start to finish","image_key":null},{"id":"opt_on_the_day","label":"On-the-day coordination","image_key":null},{"id":"opt_finding_suppliers","label":"Finding suppliers","image_key":null},{"id":"opt_catering","label":"Catering","image_key":null},{"id":"opt_decor_and_styling","label":"Decor and styling","image_key":null},{"id":"opt_entertainment","label":"Entertainment","image_key":null},{"id":"opt_guest_travel_and","label":"Guest travel and hotels","image_key":null}],"minSelections":1,"maxSelections":8,"allowOther":false},{"id":"blk_eventpla11","ref":"priorities","title":"Rank what matters most to you","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_food_and","label":"Food and drink"},{"id":"opt_item_the_venue","label":"The venue and setting"},{"id":"opt_item_entertainment","label":"Entertainment"},{"id":"opt_item_decor","label":"Decor"},{"id":"opt_item_staying_on","label":"Staying on budget"},{"id":"opt_item_a_relaxed","label":"A relaxed day for you"}]},{"id":"blk_eventpla12","ref":"budget","title":"What''s your overall budget?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_5_000","label":"Under $5,000","image_key":null},{"id":"opt_5_000_20","label":"$5,000–$20,000","image_key":null},{"id":"opt_20_000_50","label":"$20,000–$50,000","image_key":null},{"id":"opt_more_than_50","label":"More than $50,000","image_key":null},{"id":"opt_not_decided_yet","label":"Not decided yet","image_key":null}],"allowOther":false},{"id":"blk_eventpla13","ref":"vision","title":"Describe the event you''re picturing","description":"The feeling, a theme, anything you''ve seen and loved.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_eventpla14","ref":"heard","title":"How did you hear about us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_a_friend_or","label":"A friend or past client","image_key":null},{"id":"opt_a_venue_or","label":"A venue or supplier","image_key":null},{"id":"opt_search","label":"Search","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}]}],"endings":[{"id":"end_eventpla01","ref":"end_thanks","title":"Thanks, we have what we need 🎉","bodyMd":"We''ll check our availability for your date and get back to you to set up the consultation.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_eventpla01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"venue_name","target":"services","targetKind":"block"},{"id":"rl_eventpla02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_venue"},"op":"eq","value":true}],"groups":[]},"from":"has_venue","target":"venue_name","targetKind":"block","branch":"true"},{"id":"rl_eventpla03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_venue"},"op":"eq","value":false}],"groups":[]},"from":"has_venue","target":"area","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
