VALUES ('tpl_marketingbriefform', 'marketing-brief-form', 'Marketing brief form', 'Form', 'A campaign brief that covers the goal, audience, message, channels and deadline.', 'Written for agencies and in-house teams who are tired of briefs that arrive as a one-line email. It asks for the goal and how success will be measured, the audience and message, channels and deliverables, then budget and dates. Teams with brand guidelines upload them; teams without describe the tone they want.', '["marketing","marketing brief","campaign brief","creative brief","agency brief","branching"]', 'Megaphone', 'content', 5, 16, '{"schemaVersion":9,"title":"Marketing brief","description":"A campaign brief that covers the goal, audience, message, channels and deadline.","blocks":[{"id":"blk_marketin00","ref":"welcome","title":"Let''s get the campaign brief down. It takes about five minutes and saves a lot of back and forth.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_marketin01","ref":"requester","title":"Who''s sending the brief?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_marketin02","ref":"brand","title":"Which brand or product is this for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_marketin03","ref":"campaign","title":"Give the campaign a working name","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_marketin04","ref":"objective","title":"What''s the main goal?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_build_awareness","label":"Build awareness","image_key":null},{"id":"opt_generate_leads","label":"Generate leads","image_key":null},{"id":"opt_drive_sales","label":"Drive sales","image_key":null},{"id":"opt_launch_something_new","label":"Launch something new","image_key":null},{"id":"opt_win_back_or","label":"Win back or keep customers","image_key":null},{"id":"opt_fill_an_event","label":"Fill an event","image_key":null}],"allowOther":false},{"id":"blk_marketin05","ref":"success","title":"How will you know it worked?","description":"The number or result you''ll judge it by.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_marketin06","ref":"audience","title":"Who are we trying to reach, and what do they care about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_marketin07","ref":"message","title":"If people remember one thing, what should it be?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_marketin08","ref":"channels","title":"Which channels should it run on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_paid_search","label":"Paid search","image_key":null},{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_website","label":"Website","image_key":null},{"id":"opt_print","label":"Print","image_key":null},{"id":"opt_events","label":"Events","image_key":null},{"id":"opt_pr","label":"PR","image_key":null},{"id":"opt_open_to_suggestions","label":"Open to suggestions","image_key":null}],"minSelections":1,"maxSelections":8,"allowOther":false},{"id":"blk_marketin09","ref":"deliverables","title":"What exactly needs to be made?","description":"For example: 6 social posts, a landing page, 2 emails.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_marketin10","ref":"has_guidelines","title":"Do you have brand guidelines we should follow?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_marketin11","ref":"guidelines_file","title":"Upload them here","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["application/pdf","image/*"],"maxFiles":3,"maxSizeMB":25},{"id":"blk_marketin12","ref":"tone","title":"Then how should it sound? Pick up to three.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_friendly","label":"Friendly","image_key":null},{"id":"opt_expert","label":"Expert","image_key":null},{"id":"opt_playful","label":"Playful","image_key":null},{"id":"opt_bold","label":"Bold","image_key":null},{"id":"opt_reassuring","label":"Reassuring","image_key":null},{"id":"opt_luxurious","label":"Luxurious","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":false},{"id":"blk_marketin13","ref":"mandatories","title":"Anything that must or must not be included?","description":"Legal lines, logos, words to avoid, offers that have to appear.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_marketin14","ref":"budget","title":"What''s the budget, in your currency?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_marketin15","ref":"launch_date","title":"When does it need to go live?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_marketin16","ref":"approver","title":"Who signs off the final work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150}],"endings":[{"id":"end_marketin01","ref":"end_thanks","title":"Brief received 📣","bodyMd":"We''ll read it through and come back with any questions, then a plan and timeline.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_marketin01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"guidelines_file","target":"mandatories","targetKind":"block"},{"id":"rl_marketin02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_guidelines"},"op":"eq","value":true}],"groups":[]},"from":"has_guidelines","target":"guidelines_file","targetKind":"block","branch":"true"},{"id":"rl_marketin03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_guidelines"},"op":"eq","value":false}],"groups":[]},"from":"has_guidelines","target":"tone","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"s