VALUES ('tpl_testimonialrequest', 'testimonial-request', 'Testimonial form', 'Form', 'Collect quotes you''re actually allowed to publish.', 'Most testimonials never get used because nobody asked permission in writing. This one collects the story, the result, the credit and the consent together. A customer who rates the experience three stars or lower is asked privately what fell short instead of being pushed for a quote, and an anonymous quote is never chased for a headshot.', '["marketing","testimonial form","customer testimonial request","review collection","social proof","branching"]', 'Quote', 'content', 4, 14, '{"schemaVersion":9,"title":"Testimonial request","description":"Collect quotes you''re actually allowed to publish.","blocks":[{"id":"blk_testimon00","ref":"welcome","title":"Would you say a few words about working with us? It really helps.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_testimon01","ref":"contact","title":"Your name and email","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_testimon02","ref":"rating","title":"How would you rate your experience with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_testimon03","ref":"worked_on","title":"What did we work on together?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_testimon04","ref":"before","title":"What was going on before you came to us?","description":"The most useful testimonials have a before in them.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_testimon05","ref":"quote","title":"In your own words, what was it like working with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_testimon06","ref":"result","title":"Is there a specific result you''d be happy to mention?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_testimon07","ref":"attribution","title":"How would you like to be credited?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_full_name_role","label":"Full name, role and company","image_key":null},{"id":"opt_first_name_and","label":"First name and company only","image_key":null},{"id":"opt_anonymously","label":"Anonymously","image_key":null}],"allowOther":false},{"id":"blk_testimon08","ref":"role_company","title":"Role and company, exactly as you''d like it shown","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_testimon09","ref":"photo","title":"A photo we can show alongside it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*"],"maxFiles":1,"maxSizeMB":8},{"id":"blk_testimon10","ref":"linkedin","title":"Your LinkedIn profile, if you''d like it linked","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_testimon11","ref":"company_only","title":"Which company should we name?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_testimon12","ref":"where_ok","title":"Where are you happy for it to appear?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_our_website","label":"Our website","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_sales_decks_and","label":"Sales decks and proposals","image_key":null},{"id":"opt_paid_advertising","label":"Paid advertising","image_key":null}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_testimon13","ref":"publish_consent","title":"Permission to publish","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I''m happy for this quote, the credit I chose, and any photo I''ve provided to be used in the places I selected. I understand I can withdraw this by asking.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"},{"id":"blk_testimon14","ref":"improve","title":"Sorry it wasn''t better. What should we have done differently?","description":"This stays with us and won''t be published.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false}],"endings":[{"id":"end_testimon01","ref":"end_thanks","title":"Thank you ⭐","bodyMd":"That means a lot. We''ll let you know where it ends up.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_testimon02","ref":"end_private","title":"Thank you for telling us","bodyMd":"We''d rather hear this than not. Someone from the team will read it and may be in touch.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_testimon01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"linkedin","target":"where_ok","targetKind":"block"},{"id":"rl_testimon02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"publish_consent","target":"end_t