VALUES ('tpl_userregistrationform', 'user-registration-form', 'User registration form', 'Form', 'Collect what you need to register and approve a new user.', 'A registration form for anything that reviews sign-ups before giving access, such as a portal, a community or a beta. Individuals get a short path; people registering for a team add the organisation, their role and the team size. An age check at the start stops anyone under 16 with a friendly ending instead of an error.', '["marketing","user registration form","account registration","sign up form","access request","branching"]', 'UserPlus', 'content', 4, 12, '{"schemaVersion":9,"title":"User registration","description":"Collect what you need to register and approve a new user.","blocks":[{"id":"blk_userregi00","ref":"welcome","title":"Welcome! Register here and we''ll review your details before your access is switched on. It takes a minute or two.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_userregi01","ref":"age_ok","title":"Are you 16 or older?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_userregi02","ref":"contact","title":"Your name and email","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_userregi03","ref":"country","title":"Which country are you in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["country"],"location":"off"},{"id":"blk_userregi04","ref":"account_type","title":"Who are you registering for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_my_team_or","label":"My team or organisation","image_key":null}],"allowOther":false},{"id":"blk_userregi05","ref":"org_name","title":"What''s the organisation called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_userregi06","ref":"job_role","title":"What''s your role there?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_userregi07","ref":"team_size","title":"How many people would use it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_2_5","label":"2–5","image_key":null},{"id":"opt_6_20","label":"6–20","image_key":null},{"id":"opt_21_100","label":"21–100","image_key":null},{"id":"opt_more_than_100","label":"More than 100","image_key":null}],"allowOther":false},{"id":"blk_userregi08","ref":"use_case","title":"What are you hoping to use it for?","description":"A sentence or two helps us approve you faster.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_userregi09","ref":"found_us","title":"How did you hear about us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_a_friend_or","label":"A friend or colleague","image_key":null},{"id":"opt_search","label":"Search","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_an_article_or","label":"An article or podcast","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}]},{"id":"blk_userregi10","ref":"invite_code","title":"Do you have an invite or referral code?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_