VALUES ('tpl_gymmembershipform', 'gym-membership-form', 'Gym membership form', 'Form', 'Everything the front desk needs before a new member''s first session.', 'Covers the plan, start date and training goals, then the parts gyms usually chase on paper: health notes, an emergency contact and the waiver. Anyone who mentions an injury or condition is asked what it is and whether a doctor has cleared them, so a trainer knows before the induction rather than during it.', '["membership","gym membership form","gym sign up","fitness membership application","health club registration","branching"]', 'Dumbbell', 'content', 4, 14, '{"schemaVersion":9,"title":"Gym membership","description":"Everything the front desk needs before a new member''s first session.","blocks":[{"id":"blk_gymmembe00","ref":"welcome","title":"Great to have you! Let''s get your membership set up. It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_gymmembe01","ref":"contact","title":"Your name, email and phone","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_gymmembe02","ref":"date_of_birth","title":"Your date of birth","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_gymmembe03","ref":"plan","title":"Which membership would you like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_monthly_cancel_any","label":"Monthly, cancel any time","image_key":null},{"id":"opt_annual","label":"Annual","image_key":null},{"id":"opt_off_peak","label":"Off-peak","image_key":null},{"id":"opt_student","label":"Student","image_key":null},{"id":"opt_classes_only","label":"Classes only","image_key":null}],"allowOther":false},{"id":"blk_gymmembe04","ref":"start_date","title":"When would you like to start?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_gymmembe05","ref":"goals","title":"What are you training for?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_getting_stronger","label":"Getting stronger","image_key":null},{"id":"opt_losing_weight","label":"Losing weight","image_key":null},{"id":"opt_fitness_and_stamina","label":"Fitness and stamina","image_key":null},{"id":"opt_flexibility_and_mobility","label":"Flexibility and mobility","image_key":null},{"id":"opt_training_for_an","label":"Training for an event","image_key":null},{"id":"opt_feeling_better_day","label":"Feeling better day to day","image_key":null}],"minSelections":0,"maxSelections":4,"allowOther":false},{"id":"blk_gymmembe06","ref":"experience","title":"How much gym experience do you have?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_new_to_it","label":"New to it","image_key":null},{"id":"opt_some_but_it","label":"Some, but it''s been a while","image_key":null},{"id":"opt_i_train_regularly","label":"I train regularly","image_key":null}],"allowOther":false},{"id":"blk_gymmembe07","ref":"times","title":"When are you most likely to come in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_early_morning","label":"Early morning","image_key":null},{"id":"opt_lunchtime","label":"Lunchtime","image_key":null},{"id":"opt_evenings","label":"Evenings","image_key":null},{"id":"opt_weekends","label":"Weekends","image_key":null}],"min