VALUES ('tpl_membershipcancellationfo', 'membership-cancellation-form', 'Membership cancellation form', 'Form', 'Take cancellation requests cleanly, and offer a pause to those who want one.', 'Makes leaving easy while still giving people a real alternative. After the reason, members are offered a pause or a cheaper plan once, with no pressure: a pause records the return date, a switch hands them to the team, and a cancellation collects the end date and optional feedback. Members who are moving away skip the offer entirely.', '["membership","membership cancellation form","cancel membership request","gym cancellation","subscription cancellation","branching"]', 'LogOut', 'content', 3, 11, '{"schemaVersion":9,"title":"Membership cancellation","description":"Take cancellation requests cleanly, and offer a pause to those who want one.","blocks":[{"id":"blk_membersh00","ref":"welcome","title":"Sorry to see you go. This takes about a minute, and the feedback questions at the end are optional.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_membersh01","ref":"contact","title":"Your name and the email on your membership","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_membersh02","ref":"member_number","title":"Membership number, if you have it","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_membersh03","ref":"membership","title":"Which membership is this about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_monthly","label":"Monthly","image_key":null},{"id":"opt_annual","label":"Annual","image_key":null},{"id":"opt_off_peak","label":"Off-peak","image_key":null},{"id":"opt_family_or_joint","label":"Family or joint","image_key":null}],"allowOther":true},{"id":"blk_membersh04","ref":"reason","title":"What''s the main reason?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_m_moving","label":"I''m moving away","image_key":null},{"id":"opt_it_costs_too","label":"It costs too much","image_key":null},{"id":"opt_i_m_not","label":"I''m not using it enough","image_key":null},{"id":"opt_i_m_unhappy","label":"I''m unhappy with the service","image_key":null},{"id":"opt_health_or_personal","label":"Health or personal reasons","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_membersh05","ref":"what_went_wrong","title":"We''re sorry. What went wrong?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_membersh06","ref":"alternative","title":"Would either of these work better than cancelling?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_pause_my_membership","label":"Pause my membership instead","image_key":null},{"id":"opt_switch_to_a","label":"Switch to a cheaper option","image_key":null},{"id":"opt_no_thanks_please","label":"No thanks, please cancel","image_key":null}],"allowOther":false},{"id":"blk_membersh07","ref":"pause_until","title":"When would you like to come back?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_membersh08","ref":"end_date","title":"When should the cancellation take effect?","description":"If you''re not sure, pick the earliest date. Your notice period still applies.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_membersh09","ref":"experience","title":"Overall, how was your time as a member?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_membersh10","ref":"feedback","title":"Anything else you''d like us to know?","description":"Completely optional.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_membersh11","ref":"come_back","title":"Can we let you know about offers if you''d like to return one day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"}],"endings":[{"id":"end_membersh01","ref":"end_thanks","title":"Cancellation request received","bodyMd":"We''ll email you to confirm the date your membership ends. Thanks for being a member.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_membersh02","ref":"end_paused","title":"Your pause request is in ⏸️","bodyMd":"We''ll confirm the pause by email and remind you before your return date.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_membersh03","ref":"end_switch","title":"Let''s find a better fit","bodyMd":"Someone from the team will email you the cheaper options and switch you over once you''ve picked one.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_membersh01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"pause_until","target":"end_paused","targetKind":"ending"},{"id":"rl_membersh02","action_kind":"goto","when":{"op":"and","conditions"