INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_membershipapplication', 'membership-application', 'Membership application form', 'Form', 'Take applications with the tier, the evidence and the terms in one pass.', 'Everything a membership secretary would otherwise chase over three emails. A concession applicant is asked which one applies and for evidence, a household membership for the other names on it, and a life membership nomination for the nominating member and history, so the committee can reply with a decision rather than another question.', '["membership","membership application form","club membership form","society membership","association application","branching"]', 'BadgeCheck', 'content', 3, 14, '{"schemaVersion":9,"title":"Membership application","description":"Take applications with the tier, the evidence and the terms in one pass.","blocks":[{"id":"blk_membersh00","ref":"welcome","title":"Glad you want to join us. A few questions and we''ll take it from there.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_membersh01","ref":"contact","title":"Your name, email and phone","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_membersh02","ref":"date_of_birth","title":"Your date of birth","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"DD/MM/YYYY","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_membersh03","ref":"address","title":"Your address","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal","country"],"location":"off"},{"id":"blk_membersh04","ref":"tier","title":"Which membership are you applying for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"