VALUES ('tpl_serviceorderform', 'service-order-form', 'Service order form', 'Form', 'Collect the job, the site and the timing so your team can plan the visit.', 'Built for trades and field services that need more than a name and a phone number before they can quote or book a visit. Business customers are asked for a company name and purchase order, and anyone who picks the emergency option gets a safety check and a call-back ending instead of a date picker. Access notes and photos come before the timing question, so an emergency order still reaches the on-call team with everything they need.', '["order","service order","work order","job request","field service","branching"]', 'HardHat', 'number', 4, 13, '{"schemaVersion":9,"title":"Service order","description":"Collect the job, the site and the timing so your team can plan the visit.","blocks":[{"id":"blk_serviceo00","ref":"welcome","title":"Hi there. Tell us about the job and we''ll get it planned.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_serviceo01","ref":"contact","title":"First, who should we contact about this order?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_serviceo02","ref":"customer_type","title":"Is this for your home or for a business?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_my_home","label":"My home","image_key":null},{"id":"opt_a_business","label":"A business","image_key":null}],"allowOther":false},{"id":"blk_serviceo03","ref":"company","title":"What''s the company name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_serviceo04","ref":"po_number","title":"Do you have a purchase order number or quote reference?","description":"Leave it blank if you don''t have one yet.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_serviceo05","ref":"service","title":"What kind of work do you need?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_repair","label":"Repair","image_key":null},{"id":"opt_installation","label":"Installation","image_key":null},{"id":"opt_regular_maintenance","label":"Regular maintenance","image_key":null},{"id":"opt_inspection_or_assessment","label":"Inspection or assessment","image_key":null},{"id":"opt_cleaning","label":"Cleaning","image_key":null}],"allowOther":true},{"id":"blk_serviceo06","ref":"details","title":"Describe the job in a few sentences.","description":"What''s wrong or what you want done, the make or model if there is one, and roughly how big the area is.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_serviceo07","ref":"site_address","title":"Where will the work take place?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","state","postal"],"location":"off"},{"id":"blk_serviceo08","ref":"access","title":"Anything we should know about getting in and working on site?","description":"Parking, gate codes, key collection, pets, or rooms we shouldn''t enter.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_serviceo09","ref":"photos","title":"Got photos of the problem or the space? Add up to five.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":10},{"id":"blk_serviceo10","ref":"urgency","title":"How soon do you need us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_s_an","label":"It''s an emergency","image_key":null},{"id":"opt_within_the_next","label":"Within the next week","image_key":null},{"id":"opt_sometime_this_month","label":"Sometime this month","image_key":null},{"id":"opt_i_m_planning","label":"I''m planning ahead","image_key":null}],"allowOther":false},{"id":"blk_serviceo11","ref":"hazard","title":"Is anything unsafe right now, such as a gas smell, flooding or exposed wiring?","description":"If so, keep everyone clear and call your local emergency number before anything else.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_serviceo12","ref":"preferred_date","title":"Which date would suit you best?","description":"We''ll confirm the actual date once we''ve checked the schedule.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_serviceo13","ref":"time_window","title":"Which times work for a visit?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_mornings","label":"Mornings","image_key":null},{"id":"opt_afternoons","label":"Afternoons","image_key":null},{"id":"opt_evenings","label":"Evenings","image_key":null},{"id":"opt_weekends","label":"Weekends","image_key":null}],"minSelections":0,"maxSelections":4,"allowOther":false}],"endings":[{"id":"end_serviceo01","ref":"end_thanks","title":"Order received ✅","bodyMd":"We''ll check the details and send you a confirmed date and price. Nothing is booked until you hear back from us.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_serviceo02","ref":"end_urgent","title":"We''re on it","bodyMd":"Emergency orders go straight to the on-call team, and someone will phone you shortly on the number you gave us.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_serviceo01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"hazard","target":"end_urgent","targetKind":"ending"},{"id":"rl_serviceo02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"customer_type"},"op":"eq","value":"opt_a_business"}],"groups":[]},"from":"customer_type","target":"company","targetKind":"block","branch":"true"},{"id":"rl_serviceo03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"customer_type"},"op":"eq","value":"opt_my_home"}],"groups":[]},"from":"customer_type","target":"service","targetKind":"block","branch":"true"},{"id":"rl_serviceo04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"urgency"},"op":"eq","value":"opt_it_s_an"}],"groups":[]},"from":"urgency","target":"hazard","targetKind":"block","branch":"true"},{"id":"rl_serviceo05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"urgency"},"op":"eq","value":"opt_within_the_next"}],"groups":[]},"from":"urgency","target":"preferred_date","targetKind":"block","branch":"true"},{"id":"rl_serviceo06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"urgency"},"op":"eq","value":"opt_sometime_this_month"}],"groups":[]},"from":"urgency","target":"preferred_date","targetKind":"block","branch":"true"},{"id":"rl_serviceo07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"urgency"},"op":"eq","value":"opt_i_m_planning"}],"groups":[]},"from":"urgency","target":"preferred_date","targetKind":"block","branch":"true"},{"id":"rl_serviceo08","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"po_number","target":"details","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
