VALUES ('tpl_cateringorderform', 'catering-order-form', 'Catering order form', 'Form', 'Menu, headcount, dietary needs and delivery details for one event, in one order.', 'Asks for everything the kitchen and the driver need: the menu, the headcount, the serving time and the dietary counts. Anyone who mentions a severe allergy is asked for the details, and customers collecting from you skip the venue and on-site contact questions entirely.', '["order","catering order","food order","event catering","dietary requirements","branching"]', 'ChefHat', 'number', 5, 16, '{"schemaVersion":9,"title":"Catering order","description":"Menu, headcount, dietary needs and delivery details for one event, in one order.","blocks":[{"id":"blk_catering00","ref":"welcome","title":"Hello! Let''s get your catering order down. Have your guest numbers and menu choice to hand.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_catering01","ref":"contact","title":"Who''s placing the order?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_catering02","ref":"organisation","title":"Are you ordering for a company or organisation? If so, which one?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_catering03","ref":"event_type","title":"What''s the occasion?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_business_meeting","label":"Business meeting","image_key":null},{"id":"opt_conference_or_training","label":"Conference or training day","image_key":null},{"id":"opt_wedding","label":"Wedding","image_key":null},{"id":"opt_birthday_or_family","label":"Birthday or family party","image_key":null},{"id":"opt_funeral_or_memorial","label":"Funeral or memorial","image_key":null},{"id":"opt_fundraiser","label":"Fundraiser","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_catering04","ref":"serve_time","title":"When should the food be ready to eat?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":30,"timeMin":"06:00","timeMax":"23:00"},{"id":"blk_catering05","ref":"guests","title":"How many people are you feeding?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":5000,"integerOnly":true},{"id":"blk_catering06","ref":"menu","title":"Which menu would you like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_breakfast_and_pastries","label":"Breakfast and pastries","image_key":null},{"id":"opt_sandwich_and_salad","label":"Sandwich and salad lunch","image_key":null},{"id":"opt_hot_buffet","label":"Hot buffet","image_key":null},{"id":"opt_canap_s_and","label":"Canapés and finger food","image_key":null},{"id":"opt_plated_sit_down","label":"Plated sit-down meal","image_key":null}],"allowOther":false},{"id":"blk_catering07","ref":"extras","title":"Anything to add?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_desserts","label":"Desserts","image_key":null},{"id":"opt_fruit_platter","label":"Fruit platter","image_key":null},{"id":"opt_tea_and_coffee","label":"Tea and coffee","image_key":null},{"id":"opt_soft_drinks_and","label":"Soft drinks and juice","image_key":null},{"id":"opt_plates_cutlery_and","label":"Plates, cutlery and napkins","image_key":null},{"id":"opt_serving_staff","label":"Serving staff","image_key":null},{"id":"opt_clearing_up_afterwards","label":"Clearing up afterwards","image_key":null}],"minSelections":0,"maxSelections":7,"allowOther":false},{"id":"blk_catering08","ref":"dietary","title":"Any dietary needs? Give a count for each.","description":"For example: 6 vegetarian, 2 vegan, 3 gluten free, 1 halal.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_catering09","ref":"severe_allergy","title":"Does anyone have a severe allergy we need to plan the kitchen around?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_catering10","ref":"allergy_details","title":"Tell us the allergy, how many guests have it, and how serious it is.","description":"We''ll confirm what we can safely prepare before the order is final.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_catering11","ref":"service_style","title":"How should the food reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_ll_collect","label":"I''ll collect it","image_key":null},{"id":"opt_deliver_and_drop","label":"Deliver and drop off","image_key":null},{"id":"opt_deliver_set_up","label":"Deliver, set up and serve","image_key":null}],"allowOther":false},{"id":"blk_catering12","ref":"venue","title":"Where are we delivering to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","state","postal"],"location":"off"},{"id":"blk_catering13","ref":"onsite_contact","title":"Who will meet the driver on the day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","phone"]},{"id":"blk_catering14","ref":"access","title":"Anything about the venue we should know?","description":"Loading bay, stairs or lifts, the room we''re serving in, and when we can get in to set up.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_catering15","ref":"budget","title":"Roughly what''s your budget per guest?","description":"In your own currency. It helps us suggest swaps if the menu comes in over.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_catering16","ref":"notes","title":"Anything else we should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_catering01","ref":"end_thanks","title":"Order request received 🍽️","bodyMd":"We''ll check the date, quantities and any dietary needs, then send you a confirmed menu and price. The order is final once you''ve approved that.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_catering01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"severe_allergy"},"op":"eq","value":true}],"groups":[]},"from":"severe_allergy","target":"allergy_details","targetKind":"block","branch":"true"},{"id":"rl_catering02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"severe_allergy"},"op":"eq","value":false}],"groups":[]},"from":"severe_allergy","target":"service_style","targetKind":"block","branch":"true"},{"id":"rl_catering03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"service_style"},"op":"eq","value":"opt_i_ll_collect"}],"groups":[]},"from":"service_style","target":"budget","targetKind":"block","branch":"true"},{"id":"rl_catering04","action_kind