VALUES ('tpl_photographyorderform', 'photography-order-form', 'Photography order form', 'Form', 'Book a new photo session or order prints and files from a past shoot.', 'One form for the two orders a photographer actually gets. New clients choose a session type, package and date; past clients name their gallery and the images they want printed. Everyone is asked how the photos will be used, which settles licensing before it becomes an awkward conversation.', '["order","photography order","photo session booking","print order","photographer","branching"]', 'Camera', 'number', 4, 16, '{"schemaVersion":9,"title":"Photography order","description":"Book a new photo session or order prints and files from a past shoot.","blocks":[{"id":"blk_photogra00","ref":"welcome","title":"Hi! Let''s get your photography order sorted.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_photogra01","ref":"contact","title":"Your details first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_photogra02","ref":"order_kind","title":"What are you ordering?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_new_photo","label":"A new photo session","image_key":null},{"id":"opt_prints_or_files","label":"Prints or files from a past session","image_key":null}],"allowOther":false},{"id":"blk_photogra03","ref":"session_type","title":"What kind of session?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_portraits_or_headshots","label":"Portraits or headshots","image_key":null},{"id":"opt_family","label":"Family","image_key":null},{"id":"opt_couple_or_engagement","label":"Couple or engagement","image_key":null},{"id":"opt_newborn","label":"Newborn","image_key":null},{"id":"opt_event","label":"Event","image_key":null},{"id":"opt_product_or_brand","label":"Product or brand","image_key":null}],"allowOther":true},{"id":"blk_photogra04","ref":"package","title":"Which package would you like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_mini","label":"Mini","description":"A short session and a small set of edited images","image_key":null},{"id":"opt_standard","label":"Standard","description":"A full session with a larger edited set","image_key":null},{"id":"opt_full_coverage","label":"Full coverage","description":"Extended time, every usable image edited","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","description":"We''ll suggest one from your answers","image_key":null}],"allowOther":false},{"id":"blk_photogra05","ref":"session_date","title":"When would you like the session?","description":"We''ll confirm once we''ve checked availability and light.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_photogra06","ref":"location","title":"Where should we shoot?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_the_studio","label":"In the studio","image_key":null},{"id":"opt_at_my_home","label":"At my home or business","image_key":null},{"id":"opt_outdoors_at_a","label":"Outdoors, at a place I''ll suggest","image_key":null},{"id":"opt_i_d_like","label":"I''d like a recommendation","image_key":null}],"allowOther":false},{"id":"blk_photogra07","ref":"subjects","title":"How many people, pets or products will be in front of the camera?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":50