VALUES ('tpl_salesperformanceevaluati', 'sales-performance-evaluation-form', 'Sales performance evaluation form', 'Form', 'A manager''s review of one rep: the number, the skills behind it and the support they need next.', 'Separates the result from the skills that produced it, so a strong rep in a thin territory is not judged the same as a weak rep in a rich one. The target question decides the follow-up: a miss is asked what got in the way, a beat is asked what worked, and every review ends with one skill to build and the support that would help most.', '["other","sales performance review","sales evaluation","quota attainment","sales coaching","branching"]', 'TrendingUp', 'text', 4, 15, '{"schemaVersion":9,"title":"Sales performance review","description":"A manager''s review of one rep: the number, the skills behind it and the support they need next.","blocks":[{"id":"blk_salesper00","ref":"welcome","title":"Let''s review this period. Plan on five minutes, and have their numbers to hand.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_salesper01","ref":"rep_name","title":"Which salesperson are you reviewing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_salesper02","ref":"period","title":"Which period does this review cover?","description":"For example: Q3, or January to June.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_salesper03","ref":"sales_role","title":"What''s their role?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_sales_development_rep","label":"Sales development rep","image_key":null},{"id":"opt_account_executive","label":"Account executive","image_key":null},{"id":"opt_account_manager","label":"Account manager","image_key":null},{"id":"opt_sales_manager","label":"Sales manager","image_key":null},{"id":"opt_other_sales_role","label":"Other sales role","image_key":null}]},{"id":"blk_salesper04","ref":"attainment","title":"What percentage of their target did they reach?","description":"Leave it blank if they don''t carry a number yet.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":1000,"integerOnly":false},{"id":"blk_salesper05","ref":"target_result","title":"How did that compare with what was expected?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_beat_it","label":"Beat it","image_key":null},{"id":"opt_met_it","label":"Met it","image_key":null},{"id":"opt_fell_short","label":"Fell short","image_key":null},{"id":"opt_still_ramping_no","label":"Still ramping, no target yet","image_key":null}],"allowOther":false},{"id":"blk_salesper06","ref":"what_worked","title":"What did they do that others on the team could copy?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_salesper07","ref":"shortfall_reasons","title":"What got in the way?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_not_enough_pipeline","label":"Not enough pipeline","image_key":null},{"id":"opt_deals_slipped_into","label":"Deals slipped into next period","image_key":null},{"id":"opt_lost_to_a","label":"Lost to a competitor","image_key":null},{"id":"opt_territory_or_account","label":"Territory or account changes","image_key":null},{"id":"opt_gaps_in_the","label":"Gaps in the product","image_key":null},{"id":"opt_skills_still_developing","label":"Skills still developing","image_key":null},{"id":"opt_personal_circumsta