VALUES ('tpl_360degreefeedbackform', '360-degree-feedback-form', '360 degree feedback form', 'Form', 'Feedback on one person from the people around them, with examples, not just scores.', 'Asks every reviewer the same core questions so answers can be compared across managers, peers and direct reports. People who report to the person also rate their leadership, a question the others skip. The keep, start and stop prompts pull out specific examples, and a short follow-up asks for one whenever an answer is too vague to act on.', '["other","360 degree feedback","peer review","performance review","leadership feedback","branching"]', 'Users', 'text', 4, 11, '{"schemaVersion":9,"title":"360 degree feedback","description":"Feedback on one person from the people around them, with examples, not just scores.","blocks":[{"id":"blk_360degre00","ref":"welcome","title":"You''ve been asked for feedback on a colleague. Honest and specific is the most useful thing you can give.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_360degre01","ref":"subject","title":"Who are you giving feedback about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_360degre02","ref":"relationship","title":"How do you work with them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_m_their","label":"I''m their manager","image_key":null},{"id":"opt_we_re_peers","label":"We''re peers","image_key":null},{"id":"opt_they_manage_me","label":"They manage me","image_key":null},{"id":"opt_i_work_with","label":"I work with them from another team","image_key":null}],"allowOther":false},{"id":"blk_360degre03","ref":"leadership","title":"As your manager, how often do they do these things?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_make_priorities","label":"Make priorities clear"},{"id":"opt_row_give_useful","label":"Give useful feedback"},{"id":"opt_row_back_the","label":"Back the team when it counts"},{"id":"opt_row_make_time","label":"Make time for one-to-ones"},{"id":"opt_row_help_me","label":"Help me grow"}],"columns":[{"id":"opt_col_rarely","label":"Rarely"},{"id":"opt_col_sometimes","label":"Sometimes"},{"id":"opt_col_often","label":"Often"},{"id":"opt_col_almost_always","label":"Almost always"}],"multiplePerRow":false},{"id":"blk_360degre04","ref":"how_long","title":"How long have you worked with them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_3","label":"Less than 3 months","image_key":null},{"id":"opt_3_to_12","label":"3 to 12 months","image_key":null},{"id":"opt_1_to_3","label":"1 to 3 years","image_key":null},{"id":"opt_more_than_3","label":"More than 3 years","image_key":null}],"allowOther":false},{"id":"blk_360degre05","ref":"competencies","title":"How often do you see them do each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_communicate_clearly","label":"Communicate clearly"},{"id":"opt_row_collaborate_and","label":"Collaborate and share credit"},{"id":"opt_row_deliver_what","label":"Deliver what they promise"},{"id":"opt_row_solve_problems","label":"Solve problems without being asked"},{"id":"opt_row_take_feedback","label":"Take feedback well"},{"id":"opt_row_treat_people","label":"Treat people with respect"}],"columns":[{"id":"opt_col_rarely","label":"Rarely"},{"id":"opt_col_sometimes","label":"Sometimes"},{"id":"opt_col_often","label":"Often"},{"id":"opt_col_almost_always","label":"Almost always"}],"multiplePerRow":false},{"id":"blk_360degre06","ref":"keep_doing","title":"What should they keep doing? Give an example if you can.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_360degre07","ref":"start_doing","title":"What''s one thing they should start doing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_360degre08","ref":"stop_doing","title":"Is there anything they should stop doing?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_360degre09","ref":"effectiveness","title":"Overall, how effective are they in their role?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not effective","labelHigh":"Highly effective"},{"id":"blk_360degre10","ref":"attribution","title":"Can we show your name next to your feedback?","description":"Say no and your answers are shared only as part of a summary.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, name me","noLabel":"No, keep it unnamed"},{"id":"blk_360degre11","ref":"reviewer_name","title":"What name should appear next to your feedback?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120}],"endings":[{"id":"end_360degre01","ref":"end_thanks","title":"Thank you for your feedback","bodyMd":"It will be combined with everyone else''s and discussed with them as part of their development plan.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_360degre01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"relationship"},"op":"eq","value":"opt_they_m