VALUES ('tpl_ghiblistyleform', 'ghibli-style-form', 'Ghibli style form', 'Form', 'Take illustration requests for soft, hand-painted anime-style portraits and scenes.', 'For artists who take commissions in the gentle, painterly style people associate with classic hand-drawn anime films. Clients who want a portrait, a pet or a place are asked for reference photos, while original scenes get space to describe them. Anyone ordering for business use is asked where it will appear, so the licence is clear before you start.', '["other","ghibli style art","anime portrait commission","illustration request","art commission","branching"]', 'Paintbrush', 'text', 4, 13, '{"schemaVersion":9,"title":"Ghibli-style art request","description":"Take illustration requests for soft, hand-painted anime-style portraits and scenes.","blocks":[{"id":"blk_ghiblist00","ref":"welcome","title":"Hello! Tell me about the picture you''d like and I''ll see how I can bring it to life.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_ghiblist01","ref":"name","title":"What should I call you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_ghiblist02","ref":"subject","title":"What would you like drawn?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_me_a_friend","label":"Me, a friend or my family","image_key":null},{"id":"opt_a_couple","label":"A couple","image_key":null},{"id":"opt_a_pet","label":"A pet","image_key":null},{"id":"opt_my_home_or","label":"My home or a place I love","image_key":null},{"id":"opt_an_original_scene","label":"An original scene I''ll describe","image_key":null}],"allowOther":false},{"id":"blk_ghiblist03","ref":"scene","title":"Describe the scene. What''s happening, and where?","description":"Time of day, the weather, who or what is in it, and the feeling you want it to have.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_ghiblist04","ref":"references","title":"Add reference photos, up to five.","description":"Clear faces, outfits, a pet''s markings or the view you want. For an original scene, add anything that shows the look you''re after, or skip it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*"],"maxFiles":5,"maxSizeMB":15},{"id":"blk_ghiblist05","ref":"details","title":"Any details I mustn''t miss?","description":"Names, a favourite jumper, a scar, a toy, a colour someone always wears.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_ghiblist06","ref":"mood","title":"Pick up to three settings or moods you''d love.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_sunny_meadow_and","label":"Sunny meadow and tall clouds","image_key":null},{"id":"opt_cosy_kitchen_or","label":"Cosy kitchen or bakery","image_key":null},{"id":"opt_rainy_day_at","label":"Rainy day at a bus stop","image_key":null},{"id":"opt_seaside_town","label":"Seaside town","image_key":null},{"id":"opt_mossy_forest_path","label":"Mossy forest path","image_key":null},{"id":"opt_night_sky_and","label":"Night sky and lanterns","image_key":null},{"id":"opt_summer_train_ride","label":"Summer train ride","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":false},{"id":"blk_ghiblist07","ref":"palette","title":"How should the colours feel?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Soft and pastel","labelHigh":"Rich and bright"},{"id":"blk_ghiblist08","ref":"format","title":"What would you like to receive?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_digital_file","label":"A digital file","image_key":null},{"id":"opt_a_digital_file_2","label":"A digital file and a print","image_key":null},{"id":"opt_a_file_big","label":"A file big enough for a poster","image_key":null}],"allowOther":false},{"id":"blk_ghiblist09","ref":"purpose","title":"What''s it for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_gift","label":"A gift","image_key":null},{"id":"opt_just_for_me","label":"Just for me","image_key":null},{"id":"opt_a_profile_picture","label":"A profile picture","image_key":null},{"id":"opt_wedding_or_event","label":"Wedding or event stationery","image_key":null},{"id":"opt_my_business","label":"My business","image_key":null}],"allowOther":false},{"id":"blk_ghiblist10","ref":"business_use","title":"Where will the art appear?","description":"Website, packaging, social posts, printed merchandise. It helps me price the right licence.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_ghiblist11","ref":"deadline","title":"Is there a date you need it by?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_ghiblist12","ref":"email","title":"Where should I send sketches and a quote?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_ghiblist13","ref":"share_ok","title":"Can I share the finished piece on my portfolio and social pages?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"}],"endings":[{"id":"end_ghiblist01","ref":"end_thanks","title":"Thank you, this sounds lovely 🌿","bodyMd":"I''ll look through your references and reply with a rough sketch idea, a price and a date I can finish by.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_ghiblist01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"subject"},"op":"eq","value":"opt_an_original_scene"}],"groups":[]},"from":"subject","target":"scene","targetKind":"block","branch":"true"},{"id":"rl_ghiblist02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"subject"},"op":"eq","value":"opt_me_a_friend"}],"groups":[]},"from":"subject","target":"references","targetKind":"block","branch":"true"},{"id":"rl_ghiblist03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"subject"},"op":"eq","value":"opt_a_couple"}],"groups":[]},"from":"subject","target":"references","targetKind":"block","branch":"true"},{"id":"rl_ghiblist04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"subject"},"op":"eq","value":"opt_a_pet"}],"groups":[]},"from":"subject","target":"references","targetKind":"block","branch":"true"},{"id":"rl_ghiblist05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"subject"},"op":"eq","value":"opt_my_home_or"}],"groups":[]},"from":"subject","target":"references","targetKind":"block","branch":"true"},{"id":"rl_ghiblist06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"purpose"},"op":"eq","value":"opt_my_business"}],"groups":[]},"from":"purpose","target":"business_use","targetKind":"block","branch":"true"},{"id":"rl_ghiblist07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"purpose"},"op":"eq","value":"opt_a_gift"}],"groups":[]},"from":"purpose","target":"deadline","targetKind":"block","branch":"true"},{"id":"rl_ghiblist08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"purpose"},"op":"eq","value":"opt_just_for_me"}],"groups":[]},"from":"purpose","target":"deadline","targetKind":"block","branch":"true"},{"id":"rl_ghiblist09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"purpose"},"op":"eq","value":"opt_a_profile_picture"}],"groups":[]},"from":"purpose","target":"deadline","targetKind":"block","branch":"true"},{"id":"rl_ghiblist10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"purpose"},"op":"eq","value":"opt_wedding_or_event"}],"groups":[]},"from":"purpose","target":"deadline","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#d9f2e6","surface":"#ffffff","text":"#12342a","accent":"#0f766e","accentText":"#f5fffb","botBubble":"#ffffff","userBubble":"#0f766e","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"plus","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
