VALUES ('tpl_employeeonboarding', 'employee-onboarding', 'Employee onboarding form', 'Form', 'Collect what a new starter needs before day one.', 'The details that otherwise arrive as five separate emails in the first week: legal name, contact details, kit, an emergency contact and a signature on the handbook. Remote starters get shipping and home-setup questions, office starters pick their site and say how they''ll commute, and hybrid starters choose an office and get the home-setup questions too.', '["other","employee onboarding","new hire form","people ops","pre-boarding","branching"]', 'UserCheck', 'text', 5, 18, '{"schemaVersion":9,"title":"Employee onboarding","description":"Collect what a new starter needs before day one.","blocks":[{"id":"blk_employee00","ref":"welcome","title":"Welcome aboard! A few details so everything''s ready on your first day.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_employee01","ref":"legal_name","title":"What''s your full legal name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_employee02","ref":"preferred_name","title":"What name and pronouns should we use in the team directory?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_employee03","ref":"personal_email","title":"A personal email we can reach you on before you start","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_employee04","ref":"phone","title":"Your mobile number?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_employee05","ref":"start_date","title":"Please confirm your start date.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_employee06","ref":"work_location","title":"Where will you be working from?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_remote","label":"Remote","image_key":null},{"id":"opt_the_office","label":"The office","image_key":null},{"id":"opt_a_bit_of","label":"A bit of both","image_key":null}],"allowOther":false},{"id":"blk_employee07","ref":"office_site","title":"Which office?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_head_office","label":"Head office","image_key":null},{"id":"opt_north_office","label":"North office","image_key":null},{"id":"opt_south_office","label":"South office","image_key":null}]},{"id":"blk_employee08","ref":"commute","title":"How will you get in?","description":"So we know whether to sort a parking space or a bike rack.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_public_transport","label":"Public transport","image_key":null},{"id":"opt_driving","label":"Driving","image_key":null},{"id":"opt_cycling","label":"Cycling","image_key":null},{"id":"opt_walking","label":"Walking","image_key":null}],"allowOther":false},{"id":"blk_employee09","ref":"hybrid_office","title":"Which office will you use on office days?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_head_office","label":"Head office","image_key":null},{"id":"opt_north_office","label":"North office","image_key":null},{"id":"opt_south_office","label":"South office","image_key":null}]},{"id":"blk_employee10","ref":"shipping_address","title":"Where should we ship your kit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","state","postal","country"],"location":"off"},{"id":"blk_employee11","ref":"home_setup","title":"What do you already have at home?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_external_monitor","label":"External monitor","image_key":null},{"id":"opt_keyboard_and_mouse","label":"Keyboard and mouse","image_key":null},{"id":"opt_a_decent_desk","label":"A decent desk chair","image_key":null},{"id":"opt_headset","label":"Headset","image_key":null},{"id":"opt_webcam","label":"Webcam","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_employee12","ref":"equipment","title":"Which laptop would you like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_mac","label":"Mac","image_key":null},{"id":"opt_windows","label":"Windows","image_key":null},{"id":"opt_linux","label":"Linux","image_key":null},{"id":"opt_no_preference","label":"No preference","image_key":null}],"allowOther":false},{"id":"blk_employee13","ref":"tshirt","title":"T-shirt size, for the welcome pack?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_xs","label":"XS","image_key":null},{"id":"opt_s_2","label":"S","image_key":null},{"id":"opt_m_3","label":"M","image_key":null},{"id":"opt_l_4","label":"L","image_key":null},{"id":"opt_xl","label":"XL","image_key":null},{"id":"opt_xxl","label":"XXL","image_key":null}],"allowOther":false},{"id":"blk_employee14","ref":"dietary","title":"Any dietary needs for team lunches?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_employee15","ref":"emergency_name","title":"Who should we contact in an emergency, and how are they related to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_employee16","ref":"emergency_phone","title":"Their phone number?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_employee17","ref":"accessibility","title":"Is there anything we should set up so work works well for you?","description":"Adjustments, equipment, working hours. Only your manager and HR will see this.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_employee18","ref":"handbook","title":"Sign to confirm you''ve read the employee handbook.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"signature","drawnNameRequired":true}],"endings":[{"id":"end_employee01","ref":"end_thanks","title":"All set 🎊","bodyMd":"See you on day one. We''ll email your first-week schedule shortly.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_employee01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"commute","target":"equipment","targetKind":"block"},{"id":"rl_employee02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"work_location"},"op":"eq","value":"opt_remote"}],"groups":[]},"from":"work_location","target":"shipping_address","targetKind":"block","branch":"true"},{"id":"rl_employee03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"work_location"},"op":"eq","value":"opt_the_office"}],"groups":[]},"from":"work_location","target":"office_site","targetKind":"block","branch":"true"},{"id":"rl_employee04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"work_location"},"op":"eq","value":"opt_a_bit_of"}],"groups":[]},"from":"work_location","target":"hybrid_office","targetKind":"block","branch":"true"},{"id":"rl_employee05","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"hybrid_office","target":"home_setup","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffe4d3","surface":"#ffffff","text":"#3a2418","accent":"#c2410c","accentText":"#fffaf5","botBubble":"#ffffff","userBubble":"#c2410c","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
