VALUES ('tpl_referralsubmission', 'referral-submission', 'Employee referral form', 'Form', 'Put a candidate forward with their name, the role and one honest reason they fit.', 'Kept short on purpose, because people stop referring when it feels like paperwork. The candidate''s name, the role and one honest reason are enough for a recruiter to act on. When the candidate already knows, the form asks how to reach them; when they don''t, it takes the referrer''s word that they''ll check first, rather than contact details they shouldn''t be sharing.', '["other","employee referral","referral program","hiring","recruiting","branching"]', 'UserPlus', 'text', 4, 12, '{"schemaVersion":9,"title":"Employee referral","description":"Put a candidate forward with their name, the role and one honest reason they fit.","blocks":[{"id":"blk_referral00","ref":"welcome","title":"Know someone great? Put them forward. It only takes a few minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_referral01","ref":"referrer","title":"First, your name and work email, so we can keep you posted.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_referral02","ref":"referrer_team","title":"Which team are you on?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_referral03","ref":"candidate_name","title":"Who are you referring?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_referral04","ref":"role","title":"Which role are you referring them for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_engineering","label":"Engineering","image_key":null},{"id":"opt_design","label":"Design","image_key":null},{"id":"opt_product","label":"Product","image_key":null},{"id":"opt_sales","label":"Sales","image_key":null},{"id":"opt_marketing","label":"Marketing","image_key":null},{"id":"opt_operations","label":"Operations","image_key":null},{"id":"opt_no_specific_role","label":"No specific role yet","image_key":null}]},{"id":"blk_referral05","ref":"worked_together","title":"How do you know them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_we_worked_together","label":"We worked together directly","image_key":null},{"id":"opt_same_company_different","label":"Same company, different team","image_key":null},{"id":"opt_through_a_community","label":"Through a community or event","image_key":null},{"id":"opt_personally","label":"Personally","image_key":null}],"allowOther":false},{"id":"blk_referral06","ref":"has_consent","title":"Do they know you''re referring them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, they''re expecting it","noLabel":"Not yet"},{"id":"blk_referral07","ref":"candidate_contact","title":"How can we reach them? An email or profile link is fine.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_referral08","ref":"best_approach","title":"How should we get in touch?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_an_email_from","label":"An email from a recruiter","image_key":null},{"id":"opt_a_message_on","label":"A message on a professional network","image_key":null},{"id":"opt_i_ll_introduce","label":"I''ll introduce us","image_key":null}],"allowOther":false},{"id":"blk_referral09","ref":"cv","title":"Have their CV? Attach it here.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["application/pdf","application/msword","application/vnd.openxmlformats-officedocument.wordprocessingml.document"],"maxFiles":1,"maxSizeMB":10},{"id":"blk_referral10","ref":"will_ask","title":"Will you ask them first?","description":"We won''t contact anyone who hasn''t agreed to it.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, I''ll check with them","noLabel":"No, just log it for now"},{"id":"blk_referral11","ref":"why","title":"Why would they be good here?","description":"One specific thing you''ve seen them do beats a list of adjectives.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_referral12","ref":"strength","title":"How strongly would you vouch for them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Worth a look","labelHigh":"Hire them tomorrow"}],"endings":[{"id":"end_referral01","ref":"end_thanks","title":"Thanks for the referral 🙌","bodyMd":"A recruiter will take it from here, and we''ll let you know how it goes.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_referral01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"cv","target":"why","targetKind":"block"},{"id":"rl_referral02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_consent"},"op":"eq","value":true}],"groups":[]},"from":"has_consent","target":"candidate_contact","targetKind":"block","branch":"true"},{"id":"rl_referral03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_consent"},"op":"eq","value":false}],"groups":[]},"from":"has_consent","target":"will_ask","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#f26b1d","surface":"#fff7f0","text":"#1c1917","accent":"#1c1917","accentText":"#ffffff","botBubble":"#fff7f0","userBubble":"#1c1917","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundPatternColor":"#1c1917","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
