VALUES ('tpl_marketingquoteform', 'marketing-quote-form', 'Marketing quote form', 'Form', 'Scope a campaign or a retainer well enough to send a real estimate.', 'Built for agencies and freelance marketers who are tired of quoting from a one-line enquiry. A one-off campaign is asked about launch date and length, a monthly retainer about who runs marketing today and how long they want to commit, so each estimate starts from the facts that actually move the price.', '["quote","marketing quote","agency estimate","campaign pricing","retainer","branching"]', 'Megaphone', 'advanced', 4, 14, '{"schemaVersion":9,"title":"Marketing quote","description":"Scope a campaign or a retainer well enough to send a real estimate.","blocks":[{"id":"blk_marketin00","ref":"welcome","title":"Tell us what you''re planning and we''ll put together an estimate for you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_marketin01","ref":"contact","title":"First, who are we preparing this for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_marketin02","ref":"company","title":"What''s the business called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_marketin03","ref":"website","title":"Where can we see the brand today?","description":"Your website, or a social profile if there''s no site yet.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_marketin04","ref":"services","title":"Which services should the estimate cover?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_paid_ads","label":"Paid ads","image_key":null},{"id":"opt_seo","label":"SEO","image_key":null},{"id":"opt_social_media_management","label":"Social media management","image_key":null},{"id":"opt_content_and_copywriting","label":"Content and copywriting","image_key":null},{"id":"opt_email_marketing","label":"Email marketing","image_key":null},{"id":"opt_branding_and_design","label":"Branding and design","image_key":null},{"id":"opt_video_and_motion","label":"Video and motion","image_key":null},{"id":"opt_strategy_only","label":"Strategy only","image_key":null}],"minSelections":1,"maxSelections":8,"allowOther":false},{"id":"blk_marketin05","ref":"engagement","title":"Is this a one-off piece of work or ongoing support?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_one_off","label":"A one-off campaign or project","image_key":null},{"id":"opt_ongoing_monthly_support","label":"Ongoing monthly support","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}],"allowOther":false},{"id":"blk_marketin06","ref":"launch_date","title":"When would you like the campaign to go live?","description":"A rough date is fine. It tells us how much time there is to build it.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_marketin07","ref":"campaign_length","title":"And how long should it run?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_a_month","label":"Under a month","image_key":null},{"id":"opt_one_to_three","label":"One to three months","image_key":null},{"id":"opt_three_to_six","label":"Three to six months","image_key":null},{"id":"opt_longer","label":"Longer","image_key":null}],"allowOther":false},{"id":"blk_marketin08","ref":"current_team","title":"Who looks after marketing at the moment?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_nobody_yet","label":"Nobody yet","image_key":null},{"id":"opt_the_founder_or","label":"The founder or owner","image_key":null},{"id":"opt_someone_in_house","label":"Someone in-house","image_key":null},{"id":"opt_another_agency","label":"Another agency","image_key":null}],"allowOther":false},{"id":"blk_marketin09","ref":"commitment","title":"How long would you give it before reviewing results?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_three_months","label":"Three months","image_key":null},{"id":"opt_six_months","label":"Six months","image_key":null},{"id":"opt_a_year","label":"A year","image_key":null},{"id":"opt_open_ended","label":"Open-ended","image_key":null}],"allowOther":false},{"id":"blk_marketin10","ref":"priorities","title":"Put these in order of what matters most to you","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_more_leads","label":"More leads or sales"},{"id":"opt_item_brand_awareness","label":"Brand awareness"},{"id":"opt_item_website_traffic","label":"Website traffic"},{"id":"opt_item_engagement_with","label":"Engagement with existing customers"}]},{"id":"blk_marketin11","ref":"brief","title":"Tell us about the product, the audience and anything you''ve already tried","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_marketin12","ref":"budget","title":"What budget range are you working with for our fees?","description":"Ad spend is separate, so leave it out of this number.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_2k","label":"Under $2k","image_key":null},{"id":"opt_2k_5k","label":"$2k–$5k","image_key":null},{"id":"opt_5k_15k","label":"$5k–$15k","image_key":null},{"id":"opt_over_15k","label":"Over $15k","image_key":null},{"id":"opt_not_sure_suggest","label":"Not sure, suggest something","image_key":null}],"allowOther":false},{"id":"blk_marketin13","ref":"references","title":"Anything we should look at? Past campaigns, brand guides, examples you like.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":10},{"id":"blk_marketin14","ref":"phone","title":"A phone number, in case a quick call is easier","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false}],"endings":[{"id":"end_marketin01","ref":"end_thanks","title":"Got it, your estimate is on its way","bodyMd":"We''ll review everything and send a proposal, or a couple of questions if something needs clearing up first.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_marketin01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"campaign_length","target":"priorities","targetKind":"block"},{"id":"rl_marketin02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"engagement"},"op":"eq","value":"opt_a_one_off"}],"groups":[]},"from":"engagement","target":"launch_date","targetKind":"block","branch":"true"},{"id":"rl_marketin03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"engagement"},"op":"eq","value":"opt_ongoing_monthly_support"}],"groups":[]},"from":"engagement","target":"current_team","targetKind":"block","branch":"true"},{"id":"rl_marketin04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"engagement"},"op":"eq","value":"opt_not_sure_yet"}],"groups":[]},"from":"engagement","target":"priorities","targetKind":"block","branch":"true"},{"id":"rl_marketin05","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"commitment","target":"brief","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
