VALUES ('tpl_electricalquoteform', 'electrical-quote-form', 'Electrical quote form', 'Form', 'Get enough detail on an electrical job to price it or plan a visit.', 'Written for electricians and small contracting firms. The first question checks for danger, and anyone describing sparks, burning or a shock is sent straight to urgent advice instead of a quote queue. Faults get asked how far the problem spreads; new work gets asked what and how much, and everyone is asked for photos of the fuse board.', '["quote","electrical quote","electrician estimate","electrical job request","contractor","branching"]', 'Zap', 'advanced', 4, 12, '{"schemaVersion":9,"title":"Electrical quote","description":"Get enough detail on an electrical job to price it or plan a visit.","blocks":[{"id":"blk_electric00","ref":"welcome","title":"Need an electrician? Tell us about the job and we''ll come back with a price or a time to look.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_electric01","ref":"danger","title":"First, a safety check: is anything sparking, smelling of burning, or has anyone had a shock?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, it has","noLabel":"No, nothing like that"},{"id":"blk_electric02","ref":"work_type","title":"What kind of work is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_something_isn_t","label":"Something isn''t working","image_key":null},{"id":"opt_new_sockets_lights","label":"New sockets, lights or circuits","image_key":null},{"id":"opt_rewire_or_fuse","label":"Rewire or fuse board upgrade","image_key":null},{"id":"opt_ev_charger_installation","label":"EV charger installation","image_key":null},{"id":"opt_inspection_or_safety","label":"Inspection or safety certificate","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_electric03","ref":"fault_details","title":"What''s happening, and when did it start?","description":"For example: a breaker keeps tripping, lights flicker, one socket is dead.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_electric04","ref":"fault_scope","title":"How much of the property is affected?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_one_socket_or","label":"One socket or light","image_key":null},{"id":"opt_one_room","label":"One room","image_key":null},{"id":"opt_several_rooms","label":"Several rooms","image_key":null},{"id":"opt_the_whole_property","label":"The whole property","image_key":null}],"allowOther":false},{"id":"blk_electric05","ref":"work_details","title":"Describe the work: what you''d like, where, and how many of each","description":"For example: six downlights in the kitchen and two double sockets in the garage.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_electric06","ref":"property_type","title":"What kind of property is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_house","label":"House","image_key":null},{"id":"opt_flat_or_apartment","label":"Flat or apartment","image_key":null},{"id":"opt_office","label":"Office","image_key":null},{"id":"opt_shop_restaurant_or","label":"Shop, restaurant or other commercial space","image_key":null},{"id":"opt_industrial_unit","label":"Industrial unit","image_key":null}],"allowOther":false},{"id":"blk_electric07","ref":"wiring_age","title":"Roughly how old is the wiring?","description":"It helps us know what we might find behind the walls.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_10","label":"Less than 10 years","image_key":null},{"id":"opt_10_to_30","label":"10 to 30 years","image_key":null},{"id":"opt_over_30_years","label":"Over 30 years","image_key":null},{"id":"opt_no_idea","label":"No idea","image_key":null}],"allowOther":false},{"id":"blk_electric08","ref":"photos","title":"Can you add photos of the fuse board and the area you need work on?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","video/*"],"maxFiles":5,"maxSizeMB":10},{"id":"blk_electric09","ref":"address","title":"Where''s the property?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal"],"location":"off"},{"id":"blk_electric10","ref":"access","title":"Anything we should know about getting in? Parking, keys, pets, a tenant to call first.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_electric11","ref":"preferred_date","title":"When would suit you for the work?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_electric12","ref":"contact","title":"How do we reach you with the quote?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","phone","email"]}],"endings":[{"id":"end_electric01","ref":"end_thanks","title":"Thanks, we''ve got your job details","bodyMd":"We''ll look through everything and send a price, or suggest a visit if we need to see it first.","imageUrl":null,"redirectDelay