VALUES ('tpl_freelancequoteform', 'freelance-quote-form', 'Freelance quote form', 'Form', 'Everything a freelancer needs to price a project before the first call.', 'For designers, writers, developers and other freelancers who quote project by project. It asks the things that quietly change a price, such as where the work will be used, whether the deadline is fixed and how many people sign it off, and when a client wants changes to something that already exists, it asks to see it. Work signed off by a committee also asks who settles disagreements, which is where revision rounds multiply.', '["quote","freelance quote","project estimate","freelancer","client intake","branching"]', 'Briefcase', 'advanced', 4, 13, '{"schemaVersion":9,"title":"Freelance quote","description":"Everything a freelancer needs to price a project before the first call.","blocks":[{"id":"blk_freelanc00","ref":"welcome","title":"Hi! Tell me about your project and I''ll send you a quote.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_freelanc01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_freelanc02","ref":"email","title":"And the best email for the quote?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_freelanc03","ref":"builds_on_existing","title":"Does this build on work that already exists, like a site, a draft or an earlier design?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, there''s something already","noLabel":"No, it''s new"},{"id":"blk_freelanc04","ref":"existing_link","title":"Where can I see what exists now?","description":"A link to the site, file or document is perfect.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_freelanc05","ref":"deliverables","title":"What do you need made? List the pieces as you see them.","description":"For example: a homepage and three inner pages, or ten product descriptions.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_freelanc06","ref":"usage","title":"Where will the work be used?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_website_or_app","label":"Website or app","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_paid_advertising","label":"Paid advertising","image_key":null},{"id":"opt_print","label":"Print","image_key":null},{"id":"opt_internal_use_only","label":"Internal use only","image_key":null},{"id":"opt_resold_or_given","label":"Resold or given to clients","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_freelanc07","ref":"references","title":"Any examples you like, or links I should look at?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_freelanc08","ref":"deadline","title":"When do you need it finished?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_freelanc09","ref":"deadline_fixed","title":"Is that date fixed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, it can''t move","noLabel":"No, there''s some room"},{"id":"blk_freelanc10","ref":"approvers","title":"Who will sign off on the work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_me_and_one","label":"Me and one other person","image_key":null},{"id":"opt_a_team_or","label":"A team or a committee","image_key":null}],"allowOther":false},{"id":"blk_freelanc11","ref":"final_say","title":"When the feedback disagrees, who has the final say?","description":"A name and role is enough. It tells me who to check with before each round.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":160},{"id":"blk_freelanc12","ref":"budget","title":"Do you have a budget in mind?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_1_000","label":"Under $1,000","image_key":null},{"id":"opt_1_000_3","label":"$1,000–$3,000","image_key":null},{"id":"opt_3_000_8","label":"$3,000–$8,000","image_key":null},{"id":"opt_over_8_000","label":"Over $8,000","image_key":null},{"id":"opt_i_d_like","label":"I''d like your suggestion","image_key":null}],"allowOther":false},{"id":"blk_freelanc13","ref":"found_me","title":"Last one: how did you find me?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_referral","label":"A referral","image_key":null},{"id":"opt_search","label":"Search","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_my_portfolio","label":"My portfolio","image_key":null}],"allowOther":true}],"endings":[{"id":"end_freelanc01","ref":"end_thanks","title":"Thanks, that''s everything I need","bodyMd":"I''ll read it properly and send you a quote, with any questions I have, within two working days.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_freelanc01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"builds_on_existing"},"op":"eq","value":true}],"groups":[]},"from":"builds_on_existing","target":"existing_link","targetKind":"block","branch":"true"},{"id":"rl_freelanc02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"builds_on_existing"},"op":"eq","value":false}],"groups":[]},"from":"builds_on_existing","target":"deliverables","targetKind":"block","branch":"true"},{"id":"rl_freelanc03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"approvers"},"op":"eq","value":"opt_a_team_or"}],"groups":[]},"from":"approvers","target":"final_say","targetKind":"block","branch":"true"},{"id":"rl_freelanc04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"approvers"},"op":"eq","value":"opt_just_me"}],"groups":[]},"from":"approvers","target":"budget","targetKind":"block","branch":"true"},{"id":"rl_freelanc05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"approvers"},"op":"eq","value":"opt_me_and_one"}],"groups":[]},"from":"approvers","target":"budget","targetKind":"block","branch":"true"},{"id":"rl_freelanc06","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"existing_link","target":"usage","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turn