VALUES ('tpl_graphicdesignquoteform', 'graphic-design-quote-form', 'Graphic design quote form', 'Form', 'Scope a design job, from one flyer to a full identity, before quoting.', 'For graphic designers and small studios. Clients with a brand are asked to upload it; clients without one are asked what feel they''re after, so you know whether you''re designing a flyer or a whole identity. Anything going to print is asked for sizes and quantities, which is where design quotes most often go wrong.', '["quote","graphic design quote","design estimate","design brief","freelance designer","branching"]', 'Palette', 'advanced', 4, 14, '{"schemaVersion":9,"title":"Graphic design quote","description":"Scope a design job, from one flyer to a full identity, before quoting.","blocks":[{"id":"blk_graphicd00","ref":"welcome","title":"Looking for a designer? Tell me what you need and I''ll put a quote together.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_graphicd01","ref":"contact","title":"Who am I talking to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_graphicd02","ref":"company","title":"What''s the business or project called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_graphicd03","ref":"pieces","title":"What do you need designed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_logo","label":"Logo","image_key":null},{"id":"opt_full_brand_identity","label":"Full brand identity","image_key":null},{"id":"opt_social_media_graphics","label":"Social media graphics","image_key":null},{"id":"opt_flyer_or_poster","label":"Flyer or poster","image_key":null},{"id":"opt_brochure_or_booklet","label"