VALUES ('tpl_plumbingquoteform', 'plumbing-quote-form', 'Plumbing quote form', 'Form', 'Understand a plumbing job before you quote it or book a visit.', 'For plumbers and small plumbing firms. It opens with how urgent the job is, and anyone with water leaking right now is told to turn off the stopcock and call instead of joining the queue. Installations are asked who supplies the fittings, which is the question that most often changes the price.', '["quote","plumbing quote","plumber estimate","plumbing job request","contractor","branching"]', 'Wrench', 'advanced', 3, 10, '{"schemaVersion":9,"title":"Plumbing quote","description":"Understand a plumbing job before you quote it or book a visit.","blocks":[{"id":"blk_plumbing00","ref":"welcome","title":"Plumbing problem or a new job? Tell us about it and we''ll come back with a price.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_plumbing01","ref":"urgency","title":"How urgent is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_water_is_leaking","label":"Water is leaking or flooding right now","image_key":null},{"id":"opt_urgent_within_a","label":"Urgent, within a day or two","image_key":null},{"id":"opt_in_the_next","label":"In the next couple of weeks","image_key":null},{"id":"opt_just_planning_ahead","label":"Just planning ahead","image_key":null}],"allowOther":false},{"id":"blk_plumbing02","ref":"job_type","title":"What do you need help with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_leak_or","label":"A leak or drip","image_key":null},{"id":"opt_a_blocked_drain","label":"A blocked drain, sink or toilet","image_key":null},{"id":"opt_no_hot_water","label":"No hot water or heating","image_key":null},{"id":"opt_fitting_a_new","label":"Fitting a new tap, toilet or appliance","image_key":null},{"id":"opt_a_new_bathroom","label":"A new bathroom or kitchen","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_plumbing03","ref":"fittings","title":"Who''s supplying the fittings and fixtures?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_ve_bought","label":"I''ve bought them already","image_key":null},{"id":"opt_i_ll_buy","label":"I''ll buy them, I just need fitting","image_key":null},{"id":"opt_i_d_like","label":"I''d like you to supply them","image_key":null},{"id":"opt_not_decided_yet","label":"Not decided yet","image_key":null}],"allowOther":false},{"id":"blk_plumbing04","ref":"description","title":"Describe the job, including when the problem started if it''s a repair","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_plumbing05","ref":"property_type","title":"What kind of property is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_house","label":"House","image_key":null},{"id":"opt_flat_or_apartment","label":"Flat or apartment","image_key":null},{"id":"opt_office","label":"Office","image_key":null},{"id":"opt_shop_or_restaurant","label":"Shop or restaurant","image_key":null},{"id":"opt_other_commercial_building","label":"Other commercial building","image_key":null}],"allowOther":false},{"id":"blk_plumbing06","ref":"owner","title":"Are you the owner?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_i_own","label":"Yes, I own it","image_key":null},{"id":"opt_i_m_a","label":"I''m a tenant","image_key":null},{"id":"opt_i_manage_it","label":"I manage it for someone else","image_key":null}],"allowOther":false},{"id":"blk_plumbing07","ref":"photos","title":"Photos or a short video of the problem or the space help us quote faster","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","video/*"],"maxFiles":5,"maxSizeMB":10},{"id":"blk_plumbing08","ref":"address","title":"Where''s the property?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal"],"location":"off"},{"id":"blk_plumbing09","ref":"access","title":"When could we get in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_weekday_mornings","label":"Weekday mornings","image_key":null},{"id":"opt_weekday_afternoons","label":"Weekday afternoons","image_key":null},{"id":"opt_evenings","label":"Evenings","image_key":null},{"id":"opt_weekends","label":"Weekends","image_key":null}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_plumbing10","ref":"contact","title":"How should we get back to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","phone","email"]}],"endings":[{"id":"end_plumbing01","ref":"end_thanks","title":"Thanks, we''ll be in touch soon","bodyMd":"We''ll look over your details and photos, then call or email with a price or a time to come and look.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_plumbing02","ref":"end_emergency","title":"Turn off the water, then call us 🚰","bodyMd":"Shut off the water at the stopcock, usually under the kitchen sink or where the pipe comes into the building. If water is near electrics, keep clear of them. Then phone our emergency line so we can get someone out.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[