VALUES ('tpl_translationquoteform', 'translation-quote-form', 'Translation quote form', 'Form', 'Collect everything a translator needs to price a document.', 'For freelance translators and small agencies. It asks the details that set the rate: the language pair, the subject, the word count and whether the files are editable or scanned. Anything going to a court, embassy or government office is asked what kind of certified translation it needs, so nobody finds out too late.', '["quote","translation quote","translator estimate","certified translation","language services","branching"]', 'Languages', 'advanced', 4, 12, '{"schemaVersion":9,"title":"Translation quote","description":"Collect everything a translator needs to price a document.","blocks":[{"id":"blk_translat00","ref":"welcome","title":"Need something translated? Tell us about it and we''ll send you a quote.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_translat01","ref":"source_lang","title":"What language is the original in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_translat02","ref":"target_lang","title":"Which language or languages should it be translated into?","description":"If it''s more than one, list them all.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_translat03","ref":"subject","title":"What kind of material is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_personal_documents_like","label":"Personal documents, like certificates or IDs","image_key":null},{"id":"opt_legal_or_contracts","label":"Legal or contracts","image_key":null},{"id":"opt_business_or_marketing","label":"Business or marketing","image_key":null},{"id":"opt_website_or_app","label":"Website or app","image_key":null},{"id":"opt_technical_or_medical","label":"Technical or medical","image_key":null},{"id":"opt_academic","label":"Academic","image_key":null}],"allowOther":false},{"id":"blk_translat04","ref":"purpose","title":"What will the translation be used for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_to_understand","label":"Just to understand it","image_key":null},{"id":"opt_publishing_to_customers","label":"Publishing to customers or readers","image_key":null},{"id":"opt_submitting_to_a","label":"Submitting to a court, embassy or government office","image_key":null}],"allowOther":false},{"id":"blk_translat05","ref":"certification","title":"What does the receiving office ask for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_certified_translation","label":"A certified translation","image_key":null},{"id":"opt_a_sworn_or","label":"A sworn or notarised translation","image_key":null},{"id":"opt_i_m_not","label":"I''m not sure yet","image_key":null}],"allowOther":false},{"id":"blk_translat06","ref":"authority_country","title":"Which country is it being submitted in?","description":"Rules for official translations differ from country to country.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_translat07","ref":"word_count","title":"Roughly how many words is it?","description":"A guess is fine. If you only know the page count, allow about 250 words a page.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"integerOnly":true},{"id":"blk_translat08","ref":"format","title":"What format are the files in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_word_or_another","label":"Word or another editable file","image_key":null},{"id":"opt_pdf_with_selectable","label":"PDF with selectable text","image_key":null},{"id":"opt_scans_or_photos","label":"Scans or photos","image_key":null},{"id":"opt_website_or_app","label":"Website or app files","image_key":null}],"allowOther":false},{"id":"blk_translat09","ref":"files","title":"Upload the documents so we can check them before quoting","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["application/pdf","image/*",".doc",".docx",".txt",".xlsx",".pptx"],"maxFiles":10,"maxSizeMB":25},{"id":"blk_translat10","ref":"glossary","title":"Do you have a glossary or earlier translations we should match?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_translat11","ref":"deadline","title":"When do you need it back?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_translat12","ref":"contact","title":"Where should we send the quote?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]}],"endings":[{"id":"end_translat01","ref":"end_thanks","title":"Thanks, we''ll check the files and send a quote","bodyMd":"We''ll confirm the price, the delivery date and anything we need to clarify about the text.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_translat01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"purpose"},"op":"eq","value":"opt_submitting_to_a"}],"groups":[]},"from":"purpose","target":"certification","targetKind":"block","branch":"true"},{"id":"rl_translat02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"purpose"},"op":"eq","value":"opt_just_to_understand"}],"groups":[]},"from":"purpose","target":"word_count","targetKind":"block","branch":"true"},{"id":"rl_translat03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"purpose"},"op":"eq","value":"opt_publishing_to_customers"}],"groups":[]},"from":"purpose","target":"word_count","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allo