VALUES ('tpl_quoterequest', 'quote-request', 'Quote request form', 'Form', 'Scope a job well enough to price it without a call.', 'Most quote forms collect a name and a vague description, then cost you a discovery call anyway. This one asks the questions the price actually depends on, and those depend on the job: a new build is scoped differently from a redesign, and ongoing support differently again. The first reply can be a number.', '["quote","quote request","request a quote","pricing","services","branching"]', 'FileText', 'advanced', 4, 15, '{"schemaVersion":9,"title":"Quote request","description":"Scope a job well enough to price it without a call.","blocks":[{"id":"blk_quotereq00","ref":"welcome","title":"Tell us what you need and we''ll come back with a price.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_quotereq01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_quotereq02","ref":"email","title":"Where should we send the quote?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_quotereq03","ref":"company","title":"Company, if there is one?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_quotereq04","ref":"job_type","title":"What kind of work is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_new_build","label":"New build","image_key":null},{"id":"opt_redesign_of_something","label":"Redesign of something existing","image_key":null},{"id":"opt_ongoing_support","label":"Ongoing support","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_quotereq05","ref":"build_scale","title":"Roughly how big is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_single_page","label":"A single page or screen","image_key":null},{"id":"opt_a_handful_of","label":"A handful of pages","image_key":null},{"id":"opt_a_full_site","label":"A full site or product","image_key":null},{"id":"opt_i_genuinely_don","label":"I genuinely don''t know","image_key":null}],"allowOther":false},{"id":"blk_quotereq06","ref":"build_has_design","title":"Is there a design already?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, it''s ready","noLabel":"No, we''d need that too"},{"id":"blk_quotereq07","ref":"existing_url","title":"Link to what exists now","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_quotereq08","ref":"redesign_reason","title":"What''s driving the change?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_it_looks_dated","label":"It looks dated","image_key":null},{"id":"opt_it_doesn_t","label":"It doesn''t convert","image_key":null},{"id":"opt_it_s_hard","label":"It''s hard to maintain","image_key":null},{"id":"opt_the_business_has","label":"The business has changed","image_key":null}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_quotereq09","ref":"keep_content","title":"Are you keeping the existing content?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Mostly, yes","noLabel":"No, it''s all being rewritten"},{"id":"blk_quotereq10","ref":"support_hours","title":"How much help do you expect to need?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_few_hours","label":"A few hours a month","image_key":null},{"id":"opt_a_day_or","label":"A day or two a month","image_key":null},{"id":"opt_a_day_a","label":"A day a week","image_key":null},{"id":"opt_more_than_that","label":"More than that","image_key":null}],"allowOther":false},{"id":"blk_quotereq11","ref":"support_response","title":"How fast do you need us to respond?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_same_day","label":"Same day","image_key":null},{"id":"opt_within_two_days","label":"Within two days","image_key":null},{"id":"opt_within_a_week","label":"Within a week","image_key":null}],"allowOther":false},{"id":"blk_quotereq12","ref":"job_description","title":"Describe the job in your own words","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_quotereq13","ref":"budget","title":"What''s your budget range?","description":"A range is fine. It tells us what''s realistic.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_5k","label":"Under $5k","image_key":null},{"id":"opt_5k_15k","label":"$5k–$15k","image_key":null},{"id":"opt_15k_50k","label":"$15k–$50k","image_key":null},{"id":"opt_50k","label":"$50k+","image_key":null},{"id":"opt_i_d_rather","label":"I''d rather you suggest","image_key":null}],"allowOther":false},{"id":"blk_quotereq14","ref":"deadline","title":"When would you like it finished?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_quotereq15","ref":"attachments","title":"Anything to share? Briefs, drawings, screenshots.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":10}],"endings":[{"id":"end_quotereq01","ref":"end_thanks","title":"On it 📝","bodyMd":"You''ll have a quote within two working days.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_quotereq01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"build_has_design","target":"job_description","targetKind":"block"},{"id":"rl_quotereq02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"keep_content","target":"job_description","targetKind":"block"},{"id":"rl_quotereq03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"job_type"},"op":"eq","value":"opt_new_build"}],"groups":[]},"from":"job_type","target":"build_scale","targetKind":"block","branch":"true"},{"id":"rl_quotereq04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"job_type"},"op":"eq","value":"opt_redesign_of_something"}],"groups":[]},"from":"job_type","target":"existing_url","targetKind":"block","branch":"true"},{"id":"rl_quotereq05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"job_type"},"op":"eq","value":"opt_ongoing_support"}],"groups":[]},"from":"job_type","target":"support_hours","targetKind":"block","branch":"true"},{"id":"rl_quotereq06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"job_type"},"op":"eq","value":"opt_something_else"}],"groups":[]},"from":"job_type","target":"job_description","targetKind":"block","branch":"true"},{"id":"rl_quotereq07","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"support_response","target":"budget","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
