VALUES ('tpl_contestregistrationform', 'contest-registration-form', 'Contest registration form', 'Form', 'Register entrants and collect their entry in one conversation.', 'For competitions judged on submitted work, from writing and design contests to school and community challenges. Entrants under 18 are asked for a parent or guardian before they go on, team entries give a team name and size, and anyone who says the work isn''t their own is stopped politely before they upload it, so it never reaches your judges.', '["registration","contest registration","competition entry","contest entry form","submissions","branching"]', 'Trophy', 'contact', 4, 14, '{"schemaVersion":9,"title":"Contest registration","description":"Register entrants and collect their entry in one conversation.","blocks":[{"id":"blk_contestr00","ref":"welcome","title":"Ready to enter? This takes a few minutes, and you''ll upload your entry at the end.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_contestr01","ref":"contact","title":"First, your details so we can reach you about your entry","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_contestr02","ref":"adult","title":"Are you 18 or older?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_contestr03","ref":"guardian","title":"Please add a parent or guardian we can contact","description":"We''ll ask them to confirm your entry before judging.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_contestr04","ref":"entry_type","title":"Are you entering on your own or as a team?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_on_my_own","label":"On my own","image_key":null},{"id":"opt_as_a_team","label":"As a team","image_key":null}],"allowOther":false},{"id":"blk_contestr05","ref":"team_name","title":"What''s your team called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_contestr06","ref":"team_size","title":"How many people are in the team, including you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":2,"max":20,"integerOnly":true},{"id":"blk_contestr07","ref":"category","title":"Which category are you entering?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_open_category","label":"Open category","image_key":null},{"id":"opt_students","label":"Students","image_key":null},{"id":"opt_beginners","label":"Beginners","image_key":null}]},{"id":"blk_contestr08","ref":"original","title":"Is the entry entirely your own original work?","description":"For a team entry, work made together by the team counts.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, it''s original","noLabel":"No, not entirely"},{"id":"blk_contestr09","ref":"entry_title","title":"What''s your entry called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_contestr10","ref":"entry_description","title":"Tell the judges about it: what it is and what you were going for","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_contestr11","ref":"entry_file","title":"Upload your entry","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf","video/*","audio/*"],"maxFiles":3,"maxSizeMB":50},{"id":"blk_contestr12","ref":"entry_link","title":"If your entry lives online too, add the link","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_contestr13","ref":"rules","title":"Contest rules","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I have read the contest rules and agree to them. I understand my entry may be shown publicly with my name if it is shortlisted or wins.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"},{"id":"blk_contestr14","ref":"heard_from","title":"Last one: how did you hear about the contest?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_a_friend","label":"A friend","image_key":null},{"id":"opt_school_club_or","label":"School, club or work","image_key":null},{"id":"opt_our_website_or","label":"Our website or newsletter","image_key":null}],"allowOther":true}],"endings":[{"id":"end_contestr01","ref":"end_thanks","title":"You''re in, good luck! 🏆","bodyMd":"We''ve received your entry. We''ll email you when judging closes and let every entrant know the results.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_contestr02","ref":"end_not_entered","title":"We can''t accept this entry yet","bodyMd":"Entries need to be your own original work. If you have a different piece that is, you''re welcome to start again and enter that instead.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_contestr01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"adult"},"op":"eq","value":false}],"groups":[]},"from":"adult","target":"guardian","targetKind":"block","branch":"true"},{"id":"rl_contestr02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"adult"},"op":"eq","value":true}],"groups":[]},"from":"adult","target":"entry_type","targetKind":"block","branch":"true"},{"id":"rl_contestr03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"entry_type"},"op":"eq","value":"opt_as_a_team"}],"groups":[]},"from":"entry_type","target":"team_name","targetKind":"block","branch":"true"},{"id":"rl_contestr04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"entry_type"},"op":"eq","value":"opt_on_my_own"}],"groups":[]},"from":"entry_type","target":"category","targetKind":"block","branch":"true"},{"id":"rl_contestr05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"original"},"op":"eq","value":false}],"groups":[]},"from":"original","target":"end_not_entered","targetKind":"ending","branch":"true"},{"id":"rl_contestr06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"original"},"op":"eq","value":true}],"groups":[]},"from":"original","target":"entry_title","targetKind":"block","branch":"true"},{"id":"rl_contestr07","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"guardian","target":"team_size","targetKind":"block","branch":"true"},{"id":"rl_contestr08","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"team_size","target":"original","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
