VALUES ('tpl_yogaregistrationform', 'yoga-registration-form', 'Yoga registration form', 'Form', 'Sign students up for the right class, with what the teacher needs to know.', 'For studios and independent teachers. It places each student by class and experience, asks when they can come, and only asks about injuries in detail when there''s something to tell. Anyone booking prenatal yoga is asked how far along they are and whether their midwife or doctor is happy for them to exercise.', '["registration","yoga registration","yoga class signup","studio registration","yoga intake","branching"]', 'Leaf', 'contact', 4, 12, '{"schemaVersion":9,"title":"Yoga class registration","description":"Sign students up for the right class, with what the teacher needs to know.","blocks":[{"id":"blk_yogaregi00","ref":"welcome","title":"Welcome! Let''s find the right class for you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_yogaregi01","ref":"contact","title":"Let''s start with your details","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_yogaregi02","ref":"class","title":"Which class would you like to join?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_beginners","label":"Beginners","image_key":null},{"id":"opt_vinyasa_flow","label":"Vinyasa flow","image_key":null},{"id":"opt_yin_and_restorative","label":"Yin and restorative","image_key":null},{"id":"opt_prenatal","label":"Prenatal","image_key":null},{"id":"opt_private_one_to","label":"Private one-to-one","image_key":null}],"allowOther":false},{"id":"blk_yogaregi03","ref":"weeks_pregnant","title":"How many weeks pregnant are you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":42,"integerOnly":true},{"id":"blk_yogaregi04","ref":"cleared","title":"Has your midwife or doctor said it''s fine for you to exercise?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"Not yet"},{"id":"blk_yogaregi05","ref":"experience","title":"How much yoga have you done before?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_none_this_is","label":"None, this is my first time","image_key":null},{"id":"opt_a_few_classes","label":"A few classes","image_key":null},{"id":"opt_i_practise_regularly","label":"I practise regularly","image_key":null},{"id":"opt_i_teach_or","label":"I teach or have trained","image_key":null}],"allowOther":false},{"id":"blk_yogaregi06","ref":"times","title":"When could you come?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_early_mornings","label":"Early mornings","image_key":null},{"id":"opt_lunchtime","label":"Lunchtime","image_key":null},{"id":"opt_weekday_evenings","label":"Weekday evenings","image_key":null},{"id":"opt_saturdays","label":"Saturdays","image_key":null},{"id":"opt_sundays","label":"Sundays","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_yogaregi07","ref":"format","title":"Would you rather come to the studio or join online?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_the_studio","label":"In the studio","image_key":null},{"id":"opt_live_online","label":"Live online","image_key":null},{"id":"opt_either_is_fine","label":"Either is fine","image_key":null}],"allowOther":false},{"id":"blk_yogaregi08","ref":"hopes","title":"What are you hoping yoga will help with?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select"