VALUES ('tpl_productregistrationform', 'product-registration-form', 'Product registration form', 'Form', 'Record who owns what, and catch a faulty product on day one.', 'For brands selling physical products. It records the model, serial number, where and when it was bought and a copy of the receipt, which is what warranty and recall checks need. One question asks whether everything arrived working, and a buyer who says no is asked what''s wrong and sent to a support ending instead of a thank-you.', '["registration","product registration","warranty registration","serial number","customer onboarding","branching"]', 'BadgeCheck', 'contact', 4, 13, '{"schemaVersion":9,"title":"Product registration","description":"Record who owns what, and catch a faulty product on day one.","blocks":[{"id":"blk_productr00","ref":"welcome","title":"Thanks for your purchase! Registering takes a couple of minutes and helps us support you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_productr01","ref":"product","title":"Which product and model are you registering?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_productr02","ref":"serial","title":"What''s the serial number?","description":"It''s on a label on the product or its box, often under a barcode.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_productr03","ref":"purchase_date","title":"When did you buy it?","description":"If it was a gift, the date you received it is fine.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_productr04","ref":"bought_from","title":"Where did you buy it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_directly_from_our","label":"Directly from our website","image_key":null},{"id":"opt_a_shop","label":"A shop","image_key":null},{"id":"opt_an_online_retailer","label":"An online retailer or marketplace","image_key":null},{"id":"opt_it_was_a","label":"It was a gift","image_key":null}],"allowOther":false},{"id":"blk_productr05","ref":"retailer","title":"Which shop or retailer was it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_productr06","ref":"receipt","title":"Upload a photo of the receipt or order confirmation, if you have it","description":"Keeping it on file makes any warranty claim quicker.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":2,"maxSizeMB":10},{"id":"blk_productr07","ref":"contact","title":"Who should we register it to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_productr08","ref":"address","title":"Your address, so we can reach you about safety notices or recalls","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal","country"],"location":"off"},{"id":"blk_productr09","ref":"working","title":"Did everything arrive complete and working?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, all good","noLabel":"No, there''s a problem"},{"id":"blk_productr10","ref":"setup_ease","title":"How easy was it to set up?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_productr11","ref":"updates","title":"Product news","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"Send me occasional emails about updates, tips and offers for my product. I can unsubscribe at any time. Safety and warranty messages are sent either way.","allowDecline":true,"agreeLabel":"Yes, keep me posted","declineLabel":"No thanks"},{"id":"blk_productr12","ref":"problem","title":"What''s wrong? Describe what you see and when it happens.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_productr13","ref":"problem_photos","title":"Photos or a short video of the problem help our team a lot","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","video/*"],"maxFiles":4,"maxSizeMB":10}],"endings":[{"id":"end_productr01","ref":"end_thanks","title":"You''re registered ✅","bodyMd":"Your product is on file. Keep your serial number handy if you ever need to contact support.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_productr02","ref":"end_support","title":"Registered, and we''re on the problem","bodyMd":"Your product is on file, and our support team has your description. They''ll email you about a fix or a replacement.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_productr01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"updates","target":"end_thanks","targetKind":"ending"},{"id":"rl_productr02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"problem_photos","target":"end_support","targetKind":"ending"},{"id":"rl_productr03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"bought_from"},"op":"eq","value":"opt_a_shop"}],"groups":[]},"from":"bought_from","target":"retailer","targetKind":"block","branch":"true"},{"id":"rl_productr04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"bought_from"},"op":"eq","value":"opt_an_online_retailer"}],"groups":[]},"from":"bought_from","target":"retailer","targetKind":"block","branch":"true"},{"id":"rl_productr05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"bought_from"},"op":"eq","value":"opt_directly_from_our"}],"groups":[]},"from":"bought_from","target":"receipt","targetKind":"block","branch":"true"},{"id":"rl_productr06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"bought_from"},"op":"eq","value":"opt_it_was_a"}],"groups":[]},"from":"bought_from","target":"receipt","targetKind":"block","branch":"true"},{"id":"rl_productr07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"working"},"op":"eq","value":true}],"groups":[]},"from":"working","target":"setup_ease","targetKind":"block","branch":"true"},{"id":"rl_productr08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"working"},"op":"eq","value":false}],"groups":[]},"from":"working","target":"problem","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
