VALUES ('tpl_volunteersignup', 'volunteer-signup', 'Volunteer sign up form', 'Form', 'Match volunteers to shifts they can actually make.', 'Availability and skills as structured choices, so a coordinator fills a rota by filtering rather than by reading. Under-18s add a parent or guardian, anyone offering to drive is asked about their licence and insurance, and anyone working with people directly is asked about a background check. Those are the questions that otherwise hold up a whole rota.', '["registration","volunteer sign up","volunteer registration","nonprofit","volunteer rota","branching"]', 'HandHeart', 'contact', 4, 15, '{"schemaVersion":9,"title":"Volunteer signup","description":"Match volunteers to shifts they can actually make.","blocks":[{"id":"blk_voluntee00","ref":"welcome","title":"Thanks for offering to help! Tell us when you''re free and what you''d like to do.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_voluntee01","ref":"contact","title":"First, your details","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_voluntee02","ref":"over_18","title":"Are you 18 or over?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_voluntee03","ref":"guardian_contact","title":"A parent or guardian''s name and phone number","description":"We need this before you can be put on a shift.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":160},{"id":"blk_voluntee04","ref":"availability","title":"When are you usually free?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_weekday_mornings","label":"Weekday mornings","image_key":null},{"id":"opt_weekday_afternoons","label":"Weekday afternoons","image_key":null},{"id":"opt_weekday_evenings","label":"Weekday evenings","image_key":null},{"id":"opt_saturdays","label":"Saturdays","image_key":null},{"id":"opt_sundays","label":"Sundays","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_voluntee05","ref":"commitment","title":"How often could you help?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_week","label":"Every week","image_key":null},{"id":"opt_a_couple_of","label":"A couple of times a month","image_key":null},{"id":"opt_now_and_then","label":"Now and then","image_key":null},{"id":"opt_one_off_events","label":"One-off events only","image_key":null}],"allowOther":false},{"id":"blk_voluntee06","ref":"primary_role","title":"What would you most like to help with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_driving_and_deliveries","label":"Driving and deliveries","image_key":null},{"id":"opt_working_with_people","label":"Working with people directly","image_key":null},{"id":"opt_events_and_stewarding","label":"Events and stewarding","image_key":null},{"id":"opt_fundraising","label":"Fundraising","image_key":null},{"id":"opt_admin_and_data","label":"Admin and data","image_key":null},{"id":"opt_whatever_s_needed","label":"Whatever''s needed","image_key":null}],"allowOther":false},{"id":"blk_voluntee07","ref":"licence_years","title":"How many years have you held a full driving licence?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":80,"integerOnly":true},{"id":"blk_voluntee08","ref":"own_vehicle","title":"Would you use your own vehicle?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, my own","noLabel":"I''d need one of yours"},{"id":"blk_voluntee09","ref":"insurance","title":"Does your vehicle insurance cover volunteer driving?","description":"If you''re not sure, say no and we''ll help you check with your insurer.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_voluntee10","ref":"background_check","title":"Do you have a current background check for working with children or vulnerable adults?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_and_it","label":"Yes, and it''s up to date","image_key":null},{"id":"opt_yes_but_it","label":"Yes, but it may have expired","image_key":null},{"id":"opt_no_i_d","label":"No, I''d need one","image_key":null},{"id":"opt_i_m_not","label":"I''m not sure","image_key":null}],"allowOther":false},{"id":"blk_voluntee11","ref":"people_experience","title":"Have you done anything like this before?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_voluntee12","ref":"skills","title":"Any skills or experience we should know about?","description":"Languages, first aid, cooking, a trade, anything you think might help.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_voluntee13","ref":"access_needs","title":"Anything we should know to make volunteering work for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_voluntee14","ref":"emergency_contact","title":"An emergency contact: name and phone number","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":160},{"id":"blk_voluntee15","ref":"policies","title":"Volunteer agreement","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I have read the volunteer agreement and safeguarding policy, and agree to follow them.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_voluntee01","ref":"end_thanks","title":"Welcome to the team 💚","bodyMd":"A coordinator will be in touch with the rota and your first shift.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_voluntee01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"insurance","target":"skills","targetKind":"block"},{"id":"rl_voluntee02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"over_18"},"op":"eq","value":false}],"groups":[]},"from":"over_18","target":"guardian_contact","targetKind":"block","branch":"true"},{"id":"rl_voluntee03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"over_18"},"op":"eq","value":true}],"groups":[]},"from":"over_18","target":"availability","targetKind":"block","branch":"true"},{"id":"rl_voluntee04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_role"},"op":"eq","value":"opt_driving_and_deliveries"}],"groups":[]},"from":"primary_role","target":"licence_years","targetKind":"block","branch":"true"},{"id":"rl_voluntee05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_role"},"op":"eq","value":"opt_working_with_people"}],"groups":[]},"from":"primary_role","target":"background_check","targetKind":"block","branch":"true"},{"id":"rl_voluntee06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_role"},"op":"eq","value":"opt_events_and_stewarding"}],"groups":[]},"from":"primary_role","target":"skills","targetKind":"block","branch":"true"},{"id":"rl_voluntee07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_role"},"op":"eq","value":"opt_fundraising"}],"groups":[]},"from":"primary_role","target":"skills","targetKind":"block","branch":"true"},{"id":"rl_voluntee08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_role"},"op":"eq","value":"opt_admin_and_data"}],"groups":[]},"from":"primary_role","target":"skills","targetKind":"block","branch":"true"},{"id":"rl_voluntee09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_role"},"op":"eq","value":"opt_whatever_s_needed"}],"groups":[]},"from":"primary_role","target":"skills","targetKind":"block","branch":"true"},{"id":"rl_voluntee10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"own_vehicle"},"op":"eq","value":true}],"groups":[]},"from":"own_vehicle","target":"insurance","targetKind":"block","branch":"true"},{"id":"rl_voluntee11","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"own_vehicle"},"op":"eq","value":false}],"groups":[]},"from":"own_vehicle","target":"skills","targetKind":"block","branch":"true"},{"id":"rl_voluntee12","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"guardian_contact","target":"commitment","targetKind":"block","branch":"true"},{"id":"rl_voluntee13","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"people_experience","target":"access_needs","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#221d44","surface":"#2d2757","text":"#f5f3ff","accent":"#ff8a4c","accentText":"#1c1917","botBubble":"#332c5e","userBubble":"#ff8a4c","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
