INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_onlineactivitylog', 'online-activity-log', 'Online activity log', 'Form', 'Record one piece of work at a time, with the time it took and where it stands.', 'One entry per task: the day, the kind of work, the hours and whether it is done. Anyone who marks a task as blocked is asked what is in the way and whether they need help, so the log doubles as an early warning rather than just a timesheet.', '["report","activity log","work log","time tracking","daily log","timesheet"]', 'ClipboardList', 'contact', 4, 12, '{"schemaVersion":9,"title":"Activity log","description":"Record one piece of work at a time, with the time it took and where it stands.","blocks":[{"id":"blk_onlineac00","ref":"welcome","title":"Time to log an entry. It takes about a minute.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_onlineac01","ref":"logged_by","title":"Who is logging this entry?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_onlineac02","ref":"entry_date","title":"Which day was this work done?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_onlineac03","ref":"category","title":"What kind of work was it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_client_or_customer","label":"Client or customer work","image_key":null},{"id":"opt_internal_project","label":"Internal project","image_key":null},{"id":"opt_meetings_and_calls","label":"Meetings and calls","image_key":null},{"id":"opt_admin_and_email","label":"Admin and email","image_key":null},{"id":"opt_training_or_learning","label":"Training or learning","image_key":null}],"allowOther":true},{"id":"blk_onlineac04","ref":"task","title":"What did you work on?","description":"A short name someone else would recognise, like a project or ticket name.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_onlineac05","ref":"hours","title":"How many hours did it take?","description":"Use decimals for part hours, so 1.5 is an hour and a half.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":24,"integerOnly":false},{"id":"blk_onlineac06","ref":"status","title":"Where does it stand now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_done","label":"Done","image_key":null},{"id":"opt_still_in_progress","label":"Still in progress","image_key":null},{"id":"opt_blocked","label":"Blocked","image_key":null}],"allowOther":false},{"id":"blk_onlineac07","ref":"outcome","title":"What came out of it?","description":"A result, a decision, or what''s left to do.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_onlineac08","ref":"blocker","title":"What''s in the way?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_onlineac09","ref":"needs_help","title":"Do you need someone to step in to get it moving?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_onlineac10","ref":"focus","title":"How focused was that time?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Constant interruptions","labelHigh":"Deep, uninterrupted work"},{"id":"blk_onlineac11","ref":"next_step","title":"What''s the next step, and who owns it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_onlineac12","ref":"attachment","title":"Anything worth keeping with this entry?","description":"Optional. A screenshot, a document or meeting notes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":3,"maxSizeMB":10}],"endings":[{"id":"end_onlineac01","ref":"end_thanks","title":"Entry logged","bodyMd":"Thanks. If you flagged a blocker, whoever reviews the log will see it first.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_onlineac01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"outcome","target":"focus","targetKind":"block"},{"id":"rl_onlineac02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"status"},"op":"eq","value":"opt_done"}],"groups":[]},"from":"status","target":"outcome","targetKind":"block","branch":"true"},{"id":"rl_onlineac03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"status"},"op":"eq","value":"opt_still_in_progress"}],"groups":[]},"from":"status","target":"outcome","targetKind":"block","branch":"true"},{"id":"rl_onlineac04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"status"},"op":"eq","value":"opt_blocked"}],"groups":[]},"from":"status","target":"blocker","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","show