goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"request_type"},"op":"eq","value":"opt_something_else"}],"groups":[]},"from":"request_type","target":"summary","targetKind":"block","branch":"true"},{"id":"rl_marketin07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"date_fixed"},"op":"eq","value":true}],"groups":[]},"from":"date_fixed","target":"date_reason","targetKind":"block","branch":"true"},{"id":"rl_marketin08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"date_fixed"},"op":"eq","value":false}],"groups":[]},"from":"date_fixed","target":"references","targetKind":"block","branch":"true"},{"id":"rl_marketin09","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"date_reason","target":"approver","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is s