VALUES ('tpl_mediarequestform', 'media-request-form', 'Media request form', 'Form', 'Collect press enquiries with everything your communications team needs to respond.', 'Journalists get a short, clear route to your press team instead of a generic inbox. The form asks what kind of request it is and follows up to match: preferred format and spokesperson for an interview, which assets for a media kit request, and location details for filming.', '["request","media request","press enquiry","press office","interview request","PR"]', 'Newspaper', 'content', 4, 13, '{"schemaVersion":9,"title":"Media request","description":"Collect press enquiries with everything your communications team needs to respond.","blocks":[{"id":"blk_mediareq00","ref":"welcome","title":"Hello. Tell us about your story and we''ll get back to you before your deadline where we can.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_mediareq01","ref":"journalist","title":"Your name and how to reach you","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_mediareq02","ref":"outlet","title":"Which outlet or publication are you with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_mediareq03","ref":"outlet_type","title":"What kind of outlet is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_newspaper","label":"Newspaper","image_key":null},{"id":"opt_magazine","label":"Magazine","image_key":null},{"id":"opt_tv","label":"TV","image_key":null},{"id":"opt_radio","label":"Radio","image_key":null},{"id":"opt_podcast","label":"Podcast","image_key":null},{"id":"opt_online_publication","label":"Online publication","image_key