VALUES ('tpl_newuserrequestform', 'new-user-request-form', 'New user request form', 'Form', 'Ask for accounts, access and equipment for a new starter in one go.', 'Everything IT needs to set someone up before their first morning: start date, role, systems and equipment. Contractors and temporary staff are asked for an end date so access doesn''t outlive the contract, and any request for admin rights has to say why and whether a manager has approved it.', '["request","new user request","access request","IT onboarding","new starter","account request"]', 'UserPlus', 'content', 4, 14, '{"schemaVersion":9,"title":"New user request","description":"Ask for accounts, access and equipment for a new starter in one go.","blocks":[{"id":"blk_newuser00","ref":"welcome","title":"Setting up access for someone new? This takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_newuser01","ref":"requester","title":"First, who is making the request?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_newuser02","ref":"new_user_name","title":"What is the new user''s full name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_newuser03","ref":"job_title","title":"What is their job title?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_newuser04","ref":"department","title":"Which department will they be in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_sales","label":"Sales","image_key":null},{"id":"opt_marketing","label":"Marketing","image_key":null},{"id":"opt_engineering","label":"Engineering","image_key":null},{"id":"opt_product","label":"Product","image_key":null},{"id":"opt_customer_support","label":"Customer support","image_key":null},{"id":"opt_finance","label":"Finance","image_key":null},{"id":"opt_people_and_hr","label":"People and HR","image_key":null},{"id":"opt_operations","label":"Operations","image_key":null},{"id":"opt_other","label":"Other","image_key":null}]},{"id":"blk_newuser05","ref":"start_date","title":"When is their first day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_newuser06","ref":"employment_type","title":"What kind of role is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_employee","label":"Employee","image_key":null},{"id":"opt_contractor","label":"Contractor","image_key":null},{"id":"opt_intern","label":"Intern","image_key":null},{"id":"opt_temporary_staff","label":"Temporary staff","image_key":null}],"allowOther":false},{"id":"blk_newuser07","ref":"end_date","title":"When should their access end?","description":"We''ll switch accounts off on this date unless you tell us otherwise.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_newuser08","ref":"systems","title":"Which systems will they need?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_email_and_calendar","label":"Email and calendar","image_key":null},{"id":"opt_team_chat","label":"Team chat","image_key":null},{"id":"opt_shared_drives_and","label":"Shared drives and documents","image_key":null},{"id":"opt_crm","label":"CRM","image_k