VALUES ('tpl_informationrequestform', 'information-request-form', 'Information request form', 'Form', 'Take requests for documents or details, and know where and how to send the reply.', 'Asks what the person needs, what it is for and how they want to receive it. Anyone asking for records about themselves is asked for a reference and proof of identity before the rest, and a request for a printed copy asks for a postal address, so nobody is chased for details afterwards.', '["request","information request","document request","records request","request for information","proof of identity"]', 'FileSearch', 'content', 3, 11, '{"schemaVersion":9,"title":"Information request","description":"Take requests for documents or details, and know where and how to send the reply.","blocks":[{"id":"blk_informat00","ref":"welcome","title":"Looking for some information from us? Tell us what you need and we''ll get it to you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_informat01","ref":"requester","title":"Who should we reply to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_informat02","ref":"requester_type","title":"Which best describes you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_customer_or_client","label":"Customer or client","image_key":null},{"id":"opt_partner_or_supplier","label":"Partner or supplier","image_key":null},{"id":"opt_student_or_researcher","label":"Student or researcher","image_key":null},{"id":"opt_member_of_the","label":"Member of the public","image_key":null}],"allowOther":true},{"id":"blk_informat03","ref":"about","title":"What is the information about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_records_about_me","label":"Records about me or my account","image_key":null},{"id":"opt_our_policies_or","label":"Our policies or procedures","image_key":null},{"id":"opt_our_products_or","label":"Our products or services","image_key":null},{"id":"opt_reports_or_published","label":"Reports or published data","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_informat04","ref":"account_ref","title":"Do you have an account, customer or case number?","description":"It helps us find your records quickly. Leave blank if you don''t know it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_informat05","ref":"id_proof","title":"Please upload proof of identity","description":"We only release personal records to the person they belong to. A photo of an ID document is enough.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":2,"maxSizeMB":10},{"id":"blk_informat06","ref":"details","title":"What exactly would you like to receive?","description":"Name the document, time period or topic if you can.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_informat07","ref":"purpose","title":"What do you need it for?","description":"Optional, but it helps us send the most useful version.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_informat08","ref":"delivery","title":"How would you like to receive it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_by_email","label":"By email","image_key":null},{"id":"opt_as_a_printed","label":"As a printed copy by post","image_key":null},{"id":"opt_a_phone_call","label":"A phone call to talk it through","image_key":null}],"allowOther":false},{"id":"blk_informat09","ref":"postal_address","title":"Where should we post it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","state","postal","country"],"location":"off"},{"id":"blk_informat10","ref":"phone","title":"What number should we call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_informat11","ref":"needed_by","title":"Is there a date you need it by?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"}],"endings":[{"id":"end_informat01","ref":"end_thanks","title":"Request received","bodyMd":"We''ll confirm we have it and tell you when to expect a reply. If we need anything else, we''ll ask by email.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_informat01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"postal_address","target":"needed_by","targetKind":"block"},{"id":"rl_informat02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"about"},"op":"eq","value":"opt_records_about_me"}],"groups":[]},"from":"about","target":"account_ref","targetKind":"block","branch":"true"},{"id":"rl_informat03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"about"},"op":"eq","value":"opt_our_policies_or"}],"groups":[]},"from":"about","target":"details","targetKind":"block","branch":"true"},{"id":"rl_informat04","action_kind":"goto","when":{"op":"and","conditions":[{"left