VALUES ('tpl_taxibookingform', 'taxi-booking-form', 'Taxi booking form', 'Form', 'Take a trip request with everything a dispatcher needs to send the right car.', 'Pickup and drop-off first, with an option to share the passenger''s current location, then when, how many and what kind of vehicle. Airport pickups are asked for the flight number so the driver can track delays, and anyone booking a return trip gives the return time in the same conversation.', '["request","taxi booking","cab booking","ride booking","airport transfer","car service booking"]', 'Car', 'content', 4, 14, '{"schemaVersion":9,"title":"Taxi booking","description":"Take a trip request with everything a dispatcher needs to send the right car.","blocks":[{"id":"blk_taxibook00","ref":"welcome","title":"Where are you headed? Let''s get your ride booked.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_taxibook01","ref":"passenger","title":"Your name and a number the driver can call","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","phone","email"]},{"id":"blk_taxibook02","ref":"pickup","title":"Where should we pick you up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal"],"location":"optional"},{"id":"blk_taxibook03","ref":"airport","title":"Is the pickup at an airport?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_taxibook04","ref":"flight","title":"What is your flight number?","description":"The driver will check arrival times, so a delay won''t cost you the ride.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":20},{"id":"blk_taxibook05","ref":"destination","title":"Where are you going?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal"],"location":"off"},{"id":"blk_taxibook06","ref":"timing","title":"When do you need the car?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_as_soon_as","label":"As soon as possible","image_key":null},{"id":"opt_at_a_later","label":"At a later time","image_key":null}],"allowOther":false},{"id":"blk_taxibook07","ref":"pickup_time","title":"What date and time should the driver arrive?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":15,"timeMin":"00:00","timeMax":"23:45"},{"id":"blk_taxibook08","ref":"passengers","title":"How many passengers?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":16,"integerOnly":true},{"id":"blk_taxibook09","ref":"luggage","title":"How much luggage?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_none_or_hand","label":"None or hand luggage only","image_key":null},{"id":"opt_one_or_two","label":"One or two suitcases","image_key":null},{"id":"opt_three_or_more","label":"Three or more suitcases","image_key":null},{"id":"opt_bulky_items_like","label":"Bulky items, like a bike or skis","image_key":null}],"allowOther":false},{"id":"blk_taxibook10","ref":"vehicle_needs","title":"Do you need any of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_wheelchair_accessible_vehi","label":"Wheelchair accessible vehicle","image_key":null},{"id":"opt_child_or_booster","label":"Child or booster seat","image_key":null},{"id":"opt_space_for_a","label":"Space for a pet","image_key":null},{"id":"opt_a_larger_car","label":"A larger car or van","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_taxibook11","ref":"return_trip","title":"Would you like to book a return trip too?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_taxibook12","ref":"return_time","title":"When should we pick you up for the return?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":15,"timeMin":"00:00","timeMax":"23:45"},{"id":"blk_taxibook13","ref":"pay_method","title":"How will you pay the driver?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_card","label":"Card","image_key":null},{"id":"opt_cash","label":"Cash","image_key":null},{"id":"opt_company_account","label":"Company account","image_key":null}],"allowOther":false},{"id":"blk_taxibook14","ref":"driver_notes","title":"Anything the driver should know?","description":"Gate codes, which entrance, or where you''ll be waiting.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false}],"endings":[{"id":"end_taxibook01","ref":"end_thanks","title":"Booking request received 🚕","bodyMd":"We''ll confirm your driver and fare by text or email. For a pickup in the next hour, please also call us.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_taxibook01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"airport"},"op":"eq","value":true}],"groups":[]},"from":"airport","target":"flight","targetKind":"block","branch":"true"},{"id":"rl_taxibook02","action_