INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_transportationrequestfor', 'transportation-request-form', 'Transportation request form', 'Form', 'Request transport for a group or a load, with the details a coordinator needs to plan it.', 'The form first asks whether people or goods are moving. Passenger trips cover group size, accessibility and luggage; goods cover what the load is, its size and weight and any special handling. Both then share the route, timing, return trip and site access, so the coordinator can book the right vehicle first time.', '["request","transportation request","transport booking","vehicle request","delivery request","logistics"]', 'Truck', 'content', 4, 17, '{"schemaVersion":9,"title":"Transportation request","description":"Request transport for a group or a load, with the details a coordinator needs to plan it.","blocks":[{"id":"blk_transpor00","ref":"welcome","title":"Need transport arranged? Tell us what''s moving and we''ll plan the rest.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_transpor01","ref":"requester","title":"Who is making the request?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_transpor02","ref":"department","title":"Which team, department or organisation is it for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_transpor03","ref":"moving","title":"What needs moving?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_people","label":"People","image_key":null},{"id":"opt_goods_or_equipment","label":"Goods or equipment","image_key":null}],"allowOther":false},{"id":"blk_transpor04","ref":"passengers","title":"How many people are travelling?","required":true,"visibi