mage_key":null},{"id":"opt_hazardous_materials","label":"Hazardous materials","image_key":null},{"id":"opt_oversized_or_awkward","label":"Oversized or awkward shape","image_key":null},{"id":"opt_none_of_these","label":"None of these","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_transpor11","ref":"from","title":"Where does the trip start?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal"],"location":"off"},{"id":"blk_transpor12","ref":"to","title":"Where does it end?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["street","city","postal"],"location":"off"},{"id":"blk_transpor13","ref":"departure","title":"When should it leave?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":15,"timeMin":"00:00","timeMax":"23:45"},{"id":"blk_transpor14","ref":"return_needed","title":"Is a return trip needed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_transpor15","ref":"return_time","title":"When should the return trip leave?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":15,"timeMin":"00:00","timeMax":"23:45"},{"id":"blk_transpor16","ref":"site_access","title":"Anything the driver should know about parking, loading or access?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_transpor17","ref":"cost_code","title":"Which budget or cost code should this be charged to?","required":false,"visibility":null,"image_key":null,"agentHint