VALUES ('tpl_workrequestform', 'work-request-form', 'Work request form', 'Form', 'A single intake for jobs, fixes and changes, with enough detail to prioritise them.', 'After a one-line summary and the details, it asks whether something is broken, needs changing or is new, and anyone reporting a fault is asked when it started and whether there''s a workaround. The last question asks whether anyone is unable to work until it''s done, and those requests get their own ending so the requester knows it is being treated as urgent.', '["request","work request","job request","work order","task request","maintenance request"]', 'Wrench', 'content', 4, 12, '{"schemaVersion":9,"title":"Work request","description":"A single intake for jobs, fixes and changes, with enough detail to prioritise them.","blocks":[{"id":"blk_workrequ00","ref":"welcome","title":"Need something done? Tell us what and why, and we''ll pick it up.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_workrequ01","ref":"requester","title":"Who is making the request?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_workrequ02","ref":"team","title":"Which team or location are you in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_workrequ03","ref":"summary","title":"In one line, what needs doing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_workrequ04","ref":"details","title":"Give us the details","description":"Where it is, what you expected, and anything you''ve already tried.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_workrequ05","ref":"kind","title":"What kind of request is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_something_is_broken","label":"Something is broken or not working","image_key":null},{"id":"opt_a_change_to","label":"A change to something that exists","image_key":null},{"id":"opt_something_new","label":"Something new","image_key":null},{"id":"opt_a_question_or","label":"A question or advice","image_key":null}],"allowOther":false},{"id":"blk_workrequ06","ref":"broken_since","title":"When did you first notice it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_workrequ07","ref":"workaround","title":"Is there a workaround in the meantime?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_workrequ08","ref":"why","title":"What happens if this isn''t done?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_workrequ09","ref":"impact","title":"Who does it affect?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_my_team","label":"My team","image_key":null},{"id":"opt_several_teams","label":"Several teams","image_key":null},{"id":"opt_customers","label":"Customers","image_key":null}],"allowOther":false},{"id":"blk_workrequ10","ref":"needed_by","title":"When do you need it done by?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_workrequ11","ref":"files","title":"Photos, screenshots or documents that help explain it","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":10},{"id":"blk_workrequ12","ref":"work_stopped","title":"Is anyone unable to work until this is done?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"}],"endings":[{"id":"end_workrequ01","ref":"end_thanks","title":"Request received","bodyMd":"We''ll review it, set a priority and let you know who''s picking it up.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_workrequ02","ref":"end_urgent","title":"Marked urgent","bodyMd":"We''ll look at this first and get in touch today. If it gets worse in the meantime, contact the team directly.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_workrequ01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"kind"},"op":"eq","value":"opt_something_is_broken"}],"groups":[]},"from":"kind","target":"broken_since","targetKind":"block","branch":"true"},{"id":"rl_workrequ02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"kind"},"op":"eq","value":"opt_a_change_to"}],"groups":[]},"from":"kind","target":"why","targetKind":"block","branch":"true"},{"id":"rl_workrequ03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"kind"},"op":"eq","value":"opt_something_new"}],"groups":[]},"from":"kind","target":"why","targetKind":"block","branch":"true"},{"id":"rl_workrequ04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"kind"},"op":"eq","value":"opt_a_question_or"}],"groups":[]},"from":"kind","target":"why","targetKind":"block","branch":"true"},{"id":"rl_workrequ05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"work_stopped"},"op":"eq","value":true}],"groups":[]},"from":"work_stopped","target":"end_urgent","targetKind":"ending","branch":"true"},{"id":"rl_workrequ06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"work_stopped"},"op":"eq","value":false}],"groups":[]},"from":"work_stopped","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffe4d3","surface":"#ffffff","text":"#3a2418","accent":"#c2410c","accentText":"#fffaf5","botBubble":"#ffffff","userBubble":"#c2410c","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
