VALUES ('tpl_softwaredevelopmentreque', 'software-development-request-form', 'Software development request form', 'Form', 'Take requests for new tools and features, starting from the problem rather than the solution.', 'Asks the questions a developer would ask before estimating: what problem this solves, for whom, how it is handled today and what the finished thing must do. Changes to existing systems name the system, and only requests with a real deadline are asked for the date and what it depends on.', '["request","software development request","development request","app development request","IT project request","requirements gathering"]', 'Code', 'content', 5, 16, '{"schemaVersion":9,"title":"Software development request","description":"Take requests for new tools and features, starting from the problem rather than the solution.","blocks":[{"id":"blk_software00","ref":"welcome","title":"Have something you''d like built or changed? Start with the problem and we''ll work out the solution together.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_software01","ref":"requester","title":"Who is making the request?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_software02","ref":"team","title":"Which team or department are you in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_software03","ref":"kind","title":"What kind of request is this?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_new_tool","label":"A new tool or app","image_key":null},{"id":"opt_a_new_feature","label":"A new feature in an existing system","image_key":null},{"id":"opt_a_change_to","label":"A change to how something works","image_key":null},{"id":"opt_connecting_two_systems","label":"Connecting two systems","image_key":null},{"id":"opt_a_report_or","label":"A report or data export","image_key":null}],"allowOther":false},{"id":"blk_software04","ref":"existing_system","title":"Which existing system or systems does it involve?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_software05","ref":"problem","title":"What problem are you trying to solve?","description":"Describe the problem, not the solution. We may find an easier way to fix it.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_software06","ref":"today","title":"How is it handled today?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_software07","ref":"users","title":"Who will use it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_people_on_my","label":"People on my team","image_key":null},{"id":"opt_other_staff","label":"Other staff","image_key":null},{"id":"opt_customers","label":"Customers","image_key":null},{"id":"opt_partners_or_suppliers","label":"Partners or suppliers","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_software08","ref":"user_count","title":"Roughly how many people will use it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_fewer_than_10","label":"Fewer than 10","image_key":null},{"id":"opt_10_to_100","label":"10 to 100","image_key":null},{"id":"opt_100_to_1","label":"100 to 1,000","image_key":null},{"id":"opt_more_than_1","label":"More than 1,000","image_key"