INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_featurerequest', 'feature-request', 'Feature request form', 'Form', 'Capture the problem behind the request, not just the request.', 'People ask for solutions; roadmaps need problems. This asks what they are trying to do and how they work around it today, and when someone says they are blocked right now, it takes that seriously: it asks what they can''t do and where to reach them, and ends by promising a reply that day.', '["request","feature request","product feedback","roadmap","user ideas","feature request form"]', 'Lightbulb', 'content', 3, 12, '{"schemaVersion":9,"title":"Feature request","description":"Capture the problem behind the request, not just the request.","blocks":[{"id":"blk_featurer00","ref":"welcome","title":"Got an idea? Tell us what you''re trying to do and we''ll take it from there.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_featurer01","ref":"request","title":"In one line, what would you like to be able to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_featurer02","ref":"problem","title":"What are you trying to accomplish when you need it?","description":"The goal behind the request helps us more than a specific design.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_featurer03","ref":"workaround","title":"How do you handle it today?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_featurer04","ref":"area","title":"Which part of the product is this about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_building_and_editing","label":"Building and editing","image_key":null},{"id":"opt_sharing_and_publishing","label":"Sharing and publishing","image_key":null},{"id":"opt_results_and_reporting","label":"Results and reporting","image_key":null},{"id":"opt_connecting_to_other","label":"Connecting to other tools","image_key":null},{"id":"opt_billing_and_admin","label":"Billing and admin","image_key":null}],"allowOther":true},{"id":"blk_featurer05","ref":"mockup","title":"A screenshot or sketch, if it helps explain","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":3,"maxSizeMB":10},{"id":"blk_featurer06","ref":"importance","title":"How much would this change your day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_s_blocking","label":"It''s blocking me right now","image_key":null},{"id":"opt_it_would_save","label":"It would save me real time","image_key":null},{"id":"opt_it_would_be","label":"It would be nice to have","image_key":null}],"allowOther":false},{"id":"blk_featurer07","ref":"blocking_since","title":"When did it start blocking you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_featurer08","ref":"blocking_impact","title":"What can''t you do until this exists?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_featurer09","ref":"blocking_email","title":"Where can we reach you today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_featurer10","ref":"how_often","title":"How often would you use it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_daily","label":"Daily","image_key":null},{"id":"opt_weekly","label":"Weekly","image_key":null},{"id":"opt_monthly","label":"Monthly","image_key":null},{"id":"opt_now_and_then","label":"Now and then","image_key":null}],"allowOther":false},{"id":"blk_featurer11","ref":"who_else","title":"Who else on your side would use it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_a_few_people","label":"A few people on my team","image_key":null},{"id":"opt_most_of_my","label":"Most of my team or company","image_key":null}],"allowOther":false},{"id":"blk_featurer12","ref":"email","title":"Where can we reach you if we build it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_featurer01","ref":"end_thanks","title":"Logged 💡","bodyMd":"We read every one of these. If you left an email, we''ll tell you when it ships.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_featurer02","ref":"end_urgent","title":"Flagged as blocking 🚧","bodyMd":"Someone will reply today, often with a workaround before the fix exists.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_featurer01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"blocking_email","target":"end_urgent","targetKind":"ending"},{"id":"rl_featurer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"importance"},"op":"eq","value":"opt_it_s_blocking"}],"groups":[]},"from":"importance","target":"blocking_since","targetKind":"block","branch":"true"},{"id":"rl_featurer03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"importance"},"op":"eq","value":"opt_it_would_save"}],"groups":[]},"from":"importance","target":"how_often","targetKind":"block","branch":"true"},{"id":"rl_featurer04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"importance"},"op":"eq","value":"opt_it_would_be"}],"groups":[]},"from":"importance","target":"how_often","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ece3ff","surface":"#ffffff","text":"#2a1f3d","accent":"#6d3fc7","accentText":"#fbf8ff","botBubble":"#ffffff","userBubble":"#6d3fc7","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
