VALUES ('tpl_onlinesignupform', 'online-signup-form', 'Online signup form', 'Form', 'A short signup that tells you who joined, why, and whether they came alone or with a team.', 'Most signup forms stop at a name and an email, and you learn nothing you can act on. This one also asks what people want from joining and how they like to hear from you. Anyone signing up for a team or organisation gets two extra questions about it, so group signups are easy to spot in your list.', '["signup","online signup form","community signup","program registration","member signup","join form"]', 'UserPlus', 'choice', 3, 10, '{"schemaVersion":9,"title":"Online signup","description":"A short signup that tells you who joined, why, and whether they came alone or with a team.","blocks":[{"id":"blk_onlinesi00","ref":"welcome","title":"Glad you''re joining us. This takes about two minutes, then you''re in.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_onlinesi01","ref":"contact","title":"First, who are you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_onlinesi02","ref":"joining_as","title":"Are you signing up just for yourself, or for a group?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_for_me","label":"Just for me","image_key":null},{"id":"opt_for_a_team","label":"For a team or organisation","image_key":null}],"allowOther":false},{"id":"blk_onlinesi03","ref":"org_name","title":"What is the team or organisation called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_onlinesi04","ref":"group_size","title":"Roughly how many people will be joining with you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":10000,"integerOnly":true},{"id":"blk_onlinesi05","ref":"location","title":"Where are you based?","description":"City and country are enough. It helps us plan meetups and time zones.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"address","fields":["city","country"],"location":"off"},{"id":"blk_onlinesi06","ref":"interests","title":"What are you hoping to get out of joining?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_learning_new_skills","label":"Learning new skills","image_key":null},{"id":"opt_meeting_people_like","label":"Meeting people like me","image_key":null},{"id":"opt_getting_help_with","label":"Getting help with a problem","image_key":null},{"id":"opt_sharing_what_i","label":"Sharing what I know","image_key":null},{"id":"opt_staying_up_to","label":"Staying up to date","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_onlinesi07","ref":"experience","title":"How new are you to what we do?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Brand new to it","labelHigh":"I could teach it"},{"id":"blk_onlinesi08","ref":"heard_from","title":"How did you hear about us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_a_friend_or","label":"A friend or colleague","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_search_engine","label":"Search engine","image_key":null},{"id":"opt_an_event","label":"An event","image_key":null},{"id":"opt_a_newsletter_or","label":"A newsletter or blog","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}]},{"id":"blk_onlinesi09","ref":"updates","title":"How often would you like to hear from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_update","label":"Every update","image_key":null},{"id":"opt_a_weekly_roundup","label":"A weekly roundup","image_key":null},{"id":"opt_only_the_important","label":"Only the important stuff","image_key":null}],"allowOther":false},{"id":"blk_onlinesi10","ref":"terms","title":"The fine print","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I agree to the community guidelines and to receive emails about my membership. I can unsubscribe at any time.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_onlinesi01","ref":"end_thanks","title":"You''re signed up 🎉","bodyMd":"A welcome email with your next steps is on its way. If you can''t find it, have a look in your spam folder.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_onlinesi01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"joining_as"},"op":"eq","value":"opt_just_for_me"}],"groups":[]},"from":"joining_as","target":"location","targetKind":"block","branch":"true"},{"id":"rl_onlinesi02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"joining_as"},"op":"eq","value":"opt_for_a_team"}],"groups":[]},"from":"joining_as","target":"org_name","targetKind":"block","branch":"true"},{"id":"rl_onlinesi03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"group_size","target":"interests","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#d9f2e6","surface":"#ffffff","text":"#12342a","accent":"#0f766e","accentText":"#f5fffb","botBubble":"#ffffff","userBubble":"#0f766e","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"plus","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
