VALUES ('tpl_betasignup', 'beta-signup', 'Beta tester signup form', 'Form', 'Recruit testers who will actually test, sorted by platform and available time.', 'A beta list full of people who never log in is worse than a short one. This asks about setup, the time someone can give and what they would try first. Anyone who can give real time is then asked how they like to give feedback and how many rough edges they can live with, which is exactly what you need to pick the first invite wave.', '["signup","beta tester signup","beta program","early access","user research","product testing"]', 'FlaskConical', 'choice', 4, 11, '{"schemaVersion":9,"title":"Beta signup","description":"Recruit testers who will actually test, sorted by platform and available time.","blocks":[{"id":"blk_betasign00","ref":"welcome","title":"Want early access? Tell us a little about how you''d use it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_betasign01","ref":"email","title":"What email should the invite go to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_betasign02","ref":"name","title":"And your name?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_betasign03","ref":"role","title":"Which best describes your work?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_founder_or_manager","label":"Founder or manager","image_key":null},{"id":"opt_engineer_or_developer","label":"Engineer or developer","image_key":null},{"id":"opt_designer","label":"Designer","image_key":null},{"id":"opt_marketing_or_sales","label":"Marketing or sales","image_key":null},{"id":"opt_operations_or_support","label":"Operations or support","image_key":null},{"id":"opt_student","label":"Student","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_betasign04","ref":"platform","title":"Which platforms would you test on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_web","label":"Web","image_key":null},{"id":"opt_ios","label":"iOS","image_key":null},{"id":"opt_android","label":"Android","image_key":null},{"id":"opt_desktop","label":"Desktop","image_key":null},{"id":"opt_api_only","label":"API only","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_betasign05","ref":"current_tool","title":"What do you use today for the job this would do?","description":"A product name, a spreadsheet, or nothing at all are all useful answers.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_betasign06","ref":"use_case","title":"What would you try first?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_betasign07","ref":"time_commitment","title":"How much time could you give in the first month?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_as_much_as","label":"As much as it takes","image_key":null},{"id":"opt_a_few_hours","label":"A few hours","image_key":null},{"id":"opt_an_hour_or","label":"An hour or two","image_key":null}],"allowOther":false},{"id":"blk_betasign08","ref":"feedback_style","title":"How would you rather give feedback?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_written_notes_as","label":"Written notes as I go","image_key":null},{"id":"opt_a_call_every","label":"A call every couple of weeks","image_key":null},{"id":"opt_bug_reports_only","label":"Bug reports only","image_key":null},{"id":"opt_screen_recordings","label":"Screen recordings","image_key":null}],"minSelections":0,"maxSelections":4,"allowOther":false},{"id":"blk_betasign09","ref":"rough_edges","title":"How much roughness can you live with?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Must basically work","labelHigh":"Break it, I''ll tell you how"},{"id":"blk_betasign10","ref":"call_slot","title":"Best time for an occasional call?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_mornings","label":"Mornings","image_key":null},{"id":"opt_afternoons","label":"Afternoons","image_key":null},{"id":"opt_evenings","label":"Evenings","image_key":null},{"id":"opt_i_d_rather","label":"I''d rather not","image_key":null}],"allowOther":false},{"id":"blk_betasign11","ref":"nda_consent","title":"Keeping it quiet","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I understand the beta is confidential and agree not to share screenshots or details publicly until launch.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_betasign01","ref":"end_thanks","title":"You''re on the list 🧪","bodyMd":"We invite testers in small waves. We''ll email you when your invite is ready, along with how to send us feedback.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_betasign01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"time_commitment"},"op":"eq","value":"opt_as_much_as"}],"groups":[]},"from":"time_commitment","target":"feedback_style","targetKind":"block","branch":"true"},{"id":"rl_betasign02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"time_commitment"},"op":"eq","value":"opt_a_few_hours"}],"groups":[]},"from":"time_commitment","target":"feedback_style","targetKind":"block","branch":"true"},{"id":"rl_betasign03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"time_commitment"},"op":"eq","value":"opt_an_hour_or"}],"groups":[]},"from":"time_commitment","target":"nda_consent","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#221d44","surface":"#2d2757","text":"#f5f3ff","accent":"#ff8a4c","accentText":"#1c1917","botBubble":"#332c5e","userBubble":"#ff8a4c","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
