VALUES ('tpl_newslettersignup', 'newsletter-signup', 'Newsletter signup form', 'Form', 'Subscribe people to the topics they actually want, at the pace they want.', 'A single list means every send is wrong for someone. Asking which topics and how often, at the moment of signing up, is the cheapest way to prevent unsubscribes. The form also asks why someone came: customers, people still deciding and readers who are here for the writing each get one follow-up of their own.', '["signup","newsletter signup form","email subscription","mailing list","email preferences","subscriber segmentation"]', 'Mail', 'choice', 3, 10, '{"schemaVersion":9,"title":"Newsletter signup","description":"Subscribe people to the topics they actually want, at the pace they want.","blocks":[{"id":"blk_newslett00","ref":"welcome","title":"Want the newsletter? Tell us what to send and how often.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_newslett01","ref":"email","title":"What''s your email?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_newslett02","ref":"first_name","title":"First name, so we''re not writing to a stranger?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_newslett03","ref":"reader_type","title":"What brings you here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_use_the","label":"I use the product","image_key":null},{"id":"opt_i_m_deciding","label":"I''m deciding whether to use it","image_key":null},{"id":"opt_i_m_here","label":"I''m here for the writing","image_key":null}],"allowOther":false},{"id":"blk_newslett04","ref":"customer_since","title":"How long have you been using it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a month","image_key":null},{"id":"opt_a_few_months","label":"A few months","image_key":null},{"id":"opt_over_a_year","label":"Over a year","image_key":null}],"allowOther":false},{"id":"blk_newslett05","ref":"evaluating_against","title":"What else are you looking at?","description":"No wrong answer. It tells us which comparisons are worth writing.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_newslett06","ref":"writing_found_via","title":"What did you read that brought you here?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_newslett07","ref":"topics","title":"What should we send you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_product_updates","label":"Product updates","image_key":null},{"id":"opt_how_to_guides","label":"How-to guides","image_key":null},{"id":"opt_customer_stories","label":"Customer stories","image_key":null},{"id":"opt_industry_news","label":"Industry news","image_key":null},{"id":"opt_events_and_webinars","label":"Events and webinars","image_key":null},{"id":"opt_behind_the_scenes","label":"Behind the scenes","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_newslett08","ref":"frequency","title":"How often?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_weekly","label":"Weekly","image_key":null},{"id":"opt_every_two_weeks","label":"Every two weeks","image_key":null},{"id":"opt_monthly","label":"Monthly","image_key":null}],"allowOther":false},{"id":"blk_newslett09","ref":"wish_list","title":"Anything you''d love us to write about?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":400,"aiQualityCheck":false},{"id":"blk_newslett10","ref":"consent","title":"Permission to email you","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I agree to receive marketing emails and understand I can unsubscribe from any of them at any time.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_newslett01","ref":"end_thanks","title":"Subscribed ✉️","bodyMd":"Check your inbox to confirm your subscription. Your first issue will match the topics you picked.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_newslett01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reader_type"},"op":"eq","value":"opt_i_use_the"}],"groups":[]},"from":"reader_type","target":"customer_since","targetKind":"block","branch":"true"},{"id":"rl_newslett02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reader_type"},"op":"eq","value":"opt_i_m_deciding"}],"groups":[]},"from":"reader_type","target":"evaluating_against","targetKind":"block","branch":"true"},{"id":"rl_newslett03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reader_type"},"op":"eq","value":"opt_i_m_here"}],"groups":[]},"from":"reader_type","target":"writing_found_via","targetKind":"block","branch":"true"},{"id":"rl_newslett04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"customer_since","target":"topics","targetKind":"block","branch":"true"},{"id":"rl_newslett05","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"evaluating_against","target":"topics","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
