VALUES ('tpl_gymsatisfactionsurvey', 'gym-satisfaction-survey', 'Gym satisfaction survey', 'Survey', 'Rate the equipment, classes and staff, and catch members who are close to cancelling.', 'Covers what members actually use, a quick grid on the things that make or break a gym, and a ranked wishlist. Members who admit they have thought about cancelling get two extra questions about why and what would keep them, plus the option to have the manager get in touch.', '["business","gym survey","member satisfaction","fitness club feedback","member retention","gym member questionnaire"]', 'Dumbbell', 'text', 4, 15, '{"schemaVersion":9,"title":"Gym member satisfaction","description":"Rate the equipment, classes and staff, and catch members who are close to cancelling.","blocks":[{"id":"blk_gymsatis00","ref":"welcome","title":"Hi! We''d love to hear how training with us is going. It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_gymsatis01","ref":"membership_length","title":"How long have you been a member?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_3","label":"Less than 3 months","image_key":null},{"id":"opt_3_to_12","label":"3 to 12 months","image_key":null},{"id":"opt_1_to_3","label":"1 to 3 years","image_key":null},{"id":"opt_more_than_3","label":"More than 3 years","image_key":null}],"allowOther":false},{"id":"blk_gymsatis02","ref":"visit_frequency","title":"In a normal week, how often do you come in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_once","label":"Less than once a week","image_key":null},{"id":"opt_1_or_2","label":"1 or 2 times","image_key":null},{"id":"opt_3_or_4","label":"3 or 4 times","image_key":null},{"id":"opt_5_times_or","label":"5 times or more","image_key":null}],"allowOther":false},{"id":"blk_gymsatis03","ref":"main_goal","title":"What''s the main thing you train for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_getting_stronger","label":"Getting stronger","image_key":null},{"id":"opt_losing_weight","label":"Losing weight","image_key":null},{"id":"opt_fitness_and_stamina","label":"Fitness and stamina","image_key":null},{"id":"opt_staying_healthy_as","label":"Staying healthy as I get older","image_key":null},{"id":"opt_recovering_from_an","label":"Recovering from an injury","image_key":null},{"id":"opt_the_classes_and","label":"The classes and the people","image_key":null}],"allowOther":true},{"id":"blk_gymsatis04","ref":"used","title":"Which parts of the gym do you use?","description":"Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_weights_and_machines","label":"Weights and machines","image_key":null},{"id":"opt_cardio_equipment","label":"Cardio equipment","image_key":null},{"id":"opt_group_classes","label":"Group classes","image_key":null},{"id":"opt_personal_training","label":"Personal training","image_key":null},{"id":"opt_pool_sauna_or","label":"Pool, sauna or spa","image_key":null},{"id":"opt_changing_rooms_and","label":"Changing rooms and showers","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_gymsatis05","ref":"aspects","title":"How would you rate each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_condition_of","label":"Condition of the equipment"},{"id":"opt_row_cleanliness","label":"Cleanliness"},{"id":"opt_row_changing_rooms","label":"Changing rooms"},{"id":"opt_row_class_times","label":"Class times and variety"},{"id":"opt_row_help_from","label":"Help from staff and trainers"},{"id":"opt_row_how_busy","label":"How busy it gets at peak times"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_great","label":"Great"}],"multiplePerRow":false},{"id":"blk_gymsatis06","ref":"overall","title":"Overall, how happy are you with your membership?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_gymsatis07","ref":"value","title":"How fair does your membership fee feel for what you get?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Poor value","labelHigh":"Great value"},{"id":"blk_gymsatis08","ref":"thinking_leaving","title":"Have you thought about cancelling in the last three months?","description":"An honest answer helps us far more than a polite one.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_gymsatis09","ref":"leave_reasons","title":"What''s making you think about it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_the_cost","label":"The cost","image_key":null},{"id":"opt_too_crowded_when","label":"Too crowded when I can come","image_key":null},{"id":"opt_equipment_is_broken","label":"Equipment is broken or missing","image_key":null},{"id":"opt_classes_don_t","label":"Classes don''t fit my schedule","image_key":null},{"id":"opt_i_m_not","label":"I''m not seeing results","image_key":null},{"id":"opt_moving_away_or","label":"Moving away or changing routine","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_gymsatis10","ref":"keep_you","title":"What would make you stay?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_gymsatis11","ref":"contact_ok","title":"Would you like the gym manager to get in touch about this?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_gymsatis12","ref":"contact_email","title":"What''s the best email to reach you on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_gymsatis13","ref":"wishlist","title":"Put these in order: which would improve your visits most?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_more_or","label":"More or newer equipment"},{"id":"opt_item_classes_at","label":"Classes at times I can make"},{"id":"opt_item_cleaner_changing","label":"Cleaner changing rooms"},{"id":"opt_item_less_crowding","label":"Less crowding at peak times"},{"id":"opt_item_more_guidance","label":"More guidance from staff"},{"id":"opt_item_longer_opening","label":"Longer opening hours"}]},{"id":"blk_gymsatis14","ref":"recommend","title":"How likely are you to recommend the gym to a friend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_gymsatis15","ref":"anything_else","title":"Anything else you''d like the team to know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_gymsatis01","ref":"end_thanks","title":"Thanks for the feedback 💪","bodyMd":"The team reads every response, and we''ll share what we change because of them.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_gymsatis01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"thinking_leaving"},"op":"eq","value":true}],"groups":[]},"from":"thinking_leaving","target":"leave_reasons","targetKind":"block","branch":"true"},{"id":"rl_gymsatis02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"thinking_leaving"},"op":"eq","value":false}],"groups":[]},"from":"thinking_leaving","target":"wishlist","targetKind":"block","branch":"true"},{"id":"rl_gymsatis03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"contact_ok"},"op":"eq","value":true}],"groups":[]},"from":"contact_ok","target":"contact_email","targetKind":"block","branch":"true"},{"id":"rl_gymsatis04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"contact_ok"},"op":"eq","value":false}],"groups":[]},"from":"contact_ok","target":"wishlist","targetKind":"block","branch":"true"},{"id":"rl_gymsatis05","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"contact_email","target":"recommend","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#5b2ee6","surface":"#4a22c9","text":"#ffffff","accent":"#ffd166","accentText":"#1c1917","botBubble":"#4a22c9","userBubble":"#ffd166","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundPatternColor":"#ffffff","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
