VALUES ('tpl_pricesensitivitysurvey', 'price-sensitivity-survey', 'Price sensitivity survey', 'Survey', 'Four price-point questions in the Van Westendorp style, with value and context around them.', 'Built around the four classic price-point questions, asked in a fixed order from most expensive to least, so everyone works down the same ladder. Current customers first say what justifies the cost, former customers say why they stopped, and prospects go straight to the price questions.', '["business","price sensitivity","Van Westendorp","willingness to pay","pricing research","price point survey"]', 'Calculator', 'text', 3, 11, '{"schemaVersion":9,"title":"Price sensitivity","description":"Four price-point questions in the Van Westendorp style, with value and context around them.","blocks":[{"id":"blk_pricesen00","ref":"welcome","title":"Hi! We''re working out our pricing and want your honest view. It takes about four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_pricesen01","ref":"relationship","title":"Which of these describes you?","description":"Every question here is about the same product and plan.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_pay_for","label":"I pay for it now","image_key":null},{"id":"opt_i_used_to","label":"I used to pay for it","image_key":null},{"id":"opt_i_haven_t","label":"I haven''t bought it yet","image_key":null}],"allowOther":false},{"id":"blk_pricesen02","ref":"value_now","title":"How would you rate the value you get for what you pay?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Poor value","labelHigh":"Excellent value"},{"id":"blk_pricesen03","ref":"worth_it","title":"Which parts of it make the cost worth it for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_the_time_it","label":"The time it saves me","image_key":null},{"id":"opt_features_i_can","label":"Features I can''t get elsewhere","image_key":null},{"id":"opt_quality_and_reliability","label":"Quality and reliability","image_key":null},{"id":"opt_support_when_i","label":"Support when I need it","image_key":null},{"id":"opt_it_s_cheaper","label":"It''s cheaper than the alternatives","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_pricesen04","ref":"why_stopped","title":"What made you stop paying for it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_pricesen05","ref":"too_expensive","title":"At what price would it be so expensive that you wouldn''t consider buying it?","description":"Enter an amount in your usual currency, per month.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_pricesen06","ref":"getting_expensive","title":"At what price would it start to feel expensive, so you''d think hard before buying?","description":"Still something you might buy, just not without a second thought.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_pricesen07","ref":"bargain","title":"At what price would it feel like a bargain?","description":"Great value for the money, and you''d buy it without hesitating.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_pricesen08","ref":"too_cheap","title":"At what price would it be so cheap that you''d doubt the quality?","description":"Same currency and period as your other answers.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_pricesen09","ref":"price_rise","title":"Imagine you were paying for it and the price went up by 10%. What would you most likely do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_keep_paying_without","label":"Keep paying without a second thought","image_key":null},{"id":"opt_keep_paying_but","label":"Keep paying, but start looking around","image_key":null},{"id":"opt_move_to_a","label":"Move to a cheaper option or plan","image_key":null},{"id":"opt_stop_paying_for","label":"Stop paying for it","image_key":null}],"allowOther":false},{"id":"blk_pricesen10","ref":"billing","title":"How would you prefer to pay?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_monthly","label":"Monthly","image_key":null},{"id":"opt_yearly_for_a","label":"Yearly, for a discount","image_key":null},{"id":"opt_a_one_off","label":"A one-off payment","image_key":null},{"id":"opt_pay_only_for","label":"Pay only for what I use","image_key":null}],"allowOther":false},{"id":"blk_pricesen11","ref":"alternative","title":"If it didn''t exist, what would you use instead?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200}],"endings":[{"id":"end_pricesen01","ref":"end_thanks","title":"Thank you, that''s really useful","bodyMd":"Your answers go straight into our pricing decision. Nothing changes for you without notice.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_pricesen01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"worth_it","target":"too_expensive","targetKind":"block"},{"id":"rl_pricesen