VALUES ('tpl_restaurantfeedbacksurvey', 'restaurant-feedback-survey', 'Restaurant feedback survey', 'Survey', 'Learn who your diners are, how each visit rated and what they want from the menu.', 'A survey for planning, not just complaint handling: it learns how often each diner comes, asks first-timers how they found you, and rates food, service and prices. A low overall rating opens questions on exactly which parts let the diner down, and everyone ranks what matters when they choose where to eat.', '["business","restaurant survey","diner survey","menu feedback","guest experience","restaurant market research"]', 'ChefHat', 'text', 4, 15, '{"schemaVersion":9,"title":"Restaurant visit survey","description":"Learn who your diners are, how each visit rated and what they want from the menu.","blocks":[{"id":"blk_restaura00","ref":"welcome","title":"Thanks for eating with us! We''re planning the next few months and would love your view. It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_restaura01","ref":"meal","title":"What was your most recent visit for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_breakfast_or_brunch","label":"Breakfast or brunch","image_key":null},{"id":"opt_lunch","label":"Lunch","image_key":null},{"id":"opt_dinner","label":"Dinner","image_key":null},{"id":"opt_drinks_or_a","label":"Drinks or a snack","image_key":null}],"allowOther":false},{"id":"blk_restaura02","ref":"party","title":"Who were you with?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_two_of_us","label":"Two of us","image_key":null},{"id":"opt_a_group_of","label":"A group of 3–6","image_key":null},{"id":"opt_a_bigger_group","label":"A bigger group or a celebration","image_key":null}],"allowOther":false},{"id":"blk_restaura03","ref":"how_often","title":"How often do you eat with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_this_was_my","label":"This was my first time","image_key":null},{"id":"opt_a_few_times","label":"A few times a year","image_key":null},{"id":"opt_about_once_a","label":"About once a month","image_key":null},{"id":"opt_most_weeks","label":"Most weeks","image_key":null}],"allowOther":false},{"id":"blk_restaura04","ref":"found_us","title":"How did you hear about us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_walked_past","label":"I walked past","image_key":null},{"id":"opt_a_friend_recommended","label":"A friend recommended us","image_key":null},{"id":"opt_online_reviews_or","label":"Online reviews or maps","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_an_article_or","label":"An article or food guide","image_key":null}],"allowOther":true},{"id":"blk_restaura05","ref":"ordered","title":"What did you order?","description":"Just the main dishes is fine.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_restaura06","ref":"ratings","title":"How would you rate each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_taste_of","label":"Taste of the food"},{"id":"opt_row_portion_size","label":"Portion size"},{"id":"opt_row_food_served","label":"Food served at the right temperature"},{"id":"opt_row_speed_of","label":"Speed of service"},{"id":"opt_row_friendliness_of","label":"Friendliness of the staff"},{"id":"opt_row_cleanliness","label":"Cleanliness"},{"id":"opt_row_atmosphere_and","label":"Atmosphere and noise level"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_restaura07","ref":"prices","title":"How fair were the prices for what you got?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Too expensive","labelHigh":"Great value"},{"id":"blk_restaura08","ref":"overall","title":"Overall, how was your visit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_restaura09","ref":"highlight","title":"What was the best part of your meal?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_restaura10","ref":"letdowns","title":"Sorry it fell short. Which parts let you down?","description":"Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_the_food_itself","label":"The food itself","image_key":null},{"id":"opt_waiting_too_long","label":"Waiting too long","image_key":null},{"id":"opt_how_we_treated","label":"How we treated you","image_key":null},{"id":"opt_the_price_for","label":"The price for what you got","image_key":null},{"id":"opt_the_room_noise","label":"The room, noise or cleanliness","image_key":null},{"id":"opt_a_problem_with","label":"A problem with the booking or the bill","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_restaura11","ref":"problem","title":"What happened?","description":"The dish and roughly what time help us trace it to the right shift.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_restaura12","ref":"choice_factors","title":"When you choose where to eat, what matters most to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_quality_of","label":"Quality of the food"},{"id":"opt_item_price","label":"Price"},{"id":"opt_item_being_close","label":"Being close by"},{"id":"opt_item_atmosphere","label":"Atmosphere"},{"id":"opt_item_quick_service","label":"Quick service"},{"id":"opt_item_options_for","label":"Options for my diet"}]},{"id":"blk_restaura13","ref":"menu_wishes","title":"What would you like to see more of on the menu?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_vegetarian_and_vegan","label":"Vegetarian and vegan dishes","image_key":null},{"id":"opt_gluten_free_options","label":"Gluten-free options","image_key":null},{"id":"opt_seasonal_specials","label":"Seasonal specials","image_key":null},{"id":"opt_smaller_or_lighter","label":"Smaller or lighter plates","image_key":null},{"id":"opt_a_children_s","label":"A children''s menu","image_key":null},{"id":"opt_non_alcoholic_drinks","label":"Non-alcoholic drinks","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_restaura14","ref":"next_visit","title":"What one thing would make your next visit better?","description":"A dish, a change to the room, the booking, anything at all.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_restaura15","ref":"return_likely","title":"How likely are you to come back in the next few months?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not likely","labelHigh":"Definitely"}],"endings":[{"id":"end_restaura01","ref":"end_thanks","title":"Thank you, see you soon 🍽️","bodyMd":"Every response is read by the team, and your ideas go into our next menu planning.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_restaura01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"highlight","target":"choice_factors","targetKind":"block"},{"id":"rl_restaura02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"how_often"},"op":"eq","value":"opt_this_was_my"}],"groups":[]},"from":"how_often","target":"found_us","targetKind":"block","branch":"true"},{"id":"rl_restaura03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"how_often"},"op":"eq","value":"opt_a_few_times"}],"groups":[]},"from":"how_often","target":"ordered","targetKind":"block","branch":"true"},{"id":"rl_restaura04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"how_often"},"op":"eq","value":"opt_about_once_a"}],"groups":[]},"from":"how_often","target":"ordered","targetKind":"block","branch":"true"},{"id":"rl_restaura05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"how_often"},"op":"eq","value":"opt_most_weeks"}],"groups":[]},"from":"how_often","target":"ordered","targetKind":"block","branch":"true"},{"id":"rl_restaura06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"gte","value":3}],"groups":[]},"from":"overall","target":"highlight","targetKind":"block","branch":"true"},{"id":"rl_restaura07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"lte","value":2}],"groups":[]},"from":"overall","target":"letdowns","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#5b2ee6","surface":"#4a22c9","text":"#ffffff","accent":"#ffd166","accentText":"#1c1917","botBubble":"#4a22c9","userBubble":"#ffd166","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundPatternColor":"#ffffff","backgroundSha