INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_systemusabilitysurvey', 'system-usability-survey', 'System usability survey', 'Survey', 'A task check, ten standard usability statements and the moments people got stuck.', 'Anchored to a real task: people say what they tried to do and whether they managed it, and anyone who didn''t is asked where they got stuck. The ten standard usability statements sit in one grid, so you can score them the usual way, and willing users can sign up for a follow-up session.', '["business","system usability scale","SUS questionnaire","usability testing","UX research","SUS score"]', 'Laptop', 'text', 3, 10, '{"schemaVersion":9,"title":"System usability","description":"A task check, ten standard usability statements and the moments people got stuck.","blocks":[{"id":"blk_systemus00","ref":"welcome","title":"Thanks for trying the system. A few questions about how that went, about four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_systemus01","ref":"task","title":"What were you trying to do just now?","description":"For example, submitting an expense or finding a customer record.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_systemus02","ref":"task_done","title":"Did you manage to do it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_completely","label":"Yes, completely","image_key":null},{"id":"opt_partly","label":"Partly","image_key":null},{"id":"opt_no_i_got","label":"No, I got stuck","image_key":null}],"allowOther":false},{"id":"blk_systemus03","ref":"stuck_where","title":"Where did it go wrong?","description":"What you expected to happen, and what happened instead.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_systemus04","ref":"ease","title":"Overall, how easy or hard was that task?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":7,"startAt":1,"labelLow":"Very hard","labelHigh":"Very easy"},{"id":"blk_systemus05","ref":"sus","title":"How much do you agree with each statement about the system?","description":"Go with your first reaction.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_i_think","label":"I think that I would like to use this system frequently"},{"id":"opt_row_i_found","label":"I found the system unnecessarily complex"},{"id":"opt_row_i_thought","label":"I thought the system was easy to use"},{"id":"opt_row_i_think_2","label":"I think that I would need the support of a technical person to be able to use this system"},{"id":"opt_row_i_found_2","label":"I found the various functions in this system were well integrated"},{"id":"opt_row_i_thought_2","label":"I thought there was too much inconsistency in this system"},{"id":"opt_row_i_would","label":"I would imagine that most people would learn to use this system very quickly"},{"id":"opt_row_i_found_3","label":"I found the system very cumbersome to use"},{"id":"opt_row_i_felt","label":"I felt very confident using the system"},{"id":"opt_row_i_needed","label":"I needed to learn a lot of things before I could get going with this system"}],"columns":[{"id":"opt_col_strongly_disagree","label":"Strongly disagree"},{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_neutral","label":"Neutral"},{"id":"opt_col_agree","label":"Agree"},{"id":"opt_col_strongly_agree","label":"Strongly agree"}],"multiplePerRow":false},{"id":"blk_systemus06","ref":"slowdowns","title":"Where did you slow down, if anywhere?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"o