VALUES ('tpl_websitequestionnaire', 'website-questionnaire', 'Website questionnaire', 'Survey', 'Find out what visitors came for, and where the site let them down.', 'Built around the visit someone just had, not their opinion of your brand. It asks what they came to do and whether they managed it: a visitor who found it easily moves straight on, one who had to dig is asked where, and one who gave up is asked what was missing and where they looked.', '["customer satisfaction","website questionnaire","website feedback","user experience","visitor survey","navigation"]', 'Globe', 'number', 3, 10, '{"schemaVersion":9,"title":"Website questionnaire","description":"Find out what visitors came for, and where the site let them down.","blocks":[{"id":"blk_websiteq00","ref":"welcome","title":"Hi! Got a minute to tell us how your visit to our website went?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_websiteq01","ref":"visit_goal","title":"What brought you to the site today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_finding_out_what","label":"Finding out what you offer","image_key":null},{"id":"opt_comparing_prices_or","label":"Comparing prices or options","image_key":null},{"id":"opt_buying_or_booking","label":"Buying or booking something","image_key":null},{"id":"opt_getting_help_with","label":"Getting help with something I already have","image_key":null},{"id":"opt_finding_contact_details","label":"Finding contact details","image_key":null}],"allowOther":true},{"id":"blk_websiteq02","ref":"first_visit","title":"Is this your first visit to the site?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_websiteq03","ref":"found_it","title":"Did you find what you came for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_easily","label":"Yes, easily","image_key":null},{"id":"opt_yes_but_it","label":"Yes, but it took some digging","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_websiteq04","ref":"where_stuck","title":"Where did you get stuck along the way?","description":"A page name or the link you expected to click is plenty.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_websiteq05","ref":"what_missing","title":"What were you looking for that you couldn''t find?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_websiteq06","ref":"where_looked","title":"Where did you look for it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_the_main_menu","label":"The main menu","image_key":null},{"id":"opt_the_site_search","label":"The site search","image_key":null},{"id":"opt_the_home_page","label":"The home page","image_key":null},{"id":"opt_the_footer_links","label":"The footer links","image_key":null},{"id":"opt_help_or_faq","label":"Help or FAQ pages","image_key":null},{"id":"opt_a_search_engine","label":"A search engine","image_key":null}],"minSelections":0,"maxSelections":10,"allowOther":false},{"id":"blk_websiteq07","ref":"site_ratings","title":"How would you rate the site on each of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_finding_my","label":"Finding my way around"},{"id":"opt_row_clarity_of","label":"Clarity of the wording"},{"id":"opt_row_how_fast","label":"How fast pages load"},{"id":"opt_row_how_it","label":"How it works on my phone"},{"id":"opt_row_look_and","label":"Look and feel"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_great","label":"Great"}],"multiplePerRow":false},{"id":"blk_websiteq08","ref":"expected_content","title":"Is there anything you expected to see on the site that isn''t there?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_websiteq09","ref":"return_likely","title":"How likely are you to come back to the site?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Very unlikely","labelHigh":"Very likely"},{"id":"blk_websiteq10","ref":"follow_up_email","title":"Happy for us to follow up with a question or two? Leave your email if so.","description":"Optional. We''ll only use it to ask about this feedback.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_websiteq01","ref":"end_thanks","title":"Thanks, that''s really useful","bodyMd":"We read every answer and use them to decide what to fix on the site first.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_websiteq01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"where_stuck","target":"site_ratings","targetKind":"block"},{"id":"rl_websiteq02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"found_it"},"op":"eq","value":"opt_yes_easily"}],"groups":[]},"from":"found_it","target":"site_ratings","targetKind":"block","branch":"true"},{"id":"rl_websiteq03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"found_it"},"op":"eq","value":"opt_yes_but_it"}],"groups":[]},"from":"found_it","target":"where_stuck","targetKind":"block","branch":"true"},{"id":"rl_websiteq04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"found_it"},"op":"eq","value":"opt_no"}],"groups":[]},"from":"found_it","target":"what_missing","targetKind":"block","branch":"true"},{"id":"rl_websiteq05","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"where_looked","target":"expected_content","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f3e6ff","surface":"#ffffff","text":"#2b1638","accent":"#9333ea","accentText":"#fdf9ff","botBubble":"#ffffff","userBubble":"#9333ea","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"confetti","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
