VALUES ('tpl_cescustomereffortscoresu', 'ces-customer-effort-score-survey', 'Customer effort score survey', 'Survey', 'One effort question, and a closer look at the steps that made it hard.', 'Asks the standard effort question about one named task, on a seven-point agree scale. Customers who found it hard are asked what got in the way, how many times they had to get in touch and which step they would remove; customers who found it easy just say what helped.', '["customer satisfaction","customer effort score","CES survey","support feedback","customer experience","friction"]', 'Gauge', 'number', 3, 10, '{"schemaVersion":9,"title":"Customer effort score (CES)","description":"One effort question, and a closer look at the steps that made it hard.","blocks":[{"id":"blk_cescusto00","ref":"welcome","title":"Quick one about what you just did with us. It takes under a minute.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_cescusto01","ref":"task","title":"What were you trying to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_get_help_from","label":"Get help from support","image_key":null},{"id":"opt_set_up_my","label":"Set up my account","image_key":null},{"id":"opt_place_or_change","label":"Place or change an order","image_key":null},{"id":"opt_return_or_cancel","label":"Return or cancel something","image_key":null},{"id":"opt_update_billing_or","label":"Update billing or account details","image_key":null}],"allowOther":true},{"id":"blk_cescusto02","ref":"effort","title":"How much do you agree with this: it was easy to get that done with us.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":7,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_cescusto03","ref":"friction_points","title":"What made it harder than it should have been?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_too_many_steps","label":"Too many steps","image_key":null},{"id":"opt_i_had_to","label":"I had to repeat information","image_key":null},{"id":"opt_i_was_passed","label":"I was passed between people or teams","image_key":null},{"id":"opt_waiting_for_a","label":"Waiting for a reply","image_key":null},{"id":"opt_the_instructions_were","label":"The instructions were unclear","image_key":null},{"id":"opt_something_didn_t","label":"Something didn''t work","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_cescusto04","ref":"contacts","title":"How many times did you have to get in touch with us about it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_didn_t","label":"I didn''t need to","image_key":null},{"id":"opt_once","label":"Once","image_key":null},{"id":"opt_twice","label":"Twice","image_key":null},{"id":"opt_three_times_or","label":"Three times or more","image_key":null}],"allowOther":false},{"id":"blk_cescusto05","ref":"remove_step","title":"If you could remove one step from what you just went through, which would it be?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_cescusto06","ref":"what_helped","title":"What made it easy?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_cescusto07","ref":"time_taken","title":"Roughly how long did it take from start to finish?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_few_minutes","label":"A few minutes","image_key":null},{"id":"opt_under_an_hour","label":"Under an hour","image_key":null},{"id":"opt_a_few_hours","label":"A few hours","image_key":null},{"id":"opt_a_day_or","label":"A day or more","image_key":null}],"allowOther":false},{"id":"blk_cescusto08","ref":"customer_since","title":"How long have you been a customer?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_less_than_a","label":"Less than a month","image_key":null},{"id":"opt_1_to_12","label":"1 to 12 months","image_key":null},{"id":"opt_1_to_3","label":"1 to 3 years","image_key":null},{"id":"opt_more_than_3","label":"More than 3 years","image_key":null}]},{"id":"blk_cescusto09","ref":"may_contact","title":"Can we contact you if we have a question about your answers?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_cescusto10","ref":"contact_email","title":"What''s the best email for that?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_cescusto01","ref":"end_thanks","title":"Thanks for telling us","bodyMd":"Your answers go straight to the team that owns this part of the experience.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_cescusto01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"remove_step","target":"time_taken","targetKind":"block"},{"id":"rl_cescusto02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"effort"},"op":"lte","value":4}],"groups":[]},"from":"effort","target":"friction_points","targetKind":"block","branch":"true"},{"id":"rl_cescusto03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"effort"},"op":"gte","value":5}],"groups":[]},"from":"