VALUES ('tpl_customerservicesatisfact', 'customer-service-satisfaction-survey', 'Customer service satisfaction survey', 'Survey', 'Rate the help, then check whether the problem is actually solved.', 'Keeps the person who helped separate from the outcome, because a friendly agent can still leave a problem open. Customers whose issue is fully sorted are asked what the agent did well; anyone with a partly or fully open case can ask to have it reopened and leave an email, and lands on an ending that says so.', '["customer satisfaction","customer service survey","support satisfaction","help desk feedback","agent rating","case resolution"]', 'LifeBuoy', 'number', 3, 11, '{"schemaVersion":9,"title":"Customer service satisfaction","description":"Rate the help, then check whether the problem is actually solved.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"Thanks for getting in touch with us recently. How did we do?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"channel","title":"How did you get in touch?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_live_chat","label":"Live chat","image_key":null},{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_phone","label":"Phone","image_key":null},{"id":"opt_in_person","label":"In person","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null}],"allowOther":false},{"id":"blk_customer02","ref":"topic","title":"What was it about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_an_order_or","label":"An order or delivery","image_key":null},{"id":"opt_billing_or_a","label":"Billing or a refund","image_key":null},{"id":"opt_a_technical_problem","label":"A technical problem","image_key":null},{"id":"opt_signing_in_or","label":"Signing in or account access","image_key":null},{"id":"opt_a_question_about","label":"A question about a product","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_customer03","ref":"agent","title":"How much do you agree with each of these about the person who helped you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_they_understood","label":"They understood my problem"},{"id":"opt_row_they_explained","label":"They explained things clearly"},{"id":"opt_row_they_were","label":"They were polite and patient"},{"id":"opt_row_they_kept","label":"They kept me updated"},{"id":"opt_row_they_knew","label":"They knew what they were talking about"}],"columns":[{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_neutral","label":"Neutral"},{"id":"opt_col_agree","label":"Agree"}],"multiplePerRow":false},{"id":"blk_customer04","ref":"speed","title":"How happy are you with how quickly we got back to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_customer05","ref":"overall","title":"Overall, how satisfied are you with the help you got?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_customer06","ref":"resolved","title":"Is your issue sorted now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_fully","label":"Yes, fully","image_key":null},{"id":"opt_partly","label":"Partly","image_key":null},{"id":"opt_no_it_s","label":"No, it''s still open","image_key":null}],"allowOther":false},{"id":"blk_customer07","ref":"still_open","title":"What still needs sorting out?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_customer08","ref":"reopen","title":"Would you like us to reopen your case and pick it up again?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, please","noLabel":"No thanks"},{"id":"blk_customer09","ref":"reopen_email","title":"Which email should we reply to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_customer10","ref":"praise","title":"Anything the person who helped you did especially well?","description":"We pass these on to the team.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_customer11","ref":"improve","title":"What''s one thing that would make getting help from us easier?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"Thank you for the feedback","bodyMd":"It helps us train the team and fix the things that make people get in touch twice.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_customer02","ref":"end_reopen","title":"We''re on it 🔁","bodyMd":"Your case has been flagged to reopen, and the team will reply to the email you gave us.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"reopen_email","target":"end_reopen","targetKind":"ending"},{"id":"rl_customer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolved"},"op":"eq","value":"opt_yes_fully"}],"groups":[]},"from":"resolved","target":"praise","targetKind":"block","branch":"true"},{"id":"rl_customer03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolved"},"op":"eq","value":"opt_partly"}],"groups":[]},"from":"resolved","target":"still_open","targetKind":"block","branch":"true"},{"id":"rl_customer04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolved"},"op":"eq","value":"opt_no_it_s"}],"groups":[]},"from":"resolved","target":"still_open","targetKind":"block","branch":"true"},{"id":"rl_customer05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reopen"},"op":"eq","value":false}],"groups":[]},"from":"reopen","target":"improve","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffe4d3","surface":"#ffffff","text":"#3a2418","accent":"#c2410c","accentText":"#fffaf5","botBubble":"#ffffff","userBubble":"#c2410c","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
