VALUES ('tpl_restaurantcustomersatisf', 'restaurant-customer-satisfaction-survey', 'Restaurant customer satisfaction survey', 'Survey', 'Diners rate food, service and value, and unhappy guests reach the manager.', 'Asks guests who ate in about the room and the service, and takeaway or delivery customers whether their order arrived complete. Everyone rates the food and value; a low overall score asks what would have made it better and offers a call from the manager, while happy diners are asked what they enjoyed.', '["customer satisfaction","restaurant survey","diner feedback","food and service","hospitality"]', 'Utensils', 'number', 3, 13, '{"schemaVersion":9,"title":"Restaurant satisfaction survey","description":"Diners rate food, service and value, and unhappy guests reach the manager.","blocks":[{"id":"blk_restaura00","ref":"welcome","title":"Thanks for eating with us! Can we ask how it went?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_restaura01","ref":"visit_date","title":"When did you eat with us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_restaura02","ref":"visit_type","title":"How did you have your meal?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_dined_in","label":"Dined in","image_key":null},{"id":"opt_takeaway","label":"Takeaway","image_key":null},{"id":"opt_delivery","label":"Delivery","image_key":null}],"allowOther":false},{"id":"blk_restaura03","ref":"dine_in","title":"How was your time in the restaurant?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_welcome_on","label":"Welcome on arrival"},{"id":"opt_row_friendliness_of","label":"Friendliness of staff"},{"id":"opt_row_speed_of","label":"Speed of service"},{"id":"opt_row_cleanliness","label":"Cleanliness"},{"id":"opt_row_atmosphere","label":"Atmosphere"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_restaura04","ref":"order_accurate","title":"Was your order complete and correct?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_all_there","label":"Yes, all there","image_key":null},{"id":"opt_something_was_missing","label":"Something was missing","image_key":null},{"id":"opt_something_was_wrong","label":"Something was wrong","image_key":null},{"id":"opt_it_was_cold","label":"It was cold or damaged","image_key":null}],"allowOther":false},{"id":"blk_restaura05","ref":"food","title":"How was the food?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_restaura06","ref":"dishes","title":"What did you order, and did any dish stand out, good or bad?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_restaura07","ref":"value","title":"How fair were the prices for what you got?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Poor value","labelHigh":"Great value"},{"id":"blk_restaura08","ref":"overall","title":"Overall, how would you rate your visit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_restaura09","ref":"better","title":"Sorry it wasn''t better. What''s the one thing that would have made the difference?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_restaura10","ref":"manager","title":"Would you like the manager to get in touch with you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_restaura11","ref":"manager_contact","title":"How can the manager reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","email","phone"]},{"id":"blk_restaura12","ref":"enjoyed","title":"What did you enjoy most?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_restaura13","ref":"return_visit","title":"Would you eat with us again?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_definitely","label":"Definitely","image_key":null},{"id":"opt_probably","label":"Probably","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null},{"id":"opt_probably_not","label":"Probably not","image_key":null}],"allowOther":false}],"endings":[{"id":"end_restaura01","ref":"end_thanks","title":"Thanks, and hope to see you soon 🍽️","bodyMd":"The kitchen and floor team read every answer.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_restaura02","ref":"end_manager","title":"The manager will be in touch","bodyMd":"Thank you for giving us the chance to put this right. We''ll use the details you left.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_restaura01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"dine_in","target":"food","targetKind":"block"},{"id":"rl_restaura02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"manager_contact","target":"end_manager","targetKind":"ending"},{"id":"rl_restaura03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"visit_type"},"op":"eq","value":"opt_dined_in"}],"groups":[]},"from":"visit_type","target":"dine_in","targetKind":"block","branch":"true"},{"id":"rl_restaura04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"visit_type"},"op":"eq","value":"opt_takeaway"}],"groups":[]},"from":"visit_type","target":"order_accurate","targetKind":"block","branch":"true"},{"id":"rl_restaura05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"visit_type"},"op":"eq","value":"opt_delivery"}],"groups":[]},"from":"visit_type","target":"order_accurate","targetKind":"block","branch":"true"},{"id":"rl_restaura06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"lte","value":3}],"groups":[]},"from":"overall","target":"better","targetKind":"block","branch":"true"},{"id":"rl_restaura07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"gte","value":4}],"groups":[]},"from":"overall","target":"enjoyed","targetKind":"block","branch":"true"},{"id":"rl_restaura08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"manager"},"op":"eq","value":false}],"groups":[]},"from":"manager","target":"return_visit","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.",