VALUES ('tpl_studentsatisfactionsurve', 'student-satisfaction-survey', 'Student satisfaction survey', 'Survey', 'Teaching, resources, workload and support, from the students themselves.', 'Covers the parts of a course students feel most: teaching, feedback on their work, resources, workload and belonging. A student who rates their course low is asked what''s making it hard and can ask student support to get in touch, while everyone else can answer without giving a name.', '["customer satisfaction","student satisfaction survey","course evaluation","student feedback","higher education","student experience"]', 'GraduationCap', 'number', 4, 13, '{"schemaVersion":9,"title":"Student satisfaction survey","description":"Teaching, resources, workload and support, from the students themselves.","blocks":[{"id":"blk_students00","ref":"welcome","title":"Hi! We''d like to hear how your course is going. It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_students01","ref":"course","title":"Which course or programme are you studying?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_students02","ref":"year","title":"Which year are you in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_first_year","label":"First year","image_key":null},{"id":"opt_second_year","label":"Second year","image_key":null},{"id":"opt_third_year","label":"Third year","image_key":null},{"id":"opt_fourth_year_or","label":"Fourth year or later","image_key":null},{"id":"opt_postgraduate","label":"Postgraduate","image_key":null}],"allowOther":false},{"id":"blk_students03","ref":"teaching","title":"How much do you agree with each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_staff_explain","label":"Staff explain things clearly"},{"id":"opt_row_the_course","label":"The course is well organised"},{"id":"opt_row_feedback_on","label":"Feedback on my work helps me improve"},{"id":"opt_row_feedback_arrives","label":"Feedback arrives in time to be useful"},{"id":"opt_row_i_can","label":"I can get help from staff when I need it"}],"columns":[{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_somewhat_disagree","label":"Somewhat disagree"},{"id":"opt_col_somewhat_agree","label":"Somewhat agree"},{"id":"opt_col_agree","label":"Agree"}],"multiplePerRow":false},{"id":"blk_students04","ref":"resources","title":"How well do the library, online learning tools and study spaces meet your needs?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_students05","ref":"workload","title":"How manageable is your workload?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_light","label":"Too light","image_key":null},{"id":"opt_about_right","label":"About right","image_key":null},{"id":"opt_heavy_but_manageable","label":"Heavy but manageable","image_key":null},{"id":"opt_too_heavy","label":"Too heavy","image_key":null}],"allowOther":false},{"id":"blk_students06","ref":"support_used","title":"Which support services have you used this year?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_academic_advising_or","label":"Academic advising or tutoring","image_key":null},{"id":"opt_wellbeing_or_counselling","label":"Wellbeing or counselling","image_key":null},{"id":"opt_careers_service","label":"Careers service","image_key":null},{"id":"opt_disability_or_learning","label":"Disability or learning support","image_key":null}