VALUES ('tpl_eventsatisfactionsurvey', 'event-satisfaction-survey', 'Event satisfaction survey', 'Survey', 'What worked, what disappointed, and whether people will come back.', 'Splits in-person and online attendees early, so one group rates the venue and check-in and the other rates the stream. Attendees who found it better than expected are asked for the highlight, while those who found it worse are asked what fell short, before everyone ranks what they value.', '["customer satisfaction","event satisfaction survey","post-event survey","attendee feedback","conference feedback","event evaluation"]', 'Ticket', 'number', 3, 12, '{"schemaVersion":9,"title":"Event satisfaction survey","description":"What worked, what disappointed, and whether people will come back.","blocks":[{"id":"blk_eventsat00","ref":"welcome","title":"Thanks for coming! A few quick questions while the event is fresh.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventsat01","ref":"attended","title":"How did you attend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_person","label":"In person","image_key":null},{"id":"opt_online","label":"Online","image_key":null}],"allowOther":false},{"id":"blk_eventsat02","ref":"venue","title":"How would you rate these on the day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_registration_and","label":"Registration and check-in"},{"id":"opt_row_the_venue","label":"The venue and its location"},{"id":"opt_row_signs_and","label":"Signs and finding your way"},{"id":"opt_row_food_and","label":"Food and drink"},{"id":"opt_row_room_comfort","label":"Room comfort and sound"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_eventsat03","ref":"stream","title":"How well did the online side work for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_joining_the","label":"Joining the event"},{"id":"opt_row_video_and","label":"Video and sound quality"},{"id":"opt_row_asking_questions","label":"Asking questions or chatting"},{"id":"opt_row_access_to","label":"Access to recordings"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_eventsat04","ref":"overall","title":"Overall, how would you rate the event?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_eventsat05","ref":"expectations","title":"How did it compare with what you expected?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_better_than_expected","label":"Better than expected","image_key":null},{"id":"opt_about_what_i","label":"About what I expected","image_key":null},{"id":"opt_worse_than_expected","label":"Worse than expected","image_key":null}],"allowOther":false},{"id":"blk_eventsat06","ref":"highlight","title":"What was the most worthwhile moment for you?","description":"A session, a conversation, anything that made it worth coming.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_eventsat07","ref":"fell_short","title":"What disappointed you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_eventsat08","ref":"relevance","title":"How relevant were the sessions to your work or interests?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not relevant","labelHigh":"Very relevant"},{"id":"blk_eventsat09","ref":"value_most","title":"Rank what you value most at events like this","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_talks_and","label":"Talks and keynotes"},{"id":"opt_item_hands_on","label":"Hands-on workshops"},{"id":"opt_item_meeting_other","label":"Meeting other attendees"},{"id":"opt_item_exhibitors_and","label":"Exhibitors and demos"},{"id":"opt_item_social_events","label":"Social events"}]},{"id":"blk_eventsat10","ref":"next_topics","title":"What topics or speakers would you like to see next time?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_eventsat11","ref":"come_again","title":"Would you come to the next one?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_definitely","label":"Definitely","image_key":null},{"id":"opt_probably","label":"Probably","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null},{"id":"opt_probably_not","label":"Probably not","image_key":null}],"allowOther":false},{"id":"blk_eventsat12","ref":"recommend","title":"How likely are you to recommend this event to a colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"}],"endings":[{"id":"end_eventsat01","ref":"end_thanks","title":"Thanks for the feedback 🎟️","bodyMd":"We''ll use it to plan the next one. Hope to see you there.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"i