VALUES ('tpl_membersatisfactionsurvey', 'member-satisfaction-survey', 'Member satisfaction survey', 'Survey', 'Find out what members value, and why some might not renew.', 'Asks why people joined, ranks the benefits they care about and checks whether you contact them too much or too little. The renewal question decides the rest: loyal members say what they value most, undecided ones say what would help them choose, and members leaning towards leaving are asked why and what would change their mind.', '["customer satisfaction","member satisfaction survey","membership survey","association feedback","renewal","member retention"]', 'Users', 'number', 3, 13, '{"schemaVersion":9,"title":"Member satisfaction survey","description":"Find out what members value, and why some might not renew.","blocks":[{"id":"blk_membersa00","ref":"welcome","title":"Hi! As a member, your view shapes what we do next. This takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_membersa01","ref":"tenure","title":"How long have you been a member?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a year","image_key":null},{"id":"opt_1_to_2","label":"1 to 2 years","image_key":null},{"id":"opt_3_to_5","label":"3 to 5 years","image_key":null},{"id":"opt_more_than_5","label":"More than 5 years","image_key":null}],"allowOther":false},{"id":"blk_membersa02","ref":"why_joined","title":"Why did you join?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_meeting_people_in","label":"Meeting people in my field","image_key":null},{"id":"opt_events","label":"Events","image_key":null},{"id":"opt_learning_and_training","label":"Learning and training","image_key":null},{"id":"opt_member_discounts","label":"Member discounts","image_key":null},{"id":"opt_resources_and_publications","label":"Resources and publications","image_key":null},{"id":"opt_supporting_the_cause","label":"Supporting the cause","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_membersa03","ref":"benefit_rank","title":"Rank these benefits by how much they matter to you","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_events","label":"Events"},{"id":"opt_item_learning_and","label":"Learning and training"},{"id":"opt_item_networking","label":"Networking"},{"id":"opt_item_discounts","label":"Discounts"},{"id":"opt_item_resources_and","label":"Resources and publications"}]},{"id":"blk_membersa04","ref":"participation","title":"How often do you take part in something we run?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_most_months","label":"Most months","image_key":null},{"id":"opt_a_few_times","label":"A few times a year","image_key":null},{"id":"opt_once_a_year","label":"Once a year or less","image_key":null},{"id":"opt_i_haven_t","label":"I haven''t yet","image_key":null}],"allowOther":false},{"id":"blk_membersa05","ref":"value","title":"How good is your membership for what you pay?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Poor value","labelHigh":"Excellent value"},{"id":"blk_membersa06","ref":"comms","title":"How do you feel about how much you hear from us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_emails_and","label":"Emails and newsletters"},{"id":"opt_row_event_invitations","label":"Event invitations"},{"id":"opt_row_updates_from","label":"Updates from the board or committee"},{"id":"opt_row_social_media","label":"Social media"}],"columns":[{"id":"opt_col_too_little","label":"Too little"},{"id":"opt_col_about_right","label":"About right"},{"id":"opt_col_too_much","label":"Too much"}],"multiplePerRow":false},{"id":"blk_membersa07","ref":"renew","title":"How likely are you to renew when your membership is up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_definitely_renewing","label":"Definitely renewing","image_key":null},{"id":"opt_probably","label":"Probably","image_key":null},{"id":"opt_undecided","label":"Undecided","image_key":null},{"id":"opt_probably_not","label":"Probably not","image_key":null},{"id":"opt_definitely_not","label":"Definitely not","image_key":null}],"allowOther":false},{"id":"blk_membersa08","ref":"valued_most","title":"What do you value most about being a member?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_membersa09","ref":"help_decide","title":"What would help you decide?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_membersa10","ref":"leave_reasons","title":"What''s making you think about not renewing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_i_don_t","label":"I don''t use it enough","image_key":null},{"id":"opt_the_cost","label":"The cost","image_key":null},{"id":"opt_the_benefits_don","label":"The benefits don''t fit my needs any more","image_key":null},{"id":"opt_i_m_changing","label":"I''m changing jobs or moving","image_key":null},{"id":"opt_i_ve_found","label":"I''ve found something that suits me better","image_key":null},{"id":"opt_a_poor_experience","label":"A poor experience with us","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_membersa11","ref":"would_stay","title":"Is there anything that would make you stay?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_membersa12","ref":"recommend","title":"How likely are you to recommend membership to a colleague or friend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_membersa13","ref":"improve","title":"What''s one thing we should start, stop or change?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_membersa01","ref":"end_thanks","title":"Thanks for being a member 🙌","bodyMd":"We''ll share what we''re changing once we''ve read everyone''s answers.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_membersa02","ref":"end_leaving","title":"Thank you for being honest","bodyMd":"Hearing why people leave is how we get better. Whatever you decide, thanks for being a member.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_membersa01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"valued_most","target":"recommend","targetKind":"block"},{"id":"rl_membersa02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"help_decide","target":"recommend","targetKind":"block"},{"id":"rl_membersa03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"would_stay","target":"end_leaving","targetKind":"ending"},{"id":"rl_membersa04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"renew"},"op":"eq","value":"opt_definitely_renewing"}],"groups":[]},"from":"renew","target":"valued_most","targetKind":"block","branch":"true"},{"id":"rl_membersa05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"renew"},"op":"eq","value":"opt_probably"}],"groups":[]},"from":"renew","target":"valued_most","targetKind":"block","branch":"true"},{"id":"rl_membersa06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"renew"},"op":"eq","value":"opt_undecided"}],"groups":[]},"from":"renew","target":"help_decide","targetKind":"block","branch":"true"},{"id":"rl_membersa07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"renew"},"op":"eq","value":"opt_probably_not"}],"groups":[]},"from":"renew","target":"leave_reasons","targetKind":"block","branch":"true"},{"id":"rl_membersa08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"renew"},"op":"eq","value":"opt_definitely_not"}],"groups":[]},"from":"renew","target":"leave_reasons","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
