INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_csatsurvey', 'csat-survey', 'CSAT survey', 'Survey', 'Rate a specific interaction, and dig only where it went badly.', 'CSAT works when it is asked about one thing, straight after that thing happened. A customer with nothing outstanding gives one reason for their score and is done; anyone left with something unsorted is asked what is outstanding and what got in the way, and can ask a person to pick it up. Nobody is asked what went wrong when nothing did.', '["customer satisfaction","CSAT survey","customer satisfaction score","support feedback","post-interaction survey","customer feedback"]', 'SmilePlus', 'number', 3, 9, '{"schemaVersion":9,"title":"Customer satisfaction (CSAT)","description":"Rate a specific interaction, and dig only where it went badly.","blocks":[{"id":"blk_csatsurv00","ref":"welcome","title":"How did that go? A couple of questions while it''s fresh.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_csatsurv01","ref":"touchpoint","title":"What are you rating today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_conversation_with","label":"A conversation with support","image_key":null},{"id":"opt_a_purchase_or","label":"A purchase or delivery","image_key":null},{"id":"opt_getting_set_up","label":"Getting set up","image_key":null},{"id":"opt_using_the_product","label":"Using the product","image_key":null}],"allowOther":true},{"id":"blk_csatsurv02","ref":"satisfaction","title":"How satisfied were you overall?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_csatsurv03","ref":"effort","title":"How easy was it to get what you needed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":7,"startAt":1,"labelLow":"Very difficult","labelHigh":"Very easy"},{"id":"blk_csatsurv04","ref":"resolved","title":"Is everything sorted, with nothing left outstanding?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_csatsurv05","ref":"still_wrong","title":"What''s still outstanding?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_csatsurv06","ref":"friction","title":"What got in the way?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_took_too","label":"It took too long","image_key":null},{"id":"opt_i_had_to","label":"I had to repeat myself","image_key":null},{"id":"opt_the_answer_didn","label":"The answer didn''t fit my situation","image_key":null},{"id":"opt_i_was_sent","label":"I was sent to the wrong place","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_csatsurv07","ref":"callback","title":"Would you like someone to pick this up with you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes please","noLabel":"No, I''ll manage"},{"id":"blk_csatsurv08","ref":"callback_email","title":"Where can they reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_csatsurv09","ref":"score_reason","title":"What''s the main reason for the score you gave?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300}],"endings":[{"id":"end_csatsurv01","ref":"end_thanks","title":"Thanks for telling us ⭐","bodyMd":"Every answer is read by the team behind what you just used.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_csatsurv02","ref":"end_followup","title":"Someone will be in touch 📮","bodyMd":"We''ve flagged this as unresolved, and a person from the team will reply to the email you gave us.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_csatsurv01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"callback_email","target":"end_followup","targetKind":"ending"},{"id":"rl_csatsurv02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolved"},"op":"eq","value":false}],"groups":[]},"from":"resolved","target":"still_wrong","targetKind":"block","branch":"true"},{"id":"rl_csatsurv03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolved"},"op":"eq","value":true}],"groups":[]},"from":"resolved","target":"score_reason","targetKind":"block","branch":"true"},{"id":"rl_csatsurv04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"callback"},"op":"eq","value":false}],"groups":[]},"from":"callback","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
