INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_npssurvey', 'nps-survey', 'NPS survey', 'Survey', 'Measure loyalty, then ask detractors, passives and promoters different things.', 'The score on its own tells you almost nothing you can act on, and one follow-up cannot serve every part of the scale. A 3 is asked what went wrong and whether they are thinking of leaving, a 7 is asked what would make it a 9, and a 10 is asked what to quote, so one survey produces a fix list, a wish list and a testimonial list.', '["customer success","nps survey","net promoter score","customer loyalty","recommendation score","branching"]', 'Gauge', 'text', 2, 10, '{"schemaVersion":9,"title":"NPS survey","description":"Measure loyalty, then ask detractors, passives and promoters different things.","blocks":[{"id":"blk_npssurve00","ref":"welcome","title":"One quick question, plus a follow-up. It takes about a minute.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_npssurve01","ref":"score","title":"How likely are you to recommend us to a friend or colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_npssurve02","ref":"passive_gap","title":"What would it take for you to give us a 9 or a 10?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_npssurve03","ref":"went_wrong","title":"What''s gone wrong?","description":"Be blunt. The people who can fix it read these.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_npssurve04","ref":"problem_area","title":"Where does the trouble mostly sit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_s_missing","label":"It''s missing something I need","image_key":null},{"id":"opt_it_s_unreliable","label":"It''s unreliable","image_key":null},{"id":"opt_it_s_hard","label":"It''s hard to use","image_key":null},{"id":"opt_support_hasn_t","label":"Support hasn''t helped","image_key":null},{"id":"opt_it_costs_more","label":"It costs more than it''s worth","image_key":null}],"allowOther":true},{"id":"blk_npssurve05","ref":"at_risk","title":"Are you thinking about leaving?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Honestly, yes","noLabel":"Not right now"},{"id":"blk_npssurve06","ref":"what_works","title":"What do you like most about working with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_npssurve07","ref":"quote_ok","title":"May we quote that publicly?","description":"We would use your words without your name unless you tell us otherwise.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, go ahead","noLabel":"Please don''t"},{"id":"blk_npssurve08","ref":"improvement","title":"Is there one thing we could still do better?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_npssurve09","ref":"follow_up_ok","title":"Would it be alright if someone followed up about your answer?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Sure","noLabel":"No thanks"},{"id":"blk_npssurve10","ref":"email","title":"Where should we reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_npssurve01","ref":"end_thanks","title":"Thank you 💛","bodyMd":"Your answer goes straight to the team deciding what to improve next.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_npssurve02","ref":"end_follow_up","title":"Thanks, we''ll be in touch","bodyMd":"Someone who can act on your answer will email you within a few working days.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_npssurve01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"passive_gap","target":"follow_up_ok","targetKind":"block"},{"id":"rl_npssurve02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"at_risk","target":"follow_up_ok","targetKind":"block"},{"id":"rl_npssurve03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"email","target":"end_follow_up","targetKind":"ending"},{"id":"rl_npssurve04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"score"},"op":"lte","value":6}],"groups":[]},"from":"score","target":"went_wrong","targetKind":"block","branch":"true"},{"id":"rl_npssurve05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"score"},"op":"gte","value":9}],"groups":[]},"from":"score","target":"what_works","targetKind":"block","branch":"true"},{"id":"rl_npssurve06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"follow_up_ok"},"op":"eq","value":false}],"groups":[]},"from":"follow_up_ok","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ece3ff","surface":"#ffffff","text":"#2a1f3d","accent":"#6d3fc7","accentText":"#fbf8ff","botBubble":"#ffffff","userBubble":"#6d3fc7","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
