VALUES ('tpl_customerdevelopmentsurve', 'customer-development-survey', 'Customer development survey', 'Survey', 'Understand a problem through people''s real behaviour, before you build anything.', 'Built around what people have actually done, not what they say they would buy. It asks about the last time the problem came up, what they use now and how many hours it eats, then screens out anyone who never faces it. Only people who have tried to fix it are asked what failed, and anyone willing to talk is asked for an email.', '["customer success","customer development","problem interview","customer discovery","startup research","product validation"]', 'Search', 'text', 4, 11, '{"schemaVersion":9,"title":"Customer development","description":"Understand a problem through people''s real behaviour, before you build anything.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"We''re trying to understand how people plan staff shifts today. No sales pitch, just a few questions.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"role","title":"Which of these describes you best?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_own_or","label":"I own or run the business","image_key":null},{"id":"opt_i_manage_a","label":"I manage a team","image_key":null},{"id":"opt_i_m_on","label":"I''m on a team that gets scheduled","image_key":null}],"allowOther":true},{"id":"blk_customer02","ref":"last_time","title":"When did you last have to plan staff shifts?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_this_week","label":"This week","image_key":null},{"id":"opt_this_month","label":"This month","image_key":null},{"id":"opt_a_few_months","label":"A few months ago","image_key":null},{"id":"opt_i_never_do","label":"I never do this","image_key":null}],"allowOther":false},{"id":"blk_customer03","ref":"last_story","title":"Walk us through that last time. What did you do, step by step?","description":"The small details are the useful part.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_customer04","ref":"current_tools","title":"What do you use for it today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_a_spreadsheet","label":"A spreadsheet","image_key":null},{"id":"opt_paper_or_a","label":"Paper or a whiteboard","image_key":null},{"id":"opt_messages_in_a","label":"Messages in a group chat","image_key":null},{"id":"opt_scheduling_software","label":"Scheduling software","image_key":null},{"id":"opt_someone_else_handles","label":"Someone else handles it","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":true},{"id":"blk_customer05","ref":"hours","title":"Roughly how many hours a week does it take, including fixing changes?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":80,"integerOnly":false},{"id":"blk_customer06","ref":"hardest","title":"What''s the most frustrating part of it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_customer07","ref":"pain","title":"How much of a problem is this for you right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"I barely notice it","labelHigh":"It costs us every week"},{"id":"blk_customer08","ref":"tried_fix","title":"Have you tried or paid for anything to fix it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_customer09","ref":"tried_what","title":"What did you try, and why didn''t it stick?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_customer10","ref":"interview","title":"Would you be up for a 20-minute call to talk it through?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Happy to","noLabel":"Not this time"},{"id":"blk_customer11","ref":"email","title":"What''s the best email to arrange it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"Thank you","bodyMd":"Your story is exactly what we needed. We read every answer ourselves.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_customer02","ref":"end_not_fit","title":"Thanks for stopping by","bodyMd":"This one is for people who plan shifts, so we won''t take more of your time.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_customer03","ref":"end_call","title":"Thanks, talk soon 👋","bodyMd":"We''ll email you a couple of times to choose from. No slides, just questions.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"email","target":"end_call","targetKind":"ending"},{"id":"rl_customer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"last_time"},"op":"eq","value":"opt_i_never_do"}],"groups":[]},"from":"last_time","target":"end_not_fit","targetKind":"ending","branch":"true"},{"id":"rl_customer03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"tried_fix"},"op":"eq","value":false}],"groups":[]},"from":"tried_fix","target":"interview","targetKind":"block","branch":"true"},{"id":"rl_customer04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"interview"},"op":"eq","value":false}],"groups":[]},"from":"interview","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ece3ff","surface":"#ffffff","text":"#2a1f3d","accent":"#6d3fc7","accentText":"#fbf8ff","botBubble":"#ffffff","userBubble":"#6d3fc7","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
