INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_customerloyaltysurvey', 'customer-loyalty-survey', 'Customer loyalty survey', 'Survey', 'Learn what keeps customers coming back and what could pull them away.', 'Satisfied customers still leave, so this survey asks about the relationship rather than one visit: why people come back, how much they trust you and what would make them switch. Anyone unlikely to return is asked why straight away instead of being asked what keeps them, and only customers who have looked at alternatives are asked what they found.', '["customer success","customer loyalty","retention survey","repeat customers","switching risk","branching"]', 'HeartHandshake', 'text', 3, 10, '{"schemaVersion":9,"title":"Customer loyalty","description":"Learn what keeps customers coming back and what could pull them away.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"You''ve stuck with us, and we''d love to know why. A few quick questions.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"tenure","title":"How long have you been a customer?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_6","label":"Less than 6 months","image_key":null},{"id":"opt_6_to_12","label":"6 to 12 months","image_key":null},{"id":"opt_1_to_3","label":"1 to 3 years","image_key":null},{"id":"opt_more_than_3","label":"More than 3 years","image_key":null}],"allowOther":false},{"id":"blk_customer02","ref":"return_likely","title":"How likely are you to buy from us again?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Very unlikely","labelHigh":"Very likely"},{"id":"blk_customer03","ref":"low_reason","title":"What''s making you less likely to come back?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_customer04","ref":"why_stay","title":"What keeps you choosing us?","description":"Pick up to three.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_quality_of_what","label":"Quality of what we sell","image_key":null},{"id":"opt_fair_prices","label":"Fair prices","image_key":null},{"id":"opt_friendly_helpful_service","label":"Friendly, helpful service","image_key":null},{"id":"opt_it_s_convenient","label":"It''s convenient","image_key":null},{"id":"opt_i_trust_you","label":"I trust you to get it right","image_key":null},{"id":"opt_honestly_habit","label":"Honestly, habit","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_customer05","ref":"trust","title":"How much do you trust us to get things right when something goes wrong?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_customer06","ref":"shopped_around","title":"Have you looked at other options in the last six months?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_customer07","ref":"alternatives","title":"What made you look, and what did you find?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_customer08","ref":"switch_trigger","title":"What would be most likely to make you switch?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_price_increase","label":"A price increase","image_key":null},{"id":"opt_a_drop_in","label":"A drop in quality","image_key":null},{"id":"opt_poor_service_when","label":"Poor service when something goes wrong","image_key":null},{"id":"opt_a_competitor_with","label":"A competitor with a better offer","image_key":null},{"id":"opt_nothing_i_can","label":"Nothing I can think of","image_key":null}],"allowOther":false},{"id":"blk_customer09","ref":"recommend","title":"How likely are you to recommend us to a friend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_customer10","ref":"one_thing","title":"What''s one thing we could do to earn your next purchase?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"Thanks for being straight with us 🙌","bodyMd":"We''ll use your answers to keep doing what you value and fix what you don''t.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"low_reason","target":"trust","targetKind":"block"},{"id":"rl_customer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"return_likely"},"op":"gte","value":3}],"groups":[]},"from":"return_likely","target":"why_stay","targetKind":"block","branch":"true"},{"id":"rl_customer03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"shopped_around"},"op":"eq","value":false}],"groups":[]},"from":"shopped_around","target":"switch_trigger","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
