INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_customerneedssurvey', 'customer-needs-survey', 'Customer needs survey', 'Survey', 'Find out what customers are trying to achieve and what stands in their way.', 'Starts from the customer''s goal instead of your feature list, then asks what slows them down, how much each quality matters and which improvements they would rank first. Customers who say current options only partly work, or not at all, are asked what''s missing before anything else.', '["customer success","customer needs","needs assessment","customer research","feature priorities","branching"]', 'Target', 'text', 3, 10, '{"schemaVersion":9,"title":"Customer needs","description":"Find out what customers are trying to achieve and what stands in their way.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"Help us understand what you need from us. It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"goal","title":"What are you trying to get done when you come to us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_customer02","ref":"frequency","title":"How often do you need to do that?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_every_week","label":"Every week","image_key":null},{"id":"opt_every_month","label":"Every month","image_key":null},{"id":"opt_less_often","label":"Less often","image_key":null}],"allowOther":false},{"id":"blk_customer03","ref":"obstacles","title":"What gets in the way most often?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_it_takes_too","label":"It takes too long","image_key":null},{"id":"opt_too_many_steps","label":"Too many steps or tools","image_key":null},{"id":"opt_it_s_hard","label":"It''s hard to learn","image_key":null},{"id":"opt_it_costs_too","label":"It costs too much","image_key":null},{"id":"opt_getting_help_is","label":"Getting help is slow","image_key":null},{"id":"opt_nothing_really","label":"Nothing really","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":true},{"id":"blk_customer04","ref":"obstacle_story","title":"Tell us about the last time something slowed you down.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_customer05","ref":"importance","title":"How much does each of these matter to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_speed","label":"Speed"},{"id":"opt_row_ease_of","label":"Ease of use"},{"id":"opt_row_price","label":"Price"},{"id":"opt_row_reliability","label":"Reliability"},{"id":"opt_row_help_from","label":"Help from a real person"}],"columns":[{"id":"opt_col_not_much","label":"Not much"},{"id":"opt_col_somewhat","label":"Somewhat"},{"id":"opt_col_a_lot","label":"A lot"},{"id":"opt_col_it_s","label":"It''s essential"}],"multiplePerRow":false},{"id":"blk_customer06","ref":"priorities","title":"Which improvements would help you most? Put the best first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_faster_results","label":"Faster results"},{"id":"opt_item_simpler_setup","label":"Simpler setup"},{"id":"opt_item_better_guides","label":"Better guides and help content"},{"id":"opt_item_more_ways","label":"More ways to get support"},{"id":"opt_item_more_flexible","label":"More flexible pricing"}]},{"id":"blk_customer07","ref":"needs_met","title":"How well do the options available to you today meet your needs?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_fully","label":"Fully","image_key":null},{"id":"opt_mostly","label":"Mostly","image_key":null},{"id":"opt_only_partly","label":"Only partly","image_key":null},{"id":"opt_not_at_all","label":"Not at all","image_key":null}],"allowOther":false},{"id":"blk_customer08","ref":"missing","title":"What''s missing? What would a good solution do that nothing does now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_customer09","ref":"follow_up_ok","title":"Could we contact you to hear more?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, that''s fine","noLabel":"No, thanks"},{"id":"blk_customer10","ref":"email","title":"What email should we use?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"Thank you","bodyMd":"Your answers go straight into how we plan the next few months.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"needs_met"},"op":"eq","value":"opt_fully"}],"groups":[]},"from":"needs_met","target":"follow_up_ok","targetKind":"block","branch":"true"},{"id":"rl_customer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"needs_met"},"op":"eq","value":"opt_mostly"}],"groups":[]},"from":"needs_met","target":"follow_up_ok","targetKind":"block","branch":"true"},{"id":"rl_customer03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"follow_up_ok"},"op":"eq","value":false}],"groups":[]},"from":"follow_up_ok","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#f26b1d","surface":"#fff7f0","text":"#1c1917","accent":"#1c1917","accentText":"#ffffff","botBubble":"#fff7f0","userBubble":"#1c1917","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundPatternColor":"#1c1917","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
