VALUES ('tpl_helpdeskfeedbacksurvey', 'help-desk-feedback-survey', 'Help desk feedback survey', 'Survey', 'Check whether a help desk request was understood, explained and actually fixed.', 'Sent after a ticket closes, it asks the question most help desk surveys skip: is the problem really fixed? Anyone who says no is asked what still isn''t working and whether to reopen the ticket, before rating how well the request was understood and explained.', '["customer success","help desk survey","it support feedback","ticket feedback","service desk","branching"]', 'LifeBuoy', 'text', 4, 11, '{"schemaVersion":9,"title":"Help desk feedback","description":"Check whether a help desk request was understood, explained and actually fixed.","blocks":[{"id":"blk_helpdesk00","ref":"welcome","title":"Your help desk request was closed. Mind telling us how it went? It takes a minute.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_helpdesk01","ref":"ticket","title":"What was the ticket number, if you have it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_helpdesk02","ref":"request_type","title":"What did you contact us about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_password_or_login","label":"Password or login","image_key":null},{"id":"opt_laptop_phone_or","label":"Laptop, phone or other hardware","image_key":null},{"id":"opt_software_or_an","label":"Software or an app","image_key":null},{"id":"opt_access_or_permissions","label":"Access or permissions","image_key":null},{"id":"opt_email_or_calendar","label":"Email or calendar","image_key":null},{"id":"opt_network_or_wi","label":"Network or Wi-Fi","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_helpdesk03","ref":"resolved","title":"Is the problem fixed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_fully","label":"Yes, fully","image_key":null},{"id":"opt_partly","label":"Partly","image_key":null},{"id":"opt_no_not_yet","label":"No, not yet","image_key":null}],"allowOther":false},{"id":"blk_helpdesk04","ref":"still_broken","title":"What''s still not working?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_helpdesk05","ref":"reopen","title":"Should we reopen the ticket?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, please","noLabel":"No, I''ll manage"},{"id":"blk_helpdesk06","ref":"understood","title":"How well did we understand your request the first time you explained it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_helpdesk07","ref":"clarity","title":"How clear was the explanation or next step we gave you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_helpdesk08","ref":"time_to_fix","title":"How long did it take from asking to having an answer?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_an_hour","label":"Under an hour","image_key":null},{"id":"opt_same_day","label":"Same day","image_key":null},{"id":"opt_1_to_2","label":"1 to 2 days","image_key":null},{"id":"opt_longer_than_2","label":"Longer than 2 days","image_key":null}],"allowOther":false},{"id":"blk_helpdesk09","ref":"work_blocked","title":"Were you unable to work while you waited?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_helpdesk10","ref":"overall","title":"Overall, how satisfied are you with the help you got?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_helpdesk11","ref":"comments","title":"Anything that would have made this easier?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_helpdesk01","ref":"end_thanks","title":"Thanks for the feedback","bodyMd":"If you asked us to reopen your ticket, someone will pick it up today.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_helpdesk01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolved"},"op":"eq","value":"opt_yes_fully"}],"groups":[]},"from":"resolved","target":"understood","targetKind":"block","branch":"true"},{"id":"rl_helpdesk02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"resolved"},"op":"eq","value":"opt_partly"}],"groups":[]},"from":"resolved","target":"understood","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
