INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_hotelfeedbacksurvey', 'hotel-feedback-survey', 'Hotel feedback survey', 'Survey', 'Hear how a stay really went, from check-in to anything that went wrong.', 'Covers each part of a stay in one grid, then asks the question that matters most to a hotel manager: did anything go wrong, and did the team fix it? Guests with no problems skip straight past it, and anyone who wants the manager to reply leaves an email and gets a different sign-off.', '["customer success","hotel feedback","guest survey","hospitality","post-stay survey","branching"]', 'Hotel', 'text', 4, 12, '{"schemaVersion":9,"title":"Hotel guest feedback","description":"Hear how a stay really went, from check-in to anything that went wrong.","blocks":[{"id":"blk_hotelfee00","ref":"welcome","title":"Thanks for staying with us. How was it? A few questions, about two minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_hotelfee01","ref":"checkout","title":"When did you check out?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_hotelfee02","ref":"purpose","title":"What brought you here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_work","label":"Work","image_key":null},{"id":"opt_a_holiday_or","label":"A holiday or break","image_key":null},{"id":"opt_a_wedding_or","label":"A wedding or event","image_key":null},{"id":"opt_passing_through","label":"Passing through","image_key":null}],"allowOther":false},{"id":"blk_hotelfee03","ref":"overall","title":"How was your stay overall?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_hotelfee04","ref":"aspects","title":"How would you rate each part of your stay?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_check_in","label":"Check-in"},{"id":"opt_row_room_cleanliness","label":"Room cleanliness"},{"id":"opt_row_bed_and","label":"Bed and a good night''s sleep"},{"id":"opt_row_staff_friendliness","label":"Staff friendliness"},{"id":"opt_row_breakfast","label":"Breakfast"},{"id":"opt_row_wi_fi","label":"Wi-Fi"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"},{"id":"opt_col_didn_t","label":"Didn''t use"}],"multiplePerRow":false},{"id":"blk_hotelfee05","ref":"facilities","title":"Which facilities did you use?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_restaurant","label":"Restaurant","image_key":null},{"id":"opt_bar","label":"Bar","image_key":null},{"id":"opt_pool","label":"Pool","image_key":null},{"id":"opt_gym","label":"Gym","image_key":null},{"id":"opt_spa","label":"Spa","image_key":null},{"id":"opt_room_service","label":"Room service","image_key":null},{"id":"opt_parking","label":"Parking","image_key":null},{"id":"opt_none_of_these","label":"None of these","image_key":null}],"minSelections":0,"maxSelections":8,"allowOther":false},{"id":"blk_hotelfee06","ref":"had_issue","title":"Did anything go wrong during your stay?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_hotelfee07","ref":"issue_detail","title":"What happened?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_hotelfee08","ref":"issue_fixed","title":"Did our team sort it out?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_quickly","label":"Yes, quickly","image_key":null},{"id":"opt_yes_but_it","label":"Yes, but it took a while","image_key":null},{"id":"opt_no","label":"No","image_key":null},{"id":"opt_i_didn_t","label":"I didn''t mention it","image_key":null}],"allowOther":false},{"id":"blk_hotelfee09","ref":"recommend","title":"How likely are you to recommend us to friends or family?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_hotelfee10","ref":"keep","title":"What''s one thing we should never change?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_hotelfee11","ref":"manager_reply","title":"Would you like the manager to reply to you personally?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, please","noLabel":"No need"},{"id":"blk_hotelfee12","ref":"email","title":"What email should the manager use?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_hotelfee01","ref":"end_thanks","title":"Thank you, we hope to see you again 🏨","bodyMd":"Every answer is read by the team who looked after you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_hotelfee02","ref":"end_manager","title":"Thank you, the manager will be in touch","bodyMd":"Expect an email within two days. If it''s urgent, call the front desk.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_hotelfee01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"email","target":"end_manager","targetKind":"ending"},{"id":"rl_hotelfee02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"had_issue"},"op":"eq","value":false}],"groups":[]},"from":"had_issue","target":"recommend","targetKind":"block","branch":"true"},{"id":"rl_hotelfee03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"manager_reply"},"op":"eq","value":false}],"groups":[]},"from":"manager_reply","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ece3ff","surface":"#ffffff","text":"#2a1f3d","accent":"#6d3fc7","accentText":"#fbf8ff","botBubble":"#ffffff","userBubble":"#6d3fc7","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
