VALUES ('tpl_serviceevaluationsurvey', 'service-evaluation-survey', 'Service evaluation survey', 'Survey', 'Evaluate a service against the job it was hired to do.', 'Asks what the client needed the service to do before asking how it went, so every rating has something to be measured against. If the service did the job, it asks which step worked best; if it only partly did, it asks where things went wrong and how much that mattered.', '["customer success","service evaluation","service quality","client survey","delivery review","branching"]', 'ClipboardCheck', 'text', 3, 10, '{"schemaVersion":9,"title":"Service evaluation","description":"Evaluate a service against the job it was hired to do.","blocks":[{"id":"blk_servicee00","ref":"welcome","title":"We''d like to know how well our service did its job for you. About two minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_servicee01","ref":"service","title":"Which service are you evaluating?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_servicee02","ref":"job","title":"What did you need this service to do for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_servicee03","ref":"aspects","title":"How did we do on each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_delivered_on","label":"Delivered on time"},{"id":"opt_row_matched_what","label":"Matched what was agreed"},{"id":"opt_row_quality_of","label":"Quality of the work"},{"id":"opt_row_keeping_you","label":"Keeping you updated"},{"id":"opt_row_value_for","label":"Value for what it cost"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_servicee04","ref":"usefulness","title":"How useful has the result been since?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not useful","labelHigh":"Very useful"},{"id":"blk_servicee05","ref":"did_job","title":"Did the service do the job you needed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_completely","label":"Yes, completely","image_key":null},{"id":"opt_mostly","label":"Mostly","image_key":null},{"id":"opt_only_partly","label":"Only partly","image_key":null},{"id":"opt_not_at_all","label":"Not at all","image_key":null}],"allowOther":false},{"id":"blk_servicee06","ref":"went_well","title":"Which part or step worked best for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_servicee07","ref":"went_wrong","title":"Where did things go wrong or slow down?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_servicee08","ref":"impact","title":"How much did that affect you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_little_easy","label":"A little, easy to work around","image_key":null},{"id":"opt_noticeably_it_cost","label":"Noticeably, it cost us time","image_key":null},{"id":"opt_seriously_we_missed","label":"Seriously, we missed something important","image_key":null}],"allowOther":false},{"id":"blk_servicee09","ref":"use_again","title":"Would you use this service again?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_servicee10","ref":"suggestions","title":"What should we change before the next client?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_servicee01","ref":"end_thanks","title":"Thanks for the honest review","bodyMd":"We''ll go through it as a team and let you know what changes.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_servicee01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"went_well","target":"use_again","targetKind":"block"},{"id":"rl_servicee02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"did_job"},"op":"eq","value":"opt_yes_completely"}],"groups":[]},"from":"did_job","target":"went_well","targetKind":"block","branch":"true"},{"id":"rl_servicee03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"did_job"},"op":"eq","value":"opt_mostly"}],"groups":[]},"from":"did_job","target":"went_well","targetKind":"block","branch":"true"},{"id":"rl_servicee04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"did_job"},"op":"eq","value":"opt_only_partly"}],"groups":[]},"from":"did_job","target":"went_wrong","targetKind":"block","branch":"true"},{"id":"rl_servicee05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"did_job"},"op":"eq","value":"opt_not_at_all"}],"groups":[]},"from":"did_job","target":"went_wrong","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
