VALUES ('tpl_softwarecustomersatisfac', 'software-customer-satisfaction-survey', 'Software customer satisfaction survey', 'Survey', 'Measure how users feel about your software, and catch bugs and gaps along the way.', 'Built for software teams: a satisfaction score, a grid for ease of use, speed, features, docs and support, and a ranking of what users value most. Unhappy users are asked why before anything else, and only people who hit a bug are asked to describe it and attach a screenshot.', '["customer success","software satisfaction survey","saas csat","user feedback","product survey","bug report","branching"]', 'Laptop', 'text', 4, 12, '{"schemaVersion":9,"title":"Software satisfaction","description":"Measure how users feel about your software, and catch bugs and gaps along the way.","blocks":[{"id":"blk_software00","ref":"welcome","title":"Help us make the software better for you. About three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_software01","ref":"usage_length","title":"How long have you been using our software?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a month","image_key":null},{"id":"opt_1_to_6","label":"1 to 6 months","image_key":null},{"id":"opt_6_to_12","label":"6 to 12 months","image_key":null},{"id":"opt_more_than_a","label":"More than a year","image_key":null}],"allowOther":false},{"id":"blk_software02","ref":"usage_frequency","title":"How often do you use it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_a_few_times","label":"A few times a week","image_key":null},{"id":"opt_a_few_times_2","label":"A few times a month","image_key":null},{"id":"opt_rarely","label":"Rarely","image_key":null}],"allowOther":false},{"id":"blk_software03","ref":"csat","title":"Overall, how satisfied are you with the software?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_software04","ref":"low_reason","title":"Sorry it''s not working for you. What''s the main problem?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_software05","ref":"aspects","title":"How would you rate each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_ease_of","label":"Ease of use"},{"id":"opt_row_speed_and","label":"Speed and reliability"},{"id":"opt_row_has_the","label":"Has the features I need"},{"id":"opt_row_help_docs","label":"Help docs"},{"id":"opt_row_support_team","label":"Support team"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_software06","ref":"values","title":"What matters most to you? Put the most important first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_saves_me","label":"Saves me time"},{"id":"opt_item_easy_to","label":"Easy to learn"},{"id":"opt_item_works_reliably","label":"Works reliably"},{"id":"opt_item_fits_how","label":"Fits how my team works"},{"id":"opt_item_good_support","label":"Good support"}]},{"id":"blk_software07","ref":"missing","title":"Is there something you expected it to do that it doesn''t?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_software08","ref":"hit_bug","title":"Have you run into a bug or error in the last month?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_software09","ref":"bug_detail","title":"What happened, and where in the app were you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_software10","ref":"bug_screenshot","title":"Got a screenshot? Drop it here.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*"],"maxFiles":3,"maxSizeMB":10},{"id":"blk_software11","ref":"recommend","title":"How likely are you to recommend the software to a colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_software12","ref":"email","title":"Your email, if you''re happy for us to follow up","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_software01","ref":"end_thanks","title":"Thank you 🙏","bodyMd":"Your answers go to the product and support teams this week.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_software01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"csat"},"op":"gte","value":3}],"groups":[]},"from":"csat","target":"aspects","targetKind":"block","branch":"true"},{"id":"rl_software02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"hit_bug"},"op":"eq","value":false}],"groups":[]},"from":"hit_bug","target":"recommend","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
