VALUES ('tpl_companysatisfactionsurve', 'company-satisfaction-survey', 'Company satisfaction survey', 'Survey', 'Learn how people feel about working here, and who might be thinking of leaving.', 'Covers the whole job in one grid, from day-to-day work to pay and leadership, then asks people to rank the changes that would matter most. Staff who wouldn''t recommend working here are asked whether they have thought about leaving and what is behind it, while happier staff are asked what''s worth protecting.', '["employee satisfaction","employee satisfaction survey","company culture","staff survey","employee retention","branching"]', 'Building2', 'scale', 4, 12, '{"schemaVersion":9,"title":"Company satisfaction","description":"Learn how people feel about working here, and who might be thinking of leaving.","blocks":[{"id":"blk_companys00","ref":"welcome","title":"This survey is anonymous and takes about four minutes. Honest answers help most.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_companys01","ref":"department","title":"Which part of the company do you work in?","description":"Only used to group results, never to identify you.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_operations","label":"Operations","image_key":null},{"id":"opt_sales_and_marketing","label":"Sales and marketing","image_key":null},{"id":"opt_product_and_engineering","label":"Product and engineering","image_key":null},{"id":"opt_customer_support","label":"Customer support","image_key":null},{"id":"opt_finance_and_admin","label":"Finance and admin","image_key":null},{"id":"opt_people_and_hr","label":"People and HR","image_key":null},{"id":"opt_other","label":"Other","image_key":null}]},{"id":"blk_companys02","ref":"tenure","title":"How long have you worked here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a year","image_key":null},{"id":"opt_1_to_3","label":"1 to 3 years","image_key":null},{"id":"opt_3_to_5","label":"3 to 5 years","image_key":null},{"id":"opt_more_than_5","label":"More than 5 years","image_key":null}],"allowOther":false},{"id":"blk_companys03","ref":"overall","title":"Overall, how satisfied are you working here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_companys04","ref":"areas","title":"How do you feel about each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_your_day","label":"Your day-to-day work"},{"id":"opt_row_your_manager","label":"Your manager"},{"id":"opt_row_your_team","label":"Your team"},{"id":"opt_row_pay_and","label":"Pay and benefits"},{"id":"opt_row_your_workload","label":"Your workload"},{"id":"opt_row_chances_to","label":"Chances to learn and grow"},{"id":"opt_row_communication_from","label":"Communication from leadership"}],"columns":[{"id":"opt_col_unhappy","label":"Unhappy"},{"id":"opt_col_mixed","label":"Mixed"},{"id":"opt_col_happy","label":"Happy"},{"id":"opt_col_very_happy","label":"Very happy"}],"multiplePerRow":false},{"id":"blk_companys05","ref":"direction","title":"I understand where the company is heading and why.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_companys06","ref":"tools","title":"I have what I need to do my job well.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_companys07","ref":"changes","title":"Which changes would make the biggest difference to you? Put the biggest first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_clearer_communication","label":"Clearer communication"},{"id":"opt_item_better_pay","label":"Better pay or benefits"},{"id":"opt_item_more_flexible","label":"More flexible hours"},{"id":"opt_item_better_tools","label":"Better tools and equipment"},{"id":"opt_item_more_training","label":"More training"},{"id":"opt_item_a_fairer","label":"A fairer workload"}]},{"id":"blk_companys08","ref":"enps","title":"How likely are you to recommend working here to a friend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_companys09","ref":"thought_leaving","title":"Have you thought about leaving in the last six months?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_companys10","ref":"leave_reason","title":"What''s behind that? What would change your mind?","description":"Still anonymous. Nobody will try to work out who wrote this.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_companys11","ref":"best_thing","title":"What''s the best thing about working here?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_companys12","ref":"one_change","title":"If you could change one thing tomorrow, what would it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_companys01","ref":"end_thanks","title":"Thank you for being honest 💬","bodyMd":"We''ll share what we heard, and what we plan to do about it, within a month.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_companys01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"leave_reason","target":"one_change","targetKind":"block"},{"id":"rl_companys02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"enps"},"op":"gte","value":7}],"groups":[]},"from":"enps","target":"best_thing","targetKind":"block","branch":"true"},{"id":"rl_companys03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"thought_leaving"},"op":"eq","value":false}],"groups":[]},"from":"thought_leaving","target":"one_change","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
