VALUES ('tpl_employeeonboardingsurvey', 'employee-on-boarding-survey', 'Employee onboarding survey', 'Survey', 'Find out whether new starters got what they needed in their first weeks.', 'Asks the practical questions first: was the laptop ready, did the logins work, who introduced themselves. Then it checks whether the new hire knows what''s expected of them. Anyone still unsure is asked what about, and can leave their details for HR to follow up.', '["employee satisfaction","onboarding survey","new hire survey","employee onboarding","first 30 days","branching"]', 'UserCheck', 'scale', 4, 14, '{"schemaVersion":9,"title":"New hire onboarding","description":"Find out whether new starters got what they needed in their first weeks.","blocks":[{"id":"blk_employee00","ref":"welcome","title":"Welcome aboard! Tell us how your first few weeks have gone. About three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_employee01","ref":"time_in_role","title":"How long ago did you start?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_two","label":"Less than two weeks","image_key":null},{"id":"opt_two_to_four","label":"Two to four weeks","image_key":null},{"id":"opt_one_to_three","label":"One to three months","image_key":null},{"id":"opt_longer_than_that","label":"Longer than that","image_key":null}],"allowOther":false},{"id":"blk_employee02","ref":"team","title":"Which team did you join?","description":"Leave it blank if your team is small enough that this would identify you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_employee03","ref":"first_day","title":"How did your first day feel?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"heart"},{"id":"blk_employee04","ref":"ready","title":"When were these ready for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_laptop_and","label":"Laptop and equipment"},{"id":"opt_row_logins_and","label":"Logins and accounts"},{"id":"opt_row_a_place","label":"A place to work"},{"id":"opt_row_a_plan","label":"A plan for your first week"}],"columns":[{"id":"opt_col_on_day","label":"On day one"},{"id":"opt_col_within_a","label":"Within a few days"},{"id":"opt_col_after_a","label":"After a week or more"},{"id":"opt_col_still_waiting","label":"Still waiting"}],"multiplePerRow":false},{"id":"blk_employee05","ref":"intros","title":"Who gave you a proper introduction?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_my_manager","label":"My manager","image_key":null},{"id":"opt_my_team","label":"My team","image_key":null},{"id":"opt_a_buddy_or","label":"A buddy or mentor","image_key":null},{"id":"opt_people_in_other","label":"People in other teams I work with","image_key":null},{"id":"opt_nobody_really","label":"Nobody really","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_employee06","ref":"checkins","title":"How often has your manager checked in with you so far?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_a_few_times","label":"A few times a week","image_key":null},{"id":"opt_about_once_a","label":"About once a week","image_key":null},{"id":"opt_less_than_that","label":"Less than that","image_key":null}],"allowOther":false},{"id":"blk_employee07","ref":"expectations","title":"I know what''s expected of me in my role.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_employee08","ref":"most_helpful","title":"What helped you most in your first weeks?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_employee09","ref":"still_unsure","title":"Is there anything you''re still unsure about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_employee10","ref":"unsure_what","title":"What''s still unclear?","description":"Pay, policies, tools, your role: anything counts.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_employee11","ref":"hr_contact","title":"Would you like someone from HR to get in touch about it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, please","noLabel":"No, I''ll ask around"},{"id":"blk_employee12","ref":"contact","title":"How can HR reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_employee13","ref":"prepared","title":"Overall, how well did onboarding prepare you for the job?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Very well"},{"id":"blk_employee14","ref":"suggestion","title":"What should we do differently for the next new starter?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_employee01","ref":"end_thanks","title":"Thanks, and welcome again 🎉","bodyMd":"Your answers help us make the next person''s first weeks smoother.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_employee01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"still_unsure"},"op":"eq","value":false}],"groups":[]},"from":"still_unsure","target":"prepared","targetKind":"block","branch":"true"},{"id":"rl_employee02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"hr_contact"},"op":"eq","value":false}],"groups":[]},"from":"hr_contact","target":"prepared","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
