VALUES ('tpl_itsatisfactionsurvey', 'it-satisfaction-survey', 'IT satisfaction survey', 'Survey', 'Find out how well everyday tech and IT support are working for your team.', 'Rates each everyday system in one grid, from laptops to video calls, and asks how often tech problems interrupt real work. Only people who have asked IT for help recently are asked to rate the support, so the scores come from people who have actually used it.', '["employee satisfaction","it satisfaction survey","internal it survey","tech feedback","help desk","employee survey","branching"]', 'Wrench', 'scale', 3, 10, '{"schemaVersion":9,"title":"IT satisfaction","description":"Find out how well everyday tech and IT support are working for your team.","blocks":[{"id":"blk_itsatisf00","ref":"welcome","title":"How well is your tech working for you? A few quick questions for the IT team.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_itsatisf01","ref":"work_setup","title":"Where do you mostly work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_the_office","label":"In the office","image_key":null},{"id":"opt_at_home","label":"At home","image_key":null},{"id":"opt_a_mix_of","label":"A mix of both","image_key":null},{"id":"opt_on_the_road","label":"On the road or on site","image_key":null}],"allowOther":false},{"id":"blk_itsatisf02","ref":"overall","title":"Overall, how satisfied are you with IT at work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_itsatisf03","ref":"systems","title":"How well does each of these work for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_laptop_or","label":"Laptop or computer"},{"id":"opt_row_wi_fi","label":"Wi-Fi and network"},{"id":"opt_row_email_and","label":"Email and calendar"},{"id":"opt_row_video_calls","label":"Video calls"},{"id":"opt_row_the_main","label":"The main apps you work in"},{"id":"opt_row_printing","label":"Printing"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"},{"id":"opt_col_don_t","label":"Don''t use"}],"multiplePerRow":false},{"id":"blk_itsatisf04","ref":"interruptions","title":"How often do tech problems stop you from working?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_rarely_or_never","label":"Rarely or never","image_key":null},{"id":"opt_a_few_times","label":"A few times a month","image_key":null},{"id":"opt_every_week","label":"Every week","image_key":null},{"id":"opt_most_days","label":"Most days","image_key":null}],"allowOther":false},{"id":"blk_itsatisf05","ref":"asked_it","title":"Have you asked IT for help in the last three months?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_itsatisf06","ref":"support_speed","title":"How quickly did you get help?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Far too slow","labelHigh":"Very quickly"},{"id":"blk_itsatisf07","ref":"support_quality","title":"How well was your problem solved?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_itsatisf08","ref":"biggest_blocker","title":"Which tech problem costs you the most time?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_itsatisf09","ref":"wishes","title":"What would help you most? Pick up to three.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_a_faster_laptop","label":"A faster laptop","image_key":null},{"id":"opt_better_wi_fi","label":"Better Wi-Fi","image_key":null},{"id":"opt_fewer_passwords_and","label":"Fewer passwords and logins","image_key":null},{"id":"opt_training_on_the","label":"Training on the tools we use","image_key":null},{"id":"opt_quicker_help_desk","label":"Quicker help desk replies","image_key":null},{"id":"opt_better_equipment_for","label":"Better equipment for working from home","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_itsatisf10","ref":"comments","title":"Anything else the IT team should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_itsatisf01","ref":"end_thanks","title":"Thanks for helping us fix things 🔧","bodyMd":"The IT team will share what they''re changing next quarter.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_itsatisf01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"asked_it"},"op":"eq","value":false}],"groups":[]},"from":"asked_it","target":"biggest_blocker","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"all