VALUES ('tpl_engagementpulse', 'engagement-pulse', 'Employee pulse survey', 'Survey', 'A short, repeatable check that follows up with the people who are struggling.', 'Short enough to send every month and consistent enough to trend: five statements on workload, clarity, support, growth and belonging, plus an eNPS score. Anyone who scores 6 or below is asked what''s weighing on them and what would help this month, which is where the comments worth reading come from.', '["employee satisfaction","pulse survey","employee engagement","enps","monthly check-in","branching"]', 'HeartPulse', 'scale', 3, 11, '{"schemaVersion":9,"title":"Engagement pulse","description":"A short, repeatable check that follows up with the people who are struggling.","blocks":[{"id":"blk_engageme00","ref":"welcome","title":"Quick pulse check. Anonymous, and under two minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_engageme01","ref":"team","title":"Which team are you in?","description":"Only used to group results, never to identify you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_operations","label":"Operations","image_key":null},{"id":"opt_sales_and_marketing","label":"Sales and marketing","image_key":null},{"id":"opt_product_and_engineering","label":"Product and engineering","image_key":null},{"id":"opt_support","label":"Support","image_key":null},{"id":"opt_other","label":"Other","image_key":null}]},{"id":"blk_engageme02","ref":"workload","title":"My workload is manageable.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_engageme03","ref":"clarity","title":"I''m clear on what''s expected of me.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_engageme04","ref":"support","title":"I get the support I need from my manager.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_engageme05","ref":"growth","title":"I''m learning and growing here.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_engageme06","ref":"belonging","title":"I can be myself at work.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Strongly disagree","labelHigh":"Strongly agree"},{"id":"blk_engageme07","ref":"enps","title":"How likely are you to recommend us as a place to work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_engageme08","ref":"low_area","title":"Which of these is weighing on you most?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_too_much_work","label":"Too much work","image_key":null},{"id":"opt_unclear_priorities","label":"Unclear priorities","image_key":null},{"id":"opt_not_enough_support","label":"Not enough support","image_key":null},{"id":"opt_no_path_forward","label":"No path forward","image_key":null},{"id":"opt_something_about_the","label":"Something about the team","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":true},{"id":"blk_engageme09","ref":"low_detail","title":"What would help most, this month?","description":"Still anonymous. Answers are summarised, never quoted with a name.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_engageme10","ref":"win","title":"What went well for you this month?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_engageme11","ref":"anything_else","title":"Anything else on your mind?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_engageme01","ref":"end_thanks","title":"Thanks 💬","bodyMd":"Results are shared with the whole team, along with what we''ll do about them.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_engageme01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"enps"},"op":"lte","value":6}],"groups":[]},"from":"enps","target":"low_area","targetKind":"block","branch":"true"},{"id":"rl_engageme02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"enps"},"op":"gte","value":7}],"groups":[]},"from":"enps","target":"win","targetKind":"block","branch":"true"},{"id":"rl_engageme03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"low_detail","target":"anything_else","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
