VALUES ('tpl_managereffectivenesssurv', 'manager-effectiveness-survey', 'Manager effectiveness survey', 'Survey', 'Hear from a team how their manager really supports them, one behaviour at a time.', 'Rates the specific things a manager does, such as setting priorities, giving feedback and making timely decisions, instead of asking for one vague grade. People who score their manager low are asked for the single change that would help most and can request a private follow-up, while those who score high are asked what the manager should keep doing.', '["evaluation","manager effectiveness survey","upward feedback","manager evaluation","leadership feedback","employee survey"]', 'UserCheck', 'advanced', 4, 12, '{"schemaVersion":9,"title":"Manager effectiveness","description":"Hear from a team how their manager really supports them, one behaviour at a time.","blocks":[{"id":"blk_managere00","ref":"welcome","title":"This is a few minutes of honest feedback about your manager. Answer for how things usually are, not your best or worst week.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_managere01","ref":"manager_name","title":"Which manager is this feedback about?","description":"Only HR sees this. It is used to group answers by manager.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_managere02","ref":"tenure_with_manager","title":"How long have you reported to this manager?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_3","label":"Less than 3 months","image_key":null},{"id":"opt_3_to_12","label":"3 to 12 months","image_key":null},{"id":"opt_1_to_2","label":"1 to 2 years","image_key":null},{"id":"opt_more_than_2","label":"More than 2 years","image_key":null}],"allowOther":false},{"id":"blk_managere03","ref":"behaviours","title":"How much do you agree with each of these about your manager?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_makes_it","label":"Makes it clear what matters most right now"},{"id":"opt_row_gives_me","label":"Gives me feedback I can act on"},{"id":"opt_row_makes_decisions","label":"Makes decisions promptly when the team needs one"},{"id":"opt_row_is_available","label":"Is available when I''m stuck"},{"id":"opt_row_notices_and","label":"Notices and credits good work"},{"id":"opt_row_takes_an","label":"Takes an interest in where my career is going"},{"id":"opt_row_treats_everyone","label":"Treats everyone on the team fairly"}],"columns":[{"id":"opt_col_strongly_disagree","label":"Strongly disagree"},{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_neutral","label":"Neutral"},{"id":"opt_col_agree","label":"Agree"},{"id":"opt_col_strongly_agree","label":"Strongly agree"}],"multiplePerRow":false},{"id":"blk_managere04","ref":"one_on_ones","title":"How often do you get a one-to-one with them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_weekly","label":"Weekly","image_key":null},{"id":"opt_every_two_weeks","label":"Every two weeks","image_key":null},{"id":"opt_monthly","label":"Monthly","image_key":null},{"id":"opt_less_than_monthly","label":"Less than monthly","image_key":null},{"id":"opt_we_don_t","label":"We don''t have them","image_key":null}],"allowOther":false},{"id":"blk_managere05","ref":"psych_safety","title":"How comfortable are you raising a problem or a mistake with them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_managere06","ref":"overall","title":"Overall, how well does your manager help you do your best work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Not at all","labelHigh":"Extremely well"},{"id":"blk_managere07","ref":"keep_doing","title":"What is one thing they do that you''d want them to keep doing?","description":"A specific example is more useful than a general compliment.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_managere08","ref":"one_change","title":"What one change from your manager would make the biggest difference to your work?","description":"Describe the behaviour and what it would change for you.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_managere09","ref":"private_follow_up","title":"Would you like someone from HR to follow up with you privately?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, please","noLabel":"No, thanks"},{"id":"blk_managere10","ref":"follow_up_email","title":"What email should HR use to reach you?","description":"This is for HR only and is not passed to your manager.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_managere11","ref":"more_of","title":"Rank what you''d most like more of from your manager","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_clear_priorities","label":"Clear priorities"},{"id":"opt_item_regular_feedback","label":"Regular feedback"},{"id":"opt_item_recognition","label":"Recognition"},{"id":"opt_item_room_to","label":"Room to decide for myself"},{"id":"opt_item_help_with","label":"Help with career growth"},{"id":"opt_item_protection_from","label":"Protection from distractions"}]},{"id":"blk_managere12","ref":"anything_else","title":"Anything else your manager should hear?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_managere01","ref":"end_thanks","title":"Thanks, your manager will hear the themes","bodyMd":"HR reads every answer and shares themes with your manager, not individual replies.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_managere01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"keep_doing","target":"more_of","targetKind":"block"},{"id":"rl_managere02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"gte","value":6}],"groups":[]},"from":"overall","target":"keep_doing","targetKind":"block","branch":"true"},{"id":"rl_managere03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"lte","value":5}],"groups":[]},"from":"overall","target":"one_change","targetKind":"block","branch":"true"},{"id":"rl_managere04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"private_follow_up"},"op":"eq","value":false}],"groups":[]},"from":"private_follow_up","target":"more_of","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
