INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_preeventsurvey', 'pre-event-survey', 'Pre-event survey', 'Survey', 'Find out what registered attendees want and need before the doors open.', 'Sent after registration, it asks what people want to learn, which sessions they care about and how much they already know, so speakers can pitch their talks at the right level. Only people who say they have access needs are asked for the details, and first-timers get one extra question about what would help them settle in.', '["event","pre-event survey","attendee survey","conference planning","session interest","accessibility needs"]', 'CalendarCheck', 'contact', 4, 12, '{"schemaVersion":9,"title":"Pre-event survey","description":"Find out what registered attendees want and need before the doors open.","blocks":[{"id":"blk_preevent00","ref":"welcome","title":"You''re registered, thank you! A few quick questions now help us shape the day around the people actually coming.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_preevent01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_preevent02","ref":"attending_parts","title":"Which parts of the event are you planning to attend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_welcome_evening","label":"Welcome evening","image_key":null},{"id":"opt_day_1_talks","label":"Day 1 talks","image_key":null},{"id":"opt_day_2_workshops","label":"Day 2 workshops","image_key":null},{"id":"opt_closing_social","label":"Closing social","image_key":null}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_preevent03","ref":"hoping_for","title":"What are you hoping to get out of it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_learn_new_skills","label":"Learn new skills","image_key":null},{"id":"opt_meet_people_in","label":"Meet people in my field","image_key":null},{"id":"opt_find_partners_or","label":"Find partners or suppliers","image_key":null},{"id":"opt_hear_where_the","label":"Hear where the industry is heading","image_key":null},{"id":"opt_get_answers_to","label":"Get answers to a specific problem","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_preevent04","ref":"experience_level","title":"How familiar are you with the event''s main topic?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_new_to_it","label":"New to it","image_key":null},{"id":"opt_some_hands_on","label":"Some hands-on experience","image_key":null},{"id":"opt_i_work_with","label":"I work with it every day","image_key":null},{"id":"opt_i_could_teach","label":"I could teach it","image_key":null}],"allowOther":false},{"id":"blk_preevent05","ref":"session_interest","title":"Rank these session tracks by how much you want to attend them","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_keynotes","label":"Keynotes"},{"id":"opt_item_case_studies","label":"Case studies"},{"id":"opt_item_hands_on","label":"Hands-on workshops"},{"id":"opt_item_panel_discussions","label":"Panel discussions"},{"id":"opt_item_small_group","label":"Small-group roundtables"}]},{"id":"blk_preevent06","ref":"question_for_speakers","title":"Is there a question you''d love a speaker to answer?","description":"We pass these on so talks can cover what people are actually wondering about.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_preevent07","ref":"first_time","title":"Is this your first time at one of our events?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_preevent08","ref":"settle_in","title":"What would help you feel at home on the day?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_a_short_orientation","label":"A short orientation before it starts","image_key":null},{"id":"opt_an_introduction_to","label":"An introduction to a few other attendees","image_key":null},{"id":"opt_a_clear_schedule","label":"A clear schedule in advance","image_key":null},{"id":"opt_nothing_special_i","label":"Nothing special, I''ll find my way","image_key":null}],"minSelections":0,"maxSelections":4,"allowOther":false},{"id":"blk_preevent09","ref":"dietary","title":"Any dietary requirements we should plan for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_none","label":"None","image_key":null},{"id":"opt_vegetarian","label":"Vegetarian","image_key":null},{"id":"opt_vegan","label":"Vegan","image_key":null},{"id":"opt_gluten_free","label":"Gluten-free","image_key":null},{"id":"opt_halal","label":"Halal","image_key":null},{"id":"opt_nut_allergy","label":"Nut allergy","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":true},{"id":"blk_preevent10","ref":"access_needs","title":"Do you have any access needs we should arrange with the venue?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_preevent11","ref":"access_details","title":"Tell us what you need and we''ll set it up before you arrive","description":"For example step-free access, a hearing loop, reserved seating or a quiet room.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_preevent12","ref":"email","title":"Which email should we send joining details to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_preevent01","ref":"end_thanks","title":"See you there 🎟️","bodyMd":"Joining details and the full schedule will reach your inbox before the event.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_preevent01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"first_time"},"op":"eq","value":true}],"groups":[]},"from":"first_time","target":"settle_in","targetKind":"block","branch":"true"},{"id":"rl_preevent02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"first_time"},"op":"eq","value":false}],"groups":[]},"from":"first_time","target":"dietary","targetKind":"block","branch":"true"},{"id":"rl_preevent03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"access_needs"},"op":"eq","value":false}],"groups":[]},"from":"access_needs","target":"email","targetKind":"block","branch":"true"},{"id":"rl_preevent04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"settle_in","target":"access_needs","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowRe