VALUES ('tpl_eventevaluationsurvey', 'event-evaluation-survey', 'Event evaluation survey', 'Survey', 'Judge an event by whether it did its job for each group who came.', 'Starts by asking why each person came and whether the event delivered it, so the scores you read later have a reason attached. Sponsors and exhibitors are routed to questions about booth traffic and lead quality, and anyone whose goal wasn''t met is asked what got in the way before rating the program and organisation.', '["event","event evaluation survey","post-event survey","conference evaluation","sponsor feedback","event ROI"]', 'ClipboardCheck', 'contact', 4, 12, '{"schemaVersion":9,"title":"Event evaluation","description":"Judge an event by whether it did its job for each group who came.","blocks":[{"id":"blk_eventeva00","ref":"welcome","title":"Thanks for being part of the event. We''d like an honest look back to plan the next one well.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventeva01","ref":"role","title":"How were you involved?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_attendee","label":"Attendee","image_key":null},{"id":"opt_speaker","label":"Speaker","image_key":null},{"id":"opt_sponsor_or_exhibitor","label":"Sponsor or exhibitor","image_key":null},{"id":"opt_volunteer","label":"Volunteer","image_key":null}],"allowOther":false},{"id":"blk_eventeva02","ref":"booth_traffic","title":"How was the flow of visitors to your stand or sessions?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"number"},{"id":"blk_eventeva03","ref":"lead_quality","title":"How many of the people you met were the kind you came to meet?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_most_of_them","label":"Most of them","image_key":null},{"id":"opt_about_half","label":"About half","image_key":null},{"id":"opt_a_few","label":"A few","image_key":null},{"id":"opt_hardly_any","label":"Hardly any","image_key":null}],"allowOther":false},{"id":"blk_eventeva04","ref":"sponsor_again","title":"Would you sponsor or exhibit again?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Likely","noLabel":"Unlikely"},{"id":"blk_eventeva05","ref":"main_goal","title":"What was the main reason you took part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_to_learn_something","label":"To learn something specific","image_key":null},{"id":"opt_to_meet_people","label":"To meet people","image_key":null},{"id":"opt_to_find_customers","label":"To find customers or partners","image_key":null},{"id":"opt_to_represent_my","label":"To represent my organisation","image_key":null},{"id":"opt_it_was_part","label":"It was part of my job","image_key":null}],"allowOther":true},{"id":"blk_eventeva06","ref":"goal_met","title":"Did the event deliver on that?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_fully","label":"Yes, fully","image_key":null},{"id":"opt_partly","label":"Partly","image_key":null},{"id":"opt_not_really","label":"Not really","image_key":null}],"allowOther":false},{"id":"blk_eventeva07","ref":"what_got_in_the_way","title":"What got in the way?","description":"The more specific you are, the easier it is to fix for next time.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_eventeva08","ref":"event_parts","title":"How would you rate each part of the event?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_quality_of","label":"Quality of the sessions"},{"id":"opt_row_relevance_of","label":"Relevance of the topics"},{"id":"opt_row_schedule_and","label":"Schedule and pacing"},{"id":"opt_row_venue_or","label":"Venue or platform"},{"id":"opt_row_information_before","label":"Information before the event"},{"id":"opt_row_staff_and","label":"Staff and volunteers on the day"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_eventeva09","ref":"best_session","title":"Which session or moment was the most useful to you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_eventeva10","ref":"worth_it","title":"Was it worth the time and cost of attending?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not worth it","labelHigh":"Well worth it"},{"id":"blk_eventeva11","ref":"recommend","title":"How likely are you to recommend this event to a colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_eventeva12","ref":"one_change","title":"If you ran the next one, what would you change first?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_eventeva01","ref":"end_thanks","title":"Thank you, this goes straight into planning","bodyMd":"We''ll share what we''re changing when we announce the next event.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_eventeva01","action_kind":"g