INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_eventquestionnaire', 'event-questionnaire', 'Event questionnaire', 'Survey', 'Collect the purpose, audience and practical needs of an event before anything is booked.', 'Written for the person commissioning an event, whether that''s a client, a manager or a committee, so planning starts from their goals rather than a venue. It asks what success looks like before it asks about logistics. Online events skip straight past the location and venue questions, and hybrid events are asked what remote guests should be able to do before the venue questions.', '["event","event questionnaire","event planning questionnaire","event brief","client intake","event requirements"]', 'ClipboardList', 'contact', 5, 16, '{"schemaVersion":9,"title":"Event questionnaire","description":"Collect the purpose, audience and practical needs of an event before anything is booked.","blocks":[{"id":"blk_eventque00","ref":"welcome","title":"Let''s pin down what this event needs to be. Answer what you know; rough guesses are fine.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventque01","ref":"contact","title":"Who should we talk to about this event?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_eventque02","ref":"organisation","title":"Which organisation or team is the event for?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_eventque03","ref":"event_type","title":"What kind of event is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_conference","label":"Conference","image_key":null},{"id":"opt_workshop_or_training","label":"Workshop or training","image_key":null},{"id":"opt_product_launch","label":"Product launch","image_key":null},{"id":"opt_networking_event","label":"Networking event","image_key":null},{"id":"opt_team_offsite","label":"Team offsite","image_key":null},{"id":"opt_awards_or_gala","label":"Awards or gala","image_key":null},{"id":"opt_fundraiser","label":"Fundraiser","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_eventque04","ref":"purpose","title":"Why are you holding it, and what should be different afterwards?","description":"For example: 50 qualified leads, a team that knows the new strategy, or funds raised for a project.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_eventque05","ref":"audience","title":"Who is it for?","description":"Their roles, how well they know each other, and what would make them show up.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_eventque06","ref":"guest_count","title":"Roughly how many people do you expect?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"integerOnly":true},{"id":"blk_eventque07","ref":"format","title":"Will it be in person, online or both?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_person","label":"In person","image_key":null},{"id":"opt_online","label":"Online","image_key":null},{"id":"opt_hybrid","label":"Hybrid","image_key":null},{"id":"opt_not_decided_yet","label":"Not decided yet","image_key":null}],"allowOther":false},{"id":"blk_eventque08","ref":"remote_audience","title":"What should people joining remotely be able to do?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_watch_the_main","label":"Watch the main talks live","image_key":null},{"id":"opt_ask_questions_and","label":"Ask questions and vote in polls","image_key":null},{"id":"opt_join_breakout_sessions","label":"Join breakout sessions","image_key":null},{"id":"opt_watch_recordings_afterward","label":"Watch recordings afterwards","image_key":null},{"id":"opt_meet_the_people","label":"Meet the people in the room","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_eventque09","ref":"location","title":"Which city or area should it be in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_eventque10","ref":"venue_needs","title":"What does the venue need to have?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_main_room_for","label":"Main room for everyone","image_key":null},{"id":"opt_breakout_rooms","label":"Breakout rooms","image_key":null},{"id":"opt_stage_and_av","label":"Stage and AV","image_key":null},{"id":"opt_streaming_and_recording","label":"Streaming and recording setup","image_key":null},{"id":"opt_space_for_exhibitors","label":"Space for exhibitors","image_key":null},{"id":"opt_step_free_access","label":"Step-free access","image_key":null},{"id":"opt_overnight_accommodation_ne","label":"Overnight accommodation nearby","image_key":null}],"minSelections":0,"maxSelections":8,"allowOther":true},{"id":"blk_eventque11","ref":"online_setup","title":"What should the online experience include?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_live_talks","label":"Live talks","image_key":null},{"id":"opt_breakout_rooms","label":"Breakout rooms","image_key":null},{"id":"opt_live_q_a","label":"Live Q&A and polls","image_key":null},{"id":"opt_recordings_afterwar