ibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_it_s","label":"Yes, it''s approved","image_key":null},{"id":"opt_roughly_still_being","label":"Roughly, still being confirmed","image_key":null},{"id":"opt_no_we_need","label":"No, we need help working it out","image_key":null}],"allowOther":false},{"id":"blk_eventque16","ref":"anything_else","title":"Anything else we should know, such as past events, must-haves or things to avoid?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_eventque01","ref":"end_thanks","title":"Thanks, that gives us a solid start","bodyMd":"We''ll read this through and come back with questions and a first outline.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_eventque01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"venue_needs","target":"preferred_date","targetKind":"block"},{"id":"rl_eventque02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"format"},"op":"eq","value":"opt_in_person"}],"groups":[]},"from":"format","target":"location","targetKind":"block","branch":"true"},{"id":"rl_eventque03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"format"},"op":"eq","value":"opt_hybrid"}],"groups":[]},"from":"format","target":"remote_audience","targetKind":"block","branch":"true"},{"id":"rl_eventque04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"format"},"op":"eq","value":"opt_not_decided_yet"}],"groups":[]},"from":"format","target":"location","targetKind":"block","branch":"true"},{"id":"rl_eventque05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"format"},"op":"eq","value":"opt_online"}],"groups":[]}