INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_eventplanningsurvey', 'event-planning-survey', 'Event planning survey', 'Survey', 'Ask the people you want in the room what would get them there, before you book anything.', 'Goes to the audience you hope to attract, not the people already signed up, and asks about topics, format, day, length and what they weigh up when deciding. Anyone who says they''re unlikely to come is asked what''s stopping them, and people who want first word on dates can leave an email.', '["event","event planning survey","event interest survey","audience research","event format","attendee preferences"]', 'CalendarDays', 'contact', 3, 11, '{"schemaVersion":9,"title":"Event planning survey","description":"Ask the people you want in the room what would get them there, before you book anything.","blocks":[{"id":"blk_eventpla00","ref":"welcome","title":"We''re planning an event and want to build it around what you''d actually come to. This takes about two minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventpla01","ref":"describes_you","title":"Which best describes you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_individual_contributor","label":"Individual contributor","image_key":null},{"id":"opt_team_lead_or","label":"Team lead or manager","image_key":null},{"id":"opt_director_or_executive","label":"Director or executive","image_key":null},{"id":"opt_founder_or_self","label":"Founder or self-employed","image_key":null},{"id":"opt_student","label":"Student","image_key":null}],"allowOther":true},{"id":"blk_eventpla02","ref":"topics","title":"Which topics would you most want covered?","description":"Pick up to three.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_practical_how_to","label":"Practical how-to skills","image_key":null},{"id":"opt_industry_trends","label":"Industry trends","image_key":null},{"id":"opt_real_case_studies","label":"Real case studies","image_key":null},{"id":"opt_tools_and_technology","label":"Tools and technology","image_key":null},{"id":"opt_career_growth","label":"Career growth","image_key":null},{"id":"opt_leadership","label":"Leadership","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_eventpla03","ref":"format","title":"Which format would you be most likely to attend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_person","label":"In person","image_key":null},{"id":"opt_online","label":"Online","image_key":null},{"id":"opt_hybrid_with_the","label":"Hybrid, with the choice of either","image_key":null},{"id":"opt_no_preference","label":"No preference","image_key":null}],"allowOther":false},{"id":"blk_eventpla04","ref":"length","title":"How long should it be?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_couple_of","label":"A couple of hours","image_key":null},{"id":"opt_half_a_day","label":"Half a day","image_key":null},{"id":"opt_a_full_day","label":"A full day","image_key":null},{"id":"opt_two_days_or","label":"Two days or more","image_key":null}],"allowOther":false},{"id":"blk_eventpla05","ref":"timing","title":"When could you realistically make it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_weekday_daytime","label":"Weekday daytime","image_key":null},{"id":"opt_weekday_evening","label":"Weekday evening","image_key":null},{"id":"opt_weekend","label":"Weekend","image_key":null},{"id":"opt_depends_on_the","label":"Depends on the date","image_key":null}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_eventpla06","ref":"decision_factors","title":"Rank what matters most when you decide whether to go","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_the_topics","label":"The topics"},{"id":"opt_item_the_speakers","label":"The speakers"},{"id":"opt_item_date_and","label":"Date and time"},{"id":"opt_item_location_or","label":"Location or travel"},{"id":"opt_item_cost","label":"Cost"},{"id":"opt_item_who_else","label":"Who else is going"}]},{"id":"blk_eventpla07","ref":"likelihood","title":"If we ran an event along these lines, how likely would you be to come?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Very unlikely","labelHigh":"Very likely"},{"id":"blk_eventpla08","ref":"what_stops_you","title":"What would stop you from coming?","description":"Cost, travel, timing, the topic itself: whatever it is, it helps to know.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_eventpla09","ref":"must_have","title":"What would make this event a must-attend for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_eventpla10","ref":"keep_posted","title":"Want to hear first when the date is set?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, tell me","noLabel":"No, thanks"},{"id":"blk_eventpla11","ref":"email","title":"Where should we send the news?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_eventpla01","ref":"end_thanks","title":"Thanks for helping us plan it","bodyMd":"Your answers will shape the topics, format and timing we choose.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_eventpla01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"likelihood"},"op":"lte","value":2}],"groups":[]},"from":"likelihood","target":"what_stops_you","targetKind":"block","branch":"true"},{"id":"rl_eventpla02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"likelihood"},"op":"gte","value":3}],"groups":[]},"from":"likelihood","target":"must_have","targetKind":"block","branch":"true"},{"id":"rl_eventpla03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"keep_posted"},"op":"eq","value":false}],"groups":[]},"from":"keep_posted","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_eventpla04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"what_stops_you","target":"keep_posted","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
