VALUES ('tpl_eventfeedback', 'event-feedback', 'Event feedback survey', 'Survey', 'Rate the parts of an event separately, and dig in where the score was low.', 'A single "how was it?" averages a great speaker and a cold room into a middling score. The grid shows which one to fix, and anyone who rates the day three stars or fewer is asked what went wrong and whether they want someone to follow up, while people who loved it are asked for a highlight and whether they''d speak at the next one.', '["event","event feedback survey","post-event survey","attendee feedback","event rating","conference feedback"]', 'MessagesSquare', 'contact', 3, 11, '{"schemaVersion":9,"title":"Post-event feedback","description":"Rate the parts of an event separately, and dig in where the score was low.","blocks":[{"id":"blk_eventfee00","ref":"welcome","title":"Thanks for coming! A few quick questions on how it went.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_eventfee01","ref":"aspects","title":"How would you rate each part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_speakers","label":"Speakers"},{"id":"opt_row_venue","label":"Venue"},{"id":"opt_row_food_and","label":"Food and drink"},{"id":"opt_row_networking","label":"Networking"},{"id":"opt_row_organisation","label":"Organisation"},{"id":"opt_row_value_for","label":"Value for money"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_eventfee02","ref":"overall","title":"And the event as a whole?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_eventfee03","ref":"what_went_wrong","title":"What let it down?","description":"Specifics help most: a session, a moment, a practical problem.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_eventfee04","ref":"follow_up","title":"Would you like someone from the team to get in touch about it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, please","noLabel":"No need"},{"id":"blk_eventfee05","ref":"follow_up_email","title":"Which email should we use to reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_eventfee06","ref":"highlight","title":"What was the highlight for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_eventfee07","ref":"would_speak","title":"Would you consider speaking at the next one?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"I''d be up for it","noLabel":"Not for me"},{"id":"blk_eventfee08","ref":"improve","title":"What should we do differently next time?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_eventfee09","ref":"topics_next","title":"What would you want more of next time?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_more_technical_depth","label":"More technical depth","image_key":null},{"id":"opt_more_case_studies","label":"More case studies","image_key":null},{"id":"opt_more_hands_on","label":"More hands-on workshops","image_key":null},{"id":"opt_more_time_to","label":"More time to talk to people","image_key":null},{"id":"opt_shorter_sessions","label":"Shorter sessions","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_eventfee10","ref":"come_again","title":"Would you come to another one?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_eventfee11","ref":"email","title":"Leave your email if you''d like to hear when the next one is announced","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_eventfee01","ref":"end_thanks","title":"Thank you 🙌","bodyMd":"Every answer is read, and it shapes what we do at the next one.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_eventfee01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"follow_up_email","target":"improve","targetKind":"block"},{"id":"rl_eventfee02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"lte","value":3}],"groups":[]},"from":"overall","target":"what_went_wrong","targetKind":"block","branch":"true"},{"id":"rl_eventfee03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"gte","value":4}],"groups":[]},"from":"overall","target":"highlight","targetKind":"block","branch":"true"},{"id":"rl_eventfee04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"follow_up"},"op":"eq","value":false}],"groups":[]},"from":"follow_up","target":"improve","targetKind":"block","branch":"true"},{"id":"rl_eventfee05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"come_again"},"op":"eq","value":false}],"groups":[]},"from":"come_again","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter