INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_professionaldevelopmentf', 'professional-development-feedback-survey', 'Professional development feedback survey', 'Survey', 'Check whether development support is useful, and what people need to put new skills to work.', 'Built for an annual or half-year review of your learning programme. The usefulness score decides the follow-up: people who got value are asked what helped most, and people who didn''t are asked what got in the way. Anyone who took part in nothing skips the usefulness questions and goes straight to what held them back. It ends by asking who wants a conversation about their own development plan, and only those people are asked for an email.', '["feedback","professional development survey","learning and development","training needs","employee growth","L&D feedback"]', 'TrendingUp', 'scale', 4, 12, '{"schemaVersion":9,"title":"Professional development feedback","description":"Check whether development support is useful, and what people need to put new skills to work.","blocks":[{"id":"blk_professi00","ref":"welcome","title":"We want to spend next year''s development time and budget where it helps you most. Five minutes?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_professi01","ref":"role_level","title":"Which best describes your role?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_individual_contributor","label":"Individual contributor","image_key":null},{"id":"opt_team_lead","label":"Team lead","image_key":null},{"id":"opt_manager_of_managers","label":"Manager of managers","image_key":null},{"id":"opt_senior_leader","label":"Senior leader","image_key":null}],"allowOther":false},{"id":"blk_professi02","ref":"activities","title":"Which of these did you take part in over the last year?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_workshops_or_in","label":"Workshops or in-house courses","image_key":null},{"id":"opt_external_courses_or","label":"External courses or certifications","image_key":null},{"id":"opt_conferences_or_events","label":"Conferences or events","image_key":null},{"id":"opt_mentoring_or_coaching","label":"Mentoring or coaching","image_key":null},{"id":"opt_online_learning","label":"Online learning","image_key":null},{"id":"opt_stretch_projects_or","label":"Stretch projects or job shadowing","image_key":null},{"id":"opt_none_of_these","label":"None of these","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_professi03","ref":"usefulness","title":"Overall, how useful was the development support you had this year?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_professi04","ref":"most_valuable","title":"Which one thing helped you most, and what did it change in your work?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_professi05","ref":"not_useful","title":"What got in the way of it being useful to you?","description":"Timing, topic, format, anything. Specifics help us fix it.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_professi06","ref":"application","title":"How much do you agree with each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_what_i","label":"What I learned matched what my role needs"},{"id":"opt_row_i_had","label":"I had time to practise what I learned"},{"id":"opt_row_my_manager","label":"My manager helped me use it in my work"},{"id":"opt_row_i_know","label":"I know where to find development opportunities"}],"columns":[{"id":"opt_col_strongly_disagree","label":"Strongly disagree"},{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_agree","label":"Agree"},{"id":"opt_col_strongly_agree","label":"Strongly agree"}],"multiplePerRow":false},{"id":"blk_professi07","ref":"barriers","title":"What makes it harder to develop your skills here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_not_enough_time","label":"Not enough time","image_key":null},{"id":"opt_limited_budget","label":"Limited budget","image_key":null},{"id":"opt_not_sure_what","label":"Not sure what''s on offer","image_key":null},{"id":"opt_options_don_t","label":"Options don''t fit my role","image_key":null},{"id":"opt_little_support_from","label":"Little support from my manager","image_key":null},{"id":"opt_nothing_major","label":"Nothing major","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_professi08","ref":"support_ranking","title":"Rank the support you''d most like more of next year.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_formal_training","label":"Formal training courses"},{"id":"opt_item_mentoring_or","label":"Mentoring or coaching"},{"id":"opt_item_stretch_projects","label":"Stretch projects"},{"id":"opt_item_conference_or","label":"Conference or event budget"},{"id":"opt_item_protected_learning","label":"Protected learning time each month"}]},{"id":"blk_professi09","ref":"skill_goal","title":"Which skill do you most want to build in the next twelve months?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_professi10","ref":"apply_help","title":"What would help you put new skills to use in your day-to-day work?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_professi11","ref":"plan_chat","title":"Would you like someone from the people team to talk through a development plan with you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_professi12","ref":"work_email","title":"What''s your work email, so we can set that up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_professi01","ref":"end_thanks","title":"Thank you for the honest feedback","bodyMd":"We''ll share what we heard, and what we''re changing, once everyone has answered.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_professi02","ref":"end_plan","title":"Thanks, we''ll be in touch 📅","bodyMd":"Someone from the people team will email you within two weeks to find a time.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_professi01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"most_valuable","target":"application","targetKind":"block"},{"id":"rl_professi02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"work_email","target":"end_plan","targetKind":"ending"},{"id":"rl_professi03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"activities"},"op":"includes","value":"opt_none_of_these"}],"groups":[]},"from":"activities","target":"barriers","targetKind":"block","branch":"true"},{"id":"rl_professi04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"usefulness"},"op":"gte","value":3}],"groups":[]},"from":"usefulness","target":"most_valuable","targetKind":"block","branch":"true"},{"id":"rl_professi05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"usefulness"},"op":"lte","value":2}],"groups":[]},"from":"usefulness","target":"not_useful","targetKind":"block","branch":"true"},{"id":"rl_professi06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"plan_chat"},"op":"eq","value":true}],"groups":[]},"from":"plan_chat","target":"work_email","targetKind":"block","branch":"true"},{"id":"rl_professi07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"plan_chat"},"op":"eq","value":false}],"groups":[]},"from":"plan_chat","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#221d44","surface":"#2d2757","text":"#f5f3ff","accent":"#ff8a4c","accentText":"#1c1917","botBubble":"#332c5e","userBubble":"#ff8a4c","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
