VALUES ('tpl_mobileappsurvey', 'mobile-app-survey', 'Mobile app survey', 'Survey', 'Learn how people use your app, where it frustrates them and what would make it more useful.', 'Starts with the one job people open the app for, then asks how easy that job is. Anyone who struggles is asked where they get stuck, and anyone who reports crashes or slowness describes the last time it happened, which is what your developers need. Users who want to test new features leave an email and get their own ending.', '["feedback","mobile app survey","app feedback","in-app survey","user research","beta testers"]', 'Smartphone', 'scale', 4, 12, '{"schemaVersion":9,"title":"Mobile app survey","description":"Learn how people use your app, where it frustrates them and what would make it more useful.","blocks":[{"id":"blk_mobileap00","ref":"welcome","title":"Hi! A few quick questions about the app. Your answers go straight to the people who build it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_mobileap01","ref":"platform","title":"Which phone do you use the app on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_iphone","label":"iPhone","image_key":null},{"id":"opt_android","label":"Android","image_key":null},{"id":"opt_both","label":"Both","image_key":null}],"allowOther":false},{"id":"blk_mobileap02","ref":"frequency","title":"How often do you open the app?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_a_few_times","label":"A few times a week","image_key":null},{"id":"opt_about_once_a","label":"About once a week","image_key":null},{"id":"opt_less_often_than","label":"Less often than that","image_key":null}],"allowOther":false},{"id":"blk_mobileap03","ref":"main_task","title":"What''s the main thing you open the app to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_mobileap04","ref":"task_ease","title":"How easy is it to get that done?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Very hard","labelHigh":"Very easy"},{"id":"blk_mobileap05","ref":"stuck_point","title":"Where do you get stuck or slowed down?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_mobileap06","ref":"problems","title":"Have you run into any of these in the last month?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_crashes_or_freezes","label":"Crashes or freezes","image_key":null},{"id":"opt_slow_loading","label":"Slow loading","image_key":null},{"id":"opt_trouble_logging_in","label":"Trouble logging in","image_key":null},{"id":"opt_notifications_not_arriving","label":"Notifications not arriving","image_key":null},{"id":"opt_heavy_battery_or","label":"Heavy battery or data use","image_key":null},{"id":"opt_something_not_saving","label":"Something not saving","image_key":null},{"id":"opt_none_of_these","label":"None of these","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_mobileap07","ref":"problem_detail","title":"Tell us about the last time that happened. What were you doing just before?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_mobileap08","ref":"aspects","title":"How would you rate each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_finding_your","label":"Finding your way around"},{"id":"opt_row_speed","label":"Speed"},{"id":"opt_row_how_it","label":"How it looks"},{"id":"opt_row_notifications","label":"Notifications"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_great","label":"Great"}],"multiplePerRow":false},{"id":"blk_mobileap09","ref":"wish","title":"What one change would make the app more useful to you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_mobileap10","ref":"recommend","title":"How likely are you to recommend the app to a friend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_mobileap11","ref":"beta","title":"Would you like to try new features before everyone else?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_mobileap12","ref":"beta_email","title":"Great. Which email should we send beta invites to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_mobileap01","ref":"end_thanks","title":"Thanks for the feedback","bodyMd":"Every answer is read by the product team, and the problems you reported go into our bug queue.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_mobileap02","ref":"end_beta","title":"You''re on the beta list 🚀","bodyMd":"We''ll email you when there''s something new to try. Thanks for helping us shape it.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_mobileap01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"beta_email","target":"end_beta","targetKind":"ending"},{"id":"rl_mobileap02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"task_ease"},"op":"gte","value":4}],"groups":[]},"from":"task_ease","target":"problems","targetKind":"block","branch":"true"},{"id":"rl_mobileap03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"problems"},"op":"includes","value":"opt_none_of_these"}],"groups":[]},"from":"problems","target":"aspects","targetKind":"block","branch":"true"},{"id":"rl_mobileap04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"beta"},"op":"eq","value":false}],"groups":[]},"from":"beta","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_mobileap05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"beta"},"op":"eq","value":true}],"groups":[]},"from":"beta","target":"beta_email","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#f26b1d","surface":"#fff7f0","text":"#1c1917","accent":"#1c1917","accentText":"#ffffff","botBubble":"#fff7f0","userBubble":"#1c1917","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundPatternColor":"#1c1917","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
