INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_coursefeedbacksurvey', 'course-feedback-survey', 'Course feedback survey', 'Survey', 'Hear how students found the content, teaching and workload, and what would help them learn.', 'Covers the things you can actually change before the next run: clarity, pace, materials, assessment and workload in hours rather than adjectives. Students who rate the course low are asked what made it hard, students who rate it well are asked what helped, and everyone says what support would have made the material easier to understand.', '["feedback","course feedback survey","student feedback","course evaluation","end of course survey","teaching feedback"]', 'BookOpen', 'scale', 3, 11, '{"schemaVersion":9,"title":"Course feedback","description":"Hear how students found the content, teaching and workload, and what would help them learn.","blocks":[{"id":"blk_coursefe00","ref":"welcome","title":"Thanks for taking the course. Your feedback shapes how it runs next time, and it takes about four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_coursefe01","ref":"course","title":"Which course are you giving feedback on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_coursefe02","ref":"teaching","title":"How much do you agree with each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_explanations_were","label":"Explanations were clear"},{"id":"opt_row_the_pace","label":"The pace was about right"},{"id":"opt_row_the_materials","label":"The materials helped me learn"},{"id":"opt_row_assessments_matched","label":"Assessments matched what was taught"},{"id":"opt_row_i_could","label":"I could get help when I needed it"}],"columns":[{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_somewhat_disagree","label":"Somewhat disagree"},{"id":"opt_col_somewhat_agree","label":"Somewhat agree"},{"id":"opt_col_agree","label":"Agree"}],"multiplePerRow":false},{"id":"blk_coursefe03","ref":"workload","title":"How was the workload compared with your other courses?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_much_lighter","label":"Much lighter","image_key":null},{"id":"opt_a_bit_lighter","label":"A bit lighter","image_key":null},{"id":"opt_about_the_same","label":"About the same","image_key":null},{"id":"opt_a_bit_heavier","label":"A bit heavier","image_key":null},{"id":"opt_much_heavier","label":"Much heavier","image_key":null}],"allowOther":false},{"id":"blk_coursefe04","ref":"hours","title":"Roughly how many hours a week did you spend on it outside class?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":80,"integerOnly":false},{"id":"blk_coursefe05","ref":"overall","title":"Overall, how would you rate the course?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_coursefe06","ref":"best_part","title":"What helped you learn the most?","description":"A lecture, an exercise, a resource, a way it was taught.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_coursefe07","ref":"struggle","title":"What made it hard to get value from the course?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_coursefe08","ref":"confidence","title":"How confident are you that you could use what you learned?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Very confident"},{"id":"blk_coursefe09","ref":"support","title":"What would have helped you understand the material better?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_more_worked_examples","label":"More worked examples","image_key":null},{"id":"opt_recordings_of_sessions","label":"Recordings of sessions","image_key":null},{"id":"opt_more_office_hours","label":"More office hours","image_key":null},{"id":"opt_practice_questions_with","label":"Practice questions with answers","image_key":null},{"id":"opt_smaller_group_sessions","label":"Smaller group sessions","image_key":null},{"id":"opt_clearer_assignment_briefs","label":"Clearer assignment briefs","image_key":null},{"id":"opt_nothing_it_worked","label":"Nothing, it worked for me","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_coursefe10","ref":"one_change","title":"If you could change one thing about the course, what would it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_coursefe11","ref":"recommend","title":"Would you recommend this course to another student?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_maybe","label":"Maybe","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false}],"endings":[{"id":"end_coursefe01","ref":"end_thanks","title":"Thank you 🎓","bodyMd":"Your answers go to the course team once grades are final, so nothing you said here can affect your marks.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_coursefe01","action_kind":"goto","when":{"op":"and","condition