VALUES ('tpl_sponsorshipsatisfactions', 'sponsorship-satisfaction-survey', 'Sponsorship satisfaction survey', 'Survey', 'Review the value sponsors received, and find out who is ready to renew.', 'Asks sponsors to score each benefit you promised, from logo placement to attendee data, so you see what was delivered rather than a vague satisfaction score. Sponsors who got what they came for describe the highlight, the rest explain what fell short, and anyone ready to sponsor again lands on an ending that tells them you''ll reach out first.', '["feedback","sponsorship survey","sponsor feedback","event sponsor","sponsor renewal","partnership feedback"]', 'Handshake', 'scale', 4, 12, '{"schemaVersion":9,"title":"Sponsorship satisfaction","description":"Review the value sponsors received, and find out who is ready to renew.","blocks":[{"id":"blk_sponsors00","ref":"welcome","title":"Thank you for sponsoring. We''d like to know what worked for you and what we should do better next time.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_sponsors01","ref":"company","title":"Which company are you answering for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_sponsors02","ref":"tier","title":"Which sponsorship level did you have?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_headline_or_title","label":"Headline or title sponsor","image_key":null},{"id":"opt_main_tier","label":"Main tier","image_key":null},{"id":"opt_supporting_tier","label":"Supporting tier","image_key":null},{"id":"opt_in_kind_or","label":"In-kind or media partner","image_key":null}],"allowOther":false},{"id":"blk_sponsors03","ref":"goals","title":"What were you hoping to get out of it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_brand_awareness","label":"Brand awareness","image_key":null},{"id":"opt_leads_for_sales","label":"Leads for sales","image_key":null},{"id":"opt_hiring","label":"Hiring","image_key":null},{"id":"opt_product_demos_or","label":"Product demos or launches","image_key":null},{"id":"opt_supporting_the_community","label":"Supporting the community","image_key":null},{"id":"opt_meeting_partners","label":"Meeting partners","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_sponsors04","ref":"delivery","title":"How did we deliver on each part of your package?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_logo_and","label":"Logo and brand placement"},{"id":"opt_row_booth_or","label":"Booth or on-site presence"},{"id":"opt_row_speaking_or","label":"Speaking or stage time"},{"id":"opt_row_mentions_in","label":"Mentions in emails and social posts"},{"id":"opt_row_attendee_or","label":"Attendee or lead information"}],"columns":[{"id":"opt_col_not_included","label":"Not included"},{"id":"opt_col_below_what","label":"Below what was promised"},{"id":"opt_col_as_promised","label":"As promised"},{"id":"opt_col_better_than","label":"Better than promised"}],"multiplePerRow":false},{"id":"blk_sponsors05","ref":"audience_fit","title":"How well did the audience match the people you wanted to reach?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Poor match","labelHigh":"Spot on"},{"id":"blk_sponsors06","ref":"communication","title":"How was communication with our team before and during the event?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_sponsors07","ref":"goals_met","title":"Did you get what you came for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_partly","label":"Partly","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_sponsors08","ref":"highlight","title":"What was the most valuable part for your team?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_sponsors09","ref":"shortfall","title":"What fell short of what you expected?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_sponsors10","ref":"improve","title":"What would make a future partnership more valuable to you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_sponsors11","ref":"renew","title":"Would you sponsor again next time?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_very_likely","label":"Yes, very likely","image_key":null},{"id":"opt_maybe_depending_on","label":"Maybe, depending on changes","image_key":null},{"id":"opt_unlikely","label":"Unlikely","image_key":null}],"allowOther":false},{"id":"blk_sponsors12","ref":"renew_blocker","title":"What would need to change for it to be an easy yes?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_sponsors01","ref":"end_thanks","title":"Thank you for the candid feedback","bodyMd":"Our partnerships lead will read this and follow up with you personally.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]