VALUES ('tpl_volunteerfeedbacksurvey', 'volunteer-feedback-survey', 'Volunteer feedback survey', 'Survey', 'Find out how volunteers experienced the day and what would make them come back.', 'Checks the basics that decide whether a volunteer returns: did they know their role, have what they needed, know who to ask and feel their time was valued. Someone who had a rough day is asked what went wrong and whether the coordinator can get in touch, and only people who say yes leave their details, so everyone else stays anonymous. Everyone says what would make it easier to help again.', '["feedback","volunteer feedback survey","volunteer survey","nonprofit","volunteer retention","event volunteers"]', 'HandHeart', 'scale', 4, 13, '{"schemaVersion":9,"title":"Volunteer feedback","description":"Find out how volunteers experienced the day and what would make them come back.","blocks":[{"id":"blk_voluntee00","ref":"welcome","title":"Thank you for giving your time. Could you tell us how it went? It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_voluntee01","ref":"activity","title":"Which activity or event did you volunteer at?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_voluntee02","ref":"first_time","title":"Was this your first time volunteering with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_voluntee03","ref":"preparation","title":"Before and during your shift, was this true for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_i_knew","label":"I knew what my role involved before I arrived"},{"id":"opt_row_the_briefing","label":"The briefing prepared me for the day"},{"id":"opt_row_i_knew_2","label":"I knew who to ask for help"},{"id":"opt_row_i_had","label":"I had the equipment or supplies I needed"}],"columns":[{"id":"opt_col_no","label":"No"},{"id":"opt_col_partly","label":"Partly"},{"id":"opt_col_yes","label":"Yes"}],"multiplePerRow":false},{"id":"blk_voluntee04","ref":"shift_length","title":"How did the length of your shift feel?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_short","label":"Too short","image_key":null},{"id":"opt_about_right","label":"About right","image_key":null},{"id":"opt_too_long","label":"Too long","image_key":null}],"allowOther":false},{"id":"blk_voluntee05","ref":"valued","title":"How valued did you feel as a volunteer?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Very valued"},{"id":"blk_voluntee06","ref":"overall","title":"Overall, how was the experience?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"heart"},{"id":"blk_voluntee07","ref":"highlight","title":"What was the best part?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_voluntee08","ref":"what_wrong","title":"Sorry it wasn''t a good day. What went wrong?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_voluntee09","ref":"coordinator_call","title":"Would you like our volunteer coordinator to get in touch about it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_voluntee10","ref":"coordinator_contact","title":"Who should the coordinator contact, and how?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","email","phone"]},{"id":"blk_voluntee11","ref":"again","title":"Would you volunteer with us again?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_definitely","label":"Yes, definitely","image_key":null},{"id":"opt_maybe","label":"Maybe","image_key":null},{"id":"opt_probably_not","label":"Probably not","image_key":null}],"allowOther":false},{"id":"blk_voluntee12","ref":"easier","title":"What would make it easier to volunteer again?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_more_notice_of","label":"More notice of dates","image_key":null},{"id":"opt_shorter_shifts","label":"Shorter shifts","image_key":null},{"id":"opt_flexible_or_remote","label":"Flexible or remote roles","image_key":null},{"id":"opt_a_better_briefing","label":"A better briefing","image_key":null},{"id":"opt_volunteering_with_a","label":"Volunteering with a friend","image_key":null},{"id":"opt_help_with_travel","label":"Help with travel costs","image_key":null},{"id":"opt_nothing_it_s","label":"Nothing, it''s easy already","image_key":null}],"minSelections":0,"maxSelections":7,"allowOther":false},{"id":"blk_voluntee13","ref":"suggestions","title":"Anything else we should know or change?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_voluntee01","ref":"end_thanks","title":"Thank you for all you did 💛","bodyMd":"We read every response, and we''ll use yours to make the next shift better for everyone.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_voluntee01","action_kind":"goto","when":{"op":