VALUES ('tpl_brandawarenesssurvey', 'brand-awareness-survey', 'Brand awareness survey', 'Survey', 'Find out who remembers your brand unprompted, who recognises it, and where they came across it.', 'Asks the unprompted question first, before your brand name appears anywhere, so recall is real. Only people who recognise the brand are asked where they saw it, whether they''ve bought it and how it comes across, while everyone else skips ahead to what drives their choices. Written for a coffee brand as an example, so swap in your own category and names.', '["feedback","brand awareness survey","brand recall","brand recognition","market research","marketing survey"]', 'Megaphone', 'scale', 3, 10, '{"schemaVersion":9,"title":"Brand awareness survey","description":"Find out who remembers your brand unprompted, who recognises it, and where they came across it.","blocks":[{"id":"blk_brandawa00","ref":"welcome","title":"Hi! We''re asking people about the brands they buy. There are no right answers, and it takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_brandawa01","ref":"buy_frequency","title":"How often do you buy coffee to make at home?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_week_or","label":"Every week or more","image_key":null},{"id":"opt_about_once_a","label":"About once a month","image_key":null},{"id":"opt_a_few_times","label":"A few times a year","image_key":null},{"id":"opt_never","label":"Never","image_key":null}],"allowOther":false},{"id":"blk_brandawa02","ref":"unaided","title":"When you think of coffee to make at home, which brands come to mind? List as many as you like.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_brandawa03","ref":"aided","title":"Which of these brands have you heard of?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_nescaf","label":"Nescafé","image_key":null},{"id":"opt_lavazza","label":"Lavazza","image_key":null},{"id":"opt_brightside_coffee","label":"Brightside Coffee","image_key":null},{"id":"opt_starbucks","label":"Starbucks","image_key":null},{"id":"opt_illy","label":"Illy","image_key":null},{"id":"opt_none_of_these","label":"None of these","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_brandawa04","ref":"where_seen","title":"Where have you come across Brightside Coffee?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_on_a_supermarket","label":"On a supermarket shelf","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_an_online_ad","label":"An online ad","image_key":null},{"id":"opt_a_friend_or","label":"A friend or family member","image_key":null},{"id":"opt_in_a_caf","label":"In a café","image_key":null},{"id":"opt_news_or_a","label":"News or a review","image_key":null},{"id":"opt_i_can_t","label":"I can''t remember","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_brandawa05","ref":"bought","title":"Have you ever bought it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_regularly","label":"Yes, regularly","image_key":null},{"id":"opt_once_or_twice","label":"Once or twice","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_brandawa06","ref":"impression","title":"What''s your overall impression of Brightside Coffee?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Very negative","labelHigh":"Very positive"},{"id":"blk_brandawa07","ref":"three_words","title":"Which three words would you use to describe it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_brandawa08","ref":"choice_factors","title":"Rank what matters most when you choose a coffee.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_taste","label":"Taste"},{"id":"opt_item_price","label":"Price"},{"id":"opt_item_ethical_sourcing","label":"Ethical sourcing"},{"id":"opt_item_a_brand","label":"A brand I trust"},{"id":"opt_item_easy_to","label":"Easy to find in shops"}]},{"id":"blk_brandawa09","ref":"discovery","title":"Where do you usually find out about new food and drink brands?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_in_the_shop","label":"In the shop","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_friends_and_family","label":"Friends and family","image_key":null},{"id":"opt_online_ads","label":"Online ads","image_key":null},{"id":"opt_food_blogs_or","label":"Food blogs or reviews","image_key":null},{"id":"opt_tv_or_radio","label":"TV or radio","image_key":null},{"id":"opt_newsletters","label":"Newsletters","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_brandawa10","ref":"age_band","title":"Which age group are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_under_18","label":"Under 18","image_key":null},{"id":"opt_18_24","label":"18–24","image_key":null},{"id":"opt_25_34","label":"25–34","image_key":null},{"id":"opt_35_44","label":"35–44","image_key":null},{"id":"opt_45_54","label":"45–54","image_key":null},{"id":"opt_55_64","label":"55–64","image_key":null},{"id":"opt_65_or_over","label":"65 or over","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}]}],"endings":[{"id":"end_brandawa01","ref":"end_thanks","title":"Thank you ☕","bodyMd":"That''s everything. Your answers help us understand how people find and choose coffee.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_brandawa02","ref":"end_screen","title":"Thanks for stopping by","bodyMd":"This survey is for people who buy coffee to make at home, so that''s all we need from you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_brandawa01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"buy_frequency"},"op":"eq","value":"opt_never"}],"groups":[]},"from":"buy_frequency","target":"end_screen","targetKind":"ending","branch":"true"},{"id":"rl_brandawa02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"aided"},"op":"not_contains","value":"opt_brightside_coffee"}],"groups":[]},"from":"aided","target":"choice_factors","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
