INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_managementsurvey', 'management-survey', 'Management survey', 'Survey', 'Hear how priorities, decisions, communication and support feel from inside the team.', 'Separates the parts of management people usually lump together: whether priorities are clear and stable, who actually makes decisions, whether work is shared fairly and how much their own manager helps. People who rate their manager''s support low pick what''s missing, and people who rate it high name the habit worth spreading. It closes by asking how confident they are that anything will change.', '["feedback","management survey","manager feedback","team survey","leadership feedback","employee survey"]', 'Briefcase', 'scale', 3, 10, '{"schemaVersion":9,"title":"Management survey","description":"Hear how priorities, decisions, communication and support feel from inside the team.","blocks":[{"id":"blk_manageme00","ref":"welcome","title":"This survey is anonymous. We want to know how work is managed here, honestly, so we can fix what isn''t working.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_manageme01","ref":"department","title":"Which area do you work in?","description":"Only used to group answers. Groups with fewer than five people won''t be reported separately.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_operations","label":"Operations","image_key":null},{"id":"opt_sales","label":"Sales","image_key":null},{"id":"opt_marketing","label":"Marketing","image_key":null},{"id":"opt_product_and_engineering","label":"Product and engineering","image_key":null},{"id":"opt_customer_support","label":"Customer support","image_key":null},{"id":"opt_finance_and_admin","label":"Finance and admin","image_key":null},{"id":"opt_other","label":"Other","image_key":null}]},{"id":"blk_manageme02","ref":"tenure","title":"How long have you worked here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a year","image_key":null},{"id":"opt_1_3_years","label":"1–3 years","image_key":null},{"id":"opt_3_5_years","label":"3–5 years","image_key":null},{"id":"opt_more_than_5","label":"More than 5 years","image_key":null}],"allowOther":false},{"id":"blk_manageme03","ref":"how_managed","title":"How much do you agree with each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_i_know","label":"I know what my team''s top priorities are"},{"id":"opt_row_priorities_stay","label":"Priorities stay steady long enough to finish work"},{"id":"opt_row_decisions_are","label":"Decisions are explained, not just announced"},{"id":"opt_row_i_have","label":"I have a say in decisions that affect my work"},{"id":"opt_row_work_is","label":"Work is shared fairly across the team"}],"columns":[{"id":"opt_col_strongly_disagree","label":"Strongly disagree"},{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_agree","label":"Agree"},{"id":"opt_col_strongly_agree","label":"Strongly agree"}],"multiplePerRow":false},{"id":"blk_manageme04","ref":"manager_support","title":"How well does your direct manager help you do your job?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_manageme05","ref":"support_missing","title":"What''s missing? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_regular_one_to","label":"Regular one-to-ones","image_key":null},{"id":"opt_clear_useful_feedback","label":"Clear, useful feedback","image_key":null},{"id":"opt_help_removing_blockers","label":"Help removing blockers","image_key":null},{"id":"opt_recognition_for_good","label":"Recognition for good work","image_key":null},{"id":"opt_backing_in_difficult","label":"Backing in difficult situations","image_key":null},{"id":"opt_room_to_decide","label":"Room to decide how I work","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_manageme06","ref":"manager_best","title":"What does your manager do that helps your team deliver, and that other teams should copy?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_manageme07","ref":"decision_style","title":"How are decisions about your team''s work usually made?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_my_manager_decides","label":"My manager decides without asking us","image_key":null},{"id":"opt_my_manager_decides_2","label":"My manager decides after hearing the team","image_key":null},{"id":"opt_the_team_decides","label":"The team decides together","image_key":null},{"id":"opt_someone_higher_up","label":"Someone higher up decides and it''s passed down","image_key":null},{"id":"opt_it_s_often","label":"It''s often unclear who decides","image_key":null}],"allowOther":false},{"id":"blk_manageme08","ref":"slowdowns","title":"Rank what slows your team down, from most to least.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_unclear_or","label":"Unclear or shifting priorities"},{"id":"opt_item_too_many","label":"Too many meetings"},{"id":"opt_item_slow_approvals","label":"Slow approvals"},{"id":"opt_item_not_enough","label":"Not enough people"},{"id":"opt_item_tools_and","label":"Tools and systems"}]},{"id":"blk_manageme09","ref":"one_change","title":"If you could change one thing about how work is managed here, what would it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_manageme10","ref":"change_confidence","title":"How confident are you that this survey will lead to real changes?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Very confident"}],"endings":[{"id":"end_manageme01","ref":"end_thanks","title":"Thank you for being straight with us","bodyMd":"We''ll share the overall results and what we plan to change within a month of the survey closing.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_manageme01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"support_missing","target":"decision_style","targetKind":"block"},{"id":"rl_manageme02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"manager_support"},"op":"lte","value":2}],"groups":[]},"from":"manager_support","target":"support_missing","targetKind":"block","branch":"true"},{"id":"rl_manageme03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"manager_support"},"op":"gte","value":3}],"groups":[]},"from":"manager_support","target":"manager_best","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f3e6ff","surface":"#ffffff","text":"#2b1638","accent":"#9333ea","accentText":"#fdf9ff","botBubble":"#ffffff","userBubble":"#9333ea","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"confetti","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
