INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_posttrainingsurvey', 'post-training-survey', 'Post-training survey', 'Survey', 'Find out what learners can actually use after training, and what might stop them.', 'Goes past ''did you enjoy it'' to whether the training will change anything: a before-and-after confidence check, the first thing each person plans to try, and the obstacles they expect. Anyone who says little of it applies to their job explains why, and people who want a check-in a month later leave an email and get their own ending.', '["feedback","post-training survey","training evaluation","training feedback","learning transfer","workshop feedback"]', 'ClipboardCheck', 'scale', 4, 13, '{"schemaVersion":9,"title":"Post-training survey","description":"Find out what learners can actually use after training, and what might stop them.","blocks":[{"id":"blk_posttrai00","ref":"welcome","title":"Thanks for joining the training. A few questions about what you''ll take back to work, about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_posttrai01","ref":"training","title":"Which training did you attend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_posttrai02","ref":"format","title":"How did you take it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_person","label":"In person","image_key":null},{"id":"opt_live_online","label":"Live online","image_key":null},{"id":"opt_self_paced_online","label":"Self-paced online","image_key":null}],"allowOther":false},{"id":"blk_posttrai03","ref":"understanding","title":"How well do you understand the material now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Still lost","labelHigh":"Very clear"},{"id":"blk_posttrai04","ref":"confidence_before","title":"Before the training, how confident were you doing this in your job?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_posttrai05","ref":"confidence_after","title":"And how confident are you now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_posttrai06","ref":"relevance","title":"How much of it applies to the work you actually do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_almost_all_of","label":"Almost all of it","image_key":null},{"id":"opt_some_of_it","label":"Some of it","image_key":null},{"id":"opt_very_little","label":"Very little","image_key":null}],"allowOther":false},{"id":"blk_posttrai07","ref":"relevance_gap","title":"What would have made it relevant to your role?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_posttrai08","ref":"first_use","title":"What''s the first thing you''ll try at work in the next two weeks?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_posttrai09","ref":"obstacles","title":"What might get in the way of using it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_no_time_to","label":"No time to practise","image_key":null},{"id":"opt_my_manager_isn","label":"My manager isn''t on board","image_key":null},{"id":"opt_our_tools_or","label":"Our tools or process don''t allow it","image_key":null},{"id":"opt_i_need_more","label":"I need more practice first","image_key":null},{"id":"opt_i_ll_forget","label":"I''ll forget the details","image_key":null},{"id":"opt_nothing_i_can","label":"Nothing I can think of","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_posttrai10","ref":"support","title":"Which of these would help you apply it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_a_one_page","label":"A one-page reference sheet","image_key":null},{"id":"opt_a_short_follow","label":"A short follow-up session","image_key":null},{"id":"opt_practice_with_a","label":"Practice with a colleague","image_key":null},{"id":"opt_time_with_the","label":"Time with the trainer","image_key":null},{"id":"opt_examples_from_our","label":"Examples from our own work","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_posttrai11","ref":"trainer","title":"How would you rate the trainer?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_posttrai12","ref":"checkin","title":"Would you like a quick check-in in a month to see how it''s going?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_posttrai13","ref":"checkin_email","title":"Which email should we use for that?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_posttrai01","ref":"end_thanks","title":"Thank you, and good luck trying it out","bodyMd":"Your answers go to the training team to shape the next session.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_posttrai02","ref":"end_checkin","title":"