:false},{"id":"blk_exitinte14","ref":"recommend","title":"How likely are you to recommend us as a place to work?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_exitinte15","ref":"boomerang","title":"Would you consider working here again one day?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"}],"endings":[{"id":"end_exitinte01","ref":"end_thanks","title":"Thank you, genuinely 🙏","bodyMd":"All the best for what''s next.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_exitinte01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"comp_gap","target":"could_have_stayed","targetKind":"block"},{"id":"rl_exitinte02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"growth_missing","target":"could_have_stayed","targetKind":"block"},{"id":"rl_exitinte03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"raised_it","target":"could_have_stayed","targetKind":"block"},{"id":"rl_exitinte04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"balance_detail","target":"could_have_stayed","targetKind":"block"},{"id":"rl_exitinte05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_reason"},"op":"eq","value":"opt_pay_and_benefits"}],"groups":[]},"from":"primary_reason","target":"comp_gap","targetKind":"block","branch":"true"},{"id":"rl_exitinte06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_reason"},"op":"eq","value":"opt_career_growth"}],"groups":[]},"from":"primary_reason","target":"growth_missing","targetKind":"block","branch":"true"},{"id":"rl_exitinte07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_reason"},"op":"eq","value":"opt_manager_or_team"}],"groups":[]},"from":"primary_reason","target":"manager_detail","targetKind":"block","branch":"true"},{"id":"rl_exitinte08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_reason"},"op":"eq","value":"opt_work_life_balance"}],"groups":[]},"from":"primary_reason","target":"balance_detail","targetKind":"block","branch":"true"},{"id":"rl_exitinte09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_reason"},"op":"eq","value":"opt_company_direction"}],"groups":[]},"from":"primary_reason","target":"direction_detail","targetKind":"block","branch":"true"},{"id":"rl_exitinte10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_reason"},"op":"eq","value":"opt_personal_reasons"}],"groups":[]},"from":"primary_reason","target":"could_have_stayed","targetKind":"block","branch":"true"},{"id":"rl_exitinte11","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"could_have_stayed"},"op":"eq","value":true}],"groups":[]},"from":"could_have_stayed","target":"what_would_keep","targetKind":"block","branch":"true"},{"id":"rl_exitinte12","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"could_have_stayed"},"op":"eq","value":false}],"groups":[]},"from":"could_have_stayed","target":"what_worked","targetKind":"block","branch":"true"},{"id":"rl_exitinte13","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"direction_detail","target":"what_to_change","targetKind":"block","branch":"true"},{"id":"rl_exitinte14","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"what_would_keep","target":"what_to_change","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,