VALUES ('tpl_productfeedbacksurvey', 'product-feedback-survey', 'Product feedback survey', 'Survey', 'Learn what users rely on, what gets in their way and what they want next.', 'Starts with the job people hire your product for, then rates it on the things that matter. The overall score decides the next question: happy users are asked what they would hate to lose, and unhappy ones describe the last time it got in their way and whether it blocks them outright.', '["feedback","product feedback survey","user feedback","feature requests","product research","branching"]', 'ThumbsUp', 'scale', 4, 13, '{"schemaVersion":9,"title":"Product feedback","description":"Learn what users rely on, what gets in their way and what they want next.","blocks":[{"id":"blk_productf00","ref":"welcome","title":"Thanks for using the product. Five minutes of your honest opinion will shape what we build next.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_productf01","ref":"use_for","title":"In a sentence, what do you mainly use it for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_productf02","ref":"frequency","title":"How often do you use it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_a_few_times","label":"A few times a week","image_key":null},{"id":"opt_a_few_times_2","label":"A few times a month","image_key":null},{"id":"opt_rarely","label":"Rarely","image_key":null}],"allowOther":false},{"id":"blk_productf03","ref":"aspects","title":"How does it do on each of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_ease_of","label":"Ease of use"},{"id":"opt_row_reliability","label":"Reliability"},{"id":"opt_row_speed","label":"Speed"},{"id":"opt_row_has_the","label":"Has the features I need"},{"id":"opt_row_help_and","label":"Help and documentation"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_great","label":"Great"}],"multiplePerRow":false},{"id":"blk_productf04","ref":"overall","title":"Overall, how well does it do the job you use it for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_productf05","ref":"best_part","title":"What works best for you? What would you miss most if it disappeared?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productf06","ref":"obstacle","title":"Tell us about the last time it got in your way. What were you trying to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_productf07","ref":"blocker","title":"Does that stop you getting the work done, or just slow you down?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"It stops me","noLabel":"It slows me down"},{"id":"blk_productf08","ref":"one_change","title":"If you could change one thing about the product, what would it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productf09","ref":"priorities","title":"Rank these by what you would like us to work on first.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_fixing_bugs","label":"Fixing bugs"},{"id":"opt_item_making_it","label":"Making it faster"},{"id":"opt_item_making_it_2","label":"Making it easier to learn"},{"id":"opt_item_new_features","label":"New features"},{"id":"opt_item_working_with","label":"Working with other tools I use"}]},{"id":"blk_productf10","ref":"disappointed","title":"How would you feel if you could no longer use the product?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_very_disappointed","label":"Very disappointed","image_key":null},{"id":"opt_somewhat_disappointed","label":"Somewhat disappointed","image_key":null},{"id":"opt_not_disappointed","label":"Not disappointed","image_key":null}],"allowOther":false},{"id":"blk_productf11","ref":"recommend","title":"How likely are you to recommend it to a friend or colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_productf12","ref":"follow_up","title":"Could someone from the product team get in touch about your answers?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_productf13","ref":"email","title":"What''s the best email to reach you on?","description":"We''ll only use it to talk about this feedback.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_productf01","ref":"end_thanks","title":"Thank you, this goes straight to the product team","bodyMd":"We read every answer, and the patterns decide what we fix and build next.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_productf01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"best_part","target":"one_change","targetKind":"block"},{"id":"rl_productf02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"gte","value":3}],"groups":[]},"from":"overall","target":"best_part","targetKind":"block","branch":"true"},{"id":"rl_productf03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"lte","value":2}],"groups":[]},"from":"overall","target":"obstacle","targetKind":"block","branch":"true"},{"id":"rl_productf04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"follow_up"},"op":"eq","value":false}],"groups":[]},"from":"follow_up","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta"