VALUES ('tpl_brandingquestionnaire', 'branding-questionnaire', 'Branding questionnaire', 'Survey', 'Everything a designer needs to know about a business before brand work starts.', 'Covers the business, the customer, the personality and the practical scope, so the first meeting starts from answers instead of a blank page. Clients refreshing an existing brand are asked what works now, what doesn''t and to upload their current files. A brand new business skips straight to its audience.', '["feedback","branding questionnaire","brand discovery","design brief","client onboarding","agency intake"]', 'Palette', 'scale', 5, 17, '{"schemaVersion":9,"title":"Branding questionnaire","description":"Everything a designer needs to know about a business before brand work starts.","blocks":[{"id":"blk_branding00","ref":"welcome","title":"Before we start on your brand, we''d like to understand the business behind it. This takes about ten minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_branding01","ref":"contact","title":"First, who are we working with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_branding02","ref":"business_name","title":"What''s the name of the business?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_branding03","ref":"website","title":"Do you have a website? Paste the link if so.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_branding04","ref":"what_you_do","title":"Describe what the business does, the way you''d explain it to a friend.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_branding05","ref":"stage","title":"Which of these fits best?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_new_business","label":"A new business with no brand yet","image_key":null},{"id":"opt_a_refresh_of","label":"A refresh of our existing brand","image_key":null},{"id":"opt_a_full_rebrand","label":"A full rebrand","image_key":null}],"allowOther":false},{"id":"blk_branding06","ref":"keep","title":"What about the current brand is working and should stay?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_branding07","ref":"change_why","title":"What isn''t working any more? What made you decide to change it now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_branding08","ref":"current_files","title":"Upload your current logo and any brand files you have.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":20},{"id":"blk_branding09","ref":"audience","title":"Who is your ideal customer? Describe one real person if you can.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_branding10","ref":"competitors","title":"Name two or three competitors, and how you want people to see you differently from them.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_branding11","ref":"personality","title":"Pick three words that should describe the brand.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_friendly","label":"Friendly","image_key":null},{"id":"opt_premium","label":"Premium","image_key":null},{"id":"opt_bold","label":"Bold","image_key":null},{"id":"opt_calm","label":"Calm","image_key":null},{"id":"opt_playful","label":"Playful","image_key":null},{"id":"opt_trustworthy","label":"Trustworthy","image_key":null},{"id":"opt_expert","label":"Expert","image_key":null},{"id":"opt_down_to_earth","label":"Down to earth","image_key":null},{"id":"opt_inventive","label":"Inventive","image_key":null},{"id":"opt_warm","label":"Warm","image_key":null}],"minSelections":3,"maxSelections":3,"allowOther":false},{"id":"blk_branding12","ref":"tone","title":"Where should the brand sit between playful and serious?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Playful","labelHigh":"Serious"},{"id":"blk_branding13","ref":"admired","title":"Which brands, in any industry, do you admire? What do you like about them?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_branding14","ref":"avoid","title":"Is anything off the table? Colours, styles or ideas you don''t want.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_branding15","ref":"deliverables","title":"What do you need from this project?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_logo","label":"Logo","image_key":null},{"id":"opt_colour_palette_and","label":"Colour palette and typography","image_key":null},{"id":"opt_brand_guidelines","label":"Brand guidelines","image_key":null},{"id":"opt_messaging_and_tagline","label":"Messaging and tagline","image_key":null},{"id":"opt_website_design","label":"Website design","image_key":null},{"id":"opt_social_media_templates","label":"Social media templates","image_key":null},{"id":"opt_packaging_or_print","label":"Packaging or print","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_branding16","ref":"deadline","title":"Is there a launch date we should work toward?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_branding17","ref":"decision_maker","title":"Who has the final say on the brand, and will they be in the review meetings?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200}],"endings":[{"id":"end_branding01","ref":"end_thanks","title":"Thank you, that''s a great start 🎨","bodyMd":"We''ll read through your answers before our first call and come prepared with questions.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_branding01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"stage"},"op":"eq","value":"opt_a_new_business"}],"groups":[]},"from":"stage","target":"audience","targetKind":"block","branch":"true"},{"id":"rl_branding02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"stage"},"op":"eq","value":"opt_a_refresh_of"}],"groups":[]},"from":"stage","target":"keep","targetKind":"block","branch":"true"},{"id":"rl_branding03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"stage"},"op":"eq","value":"opt_a_full_rebrand"}],"groups":[]},"from":"stage","target":"keep","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#221d44","surface":"#2d2757","text":"#f5f3ff","accent":"#ff8a4c","accentText":"#1c1917","botBubble":"#332c5e","userBubble":"#ff8a4c","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":nul