VALUES ('tpl_cancellationsurvey', 'cancellation-survey', 'Cancellation survey', 'Survey', 'Find out why people leave, and ask each of them the one follow-up that fits.', 'The exit is the most honest moment you get, and the reason decides what is worth asking next. Price gets a question about what would have felt fair, a missing feature gets asked which one, and a switch to a competitor gets asked what they do better. "No longer need it" is left alone. Nobody is talked out of leaving.', '["feedback","cancellation survey","churn survey","exit survey","subscription cancellation","branching"]', 'DoorOpen', 'scale', 3, 12, '{"schemaVersion":9,"title":"Cancellation survey","description":"Find out why people leave, and ask each of them the one follow-up that fits.","blocks":[{"id":"blk_cancella00","ref":"welcome","title":"Sorry to see you go. A couple of quick questions, and then you''re done. Your cancellation goes ahead either way.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_cancella01","ref":"reason","title":"What''s the main reason you''re cancelling?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_expensive","label":"Too expensive","image_key":null},{"id":"opt_missing_a_feature","label":"Missing a feature I need","image_key":null},{"id":"opt_too_hard_to","label":"Too hard to use","image_key":null},{"id":"opt_found_a_better","label":"Found a better alternative","image_key":null},{"id":"opt_i_didn_t","label":"I didn''t use it enough","image_key":null},{"id":"opt_no_longer_need","label":"No longer need it","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_cancella02","ref":"price_fair","title":"What would have felt fair?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_lower_price","label":"A lower price for the same thing","image_key":null},{"id":"opt_a_smaller_plan","label":"A smaller plan with fewer features","image_key":null},{"id":"opt_the_price_was","label":"The price was fine, the value wasn''t there","image_key":null},{"id":"opt_paying_monthly_instead","label":"Paying monthly instead of yearly, or the other way round","image_key":null}],"allowOther":false},{"id":"blk_cancella03","ref":"missing_feature","title":"Which feature were you missing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_cancella04","ref":"missing_blocked","title":"Did that block you outright, or just slow you down?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Blocked me","noLabel":"Slowed me down"},{"id":"blk_cancella05","ref":"hard_where","title":"Where did it lose you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_cancella06","ref":"competitor","title":"What are you moving to?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_cancella07","ref":"competitor_why","title":"What do they do better?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_cancella08","ref":"low_use_why","title":"What got in the way of using it more?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_never_finished","label":"I never finished setting it up","image_key":null},{"id":"opt_i_forgot_about","label":"I forgot about it","image_key":null},{"id":"opt_it_didn_t","label":"It didn''t fit how I work","image_key":null},{"id":"opt_i_didn_t","label":"I didn''t have the time","image_key":null}],"allowOther":false},{"id":"blk_cancella09","ref":"tenure","title":"How long were you with us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a month","image_key":null},{"id":"opt_1_6_months","label":"1–6 months","image_key":null},{"id":"opt_6_12_months","label":"6–12 months","image_key":null},{"id":"opt_over_a_year","label":"Over a year","image_key":null}],"allowOther":false},{"id":"blk_cancella10","ref":"detail","title":"Anything else you''d like us to know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_cancella11","ref":"would_return","title":"Would you consider coming back if we fixed what made you leave?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Maybe","noLabel":"Unlikely"},{"id":"blk_cancella12","ref":"keep_in_touch","title":"Want us to tell you when we do? Leave your email.","description":"Only for this. No marketing.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_cancella01","ref":"end_thanks","title":"Thanks for the honesty 👋","bodyMd":"Your cancellation is not affected by anything you said here.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_cancella02","ref":"end_notify","title":"Thanks, we''ll let you know","bodyMd":"We''ll write once, when what you told us about has changed. Your cancellation goes ahead as normal.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[]