VALUES ('tpl_customersuccessstoryques', 'customer-success-story-questionnaire', 'Customer success story questionnaire', 'Survey', 'Collect a customer''s story in their own words, ready to shape into a case study.', 'Walks a customer through the story in the order a case study is written: before, the decision, the day to day and the results. Anyone with a figure to share is asked how they measured it. Customers who agree to be named are asked for a headshot, and those who prefer to stay anonymous are asked how they''d like to be described.', '["feedback","customer success story","case study questionnaire","customer testimonial","case study interview","b2b marketing"]', 'Quote', 'scale', 5, 16, '{"schemaVersion":9,"title":"Customer success story","description":"Collect a customer''s story in their own words, ready to shape into a case study.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"Thanks for agreeing to share your story. Answer in your own words; we''ll do the tidying up and show you the draft before anything goes out.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"contact","title":"Let''s start with your details.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_customer02","ref":"company","title":"Which company do you work for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_customer03","ref":"job_title","title":"What''s your job title?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_customer04","ref":"company_does","title":"In two or three sentences, what does your company do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_customer05","ref":"before","title":"Before you started working with us, what problem were you trying to solve?","description":"What was it costing you in time, money or stress?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_customer06","ref":"previous","title":"How were you handling it before?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_with_another_product","label":"With another product like ours","image_key":null},{"id":"opt_with_spreadsheets_or","label":"With spreadsheets or manual work","image_key":null},{"id":"opt_with_an_agency","label":"With an agency or contractor","image_key":null},{"id":"opt_we_weren_t","label":"We weren''t handling it at all","image_key":null}],"allowOther":true},{"id":"blk_customer07","ref":"why_chose","title":"Why did you choose us over the other options?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_customer08","ref":"how_use","title":"How does your team use it day to day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_customer09","ref":"results","title":"What has changed since you started?","description":"Think about time saved, money saved, growth, or things you can do now that you couldn''t before.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_customer10","ref":"has_figure","title":"Do you have a figure we could publish, such as hours saved each week?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_customer11","ref":"figure","title":"What''s the figure, and how did you measure it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_customer12","ref":"advice","title":"What would you say to someone who is weighing us up right now?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_customer13","ref":"named","title":"Can we publish the story with your name, job title and company?","description":"You''ll approve the final wording either way.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, name me","noLabel":"Keep me anonymous"},{"id":"blk_customer14","ref":"headshot","title":"Could you upload a photo of yourself to go with your quote?","description":"A clear, well-lit headshot works best. Team or office photos are welcome too.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*"],"maxFiles":4,"maxSizeMB":15},{"id":"blk_customer15","ref":"anon_description","title":"How should we describe you instead?","description":"For example, \"Operations lead at a logistics company\".","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_customer16","ref":"call_ok","title":"Would you be open to a short call so we can fill in any gaps?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"Thank you for sharing your story","bodyMd":"We''ll write it up and send you the draft to approve before anything is published.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_customer02","ref":"end_call","title":"Thank you, we''ll be in touch to book a call 🙌","bodyMd":"Expect an email with a few times to choose from. We''ll send the draft after we speak.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"headshot","target":"call_ok","targetKind":"block"},{"id":"rl_customer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_figure"},"op":"eq","value":false}],"groups":[]},"from":"has_figure","target":"advice","targetKind":"block","branch":"true"},{"id":"rl_customer03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"named"},"op":"eq","value":true}],"groups":[]},"from":"named","target":"headshot","targetKind":"block","branch":"true"},{"id":"rl_customer04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"named"},"op":"eq","value":false}],"groups":[]},"from":"named","target":"anon_description","targetKind":"block","branch":"true"},{"id":"rl_customer05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"call_ok"},"op":"eq","value":true}],"groups":[]},"from":"call_ok","target":"end_call","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f3e6ff","surface":"#ffffff","text":"#2b1638","accent":"#9333ea","accentText":"#fdf9ff","botBubble":"#ffffff","userBubble":"#9333ea","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"confetti","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
