VALUES ('tpl_emaildesignquestionnaire', 'email-design-questionnaire', 'Email design questionnaire', 'Survey', 'Collect the audience, message, action and practical limits before designing an email.', 'Asks what a designer needs before opening a layout tool: who the email is for, the one action it should drive, who writes the copy and what it must work with. Clients ordering a series are asked how many emails, and anyone with brand guidelines is asked to upload them.', '["feedback","email design questionnaire","email design brief","newsletter design","email template request","client intake"]', 'Mail', 'scale', 5, 15, '{"schemaVersion":9,"title":"Email design brief","description":"Collect the audience, message, action and practical limits before designing an email.","blocks":[{"id":"blk_emaildes00","ref":"welcome","title":"Let''s plan your email. A few questions now saves a round of revisions later.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_emaildes01","ref":"contact","title":"Who should we send the designs to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_emaildes02","ref":"company","title":"Which company or brand is this for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_emaildes03","ref":"email_type","title":"What kind of email is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_newsletter","label":"Newsletter","image_key":null},{"id":"opt_promotion_or_sale","label":"Promotion or sale","image_key":null},{"id":"opt_product_announcement","label":"Product announcement","image_key":null},{"id":"opt_welcome_or_onboarding","label":"Welcome or onboarding email","image_key":null},{"id":"opt_event_invitation","label":"Event invitation","image_key":null},{"id":"opt_receipt_or_confirmation","label":"Receipt or confirmation","image_key":null}],"allowOther":true},{"id":"blk_emaildes04","ref":"scope","title":"Is this a single email or something you''ll reuse?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_one_off","label":"A one-off send","image_key":null},{"id":"opt_a_reusable_template","label":"A reusable template","image_key":null},{"id":"opt_a_series_of","label":"A series of emails","image_key":null}],"allowOther":false},{"id":"blk_emaildes05","ref":"series_count","title":"How many emails are in the series?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":2,"max":30,"integerOnly":true},{"id":"blk_emaildes06","ref":"audience","title":"Who will receive it, and what do they already know about you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_emaildes07","ref":"main_action","title":"What is the one thing a reader should do after opening it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":400,"aiQualityCheck":false},{"id":"blk_emaildes08","ref":"cta_link","title":"Where should the main button link to?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"url","unique":false,"httpsOnly":false},{"id":"blk_emaildes09","ref":"copy","title":"Who is writing the words?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_we_ll_supply","label":"We''ll supply final copy","image_key":null},{"id":"opt_we_have_a","label":"We have a draft that needs editing","image_key":null},{"id":"opt_we_need_you","label":"We need you to write it","image_key":null}],"allowOther":false},{"id":"blk_emaildes10","ref":"has_brand","title":"Do you have brand guidelines, such as a logo, colours and fonts?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_emaildes11","ref":"brand_files","title":"Upload your logo and brand guidelines.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":20},{"id":"blk_emaildes12","ref":"platform","title":"Which email platform will you send it from?","description":"We''ll build and test it in the tool you''ll actually send with.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_emaildes13","ref":"must_haves","title":"Which of these does it need to handle?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_looks_right_in","label":"Looks right in dark mode","image_key":null},{"id":"opt_a_plain_text","label":"A plain-text version","image_key":null},{"id":"opt_personal_details_like","label":"Personal details like the reader''s first name","image_key":null},{"id":"opt_more_than_one","label":"More than one language","image_key":null},{"id":"opt_easy_to_read","label":"Easy to read with a screen reader","image_key":null},{"id":"opt_images_we_can","label":"Images we can swap for each send","image_key":null}],"minSelections":0,"maxSelections":10,"allowOther":false},{"id":"blk_emaildes14","ref":"examples","title":"Share a couple of emails you''ve enjoyed receiving, and what you liked about them.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_emaildes15