VALUES ('tpl_leadgenerationsurvey', 'lead-generation-survey', 'Lead generation survey', 'Survey', 'Learn what potential buyers need, then invite the ones who want help to talk.', 'Asks about the problem, what has been tried and how urgent it is before asking for any details, so people answer as themselves rather than as a lead. At the end they choose what they want from you: a call, a written summary, or nothing at all. Each choice gets its own path and its own sign-off.', '["feedback","lead generation survey","lead capture","prospect research","b2b survey","branching"]', 'Target', 'scale', 3, 9, '{"schemaVersion":9,"title":"Lead generation survey","description":"Learn what potential buyers need, then invite the ones who want help to talk.","blocks":[{"id":"blk_leadgene00","ref":"welcome","title":"We''re learning how teams like yours handle this problem. A few quick questions, and you decide at the end whether we follow up.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_leadgene01","ref":"role","title":"Which best describes your role?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_founder_or_owner","label":"Founder or owner","image_key":null},{"id":"opt_marketing","label":"Marketing","image_key":null},{"id":"opt_sales","label":"Sales","image_key":null},{"id":"opt_operations","label":"Operations","image_key":null}],"allowOther":true},{"id":"blk_leadgene02","ref":"company_size","title":"How many people work at your company?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_2_10","label":"2–10","image_key":null},{"id":"opt_11_50","label":"11–50","image_key":null},{"id":"opt_51_200","label":"51–200","image_key":null},{"id":"opt_more_than_200","label":"More than 200","image_key":null}],"allowOther":false},{"id":"blk_leadgene03","ref":"challenge","title":"What''s the biggest challenge you''re trying to solve right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_leadgene04","ref":"tried","title":"What have you tried so far?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_handling_it_ourselves","label":"Handling it ourselves","image_key":null},{"id":"opt_hiring_someone_for","label":"Hiring someone for it","image_key":null},{"id":"opt_software_or_a","label":"Software or a tool","image_key":null},{"id":"opt_an_agency_or","label":"An agency or consultant","image_key":null},{"id":"opt_nothing_yet","label":"Nothing yet","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_leadgene05","ref":"impact","title":"How much is this problem holding you back?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"A minor nuisance","labelHigh":"A serious problem"},{"id":"blk_leadgene06","ref":"timeline","title":"When would you like it solved?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_within_a_month","label":"Within a month","image_key":null},{"id":"opt_in_the_next","label":"In the next 1–3 months","image_key":null},{"id":"opt_later_this_year","label":"Later this year","image_key":null},{"id":"opt_no_plans_just","label":"No plans, just researching","image_key":null}],"allowOther":false},{"id":"blk_leadgene07","ref":"next_step","title":"What would be most useful from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_short_call","label":"A short call to talk it through","image_key":null},{"id":"opt_a_written_summary","label":"A written summary with suggestions","image_key":null},{"id":"opt_the_survey_findings","label":"The survey findings when they''re ready","image_key":null},{"id":"opt_nothing_for_now","label":"Nothing for now, thanks","image_key":null}],"allowOther":false},{"id":"blk_leadgene08","ref":"call_contact","title":"Where can we reach you to set up the call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_leadgene09","ref":"email_contact","title":"Where should we send it?","description":"We''ll only use this to send what you asked for.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","email"]}],"endings":[{"id":"end_leadgene01","ref":"end_thanks","title":"Thanks, we''ll send it by email","bodyMd":"Look out for it in your inbox. We''ll only send what you asked for.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_leadgene02","ref":"end_call","title":"Thanks, we''ll be in touch to book a call 📞","bodyMd":"Someone who knows this problem well will contact you within a couple of working days.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_leadgene03","ref":"end_research","title":"Thanks for your answers","bodyMd":"That''s everything. We won''t contact you, but you''re welcome to come back if that changes.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_leadgene01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"call_contact","target":"end_call","targetKind":"ending"},{"id":"rl_leadgene02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"next_step"},"op":"eq","value":"opt_a_short_call"}],"groups":[]},"from":"next_step","target":"call_contact","targetKind":"block","branch":"true"},{"id":"rl_leadgene03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"next_step"},"op":"eq","value":"opt_a_written_summary"}],"groups":[]},"from":"next_step","target":"email_contact","targetKind":"block","branch":"true"},{"id":"rl_leadgene04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"next_step"},"op":"eq","value":"opt_the_survey_findings"}],"groups":[]},"from":"next_step","target":"email_contact","targetKind":"block","branch":"true"},{"id":"rl_leadgene05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"next_step"},"op":"eq","value":"opt_nothing_for_now"}],"groups":[]},"from":"next_step","target":"end_research","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
