INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_clientsatisfactionsurvey', 'client-satisfaction-survey', 'Client satisfaction survey', 'Survey', 'Check in with ongoing clients on results, communication and whether they plan to stay.', 'Made for a regular check-in with retained clients rather than a one-off project debrief. Clients whose results fell short are asked where and what would put it right, and the rest are asked what they''d hate to lose. Anyone unsure about continuing is offered a call from their account lead, and those who accept get their own ending.', '["feedback","client satisfaction survey","client check-in","account review","client retention","agency survey"]', 'SmilePlus', 'scale', 4, 12, '{"schemaVersion":9,"title":"Client satisfaction","description":"Check in with ongoing clients on results, communication and whether they plan to stay.","blocks":[{"id":"blk_clientsa00","ref":"welcome","title":"Thanks for working with us. We''d like to know how things are really going. This takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_clientsa01","ref":"service","title":"Which service or account are you answering about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_clientsa02","ref":"overall","title":"Overall, how satisfied are you with working with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_clientsa03","ref":"areas","title":"How satisfied are you with each of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_quality_of","label":"Quality of the work"},{"id":"opt_row_how_quickly","label":"How quickly we respond"},{"id":"opt_row_updates_on","label":"Updates on progress"},{"id":"opt_row_how_well","lab