VALUES ('tpl_healthcareemployeesatisf', 'healthcare-employee-satisfaction-survey', 'Healthcare employee satisfaction survey', 'Survey', 'Understand how healthcare staff experience their work, without collecting patient details.', 'Written for wards, clinics and practices, where satisfaction depends on staffing, handovers, breaks and feeling safe to speak up. Staff who say they often feel burned out are asked what drives it, and anyone unsure about staying is asked what would keep them. Open questions remind people to leave patient details out.', '["healthcare","healthcare employee survey","nurse satisfaction survey","hospital staff survey","staff burnout","clinical staff feedback"]', 'Stethoscope', 'content', 4, 12, '{"schemaVersion":9,"title":"Healthcare staff satisfaction","description":"Understand how healthcare staff experience their work, without collecting patient details.","blocks":[{"id":"blk_healthca00","ref":"welcome","title":"This survey is anonymous and takes about five minutes. Please don''t include patient names or details in any answer.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_healthca01","ref":"role","title":"Which best describes your role?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_nurse_or_midwife","label":"Nurse or midwife","image_key":null},{"id":"opt_doctor","label":"Doctor","image_key":null},{"id":"opt_allied_health_professional","label":"Allied health professional","image_key":null},{"id":"opt_healthcare_assistant_or","label":"Healthcare assistant or support worker","image_key":null},{"id":"opt_admin_or_reception","label":"Admin or reception","image_key":null},{"id":"opt_other","label":"Other","image_key":null}],"allowOther":false},{"id":"blk_healthca02","ref":"shift_pattern","title":"What shift pattern do you mostly work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_days","label":"Days","image_key":null},{"id":"opt_nights","label":"Nights","image_key":null},{"id":"opt_rotating_days_and","label":"Rotating days and nights","image_key":null},{"id":"opt_regular_office_hours","label":"Regular office hours","image_key":null}],"allowOther":false},{"id":"blk_healthca03","ref":"satisfaction","title":"Overall, how satisfied are you working here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_healthca04","ref":"workload","title":"How manageable is your workload on a typical shift?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Unmanageable","labelHigh":"Very manageable"},{"id":"blk_healthca05","ref":"conditions","title":"How often is each of these true for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_i_have","label":"I have the equipment and supplies I need"},{"id":"opt_row_staffing_levels","label":"Staffing levels let me give safe care"},{"id":"opt_row_handovers_give","label":"Handovers give me what I need"},{"id":"opt_row_i_can","label":"I can take my breaks"},{"id":"opt_row_managers_keep","label":"Managers keep me informed about changes"},{"id":"opt_row_i_feel","label":"I feel safe raising concerns"}],"columns":[{"id":"opt_col_never","label":"Never"},{"id":"opt_col_sometimes","label":"Sometimes"},{"id":"opt_col_usually","label":"Usually"},{"id":"opt_col_always","label":"Always"}],"multiplePerRow":false},{"id":"blk_healthca06","ref":"burnout","title":"How often do you finish a shift feeling burned out?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_rarely","label":"Rarely","image_key":null},{"id":"opt_sometimes","label":"Sometimes","image_key":null},{"id":"opt_often","label":"Often","image_key":null},{"id":"opt_most_shifts","label":"Most shifts","image_key":null}],"allowOther":false},{"id":"blk_healthca07","ref":"burnout_causes","title":"What contributes to that most?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_understaffing","label":"Understaffing","image_key":null},{"id":"opt_long_or_unpredictable","label":"Long or unpredictable hours","image_key":null},{"id":"opt_missed_breaks","label":"Missed breaks","image_key":null},{"id":"opt_emotional_demands_of","label":"Emotional demands of the work","image_key":null},{"id":"opt_paperwork_and_admin","label":"Paperwork and admin","image_key":null},{"id":"opt_little_support_from","label":"Little support from leaders","image_key":null},{"id":"opt_conflict_with_colleagues","label":"Conflict with colleagues","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_healthca08","ref":"valued","title":"How valued do you feel for the work you do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Very valued"},{"id":"blk_healthca09","ref":"staying","title":"Do you see yourself working here a year from now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_healthca10","ref":"keep_you","title":"What would make you more likely to stay?","description":"Please leave out patient names or details.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_healthca11","ref":"one_change","title":"What one change would most improve your working day?","description":"Please leave out patient names or details.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_healthca12","ref":"recommend","title":"How likely are you to recommend this as a place to work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"}],"endings":[{"id":"end_healthca01","ref":"end_thanks","title":"Thank you for your time 💙","bodyMd":"Results are reported by staff group only, and we''ll share what we''re changing once the survey closes.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_healthca01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"burnout"},"op":"eq","value":"opt_rarely"}],"groups":[]},"from":"burnout","target":"valued","targetKind":"block","branch":"true"},{"id":"rl_healthca02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"burnout"},"op":"eq","value":"opt_sometimes"}],"groups":[]},"from":"burnout","target":"valued","targetKind":"block","branch":"true"},{"id":"rl_healthca03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"staying"},"op":"eq","value":"opt_yes"}],"groups":[]},"from":"staying","target":"one_change","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","after