VALUES ('tpl_competitorresearchsurvey', 'competitor-research-survey', 'Competitor research survey', 'Survey', 'Find out who you were compared with, on what, and why the buyer went the way they did.', 'Built for buyers who have just made a decision, including the ones who went elsewhere. It maps the shortlist and the criteria first, then asks one question that splits the path: buyers who chose you say what tipped it, buyers who chose a rival say what made that option the better fit, and anyone still deciding says what is holding them up.', '["market research","competitor research","win loss survey","competitive analysis","buyer research"]', 'Target', 'content', 4, 14, '{"schemaVersion":9,"title":"Competitor research","description":"Find out who you were compared with, on what, and why the buyer went the way they did.","blocks":[{"id":"blk_competit00","ref":"welcome","title":"You recently looked at a few options, us among them. Mind telling us how that comparison went? Honest answers help most.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_competit01","ref":"role_in_decision","title":"What was your part in the decision?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_made_the","label":"I made the final call","image_key":null},{"id":"opt_i_recommended_an","label":"I recommended an option","image_key":null},{"id":"opt_i_was_asked","label":"I was asked for input","image_key":null},{"id":"opt_i_was_one","label":"I was one of several people deciding","image_key":null}],"allowOther":false},{"id":"blk_competit02","ref":"alternatives","title":"Which other options did you look at? Include building it yourselves or sticking with what you had, if those were on the table.","required":true,"visibility":null,"image_key":null,"agentHints":{"askStyle":"Encourage them to name specific products or approaches, even ones they dropped early.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_competit03","ref":"research_channels","title":"Where did you do your research?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_search_engines","label":"Search engines","image_key":null},{"id":"opt_review_and_comparison","label":"Review and comparison sites","image_key":null},{"id":"opt_recommendations_from_colle","label":"Recommendations from colleagues or friends","image_key":null},{"id":"opt_social_media_or","label":"Social media or online communities","image_key":null},{"id":"opt_conversations_with_sales","label":"Conversations with sales teams","image_key":null},{"id":"opt_free_trials_or","label":"Free trials or demos","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_competit04","ref":"criteria","title":"Rank what mattered most when you compared the options.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_price","label":"Price"},{"id":"opt_item_ease_of","label":"Ease of use"},{"id":"opt_item_a_specific","label":"A specific feature we needed"},{"id":"opt_item_fit_with","label":"Fit with the tools we already use"},{"id":"opt_item_quality_of","label":"Quality of support"},{"id":"opt_item_reputation_and","label":"Reputation and reviews"}]},{"id":"blk_competit05","ref":"comparison","title":"Compared with the other options, how did we come across on each of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_price","label":"Price"},{"id":"opt_row_ease_of","label":"Ease of use"},{"id":"opt_row_features","label":"Features"},{"id":"opt_row_support","label":"Support"},{"id":"opt_row_trust_in","label":"Trust in the company"}],"columns":[{"id":"opt_col_weaker","label":"Weaker"},{"id":"opt_col_about_the","label":"About the same"},{"id":"opt_col_stronger","label":"Stronger"},{"id":"opt_col_didn_t","label":"Didn''t compare this"}],"multiplePerRow":false},{"id":"blk_competit06","ref":"outcome","title":"Where did you end up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_we_chose_you","label":"We chose you","image_key":null},{"id":"opt_we_chose_another","label":"We chose another option","image_key":null},{"id":"opt_we_re_still","label":"We''re still deciding","image_key":null},{"id":"opt_we_decided_not","label":"We decided not to buy anything for now","image_key":null}],"allowOther":false},{"id":"blk_competit07","ref":"won_reason","title":"What tipped the decision toward us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_competit08","ref":"chosen_option","title":"Which option did you go with?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_competit09","ref":"lost_reason","title":"What made them the better fit for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_competit10","ref":"win_back","title":"Is there anything that would make you look at us again later?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_competit11","ref":"blockers","title":"What is holding the decision up, or made you hold off?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_budget_isn_t","label":"Budget isn''t approved yet","image_key":null},{"id":