VALUES ('tpl_personalityquestionnaire', 'personality-questionnaire', 'Personality questionnaire', 'Survey', 'Help people describe how they like to work, in their own words, as a start to a team conversation.', 'Everyday questions about energy, focus, decisions and feedback, and each person picks who can see their answers before they start. Anyone who says pressure tends to overwhelm them is asked what actually helps, so a manager has something to act on.', '["market research","personality questionnaire","working style","team building","self reflection","onboarding"]', 'Brain', 'content', 4, 11, '{"schemaVersion":9,"title":"Working style questionnaire","description":"Help people describe how they like to work, in their own words, as a start to a team conversation.","blocks":[{"id":"blk_personal00","ref":"welcome","title":"A few questions about how you like to work. There are no right answers, and nothing here is a test.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_personal01","ref":"name","title":"What should we call you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_personal02","ref":"visibility","title":"Before we start: who would you like to see your answers?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_only_my_manager","label":"Only my manager","image_key":null},{"id":"opt_my_whole_team","label":"My whole team","image_key":null},{"id":"opt_only_the_person","label":"Only the person running this","image_key":null}],"allowOther":false},{"id":"blk_personal03","ref":"energy","title":"After a long day of meetings and conversations, how do you usually feel?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_energised_i_could","label":"Energised, I could keep going","image_key":null},{"id":"opt_fine_it_depends","label":"Fine, it depends on the people","image_key":null},{"id":"opt_drained_i_need","label":"Drained, I need quiet time to recover","image_key":null}],"allowOther":false},{"id":"blk_personal04","ref":"new_task","title":"When you get a new task, what do you do first?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_make_a_plan","label":"Make a plan before starting","image_key":null},{"id":"opt_jump_in_and","label":"Jump in and figure it out as I go","image_key":null},{"id":"opt_talk_it_through","label":"Talk it through with someone","image_key":null},{"id":"opt_look_at_how","label":"Look at how it was done before","image_key":null}],"allowOther":false},{"id":"blk_personal05","ref":"statements","title":"How much does each of these sound like you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_i_like","label":"I like having a clear routine"},{"id":"opt_row_i_enjoy","label":"I enjoy meeting new people"},{"id":"opt_row_i_prefer","label":"I prefer to finish one thing before starting another"},{"id":"opt_row_i_m","label":"I''m comfortable speaking up in a group"},{"id":"opt_row_i_notice","label":"I notice small details others miss"}],"columns":[{"id":"opt_col_not_really","label":"Not really"},{"id":"opt_col_sometimes","label":"Sometimes"},{"id":"opt_col_mostly","label":"Mostly"},{"id":"opt_col_very_much","label":"Very much"}],"multiplePerRow":false},{"id":"blk_personal06","ref":"decisions","title":"When you make a decision, do you lean more on gut feeling or on data?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":7,"startAt":1,"labelLow":"Gut feeling","labelHigh":"Data and evidence"},{"id":"blk_personal07","ref":"motivators","title":"Rank what keeps you most motivated at work.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_learning_something","label":"Learning something new"},{"id":"opt_item_seeing_the","label":"Seeing the result of my work"},{"id":"opt_item_recognition_from","label":"Recognition from others"},{"id":"opt_item_helping_the","label":"Helping the people around me"},{"id":"opt_item_having_control","label":"Having control over how I work"}]},{"id":"blk_personal08","ref":"feedback","title":"How do you prefer to get feedback?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_straight_away_as","label":"Straight away, as things happen","image_key":null},{"id":"opt_in_a_regular","label":"In a regular one-to-one","image_key":null},{"id":"opt_in_writing_so","label":"In writing, so I can think about it","image_key":null},{"id":"opt_a_mix_depending","label":"A mix, depending on the topic","image_key":null}],"allowOther":false},{"id":"blk_personal09","ref":"pressure","title":"When deadlines pile up, which is closest to how you react?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_get_more","label":"I get more focused","image_key":null},{"id":"opt_i_cope_though","label":"I cope, though it takes effort","image_key":null},{"id":"opt_i_feel_overwhelmed","label":"I feel overwhelmed more often than I''d like","image_key":null}],"allowOther":false},{"id":"blk_personal10","ref":"what_helps","title":"What helps most when that happens? Think of something a teammate or manager could actually do.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_personal11","ref":"work_with_me","title":"What''s one thing people should know about working with you?","required":false,"visibility":n