VALUES ('tpl_dietsurvey', 'diet-survey', 'Diet survey', 'Survey', 'Understand eating patterns, food choices and the practical barriers behind them.', 'Covers the diet someone follows, a week of typical eating in one grid, what drives their choices and what makes eating well harder. People who follow a particular diet are asked why, and everyone else skips straight past it.', '["market research","diet survey","eating habits survey","nutrition survey","food preferences","healthy eating"]', 'Utensils', 'content', 4, 11, '{"schemaVersion":9,"title":"Eating habits survey","description":"Understand eating patterns, food choices and the practical barriers behind them.","blocks":[{"id":"blk_dietsurv00","ref":"welcome","title":"Hi! This is a short survey about everyday eating habits. Answers are for general research, and nothing here is judged.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_dietsurv01","ref":"diet","title":"Do you follow a particular way of eating?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_no_particular_diet","label":"No particular diet","image_key":null},{"id":"opt_vegetarian","label":"Vegetarian","image_key":null},{"id":"opt_vegan","label":"Vegan","image_key":null},{"id":"opt_pescatarian","label":"Pescatarian","image_key":null},{"id":"opt_low_carb","label":"Low carb","image_key":null},{"id":"opt_gluten_free","label":"Gluten-free","image_key":null}],"allowOther":true},{"id":"blk_dietsurv02","ref":"diet_reason","title":"What are your main reasons for eating this way?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_general_health","label":"General health","image_key":null},{"id":"opt_a_medical_condition","label":"A medical condition or allergy","image_key":null},{"id":"opt_animal_welfare_or","label":"Animal welfare or the environment","image_key":null},{"id":"opt_religion_or_culture","label":"Religion or culture","image_key":null},{"id":"opt_managing_my_weight","label":"Managing my weight","image_key":null},{"id":"opt_cost","label":"Cost","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_dietsurv03","ref":"meals_per_day","title":"On a typical day, how many proper meals do you eat?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_one","label":"One","image_key":null},{"id":"opt_two","label":"Two","image_key":null},{"id":"opt_three","label":"Three","image_key":null},{"id":"opt_more_than_three","label":"More than three","image_key":null}],"allowOther":false},{"id":"blk_dietsurv04","ref":"food_frequency","title":"How often do you have each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_fruit","label":"Fruit"},{"id":"opt_row_vegetables","label":"Vegetables"},{"id":"opt_row_whole_grains","label":"Whole grains"},{"id":"opt_row_red_or","label":"Red or processed meat"},{"id":"opt_row_sugary_drinks","label":"Sugary drinks"},{"id":"opt_row_takeaway_or","label":"Takeaway or fast food"}],"columns":[{"id":"opt_col_rarely","label":"Rarely"},{"id":"opt_col_once_or","label":"Once or twice a week"},{"id":"opt_col_most_days","label":"Most days"},{"id":"opt_col_every_day","label":"Every day"}],"multiplePerRow":false},{"id":"blk_dietsurv05","ref":"snacking","title":"How often do you snack between meals?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_hardly_ever","label":"Hardly ever","image_key":null},{"id":"opt_once_a_day","label":"Once a day","image_key":null},{"id":"opt_several_times_a","label":"Several times a day","image_key":null},{"id":"opt_i_graze_more","label":"I graze more than I eat meals","image_key":null}],"allowOther":false},{"id":"blk_dietsurv06","ref":"home_cooking","title":"In a normal week, on how many days do you cook at home?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":8,"startAt":0,"labelLow":"Never","labelHigh":"Every day"},{"id":"blk_dietsurv07","ref":"influences","title":"Rank what most influences what you eat.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_taste","label":"Taste"},{"id":"opt_item_price","label":"Price"},{"id":"opt_item_health","label":"Health"},{"id":"opt_item_convenience","label":"Convenience"},{"id":"opt_item_time_to","label":"Time to prepare"},{"id":"opt_item_what_others","label":"What others in my home eat"}]},{"id":"blk_dietsurv08","ref":"satisfaction","title":"How happy are you with the way you eat right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_dietsurv09","ref":"barriers","title":"What makes it harder to eat the way you''d like?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_not_enough_time","label":"Not enough time","image_key":null},{"id":"opt_healthy_food_costs","label":"Healthy food costs more","image_key":null},{"id":"opt_not_confident_cooking","label":"Not confident cooking","image_key":null},{"id":"opt_long_or_irregular","label":"Long or irregular work hours","image_key":null},{"id":"opt_cravings_and_habits","label":"Cravings and habits","image_key":null},{"id":"opt_nothing_really_i","label":"Nothing really, I''m happy with it","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_dietsurv10","ref":"easier","title":"What one change would make eating well easier for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text"