VALUES ('tpl_facebooksurvey', 'facebook-survey', 'Facebook survey', 'Survey', 'Learn why people follow your Page or Group and what would get them more involved.', 'Short enough to finish from a link in a post. It asks how people found you, why they stay and which formats they want, then splits on how they take part: members who comment or post say what got them talking, and quiet readers say what holds them back.', '["market research","facebook survey","facebook group survey","social media survey","community feedback","audience research"]', 'ThumbsUp', 'content', 3, 10, '{"schemaVersion":9,"title":"Facebook audience survey","description":"Learn why people follow your Page or Group and what would get them more involved.","blocks":[{"id":"blk_facebook00","ref":"welcome","title":"Thanks for being part of our community on Facebook. We''d love to know what you want from it. It takes about two minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_facebook01","ref":"how_found","title":"How did you first find us on Facebook?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_friend_shared","label":"A friend shared or invited me","image_key":null},{"id":"opt_it_showed_up","label":"It showed up in my feed","image_key":null},{"id":"opt_i_searched_for","label":"I searched for it","image_key":null},{"id":"opt_from_our_website","label":"From our website or emails","image_key":null},{"id":"opt_from_an_ad","label":"From an ad","image_key":null}],"allowOther":true},{"id":"blk_facebook02","ref":"visit_frequency","title":"How often do you see or check our posts?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_a_few_times","label":"A few times a week","image_key":null},{"id":"opt_about_once_a","label":"About once a week","image_key":null},{"id":"opt_less_often_than","label":"Less often than that","image_key":null}],"allowOther":false},{"id":"blk_facebook03","ref":"reasons","title":"Why do you follow us? Pick up to three.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_useful_tips_and","label":"Useful tips and information","image_key":null},{"id":"opt_news_and_announcements","label":"News and announcements","image_key":null},{"id":"opt_offers_and_deals","label":"Offers and deals","image_key":null},{"id":"opt_talking_with_people","label":"Talking with people who share my interest","image_key":null},{"id":"opt_asking_questions_and","label":"Asking questions and getting help","image_key":null},{"id":"opt_it_s_just","label":"It''s just entertaining","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_facebook04","ref":"formats","title":"Rank the kinds of posts you''d most like to see.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_short_videos","label":"Short videos"},{"id":"opt_item_live_sessions","label":"Live sessions"},{"id":"opt_item_photos","label":"Photos"},{"id":"opt_item_how_to","label":"How-to posts"},{"id":"opt_item_questions_for","label":"Questions for the community"},{"id":"opt_item_updates_and","label":"Updates and announcements"}]},{"id":"blk_facebook05","ref":"participation","title":"Which best describes how you take part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_mostly_read","label":"I mostly read","image_key":null},{"id":"opt_i_react_or","label":"I react or share","image_key":null},{"id":"opt_i_comment","label":"I comment","image_key":null},{"id":"opt_i_post_my","label":"I post my own things","image_key":null}],"allowOther":false},{"id":"blk_facebook06","ref":"best_post","title":"Think of a post or discussion that got you to join in. What made it worth responding to?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_facebook07","ref":"reader_barriers","title":"What usually stops you from commenting or posting?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_i_m_happy","label":"I''m happy just reading","image_key":null},{"id":"opt_i_m_not","label":"I''m not sure my question is welcome","image_key":null},{"id":"opt_i_don_t","label":"I don''t have time","image_key":null},{"id":"opt_i_prefer_to","label":"I prefer to keep my activity private","image_key":null},{"id":"opt_the_discussions_don","label":"The discussions don''t feel relevant to me","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_facebook08","ref":"usefulness","title":"How useful are our posts to you overall?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_facebook09","ref":"more_less","title":"What would you like to see more of, or less of?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_facebook10","ref":"recommend","title":"How likely are you to recommend our Page or Group to a friend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"}],"endings":[{"id":"end_facebook01","ref":"end_thanks","title":"Thanks, we''ll put this to good use 👍","bodyMd":"We''ll share what we heard, and what we''re changing, in a post soon.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_facebook01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"best_post","target":"usefulness","targetKind":"block"},{"id":"rl_facebook02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"participation"},"op":"eq","value":"opt_i_mostly_read"}],"groups":[]},"from":"participation","target":"reader_barriers","targetKind":"block","branch":"true"},{"id":"rl_facebook03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"participation"},"op":"eq","value":"opt_i_react_or"}],"groups":[]},"from":"participation","target":"best_post","targetKind":"block","branch":"true"},{"id":"rl_facebook04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"participation"},"op":"eq","value":"opt_i_comment"}],"groups":[]},"from":"participation","target":"best_post","targetKind":"block","branch":"true"},{"id":"rl_facebook05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"participation"},"op":"eq","value":"opt_i_post_my"}],"groups":[]},"from":"participation","target":"best_post","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffdce8","surface":"#ffffff","text":"#3d1424","accent":"#be185d","accentText":"#fff7fa","botBubble":"#ffffff","userBubble":"#be185d","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"scallops","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
