VALUES ('tpl_insurancequestionnaire', 'insurance-questionnaire', 'Insurance questionnaire', 'Survey', 'Collect needs, current cover and priorities before an insurance review call.', 'Asks personal and business clients different questions, so a family never sees a question about employees. Anyone already insured is asked for their current provider and renewal date, and people who need cover within a week land on their own ending so the team can call them first.', '["market research","insurance questionnaire","insurance needs assessment","insurance intake","insurance agent","lead qualification"]', 'ShieldCheck', 'content', 4, 15, '{"schemaVersion":9,"title":"Insurance needs questionnaire","description":"Collect needs, current cover and priorities before an insurance review call.","blocks":[{"id":"blk_insuranc00","ref":"welcome","title":"Hi! A few questions so our adviser understands what you need before you talk. It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_insuranc01","ref":"cover_for","title":"Who is the cover for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_me_or_my","label":"Me or my family","image_key":null},{"id":"opt_my_business","label":"My business","image_key":null}],"allowOther":false},{"id":"blk_insuranc02","ref":"personal_types","title":"Which kinds of cover would you like to talk about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_health","label":"Health","image_key":null},{"id":"opt_life","label":"Life","image_key":null},{"id":"opt_home_or_renters","label":"Home or renters","image_key":null},{"id":"opt_car","label":"Car","image_key":null},{"id":"opt_travel","label":"Travel","image_key":null},{"id":"opt_income_protection","label":"Income protection","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_insuranc03","ref":"household","title":"Who is in your household?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_me_and_a","label":"Me and a partner","image_key":null},{"id":"opt_me_a_partner","label":"Me, a partner and children","image_key":null},{"id":"opt_me_and_children","label":"Me and children","image_key":null},{"id":"opt_other_family_members","label":"Other family members too","image_key":null}]},{"id":"blk_insuranc04","ref":"life_event","title":"Has anything changed recently that prompted this?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_bought_or_moved","label":"Bought or moved home","image_key":null},{"id":"opt_new_baby_or","label":"New baby or child","image_key":null},{"id":"opt_married_or_moved","label":"Married or moved in together","image_key":null},{"id":"opt_new_car","label":"New car","image_key":null},{"id":"opt_changed_job_or","label":"Changed job or retired","image_key":null},{"id":"opt_nothing_in_particular","label":"Nothing in particular","image_key":null}],"allowOther":true},{"id":"blk_insuranc05","ref":"business_type","title":"What does your business do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_insuranc06","ref":"employees","title":"How many people work in the business, including you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"integerOnly":true},{"id":"blk_insuranc07","ref":"business_types","title":"Which kinds of business cover would you like to talk about?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_general_liability","label":"General liability","image_key":null},{"id":"opt_professional_indemnity","label":"Professional indemnity","image_key":null},{"id":"opt_property_and_equipment","label":"Property and equipment","image_key":null},{"id":"opt_commercial_vehicles","label":"Commercial vehicles","image_key":null},{"id":"opt_employee_health_or","label":"Employee health or benefits","image_key":null},{"id":"opt_cyber","label":"Cyber","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_insuranc08","ref":"currently_insured","title":"Do you have any of this cover already?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_insuranc09","ref":"current_cover","title":"Who is it with, and what does it cover? A rough description is fine.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_insuranc10","ref":"renewal_date","title":"When does your current policy renew or end?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_insuranc11","ref":"priorities","title":"Rank what matters most to you in a policy.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_a_lower","label":"A lower premium"},{"id":"opt_item_broader_cover","label":"Broader cover"},{"id":"opt_item_a_lower_2","label":"A lower excess or deductible"},{"id":"opt_item_fast_simple","label":"Fast, simple claims"},{"id":"opt_item_everything_with","label":"Everything with one provider"}]},{"id":"blk_insuranc12","ref":"anything_else","title":"Is there anything else the adviser should know before you talk?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_insuranc13","ref":"contact","title":"How can the adviser reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_insuranc14","ref":"consent","title":"Before you send this","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I agree that you may use these answers to contact me about insurance cover. I understand this questionnaire is not a quote or an offer of cover.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"},{"id":"blk_insuranc15","ref":"timeline","title":"Last one: how soon do you need cover in place?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_within_a_week","label":"Within a week","image_key":null},{"id":"opt_within_a_month","label":"Within a month","image_key":null},{"id":"opt_in_the_next","label":"In the next few months","image_key":null},{"id":"opt_i_m_just","label":"I''m just reviewing my options","image_key":null}],"allowOther":false}],"endings":[{"id":"end_insuranc01","ref":"end_thanks","title":"Thanks, we have everything we need","bodyMd":"An adviser will review your answers and get in touch to arrange a conversation.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_insuranc02","ref":"end_urgent","title":"Got it, we''ll call you first ⏱️","bodyMd":"You need cover soon, so an adviser will contact you as early as possible. Keep your current policy details to hand if you have them.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_insuranc01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"life_event","target":"currently_insured","targetKind":"block"},{"id":"rl_insuranc02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cover_for"},"op":"eq","value":"opt_me_or_my"}],"groups":[]},"from":"cover_for","target":"personal_types","targetKind":"block","branch":"true"},{"id":"rl_insuranc03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cover_for"},"op":"eq","value":"opt_my_business"}],"groups":[]},"from":"cover_for","target":"business_type","targetKind":"block","branch":"true"},{"id":"rl_insuranc04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"currently_insured"},"op":"eq","value":true}],"groups":[]},"from":"currently_insured","target":"current_cover","targetKind":"block","branch":"true"},{"id":"rl_insuranc05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"currently_insured"},"op":"eq","value":false}],"groups":[]},"from":"currently_insured","target":"priorities","targetKind":"block","branch":"true"},{"id":"rl_insuranc06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"timeline"},"op":"eq","value":"opt_within_a_week"}],"groups":[]},"from":"timeline","target":"end_urgent","targetKind":"ending","branch":"true"},{"id":"rl_insuranc07","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"renewal_date","target":"anything_else","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":"