INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_customerlosssurvey', 'customer-loss-survey', 'Customer loss survey', 'Survey', 'Learn what changed for a customer who stopped buying, and how you compare with where they went.', 'For customers who drifted away rather than formally cancelling, such as a client who stopped reordering or a regular who stopped coming in. It asks what changed and whether they ever told you, which shows how many losses you could have seen coming. Price leavers get a pricing question, people who moved elsewhere compare you side by side, and anyone open to a conversation reaches an ending that promises a call.', '["marketing","customer loss survey","lost customer survey","lapsed customer survey","win back customers","why customers stop buying"]', 'DoorOpen', 'choice', 4, 12, '{"schemaVersion":9,"title":"Lost customer survey","description":"Learn what changed for a customer who stopped buying, and how you compare with where they went.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"We noticed we haven''t seen you in a while. Would you tell us what changed? It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"customer_since","title":"How long were you buying from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_less_than_3","label":"Less than 3 months","image_key":null},{"id":"opt_3_to_12","label":"3 to 12 months","image_key":null},{"id":"opt_1_to_3","label":"1 to 3 years","image_key":null},{"id":"opt_more_than_3","label":"More than 3 years","image_key":null}]},{"id":"blk_customer02","ref":"last_bought","title":"Roughly when did you last buy from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_the_last","label":"In the last 3 months","image_key":null},{"id":"opt_3_to_6","label":"3 to 6 months ago","image_key":null},{"id":"opt_6_to_12","label":"6 to 12 months ago","image_key":null},{"id":"opt_more_than_a","label":"More than a year ago","image_key":null}],"allowOther":false},{"id":"blk_customer03","ref":"main_reason","title":"What changed that made you stop?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_price","label":"The price","image_key":null},{"id":"opt_something_i_needed","label":"Something I needed was missing","image_key":null},{"id":"opt_quality_or_reliability","label":"Quality or reliability slipped","image_key":null},{"id":"opt_service_let_me","label":"Service let me down","image_key":null},{"id":"opt_somewhere_else_became","label":"Somewhere else became more convenient","image_key":null},{"id":"opt_my_needs_changed","label":"My needs changed","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_customer04","ref":"price_view","title":"Compared with what else is out there, how did our price feel?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_much_too_high","label":"Much too high","image_key":null},{"id":"opt_a_bit_high","label":"A bit high","image_key":null},{"id":"opt_fair_but_i","label":"Fair, but I couldn''t justify it any more","image_key":null},{"id":"opt_fair_the_budget","label":"Fair, the budget just went away","image_key":null}],"allowOther":false},{"id":"blk_customer05","ref":"reason_detail","title":"When did you first notice it, and what happened?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_customer06","ref":"told_us","title":"Did you mention any of this to us before you stopped?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_customer07","ref":"moved_to","title":"Where do you get this now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_from_another_business","label":"From another business","image_key":null},{"id":"opt_we_do_it","label":"We do it ourselves now","image_key":null},{"id":"opt_nowhere_we_stopped","label":"Nowhere, we stopped needing it","image_key":null},{"id":"opt_still_deciding","label":"Still deciding","image_key":null}],"allowOther":false},{"id":"blk_customer08","ref":"compare","title":"How does the business you use now compare with us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_price","label":"Price"},{"id":"opt_row_quality","label":"Quality"},{"id":"opt_row_convenience","label":"Convenience"},{"id":"opt_row_service","label":"Service"},{"id":"opt_row_range_on","label":"Range on offer"}],"columns":[{"id":"opt_col_they_re","label":"They''re worse"},{"id":"opt_col_about_the","label":"About the same"},{"id":"opt_col_they_re_2","label":"They''re better"}],"multiplePerRow":false},{"id":"blk_customer09","ref":"experience","title":"Before things changed, how happy were you with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_customer10","ref":"bring_back","title":"What would we need to change for you to buy from us again?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_customer11","ref":"contact_ok","title":"Would you be open to a short call about your experience?","description":"No sales pitch. We just want to understand it properly.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_customer12","ref":"contact_email","title":"Great, what''s the best email to reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"Thank you for being honest with us","bodyMd":"We read every answer, and it goes to the people who look after the part of the experience you mentioned.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_customer02","ref":"end_call","title":"Thanks, we''ll be in touch 📞","bodyMd":"Someone from the team will email you to find a time that suits you. It will be a conversation, not a pitch.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"contact_email","target":"end_call","targetKind":"ending"},{"id":"rl_customer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"main_reason"},"op":"eq","value":"opt_the_price"}],"groups":[]},"from":"main_reason","target":"price_view","targetKind":"block","branch":"true"},{"id":"rl_customer03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"main_reason"},"op":"eq","value":"opt_something_i_needed"}],"groups":[]},"from":"main_reason","target":"reason_detail","targetKind":"block","branch":"true"},{"id":"rl_customer04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"main_reason"},"op":"eq","value":"opt_quality_or_reliability"}],"groups":[]},"from":"main_reason","target":"reason_detail","targetKind":"block","branch":"true"},{"id":"rl_customer05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"main_reason"},"op":"eq","value":"opt_service_let_me"}],"groups":[]},"from":"main_reason","target":"reason_detail","targetKind":"block","branch":"true"},{"id":"rl_customer06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"main_reason"},"op":"eq","value":"opt_somewhere_else_became"}],"groups":[]},"from":"main_reason","target":"reason_detail","targetKind":"block","branch":"true"},{"id":"rl_customer07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"main_reason"},"op":"eq","value":"opt_my_needs_changed"}],"groups":[]},"from":"main_reason","target":"reason_detail","targetKind":"block","branch":"true"},{"id":"rl_customer08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"main_reason"},"op":"eq","value":"opt_something_else"}],"groups":[]},"from":"main_reason","target":"reason_detail","targetKind":"block","branch":"true"},{"id":"rl_customer09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"moved_to"},"op":"eq","value":"opt_from_another_business"}],"groups":[]},"from":"moved_to","target":"compare","targetKind":"block","branch":"true"},{"id":"rl_customer10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"moved_to"},"op":"eq","value":"opt_we_do_it"}],"groups":[]},"from":"moved_to","target":"experience","targetKind":"block","branch":"true"},{"id":"rl_customer11","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"moved_to"},"op":"eq","value":"opt_nowhere_we_stopped"}],"groups":[]},"from":"moved_to","target":"experience","targetKind":"block","branch":"true"},{"id":"rl_customer12","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"moved_to"},"op":"eq","value":"opt_still_deciding"}],"groups":[]},"from":"moved_to","target":"experience","targetKind":"block","branch":"true"},{"id":"rl_customer13","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"contact_ok"},"op":"eq","value":false}],"groups":[]},"from":"contact_ok","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","