VALUES ('tpl_customerretentionsurvey', 'customer-retention-survey', 'Customer retention survey', 'Survey', 'Ask current customers what keeps them with you and what could change their mind.', 'Built for customers who are still with you, which is when their answers are most useful. It measures the value they get and why they stay, then asks one direct question: has anything come close to making you leave? Those who say yes are asked what happened and what you should fix first, and everyone says whether they expect to still be a customer a year from now, so at-risk accounts surface before they cancel.', '["marketing","customer retention survey","renewal survey","at-risk customers","why customers stay","retention questions"]', 'HeartHandshake', 'choice', 3, 10, '{"schemaVersion":9,"title":"Customer retention survey","description":"Ask current customers what keeps them with you and what could change their mind.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"You''ve been with us a while, and we''d like to keep earning that. Mind answering a few questions?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"tenure","title":"How long have you been a customer?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_less_than_6","label":"Less than 6 months","image_key":null},{"id":"opt_6_to_12","label":"6 to 12 months","image_key":null},{"id":"opt_1_to_2","label":"1 to 2 years","image_key":null},{"id":"opt_more_than_2","label":"More than 2 years","image_key":null}]},{"id":"blk_customer02","ref":"usage","title":"How often do you use us these days?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_daily","label":"Daily","image_key":null},{"id":"opt_a_few_times","label":"A few times a week","image_key":null},{"id":"opt_a_few_times_2","label":"A few times a month","image_key":null},{"id":"opt_rarely","label":"Rarely","image_key":null}],"allowOther":false},{"id":"blk_customer03","ref":"value","title":"How much value do you get for what you pay?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Very little","labelHigh":"A great deal"},{"id":"blk_customer04","ref":"why_stay","title":"What keeps you with us? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_it_does_the","label":"It does the job well","image_key":null},{"id":"opt_good_value_for","label":"Good value for money","image_key":null},{"id":"opt_helpful_support","label":"Helpful support","image_key":null},{"id":"opt_it_fits_how","label":"It fits how we already work","image_key":null},{"id":"opt_switching_would_be","label":"Switching would be a hassle","image_key":null},{"id":"opt_i_trust_the","label":"I trust the company","image_key":null}],"minSelections":1,"maxSelections":4,"allowOther":true},{"id":"blk_customer05","ref":"aspects","title":"How are we doing on each of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_quality","label":"Quality"},{"id":"opt_row_reliability","label":"Reliability"},{"id":"opt_row_support","label":"Support"},{"id":"opt_row_keeping_you","label":"Keeping you informed"},{"id":"opt_row_price","label":"Price"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_customer06","ref":"considered_leaving","title":"Has anything ever come close to making you leave us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_customer07","ref":"leaving_trigger","title":"What happened?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_customer08","ref":"fix_first","title":"If we could fix one thing first, what should it be?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_price","label":"The price","image_key":null},{"id":"opt_a_missing_feature","label":"A missing feature or service","image_key":null},{"id":"opt_reliability","label":"Reliability","image_key":null},{"id":"opt_response_times_from","label":"Response times from support","image_key":null},{"id":"opt_how_we_communicate","label":"How we communicate changes","image_key":null}],"allowOther":true},{"id":"blk_customer09","ref":"one_improvement","title":"What''s one improvement that would make you even more likely to stay?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_customer10","ref":"stay_next_year","title":"A year from now, do you expect to still be a customer?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_definitely","label":"Definitely","image_key":null},{"id":"opt_probably","label":"Probably","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null},{"id":"opt_probably_not","label":"Probably not","image_key":null}],"allowOther":false}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"Thank you for sticking with us","bodyMd":"Your answers go straight to the team, and we''ll share what we change because of them.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"considered_leaving"},"op":"eq","value":false}],"groups":[]},"from":"considered_leaving","target":"one_improvement","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f3e6ff","surface":"#ffffff","text":"#2b1638","accent":"#9333ea","accentText":"#fdf9ff","botBubble":"#ffffff","userBubble":"#9333ea","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"confetti","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
