VALUES ('tpl_foodsurvey', 'food-survey', 'Food survey', 'Survey', 'Learn what people like to eat, what they avoid and what they value when choosing food.', 'A food preferences survey for restaurants, caterers and food brands. It starts with diets and allergies, asking for details only from people who have an allergy, then covers cuisines, spice, eating-out habits and what matters most in a meal, finishing with the dish people wish they could find.', '["marketing","food survey","food preferences survey","menu planning survey","dietary requirements","restaurant survey"]', 'Utensils', 'choice', 3, 10, '{"schemaVersion":9,"title":"Food preferences survey","description":"Learn what people like to eat, what they avoid and what they value when choosing food.","blocks":[{"id":"blk_foodsurv00","ref":"welcome","title":"Hungry for a quick chat? We''d love to hear what you like to eat.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_foodsurv01","ref":"diet","title":"Do you follow any of these diets?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_no_particular_diet","label":"No particular diet","image_key":null},{"id":"opt_vegetarian","label":"Vegetarian","image_key":null},{"id":"opt_vegan","label":"Vegan","image_key":null},{"id":"opt_pescatarian","label":"Pescatarian","image_key":null},{"id":"opt_halal","label":"Halal","image_key":null},{"id":"opt_kosher","label":"Kosher","image_key":null},{"id":"opt_gluten_free","label":"Gluten-free","image_key":null},{"id":"opt_low_carb","label":"Low-carb","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":true},{"id":"blk_foodsurv02","ref":"has_allergy","title":"Do you have any food allergies or intolerances?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_foodsurv03"