VALUES ('tpl_magazinereadersurvey', 'magazine-reader-survey', 'Magazine reader survey', 'Survey', 'Find out which sections readers value, which they skip and what would make them stay.', 'A reader survey for print and digital magazines. It covers format, reading habits and a section-by-section grid, then splits on the overall rating: readers who love it name the piece that stayed with them, and readers who do not are asked what disappoints them. It closes by asking whether they plan to keep reading.', '["marketing","magazine reader survey","reader survey","publication feedback","readership survey","editorial feedback"]', 'BookOpen', 'choice', 3, 10, '{"schemaVersion":9,"title":"Magazine reader survey","description":"Find out which sections readers value, which they skip and what would make them stay.","blocks":[{"id":"blk_magazine00","ref":"welcome","title":"Thanks for reading us. We''d like to know what you love, what you skip and what''s missing.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_magazine01","ref":"format","title":"How do you usually read the magazine?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_print","label":"In print","image_key":null},{"id":"opt_on_our_website","label":"On our website","image_key":null},{"id":"opt_in_the_app","label":"In the app or as a digital edition","image_key":null},{"id":"opt_a_mix_of","label":"A mix of these","image_key":null}],"allowOther":false},{"id":"blk_magazine02","ref":"reader_since","title":"How long have you been reading us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_this_is_one","label":"This is one of my first issues","image_key":null},{"id":"opt_less_than_a","label":"Less than a year","image_key":null},{"id":"opt_1_to_3","label":"1 to 3 years","image_key":null},{"id":"opt_more_than_3","label":"More than 3 years","image_key":null}]},{"id":"blk_magazine03","ref":"how_much","title":"How much of an issue do you usually read?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_nearly_all_of","label":"Nearly all of it","image_key":null},{"id":"opt_about_half","label":"About half","image_key":null},{"id":"opt_a_few_pieces","label":"A few pieces that catch my eye","image_key":null},{"id":"opt_very_little","label":"Very little","image_key":null}],"allowOther":false},{"id":"blk_magazine04","ref":"sections","title":"How often do you read each section?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_news_and","label":"News and short reads"},{"id":"opt_row_long_features","label":"Long features"},{"id":"opt_row_interviews","label":"Interviews"},{"id":"opt_row_reviews","label":"Reviews"},{"id":"opt_row_how_to","label":"How-to guides"},{"id":"opt_row_opinion_columns","label":"Opinion columns"}],"columns":[{"id":"opt_col_always","label":"Always"},{"id":"opt_col_sometimes","label":"Sometimes"},{"id":"opt_col_rarely","label":"Rarely"},{"id":"opt_col_skip_it","label":"Skip it"}],"multiplePerRow":false},{"id":"blk_magazine05","ref":"more_of","title":"Which topics would you like to see more of?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_practical_advice","label":"Practical advice","image_key":null},{"id":"opt_in_depth_investigations","label":"In-depth investigations","image_key":null},{"id":"opt_people_and_profiles","label":"People and profiles","image_key":null},{"id":"opt_trends_and_what","label":"Trends and what''s next","image_key":null},{"id":"opt_local_stories","label":"Local stories","image_key":null},{"id":"opt_reader_contributions","label":"Reader contributions","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_magazine06","ref":"overall","title":"Overall, how would you rate the magazine right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_magazine07","ref":"favourite_piece","title":"Which recent piece stayed with you, and why?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_magazine08","ref":"disappoints","title":"What''s letting the magazine down for you at the moment?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_magazine09","ref":"keep_reading","title":"How likely are you to keep reading over the next year?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_definitely","label":"Definitely","image_key":null},{"id":"opt_probably","label":"Probably","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null},{"id":"opt_probably_not","label":"Probably not","image_key":null}],"allowOther":false},{"id":"blk_magazine10","ref":"one_change","title":"If you were editor for a day, what''s the one thing you''d change?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300}],"endings":[{"id":"end_magazine01","ref":"end_thanks","title":"Thank you, the editors will read this 📖","bodyMd":"Reader answers go straight into planning the next issues.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_magazine01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"favourite_piece","target":"keep_reading","targetKind":"block"},{"id":"rl_magazine02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"lte","value":3}],"groups":[]},"from":"overall","target":"disappoints","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
