VALUES ('tpl_marketsegmentationsurvey', 'market-segmentation-survey', 'Market segmentation survey', 'Survey', 'Find meaningful groups in your audience based on needs and behaviour.', 'Segments built only on age or job title rarely predict what people buy. This survey asks about needs first: the problem, how often it happens, what people use today and how they choose, with background questions saved for the end. People already using something rate it, and people using nothing are asked why, which often reveals a segment of its own.', '["marketing","market segmentation survey","customer segmentation","needs-based segmentation","audience research","buyer personas"]', 'PieChart', 'choice', 3, 11, '{"schemaVersion":9,"title":"Market segmentation survey","description":"Find meaningful groups in your audience based on needs and behaviour.","blocks":[{"id":"blk_marketse00","ref":"welcome","title":"Hi! We''re trying to understand the different kinds of people we could help. This takes about four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_marketse01","ref":"main_goal","title":"Rank these goals by how important they are to you right now.","description":"Replace these with the goals your product or service helps with.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_saving_time","label":"Saving time"},{"id":"opt_item_saving_money","label":"Saving money"},{"id":"opt_item_getting_better","label":"Getting better results"},{"id":"opt_item_reducing_stress","label":"Reducing stress"},{"id":"opt_item_learning_something","label":"Learning something new"}]},{"id":"blk_marketse02","ref":"problem_frequency","title":"How often do you run into the problem you''d most like solved?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_every_week","label":"Every week","image_key":null},{"id":"opt_every_month_or","label":"Every month or so","image_key":null},{"id":"opt_rarely","label":"Rarely","image_key":null}],"allowOther":false},{"id":"blk_marketse03","ref":"current_solution","title":"How do you deal with it today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_paid_product","label":"A paid product or service","image_key":null},{"id":"opt_a_free_tool","label":"A free tool or app","image_key":null},{"id":"opt_spreadsheets_or_my","label":"Spreadsheets or my own system","image_key":null},{"id":"opt_someone_else_does","label":"Someone else does it for me","image_key":null},{"id":"opt_nothing_i_manage","label":"Nothing, I manage without","image_key":null}],"allowOther":false},{"id":"blk_marketse04","ref":"current_satisfaction","title":"How well does that work for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_marketse05","ref":"why_nothing","title":"What''s stopped you from using something for it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_marketse06","ref":"how_choose","title":"When you buy something like this, which sounds most like you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_research_a","label":"I research a lot and compare options","image_key":null},{"id":"opt_i_go_with","label":"I go with what people I trust recommend","image_key":null},{"id":"opt_i_pick_the","label":"I pick the cheapest that does the job","image_key":null},{"id":"opt_i_pay_more","label":"I pay more for the best quality","image_key":null},{"id":"opt_i_buy_quickly","label":"I buy quickly and switch if it doesn''t work","image_key":null}],"allowOther":false},{"id":"blk_marketse07","ref":"attitudes","title":"How much do you agree with each statement?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_i_like","label":"I like trying new products early"},{"id":"opt_row_i_d","label":"I''d pay more to save time"},{"id":"opt_row_i_prefer","label":"I prefer to do things myself"},{"id":"opt_row_price_is","label":"Price is usually the deciding factor"}],"columns":[{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_neutral","label":"Neutral"},{"id":"opt_col_agree","label":"Agree"}],"multiplePerRow":false},{"id":"blk_marketse08","ref":"willingness","title":"How much would a better solution be worth to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not much","labelHigh":"A lot"},{"id":"blk_marketse09","ref":"age_range","title":"A little background: which age group are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_18_to_24","label":"18 to 24","image_key":null},{"id":"opt_25_to_34","label":"25 to 34","image_key":null},{"id":"opt_35_to_44","label":"35 to 44","image_key":null},{"id":"opt_45_to_54","label":"45 to 54","image_key":null},{"id":"opt_55_to_64","label":"55 to 64","image_key":null},{"id":"opt_65_or_over","label":"65 or over","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}]},{"id":"blk_marketse10","ref":"situation","title":"Which best describes your situation?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_employed","label":"Employed","image_key":null},{"id":"opt_self_employed_or","label":"Self-employed or running a business","image_key":null},{"id":"opt_student","label":"Student","image_key":null},{"id":"opt_not_working_right","label":"Not working right now","image_key":null},{"id":"opt_retired","label":"Retired","image_key":null}],"allowOther":false},{"id":"blk_marketse11","ref":"region","title":"Which country or region do you live in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":100}],"endings":[{"id":"end_marketse01","ref":"end_thanks","title":"Thank you, this really helps","bodyMd":"Your answers are combined with everyone else''s, and never shared in a way that identifies you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_marketse01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"current_satisfaction","target":"how_choose","targetKind":"block"},{"id":"rl_marketse02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"current_solution"},"op":"eq","value":"opt_nothing_i_manage"}],"groups":[]},"from":"current_solution","target":"why_nothing","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
