INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_mediausagesurvey', 'media-usage-survey', 'Media usage survey', 'Survey', 'Learn where your audience gets news and entertainment, and why they choose each channel.', 'Useful for planning where to advertise, publish or partner. It maps which channels people use and how often, why they turn to media at all and which sources they trust, then asks whether they pay for any subscriptions, with a follow-up only for those who do.', '["marketing","media usage survey","media consumption survey","media habits","audience research","channel planning"]', 'MonitorPlay', 'choice', 3, 10, '{"schemaVersion":9,"title":"Media habits survey","description":"Learn where your audience gets news and entertainment, and why they choose each channel.","blocks":[{"id":"blk_mediausa00","ref":"welcome","title":"Hi! We''re curious how you keep up with news and entertainment. A few quick questions.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_mediausa01","ref":"channel_frequency","title":"How often do you use each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_social_media","label":"Social media"},{"id":"opt_row_video_streaming","label":"Video streaming services"},{"id":"opt_row_youtube_or","label":"YouTube or other online video"},{"id":"opt_row_podcasts","label":"Podcasts"},{"id":"opt_row_radio","label":"Radio"},{"id":"opt_row_tv","label":"TV"},{"id":"opt_row_news_websites","label":"News websites or apps"},{"id":"opt_row_email_newsletters","label":"Email newsletters"},{"id":"opt_row_printed_newspapers","label":"Printed newspapers or magazines"}],"columns":[{"id":"opt_col_daily","label":"Daily"},{"id":"opt_col_weekly","label":"Weekly"},{"id":"opt_col_rarely","label":"Rarely"},{"id":"opt_col_never","label":"Never"}],"multiplePerRow":false},{"id":"blk_mediausa02","ref":"daily_time","title":"On a typical day, how much time do you spend with media of any kind?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_1","label":"Less than 1 hour","image_key":null},{"id":"opt_1_to_3","label":"1 to 3 hours","image_key":null},{"id":"opt_3_to_5","label":"3 to 5 hours","image_key":null},{"id":"opt_more_than_5","label":"More than 5 hours","image_key":null}],"allowOther":false},{"id":"blk_mediausa03","ref":"reasons","title":"Rank why you turn to media, most important first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_staying_informed","label":"Staying informed"},{"id":"opt_item_entertainment","label":"Entertainment"},{"id":"opt_item_learning_something","label":"Learning something"},{"id":"opt_item_relaxing","label":"Relaxing"},{"id":"opt_item_keeping_up","label":"Keeping up with friends"},{"id":"opt_item_work","label":"Work"}]},{"id":"blk_mediausa04","ref":"news_source","title":"Where do you get most of your news?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_news_websites_or","label":"News websites or apps","image_key":null},{"id":"opt_tv","label":"TV","image_key":null},{"id":"opt_radio","label":"Radio","image_key":null},{"id":"opt_podcasts","label":"Podcasts","image_key":null},{"id":"opt_newsletters","label":"Newsletters","image_key":null},{"id":"opt_print","label":"Print","image_key":null},{"id":"opt_friends_and_family","label":"Friends and family","image_key":null},{"id":"opt_i_don_t","label":"I don''t really follow the news","image_key":null}]},{"id":"blk_mediausa05","ref":"trust","title":"How much do you trust the news you come across online?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_mediausa06","ref":"devices","title":"Which devices do you use for media most?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_phone","label":"Phone","image_key":null},{"id":"opt_laptop_or_computer","label":"Laptop or computer","image_key":null},{"id":"opt_tablet","label":"Tablet","image_key":null},{"id":"opt_tv","label":"TV","image_key":null},{"id":"opt_smart_speaker","label":"Smart speaker","image_key":null},{"id":"opt_car_radio","label":"Car radio","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":false},{"id":"blk_mediausa07","ref":"pays","title":"Do you pay for any media subscriptions right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_mediausa08","ref":"paid_for","title":"Which kinds?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_video_streaming","label":"Video streaming","image_key":null},{"id":"opt_music_streaming","label":"Music streaming","image_key":null},{"id":"opt_news","label":"News","image_key":null},{"id":"opt_magazines","label":"Magazines","image_key":null},{"id":"opt_podcasts_or_audiobooks","label":"Podcasts or audiobooks","image_key":null},{"id":"opt_a_creator_i","label":"A creator I follow","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_mediausa09","ref":"ads","title":"Which sounds closest to how you feel about ads?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_fine_if_they","label":"Fine if they''re relevant","image_key":null},{"id":"opt_i_tolerate_them","label":"I tolerate them for free content","image_key":null},{"id":"opt_i_avoid_them","label":"I avoid them whenever I can","image_key":null},{"id":"opt_i_d_pay","label":"I''d pay to never see them","image_key":null}],"allowOther":false},{"id":"blk_mediausa10","ref":"discovered","title":"What''s the last show, podcast, channel or publication you discovered, and how did you find it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false}],"endings":[{"id":"end_mediausa01","ref":"end_thanks","title":"Thanks for sharing your habits","bodyMd":"Your answers help us decide where and how to reach people like you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_mediausa01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"pays"},"op":"eq","value":false}],"groups":[]},"from":"pays","target":"ads","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
