VALUES ('tpl_meetingfeedbacksurvey', 'meeting-feedback-survey', 'Meeting feedback survey', 'Survey', 'Find out whether a meeting was worth it and what would make the next one better.', 'A short check to send right after a meeting. It rates purpose, participation, timekeeping and decisions in one grid, then asks whether it was worth the time: anyone who says no is asked how it could have worked better. Anyone unsure of the next steps is asked what is unclear, so it can be fixed before work stalls.', '["marketing","meeting feedback survey","meeting effectiveness","post-meeting survey","team meetings","meeting evaluation"]', 'MessagesSquare', 'choice', 3, 8, '{"schemaVersion":9,"title":"Meeting feedback","description":"Find out whether a meeting was worth it and what would make the next one better.","blocks":[{"id":"blk_meetingf00","ref":"welcome","title":"Thanks for joining the meeting. Two minutes to help make the next one better?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_meetingf01","ref":"meeting","title":"Which meeting are you giving feedback on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_meetingf02","ref":"your_role","title":"What was your part in it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_ran_it","label":"I ran it","image_key":null},{"id":"opt_i_presented","label":"I presented","image_key":null},{"id":"opt_i_took_part","label":"I took part","image_key":null},{"id":"opt_i_mostly_listened","label":"I mostly listened","image_key":null}],"allowOther":false},{"id":"blk_meetingf03","ref":"aspects","title":"How did the meeting do on each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_clear_purpose","label":"Clear purpose"},{"id":"opt_row_the_right","label":"The right people were there"},{"id":"opt_row_started_and","label":"Started and ended on time"},{"id":"opt_row_everyone_could","label":"Everyone could speak"},{"id":"opt_row_decisions_were","label":"Decisions were made"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"}],"multiplePerRow":false},{"id":"blk_meetingf04","ref":"worth_time","title":"Was the meeting worth your time?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_meetingf05","ref":"better_format","title":"What would have worked better?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_an_email_or","label":"An email or written update","image_key":null},{"id":"opt_a_shorter_meeting","label":"A shorter meeting","image_key":null},{"id":"opt_fewer_people","label":"Fewer people","image_key":null},{"id":"opt_a_clearer_agenda","label":"A clearer agenda sent beforehand","image_key":null},{"id":"opt_i_didn_t","label":"I didn''t need to be there","image_key":null}],"allowOther":true},{"id":"blk_meetingf06","ref":"next_steps_clear","title":"Do you know what you need to do next as a result?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_meetingf07","ref":"unclear","title":"What''s unclear about the next steps?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_meetingf08","ref":"one_change","title":"What''s one thing that would make the next meeting better?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false}],"endings":[{"id":"end_meetingf01","ref":"end_thanks","title":"Thanks, noted for next time","bodyMd":"The organiser will see your answers and follow up on anything that''s unclear.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_meetingf01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"worth_time"},"op":"gte","value":3}],"groups":[]},"from":"worth_time","target":"next_steps_clear","targetKind":"block","branch":"true"},{"id":"rl_meetingf02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"next_steps_clear"},"op":"eq","value":true}],"groups":[]},"from":"next_steps_clear","target":"one_change","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
