VALUES ('tpl_mysteryshoppersurvey', 'mystery-shopper-survey', 'Mystery shopper survey', 'Survey', 'Give mystery shoppers a clear, factual way to report each visit.', 'Written for the shopper to fill in straight after a visit, with questions that ask what happened rather than how it felt. In-store visits get a question about the shop''s condition that phone and online visits skip, and a missing item prompts a follow-up about what was offered instead. Photos of receipts or displays can be attached as evidence.', '["marketing","mystery shopper survey","mystery shopping form","store audit","customer experience audit","retail evaluation"]', 'Search', 'choice', 4, 13, '{"schemaVersion":9,"title":"Mystery shopper report","description":"Give mystery shoppers a clear, factual way to report each visit.","blocks":[{"id":"blk_mysterys00","ref":"welcome","title":"Thanks for completing this visit. Please fill this in as soon as you can, while the details are fresh.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_mysterys01","ref":"shopper","title":"Your details","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]},{"id":"blk_mysterys02","ref":"location","title":"Which store or branch did you visit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_mysterys03","ref":"visit_time","title":"When did the visit take place?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":false,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_mysterys04","ref":"visit_channel","title":"How did you contact the business?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_store","label":"In store","image_key":null},{"id":"opt_by_phone","label":"By phone","image_key":null},{"id":"opt_online_chat_or","label":"Online chat or website","image_key":null}],"allowOther":false},{"id":"blk_mysterys05","ref":"store_condition","title":"How did the store look?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_entrance_and","label":"Entrance and windows"},{"id":"opt_row_shelves_and","label":"Shelves and displays"},{"id":"opt_row_floors_and","label":"Floors and aisles"},{"id":"opt_row_fitting_rooms","label":"Fitting rooms or seating"},{"id":"opt_row_checkout_area","label":"Checkout area"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_acceptable","label":"Acceptable"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_not_applicable","label":"Not applicable"}],"multiplePerRow":false},{"id":"blk_mysterys06","ref":"greeted","title":"How soon were you greeted or answered?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_straight_away","label":"Straight away","image_key":null},{"id":"opt_within_a_couple","label":"Within a couple of minutes","image_key":null},{"id":"opt_after_a_long","label":"After a long wait","image_key":null},{"id":"opt_not_at_all","label":"Not at all","image_key":null}],"allowOther":false},{"id":"blk_mysterys07","ref":"staff_knowledge","title":"How well could staff answer your questions about the product?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_mysterys08","ref":"item_found","title":"Was the item you asked about available?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_mysterys09","ref":"alternative_offered","title":"What did staff do when it wasn''t available?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_offered_to_order","label":"Offered to order it","image_key":null},{"id":"opt_suggested_an_alternative","label":"Suggested an alternative","image_key":null},{"id":"opt_told_me_to","label":"Told me to check back later","image_key":null},{"id":"opt_nothing","label":"Nothing","image_key":null}],"allowOther":false},{"id":"blk_mysterys10","ref":"checkout","title":"How smooth was the checkout or next step?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_mysterys11","ref":"observations","title":"Describe the visit in your own words, sticking to what you saw and heard.","description":"Include staff names or descriptions, times and anything that stood out.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2000,"aiQualityCheck":false},{"id":"blk_mysterys12","ref":"evidence","title":"Upload your receipt and any photos you took.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","application/pdf"],"maxFiles":5,"maxSizeMB":10},{"id":"blk_mysterys13","ref":"overall","title":"Overall, how close was the visit to the standard you were briefed on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Far below","labelHigh":"Fully met"}],"endings":[{"id":"end_mysterys01","ref":"end_thanks","title":"Report received, thank you","bodyMd":"We''ll review it and be in touch if anything needs clarifying.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_mysterys01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"visit_channel"},"op":"eq","value":"opt_by_phone"}],"groups":[]},"from":"visit_channel","target":"greeted","targetKind":"block","branch":"true"},{"id":"rl_mysterys02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"visit_channel"},"op":"eq","value":"opt_online_chat_or"}],"groups":[]},"from":"visit_channel","target":"greeted","targetKind":"block","branch":"true"},{"id":"rl_mysterys03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"item_found"},"op":"eq","value":true}],"groups":[]},"from":"item_found","target":"checkout","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f3e6ff","surface":"#ffffff","text":"#2b1638","accent":"#9333ea","accentText":"#fdf9ff","botBubble":"#ffffff","userBubble":"#9333ea","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"confetti","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
