VALUES ('tpl_newsletterfeedbacksurvey', 'newsletter-feedback-survey', 'Newsletter feedback survey', 'Survey', 'Find out whether your newsletter is useful and what would keep people reading.', 'A short survey to send your subscribers. It asks how they read the newsletter, and the answer decides the next question: engaged readers name their favourite part, while people who open it only now and then, or rarely, are asked what stops them. Everyone then weighs in on frequency, length and topics, and gets a chance to recommend it.', '["marketing","newsletter feedback survey","email newsletter survey","subscriber survey","reader feedback","email marketing"]', 'Mail', 'choice', 3, 9, '{"schemaVersion":9,"title":"Newsletter feedback","description":"Find out whether your newsletter is useful and what would keep people reading.","blocks":[{"id":"blk_newslett00","ref":"welcome","title":"Hi! You get our newsletter, and we want to make it worth opening. Got a minute?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_newslett01","ref":"read_habit","title":"How do you usually read the newsletter?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_read_most","label":"I read most of every issue","image_key":null},{"id":"opt_i_skim_for","label":"I skim for what interests me","image_key":null},{"id":"opt_i_open_it","label":"I open it now and then","image_key":null},{"id":"opt_i_rarely_open","label":"I rarely open it","image_key":null}],"allowOther":false},{"id":"blk_newslett02","ref":"favourite","title":"Which part do you look forward to most?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":400,"aiQualityCheck":false},{"id":"blk_newslett03","ref":"rarely_why","title":"What usually stops you opening it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_it_arrives_too","label":"It arrives too often","image_key":null},{"id":"opt_the_topics_aren","label":"The topics aren''t relevant to me","image_key":null},{"id":"opt_it_s_too","label":"It''s too long","image_key":null},{"id":"opt_the_subject_lines","label":"The subject lines don''t grab me","image_key":null},{"id":"opt_my_inbox_is","label":"My inbox is just too full","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_newslett04","ref":"usefulness","title":"How useful is the newsletter to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_newslett05","ref":"frequency","title":"How often would you like to hear from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_more_often","label":"More often","image_key":null},{"id":"opt_about_the_same","label":"About the same as now","image_key":null},{"id":"opt_less_often","label":"Less often","image_key":null}],"allowOther":false},{"id":"blk_newslett06","ref":"length","title":"How do you feel about the length?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Too short","labelHigh":"Too long"},{"id":"blk_newslett07","ref":"more_topics","title":"What would you like more of?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_practical_tips","label":"Practical tips","image_key":null},{"id":"opt_news_and_updates","label":"News and updates","image_key":null},{"id":"opt_stories_and_case","label":"Stories and case studies","image_key":null},{"id":"opt_recommended_links_and","label":"Recommended links and reading","image_key":null},{"id":"opt_offers_and_early","label":"Offers and early access","image_key":null},{"id":"opt_behind_the_scenes","label":"Behind the scenes","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_newslett08","ref":"recommend","title":"How likely are you to recommend the newsletter to a friend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_newslett09","ref":"suggestion","title":"Anything else that would make it better?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_newslett01","ref":"end_thanks","title":"Thanks for helping us improve ✉️","bodyMd":"We''ll use your answers to shape the next issues.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_newslett01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"favourite","target":"usefulness","targetKind":"block"},{"id":"rl_newslett02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"read_habit"},"op":"eq","value":"opt_i_open_it"}],"groups":[]},"from":"read_habit","target":"rarely_why","targetKind":"block","branch":"true"},{"id":"rl_newslett03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"read_habit"},"op":"eq","value":"opt_i_rarely_open"}],"groups":[]},"from":"read_habit","target":"rarely_why","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
