VALUES ('tpl_onlinecommunityneedsasse', 'online-community-needs-assessment-survey', 'Online community needs assessment survey', 'Survey', 'Find out what members need before you plan the next event, channel or program.', 'Starts with how long someone has been around and how they take part, so a quiet lurker and a daily poster can be read separately. Members who feel they don''t belong are asked what would change that, and anyone who offers to help run something is asked for an email and gets their own thank-you.', '["marketing","community survey","needs assessment","member survey","online community","community manager"]', 'Users', 'choice', 3, 11, '{"schemaVersion":9,"title":"Community needs assessment","description":"Find out what members need before you plan the next event, channel or program.","blocks":[{"id":"blk_onlineco00","ref":"welcome","title":"You make this community what it is. Help us decide what to build next? It takes about four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_onlineco01","ref":"member_length","title":"How long have you been part of the community?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a month","image_key":null},{"id":"opt_1_6_months","label":"1–6 months","image_key":null},{"id":"opt_6_12_months","label":"6–12 months","image_key":null},{"id":"opt_more_than_a","label":"More than a year","image_key":null}],"allowOther":false},{"id":"blk_onlineco02","ref":"participation","title":"Which of these sounds most like you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_mostly_read","label":"I mostly read","image_key":null},{"id":"opt_i_post_or","label":"I post or comment now and then","image_key":null},{"id":"opt_i_m_in","label":"I''m in most conversations","image_key":null},{"id":"opt_i_host_or","label":"I host or help run things","image_key":null}],"allowOther":false},{"id":"blk_onlineco03","ref":"reasons","title":"What did you join for? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_learning_from_people","label":"Learning from people who''ve done it","image_key":null},{"id":"opt_getting_help_with","label":"Getting help with a specific problem","image_key":null},{"id":"opt_meeting_people_in","label":"Meeting people in my field","image_key":null},{"id":"opt_sharing_my_own","label":"Sharing my own work","image_key":null},{"id":"opt_finding_jobs_clients","label":"Finding jobs, clients or collaborators","image_key":null},{"id":"opt_keeping_up_with","label":"Keeping up with news","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":true},{"id":"blk_onlineco04","ref":"needs_met","title":"How well does the community meet each of these needs today?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_getting_answers","label":"Getting answers to questions"},{"id":"opt_row_meeting_new","label":"Meeting new people"},{"id":"opt_row_learning_new","label":"Learning new skills"},{"id":"opt_row_feeling_welcome","label":"Feeling welcome as a newcomer"}],"columns":[{"id":"opt_col_not_at","label":"Not at all"},{"id":"opt_col_somewhat","label":"Somewhat"},{"id":"opt_col_well","label":"Well"},{"id":"opt_col_very_well","label":"Very well"}],"multiplePerRow":false},{"id":"blk_onlineco05","ref":"priorities","title":"If we could add more of one thing, what should it be? Put your top pick first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_live_events","label":"Live events and workshops"},{"id":"opt_item_q_a","label":"Q&A sessions with experts"},{"id":"opt_item_a_library","label":"A library of guides and resources"},{"id":"opt_item_small_peer","label":"Small peer groups"},{"id":"opt_item_a_board","label":"A board for jobs and projects"},{"id":"opt_item_member_spotlights","label":"Member spotlights"}]},{"id":"blk_onlineco06","ref":"barriers","title":"What makes it harder to take part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_not_enough_time","label":"Not enough time","image_key":null},{"id":"opt_events_are_at","label":"Events are at a bad time for my time zone","image_key":null},{"id":"opt_hard_to_find","label":"Hard to find conversations that matter to me","image_key":null},{"id":"opt_i_feel_nervous","label":"I feel nervous posting","image_key":null},{"id":"opt_too_many_notifications","label":"Too many notifications","image_key":null},{"id":"opt_nothing_i_take","label":"Nothing, I take part as much as I want","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":true},{"id":"blk_onlineco07","ref":"belonging","title":"How much do you feel you belong here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Like an outsider","labelHigh":"Right at home"},{"id":"blk_onlineco08","ref":"belong_more","title":"What would help you feel more at home here?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_onlineco09","ref":"one_thing","title":"If you could add one thing to the community tomorrow, what would it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_onlineco10","ref":"help_out","title":"Would you be up for helping run something, like hosting a session or welcoming new members?","required":true,"visibility":null,"image_