VALUES ('tpl_phonesurvey', 'phone-survey', 'Phone survey', 'Survey', 'An interviewer script for customer calls that logs outcomes, callbacks and answers.', 'Written for the person making the call, with every question worded to be read aloud. The first answer routes the rest: a declined or unanswered call ends straight away, a callback request asks for a time and closes on its own ending, and only a completed call goes on to the questions.', '["marketing","phone survey","telephone survey script","phone interview","customer call","cati"]', 'Phone', 'choice', 4, 14, '{"schemaVersion":9,"title":"Phone survey script","description":"An interviewer script for customer calls that logs outcomes, callbacks and answers.","blocks":[{"id":"blk_phonesur00","ref":"welcome","title":"Interviewer: open this before you dial, and fill it in as the call goes. Read the questions exactly as written.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_phonesur01","ref":"interviewer","title":"Your name (interviewer)","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_phonesur02","ref":"number_called","title":"Number called","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_phonesur03","ref":"call_outcome","title":"How did the call go?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_reached_them_and","label":"Reached them and they have time now","image_key":null},{"id":"opt_asked_us_to","label":"Asked us to call back","image_key":null},{"id":"opt_declined_to_take","label":"Declined to take part","image_key":null},{"id":"opt_no_answer_or","label":"No answer or voicemail","image_key":null}],"allowOther":false},{"id":"blk_phonesur04","ref":"callback_time","title":"When did they ask to be called back?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":true,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_phonesur05","ref":"consent","title":"Read aloud: \"This takes about five minutes and your answers are only used to improve our service. Is it all right to go ahead?\" Did they agree?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_phonesur06","ref":"customer_since","title":"Read aloud: \"How long have you been a customer? Less than a year, one to three years, or more than three years?\"","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a year","image_key":null},{"id":"opt_1_3_years","label":"1–3 years","image_key":null},{"id":"opt_more_than_3","label":"More than 3 years","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null}],"allowOther":false},{"id":"blk_phonesur07","ref":"satisfaction","title":"Read aloud: \"On a scale of one to five, where five is very satisfied, how satisfied are you with us overall?\"","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"number"},{"id":"blk_phonesur08","ref":"reason","title":"Read aloud: \"What''s the main reason for that score?\" Note their words as closely as you can.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_phonesur09","ref":"contact_channel","title":"Read aloud: \"When you need to reach us, do you usually phone, email, use chat, or come in person?\"","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_phone","label":"Phone","image_key":null},{"id":"opt_email","label":"Email","image_key":null},{"id":"opt_chat","label":"Chat","image_key":null},{"id":"opt_in_person","label":"In person","image_key":null},{"id":"opt_they_haven_t","label":"They haven''t needed to","image_key":null}],"allowOther":false},{"id":"blk_phonesur10","ref":"one_change","title":"Read aloud: \"If you could change one thing about dealing with us, what would it be?\"","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_phonesur11","ref":"recommend","title":"Read aloud: \"From zero to ten, how likely are you to recommend us to a friend or colleague?\"","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_phonesur12","ref":"wants_follow_up","title":"Did they ask for someone to follow up on anything they raised?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_phonesur13","ref":"follow_up_topic","title":"What should the follow-up be about, and when is a good time to reach them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_phonesur14","ref":"notes","title":"Your notes: anything about the call the team should know","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false}],"endings":[{"id":"end_phonesur01","ref":"end_thanks","title":"Interview saved","bodyMd":"Thank them for their time and let them know their answers will be read by the team.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_phonesur02","ref":"end_callback","title":"Callback logged 📞","bodyMd":"The time is saved with this record. Thank them and end the call politely.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_phonesur03","ref":"end_not_completed","title":"Call logged","bodyMd":"No interview this time. Thank them for their time if you spoke, and move on to the next number.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_phonesur01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"callback_time","target":"end_callback","targetKind":"ending"},{"id":"rl_phonesur02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"call_outcome"},"op":"eq","value":"opt_reached_them_and"}],"groups":[]},"from":"call_outcome","target":"consent","targetKind":"block","branch":"true"},{"id":"rl_phonesur03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"call_outcome"},"op":"eq","value":"opt_asked_us_to"}],"groups":[]},"from":"call_outcome","target":"callback_time","targetKind":"block","branch":"true"},{"id":"rl_phonesur04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"call_outcome"},"op":"eq","value":"opt_declined_to_take"}],"groups":[]},"from":"call_outcome","target":"end_not_completed","targetKind":"ending","branch":"true"},{"id":"rl_phonesur05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"call_outcome"},"op":"eq","value":"opt_no_answer_or"}],"groups":[]},"from":"call_outcome","target":"end_not_completed","targetKind":"ending","branch":"true"},{"id":"rl_phonesur06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"consent"},"op":"eq","value":false}],"groups":[]},"from":"consent","target":"end_not_completed","targetKind":"ending","branch":"true"},{"id":"rl_phonesur07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"wants_follow_up"},"op":"eq","value":false}],"groups":[]},"from":"wants_follow_up","target":"notes","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffdce8","surface":"#ffffff","text":"#3d1424","accent":"#be185d","accentText":"#fff7fa","botBubble":"#ffffff","userBubble":"#be185d","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"scallops","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
