VALUES ('tpl_podcastsurvey', 'podcast-survey', 'Podcast survey', 'Survey', 'Learn who your listeners are, how they listen and what they want next.', 'Covers the questions podcasters actually argue about: episode length, format, where people listen and what they''d cut. Listeners who rate the show highly are asked which episode stuck with them, and anyone less keen is asked what would win them back.', '["marketing","podcast survey","listener survey","podcast feedback","audience survey","podcast audience"]', 'Mic', 'choice', 4, 12, '{"schemaVersion":9,"title":"Podcast listener survey","description":"Learn who your listeners are, how they listen and what they want next.","blocks":[{"id":"blk_podcasts00","ref":"welcome","title":"Hey, thanks for listening! Got three minutes to help us plan the next season?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_podcasts01","ref":"listening_since","title":"How long have you been listening?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_this_is_my","label":"This is my first episode","image_key":null},{"id":"opt_a_few_months","label":"A few months","image_key":null},{"id":"opt_about_a_year","label":"About a year","image_key":null},{"id":"opt_since_the_early","label":"Since the early episodes","image_key":null}],"allowOther":false},{"id":"blk_podcasts02","ref":"found_us","title":"How did you find the show?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_recommended_in_my","label":"Recommended in my podcast app","image_key":null},{"id":"opt_searched_for_the","label":"Searched for the topic","image_key":null},{"id":"opt_a_friend_told","label":"A friend told me","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_heard_a_host","label":"Heard a host or guest on another show","image_key":null}],"allowOther":true},{"id":"blk_podcasts03","ref":"how_often","title":"How many episodes do you listen to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_one","label":"Every one","image_key":null},{"id":"opt_most_of_them","label":"Most of them","image_key":null},{"id":"opt_only_when_the","label":"Only when the topic grabs me","image_key":null},{"id":"opt_now_and_then","label":"Now and then","image_key":null}],"allowOther":false},{"id":"blk_podcasts04","ref":"where_listen","title":"Where are you usually when you listen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_commuting_or_driving","label":"Commuting or driving","image_key":null},{"id":"opt_working_out","label":"Working out","image_key":null},{"id":"opt_working","label":"Working","image_key":null},{"id":"opt_doing_chores","label":"Doing chores","image_key":null},{"id":"opt_winding_down_before","label":"Winding down before sleep","image_key":null},{"id":"opt_sitting_down_to","label":"Sitting down to really focus","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_podcasts05","ref":"length","title":"What episode length suits you best?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_20_minutes","label":"Under 20 minutes","image_key":null},{"id":"opt_20_40_minutes","label":"20–40 minutes","image_key":null},{"id":"opt_40_60_minutes","label":"40–60 minutes","image_key":null},{"id":"opt_over_an_hour","label":"Over an hour is fine","image_key":null},{"id":"opt_length_doesn_t","label":"Length doesn''t matter if it''s good","image_key":null}],"allowOther":false},{"id":"blk_podcasts06","ref":"formats","title":"Put these formats in order, favourite first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_guest_interviews","label":"Guest interviews"},{"id":"opt_item_solo_deep","label":"Solo deep dives"},{"id":"opt_item_panel_discussions","label":"Panel discussions"},{"id":"opt_item_listener_questions","label":"Listener questions"},{"id":"opt_item_short_news","label":"Short news roundups"}]},{"id":"blk_podcasts07","ref":"rating","title":"How would you rate the show overall?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_podcasts08","ref":"best_moment","title":"Which episode or moment has stuck with you, and why?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_podcasts09","ref":"win_back","title":"What would make the show better for you? Be as blunt as you like.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_podcasts10","ref":"next_topics","title":"Which topic or guest would you love to hear next?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_podcasts11","ref":"recommend","title":"How likely are you to recommend the show to a friend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_podcasts12","ref":"email","title":"Want to hear if your idea makes it into an episode? Leave your email (optional).","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_podcasts01","ref":"end_thanks","title":"Thanks for listening, and for this 🎧","bodyMd":"We read every answer while planning episodes. See you in the next one.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_podcasts01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"best_moment","target":"next_topics","targetKind":"block"},{"id":"rl_podcasts02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"rating"},"op":"gte","value":4}],"groups":[]},"from":"rating","target":"best_moment","targetKind":"block","branch":"true"},{"id":"rl_podcasts03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"rating"},"op":"lte","value":3}],"groups":[]},"from":"rating","target":"win_back","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
