INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_presentationfeedbacksurv', 'presentation-feedback-survey', 'Presentation feedback survey', 'Survey', 'Hear whether the audience could follow the talk and how the delivery landed.', 'Built around the question speakers rarely ask: how much of it could you follow? Anyone who lost the thread is asked where, people who watched online are asked about sound and slides, and anyone with an unanswered question can ask the speaker for a reply and reach their own ending.', '["marketing","presentation feedback survey","speaker evaluation","talk feedback","audience survey","conference session feedback"]', 'MonitorPlay', 'choice', 4, 13, '{"schemaVersion":9,"title":"Presentation feedback survey","description":"Hear whether the audience could follow the talk and how the delivery landed.","blocks":[{"id":"blk_presenta00","ref":"welcome","title":"Thanks for coming to the talk. Two minutes of honest feedback would help the speaker a lot.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_presenta01","ref":"talk","title":"Which talk or session are you giving feedback on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_presenta02","ref":"attended_how","title":"How did you watch it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_the_room","label":"In the room","image_key":null},{"id":"opt_online_live","label":"Online, live","image_key":null},{"id":"opt_watched_the_recording","label":"Watched the recording","image_key":null}],"allowOther":false},{"id":"blk_presenta03","ref":"online_issues","title":"Did anything get in the way of watching online?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_the_sound_was","label":"The sound was hard to hear","image_key":null},{"id":"opt_the_slides_were","label":"The slides were hard to read on screen","image_key":null},{"id":"opt_the_video_froze","label":"The video froze or lagged","image_key":null},{"id":"opt_i_couldn_t","label":"I couldn''t ask a question","image_key":null},{"id":"opt_no_problems","label":"No problems","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_presenta04","ref":"matched_promise","title":"Did the talk deliver what its title and description promised?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_mostly","label":"Mostly","image_key":null},{"id":"opt_not_really","label":"Not really","image_key":null}],"allowOther":false},{"id":"blk_presenta05","ref":"relevance","title":"How relevant was the content to your work or interests?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not relevant","labelHigh":"Spot on"},{"id":"blk_presenta06","ref":"follow","title":"How much of the talk could you follow?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_all_of_it","label":"All of it","image_key":null},{"id":"opt_most_of_it","label":"Most of it","image_key":null},{"id":"opt_about_half","label":"About half","image_key":null},{"id":"opt_i_lost_the","label":"I lost the thread early","image_key":null}],"allowOther":false},{"id":"blk_presenta07","ref":"lost_thread","title":"Roughly where did you lose the thread, and what would have helped you keep up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_presenta08","ref":"delivery","title":"How did the speaker do on each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_easy_to","label":"Easy to hear and understand"},{"id":"opt_row_spoke_at","label":"Spoke at a comfortable pace"},{"id":"opt_row_slides_were","label":"Slides were readable and helped"},{"id":"opt_row_kept_my","label":"Kept my attention"},{"id":"opt_row_handled_questions","label":"Handled questions well"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_presenta09","ref":"see_again","title":"Would you go to another talk by this speaker?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_maybe","label":"Maybe","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_presenta10","ref":"one_change","title":"If the speaker changed one thing for next time, what should it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_presenta11","ref":"open_question","title":"Is there a question you didn''t get to ask?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_presenta12","ref":"wants_reply","title":"Would you like the speaker to reply to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_presenta13","ref":"reply_email","title":"Where should the reply go?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_presenta01","ref":"end_thanks","title":"Thank you for the feedback","bodyMd":"It goes straight to the speaker and shapes the next version of this talk.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_presenta02","ref":"end_reply","title":"Got it, a reply is on its way ✉️","bodyMd":"The speaker will get back to you by email. Thanks for taking the time.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_presenta01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"reply_email","target":"end_reply","targetKind":"ending"},{"id":"rl_presenta02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"attended_how"},"op":"eq","value":"opt_in_the_room"}],"groups":[]},"from":"attended_how","target":"matched_promise","targetKind":"block","branch":"true"},{"id":"rl_presenta03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"follow"},"op":"eq","value":"opt_about_half"}],"groups":[]},"from":"follow","target":"lost_thread","targetKind":"block","branch":"true"},{"id":"rl_presenta04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"follow"},"op":"eq","value":"opt_i_lost_the"}],"groups":[]},"from":"follow","target":"lost_thread","targetKind":"block","branch":"true"},{"id":"rl_presenta05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"follow"},"op":"eq","value":"opt_all_of_it"}],"groups":[]},"from":"follow","target":"delivery","targetKind":"block","branch":"true"},{"id":"rl_presenta06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"follow"},"op":"eq","value":"opt_most_of_it"}],"groups":[]},"from":"follow","target":"delivery","targetKind":"block","branch":"true"},{"id":"rl_presenta07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"wants_reply"},"op":"eq","value":false}],"groups":[]},"from":"wants_reply","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
