INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_pricingsurvey', 'pricing-survey', 'Pricing survey', 'Survey', 'Find out whether your price is clear, feels fair and holds up against the alternatives.', 'Focuses on how the price is presented and judged rather than on the number alone. People who found the pricing confusing are asked exactly what was hard to work out, anyone who thinks it''s too high is asked what would make it worth paying, and everyone says what they compared you with.', '["marketing","pricing survey","pricing page feedback","value perception","pricing research","competitor pricing"]', 'Calculator', 'choice', 3, 11, '{"schemaVersion":9,"title":"Pricing survey","description":"Find out whether your price is clear, feels fair and holds up against the alternatives.","blocks":[{"id":"blk_pricings00","ref":"welcome","title":"We''re reviewing how we price and explain what we sell. Could you give us three minutes?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_pricings01","ref":"relationship","title":"Where are you with us right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_m_a","label":"I''m a current customer","image_key":null},{"id":"opt_i_used_to","label":"I used to be a customer","image_key":null},{"id":"opt_i_m_thinking","label":"I''m thinking about buying","image_key":null},{"id":"opt_i_looked_at","label":"I looked at you but chose someone else","image_key":null}],"allowOther":false},{"id":"blk_pricings02","ref":"first_reaction","title":"When you first saw our price, what was your reaction?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_i","label":"Less than I expected","image_key":null},{"id":"opt_about_what_i","label":"About what I expected","image_key":null},{"id":"opt_more_than_i","label":"More than I expected","image_key":null},{"id":"opt_i_couldn_t","label":"I couldn''t tell what it would cost me","image_key":null}],"allowOther":false},{"id":"blk_pricings03","ref":"clarity","title":"How easy was it to work out what you would pay?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Very confusing","labelHigh":"Completely clear"},{"id":"blk_pricings04","ref":"confusing","title":"What was hard to work out? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_which_option_was","label":"Which option was right for me","image_key":null},{"id":"opt_what_each_option","label":"What each option includes","image_key":null},{"id":"opt_extra_fees_or","label":"Extra fees or add-ons","image_key":null},{"id":"opt_how_the_price","label":"How the price changes as I use more","image_key":null},{"id":"opt_tax_delivery_or","label":"Tax, delivery or currency","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":true},{"id":"blk_pricings05","ref":"value","title":"For what you get, how does the price feel?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_expensive","label":"Too expensive","image_key":null},{"id":"opt_a_bit_expensive","label":"A bit expensive","image_key":null},{"id":"opt_about_right","label":"About right","image_key":null},{"id":"opt_good_value","label":"Good value","image_key":null},{"id":"opt_surprisingly_cheap","label":"Surprisingly cheap","image_key":null}],"allowOther":false},{"id":"blk_pricings06","ref":"worth_it","title":"What would need to change for the price to feel worth it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_pricings07","ref":"compared_with","title":"What did you compare our price with? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_a_direct_competitor","label":"A direct competitor","image_key":null},{"id":"opt_a_free_alternative","label":"A free alternative","image_key":null},{"id":"opt_doing_it_myself","label":"Doing it myself","image_key":null},{"id":"opt_hiring_someone_to","label":"Hiring someone to do it","image_key":null},{"id":"opt_not_buying_anything","label":"Not buying anything at all","image_key":null},{"id":"opt_i_didn_t","label":"I didn''t compare","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_pricings08","ref":"comparison_detail","title":"How did we look next to the option you compared us with most closely?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_pricings09","ref":"fair_factors","title":"What most makes a price feel fair to you? Put the biggest first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_quality_of","label":"Quality of the product"},{"id":"opt_item_help_when","label":"Help when I need it"},{"id":"opt_item_no_hidden","label":"No hidden extras"},{"id":"opt_item_a_guarantee","label":"A guarantee or easy refunds"},{"id":"opt_item_what_others","label":"What others charge"},{"id":"opt_item_discounts_for","label":"Discounts for loyal customers"}]},{"id":"blk_pricings10","ref":"packaging","title":"Which way of pricing would suit you best?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_one_simple_price","label":"One simple price for everything","image_key":null},{"id":"opt_a_few_options","label":"A few options at different prices","image_key":null},{"id":"opt_a_basic_price","label":"A basic price plus extras I choose","image_key":null},{"id":"opt_pay_only_for","label":"Pay only for what I use","image_key":null}],"allowOther":false},{"id":"blk_pricings11","ref":"anything_else","title":"Anything else about our pricing we should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_pricings01","ref":"end_thanks","title":"Thank you, that''s a real help","bodyMd":"We''ll weigh every answer before we change anything, and we''ll announce changes well ahead of time.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_pricings01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"clarity"},"op":"lte","value":3}],"groups":[]},"from":"clarity","target":"confusing","targetKind":"block","branch":"true"},{"id":"rl_pricings02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"clarity"},"op":"gte","value":4}],"groups":[]},"from":"clarity","target":"value","targetKind":"block","branch":"true"},{"id":"rl_pricings03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"value"},"op":"eq","value":"opt_too_expensive"}],"groups":[]},"from":"value","target":"worth_it","targetKind":"block","branch":"true"},{"id":"rl_pricings04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"value"},"op":"eq","value":"opt_a_bit_expensive"}],"groups":[]},"from":"value","target":"worth_it","targetKind":"block","branch":"true"},{"id":"rl_pricings05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"value"},"op":"eq","value":"opt_about_right"}],"groups":[]},"from":"value","target":"compared_with","targetKind":"block","branch":"true"},{"id":"rl_pricings06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"value"},"op":"eq","value":"opt_good_value"}],"groups":[]},"from":"value","target":"compared_with","targetKind":"block","branch":"true"},{"id":"rl_pricings07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"value"},"op":"eq","value":"opt_surprisingly_cheap"}],"groups":[]},"from":"value","target":"compared_with","targetKind":"block","branch":"true"},{"id":"rl_pricings08","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"confusing","target":"comparison_detail","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
