INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_processimprovementsurvey', 'process-improvement-survey', 'Process improvement survey', 'Survey', 'Find the friction in a workflow by asking the people who do the work.', 'Asks about one named process, so answers stay concrete. It collects the last real mistake, the workarounds people have built for themselves and a ranked list of fixes, and anyone willing to talk it through leaves an email and reaches a separate sign-off.', '["marketing","process improvement survey","workflow feedback","operations survey","continuous improvement","bottleneck"]', 'Wrench', 'choice', 4, 12, '{"schemaVersion":9,"title":"Process improvement survey","description":"Find the friction in a workflow by asking the people who do the work.","blocks":[{"id":"blk_processi00","ref":"welcome","title":"You know this process better than anyone. Help us find what''s slowing it down? About four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_processi01","ref":"process","title":"Which process are you giving feedback on?","description":"For example: customer onboarding, month-end close, order fulfilment.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_processi02","ref":"role","title":"What''s your part in it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_do_it","label":"I do it every day","image_key":null},{"id":"opt_i_do_it_2","label":"I do it now and then","image_key":null},{"id":"opt_i_hand_work","label":"I hand work into it","image_key":null},{"id":"opt_i_rely_on","label":"I rely on what comes out of it","image_key":null},{"id":"opt_i_manage_it","label":"I manage it","image_key":null}],"allowOther":false},{"id":"blk_processi03","ref":"smoothness","title":"How smoothly does it run today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Constantly stuck","labelHigh":"Runs smoothly"},{"id":"blk_processi04","ref":"time_lost","title":"Where does time go that shouldn''t? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_waiting_for_approvals","label":"Waiting for approvals","image_key":null},{"id":"opt_typing_the_same","label":"Typing the same information twice","image_key":null},{"id":"opt_chasing_people_for","label":"Chasing people for updates","image_key":null},{"id":"opt_fixing_mistakes","label":"Fixing mistakes","image_key":null},{"id":"opt_looking_for_files","label":"Looking for files or information","image_key":null},{"id":"opt_not_knowing_who","label":"Not knowing who owns a step","image_key":null},{"id":"opt_switching_between_too","label":"Switching between too many tools","image_key":null}],"minSelections":1,"maxSelections":8,"allowOther":true},{"id":"blk_processi05","ref":"hours_lost","title":"Roughly how many hours a week do you lose to these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":60,"integerOnly":false},{"id":"blk_processi06","ref":"last_mistake","title":"Think of the last time something went wrong in this process. What happened?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_processi07","ref":"has_workaround","title":"Do you use a workaround of your own, like a personal spreadsheet or checklist?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_processi08","ref":"workaround","title":"What is it, and what does it fix?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_processi09","ref":"fixes","title":"Which fixes would help you most? Put the biggest first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_fewer_approval","label":"Fewer approval steps"},{"id":"opt_item_a_clear","label":"A clear owner for each step"},{"id":"opt_item_one_place","label":"One place for all files"},{"id":"opt_item_checklists_or","label":"Checklists or templates"},{"id":"opt_item_automating_repeat","label":"Automating repeat data entry"},{"id":"opt_item_better_training","label":"Better training"}]},{"id":"blk_processi10","ref":"one_change","title":"If you could change one thing tomorrow, what would it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_processi11","ref":"talk_through","title":"Would you be happy to walk someone through the process in a short call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_processi12","ref":"email","title":"What''s the best email to reach you on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_processi01","ref":"end_thanks","title":"Thanks for your honesty","bodyMd":"We''ll share what we find and what we''re changing with everyone who took part.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_processi02","ref":"end_walkthrough","title":"Thanks, we''ll be in touch 🛠️","bodyMd":"Someone working on the review will email you to find a time. Seeing it done is the fastest way for us to understand it.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_processi01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"email","target":"end_walkthrough","targetKind":"ending"},{"id":"rl_processi02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_workaround"},"op":"eq","value":false}],"groups":[]},"from":"has_workaround","target":"fixes","targetKind":"block","branch":"true"},{"id":"rl_processi03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"talk_through"},"op":"eq","value":false}],"groups":[]},"from":"talk_through","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
