VALUES ('tpl_programsatisfactionsurve', 'program-satisfaction-survey', 'Program satisfaction survey', 'Survey', 'Hear how participants found a program, including the ones who didn''t finish.', 'Works for training courses, mentoring schemes, community programs and more. It asks where each person is in the program, so someone who left early is asked why before rating the parts they did use. Participants who want to hear about the next stage leave an email and get their own sign-off.', '["marketing","program satisfaction survey","program evaluation","participant feedback","training program","nonprofit program"]', 'ClipboardCheck', 'choice', 4, 12, '{"schemaVersion":9,"title":"Program satisfaction survey","description":"Hear how participants found a program, including the ones who didn''t finish.","blocks":[{"id":"blk_programs00","ref":"welcome","title":"Thanks for taking part in the program. Could you tell us how it''s going? It takes about four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_programs01","ref":"program","title":"Which program did you take part in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_programs02","ref":"stage","title":"Where are you in the program?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_started","label":"Just started","image_key":null},{"id":"opt_about_halfway","label":"About halfway","image_key":null},{"id":"opt_finished","label":"Finished","image_key":null},{"id":"opt_i_left_before","label":"I left before the end","image_key":null}],"allowOther":false},{"id":"blk_programs03","ref":"why_left","title":"What made you stop? There''s no wrong answer, and it helps us fix things.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_programs04","ref":"need_met","title":"Did the program meet the need you joined it for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_fully","label":"Yes, fully","image_key":null},{"id":"opt_partly","label":"Partly","image_key":null},{"id":"opt_not_yet","label":"Not yet","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_programs05","ref":"overall","title":"Overall, how satisfied are you with the program?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_programs06","ref":"parts","title":"How useful was each part for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_sessions_or","label":"Sessions or classes"},{"id":"opt_row_materials_and","label":"Materials and resources"},{"id":"opt_row_support_from","label":"Support from staff or mentors"},{"id":"opt_row_meeting_other","label":"Meeting other participants"},{"id":"opt_row_updates_about","label":"Updates about times and changes"}],"columns":[{"id":"opt_col_not_useful","label":"Not useful"},{"id":"opt_col_somewhat_useful","label":"Somewhat useful"},{"id":"opt_col_very_useful","label":"Very useful"},{"id":"opt_col_didn_t","label":"Didn''t use it"}],"multiplePerRow":false},{"id":"blk_programs07","ref":"most_helpful","title":"What helped you most, and how?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_programs08","ref":"barriers","title":"Did anything make it harder to take part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_session_times","label":"Session times","image_key":null},{"id":"opt_travel_or_location","label":"Travel or location","image_key":null},{"id":"opt_workload","label":"Workload","image_key":null},{"id":"opt_technology_or_access","label":"Technology or access","image_key":null},{"id":"opt_not_enough_support","label":"Not enough support","image_key":null},{"id":"opt_personal_circumstances","label":"Personal circumstances","image_key":null},{"id":"opt_nothing_got_in","label":"Nothing got in the way","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":true},{"id":"blk_programs09","ref":"next_stage","title":"What would make the next stage or the next round more useful?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_programs10","ref":"recommend","title":"How likely are you to recommend this program to someone in your position?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_programs11","ref":"stay_in_touch","title":"Would you like to hear about the next stage or related programs?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_programs12","ref":"email","title":"Where should we send the details?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_programs01","ref":"end_thanks","title":"Thank you for your feedback","bodyMd":"The program team reads every response and uses it to plan the next round.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_programs02","ref":"end_next","title":"You''re on the list 📬","bodyMd":"We''ll email you when the next stage opens. Thanks for your feedback on this one.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_programs01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"email","target":"end_next","targetKind":"ending"},{"id":"rl_programs02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"stage"},"op":"eq","value":"opt_just_started"}],"groups":[]},"from":"stage","target":"need_met","targetKind":"block","branch":"true"},{"id":"rl_programs03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"stage"},"op":"eq","value":"opt_about_halfway"}],"groups":[]},"from":"stage","target":"need_met","targetKind":"block","branch":"true"},{"id":"rl_programs04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"stage"},"op":"eq","value":"opt_finished"}],"groups":[]},"from":"stage","target":"need_met","targetKind":"block","branch":"true"},{"id":"rl_programs05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"stay_in_touch"},"op":"eq","value":false}],"groups":[]},"from":"stay_in_touch","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
