VALUES ('tpl_retrospectivesurvey', 'retrospective-survey', 'Retrospective survey', 'Survey', 'Collect everyone''s view of a sprint or project before the retro meeting.', 'Filled in privately before the meeting, so quieter people get heard and the discussion starts from real answers. It compares this period with the last one, asks for one concrete thing to try, and anyone who didn''t feel safe raising problems gets a gentle follow-up question.', '["marketing","retrospective survey","sprint retrospective","retro questions","agile retro","project retrospective"]', 'ListChecks', 'choice', 3, 11, '{"schemaVersion":9,"title":"Team retrospective","description":"Collect everyone''s view of a sprint or project before the retro meeting.","blocks":[{"id":"blk_retrospe00","ref":"welcome","title":"Retro time. Answer on your own before we meet, so we can spend the meeting on what matters.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_retrospe01","ref":"period","title":"Which sprint, project or period is this for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_retrospe02","ref":"mood","title":"How did this stretch of work feel for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Rough","labelHigh":"Great"},{"id":"blk_retrospe03","ref":"goal_met","title":"Did we deliver what we set out to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_mostly","label":"Mostly","image_key":null},{"id":"opt_partly","label":"Partly","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_retrospe04","ref":"went_well","title":"What went well that we should keep doing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_retrospe05","ref":"slowed_down","title":"What slowed you down? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_unclear_priorities","label":"Unclear priorities","image_key":null},{"id":"opt_waiting_on_other","label":"Waiting on other people","image_key":null},{"id":"opt_requirements_changed","label":"Requirements changed","image_key":null},{"id":"opt_too_many_meetings","label":"Too many meetings","image_key":null},{"id":"opt_tools_or_environment","label":"Tools or environment problems","image_key":null},{"id":"opt_unplanned_work","label":"Unplanned work","image_key":null},{"id":"opt_nothing_major","label":"Nothing major","image_key":null}],"minSelections":1,"maxSelections":8,"allowOther":true},{"id":"blk_retrospe06","ref":"biggest_blocker","title":"Pick the biggest thing that got in the way. What happened?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_retrospe07","ref":"compared","title":"Compared with last time, how did we do on these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_planning","label":"Planning"},{"id":"opt_row_communication_in","label":"Communication in the team"},{"id":"opt_row_working_with","label":"Working with other teams"},{"id":"opt_row_quality_of","label":"Quality of what we delivered"},{"id":"opt_row_spreading_the","label":"Spreading the workload"}],"columns":[{"id":"opt_col_worse","label":"Worse"},{"id":"opt_col_about_the","label":"About the same"},{"id":"opt_col_better","label":"Better"}],"multiplePerRow":false},{"id":"blk_retrospe08","ref":"try_next","title":"What''s one thing we should try next time?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_retrospe09","ref":"speak_up","title":"How comfortable did you feel raising problems during this period?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_retrospe10","ref":"speak_up_help","title":"What would make it easier to speak up? You can keep this general.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_retrospe11","ref":"shout_out","title":"Anyone you''d like to thank for something specific?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_retrospe01","ref":"end_thanks","title":"Thanks, see you at the retro 👋","bodyMd":"We''ll go through the answers together and agree on what to try next.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_retrospe01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"speak_up"},"op":"lte","value":2}],"groups":[]},"from":"speak_up","target":"speak_up_help","targetKind":"block","branch":"true"},{"id":"rl_retrospe02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"speak_up"},"op":"gte","value":3}],"groups":[]},"from":"speak_up","target":"shout_out","targetKind":"block","branch":"true"},{"id":"rl_retrospe03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"speak_up_help","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#5b2ee6","surface":"#4a22c9","text":"#ffffff","accent":"#ffd166","accentText":"#1c1917","botBubble":"#4a22c9","userBubble":"#ffd166","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundPatternColor":"#ffffff","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
