VALUES ('tpl_skincaresurvey', 'skin-care-survey', 'Skin care survey', 'Survey', 'Learn how people care for their skin and what makes them choose a product.', 'Built for skincare brands and shops researching their customers, not for diagnosis. It asks about routine, goals and buying habits, gives anyone who''s had a reaction a place to describe it, and invites adults who want to test new products to leave an email for a product-testing ending. Anyone under 18 skips the tester invitation.', '["marketing","skin care survey","skincare questionnaire","beauty survey","customer research","product testing"]', 'Sparkles', 'choice', 4, 13, '{"schemaVersion":9,"title":"Skin care survey","description":"Learn how people care for their skin and what makes them choose a product.","blocks":[{"id":"blk_skincare00","ref":"welcome","title":"Tell us about your skincare routine? It takes about three minutes, and this isn''t a skin assessment, just your habits and preferences.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_skincare01","ref":"skin_type","title":"How would you describe your skin most days?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_oily","label":"Oily","image_key":null},{"id":"opt_dry","label":"Dry","image_key":null},{"id":"opt_combination","label":"Combination","image_key":null},{"id":"opt_balanced","label":"Balanced","image_key":null},{"id":"opt_sensitive","label":"Sensitive","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null}],"allowOther":false},{"id":"blk_skincare02","ref":"goals","title":"What would you most like your routine to help with? Pick up to three.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_hydration","label":"Hydration","image_key":null},{"id":"opt_breakouts","label":"Breakouts","image_key":null},{"id":"opt_dark_spots_or","label":"Dark spots or uneven tone","image_key":null},{"id":"opt_fine_lines","label":"Fine lines","image_key":null},{"id":"opt_redness","label":"Redness","image_key":null},{"id":"opt_sun_protection","label":"Sun protection","image_key":null},{"id":"opt_keeping_it_simple","label":"Keeping it simple","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":false},{"id":"blk_skincare03","ref":"routine_steps","title":"How many products do you usually use in a day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_none_really","label":"None really","image_key":null},{"id":"opt_1_2","label":"1–2","image_key":null},{"id":"opt_3_4","label":"3–4","image_key":null},{"id":"opt_5_or_more","label":"5 or more","image_key":null}],"allowOther":false},{"id":"blk_skincare04","ref":"products_used","title":"Which of these do you use at least a few times a week?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_cleanser","label":"Cleanser","image_key":null},{"id":"opt_moisturiser","label":"Moisturiser","image_key":null},{"id":"opt_sunscreen","label":"Sunscreen","image_key":null},{"id":"opt_serum","label":"Serum","image_key":null},{"id":"opt_exfoliant","label":"Exfoliant","image_key":null},{"id":"opt_retinoid","label":"Retinoid","image_key":null},{"id":"opt_eye_cream","label":"Eye cream","image_key":null},{"id":"opt_none_of_these","label":"None of these","image_key":null}],"minSelections":1,"maxSelections":8,"allowOther":false},{"id":"blk_skincare05","ref":"routine_happiness","title":"How happy are you with your current routine?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_skincare06","ref":"choice_factors","title":"When choosing a new product, what matters most? Put the biggest first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_ingredients","label":"Ingredients"},{"id":"opt_item_price","label":"Price"},{"id":"opt_item_reviews","label":"Reviews"},{"id":"opt_item_a_professional","label":"A professional''s recommendation"},{"id":"opt_item_fragrance_free","label":"Fragrance free"},{"id":"opt_item_sustainable_packaging","label":"Sustainable packaging"},{"id":"opt_item_the_brand","label":"The brand"}]},{"id":"blk_skincare07","ref":"where_buy","title":"Where do you usually buy skincare?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_pharmacy","label":"Pharmacy","image_key":null},{"id":"opt_beauty_shop","label":"Beauty shop","image_key":null},{"id":"opt_a_brand_s","label":"A brand''s own website","image_key":null},{"id":"opt_online_marketplace","label":"Online marketplace","image_key":null},{"id":"opt_supermarket","label":"Supermarket","image_key":null},{"id":"opt_salon_or_clinic","label":"Salon or clinic","image_key":null}],"minSelections":1,"maxSelections":6,"allowOther":false},{"id":"blk_skincare08","ref":"had_reaction","title":"Has a skincare product ever irritated your skin?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_skincare09","ref":"reaction_detail","title":"What kind of product was it, and what happened?","description":"This helps us understand what to avoid. We can''t give medical advice.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_skincare10","ref":"wish","title":"Is there a product you wish existed?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_skincare11","ref":"age_range","title":"Which age group are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_under_18","label":"Under 18","image_key":null},{"id":"opt_18_24","label":"18–24","image_key":null},{"id":"opt_25_34","label":"25–34","image_key":null},{"id":"opt_35_44","label":"35–44","image_key":null},{"id":"opt_45_54","label":"45–54","image_key":null},{"id":"opt_55_or_over","label":"55 or over","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}]},{"id":"blk_skincare12","ref":"tester","title":"Would you like to test new products and tell us what you think?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_skincare13","ref":"tester_email","title":"Where should we send tester invitations?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_skincare01","ref":"end_thanks","title":"Thank you!","bodyMd":"Your answers help us make products that fit real routines.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_skincare02","ref":"end_tester","title":"Welcome to the testing panel ✨","bodyMd":"We''ll email you when there''s a product to try. You can say no to any invitation.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_skincare01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"tester_email","target":"end_tester","targetKind":"ending"},{"id":"rl_skincare02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"had_reaction"},"op":"eq","value":false}],"groups":[]},"from":"had_reaction","target":"wish","targetKind":"block","branch":"true"},{"id":"rl_skincare03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"age_range"},"op":"eq","value":"opt_under_18"}],"groups":[]},"from":"age_range","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_skincare04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"tester"},"op":"eq","value":false}],"groups":[]},"from":"tester","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
