INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_socialmediasurvey', 'social-media-survey', 'Social media survey', 'Survey', 'Learn where your audience spends time online and what they want to see from you there.', 'Starts with the platforms people actually use, then splits: people who already follow you say why and how useful your posts are, and people who don''t say what has kept them away. Everyone then ranks formats, picks topics and names what makes them unfollow an account.', '["marketing","social media survey","audience research","content preferences","social media questionnaire","content strategy"]', 'Megaphone', 'choice', 4, 12, '{"schemaVersion":9,"title":"Social media survey","description":"Learn where your audience spends time online and what they want to see from you there.","blocks":[{"id":"blk_socialme00","ref":"welcome","title":"We''re planning what to post next and would rather ask than guess. Two or three minutes, and every answer shapes what you''ll see from us.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_socialme01","ref":"platforms","title":"Which of these do you use at least once a week?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_instagram","label":"Instagram","image_key":null},{"id":"opt_facebook","label":"Facebook","image_key":null},{"id":"opt_linkedin","label":"LinkedIn","image_key":null},{"id":"opt_youtube","label":"YouTube","image_key":null},{"id":"opt_tiktok","label":"TikTok","image_key":null},{"id":"opt_x_6","label":"X","image_key":null},{"id":"opt_pinterest","label":"Pinterest","image_key":null},{"id":"opt_reddit","label":"Reddit","image_key":null},{"id":"opt_whatsapp_or_other","label":"WhatsApp or other messaging apps","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_socialme02","ref":"check_frequency","title":"How often do you scroll through social media on a ty