INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_sustainabilitysurvey', 'sustainability-survey', 'Sustainability survey', 'Survey', 'Find out which green changes your customers care about and what gets in the way of choosing them.', 'Asks about everyday habits and obstacles before any talk of your own plans, so the answers aren''t shaped by what people think you want to hear. Only customers who already know about your efforts are asked to rate them; everyone ranks the changes they''d value most and says what would make a green claim believable.', '["marketing","sustainability survey","environmental survey","green consumer survey","eco-friendly feedback","customer research"]', 'Leaf', 'choice', 3, 12, '{"schemaVersion":9,"title":"Sustainability survey","description":"Find out which green changes your customers care about and what gets in the way of choosing them.","blocks":[{"id":"blk_sustaina00","ref":"welcome","title":"We''re deciding which changes to make first to reduce our environmental impact, and we''d like your view. It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_sustaina01","ref":"importance","title":"When you choose where to buy, how much does a company''s environmental impact matter to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Not at all","labelHigh":"A great deal"},{"id":"blk_sustaina02","ref":"current_habits","title":"Which of these do you already do most of the time?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_recycle_at_home","label":"Recycle at home","image_key":null},{"id":"opt_bring_my_own","label":"Bring my own bags, cups or containers","image_key":null},{"id":"opt_buy_second_hand","label":"Buy second-hand or refurbished","image_key":null},{"id":"opt_pick_products_with","label":"Pick products with less packaging","image_key":null},{"id":"opt_repair_things_before","label":"Repair things before replacing them","image_key":null},{"id":"opt_walk_cycle_or","label":"Walk, cycle or use public transport where I can","image_key":null},{"id":"opt_none_of_these","label":"None of these right now","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_sustaina03","ref":"aware","title":"Before today, had you heard about anything we do to reduce our impact?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_i_could","label":"Yes, I could name something","image_key":null},{"id":"opt_i_ve_heard","label":"I''ve heard something, but vaguely","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_sustaina04","ref":"aware_which","title":"What comes to mind?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_sustaina05","ref":"our_rating","title":"How would you rate our efforts so far?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_sustaina06","ref":"priorities","title":"Rank these changes by how much you''d like us to make them.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_less_packaging","label":"Less packaging, and packaging that''s easy to recycle"},{"id":"opt_item_lower_impact","label":"Lower-impact materials or ingredients"},{"id":"opt_item_repair_refill","label":"Repair, refill or take-back options"},{"id":"opt_item_sourcing_more","label":"Sourcing more locally"},{"id":"opt_item_cutting_our","label":"Cutting our energy use and emissions"},{"id":"opt_item_fair_pay","label":"Fair pay and conditions in our supply chain"}]},{"id":"blk_sustaina07","ref":"barriers","title":"What stops you choosing the greener option more often?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_it_usually_costs","label":"It usually costs more","image_key":null},{"id":"opt_it_s_hard","label":"It''s hard to tell which option is really better","image_key":null},{"id":"opt_it_isn_t","label":"It isn''t sold where I shop","image_key":null},{"id":"opt_it_s_less","label":"It''s less convenient","image_key":null},{"id":"opt_i_don_t","label":"I don''t trust the claims","image_key":null},{"id":"opt_the_quality_isn","label":"The quality isn''t as good","image_key":null},{"id":"opt_nothing_i_already","label":"Nothing, I already choose it when I can","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_sustaina08","ref":"pay_more","title":"Would you pay a little more for a lower-impact version of something you already buy from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_happily","label":"Yes, happily","image_key":null},{"id":"opt_yes_if_the","label":"Yes, if the difference is small","image_key":null},{"id":"opt_only_if_the","label":"Only if the quality is better too","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_sustaina09","ref":"trust","title":"How much would each of these make you believe a company''s green claims?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_certification_from","label":"Certification from an independent body"},{"id":"opt_row_specific_targets","label":"Specific targets and yearly progress reports"},{"id":"opt_row_clear_details","label":"Clear details on the product or packaging"},{"id":"opt_row_being_open","label":"Being open about what hasn''t worked yet"}],"columns":[{"id":"opt_col_not_at","label":"Not at all"},{"id":"opt_col_a_little","label":"A little"},{"id":"opt_col_a_lot","label":"A lot"}],"multiplePerRow":false},{"id":"blk_sustaina10","ref":"ideas","title":"Is there one change you''d most like to see from us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_sustaina11","ref":"updates","title":"Would you like an occasional update on how these changes are going?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_sustaina12","ref":"updates_email","title":"Which email should we send them to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_sustaina01","ref":"end_thanks","title":"Thank you for your thoughts","bodyMd":"Your answers will help us decide which changes to make first.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_sustaina02","ref":"end_updates","title":"Thank you, we''ll keep you posted 🌱","bodyMd":"You''ll hear from us when there''s real progress to report, not before.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_sustaina01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"updates_email","target":"end_updates","targetKind":"ending"},{"id":"rl_sustaina02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"aware"},"op":"eq","value":"opt_yes_i_could"}],"groups":[]},"from":"aware","target":"aware_which","targetKind":"block","branch":"true"},{"id":"rl_sustaina03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"aware"},"op":"eq","value":"opt_i_ve_heard"}],"groups":[]},"from":"aware","target":"our_rating","targetKind":"block","branch":"true"},{"id":"rl_sustaina04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"aware"},"op":"eq","value":"opt_no"}],"groups":[]},"from":"aware","target":"priorities","targetKind":"block","branch":"true"},{"id":"rl_sustaina05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"updates"},"op":"eq","value":false}],"groups":[]},"from":"updates","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_sustaina06","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"aware_which","target":"barriers","targetKind":"block","branch":"true"},{"id":"rl_sustaina07","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"our_rating","target":"barriers","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f3e6ff","surface":"#ffffff","text":"#2b1638","accent":"#9333ea","accentText":"#fdf9ff","botBubble":"#ffffff","userBubble":"#9333ea","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"confetti","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
