INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_targetmarketsurvey', 'target-market-survey', 'Target market survey', 'Survey', 'Test who needs what you''re building, before you decide which audience to focus on.', 'Starts with how often the problem comes up, and anyone who doesn''t have it explains why and leaves early instead of padding your data. Everyone else rates the pain, describes their current fix, says who decides and what they''d judge a new option on, and can volunteer for a follow-up conversation.', '["marketing","target market survey","customer research","market validation","audience research","problem validation"]', 'Target', 'choice', 4, 13, '{"schemaVersion":9,"title":"Target market survey","description":"Test who needs what you''re building, before you decide which audience to focus on.","blocks":[{"id":"blk_targetma00","ref":"welcome","title":"We''re working on a way to make keeping track of household bills less of a chore, and we''re trying to learn who struggles with it most. About three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_targetma01","ref":"buying_for","title":"Who would you be solving this for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_my_household_or","label":"My household or family","image_key":null},{"id":"opt_a_small_business","label":"A small business I run or work at","image_key":null},{"id":"opt_a_larger_company","label":"A larger company or organisation","image_key":null}],"allowOther":false},{"id":"blk_targetma02","ref":"how_often","title":"How often does this problem come up for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_every_week","label":"Every week","image_key":null},{"id":"opt_a_few_times","label":"A few times a month","image_key":null},{"id":"opt_rarely","label":"Rarely","image_key":null},{"id":"opt_it_isn_t","label":"It isn''t a problem for me","image_key":null}],"allowOther":false},{"id":"blk_targetma03","ref":"not_a_problem","title":"What makes it a non-issue for you? If you''ve found something that works, we''d love to know what.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_targetma04","ref":"pain","title":"When it happens, how much does it bother you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"I barely notice","labelHigh":"It really costs me"},{"id":"blk_targetma05","ref":"current_fix","title":"How do you handle it today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_a_spreadsheet_or","label":"A spreadsheet or notes","image_key":null},{"id":"opt_an_app_or","label":"An app or piece of software","image_key":null},{"id":"opt_i_pay_someone","label":"I pay someone to handle it","image_key":null},{"id":"opt_i_ask_friends","label":"I ask friends, family or colleagues","image_key":null},{"id":"opt_i_just_put","label":"I just put up with it","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_targetma06","ref":"current_gaps","title":"What''s missing or annoying about the way you handle it now?","required":true,"visibility":null,"image_key":null,"agentHints":{"askStyle":"If the answer is general, ask for the last time it went wrong and what that cost them.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_targetma07","ref":"spent_before","title":"Have you spent money trying to solve this in the past year?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_i_pay","label":"Yes, I pay for something regularly","image_key":null},{"id":"opt_yes_once_or","label":"Yes, once or twice","image_key":null},{"id":"opt_no_but_i","label":"No, but I would for the right thing","image_key":null},{"id":"opt_no_and_i","label":"No, and I wouldn''t","image_key":null}],"allowOther":false},{"id":"blk_targetma08","ref":"decider","title":"If you found something that worked, who would decide whether to buy it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_me_alone","label":"Me alone","image_key":null},{"id":"opt_me_together_with","label":"Me, together with someone else","image_key":null},{"id":"opt_someone_else","label":"Someone else","image_key":null}],"allowOther":false},{"id":"blk_targetma09","ref":"criteria","title":"Rank what would matter most when choosing a new option.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_price","label":"Price"},{"id":"opt_item_ease_of","label":"Ease of use"},{"id":"opt_item_time_it","label":"Time it saves"},{"id":"opt_item_a_recommendation","label":"A recommendation from someone I trust"},{"id":"opt_item_reliability","label":"Reliability"},{"id":"opt_item_help_when","label":"Help when I get stuck"}]},{"id":"blk_targetma10","ref":"where_look","title":"Where would you look for a solution?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_search_engines","label":"Search engines","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_friends_family_or","label":"Friends, family or colleagues","image_key":null},{"id":"opt_review_or_comparison","label":"Review or comparison sites","image_key":null},{"id":"opt_online_communities_and","label":"Online communities and forums","image_key":null},{"id":"opt_app_stores","label":"App stores","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_targetma11","ref":"age_group","title":"Which age group are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_18_to_24","label":"18 to 24","image_key":null},{"id":"opt_25_to_34","label":"25 to 34","image_key":null},{"id":"opt_35_to_44","label":"35 to 44","image_key":null},{"id":"opt_45_to_54","label":"45 to 54","image_key":null},{"id":"opt_55_to_64","label":"55 to 64","image_key":null},{"id":"opt_65_or_over","label":"65 or over","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}]},{"id":"blk_targetma12","ref":"interview","title":"Would you be open to a short follow-up conversation about this?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_targetma13","ref":"interview_email","title":"Great. Which email should we use to arrange it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_targetma01","ref":"end_thanks","title":"Thanks for your time","bodyMd":"Your answers help us work out who we should build this for first.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_targetma02","ref":"end_not_fit","title":"Thanks, that''s useful to know","bodyMd":"Knowing who doesn''t have this problem helps us as much as knowing who does. That''s all we need from you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_targetma03","ref":"end_interview","title":"Thank you, we''ll be in touch 📬","bodyMd":"We''ll email you to find a time that suits. It''s a conversation, not a sales call.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_targetma01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"not_a_problem","target":"end_not_fit","targetKind":"ending"},{"id":"rl_targetma02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"interview_email","target":"end_interview","targetKind":"ending"},{"id":"rl_targetma03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"how_often"},"op":"eq","value":"opt_it_isn_t"}],"groups":[]},"from":"how_often","target":"not_a_problem","targetKind":"block","branch":"true"},{"id":"rl_targetma04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"how_often"},"op":"eq","value":"opt_every_day"}],"groups":[]},"from":"how_often","target":"pain","targetKind":"block","branch":"true"},{"id":"rl_targetma05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"how_often"},"op":"eq","value":"opt_every_week"}],"groups":[]},"from":"how_often","target":"pain","targetKind":"block","branch":"true"},{"id":"rl_targetma06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"how_often"},"op":"eq","value":"opt_a_few_times"}],"groups":[]},"from":"how_often","target":"pain","targetKind":"block","branch":"true"},{"id":"rl_targetma07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"how_often"},"op":"eq","value":"opt_rarely"}],"groups":[]},"from":"how_often","target":"pain","targetKind":"block","branch":"true"},{"id":"rl_targetma08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"interview"},"op":"eq","value":false}],"groups":[]},"from":"interview","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffdce8","surface":"#ffffff","text":"#3d1424","accent":"#be185d","accentText":"#fff7fa","botBubble":"#ffffff","userBubble":"#be185d","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"scallops","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
