VALUES ('tpl_technologysurvey', 'technology-survey', 'Technology survey', 'Survey', 'Understand how people use technology at work, where it slows them down and what support they need.', 'A workplace technology check that goes past a satisfaction score. People rate each part of their setup, say how much time they lose each week, and only those losing real time are asked to describe the problem. It ends on how they feel about new tools and how they''d like to learn one, which is what you need before any change.', '["marketing","technology survey","workplace technology survey","IT survey","digital tools survey","employee technology"]', 'Laptop', 'choice', 4, 11, '{"schemaVersion":9,"title":"Technology survey","description":"Understand how people use technology at work, where it slows them down and what support they need.","blocks":[{"id":"blk_technolo00","ref":"welcome","title":"We''re reviewing the tools and devices people use at work. Tell us what helps and what gets in the way. It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_technolo01","ref":"team","title":"Which team are you in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_operations","label":"Operations","image_key":null},{"id":"opt_sales","label":"Sales","image_key":null},{"id":"opt_marketing","label":"Marketing","image_key":null},{"id":"opt_finance","label":"Finance","image_key":null},{"id":"opt_hr_and_people","label":"HR and people","image_key":null},{"id":"opt_customer_support","label":"Customer support","image_key":null},{"id":"opt_engineering_or_it","label":"Engineering or IT","image_key":null},{"id":"opt_leadership","label":"Leadership","image_key":null},{"id":"opt_other","label":"Other","image_key":null}]},{"id":"blk_technolo02","ref":"devices","title":"Which devices do you use for work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_a_laptop","label":"A laptop","image_key":null},{"id":"opt_a_desktop_computer","label":"A desktop computer","image_key":null},{"id":"opt_a_work_phone","label":"A work phone","image_key":null},{"id":"opt_my_own_phone","label":"My own phone","image_key":null},{"id":"opt_a_tablet","label":"A tablet","image_key":null},{"id":"opt_a_shared_computer","label":"A shared computer or terminal","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_technolo03","ref":"main_tools","title":"Which tools or apps do you rely on most in a normal day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_technolo04","ref":"confidence","title":"How confident do you feel using the technology your job needs?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not confident","labelHigh":"Very confident"},{"id":"blk_technolo05","ref":"tool_ratings","title":"How well does each of these work for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_email_and","label":"Email and calendar"},{"id":"opt_row_chat_and","label":"Chat and video calls"},{"id":"opt_row_storing_and","label":"Storing and sharing files"},{"id":"opt_row_the_main","label":"The main system for your role"},{"id":"opt_row_your_computer","label":"Your computer itself"}],"columns":[{"id":"opt_col_gets_in","label":"Gets in my way"},{"id":"opt_col_it_s","label":"It''s okay"},{"id":"opt_col_works_well","label":"Works well"},{"id":"opt_col_i_don","label":"I don''t use it"}],"multiplePerRow":false},{"id":"blk_technolo06","ref":"time_lost","title":"In a typical week, how much time do you lose to tech problems or workarounds?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_almost_none","label":"Almost none","image_key":null},{"id":"opt_less_than_an","label":"Less than an hour","image_key":null},{"id":"opt_1_3_hours","label":"1–3 hours","image_key":null},{"id":"opt_more_than_3","label":"More than 3 hours","image_key":null}],"allowOther":false},{"id":"blk_technolo07","ref":"biggest_blocker","title":"What eats up most of that time? Describe the last time it happened.","required":true,"visibility":null,"image_key":null,"agentHints":{"askStyle":"If they name a tool, ask what they were trying to do when it went wrong.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_technolo08","ref":"support","title":"When something breaks, how good is the help you get?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_technolo09","ref":"learn_pref","title":"How do you prefer to learn a new tool?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_short_videos","label":"Short videos","image_key":null},{"id":"opt_written_step_by","label":"Written step-by-step guides","image_key":null},{"id":"opt_a_live_training","label":"A live training session","image_key":null},{"id":"opt_one_to_one","label":"One-to-one help","image_key":null},{"id":"opt_a_colleague_shows","label":"A colleague shows me","image_key":null},{"id":"opt_i_figure_it","label":"I figure it out myself","image_key":null}],"minSelections":1,"maxSelections":2,"allowOther":false},{"id":"blk_technolo10","ref":"new_tools","title":"When a new tool is introduced, how do you usually feel?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_keen_to_try","label":"Keen to try it","image_key":null},{"id":"opt_fine_if_someone","label":"Fine, if someone shows me how","image_key":null},{"id":"opt_wary_it_often","label":"Wary, it often adds work","image_key":null},{"id":"opt_i_d_rather","label":"I''d rather keep what we have","image_key":null}],"allowOther":false},{"id":"blk_technolo11","ref":"one_fix","title":"If you could fix or replace one piece of technology you use, what would it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_technolo01","ref":"end_thanks","title":"Thank you, that''s a big help","bodyMd":"We''ll share what we heard and what we plan to change once everyone has had a chance to answer.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_technolo01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"time_lost"},"op":"eq","value":"opt_1_3_hours"}],"groups":[]},"from":"time_lost","target":"biggest_blocker","targetKind":"block","branch":"true"},{"id":"rl_technolo02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"time_lost"},"op":"eq","value":"opt_more_than_3"}],"groups":[]},"from":"time_lost","target":"biggest_blocker","targetKind":"block","branch":"true"},{"id":"rl_technolo03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"time_lost"},"op":"eq","value":"opt_almost_none"}],"groups":[]},"from":"time_lost","target":"support","targetKind":"block","branch":"true"},{"id":"rl_technolo04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"time_lost"},"op":"eq","value":"opt_less_than_an"}],"groups":[]},"from":"time_lost","target":"support","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
