VALUES ('tpl_trainingevaluationsurvey', 'training-evaluation-survey', 'Training evaluation survey', 'Survey', 'Find out how well a training session was designed and delivered, and what to change for the next group.', 'Written for the people who run the training. It rates the parts you can change, from objectives and examples to practice time, pace and level, then asks whether the learner would recommend the session. A yes leads to what worked best; anything less leads to what would need to change first.', '["marketing","training evaluation survey","training feedback form","course evaluation","trainer feedback","session evaluation"]', 'GraduationCap', 'choice', 3, 11, '{"schemaVersion":9,"title":"Training evaluation","description":"Find out how well a training session was designed and delivered, and what to change for the next group.","blocks":[{"id":"blk_training00","ref":"welcome","title":"Thanks for taking part. A few quick questions about how the session was run, so the next group gets a better one.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_training01","ref":"session","title":"Which session did you attend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_training02","ref":"overall","title":"Overall, how would you rate the session?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_training03","ref":"statements","title":"How far do you agree with each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_the_objectives","label":"The objectives were clear from the start"},{"id":"opt_row_the_content","label":"The content matched what was advertised"},{"id":"opt_row_the_examples","label":"The examples fit my kind of work"},{"id":"opt_row_there_was","label":"There was enough time to practise"},{"id":"opt_row_the_materials","label":"The materials will be useful afterwards"}],"columns":[{"id":"opt_col_strongly_disagree","label":"Strongly disagree"},{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_agree","label":"Agree"},{"id":"opt_col_strongly_agree","label":"Strongly agree"}],"multiplePerRow":false},{"id":"blk_training04","ref":"pace","title":"How was the pace?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_slow","label":"Too slow","image_key":null},{"id":"opt_about_right","label":"About right","image_key":null},{"id":"opt_too_fast","label":"Too fast","image_key":null}],"allowOther":false},{"id":"blk_training05","ref":"level","title":"How did the level suit you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_basic_for","label":"Too basic for me","image_key":null},{"id":"opt_about_right","label":"About right","image_key":null},{"id":"opt_too_advanced_for","label":"Too advanced for me","image_key":null}],"allowOther":false},{"id":"blk_training06","ref":"trainer","title":"How would you rate the trainer''s delivery?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_training07","ref":"recommend","title":"Would you recommend this session to a colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_as_it","label":"Yes, as it is","image_key":null},{"id":"opt_yes_with_some","label":"Yes, with some changes","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_training08","ref":"worked_best","title":"Which part worked best for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_training09","ref":"change_first","title":"What would need to change before you''d recommend it without hesitation?","required":true,"visibility":null,"image_key":null,"agentHints":{"askStyle":"If they say something general like ''more practical'', ask which part of the session they mean.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_training10","ref":"format","title":"For a topic like this, which format suits you best?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_person","label":"In person","image_key":null},{"id":"opt_live_online","label":"Live online","image_key":null},{"id":"opt_self_paced_online","label":"Self-paced online","image_key":null},{"id":"opt_a_mix_of","label":"A mix of these","image_key":null}],"allowOther":false},{"id":"blk_training11","ref":"next_topic","title":"What would you like a future session to cover?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false}],"endings":[{"id":"end_training01","ref":"end_thanks","title":"Thank you for the feedback","bodyMd":"The trainer will read every answer before the next session runs.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_training01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"worked_best","target":"format","targetKind":"block"},{"id":"rl_training02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"recommend"},"op":"eq","value":"opt_yes_as_it"}],"groups":[]},"from":"recommend","target":"worked_best","targetKind":"block","branch":"true"},{"id":"rl_training03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"recommend"},"op":"eq","value":"opt_yes_with_some"}],"groups":[]},"from":"recommend","target":"change_first","targetKind":"block","branch":"true"},{"id":"rl_training04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"recommend"},"op":"eq","value":"opt_no"}],"groups":[]},"from":"recommend","target":"change_first","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ece3ff","surface":"#ffffff","text":"#2a1f3d","accent":"#6d3fc7","accentText":"#fbf8ff","botBubble":"#ffffff","userBubble":"#6d3fc7","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
