VALUES ('tpl_usersatisfactionsurvey', 'user-satisfaction-survey', 'User satisfaction survey', 'Survey', 'Learn how well your product works for the people using it, and the reason behind each score.', 'Anchors every answer to a real task instead of a general impression. Users who finished easily move straight to the rating, users who struggled say what made it hard, and users who gave up say where it broke and what they did instead. Each score comes with a reason, and the AI follow-up asks for more when that reason is vague.', '["marketing","user satisfaction survey","product satisfaction","user feedback","UX survey","customer satisfaction"]', 'SmilePlus', 'choice', 4, 13, '{"schemaVersion":9,"title":"User satisfaction survey","description":"Learn how well your product works for the people using it, and the reason behind each score.","blocks":[{"id":"blk_usersati00","ref":"welcome","title":"We''d like to know how using our product is going for you. Five minutes at most, and your answers go straight to the team building it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_usersati01","ref":"task","title":"The last time you used it, what were you trying to get done?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_usersati02","ref":"completed","title":"Did you manage it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_easily","label":"Yes, easily","image_key":null},{"id":"opt_yes_but_it","label":"Yes, but it took some effort","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_usersati03","ref":"hard_part","title":"What made it harder than it should have been?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_usersati04","ref":"where_broke","title":"Where did it go wrong?","required":true,"visibility":null,"image_key":null,"agentHints":{"askStyle":"Ask for the step they were on and what they saw, not their opinion of the product.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_usersati05","ref":"instead","title":"What did you do instead?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_tried_again_later","label":"Tried again later","image_key":null},{"id":"opt_asked_for_help","label":"Asked for help","image_key":null},{"id":"opt_used_a_different","label":"Used a different tool","image_key":null},{"id":"opt_gave_up_on","label":"Gave up on it for now","image_key":null}],"allowOther":true},{"id":"blk_usersati06","ref":"satisfaction","title":"Overall, how satisfied are you with it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_usersati07","ref":"reason","title":"What''s the main reason for that score?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_usersati08","ref":"qualities","title":"How would you rate each of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_speed","label":"Speed"},{"id":"opt_row_reliability","label":"Reliability"},{"id":"opt_row_finding_what","label":"Finding what you need"},{"id":"opt_row_how_it","label":"How it looks and feels"},{"id":"opt_row_help_when","label":"Help when you''re stuck"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_usersati09","ref":"frequency","title":"How often do you use it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_a_few_times","label":"A few times a week","image_key":null},{"id":"opt_a_few_times_2","label":"A few times a month","image_key":null},{"id":"opt_less_often","label":"Less often","image_key":null}],"allowOther":false},{"id":"blk_usersati10","ref":"without_it","title":"How would you feel if you could no longer use it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_very_disappointed","label":"Very disappointed","image_key":null},{"id":"opt_somewhat_disappointed","label":"Somewhat disappointed","image_key":null},{"id":"opt_not_disappointed","label":"Not disappointed","image_key":null}],"allowOther":false},{"id":"blk_usersati11","ref":"one_improvement","title":"If we could improve one thing for you next, what should it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_usersati12","ref":"follow_up","title":"Could someone from the team follow up with you about your answers?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_usersati13","ref":"follow_up_email","title":"What''s the best email to reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_usersati01","ref":"end_thanks","title":"Thank you, this helps us a lot 🙏","bodyMd":"Every answer is read by the people who decide what we build next.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_usersati02","ref":"end_follow_up","title":"Thanks, we''ll be in touch","bodyMd":"Someone from the team will email you soon to hear more.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_usersati01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"hard_part","target":"satisfaction","targetKind":"block"},{"id":"rl_usersati02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"follow_up_email","target":"end_follow_up","targetKind":"ending"},{"id":"rl_usersati03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"completed"},"op":"eq","value":"opt_yes_easily"}],"groups":[]},"from":"completed","target":"satisfaction","targetKind":"block","branch":"true"},{"id":"rl_usersati04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"completed"},"op":"eq","value":"opt_yes_but_it"}],"groups":[]},"from":"completed","target":"hard_part","targetKind":"block","branch":"true"},{"id":"rl_usersati05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"completed"},"op":"eq","value":"opt_no"}],"groups":[]},"from":"completed","target":"where_broke","targetKind":"block","branch":"true"},{"id":"rl_usersati06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"follow_up"},"op":"eq","value":false}],"groups":[]},"from":"follow_up","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_usersati07","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"instead","target":"reason","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
