VALUES ('tpl_valuepropositionsurvey', 'value-proposition-survey', 'Value proposition survey', 'Survey', 'Test whether your offer''s promise is understood, relevant and believable before you build a campaign on it.', 'Shows the promise, then asks people to explain it back in their own words, which catches confusing messaging faster than any rating. Anyone for whom it isn''t relevant says who it would suit and leaves. The rest rank the benefits, score how believable the claim is, name their doubts and say what proof would win them over.', '["marketing","value proposition survey","message testing","positioning research","concept test","marketing research"]', 'Lightbulb', 'choice', 3, 11, '{"schemaVersion":9,"title":"Value proposition test","description":"Test whether your offer''s promise is understood, relevant and believable before you build a campaign on it.","blocks":[{"id":"blk_valuepro00","ref":"welcome","title":"We''re testing how we describe something new, and we''d value your honest first reaction. About three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_valuepro01","ref":"the_offer","title":"Here''s how we describe it: \"Plan a week of dinners in ten minutes, with one shopping list and no wasted food.\"","description":"Read it once, then answer the next few questions from memory.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Continue","type":"statement"},{"id":"blk_valuepro02","ref":"understanding","title":"In your own words, what does this offer do, and who is it for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_valuepro03","ref":"clarity","title":"How clear was that description?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Confusing","labelHigh":"Completely clear"},{"id":"blk_valuepro04","ref":"relevance","title":"How relevant is it to you right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_very_i_have","label":"Very, I have this problem now","image_key":null},{"id":"opt_somewhat_it_comes","label":"Somewhat, it comes up now and then","image_key":null},{"id":"opt_not_really","label":"Not really","image_key":null}],"allowOther":false},{"id":"blk_valuepro05","ref":"who_instead","title":"Who do you think it would suit instead?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":400,"aiQualityCheck":false},{"id":"blk_valuepro06","ref":"today","title":"How do you handle this today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_valuepro07","ref":"benefits","title":"Rank these benefits by how much they''d matter to you.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_it_saves","label":"It saves me time"},{"id":"opt_item_it_costs","label":"It costs less than what I do now"},{"id":"opt_item_it_s","label":"It''s easier than what I do now"},{"id":"opt_item_it_gets","label":"It gets a better result"},{"id":"opt_item_it_s_2","label":"It''s one less thing to think about"}]},{"id":"blk_valuepro08","ref":"believable","title":"How believable is the main promise?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_valuepro09","ref":"doubts","title":"What makes you hesitate, if anything?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_it_sounds_too","label":"It sounds too good to be true","image_key":null},{"id":"opt_i_m_not","label":"I''m not sure it would work for someone like me","image_key":null},{"id":"opt_i_m_worried","label":"I''m worried about the price","image_key":null},{"id":"opt_switching_from_what","label":"Switching from what I do now would be a hassle","image_key":null},{"id":"opt_nothing_i_believe","label":"Nothing, I believe it","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_valuepro10","ref":"proof","title":"What would convince you it''s true?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_reviews_from_people","label":"Reviews from people like me","image_key":null},{"id":"opt_a_free_trial","label":"A free trial","image_key":null},{"id":"opt_a_short_demo","label":"A short demo","image_key":null},{"id":"opt_a_money_back","label":"A money-back guarantee","image_key":null},{"id":"opt_clear_pricing_up","label":"Clear pricing up front","image_key":null},{"id":"opt_a_detailed_example","label":"A detailed example or case study","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":false},{"id":"blk_valuepro11","ref":"likelihood","title":"If it were available today, how likely would you be to try it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Definitely not","labelHigh":"Definitely"},{"id":"blk_valuepro12","ref":"describe_it","title":"How would you describe it to a friend, in one sentence?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200}],"endings":[{"id":"end_valuepro01","ref":"end_thanks","title":"Thank you, that''s really useful 💡","bodyMd":"Your first reaction is exactly what we needed. We''ll use it to sharpen how we describe the offer.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_valuepro02","ref":"end_not_for_me","title":"Thanks for being honest","bodyMd":"Knowing who this isn''t for is just as useful to us. That''s everything we needed.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_valuepro01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"who_instead","target":"end_not_for_me","targetKind":"ending"},{"id":"rl_valuepro02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"relevance"},"op":"eq","value":"opt_not_really"}],"groups":[]},"from":"relevance","target":"who_instead","targetKind":"block","branch":"true"},{"id":"rl_valuepro03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"relevance"},"op":"eq","value":"opt_very_i_have"}],"groups":[]},"from":"relevance","target":"today","targetKind":"block","branch":"true"},{"id":"rl_valuepro04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"relevance"},"op":"eq","value":"opt_somewhat_it_comes"}],"groups":[]},"from":"relevance","target":"today","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","