VALUES ('tpl_vendorsatisfactionsurvey', 'vendor-satisfaction-survey', 'Vendor satisfaction survey', 'Survey', 'Hear how suppliers experience working with your organisation, and fix what makes you a hard customer.', 'Turns the usual supplier review around so vendors rate you. They score the parts of the relationship you control, and anyone who says invoices are often paid late is asked what holds them up. It finishes with what would help most and an offer of a call with your purchasing team, which gets its own ending.', '["marketing","vendor satisfaction survey","supplier satisfaction survey","supplier feedback","procurement survey","vendor relationship"]', 'Handshake', 'choice', 4, 12, '{"schemaVersion":9,"title":"Vendor satisfaction survey","description":"Hear how suppliers experience working with your organisation, and fix what makes you a hard customer.","blocks":[{"id":"blk_vendorsa00","ref":"welcome","title":"We rely on our suppliers, and we''d like to be a customer that''s easy to work with. Tell us honestly how we''re doing. About four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_vendorsa01","ref":"company","title":"Which company are you answering for?","description":"Leave it blank if you''d rather stay anonymous.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_vendorsa02","ref":"relationship_length","title":"How long have you been supplying us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a year","image_key":null},{"id":"opt_1_3_years","label":"1–3 years","image_key":null},{"id":"opt_more_than_3","label":"More than 3 years","image_key":null}],"allowOther":false},{"id":"blk_vendorsa03","ref":"overall","title":"Overall, how would you rate us as a customer?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_vendorsa04","ref":"areas","title":"How do we do on each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_clear_orders","label":"Clear orders and specifications"},{"id":"opt_row_replying_to","label":"Replying to your questions quickly"},{"id":"opt_row_forecasts_and","label":"Forecasts and advance notice"},{"id":"opt_row_fairness_in","label":"Fairness in negotiations"},{"id":"opt_row_onboarding_and","label":"Onboarding and paperwork"},{"id":"opt_row_feedback_on","label":"Feedback on your performance"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_vendorsa05","ref":"payment","title":"How often are your invoices paid within the agreed terms?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_always","label":"Always","image_key":null},{"id":"opt_usually","label":"Usually","image_key":null},{"id":"opt_sometimes","label":"Sometimes","image_key":null},{"id":"opt_rarely","label":"Rarely","image_key":null}],"allowOther":false},{"id":"blk_vendorsa06","ref":"payment_issue","title":"What usually holds payment up?","required":true,"visibility":null,"image_key":null,"agentHints":{"askStyle":"Ask where in the process it stalls, such as approval, missing purchase order numbers or disputes.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_vendorsa07","ref":"one_contact","title":"Do you have one clear contact on our side who can answer your questions?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_vendorsa08","ref":"hardest","title":"What''s the hardest part of working with us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_vendorsa09","ref":"would_help","title":"Which of these would help you most?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_longer_or_more","label":"Longer or more accurate forecasts","image_key":null},{"id":"opt_faster_payment","label":"Faster payment","image_key":null},{"id":"opt_a_single_named","label":"A single named contact","image_key":null},{"id":"opt_simpler_paperwork","label":"Simpler paperwork","image_key":null},{"id":"opt_regular_performance_review","label":"Regular performance reviews","image_key":null},{"id":"opt_earlier_involvement_in","label":"Earlier involvement in new projects","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_vendorsa10","ref":"recommend","title":"How likely are you to recommend us as a customer to other suppliers?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_vendorsa11","ref":"call","title":"Would you like a call with our purchasing team about your answers?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_vendorsa12","ref":"call_contact","title":"Who should we call?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]}],"endings":[{"id":"end_vendorsa01","ref":"end_thanks","title":"Thank you for being honest with us","bodyMd":"We''ll review every answer and share what we''re changing with all our suppliers.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_vendorsa02","ref":"end_call","title":"Thank you, we''ll call you soon 📞","bodyMd":"Someone from our purchasing team will be in touch within a week to talk it through.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_vendorsa01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"call_contact","target":"end_call","targetKind":"ending"},{"id":"rl_vendorsa02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"payment"},"op":"eq","value":"opt_sometimes"}],"groups":[]},"from":"payment","target":"payment_issue","targetKind":"block","branch":"true"},{"id":"rl_vendorsa03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"payment"},"op":"eq","value":"opt_rarely"}],"groups":[]},"from":"payment","target":"payment_issue","targetKind":"block","branch":"true"},{"id":"rl_vendorsa04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"payment"},"op":"eq","value":"opt_always"}],"groups":[]},"from":"payment","target":"one_contact","targetKind":"block","branch":"true"},{"id":"rl_vendorsa05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"payment"},"op":"eq","value":"opt_usually"}],"groups":[]},"from":"payment","target":"one_contact","targetKind":"block","branch":"true"},{"id":"rl_vendorsa06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"call"},"op":"eq","value":false}],"groups":[]},"from":"call","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},