VALUES ('tpl_websiteuserexperiencesur', 'website-user-experience-survey', 'Website user experience survey', 'Survey', 'Find out where your website helps visitors finish a task and where it lets them down.', 'Built around one real visit rather than general opinions. Visitors who got what they came for rate how easy it was; anyone who got stuck picks where it went wrong and describes what happened, which is the detail a designer can use. Everyone then says how they looked for things and rates navigation, speed and readability on the device they used.', '["marketing","website user experience survey","website feedback survey","UX survey","website usability","visitor feedback"]', 'Globe', 'choice', 3, 10, '{"schemaVersion":9,"title":"Website UX survey","description":"Find out where your website helps visitors finish a task and where it lets them down.","blocks":[{"id":"blk_websiteu00","ref":"welcome","title":"Quick question about your visit today: did our website help you do what you came for? It takes two minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_websiteu01","ref":"visit_goal","title":"What did you come to the site to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_learn_about_a","label":"Learn about a product or service","image_key":null},{"id":"opt_buy_something","label":"Buy something","image_key":null},{"id":"opt_get_help_with","label":"Get help with something I already have","image_key":null},{"id":"opt_get_in_touch","label":"Get in touch with someone","image_key":null},{"id":"opt_just_browsing","label":"Just browsing","image_key":null}],"allowOther":true},{"id":"blk_websiteu02","ref":"success","title":"Were you able to do it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_partly","label":"Partly","image_key":null},{"id":"opt_no","label":"No","image_key":null},{"id":"opt_i_m_still","label":"I''m still trying","image_key":null}],"allowOther":false},{"id":"blk_websiteu03","ref":"ease","title":"How easy was it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Very hard","labelHigh":"Very easy"},{"id":"blk_websiteu04","ref":"stuck_where","title":"Where did things go wrong?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_i_couldn_t","label":"I couldn''t find the right page","image_key":null},{"id":"opt_search_didn_t","label":"Search didn''t show anything useful","image_key":null},{"id":"opt_a_page_was","label":"A page was confusing","image_key":null},{"id":"opt_something_didn_t","label":"Something didn''t load or broke","image_key":null},{"id":"opt_a_form_or","label":"A form or checkout wouldn''t work","image_key":null},{"id":"opt_the_information_i","label":"The information I needed wasn''t there","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_websiteu05","ref":"what_happened","title":"Tell us what happened, step by step if you can.","required":true,"visibility":null,"image_key":null,"agentHints":{"askStyle":"Ask which page they were on and what they clicked or expected to see.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_websiteu06","ref":"device","title":"What were you using?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_phone","label":"A phone","image_key":null},{"id":"opt_a_tablet","label":"A tablet","image_key":null},{"id":"opt_a_laptop_or","label":"A laptop or desktop","image_key":null}],"allowOther":false},{"id":"blk_websiteu07","ref":"find_method","title":"How did you mostly look for things?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_main_menu","label":"The main menu","image_key":null},{"id":"opt_the_search_box","label":"The search box","image_key":null},{"id":"opt_links_and_buttons","label":"Links and buttons on the page","image_key":null},{"id":"opt_scrolling_until_i","label":"Scrolling until I spotted it","image_key":null},{"id":"opt_i_came_straight","label":"I came straight to the right page","image_key":null}],"allowOther":false},{"id":"blk_websiteu08","ref":"aspects","title":"How would you rate the site on each of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_finding_your","label":"Finding your way around"},{"id":"opt_row_how_fast","label":"How fast pages load"},{"id":"opt_row_how_easy","label":"How easy the text is to read"},{"id":"opt_row_how_it","label":"How it works on your device"},{"id":"opt_row_how_much","label":"How much you trust the information"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_okay","label":"Okay"},{"id":"opt_col_good","label":"Good"}],"multiplePerRow":false},{"id":"blk_websiteu09","ref":"overall","title":"Overall, how would you rate your visit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_websiteu10","ref":"one_change","title":"What one change would have made your visit better?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_websiteu01","ref":"end_thanks","title":"Thank you, that helps us fix things","bodyMd":"Our team reads every answer, and the problems you described go straight onto our list.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements