VALUES ('tpl_workshopfeedbacksurvey', 'workshop-feedback-survey', 'Workshop feedback survey', 'Survey', 'Learn what participants took from a hands-on session and what support they need afterwards.', 'Made for practical sessions where people learn by doing. It rates each activity, checks the pace and the balance of explaining versus practising, then asks how ready people feel to try it alone. Confident participants name what they''ll do first; hesitant ones pick the support that would help, so you know what to send afterwards.', '["marketing","workshop feedback survey","workshop evaluation","session feedback","participant feedback","event feedback"]', 'PenTool', 'choice', 4, 12, '{"schemaVersion":9,"title":"Workshop feedback","description":"Learn what participants took from a hands-on session and what support they need afterwards.","blocks":[{"id":"blk_workshop00","ref":"welcome","title":"Thanks for joining the workshop. A few quick questions while it''s fresh, so we can make the next one better. About three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_workshop01","ref":"workshop","title":"Which workshop did you take part in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_workshop02","ref":"overall","title":"Overall, how would you rate it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_workshop03","ref":"activities","title":"How useful was each part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_the_hands","label":"The hands-on exercises"},{"id":"opt_row_the_demonstrations","label":"The demonstrations"},{"id":"opt_row_group_discussion","label":"Group discussion"},{"id":"opt_row_handouts_and","label":"Handouts and materials"}],"columns":[{"id":"opt_col_not_useful","label":"Not useful"},{"id":"opt_col_somewhat_useful","label":"Somewhat useful"},{"id":"opt_col_very_useful","label":"Very useful"},{"id":"opt_col_didn_t","label":"Didn''t happen"}],"multiplePerRow":false},{"id":"blk_workshop04","ref":"pace","title":"How was the pace?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_slow","label":"Too slow","image_key":null},{"id":"opt_about_right","label":"About right","image_key":null},{"id":"opt_too_fast","label":"Too fast","image_key":null}],"allowOther":false},{"id":"blk_workshop05","ref":"balance","title":"Was the balance between explaining and practising right?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_much_explaining","label":"Too much explaining","image_key":null},{"id":"opt_about_right","label":"About right","image_key":null},{"id":"opt_too_much_practice","label":"Too much practice","image_key":null}],"allowOther":false},{"id":"blk_workshop06","ref":"ready","title":"How ready do you feel to try this on your own?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not ready at all","labelHigh":"Completely ready"},{"id":"blk_workshop07","ref":"first_try","title":"What''s the first thing you''ll try?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_workshop08","ref":"support_needed","title":"What would help you get there?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_a_recording_of","label":"A recording of the session","image_key":null},{"id":"opt_a_step_by","label":"A step-by-step guide to follow","image_key":null},{"id":"opt_a_follow_up","label":"A follow-up practice session","image_key":null},{"id":"opt_time_with_the","label":"Time with the facilitator one-to-one","image_key":null},{"id":"opt_a_group_where","label":"A group where I can ask questions","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_workshop09","ref":"highlight","title":"Which moment was most useful to you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_workshop10","ref":"improve","title":"What would you change for the next group?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_workshop11","ref":"next_one","title":"Would you like to hear about the next workshop?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_workshop12","ref":"next_email","title":"Which email should we use?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_workshop01","ref":"end_thanks","title":"Thank you for the feedback","bodyMd":"The facilitator will read every answer before planning the next session.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_workshop02","ref":"end_next","title":"You''re on the list 🎉","bodyMd":"We''ll email you when the next workshop is announced. Thanks again for taking part.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_workshop01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"first_try","target":"highlight","targetKind":"block"},{"id":"rl_workshop02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"next_email","target":"end_next","targetKind":"ending"},{"id":"rl_workshop03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"ready"},"op":"gte","value":3}],"groups":[]},"from":"ready","target":"first_try","targetKind":"block","branch":"true"},{"id":"rl_workshop04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"ready"},"op":"lte","value":2}],"groups":[]},"from":"ready","target":"support_needed","targetKind":"block","branch":"true"},{"id":"rl_workshop05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"next_one"},"op":"eq","value":false}],"groups":[]},"from":"next_one","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
