INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_brandperceptionsurvey', 'brand-perception-survey', 'Brand perception survey', 'Survey', 'Learn the words people attach to your brand, and the experiences behind them.', 'Asks how well someone knows you before asking what they think, so the answers can be split by customers, lapsed customers and people who have only heard of you. Anyone who has never bought skips the experience grid and goes straight to how you compare, and anyone whose view has shifted is asked what shifted it.', '["marketing","brand perception","brand image","brand research","customer perception","marketing survey"]', 'Sparkles', 'choice', 3, 10, '{"schemaVersion":9,"title":"Brand perception","description":"Learn the words people attach to your brand, and the experiences behind them.","blocks":[{"id":"blk_brandper00","ref":"welcome","title":"We''re trying to see ourselves the way you see us. Five minutes, and honest answers help most.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_brandper01","ref":"familiarity","title":"How well do you know us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_buy_from","label":"I buy from you regularly","image_key":null},{"id":"opt_i_ve_bought","label":"I''ve bought once or twice","image_key":null},{"id":"opt_i_used_to","label":"I used to buy, but stopped","image_key":null},{"id":"opt_i_ve_heard","label":"I''ve heard of you, never bought","image_key":null}],"allowOther":false},{"id":"blk_brandper02","ref":"first_heard","title":"Where did you first come across us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_friend_or","label":"A friend or colleague mentioned you","image_key":null},{"id":"opt_searching_online","label":"Searching online","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_an_article_podcast","label":"An article, podcast or video","image_key":null},{"id":"opt_in_a_shop","label":"In a shop or at an event","image_key":null},{"id":"opt_i_honestly_can","label":"I honestly can''t remember","image_key":null}],"allowOther":true},{"id":"blk_brandper03","ref":"qualities","title":"Which words fit us best? Pick up to three.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_trustworthy","label":"Trustworthy","image_key":null},{"id":"opt_good_value","label":"Good value","image_key":null},{"id":"opt_premium","label":"Premium","image_key":null},{"id":"opt_innovative","label":"Innovative","image_key":null},{"id":"opt_friendly","label":"Friendly","image_key":null},{"id":"opt_reliable","label":"Reliable","image_key":null},{"id":"opt_expensive","label":"Expensive","image_key":null},{"id":"opt_old_fashioned","label":"Old-fashioned","image_key":null},{"id":"opt_forgettable","label":"Forgettable","image_key":null},{"id":"opt_confusing","label":"Confusing","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":false},{"id":"blk_brandper04","ref":"trust","title":"How much do you trust us to do what we say we''ll do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_brandper05","ref":"experience","title":"From your own experience, how do we do on each of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_quality_of","label":"Quality of what we sell"},{"id":"opt_row_fair_pricing","label":"Fair pricing"},{"id":"opt_row_customer_service","label":"Customer service"},{"id":"opt_row_keeping_promises","label":"Keeping promises on delivery"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"},{"id":"opt_col_not_sure","label":"Not sure"}],"multiplePerRow":false},{"id":"blk_brandper06","ref":"compare","title":"Compared with the alternatives you know, where do we sit?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_clearly_better","label":"Clearly better","image_key":null},{"id":"opt_a_little_better","label":"A little better","image_key":null},{"id":"opt_about_the_same","label":"About the same","image_key":null},{"id":"opt_a_little_worse","label":"A little worse","image_key":null},{"id":"opt_clearly_worse","label":"Clearly worse","image_key":null},{"id":"opt_i_don_t","label":"I don''t know the alternatives","image_key":null}],"allowOther":false},{"id":"blk_brandper07","ref":"view_changed","title":"Has your opinion of us changed since you first came across us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_brandper08","ref":"what_changed","title":"What changed it, and in which direction?","description":"A specific moment, like an order, an ad or a conversation, is the most useful thing you can tell us.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_brandper09","ref":"recommend","title":"How likely are you to recommend us to a friend or colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_brandper10","ref":"one_sentence","title":"How would you describe us to someone who has never heard of us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":400,"aiQualityCheck":false}],"endings":[{"id":"end_brandper01","ref":"end_thanks","title":"Thank you for being straight with us","bodyMd":"Your answers go to the people who decide how we present ourselves, and they read every one.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_brandper01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"familiarity"},"op":"eq","value":"opt_i_ve_heard"}],"groups":[]},"from":"familiarity","target":"compare","targetKind":"block","branch":"true"},{"id":"rl_brandper02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"view_changed"},"op":"eq","value":false}],"groups":[]},"from":"view_changed","target":"recommend","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#f26b1d","surface":"#fff7f0","text":"#1c1917","accent":"#1c1917","accentText":"#ffffff","botBubble":"#fff7f0","userBubble":"#1c1917","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundPatternColor":"#1c1917","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
