INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_brandpersonalitysurvey', 'brand-personality-survey', 'Brand personality survey', 'Survey', 'See whether the personality people feel matches the one you meant to build.', 'Uses sliders between opposite traits, like serious and playful or traditional and modern, so you get positions you can compare with your brand guidelines rather than a pile of adjectives. Anyone who feels your words and your actions don''t match is asked where the gap shows up.', '["marketing","brand personality","brand voice","tone of voice","brand archetype","brand research"]', 'Palette', 'choice', 3, 10, '{"schemaVersion":9,"title":"Brand personality","description":"See whether the personality people feel matches the one you meant to build.","blocks":[{"id":"blk_brandper00","ref":"welcome","title":"Quick one: if our brand were a person, what would they be like? No right answers here.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_brandper01","ref":"relationship","title":"How do you know us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_m_a","label":"I''m a customer","image_key":null},{"id":"opt_i_follow_you","label":"I follow you online","image_key":null},{"id":"opt_i_ve_only","label":"I''ve only seen your ads or posts","image_key":null},{"id":"opt_i_work_with","label":"I work with you as a partner","image_key":null}],"allowOther":false},{"id":"blk_brandper02","ref":"traits","title":"Which of these traits sound most like us? Pick up to three.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_warm","label":"Warm","image_key":null},{"id":"opt_clever","label":"Clever","image_key":null},{"id":"opt_playful","label":"Playful","image_key":null},{"id":"opt_calm","label":"Calm","image_key":null},{"id":"opt_bold","label":"Bold","image_key":null},{"id":"opt_practical","label":"Practical","image_key":null},{"id":"opt_elegant","label":"Elegant","image_key":null},{"id":"opt_down_to_earth","label":"Down to earth","image_key":null},{"id":"opt_rebellious","label":"Rebellious","image_key":null},{"id":"opt_serious","label":"Serious","image_key":null},{"id":"opt_pushy","label":"Pushy","image_key":null},{"id":"opt_distant","label":"Distant","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":false},{"id":"blk_brandper03","ref":"serious_playful","title":"Where do we sit between serious and playful?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":7,"startAt":1,"labelLow":"Serious","labelHigh":"Playful"},{"id":"blk_brandper04","ref":"traditional_modern","title":"And between traditional and modern?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":7,"startAt":1,"labelLow":"Traditional","labelHigh":"Modern"},{"id":"blk_brandper05","ref":"quiet_bold","title":"And between understated and bold?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":7,"startAt":1,"labelLow":"Understated","labelHigh":"Bold"},{"id":"blk_brandper06","ref":"voice","title":"When we write to you, who does it sound like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_friend_who","label":"A friend who knows their stuff","image_key":null},{"id":"opt_a_patient_expert","label":"A patient expert","image_key":null},{"id":"opt_an_enthusiastic_salesperso","label":"An enthusiastic salesperson","image_key":null},{"id":"opt_a_big_formal","label":"A big, formal company","image_key":null},{"id":"opt_it_changes_a","label":"It changes a lot","image_key":null}],"allowOther":false},{"id":"blk_brandper07","ref":"as_a_person","title":"Imagine we walked into a room as a person. How would they come across?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_brandper08","ref":"words_match","title":"Does the way we talk match the way we actually treat you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_brandper09","ref":"mismatch","title":"Where does the gap show up?","description":"For example, a friendly website but a stiff support email.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_brandper10","ref":"similar_brand","title":"Which other brand, in any industry, feels most like us?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120}],"endings":[{"id":"end_brandper01","ref":"end_thanks","title":"Thanks, that''s a great help","bodyMd":"We''ll put your answers next to the personality we set out to have and see how close we got.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_brandper01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"words_match"},"op":"eq","value":true}],"groups":[]},"from":"words_match","target":"similar_brand","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f3e6ff","surface":"#ffffff","text":"#2b1638","accent":"#9333ea","accentText":"#fdf9ff","botBubble":"#ffffff","userBubble":"#9333ea","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"confetti","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
