VALUES ('tpl_businessimpactsurvey', 'business-impact-survey', 'Business impact survey', 'Survey', 'See how a change is really landing, team by team, and what support would help.', 'Built for the weeks after a reorganisation, a new system, a price change or an outside event. A grid rates the effect on workload, speed, quality, customers and costs, and the overall verdict decides the follow-up: people seeing gains describe them, people struggling describe the disruption, and everyone picks the support that would help.', '["marketing","business impact survey","change impact","impact assessment","change management","operations survey"]', 'Gauge', 'choice', 3, 10, '{"schemaVersion":9,"title":"Business impact","description":"See how a change is really landing, team by team, and what support would help.","blocks":[{"id":"blk_business00","ref":"welcome","title":"We want to understand how the recent change is affecting your work. It takes about four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_business01","ref":"change","title":"Which change are you telling us about?","description":"For example, the new ordering system or the move to a hybrid schedule.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_business02","ref":"team","title":"Which team or area do you work in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_sales","label":"Sales","image_key":null},{"id":"opt_marketing","label":"Marketing","image_key":null},{"id":"opt_customer_support","label":"Customer support","image_key":null},{"id":"opt_operations_or_logistics","label":"Operations or logistics","image_key":null},{"id":"opt_finance","label":"Finance","image_key":null},{"id":"opt_product_or_engineering","label":"Product or engineering","image_key":null},{"id":"opt_hr_or_people","label":"HR or people","image_key":null},{"id":"opt_leadership","label":"Leadership","image_key":null},{"id":"opt_other","label":"Other","image_key":null}]},{"id":"blk_business03","ref":"working_level","title":"Right now, how close to normal is your team working?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Badly disrupted","labelHigh":"Fully normal"},{"id":"blk_business04","ref":"effects","title":"How has the change affected each of these for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_my_workload","label":"My workload"},{"id":"opt_row_how_fast","label":"How fast things get done"},{"id":"opt_row_quality_of","label":"Quality of our work"},{"id":"opt_row_our_customers","label":"Our customers or clients"},{"id":"opt_row_costs","label":"Costs"}],"columns":[{"id":"opt_col_much_worse","label":"Much worse"},{"id":"opt_col_worse","label":"Worse"},{"id":"opt_col_no_change","label":"No change"},{"id":"opt_col_better","label":"Better"},{"id":"opt_col_much_better","label":"Much better"}],"multiplePerRow":false},{"id":"blk_business05","ref":"overall","title":"Taking everything together, how has it gone so far?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_mostly_positive","label":"Mostly positive","image_key":null},{"id":"opt_mixed","label":"Mixed","image_key":null},{"id":"opt_mostly_negative","label":"Mostly negative","image_key":null},{"id":"opt_too_early_to","label":"Too early to say","image_key":null}],"allowOther":false},{"id":"blk_business06","ref":"gains","title":"What has got better? An example helps us keep it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_business07","ref":"disruption","title":"What has been hardest? Tell us about a moment when it got in the way.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_business08","ref":"revenue","title":"What do you expect it to do to revenue or results in your area?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_increase_them","label":"Increase them","image_key":null},{"id":"opt_no_real_effect","label":"No real effect","image_key":null},{"id":"opt_reduce_them","label":"Reduce them","image_key":null},{"id":"opt_i_don_t","label":"I don''t know","image_key":null}],"allowOther":false},{"id":"blk_business09","ref":"support","title":"What would help you most from here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_clearer_information_about","label":"Clearer information about what''s changing","image_key":null},{"id":"opt_training","label":"Training","image_key":null},{"id":"opt_more_people_or","label":"More people or time","image_key":null},{"id":"opt_better_tools","label":"Better tools","image_key":null},{"id":"opt_a_chance_to","label":"A chance to raise concerns with leadership","image_key":null},{"id":"opt_nothing_we_re","label":"Nothing, we''re fine","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_business10","ref":"anything_else","title":"Anything else leadership should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_business01","ref":"end_thanks","title":"Thanks, this helps us plan the next step","bodyMd":"We''ll share what we heard, and what we''re doing about it, with everyone who took part.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_business01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"gains","target":"revenue","targetKind":"block"},{"id":"rl_business02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"eq","value":"opt_mostly_positive"}],"groups":[]},"from":"overall","target":"gains","targetKind":"block","branch":"true"},{"id":"rl_business03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"eq","value":"opt_mixed"}],"groups":[]},"from":"overall","target":"disruption","targetKind":"block","branch":"true"},{"id":"rl_business04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"eq","value":"opt_mostly_negative"}],"groups":[]},"from":"overall","target":"disruption","targetKind":"block","branch":"true"},{"id":"rl_business05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"eq","value":"opt_too_early_to"}],"groups":[]},"from":"overall","target":"revenue","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
