INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_churnsurvey', 'churn-survey', 'Churn survey', 'Survey', 'Learn why customers left or went quiet, and when the product stopped being worth it.', 'Works for people who cancelled and for people who simply stopped using you, and asks when the product stopped feeling worth it so you can see where value falls away. Every reason gets its own follow-up: a cheaper option, the missing feature, the competitor and why, what got in the way, what changed in their needs or what kept it out of their routine. Only people open to coming back are asked what it would take and for an email.', '["marketing","churn survey","customer churn","why customers leave","lost customer feedback","customer retention"]', 'LogOut', 'choice', 4, 16, '{"schemaVersion":9,"title":"Churn survey","description":"Learn why customers left or went quiet, and when the product stopped being worth it.","blocks":[{"id":"blk_churnsur00","ref":"welcome","title":"We noticed you''ve stepped away, and we''d like to understand why. It takes two minutes and shapes what we fix next.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_churnsur01","ref":"status","title":"Which of these fits you best?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_cancelled_my","label":"I cancelled my account","image_key":null},{"id":"opt_i_still_have","label":"I still have an account but stopped using it","image_key":null},{"id":"opt_i_m_about","label":"I''m about to cancel","image_key":null}],"allowOther":false},{"id":"blk_churnsur02","ref":"used_for","title":"What did you mainly use us for?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_churnsur03","ref":"tenure","title":"How long were you with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a month","image_key":null},{"id":"opt_1_6_months","label":"1–6 months","image_key":null},{"id":"opt_6_12_months","label":"6–12 months","image_key":null},{"id":"opt_more_than_a","label":"More than a year","image_key":null}],"allowOther":false},{"id":"blk_churnsur04","ref":"reason","title":"What''s the main reason you''re leaving?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_cost_too","label":"It cost too much for what I got","image_key":null},{"id":"opt_it_was_missing","label":"It was missing something I needed","image_key":null},{"id":"opt_i_switched_to","label":"I switched to another product","image_key":null},{"id":"opt_it_was_hard","label":"It was hard to use","image_key":null},{"id":"opt_too_many_bugs","label":"Too many bugs or problems","image_key":null},{"id":"opt_i_wasn_t","label":"I wasn''t using it enough","image_key":null},{"id":"opt_my_needs_changed","label":"My needs changed","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_churnsur05","ref":"cheaper_plan","title":"Would a cheaper option with fewer features have kept you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_churnsur06","ref":"missing","title":"What was missing? Tell us what you were trying to do.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_churnsur07","ref":"competitor","title":"Which product did you move to?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_churnsur08","ref":"competitor_why","title":"What does it do better for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_churnsur09","ref":"friction","title":"Tell us a bit more about what happened. A specific moment helps most.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_churnsur10","ref":"needs_changed","title":"What changed for you?","description":"For example, a new job, a finished project or a smaller team.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_churnsur11","ref":"low_use","title":"What got in the way of using it more often?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_churnsur12","ref":"when_value_dropped","title":"When did it stop feeling worth it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_right_from_the","label":"Right from the start","image_key":null},{"id":"opt_after_the_first","label":"After the first few weeks","image_key":null},{"id":"opt_after_months_of","label":"After months of use","image_key":null},{"id":"opt_only_recently","label":"Only recently","image_key":null},{"id":"opt_it_still_felt","label":"It still felt worth it, my situation changed","image_key":null}],"allowOther":false},{"id":"blk_churnsur13","ref":"overall","title":"Overall, how would you rate your time with us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_churnsur14","ref":"come_back","title":"Is there anything that would bring you back?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_churnsur15","ref":"bring_back","title":"What would it take?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_churnsur16","ref":"email","title":"If we fix it, can we let you know? Leave your email, or skip this.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_churnsur01","ref":"end_thanks","title":"Thank you, and good luck","bodyMd":"Your answer goes straight to the team deciding what we build and fix next. The door is always open.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_churnsur01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"cheaper_plan","target":"when_value_dropped","targetKind":"block"},{"id":"rl_churnsur02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"missing","target":"when_value_dropped","targetKind":"block"},{"id":"rl_churnsur03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"competitor_why","target":"when_value_dropped","targetKind":"block"},{"id":"rl_churnsur04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"friction","target":"when_value_dropped","targetKind":"block"},{"id":"rl_churnsur05","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"needs_changed","target":"when_value_dropped","targetKind":"block"},{"id":"rl_churnsur06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_it_cost_too"}],"groups":[]},"from":"reason","target":"cheaper_plan","targetKind":"block","branch":"true"},{"id":"rl_churnsur07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_it_was_missing"}],"groups":[]},"from":"reason","target":"missing","targetKind":"block","branch":"true"},{"id":"rl_churnsur08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_i_switched_to"}],"groups":[]},"from":"reason","target":"competitor","targetKind":"block","branch":"true"},{"id":"rl_churnsur09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_it_was_hard"}],"groups":[]},"from":"reason","target":"friction","targetKind":"block","branch":"true"},{"id":"rl_churnsur10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_too_many_bugs"}],"groups":[]},"from":"reason","target":"friction","targetKind":"block","branch":"true"},{"id":"rl_churnsur11","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_something_else"}],"groups":[]},"from":"reason","target":"friction","targetKind":"block","branch":"true"},{"id":"rl_churnsur12","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_my_needs_changed"}],"groups":[]},"from":"reason","target":"needs_changed","targetKind":"block","branch":"true"},{"id":"rl_churnsur13","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reason"},"op":"eq","value":"opt_i_wasn_t"}],"groups":[]},"from":"reason","target":"low_use","targetKind":"block","branch":"true"},{"id":"rl_churnsur14","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"come_back"},"op":"eq","value":false}],"groups":[]},"from":"come_back","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#d9f2e6","surface":"#ffffff","text":"#12342a","accent":"#0f766e","accentText":"#f5fffb","botBubble":"#ffffff","userBubble":"#0f766e","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"b