INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_clientquestionnaire', 'client-questionnaire', 'Client questionnaire', 'Survey', 'Understand a client''s goals and context before you recommend anything.', 'Covers what you need before a discovery call: who you''ll work with, what the business does, what success looks like, what''s in the way and what has been tried. If the person filling it in isn''t the day-to-day contact, it asks who is, and a budget amount is only requested from clients who already have one in mind.', '["marketing","client questionnaire","new client questionnaire","discovery questionnaire","agency onboarding","freelance clients"]', 'Briefcase', 'choice', 4, 14, '{"schemaVersion":9,"title":"Client questionnaire","description":"Understand a client''s goals and context before you recommend anything.","blocks":[{"id":"blk_clientqu00","ref":"welcome","title":"Looking forward to working together. A few questions first, so our first call can get straight to the useful part.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_clientqu01","ref":"contact","title":"Let''s start with you. Who are we talking to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email","phone"]},{"id":"blk_clientqu02","ref":"company","title":"What''s the name of your business?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_clientqu03","ref":"primary_contact","title":"Will you be our main contact day to day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_clientqu04","ref":"day_to_day","title":"Who should we work with, and how do we reach them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_clientqu05","ref":"business","title":"In a few sentences, what does your business do, and who are your customers?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_clientqu06","ref":"services","title":"Which kinds of help are you looking for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_strategy_and_planning","label":"Strategy and planning","image_key":null},{"id":"opt_brand_and_design","label":"Brand and design","image_key":null},{"id":"opt_website","label":"Website","image_key":null},{"id":"opt_content_and_copywriting","label":"Content and copywriting","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_paid_advertising","label":"Paid advertising","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_clientqu07","ref":"success","title":"Six months from now, what would make this a success for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_clientqu08","ref":"challenge","title":"What''s getting in the way at the moment?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_clientqu09","ref":"tried","title":"What have you already tried, and how did it go?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_clientqu10","ref":"budget_status","title":"Where are you with budget?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_we_have_a","label":"We have a set budget","image_key":null},{"id":"opt_we_have_a_2","label":"We have a rough range","image_key":null},{"id":"opt_we_d_like","label":"We''d like your advice on it","image_key":null}],"allowOther":false},{"id":"blk_clientqu11","ref":"budget_amount","title":"Roughly how much, in your currency?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_clientqu12","ref":"deadline","title":"Is there a date this needs to be ready by?","description":"Skip this if there''s no fixed deadline.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_clientqu13","ref":"decision","title":"Who else is involved in decisions on this?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_me_and_a","label":"Me and a business partner","image_key":null},{"id":"opt_a_small_team","label":"A small team","image_key":null},{"id":"opt_a_board_or","label":"A board or senior leadership","image_key":null}],"allowOther":false},{"id":"blk_clientqu14","ref":"anything_else","title":"Anything else we should know before we talk?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_clientqu01","ref":"end_thanks","title":"Thanks, we''ve got everything we need","bodyMd":"We''ll read through this before we speak and come to the call with ideas, not a list of questions.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_clientqu01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"primary_contact"},"op":"eq","value":true}],"groups":[]},"from":"primary_contact","target":"business","targetKind":"block","branch":"true"},{"id":"rl_clientqu02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"budget_status"},"op":"eq","value":"opt_we_d_like"}],"groups":[]},"from":"budget_status","target":"deadline","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
