INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_conferenceevaluationsurv', 'conference-evaluation-survey', 'Conference evaluation survey', 'Survey', 'Hear what attendees valued and what to change before next year''s conference.', 'Asks for the overall verdict first, then follows it: attendees who loved it name their highlight, and those who didn''t say what let them down. A grid rates keynotes, breakouts, networking, venue, food and scheduling, so you can separate a strong programme from a weak venue. It also asks what attendees will use at work and how many useful contacts they made, the two things most people go to a conference for, and closes with topics for next year.', '["marketing","conference evaluation","conference feedback survey","post-event survey","attendee feedback","event evaluation"]', 'Mic', 'choice', 4, 13, '{"schemaVersion":9,"title":"Conference evaluation","description":"Hear what attendees valued and what to change before next year''s conference.","blocks":[{"id":"blk_conferen00","ref":"welcome","title":"Thanks for coming to the conference. Tell us how it went for you, and help shape the next one.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_conferen01","ref":"attended_as","title":"How did you take part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_attendee","label":"Attendee","image_key":null},{"id":"opt_speaker","label":"Speaker","image_key":null},{"id":"opt_sponsor_or_exhibitor","label":"Sponsor or exhibitor","image_key":null},{"id":"opt_volunteer","label":"Volunteer","image_key":null}],"allowOther":false},{"id":"blk_conferen02","ref":"overall","title":"Overall, how would you rate the conference?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_conferen03","ref":"highlight","title":"What was the highlight for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_conferen04","ref":"let_down","title":"What let you down? Be as specific as you like.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_conferen05","ref":"aspects","title":"How did each part of the conference work for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_keynotes","label":"Keynotes"},{"id":"opt_row_breakout_sessions","label":"Breakout sessions"},{"id":"opt_row_networking","label":"Networking"},{"id":"opt_row_venue_and","label":"Venue and facilities"},{"id":"opt_row_food_and","label":"Food and drink"},{"id":"opt_row_schedule_and","label":"Schedule and timing"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"},{"id":"opt_col_didn_t","label":"Didn''t use"}],"multiplePerRow":false},{"id":"blk_conferen06","ref":"best_session","title":"Which talk or speaker will you remember a month from now?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_conferen07","ref":"takeaway","title":"What''s one idea from the conference you''ll put to use in your work?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_conferen08","ref":"contacts","title":"Roughly how many useful new contacts did you make?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_conferen09","ref":"content_level","title":"Was the content pitched at the right level for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_basic","label":"Too basic","image_key":null},{"id":"opt_about_right","label":"About right","image_key":null},{"id":"opt_too_advanced","label":"Too advanced","image_key":null},{"id":"opt_it_varied_a","label":"It varied a lot between sessions","image_key":null}],"allowOther":false},{"id":"blk_conferen10","ref":"worth_it","title":"Did what you took away justify the ticket and the time away from work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Easily"},{"id":"blk_conferen11","ref":"recommend","title":"How likely are you to recommend this conference to a colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_conferen12","ref":"return","title":"Would you come back next year?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_maybe","label":"Maybe","image_key":null},{"id":"opt_no","label":"No","image_key":null}],"allowOther":false},{"id":"blk_conferen13","ref":"next_topics","title":"Which topics or speakers would you like to see next time?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_conferen01","ref":"end_thanks","title":"Thank you, see you next time 👋","bodyMd":"The organising team reads every response while planning the next conference.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_conferen01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"highlight","target":"aspects","targetKind":"block"},{"id":"rl_conferen02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"gte","value":4}],"groups":[]},"from":"overall","target":"highlight","targetKind":"block","branch":"true"},{"id":"rl_conferen03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"lte","value":3}],"groups":[]},"from":"overall","target":"let_down","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#5b2ee6","surface":"#4a22c9","text":"#ffffff","accent":"#ffd166","accentText":"#1c1917","botBubble":"#4a22c9","userBubble":"#ffd166","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundPatternColor":"#ffffff","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
