VALUES ('tpl_consumerbehaviorsurvey', 'consumer-behavior-survey', 'Consumer behavior survey', 'Survey', 'Understand real buying decisions by asking about one recent purchase.', 'Anchored on one real, recent purchase instead of general shopping habits, so answers describe what people did rather than what they think they do. It follows the purchase from trigger to research to the deciding factor, skips the comparison question for people who didn''t shop around, and asks less happy buyers what they would do differently.', '["marketing","consumer behavior survey","buying behavior","purchase decision","shopper research","market research"]', 'ShoppingBag', 'choice', 4, 11, '{"schemaVersion":9,"title":"Consumer behavior","description":"Understand real buying decisions by asking about one recent purchase.","blocks":[{"id":"blk_consumer00","ref":"welcome","title":"We''re studying how people make buying decisions. Think of one recent purchase and we''ll walk through it together.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_consumer01","ref":"item","title":"Think of the last thing you bought that took some thought, not an everyday top-up. What was it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_consumer02","ref":"when","title":"When did you buy it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_the_last","label":"In the last week","image_key":null},{"id":"opt_in_the_last_2","label":"In the last month","image_key":null},{"id":"opt_1_3_months","label":"1–3 months ago","image_key":null},{"id":"opt_longer_ago","label":"Longer ago","image_key":null}],"allowOther":false},{"id":"blk_consumer03","ref":"trigger","title":"What made you start looking?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_something_broke_or","label":"Something broke or ran out","image_key":null},{"id":"opt_a_new_need","label":"A new need or a change in my life","image_key":null},{"id":"opt_an_ad_or","label":"An ad or a post I saw","image_key":null},{"id":"opt_someone_recommended_it","label":"Someone recommended it","image_key":null},{"id":"opt_a_sale_or","label":"A sale or discount","image_key":null},{"id":"opt_i_just_wanted","label":"I just wanted to treat myself","image_key":null}],"allowOther":true},{"id":"blk_consumer04","ref":"research","title":"Where did you look before deciding?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_search_engines","label":"Search engines","image_key":null},{"id":"opt_review_sites_or","label":"Review sites or ratings","image_key":null},{"id":"opt_social_media_or","label":"Social media or videos","image_key":null},{"id":"opt_friends_or_family","label":"Friends or family","image_key":null},{"id":"opt_the_brand_s","label":"The brand''s own website","image_key":null},{"id":"opt_in_a_shop","label":"In a shop","image_key":null},{"id":"opt_i_didn_t","label":"I didn''t look around","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_consumer05","ref":"options_compared","title":"How many options did you seriously consider?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_the_one","label":"Just the one I bought","image_key":null},{"id":"opt_2_or_3","label":"2 or 3","image_key":null},{"id":"opt_4_or_more","label":"4 or more","image_key":null}],"allowOther":false},{"id":"blk_consumer06","ref":"deciding_factors","title":"Put these in order of how much they decided it for you.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_price","label":"Price"},{"id":"opt_item_quality","label":"Quality"},{"id":"opt_item_a_brand","label":"A brand I trust"},{"id":"opt_item_reviews","label":"Reviews"},{"id":"opt_item_delivery_or","label":"Delivery or availability"},{"id":"opt_item_a_recommendation","label":"A recommendation"}]},{"id":"blk_consumer07","ref":"where_bought","title":"Where did you buy it in the end?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_large_online","label":"A large online marketplace","image_key":null},{"id":"opt_the_brand_s","label":"The brand''s own website","image_key":null},{"id":"opt_a_physical_shop","label":"A physical shop","image_key":null},{"id":"opt_through_an_app","label":"Through an app","image_key":null},{"id":"opt_somewhere_else","label":"Somewhere else","image_key":null}],"allowOther":false},{"id":"blk_consumer08","ref":"happy_now","title":"How happy are you with the purchase now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_consumer09","ref":"do_differently","title":"What would you do differently if you bought it again?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_consumer10","ref":"buy_again","title":"Would you buy from the same place again?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_consumer11","ref":"age_range","title":"Last one: which age group are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_25","label":"Under 25","image_key":null},{"id":"opt_25_34","label":"25–34","image_key":null},{"id":"opt_35_44","label":"35–44","image_key":null},{"id":"opt_45_54","label":"45–54","image_key":null},{"id":"opt_55_or_over","label":"55 or over","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false}],"endings":[{"id":"end_consumer01","ref":"end_thanks","title":"That''s everything, thank you","bodyMd":"Your purchase story joins everyone else''s and helps us see how real decisions get made.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_consumer01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"research"},"op":"includes","value":"opt_i_didn_t"}],"groups":[]},"from":"research","target":"deciding_factors","targetKind":"block","branch":"true"},{"id":"rl_consumer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"happy_now"},"op":"gte","value":4}],"groups":[]},"from":"happy_now","target":"buy_again","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
