INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_consumerpreferencesurvey', 'consumer-preference-survey', 'Consumer preference survey', 'Survey', 'Find out which features matter, which trade-offs people accept, and what makes them switch.', 'Goes past ''what do you like'' to the choices that shape a product: a ranking of priorities, a grid that separates nice-to-haves from deal-breakers, and direct trade-off questions on price and sustainability. People who wouldn''t switch from their current brand are asked what keeps them loyal, and everyone else describes the product they''d switch for.', '["marketing","consumer preference survey","customer preferences","product preferences","feature priorities","market research"]', 'ListOrdered', 'choice', 3, 11, '{"schemaVersion":9,"title":"Consumer preferences","description":"Find out which features matter, which trade-offs people accept, and what makes them switch.","blocks":[{"id":"blk_consumer00","ref":"welcome","title":"We''re designing something new and want it to fit how you actually choose. A few quick questions.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_consumer01","ref":"frequency","title":"How often do you buy or use this kind of product?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_week","label":"Every week","image_key":null},{"id":"opt_every_month_or","label":"Every month or so","image_key":null},{"id":"opt_a_few_times","label":"A few times a year","image_key":null},{"id":"opt_rarely","label":"Rarely","image_key":null}],"allowOther":false},{"id":"blk_consumer02","ref":"current_choice","title":"Which brand or product do you use most at the moment?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_consumer03","ref":"priorities","title":"Rank these from most to least important when you choose.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_price","label":"Price"},{"id":"opt_item_quality_and","label":"Quality and durability"},{"id":"opt_item_convenience","label":"Convenience"},{"id":"opt_item_design","label":"Design"},{"id":"opt_item_environmental_impact","label":"Environmental impact"},{"id":"opt_item_brand_reputation","label":"Brand reputation"}]},{"id":"blk_consumer04","ref":"importance","title":"How much does each of these matter to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_a_low","label":"A low price"},{"id":"opt_row_lasting_a","label":"Lasting a long time"},{"id":"opt_row_recyclable_packaging","label":"Recyclable packaging"},{"id":"opt_row_fast_delivery","label":"Fast delivery"},{"id":"opt_row_a_well","label":"A well-known brand"},{"id":"opt_row_helpful_customer","label":"Helpful customer service"}],"columns":[{"id":"opt_col_doesn_t","label":"Doesn''t matter"},{"id":"opt_col_nice_to","label":"Nice to have"},{"id":"opt_col_important","label":"Important"},{"id":"opt_col_deal_breaker","label":"Deal-breaker"}],"multiplePerRow":false},{"id":"blk_consumer05","ref":"tradeoff","title":"If you had to choose, which would you buy?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_cheaper_version","label":"A cheaper version that does the basics","image_key":null},{"id":"opt_a_pricier_version","label":"A pricier version that does more","image_key":null},{"id":"opt_it_depends_on","label":"It depends on what it''s for","image_key":null}],"allowOther":false},{"id":"blk_consumer06","ref":"green_premium","title":"How willing are you to pay a little more for a version that''s better for the environment?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not willing","labelHigh":"Very willing"},{"id":"blk_consumer07","ref":"switch","title":"What would make you switch from what you use now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_lower_price","label":"A lower price","image_key":null},{"id":"opt_better_quality","label":"Better quality","image_key":null},{"id":"opt_something_more_convenient","label":"Something more convenient","image_key":null},{"id":"opt_a_brand_with","label":"A brand with values I share","image_key":null},{"id":"opt_nothing_i_m","label":"Nothing, I''m happy with what I use","image_key":null}],"allowOther":false},{"id":"blk_consumer08","ref":"ideal","title":"Describe the product you''d switch for. What would it do that yours doesn''t?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_consumer09","ref":"loyalty","title":"What keeps you with your current choice?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_consumer10","ref":"turn_off","title":"Is there anything that would put you off a product like this straight away?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_consumer11","ref":"age_range","title":"Which age group are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_25","label":"Under 25","image_key":null},{"id":"opt_25_34","label":"25–34","image_key":null},{"id":"opt_35_44","label":"35–44","image_key":null},{"id":"opt_45_54","label":"45–54","image_key":null},{"id":"opt_55_or_over","label":"55 or over","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false}],"endings":[{"id":"end_consumer01","ref":"end_thanks","title":"Thank you, that''s really useful","bodyMd":"Your priorities go straight into how we shape the product.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_consumer01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"ideal","target":"turn_off","targetKind":"block"},{"id":"rl_consumer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"switch"},"op":"eq","value":"opt_nothing_i_m"}],"groups":[]},"from":"switch","target":"loyalty","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
