VALUES ('tpl_corporatesocialresponsib', 'corporate-social-responsibility-csr-survey', 'Corporate social responsibility survey', 'Survey', 'Learn which causes matter to your people and whether your current efforts feel real.', 'Separates three things that usually get mixed up: how much people care, how much they know about what you already do, and whether they believe it. People who know nothing about your work skip the credibility question, and people who find your efforts unconvincing are asked what would change their mind.', '["marketing","CSR survey","corporate social responsibility","sustainability survey","ESG survey","employee engagement"]', 'Leaf', 'choice', 3, 10, '{"schemaVersion":9,"title":"CSR survey","description":"Learn which causes matter to your people and whether your current efforts feel real.","blocks":[{"id":"blk_corporat00","ref":"welcome","title":"We''re deciding where to focus our social and environmental work, and we''d like your view. About four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_corporat01","ref":"relationship","title":"What''s your connection to us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_work_here","label":"I work here","image_key":null},{"id":"opt_i_m_a","label":"I''m a customer","image_key":null},{"id":"opt_i_m_a_2","label":"I''m a supplier or partner","image_key":null},{"id":"opt_i_live_or","label":"I live or work nearby","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_corporat02","ref":"importance","title":"How much does it matter to you that we act responsibly toward people and the planet?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"A great deal"},{"id":"blk_corporat03","ref":"awareness","title":"How much do you know about what we currently do in this area?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_nothing_at_all","label":"Nothing at all","image_key":null},{"id":"opt_a_little","label":"A little","image_key":null},{"id":"opt_a_fair_amount","label":"A fair amount","image_key":null},{"id":"opt_a_lot","label":"A lot","image_key":null}],"allowOther":false},{"id":"blk_corporat04","ref":"credibility","title":"How genuine do our current efforts seem to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Mostly talk","labelHigh":"Real and visible"},{"id":"blk_corporat05","ref":"make_it_real","title":"What would make our efforts feel more real to you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_corporat06","ref":"priorities","title":"Which issues should we focus on? Put them in order.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_reducing_our","label":"Reducing our environmental impact"},{"id":"opt_item_fair_pay","label":"Fair pay and treatment of workers"},{"id":"opt_item_diversity_and","label":"Diversity and inclusion"},{"id":"opt_item_supporting_local","label":"Supporting local communities"},{"id":"opt_item_ethical_sourcing","label":"Ethical sourcing"},{"id":"opt_item_protecting_customer","label":"Protecting customer data"}]},{"id":"blk_corporat07","ref":"one_thing","title":"If we could do one thing better next year, what should it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_corporat08","ref":"influence","title":"Does a company''s record on these issues affect whether you buy from or work with them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_a_lot","label":"Yes, a lot","image_key":null},{"id":"opt_somewhat","label":"Somewhat","image_key":null},{"id":"opt_not_really","label":"Not really","image_key":null}],"allowOther":false},{"id":"blk_corporat09","ref":"take_part","title":"Would you like to take part in any of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_volunteering_days","label":"Volunteering days","image_key":null},{"id":"opt_fundraising","label":"Fundraising","image_key":null},{"id":"opt_sharing_ideas_in","label":"Sharing ideas in a working group","image_key":null},{"id":"opt_not_right_now","label":"Not right now","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":false},{"id":"blk_corporat10","ref":"updates","title":"How would you like to hear about our progress?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_short_yearly","label":"A short yearly report","image_key":null},{"id":"opt_occasional_email_updates","label":"Occasional email updates","image_key":null},{"id":"opt_posts_on_our","label":"Posts on our website or social pages","image_key":null},{"id":"opt_i_d_rather","label":"I''d rather not hear about it","image_key":null}],"allowOther":false}],"endings":[{"id":"end_corporat01","ref":"end_thanks","title":"Thank you for helping us choose","bodyMd":"We''ll publish what we heard and the priorities we set because of it.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_corporat01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"awareness"},"op":"eq","value":"opt_nothing_at_all"}],"groups":[]},"from":"awareness","target":"priorities","targetKind":"block","branch":"true"},{"id":"rl_corporat02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"credibility"},"op":"gte","value":4}],"groups":[]},"from":"credibility","target":"priorities","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
