VALUES ('tpl_customeranalysissurvey', 'customer-analysis-survey', 'Customer analysis survey', 'Survey', 'Understand who buys from you, what problem they had and why they chose you.', 'Starts by asking whether the customer bought for themselves or for a business, then asks the background questions that fit: company size and role for business buyers, age range for everyone else. After that everyone describes the problem they had, the alternatives they weighed and the real reason they chose you.', '["marketing","customer analysis survey","customer profile","customer research","buyer persona","why customers buy"]', 'PieChart', 'choice', 4, 12, '{"schemaVersion":9,"title":"Customer analysis","description":"Understand who buys from you, what problem they had and why they chose you.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"Thanks for being a customer. We''d love to understand you a little better. It takes about four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"buyer_type","title":"Did you buy from us for yourself or for work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_for_myself_or","label":"For myself or my household","image_key":null},{"id":"opt_for_my_business","label":"For my business or employer","image_key":null}],"allowOther":false},{"id":"blk_customer02","ref":"company_size","title":"How many people work at your organisation?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_2_10","label":"2–10","image_key":null},{"id":"opt_11_50","label":"11–50","image_key":null},{"id":"opt_51_250","label":"51–250","image_key":null},{"id":"opt_more_than_250","label":"More than 250","image_key":null}],"allowOther":false},{"id":"blk_customer03","ref":"job_role","title":"What''s your role there?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_customer04","ref":"age_range","title":"Which age group are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_25","label":"Under 25","image_key":null},{"id":"opt_25_34","label":"25–34","image_key":null},{"id":"opt_35_44","label":"35–44","image_key":null},{"id":"opt_45_54","label":"45–54","image_key":null},{"id":"opt_55_or_over","label":"55 or over","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false},{"id":"blk_customer05","ref":"discovery","title":"How did you first hear about us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_search_engine","label":"Search engine","image_key":null},{"id":"opt_recommendation","label":"Recommendation","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_an_ad","label":"An ad","image_key":null},{"id":"opt_review_or_comparison","label":"Review or comparison site","image_key":null}],"allowOther":true},{"id":"blk_customer06","ref":"problem","title":"What were you trying to sort out when you first bought from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_customer07","ref":"alternatives","title":"What else did you consider?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_another_company","label":"Another company","image_key":null},{"id":"opt_doing_it_myself","label":"Doing it myself","image_key":null},{"id":"opt_doing_nothing_for","label":"Doing nothi