VALUES ('tpl_customerattitudessurvey', 'customer-attitudes-survey', 'Customer attitudes survey', 'Survey', 'See how customers feel about your product, with the reasons behind every rating.', 'Asks for a feeling first, then the reason behind it, with a different follow-up for positive, lukewarm and negative customers. A grid of agree-or-disagree statements covers value, trust, ease of use and how you compare, and a closing question on how views have shifted shows whether things are heading the right way.', '["marketing","customer attitudes survey","customer opinion survey","customer sentiment","attitude survey","product feedback"]', 'ThumbsUp', 'choice', 3, 10, '{"schemaVersion":9,"title":"Customer attitudes","description":"See how customers feel about your product, with the reasons behind every rating.","blocks":[{"id":"blk_customer00","ref":"welcome","title":"We''d like to hear how you honestly feel about our product. It takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_customer01","ref":"tenure","title":"How long have you been using our product?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a month","image_key":null},{"id":"opt_1_6_months","label":"1–6 months","image_key":null},{"id":"opt_6_12_months","label":"6–12 months","image_key":null},{"id":"opt_more_than_a","label":"More than a year","image_key":null}],"allowOther":false},{"id":"blk_customer02","ref":"feeling","title":"Overall, how do you feel about it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Very negative","labelHigh":"Very positive"},{"id":"blk_customer03","ref":"positive_why","title":"Glad to hear it. What would you tell a friend about it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_customer04","ref":"neutral_why","title":"What''s keeping it from being great for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_customer05","ref":"negative_why","title":"Sorry it''s not working for you. What has shaped that view most?","description":"A specific moment, like a bill, a bug or a support call, helps us most.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_customer06","ref":"statements","title":"How much do you agree with each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_it_s","label":"It''s worth what I pay"},{"id":"opt_row_it_does","label":"It does what it promises"},{"id":"opt_row_i_trust","label":"I trust the company behind it"},{"id":"opt_row_it_s_2","label":"It''s easy to use"},{"id":"opt_row_it_s_3","label":"It''s better than the alternatives"}],"columns":[{"id":"opt_col_strongly_disagree","label":"Strongly disagree"},{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_neutral","label":"Neutral"},{"id":"opt_col_agree","label":"Agree"},{"id":"opt_col_strongly_agree","label":"Strongly agree"}],"multiplePerRow":false},{"id":"blk_customer07","ref":"drew_you","title":"What first drew you to it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_price","label":"The price","image_key":null},{"id":"opt_a_particular_feature","label":"A particular feature","image_key":null},{"id":"opt_how_easy_it","label":"How easy it looked","image_key":null},{"id":"opt_a_recommendation","label":"A recommendation","image_key":null},{"id":"opt_the_brand","label":"The brand","image_key":null}],"allowOther":true},{"id":"blk_customer08","ref":"view_shift","title":"Compared with when you started, has your view of it changed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_s_got","label":"It''s got better","image_key":null},{"id":"opt_it_s_about","label":"It''s about the same","image_key":null},{"id":"opt_it_s_got_2","label":"It''s got worse","image_key":null}],"allowOther":false},{"id":"blk_customer09","ref":"buy_again","title":"If you were choosing again today, would you pick us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_definitely","label":"Definitely","image_key":null},{"id":"opt_probably","label":"Probably","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null},{"id":"opt_probably_not","label":"Probably not","image_key":null},{"id":"opt_definitely_not","label":"Definitely not","image_key":null}],"allowOther":false},{"id":"blk_customer10","ref":"improve","title":"What one change would improve your opinion of us the most?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_customer01","ref":"end_thanks","title":"Thank you for your honesty","bodyMd":"The team reads every answer, and the reasons you gave help us decide what to change first.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_customer01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"positive_why","target":"statements","targetKind":"block"},{"id":"rl_customer02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"neutral_why","target":"statements","targetKind":"block"},{"id":"rl_customer03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feeling"},"op":"gte","value":4}],"groups":[]},"from":"feeling","target":"positive_why","targetKind":"block","branch":"true"},{"id":"rl_customer04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feeling"},"op":"eq","value":3}],"groups":[]},"from":"feeling","target":"neutral_why","targetKind":"block","branch":"true"},{"id":"rl_customer05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feeling"},"op":"lte","value":2}],"groups":[]},"from":"feeling","target":"negative_why","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
