VALUES ('tpl_happinesssurvey', 'happiness-survey', 'Happiness survey', 'Survey', 'A quick, honest check-in on how people feel, with a private follow-up for anyone who asks.', 'A happiness survey that asks why, not just how much. People who say they are less happy than before are asked what changed, people doing well are asked what is working, and anyone can ask for a private conversation without putting their name on every answer.', '["other","happiness survey","wellbeing check-in","team mood survey","employee happiness","community survey"]', 'SmilePlus', 'advanced', 3, 9, '{"schemaVersion":9,"title":"Happiness check-in","description":"A quick, honest check-in on how people feel, with a private follow-up for anyone who asks.","blocks":[{"id":"blk_happines00","ref":"welcome","title":"Hi! This is a quick check-in on how you''re feeling here lately. It takes about three minutes, and there are no wrong answers.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_happines01","ref":"happiness","title":"Over the past month, how happy have you felt here?","description":"Think about this team, program or group specifically, not life in general.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Very unhappy","labelHigh":"Very happy"},{"id":"blk_happines02","ref":"trend","title":"Compared with a few months ago, is that...","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_happier_than_before","label":"Happier than before","image_key":null},{"id":"opt_about_the_same","label":"About the same","image_key":null},{"id":"opt_less_happy_than","label":"Less happy than before","image_key":null}],"allowOther":false},{"id":"blk_happines03","ref":"best_moment","title":"What''s one recent moment that made you glad to be part of this?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_happines04","ref":"what_changed","title":"What''s changed for you? Anything you''re comfortable sharing helps.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_happines05","ref":"happiness_sources","title":"Which of these add most to your happiness here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_the_people_i","label":"The people I spend time with","image_key":null},{"id":"opt_feeling_that_what","label":"Feeling that what I do matters","image_key":null},{"id":"opt_learning_and_growing","label":"Learning and growing","image_key":null},{"id":"opt_being_recognised_for","label":"Being recognised for my effort","image_key":null},{"id":"opt_freedom_to_decide","label":"Freedom to decide how I work","image_key":null},{"id":"opt_a_manageable_amount","label":"A manageable amount on my plate","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_happines06","ref":"belonging","title":"How much do you agree with each of these?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_i_feel","label":"I feel like I belong here"},{"id":"opt_row_i_look","label":"I look forward to the time I spend here"},{"id":"opt_row_my_effort","label":"My effort is noticed"},{"id":"opt_row_i_have","label":"I have energy left for the rest of my life"}],"columns":[{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_somewhat_disagree","label":"Somewhat disagree"},{"id":"opt_col_somewhat_agree","label":"Somewhat agree"},{"id":"opt_col_agree","label":"Agree"}],"multiplePerRow":false},{"id":"blk_happines07","ref":"one_change","title":"If you could change one thing to make this a happier place, what would it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_happines08","ref":"want_chat","title":"Would you like someone to reach out for a private chat about how you''re doing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_happines09","ref":"contact_email","title":"What''s the best email to reach you on?","description":"Only the person following up will see this.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_happines01","ref":"end_thanks","title":"Thanks for checking in 😊","bodyMd":"We look at the answers together, not one by one, and share what we''re changing because of them.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_happines02","ref":"end_followup","title":"Thank you, we''ll be in touch","bodyMd":"Someone will email you within a few days to find a time that suits you. The conversation stays between the two of you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_happines01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"best_moment","target":"happiness_sources","targetKind":"block"},{"id":"rl_happines02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"contact_email","target":"end_followup","targetKind":"ending"},{"id":"rl_happines03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"trend"},"op":"eq","value":"opt_happier_than_before"}],"groups":[]},"from":"trend","target":"best_moment","targetKind":"block","branch":"true"},{"id":"rl_happines04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"trend"},"op":"eq","value":"opt_about_the_same"}],"groups":[]},"from":"trend","target":"best_moment","targetKind":"block","branch":"true"},{"id":"rl_happines05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"trend"},"op":"eq","value":"opt_less_happy_than"}],"groups":[]},"from":"trend","target":"what_changed","targetKind":"block","branch":"true"},{"id":"rl_happines06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"want_chat"},"op":"eq","value":false}],"groups":[]},"from":"want_chat","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_happines07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"want_chat"},"op":"eq","value":true}],"groups":[]},"from":"want_chat","target":"contact_email","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#f26b1d","surface":"#fff7f0","text":"#1c1917","accent":"#1c1917","accentText":"#ffffff","botBubble":"#fff7f0","userBubble":"#1c1917","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundPatternColor":"#1c1917","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
