INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_politicalsurvey', 'political-survey', 'Political survey', 'Survey', 'Ask people where they stand on public issues, in neutral wording that leaves room for every view.', 'Built for researchers, student groups, local organisations and campaigns who want honest answers rather than the ones a leading question produces. Every question has a balanced set of options, people who think things are on the wrong track are asked why, and the demographic questions are optional and come last.', '["other","political survey","public opinion survey","voter survey","issues survey","community priorities"]', 'Flag', 'advanced', 4, 11, '{"schemaVersion":9,"title":"Political opinion survey","description":"Ask people where they stand on public issues, in neutral wording that leaves room for every view.","blocks":[{"id":"blk_politica00","ref":"welcome","title":"Hi! We''re asking people in the area about the public issues that matter to them. It takes about four minutes, and every view is welcome.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_politica01","ref":"area","title":"Which town, city or area do you live in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_politica02","ref":"direction","title":"In general, do you think things in your area are heading in the right direction or on the wrong track?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_right_direction","label":"Right direction","image_key":null},{"id":"opt_wrong_track","label":"Wrong track","image_key":null},{"id":"opt_mixed_or_not","label":"Mixed or not sure","image_key":null}],"allowOther":false},{"id":"blk_politica03","ref":"wrong_track_why","title":"What makes you feel things are on the wrong track?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_politica04","ref":"top_issues","title":"Put these issues in order of how much they matter to you, most important first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_cost_of","label":"Cost of living"},{"id":"opt_item_housing","label":"Housing"},{"id":"opt_item_healthcare","label":"Healthcare"},{"id":"opt_item_jobs_and","label":"Jobs and the economy"},{"id":"opt_item_education","label":"Education"},{"id":"opt_item_public_safety","label":"Public safety"},{"id":"opt_item_environment_and","label":"Environment and climate"},{"id":"opt_item_immigration","label":"Immigration"}]},{"id":"blk_politica05","ref":"priorities","title":"How much of a priority should each of these be for local government?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_building_more","label":"Building more affordable homes"},{"id":"opt_row_improving_public","label":"Improving public transport"},{"id":"opt_row_keeping_local","label":"Keeping local taxes low"},{"id":"opt_row_funding_police","label":"Funding police and emergency services"},{"id":"opt_row_protecting_parks","label":"Protecting parks and green space"}],"columns":[{"id":"opt_col_low","label":"Low"},{"id":"opt_col_medium","label":"Medium"},{"id":"opt_col_high","label":"High"},{"id":"opt_col_not_sure","label":"Not sure"}],"multiplePerRow":false},{"id":"blk_politica06","ref":"trust","title":"How much do you trust your elected officials to act in residents'' best interests?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_politica07","ref":"voting","title":"How often do you vote in elections?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_every_election","label":"In every election","image_key":null},{"id":"opt_in_most_elections","label":"In most elections","image_key":null},{"id":"opt_now_and_then","label":"Now and then","image_key":null},{"id":"opt_rarely_or_never","label":"Rarely or never","image_key":null},{"id":"opt_i_m_not","label":"I''m not eligible to vote","image_key":null}],"allowOther":false},{"id":"blk_politica08","ref":"news_sources","title":"Where do you usually get news about politics?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_tv_or_radio","label":"TV or radio","image_key":null},{"id":"opt_newspapers_or_news","label":"Newspapers or news websites","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_podcasts_or_video","label":"Podcasts or video channels","image_key":null},{"id":"opt_friends_family_or","label":"Friends, family or neighbours","image_key":null},{"id":"opt_i_don_t","label":"I don''t follow political news","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_politica09","ref":"leaning","title":"Which of these best describes your political views?","description":"Optional, and only used to compare answers across groups.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_left","label":"Left","image_key":null},{"id":"opt_centre_left","label":"Centre-left","image_key":null},{"id":"opt_centre","label":"Centre","image_key":null},{"id":"opt_centre_right","label":"Centre-right","image_key":null},{"id":"opt_right","label":"Right","image_key":null},{"id":"opt_none_of_these","label":"None of these","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false},{"id":"blk_politica10","ref":"age_group","title":"Which age group are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_18_24","label":"18–24","image_key":null},{"id":"opt_25_34","label":"25–34","image_key":null},{"id":"opt_35_44","label":"35–44","image_key":null},{"id":"opt_45_54","label":"45–54","image_key":null},{"id":"opt_55_64","label":"55–64","image_key":null},{"id":"opt_65_or_over","label":"65 or over","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}]},{"id":"blk_politica11","ref":"missing_issue","title":"Is there an issue we didn''t ask about that matters to you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_politica01","ref":"end_thanks","title":"Thank you for sharing your views","bodyMd":"Your answers are combined with everyone else''s, and no single response is published.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_politica01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"direction"},"op":"eq","value":"opt_wrong_track"}],"groups":[]},"from":"direction","target":"wrong_track_why","targetKind":"block","branch":"true"},{"id":"rl_politica02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"direction"},"op":"eq","value":"opt_right_direction"}],"groups":[]},"from":"direction","target":"top_issues","targetKind":"block","branch":"true"},{"id":"rl_politica03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"direction"},"op":"eq","value":"opt_mixed_or_not"}],"groups":[]},"from":"direction","target":"top_issues","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#5b2ee6","surface":"#4a22c9","text":"#ffffff","accent":"#ffd166","accentText":"#1c1917","botBubble":"#4a22c9","userBubble":"#ffd166","userBubbleText":"#1c1917","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundPatternColor":"#ffffff","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
