VALUES ('tpl_userpersonasurvey', 'user-persona-survey', 'User persona survey', 'Survey', 'Gather the goals, habits and frustrations you need to build personas from real answers.', 'Personas are only as good as the answers behind them, so this survey asks about what people actually do rather than what they would like. It covers role, goals, how often the task comes up, today''s tools and what makes people switch, then routes anyone willing to talk to an interview sign-up.', '["other","user persona survey","persona research","customer profile survey","user research","jobs to be done"]', 'Users', 'advanced', 4, 12, '{"schemaVersion":9,"title":"User persona research","description":"Gather the goals, habits and frustrations you need to build personas from real answers.","blocks":[{"id":"blk_userpers00","ref":"welcome","title":"Hi! We''re trying to understand the people we build for. A few questions about your work and how you get it done, about four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_userpers01","ref":"role","title":"Which of these best describes your role?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_founder_or_owner","label":"Founder or owner","image_key":null},{"id":"opt_manager_or_team","label":"Manager or team lead","image_key":null},{"id":"opt_individual_contributor","label":"Individual contributor","image_key":null},{"id":"opt_freelancer_or_consultant","label":"Freelancer or consultant","image_key":null},{"id":"opt_student","label":"Student","image_key":null}],"allowOther":true},{"id":"blk_userpers02","ref":"team_size","title":"How many people work in your organisation?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_2_10","label":"2–10","image_key":null},{"id":"opt_11_50","label":"11–50","image_key":null},{"id":"opt_51_250","label":"51–250","image_key":null},{"id":"opt_more_than_250","label":"More than 250","image_key":null}],"allowOther":false},{"id":"blk_userpers03","ref":"main_goal","title":"What are you ultimately trying to achieve when you do this kind of work?","description":"Think about the outcome you want, not the tool you use.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_userpers04","ref":"frequency","title":"How often does this task come up for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_several_times_a","label":"Several times a day","image_key":null},{"id":"opt_daily","label":"Daily","image_key":null},{"id":"opt_weekly","label":"Weekly","image_key":null},{"id":"opt_monthly","label":"Monthly","image_key":null},{"id":"opt_a_few_times","label":"A few times a year","image_key":null}],"allowOther":false},{"id":"blk_userpers05","ref":"current_tools","title":"How do you handle it today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_spreadsheets","label":"Spreadsheets","image_key":null},{"id":"opt_a_dedicated_app","label":"A dedicated app or software","image_key":null},{"id":"opt_email_and_chat","label":"Email and chat messages","image_key":null},{"id":"opt_pen_and_paper","label":"Pen and paper","image_key":null},{"id":"opt_someone_else_does","label":"Someone else does it for me","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_userpers06","ref":"biggest_obstacle","title":"Walk us through the last time it was frustrating. What happened?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_userpers07","ref":"what_matters","title":"When choosing a tool for this, what matters most to you? Most important first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_easy_to","label":"Easy to learn"},{"id":"opt_item_saves_time","label":"Saves time"},{"id":"opt_item_price","label":"Price"},{"id":"opt_item_reliability","label":"Reliability"},{"id":"opt_item_works_with","label":"Works with my other tools"},{"id":"opt_item_good_support","label":"Good support"}]},{"id":"blk_userpers08","ref":"tech_comfort","title":"How comfortable are you trying new software?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"I avoid it","labelHigh":"I love it"},{"id":"blk_userpers09","ref":"switched","title":"Have you looked for a better way to do this in the past year?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_userpers10","ref":"switch_story","title":"What made you look, and what did you end up doing?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_userpers11","ref":"interview","title":"Would you be open to a 30-minute follow-up call about your answers?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_userpers12","ref":"contact","title":"Great! How can we reach you to set it up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","email"]}],"endings":[{"id":"end_userpers01","ref":"end_thanks","title":"Thanks, this is really useful","bodyMd":"Your answers go straight into the research that shapes what we build next.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_userpers02","ref":"end_interview","title":"Thank you, we''ll email you soon 🙌","bodyMd":"Someone from the research team will be in touch within a week to find a time for the call.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_userpers01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"contact","target":"end_interview","targetKind":"ending"},{"id":"rl_userpers02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"switched"},"op":"eq","value":true}],"groups":[]},"from":"switched","target":"switch_story","targetKind":"block","branch":"true"},{"id":"rl_userpers03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"switched"},"op":"eq","value":false}],"groups":[]},"from":"switched","target":"interview","targetKind":"block","branch":"true"},{"id":"rl_userpers04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"interview"},"op":"eq","value":false}],"groups":[]},"from":"interview","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_userpers05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"interview"},"op":"eq","value":true}],"groups":[]},"from":"interview","target":"contact","targetKind":"block","branch":"true"},{"id":"rl_userpers06","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"switch_story","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ece3ff","surface":"#ffffff","text":"#2a1f3d","accent":"#6d3fc7","accentText":"#fbf8ff","botBubble":"#ffffff","userBubble":"#6d3fc7","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
