INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_employeeperformancesurve', 'employee-performance-survey', 'Employee performance survey', 'Survey', 'Gather input from the people who work with someone, ahead of their performance review.', 'A survey the people around an employee fill in, so the review draws on more than one view. Only their manager is asked about agreed goals, a missed goal gets asked what got in the way, and everyone gives a real work example, rates the same skills and names one specific thing to improve.', '["other","employee performance survey","manager review form","peer feedback survey","360 feedback","employee evaluation"]', 'TrendingUp', 'advanced', 4, 11, '{"schemaVersion":9,"title":"Performance review input","description":"Gather input from the people who work with someone, ahead of their performance review.","blocks":[{"id":"blk_employee00","ref":"welcome","title":"Hi! You''ve been asked for input on a colleague''s performance ahead of their review. It takes about five minutes, and specific examples help far more than general praise or criticism.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_employee01","ref":"employee_name","title":"Whose performance are you giving input on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_employee02","ref":"relationship","title":"How do you work with them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_m_their","label":"I''m their manager","image_key":null},{"id":"opt_i_work_alongside","label":"I work alongside them on the same team","image_key":null},{"id":"opt_i_work_with","label":"I work with them from another team","image_key":null},{"id":"opt_they_manage_me","label":"They manage me","image_key":null}],"allowOther":false},{"id":"blk_employee03","ref":"goals_progress","title":"How did they do against the goals you agreed for this period?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_went_beyond_them","label":"Went beyond them","image_key":null},{"id":"opt_met_them","label":"Met them","image_key":null},{"id":"opt_partly_met_them","label":"Partly met them","image_key":null},{"id":"opt_didn_t_meet","label":"Didn''t meet them","image_key":null}],"allowOther":false},{"id":"blk_employee04","ref":"goals_context","title":"What got in the way of the goals they didn''t reach?","description":"Include anything outside their control, such as changed priorities or missing resources.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_employee05","ref":"work_example","title":"Describe one piece of their work from this period that stood out. What did they do, and what came of it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_employee06","ref":"skills","title":"From what you''ve seen, how do they do on each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_quality_of","label":"Quality of their work"},{"id":"opt_row_delivering_what","label":"Delivering what they promise, on time"},{"id":"opt_row_keeping_others","label":"Keeping others informed"},{"id":"opt_row_working_with","label":"Working with people across teams"},{"id":"opt_row_solving_problems","label":"Solving problems without being asked"},{"id":"opt_row_taking_feedback","label":"Taking feedback on board"}],"columns":[{"id":"opt_col_below_what","label":"Below what the role needs"},{"id":"opt_col_getting_there","label":"Getting there"},{"id":"opt_col_what_the","label":"What the role needs"},{"id":"opt_col_beyond_what","label":"Beyond what the role needs"}],"multiplePerRow":false},{"id":"blk_employee07","ref":"under_pressure","title":"How easy are they to work with when things get busy?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Very hard","labelHigh":"Very easy"},{"id":"blk_employee08","ref":"keep_doing","title":"What should they keep doing?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_employee09","ref":"improve","title":"What''s one thing that would make them more effective? Be specific, and kind.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_employee10","ref":"develop","title":"Where do you think they''d benefit most from development?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_job_specific_skills","label":"Job-specific skills","image_key":null},{"id":"opt_leading_or_mentoring","label":"Leading or mentoring others","image_key":null},{"id":"opt_communication","label":"Communication","image_key":null},{"id":"opt_planning_and_prioritising","label":"Planning and prioritising","image_key":null},{"id":"opt_understanding_the_wider","label":"Understanding the wider business","image_key":null}],"minSelections":1,"maxSelections":2,"allowOther":true},{"id":"blk_employee11","ref":"attribution","title":"How should your input be shared with them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_with_my_name","label":"With my name on it","image_key":null},{"id":"opt_without_my_name","label":"Without my name","image_key":null}],"allowOther":false}],"endings":[{"id":"end