VALUES ('tpl_performancemanagementsur', 'performance-management-survey', 'Performance management survey', 'Survey', 'Find out whether your goals, feedback and reviews actually help people do better work.', 'A survey about the performance process itself, not anyone''s performance. Managers are asked what would help them run better reviews, everyone rates how clear, fair and useful the process is, and anyone who rates it 3 or below is asked where it lets them down so you know what to fix first.', '["other","performance management survey","performance review process","feedback culture","goal setting","HR survey"]', 'Gauge', 'advanced', 3, 11, '{"schemaVersion":9,"title":"Performance process review","description":"Find out whether your goals, feedback and reviews actually help people do better work.","blocks":[{"id":"blk_performa00","ref":"welcome","title":"Hi! We want to know whether the way we set goals, give feedback and run reviews is actually helping. This is about the process, not your performance, and it takes about four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_performa01","ref":"role_type","title":"Do you manage other people?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_i_manage","label":"Yes, I manage people","image_key":null},{"id":"opt_no_i_don","label":"No, I don''t manage anyone","image_key":null}],"allowOther":false},{"id":"blk_performa02","ref":"manager_needs","title":"What would help you run better review conversations?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_training_on_giving","label":"Training on giving feedback","image_key":null},{"id":"opt_clearer_guidance_on","label":"Clearer guidance on ratings","image_key":null},{"id":"opt_simpler_forms_and","label":"Simpler forms and templates","image_key":null},{"id":"opt_more_time_set","label":"More time set aside for reviews","image_key":null},{"id":"opt_comparing_notes_with","label":"Comparing notes with other managers","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_performa03","ref":"expectations_clear","title":"How clear are the expectations for your own role?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Very unclear","labelHigh":"Completely clear"},{"id":"blk_performa04","ref":"goal_setting","title":"How are your goals usually set?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_together_with_my","label":"Together with my manager","image_key":null},{"id":"opt_my_manager_sets","label":"My manager sets them for me","image_key":null},{"id":"opt_i_set_them","label":"I set them myself","image_key":null},{"id":"opt_i_don_t","label":"I don''t have formal goals","image_key":null}],"allowOther":false},{"id":"blk_performa05","ref":"feedback_frequency","title":"How often do you get useful feedback on your work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_week","label":"Every week","image_key":null},{"id":"opt_every_month","label":"Every month","image_key":null},{"id":"opt_every_few_months","label":"Every few months","image_key":null},{"id":"opt_only_at_formal","label":"Only at formal reviews","image_key":null},{"id":"opt_rarely_or_never","label":"Rarely or never","image_key":null}],"allowOther":false},{"id":"blk_performa06","ref":"process_ratings","title":"How much do you agree with each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_my_goals","label":"My goals reflect the work I actually do"},{"id":"opt_row_feedback_i","label":"Feedback I get is specific enough to act on"},{"id":"opt_row_reviews_are","label":"Reviews are fair and consistent across teams"},{"id":"opt_row_my_rating","label":"My rating reflects my real contribution"},{"id":"opt_row_reviews_lead","label":"Reviews lead to a real plan for my development"}],"columns":[{"id":"opt_col_strongly_disagree","label":"Strongly disagree"},{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_agree","label":"Agree"},{"id":"opt_col_strongly_agree","label":"Strongly agree"}],"multiplePerRow":false},{"id":"blk_performa07","ref":"overall_useful","title":"Overall, how useful is our performance process in helping you improve?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_performa08","ref":"what_works","title":"What part of the process helps you most?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_performa09","ref":"what_fails","title":"Where does the process let you down? A recent example helps.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_performa10","ref":"time_spent","title":"Is the time spent on reviews about right?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_too_much","label":"Too much","image_key":null},{"id":"opt_about_right","label":"About right","image_key":null},{"id":"opt_too_little","label":"Too little","image_key":null}],"allowOther":false},{"id":"blk_performa11","ref":"one_change","title":"If you could change one thing about how performance is managed here, what would it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_performa01","ref":"end_thanks","title":"Thank you for the honest answers","bodyMd":"We''ll share what we heard and what we plan to change before the next review cycle starts.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_performa01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"what_works","target":"time_spent","targetKind":"block"},{"id":"rl_performa02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"role_type"},"op":"eq","value":"opt_yes_i_manage"}],"groups":[]},"from":"role_type","target":"manager_needs","targetKind":"block","branch":"true"},{"id":"rl_performa03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"role_type"},"op":"eq","value":"opt_no_i_don"}],"groups":[]},"from":"role_type","target":"expectations_clear","targetKind":"block","branch":"true"},{"id":"rl_performa04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall_useful"},"op":"gte","value":4}],"groups":[]},"from":"overall_useful","target":"what_works","targetKind":"block","branch":"true"},{"id":"rl_performa05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall_useful"},"op":"lte","value":3}],"groups":[]},"from":"overall_useful","target":"what_fails","targetKind":"block","branch":"true"},{"id":"rl_performa06","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"manager_needs","target":"goal_setting","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
