VALUES ('tpl_worklifebalancesurvey', 'work-life-balance-survey', 'Work-life balance survey', 'Survey', 'See where workload and boundaries are slipping, and which support would help most.', 'Covers the practical things that decide balance: hours, how often work spills into evenings, whether people can switch off and use their leave. Anyone who rates their balance low is asked what''s making it hardest, and everyone ranks the kinds of flexibility that would help them most.', '["other","work-life balance survey","employee wellbeing","workload survey","flexible working","burnout survey"]', 'Leaf', 'advanced', 3, 10, '{"schemaVersion":9,"title":"Work-life balance survey","description":"See where workload and boundaries are slipping, and which support would help most.","blocks":[{"id":"blk_worklife00","ref":"welcome","title":"Hi! We want to understand how work fits with the rest of your life, and what would make it fit better. About four minutes, and your answers are anonymous.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_worklife01","ref":"arrangement","title":"How do you mostly work at the moment?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_on_site","label":"On site","image_key":null},{"id":"opt_hybrid","label":"Hybrid","image_key":null},{"id":"opt_fully_remote","label":"Fully remote","image_key":null}],"allowOther":false},{"id":"blk_worklife02","ref":"weekly_hours","title":"In a typical week, how many hours do you actually work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_fewer_than_35","label":"Fewer than 35","image_key":null},{"id":"opt_35_40","label":"35–40","image_key":null},{"id":"opt_41_45","label":"41–45","image_key":null},{"id":"opt_46_50","label":"46–50","image_key":null},{"id":"opt_more_than_50","label":"More than 50","image_key":null}],"allowOther":false},{"id":"blk_worklife03","ref":"after_hours","title":"How often do you work in the evenings or at weekends?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_rarely_or_never","label":"Rarely or never","image_key":null},{"id":"opt_once_or_twice","label":"Once or twice a month","image_key":null},{"id":"opt_most_weeks","label":"Most weeks","image_key":null},{"id":"opt_almost_every_day","label":"Almost every day","image_key":null}],"allowOther":false},{"id":"blk_worklife04","ref":"balance","title":"How would you rate your balance between work and life outside it right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Very poor","labelHigh":"Excellent"},{"id":"blk_worklife05","ref":"what_helps","title":"What helps you keep a good balance? We''d like to do more of it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_worklife06","ref":"pressures","title":"What''s making balance hardest for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_more_work_than","label":"More work than fits in my hours","image_key":null},{"id":"opt_too_many_meetings","label":"Too many meetings","image_key":null},{"id":"opt_messages_outside_working","label":"Messages outside working hours","image_key":null},{"id":"opt_unclear_or_shifting","label":"Unclear or shifting priorities","image_key":null},{"id":"opt_staff_shortages_on","label":"Staff shortages on my team","image_key":null},{"id":"opt_commute","label":"Commute","image_key":null},{"id":"opt_caring_responsibilities_at","label":"Caring responsibilities at home","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther