VALUES ('tpl_trainingneedsassessments', 'training-needs-assessment-survey', 'Training needs assessment survey', 'Survey', 'Find the real skill gaps and preferred formats before you spend a training budget.', 'A needs assessment that asks about real work, not wish lists. People rate their confidence on the skills their job depends on, describe a recent moment where more training would have helped, and rank how they like to learn. Anyone confident enough to teach a topic is asked what they could share.', '["other","training needs assessment","skills gap survey","learning needs","employee training survey","L&D survey"]', 'GraduationCap', 'advanced', 4, 11, '{"schemaVersion":9,"title":"Training needs assessment","description":"Find the real skill gaps and preferred formats before you spend a training budget.","blocks":[{"id":"blk_training00","ref":"welcome","title":"Hi! We''re planning training for the months ahead and want it to fit the work you really do. It takes about five minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_training01","ref":"team","title":"Which team or department are you in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_training02","ref":"time_in_role","title":"How long have you been in your current role?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_6","label":"Less than 6 months","image_key":null},{"id":"opt_6_months_to","label":"6 months to 2 years","image_key":null},{"id":"opt_2_to_5","label":"2 to 5 years","image_key":null},{"id":"opt_more_than_5","label":"More than 5 years","image_key":null}],"allowOther":false},{"id":"blk_training03","ref":"main_tasks","title":"Which tasks take up most of your working week?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_training04","ref":"skill_confidence","title":"How confident are you in each of these areas?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_the_main","label":"The main software and systems I use"},{"id":"opt_row_communicating_with","label":"Communicating with customers or clients"},{"id":"opt_row_planning_and","label":"Planning and prioritising my work"},{"id":"opt_row_working_with","label":"Working with data and reports"},{"id":"opt_row_leading_or","label":"Leading or coaching others"},{"id":"opt_row_safety_compliance","label":"Safety, compliance and procedures"}],"columns":[{"id":"opt_col_i_need","label":"I need training"},{"id":"opt_col_some_gaps","label":"Some gaps"},{"id":"opt_col_confident","label":"Confident"},{"id":"opt_col_i_could","label":"I could teach it"}],"multiplePerRow":false},{"id":"blk_training05","ref":"stuck_moment","title":"Describe a recent moment at work when more training or support would have helped.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1200,"aiQualityCheck":false},{"id":"blk_training06","ref":"topics","title":"Which topics would help you most in the next six months? Pick up to three.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_job_specific_technical","label":"Job-specific technical skills","image_key":null},{"id":"opt_software_and_tools","label":"Software and tools","image_key":null},{"id":"opt_customer_service","label":"Customer service","image_key":null},{"id":"opt_project_management","label":"Project management","image_key":null},{"id":"opt_managing_people","label":"Managing people","image_key":null},{"id":"opt_writing_and_presenting","label":"Writing and presenting","image_key":null},{"id":"opt_health_safety_and","label":"Health, safety and compliance","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_training07","ref":"format","title":"How do you prefer to learn? Put your favourite first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_hands_on","label":"Hands-on workshop"},{"id":"opt_item_short_online","label":"Short online lessons"},{"id":"opt_item_one_to","label":"One-to-one coaching"},{"id":"opt_item_shadowing_a","label":"Shadowing a colleague"},{"id":"opt_item_written_guides","label":"Written guides I can look up"}]},{"id":"blk_training08","ref":"time_available","title":"How much time could you realistically give to training each month?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_2","label":"Less than 2 hours","image_key":null},{"id":"opt_2_4_hours","label":"2–4 hours","image_key":null},{"id":"opt_5_8_hours","label":"5–8 hours","image_key":null},{"id":"opt_more_than_8","label":"More than 8 hours","image_key":null}],"allowOther":false},{"id":"blk_training09","ref":"can_teach","title":"Is there anything you know well enough to teach colleagues?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_training10","ref":"teach_topic","title":"What could you teach, and to whom?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":300},{"id":"blk_training11","ref":"teacher_contact","title":"Who should we contact about it?","description":"Only used to follow up about teaching.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","last_name","email"]}],"endings":[{"id":"end_training01","ref":"end_thanks","title":"Thanks, this shapes the training plan","bodyMd":"We''ll share the plan once it''s ready, based on what you and your colleagues told us.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_training02","ref":"end_teacher","title":"Thank you, we may take you up on that","bodyMd":"Sharing what you know is one of the best ways a team learns. We''ll get in touch if your topic comes up in the plan.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_training01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"teacher_contact","target":"end_teacher","targetKind":"ending"},{"id":"rl_training02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"can_teach"},"op":"eq","value":false}],"groups":[]},"from":"can_teach","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_training03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"can_teach"},"op":"eq","value":true}],"groups":[]},"from":"can_teach","target":"teach_topic","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
