VALUES ('tpl_trainingsatisfactionsurv', 'training-satisfaction-survey', 'Training satisfaction survey', 'Survey', 'Hear how a training session landed, and which part lifted or sank the overall score.', 'A satisfaction survey that pins the overall score to a cause. A high rating asks which part made the session, a lower one asks what let it down and what would have fixed it, and everyone rates their satisfaction with the content, trainer, materials, length and setup.', '["other","training satisfaction survey","training feedback form","course satisfaction survey","workshop feedback","trainer feedback"]', 'ThumbsUp', 'advanced', 3, 11, '{"schemaVersion":9,"title":"Training satisfaction","description":"Hear how a training session landed, and which part lifted or sank the overall score.","blocks":[{"id":"blk_training00","ref":"welcome","title":"Thanks for taking part in the training! Two or three minutes of feedback helps us make the next session better.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_training01","ref":"session","title":"Which training session did you attend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_training02","ref":"attended_how","title":"How did you take part?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_person","label":"In person","image_key":null},{"id":"opt_live_online","label":"Live online","image_key":null},{"id":"opt_watched_a_recording","label":"Watched a recording","image_key":null}],"allowOther":false},{"id":"blk_training03","ref":"overall","title":"Overall, how satisfied were you with the training?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_training04","ref":"best_part","title":"Which part did the most to make it a good session?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_content_itself","label":"The content itself","image_key":null},{"id":"opt_the_way_the","label":"The way the trainer explained things","image_key":null},{"id":"opt_the_hands_on","label":"The hands-on practice","image_key":null},{"id":"opt_the_handouts_and","label":"The handouts and materials","image_key":null},{"id":"opt_discussion_with_other","label":"Discussion with other participants","image_key":null}],"allowOther":true},{"id":"blk_training05","ref":"letdown","title":"What let the session down most?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_wasn_t","label":"It wasn''t relevant to my job","image_key":null},{"id":"opt_it_was_hard","label":"It was hard to follow","image_key":null},{"id":"opt_the_pace_was","label":"The pace was off","image_key":null},{"id":"opt_the_materials_weren","label":"The materials weren''t much use","image_key":null},{"id":"opt_problems_with_the","label":"Problems with the room, sound or connection","image_key":null},{"id":"opt_it_ran_too","label":"It ran too long","image_key":null}],"allowOther":true},{"id":"blk_training06","ref":"letdown_fix","title":"What would have fixed that for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_training07","ref":"satisfaction","title":"How satisfied were you with each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_how_relevant","label":"How relevant the content was to my work"},{"id":"opt_row_the_trainer","label":"The trainer''s delivery"},{"id":"opt_row_handouts_slides","label":"Handouts, slides and other materials"},{"id":"opt_row_the_length","label":"The length of the session"},{"id":"opt_row_the_room","label":"The room or online setup"},{"id":"opt_row_joining_instructions","label":"Joining instructions beforehand"}],"columns":[{"id":"opt_col_dissatisfied","label":"Dissatisfied"},{"id":"opt_col_neutral","label":"Neutral"},{"id":"opt_col_satisfied","label":"Satisfied"},{"id":"opt_col_very_satisfied","label":"Very satisfied"}],"multiplePerRow":false},{"id":"blk_training08","ref":"expectations","title":"Did the session match what its description promised?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_was_better","label":"It was better than described","image_key":null},{"id":"opt_it_was_about","label":"It was about what I expected","image_key":null},{"id":"opt_it_fell_short","label":"It fell short of the description","image_key":null}],"allowOther":false},{"id":"blk_training09","ref":"confidence","title":"How confident do you feel putting what you learned into practice?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not confident","labelHigh":"Very confident"},{"id":"blk_training10","ref":"same_trainer","title":"Would you sign up for another session with this trainer?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_training11","ref":"anything_else","title":"Anything else the trainer or organisers should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_training01","ref":"end_thanks","title":"Thank you for the feedback 🙏","bodyMd":"Every response is read before the next session is planned.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_training01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"best_part","target":"satisfaction","targetKind":"block"},{"id":"rl_training02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"gte","value":4}],"groups":[]},"from":"overall","target":"best_part","targetKind":"block","branch":"true"},{"id":"rl_training03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"lte","value":3}],"groups":[]},"from":"overall","target":"letdown","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
