INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_commutingsurvey', 'commuting-survey', 'Commuting survey', 'Survey', 'Learn how people travel in, what it costs them and what would make the trip easier.', 'A travel survey for employers, campuses and site managers planning parking, flexible hours or transport support. People who never travel in are thanked and let go at the first question, and anyone who rates their commute poorly is asked what makes it hard before everyone ranks the changes that would help most.', '["other","commuting survey","travel to work survey","staff travel plan","transport survey","commute questionnaire"]', 'Bike', 'advanced', 3, 10, '{"schemaVersion":9,"title":"Commuting survey","description":"Learn how people travel in, what it costs them and what would make the trip easier.","blocks":[{"id":"blk_commutin00","ref":"welcome","title":"We''re planning how to make getting here easier. Tell us about your usual journey in; it takes about two minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_commutin01","ref":"days_in","title":"In a typical week, how many days do you travel in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_5_days_or","label":"5 days or more","image_key":null},{"id":"opt_3_to_4","label":"3 to 4 days","image_key":null},{"id":"opt_1_to_2","label":"1 to 2 days","image_key":null},{"id":"opt_less_than_once","label":"Less than once a week","image_key":null},{"id":"opt_i_don_t","label":"I don''t travel in at all","image_key":null}],"allowOther":false},{"id":"blk_commutin02","ref":"main_mode","title":"How do you cover the longest part of your journey?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_walking","label":"Walking","image_key":null},{"id":"opt_bicycle_or_e","label":"Bicycle or e-scooter","image_key":null},{"id":"opt_motorbike_or_moped","label":"Motorbike or moped","image_key":null},{"id":"opt_driving_alone","label":"Driving alone","image_key":null},{"id":"opt_car_share_or","label":"Car share or getting a lift","image_key":null},{"id":"opt_bus_or_coach","label":"Bus or coach","image_key":null},{"id":"opt_train_tram_or","label":"Train, tram or metro","image_key":null}],"allowOther":true},{"id":"blk_commutin03","ref":"journey_time","title":"Door to door, how long does the trip usually take one way?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_15_minutes","label":"Under 15 minutes","image_key":null},{"id":"opt_15_to_30","label":"15 to 30 minutes","image_key":null},{"id":"opt_30_to_45","label":"30 to 45 minutes","image_key":null},{"id":"opt_45_to_60","label":"45 to 60 minutes","image_key":null},{"id":"opt_over_an_hour","label":"Over an hour","image_key":null}],"allowOther":false},{"id":"blk_commutin04","ref":"area","title":"Which town, neighbourhood or postcode district do you travel from?","description":"A rough area is plenty. We never need your street address.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_commutin05","ref":"monthly_cost","title":"Roughly how much does commuting cost you in a typical month?","description":"Fares, fuel and parking together. A best guess is fine.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_commutin06","ref":"commute_feeling","title":"How do you feel about your commute on a normal day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"I dread it","labelHigh":"It''s easy"},{"id":"blk_commutin07","ref":"worst_part","title":"What''s the hardest part of the journey for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_commutin08","ref":"obstacles","title":"Which of these get in the way of travelling in more easily?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_cost_of_fares","label":"Cost of fares or fuel","image_key":null},{"id":"opt_unreliable_or_infrequent","label":"Unreliable or infrequent public transport","image_key":null},{"id":"opt_traffic_and_congestion","label":"Traffic and congestion","image_key":null},{"id":"opt_not_enough_parking","label":"Not enough parking","image_key":null},{"id":"opt_no_safe_cycling","label":"No safe cycling or walking route","image_key":null},{"id":"opt_nowhere_to_store","label":"Nowhere to store a bike or change","image_key":null},{"id":"opt_feeling_unsafe_at","label":"Feeling unsafe at certain times","image_key":null},{"id":"opt_caring_duties_before","label":"Caring duties before or after work","image_key":null},{"id":"opt_nothing_really","label":"Nothing really","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_commutin09","ref":"helps_most","title":"Put these in order of how much they would help you.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_flexible_start","label":"Flexible start and finish times"},{"id":"opt_item_more_days","label":"More days working from home"},{"id":"opt_item_a_discounted","label":"A discounted public transport pass"},{"id":"opt_item_secure_bike","label":"Secure bike parking and showers"},{"id":"opt_item_help_finding","label":"Help finding someone to car share with"},{"id":"opt_item_more_or","label":"More or better parking"}]},{"id":"blk_commutin10","ref":"anything_else","title":"Anything else about getting here that we should know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_commutin01","ref":"end_thanks","title":"Thanks for sharing your journey 🙌","bodyMd":"We''ll look at the answers together and share what we plan to change.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_commutin02","ref":"end_remote","title":"Thanks, that''s all we need","bodyMd":"This survey is about journeys in, so there''s nothing more to ask you. We appreciate you letting us know.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_commutin01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"days_in"},"op":"eq","value":"opt_i_don_t"}],"groups":[]},"from":"days_in","target":"end_remote","targetKind":"ending","branch":"true"},{"id":"rl_commutin02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"commute_feeling"},"op":"lte","value":2}],"groups":[]},"from":"commute_feeling","target":"worst_part","targetKind":"block","branch":"true"},{"id":"rl_commutin03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"commute_feeling"},"op":"gte","value":3}],"groups":[]},"from":"commute_feeling","target":"obstacles","targetKind":"block","branch":"true"},{"id":"rl_commutin04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"worst_part","target":"helps_most","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
