VALUES ('tpl_marketresearchsurvey', 'market-research-survey', 'Market research survey', 'Survey', 'Test a market before you build or sell: the problem, the alternatives and the buying criteria.', 'Written around a real example, weekly meal planning, so you can see how good market research questions sound before swapping in your own market. People who aren''t the decision maker are screened out politely, those who already pay for a solution are asked what they bought, and only volunteers are asked for an email.', '["other","market research survey","market validation","customer research","buying criteria","business idea survey"]', 'PieChart', 'advanced', 4, 12, '{"schemaVersion":9,"title":"Market research survey","description":"Test a market before you build or sell: the problem, the alternatives and the buying criteria.","blocks":[{"id":"blk_marketre00","ref":"welcome","title":"We''re researching how households plan and cook their weekly meals. It takes about three minutes, and there are no right answers.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_marketre01","ref":"planner","title":"Who usually decides what gets cooked in your home?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_mostly_me","label":"Mostly me","image_key":null},{"id":"opt_it_s_shared","label":"It''s shared","image_key":null},{"id":"opt_someone_else_almost","label":"Someone else, almost always","image_key":null}],"allowOther":false},{"id":"blk_marketre02","ref":"household","title":"How many people do you usually cook for, including yourself?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":20,"integerOnly":true},{"id":"blk_marketre03","ref":"cook_frequency","title":"On a typical weekday, how often is dinner cooked at home?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_almost_every_day","label":"Almost every day","image_key":null},{"id":"opt_three_or_four","label":"Three or four days","image_key":null},{"id":"opt_once_or_twice","label":"Once or twice","image_key":null},{"id":"opt_rarely","label":"Rarely","image_key":null}],"allowOther":false},{"id":"blk_marketre04","ref":"hassle","title":"How much of a hassle is deciding what to cook each week?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"No hassle","labelHigh":"A real headache"},{"id":"blk_marketre05","ref":"current_approach","title":"How do you handle meal planning today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_i_decide_on","label":"I decide on the day","image_key":null},{"id":"opt_a_written_plan","label":"A written plan or shopping list","image_key":null},{"id":"opt_recipe_websites_or","label":"Recipe websites or apps","image_key":null},{"id":"opt_cookbooks","label":"Cookbooks","image_key":null},{"id":"opt_meal_kit_deliveries","label":"Meal kit deliveries","image_key":null},{"id":"opt_ready_meals_or","label":"Ready meals or takeaway","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_marketre06","ref":"has_paid","title":"In the last year, have you paid for anything to make this easier?","description":"An app, a meal kit, a subscription, anything.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_marketre07","ref":"paid_for","title":"What did you pay for, and do you still use it? If you stopped, why?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_marketre08","ref":"criteria","title":"When choosing something to help with meals, what matters most to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_price","label":"Price"},{"id":"opt_item_time_saved","label":"Time saved"},{"id":"opt_item_healthy_meals","label":"Healthy meals"},{"id":"opt_item_less_food","label":"Less food waste"},{"id":"opt_item_fits_our","label":"Fits our dietary needs"},{"id":"opt_item_everyone_will","label":"Everyone will actually eat it"}]},{"id":"blk_marketre09","ref":"fair_spend","title":"If something solved this well, what would feel like a fair monthly spend?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_nothing_i_d","label":"Nothing, I''d only use a free option","image_key":null},{"id":"opt_less_than_one","label":"Less than one takeaway meal","image_key":null},{"id":"opt_about_one_takeaway","label":"About one takeaway meal","image_key":null},{"id":"opt_two_or_three","label":"Two or three takeaway meals","image_key":null},{"id":"opt_more_than_that","label":"More than that","image_key":null}],"allowOther":false},{"id":"blk_marketre10","ref":"put_off","title":"What would put you off trying a new product for this?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_marketre11","ref":"follow_up","title":"Would you be up for a 20-minute follow-up chat with our team?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_marketre12","ref":"email","title":"Great. What''s the best email to reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_marketre01","ref":"end_thanks","title":"Thank you, this is really useful","bodyMd":"Your answers go straight to the team shaping what we build next.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_marketre02","ref":"end_not_fit","title":"Thanks for stopping by","bodyMd":"We''re looking for the person who plans the meals this time, so we won''t take more of your time.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_marketre01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"planner"},"op":"eq","value":"opt_someone_else_almost"}],"groups":[]},"from":"planner","target":"end_not_fit","targetKind":"ending","branch":"true"},{"id":"rl_marketre02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_paid"},"op":"eq","value":true}],"groups":[]},"from":"has_paid","target":"paid_for","targetKind":"block","branch":"true"},{"id":"rl_marketre03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"has_paid"},"op":"eq","value":false}],"groups":[]},"from":"has_paid","target":"criteria","targetKind":"block","branch":"true"},{"id":"rl_marketre04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"follow_up"},"op":"eq","value":false}],"groups":[]},"from":"follow_up","target":"end_thanks","targetKind":"ending","branch":"true"},{"id":"rl_marketre05","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"paid_for","target":"fair_spend","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dff5f7","surface":"#ffffff","text":"#0b2e33","accent":"#0e6b75","accentText":"#ffffff","botBubble":"#ffffff","userBubble":"#0e6b75","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
