INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_productresearchsurvey', 'product-research-survey', 'Product research survey', 'Survey', 'Understand the task, the current workaround and the unsolved problems before you build.', 'Built around one example task, sending invoices, to show how product research questions work: the last time they did it, the tools they use, and a grid of which problems are real. People who never do the task are thanked and let go, anyone who gave up on a tool is asked why, and only willing testers leave an email.', '["other","product research survey","user research","jobs to be done","product discovery","problem validation"]', 'FlaskConical', 'advanced', 4, 12, '{"schemaVersion":9,"title":"Product research survey","description":"Understand the task, the current workaround and the unsolved problems before you build.","blocks":[{"id":"blk_productr00","ref":"welcome","title":"We''re trying to understand how people handle invoicing before we build anything. It''s about four minutes, and honest answers help most.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_productr01","ref":"work_type","title":"Which best describes your work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_freelancer_or_sole","label":"Freelancer or sole trader","image_key":null},{"id":"opt_owner_of_a","label":"Owner of a small business","image_key":null},{"id":"opt_finance_or_admin","label":"Finance or admin at a larger company","image_key":null}],"allowOther":true},{"id":"blk_productr02","ref":"task_frequency","title":"How often do you send invoices?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_several_times_a","label":"Several times a week","image_key":null},{"id":"opt_a_few_times","label":"A few times a month","image_key":null},{"id":"opt_once_a_month","label":"Once a month or less","image_key":null},{"id":"opt_i_don_t","label":"I don''t send invoices","image_key":null}],"allowOther":false},{"id":"blk_productr03","ref":"last_time","title":"Think about the last invoice you sent. Walk us through what you did, from start to finish.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_productr04","ref":"tools","title":"What do you use for invoicing today?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_a_spreadsheet","label":"A spreadsheet","image_key":null},{"id":"opt_a_document_template","label":"A document template","image_key":null},{"id":"opt_accounting_software","label":"Accounting software","image_key":null},{"id":"opt_a_dedicated_invoicing","label":"A dedicated invoicing app","image_key":null},{"id":"opt_my_payment_provider","label":"My payment provider''s invoices","image_key":null},{"id":"opt_pen_and_paper","label":"Pen and paper","image_key":null}],"minSelections":1,"maxSelections":10,"allowOther":true},{"id":"blk_productr05","ref":"time_taken","title":"How long does one invoice take, from starting it to sending it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_5_minutes","label":"Under 5 minutes","image_key":null},{"id":"opt_5_to_15","label":"5 to 15 minutes","image_key":null},{"id":"opt_15_to_30","label":"15 to 30 minutes","image_key":null},{"id":"opt_longer_than_30","label":"Longer than 30 minutes","image_key":null}],"allowOther":false},{"id":"blk_productr06","ref":"problems","title":"How much of a problem is each of these for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_getting_paid","label":"Getting paid on time"},{"id":"opt_row_keeping_track","label":"Keeping track of who has paid"},{"id":"opt_row_getting_client","label":"Getting client details and amounts right"},{"id":"opt_row_handling_tax","label":"Handling tax on invoices"},{"id":"opt_row_matching_payments","label":"Matching payments to invoices"}],"columns":[{"id":"opt_col_not_a","label":"Not a problem"},{"id":"opt_col_minor_annoyance","label":"Minor annoyance"},{"id":"opt_col_real_problem","label":"Real problem"}],"multiplePerRow":false},{"id":"blk_productr07","ref":"setup_fit","title":"Overall, how well does your current setup work for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Very badly","labelHigh":"Perfectly"},{"id":"blk_productr08","ref":"abandoned","title":"Have you ever tried a different tool for this and gone back?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_productr09","ref":"why_abandoned","title":"What was it, and what made you give up on it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productr10","ref":"one_fix","title":"If you could fix one thing about invoicing tomorrow, what would it be?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productr11","ref":"beta","title":"Would you try an early version and tell us what you think?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_productr12","ref":"email","title":"Thanks. Where should we send the invite?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false