INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_candidateexperiencesurve', 'candidate-experience-survey', 'Candidate experience survey', 'Survey', 'Hear from applicants about your job ads, interviews and communication, at every stage.', 'One survey for every applicant, whether they were hired or not. People who only applied skip the interview questions, and anyone who didn''t feel treated with respect is asked what happened, so the complaints worth acting on come with detail.', '["other","candidate experience survey","recruitment feedback","interview feedback","hiring process survey","applicant survey"]', 'UserPlus', 'advanced', 3, 10, '{"schemaVersion":9,"title":"Candidate experience survey","description":"Hear from applicants about your job ads, interviews and communication, at every stage.","blocks":[{"id":"blk_candidat00","ref":"welcome","title":"Thanks for applying to work with us. Whatever the outcome, we''d value two minutes of honest feedback on how our process felt.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_candidat01","ref":"role","title":"Which role did you apply for?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_candidat02","ref":"ad_clarity","title":"How clearly did the job ad describe the role and what it would involve?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not clear at all","labelHigh":"Very clear"},{"id":"blk_candidat03","ref":"stage","title":"How far did you get in the process?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_applied_but","label":"I applied but wasn''t invited to interview","image_key":null},{"id":"opt_i_had_a","label":"I had a first call or screening","image_key":null},{"id":"opt_i_completed_one","label":"I completed one or more interviews","image_key":null},{"id":"opt_i_received_an","label":"I received an offer","image_key":null}],"allowOther":false},{"id":"blk_candidat04","ref":"interviews","title":"Thinking about your interviews, how much do you agree with each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_scheduling_was","label":"Scheduling was easy"},{"id":"opt_row_my_interviewers","label":"My interviewers were prepared"},{"id":"opt_row_the_questions","label":"The questions related to the actual job"},{"id":"opt_row_i_had","label":"I had time to ask my own questions"},{"id":"opt_row_i_understood","label":"I understood the next steps afterwards"}],"columns":[{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_neutral","label":"Neutral"},{"id":"opt_col_agree","label":"Agree"}],"multiplePerRow":false},{"id":"blk_candidat05","ref":"kept_informed","title":"How well did we keep you informed along the way?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_candidat06","ref":"longest_wait","title":"What was the longest you waited to hear back from us?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_few_days","label":"A few days","image_key":null},{"id":"opt_about_a_week","label":"About a week","image_key":null},{"id":"opt_two_weeks_or","label":"Two weeks or more","image_key":null},{"id":"opt_i_never_heard","label":"I never heard back","image_key":null}],"allowOther":false},{"id":"blk_candidat07","ref":"respected","title":"Did you feel treated with respect throughout?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_candidat08","ref":"respect_detail","title":"We''re sorry. What happened that made you feel that way?","description":"Share as much or as little as you like.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_candidat09","ref":"one_change","title":"What one change would have made the process better for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_candidat10","ref":"recommend","title":"How likely are you to encourage a friend to apply here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"}],"endings":[{"id":"end_candidat01","ref":"end_thanks","title":"Thank you for telling us","bodyMd":"Your feedback has no effect on any application, now or later. It helps us treat the next candidate better.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_candidat01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"stage"},"op":"eq","value":"opt_i_applied_but"}],"groups":[]},"from":"stage","target":"kept_informed","targetKind":"block","branch":"true"},{"id":"rl_candidat02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"respected"},"op":"eq","value":true}],"groups":[]},"from":"respected","target":"one_change","targetKind":"block","branch":"true"},{"id":"rl_candidat03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"respected"},"op":"eq","value":false}],"groups":[]},"from":"respected","target":"respect_detail","targetKind":"block","branch":"true"},{"id":"rl_candidat04","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"respect_detail","target":"recommend","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatar