VALUES ('tpl_jobsatisfactionsurvey', 'job-satisfaction-survey', 'Job satisfaction survey', 'Survey', 'Measure how people feel about the job itself, with a different follow-up for low and high scores.', 'Covers the parts of a job that shape how people feel about it, from the work itself to recognition and room to grow. The overall score decides the follow-up: someone struggling is asked what''s making the job hard, someone content is asked what''s worth protecting, and everyone says whether they see themselves here in a year.', '["other","job satisfaction survey","employee satisfaction","staff survey","employee engagement","workplace survey"]', 'SmilePlus', 'advanced', 3, 10, '{"schemaVersion":9,"title":"Job satisfaction survey","description":"Measure how people feel about the job itself, with a different follow-up for low and high scores.","blocks":[{"id":"blk_jobsatis00","ref":"welcome","title":"This survey is about how your job feels right now. It takes about three minutes, and answers are reported only as team totals.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_jobsatis01","ref":"department","title":"Which part of the organisation do you work in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_operations","label":"Operations","image_key":null},{"id":"opt_sales_and_marketing","label":"Sales and marketing","image_key":null},{"id":"opt_product_and_engineering","label":"Product and engineering","image_key":null},{"id":"opt_customer_support","label":"Customer support","image_key":null},{"id":"opt_finance_and_admin","label":"Finance and admin","image_key":null},{"id":"opt_people_and_hr","label":"People and HR","image_key":null},{"id":"opt_other","label":"Other","image_key":null}]},{"id":"blk_jobsatis02","ref":"tenure","title":"How long have you worked here?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_6","label":"Less than 6 months","image_key":null},{"id":"opt_6_months_to","label":"6 months to 2 years","image_key":null},{"id":"opt_2_to_5","label":"2 to 5 years","image_key":null},{"id":"opt_more_than_5","label":"More than 5 years","image_key":null}],"allowOther":false},{"id":"blk_jobsatis03","ref":"aspects","title":"How satisfied are you with each part of your job?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_the_work","label":"The work itself"},{"id":"opt_row_my_workload","label":"My workload"},{"id":"opt_row_pay_and","label":"Pay and benefits"},{"id":"opt_row_recognition_for","label":"Recognition for good work"},{"id":"opt_row_my_relationship","label":"My relationship with my manager"},{"id":"opt_row_my_relationship_2","label":"My relationship with colleagues"},{"id":"opt_row_chances_to","label":"Chances to learn and grow"}],"columns":[{"id":"opt_col_dissatisfied","label":"Dissatisfied"},{"id":"opt_col_neutral","label":"Neutral"},{"id":"opt_col_satisfied","label":"Satisfied"}],"multiplePerRow":false},{"id":"blk_jobsatis04","ref":"clear_expectations","title":"Do you know clearly what''s expected of you in your role?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_jobsatis05","ref":"overall","title":"All things considered, how satisfied are you with your job right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_jobsatis06","ref":"whats_hard","title":"What''s making the job harder to enjoy at the moment?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_jobsatis07","ref":"worth_protecting","title":"What about your job would you most hate to lose?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_jobsatis08","ref":"growth_path","title":"Can you see a way to grow here over the next year?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_clearly","label":"Yes, clearly","image_key":null},{"id":"opt_maybe_but_it","label":"Maybe, but it''s unclear how","image_key":null},{"id":"opt_not_really","label":"Not really","image_key":null}],"allowOther":false},{"id":"blk_jobsatis09","ref":"one_year","title":"Do you see yourself working here a year from now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null},{"id":"opt_probably_not","label":"Probably not","image_key":null}],"allowOther":false},{"id":"blk_jobsatis10","ref":"one_change","title":"If you could change one thing about your job, what would it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_jobsatis01","ref":"end_thanks","title":"Thank you for being honest","bodyMd":"We''ll share what we learned with the whole team and what we plan to do about it.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_jobsatis01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"whats_hard","target":"growth_path","targetKind":"block"},{"id":"rl_jobsatis02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"overall"},"op":"lte","value":5}],"groups":[]},