VALUES ('tpl_performanceappraisalsurv', 'performance-appraisal-survey', 'Performance appraisal survey', 'Survey', 'Help employees prepare for their review with goals, examples, a self-rating and next steps.', 'Sent before a review meeting so the conversation starts from the employee''s own account. Anyone who met only some of their goals is asked what got in the way before sharing their best work, and it ends with the support they need and the goals they''d set next, so the meeting can move straight to agreeing a plan.', '["other","performance appraisal survey","self appraisal form","performance review","self-assessment","employee review"]', 'ClipboardCheck', 'advanced', 4, 13, '{"schemaVersion":9,"title":"Performance appraisal","description":"Help employees prepare for their review with goals, examples, a self-rating and next steps.","blocks":[{"id":"blk_performa00","ref":"welcome","title":"Your review is coming up. This helps you and your manager start from the same page, and takes about ten minutes to answer thoughtfully.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_performa01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_performa02","ref":"job_title","title":"What''s your current job title?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_performa03","ref":"period","title":"Which period does this review cover?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80,"placeholder":"e.g. January to June"},{"id":"blk_performa04","ref":"goals_met","title":"Looking at the goals you agreed for this period, how many did you meet?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_all_of_them","label":"All of them","image_key":null},{"id":"opt_most_of_them","label":"Most of them","image_key":null},{"id":"opt_some_of_them","label":"Some of them","image_key":null},{"id":"opt_few_or_none","label":"Few or none","image_key":null},{"id":"opt_we_didn_t","label":"We didn''t set clear goals","image_key":null}],"allowOther":false},{"id":"blk_performa05","ref":"blockers","title":"What got in the way of the goals you didn''t reach?","description":"Changed priorities, missing resources, things outside your control: all worth naming.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_performa06","ref":"achievements","title":"Describe two or three pieces of work you''re proudest of this period.","description":"Specific examples help most: what you did, and what changed because of it.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":2500,"aiQualityCheck":false},{"id":"blk_performa07","ref":"evidence","title":"Want to attach anything that shows your work?","description":"Optional. A report, a message of thanks, a screenshot.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["application/pdf","image/*",".docx",".xlsx"],"maxFiles":3,"maxSizeMB":10},{"id":"blk_performa08","ref":"competencies","title":"How would you rate yourself on each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_quality_of","label":"Quality of work"},{"id":"opt_row_meeting_deadlines","label":"Meeting deadlines"},{"id":"opt_row_communication","label":"Communication"},{"id":"opt_row_working_with","label":"Working with others"},{"id":"opt_row_solving_problems","label":"Solving problems"},{"id":"opt_row_taking_initiative","label":"Taking initiative"}],"columns":[{"id":"opt_col_needs_work","label":"Needs work"},{"id":"opt_col_solid","label":"Solid"},{"id":"opt_col_a_strength","label":"A strength"}],"multiplePerRow":false},{"id":"blk_performa09","ref":"self_rating","title":"Overall, how would you rate your performance this period?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Below expectations","labelHigh":"Well above expectations"},{"id":"blk_performa10","ref":"support","title":"What support from your manager or the company would help you most next period?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_performa11","ref":"development","title":"Which areas would you like to develop?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_technical_or_job","label":"Technical or job skills","image_key":null},{"id":"opt_leading_people","label":"Leading people","image_key":null},{"id":"opt_managing_projects","label":"Managing projects","image_key":null},{"id":"opt_presenting_and_communicati","label":"Presenting and communicating","image_key":null},{"id":"opt_knowledge_of_the","label":"Knowledge of the wider business","image_key":null}],"minSelections":0,"maxSelections":10,"allowOther":true},{"id":"blk_performa12","ref":"next_goals","title":"What goals would you like to set for the next period?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_performa13","ref":"to_discuss","title":"Anything else you want to make sure comes up in the meeting?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_performa01","ref":"end_thanks","title":"All done, thank you","bodyMd":"Your manager will read this before your review, so you can spend the meeting on what comes next.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_performa01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"goals_met"},"op":"eq","value":"opt_all_of_them"}],"groups":[]},"from":"goals_met","target":"achievements","targetKind":"block","branch":"true"},{"id":"rl_performa02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"goals_met"},"op":"eq","value":"opt_most_of_them"}],"groups":[]},"from":"goals_met","target":"achievements","targetKind":"block","branch":"true"},{"id":"rl_performa03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"goals_met"},"op":"eq","value":"opt_we_didn_t"}],"groups":[]},"from":"goals_met","target":"achievements","targetKind":"block","branch":"true"},{"id":"rl_performa04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"goals_met"},"op":"eq","value":"opt_some_of_them"}],"groups":[]},"from":"goals_met","target":"blockers","targetKind":"block","branch":"true"},{"id":"rl_performa05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"goals_met"},"op":"eq","value":"opt_few_or_none"}],"groups":[]},"from":"goals_met","target":"blockers","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
