INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_supervisorevaluationsurv', 'supervisor-evaluation-survey', 'Supervisor evaluation survey', 'Survey', 'Anonymous feedback from shift and frontline teams on how their supervisor runs the shift.', 'Built for shift-based and frontline teams, where supervision is about the shift in front of you: clear instructions, fair rotas, proper handovers and help on the job. Anyone whose supervisor blames people or stays out of it when something goes wrong is asked for an example, which is often the most useful answer in the whole survey.', '["other","supervisor evaluation","supervisor feedback survey","upward feedback","team leader evaluation","shift supervisor feedback"]', 'UserCheck', 'advanced', 3, 9, '{"schemaVersion":9,"title":"Supervisor evaluation","description":"Anonymous feedback from shift and frontline teams on how their supervisor runs the shift.","blocks":[{"id":"blk_supervis00","ref":"welcome","title":"Tell us how supervision works on your shifts. It''s anonymous and takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_supervis01","ref":"supervisor","title":"Who is the supervisor you''re giving feedback on?","description":"Only HR sees names. Supervisors see combined results from three or more people.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_supervis02","ref":"shift","title":"Which shift do you usually work with them?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_days","label":"Days","image_key":null},{"id":"opt_evenings","label":"Evenings","image_key":null},{"id":"opt_nights","label":"Nights","image_key":null},{"id":"opt_rotating_shifts","label":"Rotating shifts","image_key":null},{"id":"opt_regular_office_hours","label":"Regular office hours","image_key":null}],"allowOther":false},{"id":"blk_supervis03","ref":"behaviours","title":"How often does your supervisor do each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_gives_clear","label":"Gives clear instructions at the start of a shift or task"},{"id":"opt_row_is_around","label":"Is around when I need a decision or help"},{"id":"opt_row_shares_out","label":"Shares out shifts and tasks fairly"},{"id":"opt_row_applies_the","label":"Applies the rules the same way to everyone"},{"id":"opt_row_makes_sure","label":"Makes sure handovers between shifts are clear"},{"id":"opt_row_sorts_out","label":"Sorts out missing tools, equipment or cover"}],"columns":[{"id":"opt_col_rarely","label":"Rarely"},{"id":"opt_col_sometimes","label":"Sometimes"},{"id":"opt_col_usually","label":"Usually"},{"id":"opt_col_always","label":"Always"}],"multiplePerRow":false},{"id":"blk_supervis04","ref":"on_job_coaching","title":"How often do they show you how to do something better while you''re working?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_most_shifts","label":"Most shifts","image_key":null},{"id":"opt_now_and_then","label":"Now and then","image_key":null},{"id":"opt_only_when_something","label":"Only when something goes wrong","image_key":null},{"id":"opt_hardly_ever","label":"Hardly ever","image_key":null}],"allowOther":false},{"id":"blk_supervis05","ref":"when_wrong","title":"When something goes wrong on a shift, what does your supervisor usually do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_helps_put_it","label":"Helps put it right and explains what to do next time","image_key":null},{"id":"opt_fixes_it_themselves","label":"Fixes it themselves without explaining","image_key":null},{"id":"opt_looks_for_someone","label":"Looks for someone to blame","image_key":null},{"id":"opt_stays_out_of","label":"Stays out of it","image_key":null},{"id":"opt_nothing_has_gone","label":"Nothing has gone wrong while I''ve worked with them","image_key":null}],"allowOther":false},{"id":"blk_supervis06","ref":"wrong_example","title":"Can you describe a recent time that happened? What would have helped instead?","description":"Leave out names of colleagues if you can.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_supervis07","ref":"raise_concern","title":"Would you feel able to tell your supervisor about a safety or workload concern?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_supervis08","ref":"keep_or_start","title":"What''s one thing your supervisor should start doing, or keep doing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_supervis09","ref":"overall","title":"Overall, how would you rate the supervision on your shifts?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"}],"endings":[{"id":"end_supervis01","ref":"end_thanks","title":"Thanks for your honesty","bodyMd":"Your supervisor will see combined results, never your individual answers.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_supervis01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"when_wrong"},"op":"eq","value":"opt_looks_for_someone"}],"groups":[]},"from":"when_wrong","target":"wrong_example","targetKind":"block","branch":"true"},{"id":"rl_supervis02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"when_wrong"},"op":"eq","value":"opt_stays_out_of"}],"groups":[]},"from":"when_wrong","target":"wrong_example","targetKind":"block","branch":"true"},{"id":"rl_supervis03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"when_wrong"},"op":"eq","value":"opt_helps_put_it"}],"groups":[]},"from":"when_wrong","target":"raise_concern","targetKind":"block","branch":"true"},{"id":"rl_supervis04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"when_wrong"},"op":"eq","value":"opt_fixes_it_themselves"}],"groups":[]},"from":"when_wrong","target":"raise_concern","targetKind":"block","branch":"true"},{"id":"rl_supervis05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"when_wrong"},"op":"eq","value":"opt_nothing_has_gone"}],"groups":[]},"from":"when_wrong","target":"raise_concern","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ece3ff","surface":"#ffffff","text":"#2a1f3d","accent":"#6d3fc7","accentText":"#fbf8ff","botBubble":"#ffffff","userBubble":"#6d3fc7","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"rings","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
