VALUES ('tpl_demographicsurveyquestio', 'demographic-survey-questionnaire', 'Demographic survey questionnaire', 'Survey', 'Background questions for research, with consent first and a way to skip anything personal.', 'A set of respectful demographic questions to add to research or use on its own, with consent asked first and a ''prefer not to say'' on every sensitive question. Anyone under 18 is stopped at the age question and let go kindly, so you don''t collect data you shouldn''t from minors.', '["other","demographic survey","demographic questions","research questionnaire","respondent profile","audience research"]', 'Users', 'advanced', 4, 11, '{"schemaVersion":9,"title":"Demographic questionnaire","description":"Background questions for research, with consent first and a way to skip anything personal.","blocks":[{"id":"blk_demograp00","ref":"welcome","title":"A few questions about you. They help us understand who took part, and you can skip anything you''d rather not share.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_demograp01","ref":"consent","title":"How we''ll use your answers","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I agree that my answers can be used for this research. They will be reported only in combined form, never linked to my name, and I can skip any question I prefer not to answer.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"},{"id":"blk_demograp02","ref":"age_range","title":"How old are you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_18","label":"Under 18","image_key":null},{"id":"opt_18_to_24","label":"18 to 24","image_key":null},{"id":"opt_25_to_34","label":"25 to 34","image_key":null},{"id":"opt_35_to_44","label":"35 to 44","image_key":null},{"id":"opt_45_to_54","label":"45 to 54","image_key":null},{"id":"opt_55_to_64","label":"55 to 64","image_key":null},{"id":"opt_65_or_older","label":"65 or older","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false},{"id":"blk_demograp03","ref":"gender","title":"How do you describe your gender?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_woman","label":"Woman","image_key":null},{"id":"opt_man","label":"Man","image_key":null},{"id":"opt_non_binary","label":"Non-binary","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":true},{"id":"blk_demograp04","ref":"country","title":"Which country do you live in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_demograp05","ref":"area_type","title":"Which best describes where you live?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_city","label":"A city","image_key":null},{"id":"opt_a_town_or","label":"A town or suburb","image_key":null},{"id":"opt_a_village_or","label":"A village or rural area","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false},{"id":"blk_demograp06","ref":"education","title":"What''s the highest level of education you''ve completed?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_secondary_school_or","label":"Secondary school or less","image_key":null},{"id":"opt_vocational_or_trade","label":"Vocational or trade qualification","image_key":null},{"id":"opt_some_university_or","label":"Some university or college","image_key":null},{"id":"opt_undergraduate_degree","label":"Undergraduate degree","image_key":null},{"id":"opt_postgraduate_degree","label":"Postgraduate degree","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false},{"id":"blk_demograp07","ref":"employment","title":"Which best describes your current situation?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_employed_full_time","label":"Employed full time","image_key":null},{"id":"opt_employed_part_time","label":"Employed part time","image_key":null},{"id":"opt_self_employed","label":"Self-employed","image_key":null},{"id":"opt_looking_for_work","label":"Looking for work","image_key":null},{"id":"opt_student","label":"Student","image_key":null},{"id":"opt_retired","label":"Retired","image_key":null},{"id":"opt_caring_for_family","label":"Caring for family full time","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":true},{"id":"blk_demograp08","ref":"household_size","title":"How many people live in your household, including you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":20,"integerOnly":true},{"id":"blk_demograp09","ref":"finances","title":"Which best describes your household''s finances at the moment?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_living_comfortably","label":"Living comfortably","image_key":null},{"id":"opt_doing_all_right","label":"Doing all right","image_key":null},{"id":"opt_just_about_getting","label":"Just about getting by","image_key":null},{"id":"opt_finding_it_difficult","label":"Finding it difficult","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false},{"id":"blk_demograp10","ref":"home_language","title":"Which language do you mainly speak at home?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_demograp11","ref":"health_condition","title":"Do you have a disability or long-term health condition that affects your daily life?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_no","label":"No","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false}],"endings":[{"id":"end_demograp01","ref":"end_thanks","title":"Thank you for taking part","bodyMd":"Your answers help us understand who we heard from, and they''ll only ever be reported as combined totals.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_demograp02","ref":"end_under_18","title":"Thanks for your interest","bodyMd":"This research is only open to people aged 18 or over, so we won''t ask you anything more. Nothing else you''ve shared will be used.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_demograp01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"age_range"},"op":"eq","value":"opt_under_18"}],"groups":[]},"from":"age_range","target":"end_under_18","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"