VALUES ('tpl_concepttestingsurvey', 'concept-testing-survey', 'Concept testing survey', 'Survey', 'Check whether an early idea is understood, wanted and worth building.', 'The concept is shown first, then people explain it back in their own words, so you learn whether the idea is clear before you read a single rating. Anyone who rarely has the problem skips the questions about how they solve it today, and people who say they would try it are offered early access while the rest are asked what would change their mind.', '["product","concept testing survey","concept test","idea validation","product research","early feedback"]', 'Lightbulb', 'number', 3, 10, '{"schemaVersion":9,"title":"Concept test","description":"Check whether an early idea is understood, wanted and worth building.","blocks":[{"id":"blk_conceptt00","ref":"welcome","title":"We''re working on a new idea and would love your honest first impressions. It takes about four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_conceptt01","ref":"concept","title":"Here''s the idea","description":"Replace this with a short, plain description of your concept: who it is for, the problem it solves and how it works. Add an image or short video if you have one.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Continue","type":"statement"},{"id":"blk_conceptt02","ref":"first_reaction","title":"What''s your first reaction?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":10,"startAt":1,"labelLow":"Not for me","labelHigh":"I love it"},{"id":"blk_conceptt03","ref":"understanding","title":"In a sentence or two, what do you think this does?","description":"There''s no wrong answer. We want to know if we explained it clearly.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_conceptt04","ref":"problem_fit","title":"How often do you run into the problem this is meant to solve?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_all_the_time","label":"All the time","image_key":null},{"id":"opt_now_and_then","label":"Now and then","image_key":null},{"id":"opt_rarely","label":"Rarely","image_key":null},{"id":"opt_never","label":"Never","image_key":null}],"allowOther":false},{"id":"blk_conceptt05","ref":"current_way","title":"How do you deal with it today?","required":false,"visibility":null,"image_key":null,"agentHints":{"askStyle":"Ask for the actual workaround, tool or habit they rely on, not a general opinion.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_conceptt06","ref":"appeal","title":"How appealing is each part of the idea?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_the_main","label":"The main idea"},{"id":"opt_row_how_it","label":"How it would fit into your day"},{"id":"opt_row_how_it_2","label":"How it looks"},{"id":"opt_row_how_easy","label":"How easy it seems to use"}],"columns":[{"id":"opt_col_not_appealing","label":"Not appealing"},{"id":"opt_col_neutral","label":"Neutral"},{"id":"opt_col_appealing","label":"Appealing"},{"id":"opt_col_very_appealing","label":"Very appealing"}],"multiplePerRow":false},{"id":"blk_conceptt07","ref":"concerns","title":"What questions or worries would stop you from trying it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_conceptt08","ref":"try_it","title":"If this existed today, how likely would you be to try it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_definitely","label":"Definitely","image_key":null},{"id":"opt_probably","label":"Probably","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null},{"id":"opt_probably_not","label":"Probably not","image_key":null},{"id":"opt_definitely_not","label":"Definitely not","image_key":null}],"allowOther":false},{"id":"blk_conceptt09","ref":"change_mind","title":"What would have to change for you to want it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_conceptt10","ref":"early_access","title":"Would you like early access when it''s ready?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, count me in","noLabel":"Not right now"},{"id":"blk_conceptt11","ref":"early_email","title":"Where should we send your invite?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_conceptt01","ref":"end_thanks","title":"Thank you, that''s really useful","bodyMd":"Critical answers help us most at this stage, so thanks for being straight with us.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_conceptt02","ref":"end_early","title":"You''re on the list 🚀","bodyMd":"Thanks for the honest feedback. We''ll email you as soon as there''s something to try.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_conceptt01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"change_mind","target":"end_thanks","targetKind":"ending"},{"id":"rl_conceptt02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"early_email","target":"end_early","targetKind":"ending"},{"id":"rl_conceptt03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"problem_fit"},"op":"eq","value":"opt_rarely"}],"groups":[]},"from":"problem_fit","target":"appeal","targetKind":"block","branch":"true"},{"id":"rl_conceptt04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"problem_fit"},"op":"eq","value":"opt_never"}],"groups":[]},"from":"problem_fit","target":"appeal","targetKind":"block","branch":"true"},{"id":"rl_conceptt05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"try_it"},"op":"eq","value":"opt_definitely"}],"groups":[]},"from":"try_it","target":"early_access","targetKind":"block","branch":"true"},{"id":"rl_conceptt06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"try_it"},"op":"eq","value":"opt_probably"}],"groups":[]},"from":"try_it","target":"early_access","targetKind":"block","branch":"true"},{"id":"rl_conceptt07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"try_it"},"op":"eq","value":"opt_not_sure"}],"groups":[]},"from":"try_it","target":"change_mind","targetKind":"block","branch":"true"},{"id":"rl_conceptt08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"try_it"},"op":"eq","value":"opt_probably_not"}],"groups":[]},"from":"try_it","target":"change_mind","targetKind":"block","branch":"true"},{"id":"rl_conceptt09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"try_it"},"op":"eq","value":"opt_definitely_not"}],"groups":[]},"from":"try_it","target":"change_mind","targetKind":"block","branch":"true"},{"id":"rl_conceptt10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"early_access"},"op":"eq","value":false}],"groups":[]},"from":"early_access","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
