INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_focusgroupsurvey', 'focus-group-survey', 'Focus group survey', 'Survey', 'Hear from every participant before and after the group discussion, not just the loudest.', 'The first question asks whether the session is still ahead or already over, and each group gets its own set of questions. Before the session you learn each person''s starting view and what they want to discuss; afterwards you learn what they did not get to say and whether the discussion changed their mind.', '["product","focus group survey","focus group questionnaire","pre-session survey","qualitative research","participant feedback"]', 'Users', 'number', 3, 13, '{"schemaVersion":9,"title":"Focus group survey","description":"Hear from every participant before and after the group discussion, not just the loudest.","blocks":[{"id":"blk_focusgro00","ref":"welcome","title":"Thanks for taking part in our focus group. A few questions on your own first, so every view gets heard.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_focusgro01","ref":"name","title":"What''s your first name?","description":"So we can match your answers to the session notes.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_focusgro02","ref":"timing","title":"Is the session still ahead of you, or has it already happened?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_s_still","label":"It''s still ahead","image_key":null},{"id":"opt_i_ve_just","label":"I''ve just taken part","image_key":null}],"allowOther":false},{"id":"blk_focusgro03","ref":"familiarity","title":"How familiar are you with the topic we''ll be discussing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_use_it","label":"I use it or deal with it every week","image_key":null},{"id":"opt_i_ve_some","label":"I''ve some experience with it","image_key":null},{"id":"opt_i_ve_heard","label":"I''ve heard of it but not used it","image_key":null},{"id":"opt_it_s_completely","label":"It''s completely new to me","image_key":null}],"allowOther":false},{"id":"blk_focusgro04","ref":"starting_view","title":"Before we meet, what''s your honest view on it?","required":true,"visibility":null,"image_key":null,"agentHints":{"askStyle":"Reassure them there''s no right answer and ask for one concrete example behind their view.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_focusgro05","ref":"discuss","title":"Which of these would you most like to talk about?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_what_works_well","label":"What works well today","image_key":null},{"id":"opt_what_frustrates_me","label":"What frustrates me","image_key":null},{"id":"opt_ideas_for_improving","label":"Ideas for improving it","image_key":null},{"id":"opt_price_and_value","label":"Price and value","image_key":null},{"id":"opt_how_it_compares","label":"How it compares with other options","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_focusgro06","ref":"speaking_comfort","title":"How comfortable are you sharing your views in a group?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"I''d rather listen","labelHigh":"Very comfortable"},{"id":"blk_focusgro07","ref":"access_needs","title":"Is there anything we should arrange so you can take part comfortably?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_focusgro08","ref":"felt_heard","title":"How well did the session let you say what you wanted to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_focusgro09","ref":"unsaid","title":"Was there anything you didn''t get to say, or held back?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_focusgro10","ref":"view_changed","title":"Did the discussion change your view?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_quite_a","label":"Yes, quite a lot","image_key":null},{"id":"opt_a_little","label":"A little","image_key":null},{"id":"opt_not_at_all","label":"Not at all","image_key":null}],"allowOther":false},{"id":"blk_focusgro11","ref":"what_changed","title":"What changed your mind, and how do you see it now?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_focusgro12","ref":"takeaway","title":"If the organisers remember one thing you said, what should it be?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_focusgro13","ref":"future_research","title":"Can we invite you to future research sessions?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"}],"endings":[{"id":"end_focusgro01","ref":"end_thanks","title":"Thank you for taking part","bodyMd":"Your answers sit alongside the discussion notes, so anything you held back in the room still counts.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_focusgro02","ref":"end_before","title":"See you at the session 👋","bodyMd":"Thanks. The moderator will read your answers beforehand, so your view is part of the conversation from the start.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_focusgro01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"access_needs","target":"end_before","targetKind":"ending"},{"id":"rl_focusgro02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"timing"},"op":"eq","value":"opt_it_s_still"}],"groups":[]},"from":"timing","target":"familiarity","targetKind":"block","branch":"true"},{"id":"rl_focusgro03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"timing"},"op":"eq","value":"opt_i_ve_just"}],"groups":[]},"from":"timing","target":"felt_heard","targetKind":"block","branch":"true"},{"id":"rl_focusgro04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"view_changed"},"op":"eq","value":"opt_not_at_all"}],"groups":[]},"from":"view_changed","target":"takeaway","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
