VALUES ('tpl_newproductsurvey', 'new-product-survey', 'New product survey', 'Survey', 'Learn who wants your new product, what matters to them and what''s stopping them.', 'People who never have the problem are thanked and let go straight away, so your numbers come from the audience you''re actually building for. Everyone else ranks the features, names a price and says what they''d need to know first, and the ones planning to try it can leave an email for the launch.', '["product","new product survey","product launch survey","pre-launch research","feature prioritisation","pricing research"]', 'Rocket', 'number', 3, 11, '{"schemaVersion":9,"title":"New product survey","description":"Learn who wants your new product, what matters to them and what''s stopping them.","blocks":[{"id":"blk_newprodu00","ref":"welcome","title":"We''re getting ready to launch something new and want to build it around what you actually need. About four minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_newprodu01","ref":"problem_frequency","title":"How often do you run into the problem this product is built to solve?","description":"Edit this question to name the problem in plain words.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_week_or","label":"Every week or more","image_key":null},{"id":"opt_about_once_a","label":"About once a month","image_key":null},{"id":"opt_a_few_times","label":"A few times a year","image_key":null},{"id":"opt_never","label":"Never","image_key":null}],"allowOther":false},{"id":"blk_newprodu02","ref":"current_solution","title":"How do you handle it today?","required":true,"visibility":null,"image_key":null,"agentHints":{"askStyle":"Ask what they use or do now, and what bothers them about it.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_newprodu03","ref":"current_satisfaction","title":"How happy are you with the way you handle it now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_newprodu04","ref":"features","title":"Rank these by how much they matter to you.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_quick_to","label":"Quick to set up"},{"id":"opt_item_works_well","label":"Works well on a phone"},{"id":"opt_item_fits_the","label":"Fits the tools I already use"},{"id":"opt_item_clear_fair","label":"Clear, fair pricing"},{"id":"opt_item_help_from","label":"Help from a real person when I need it"}]},{"id":"blk_newprodu05","ref":"interest","title":"From what you know about it so far, how interested are you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not interested","labelHigh":"Very interested"},{"id":"blk_newprodu06","ref":"expected_price","title":"What would you expect to pay for it?","description":"Your best guess is fine. Say whether that''s once, monthly or yearly.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"integerOnly":false},{"id":"blk_newprodu07","ref":"need_to_know","title":"What would you need to know before you''d try it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_newprodu08","ref":"intent","title":"When it launches, what are you most likely to do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_buy_it_straight","label":"Buy it straight away","image_key":null},{"id":"opt_try_a_free","label":"Try a free version first","image_key":null},{"id":"opt_wait_to_hear","label":"Wait to hear what others think","image_key":null},{"id":"opt_probably_skip_it","label":"Probably skip it","image_key":null}],"allowOther":false},{"id":"blk_newprodu09","ref":"why_skip","title":"What makes it not quite right for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_newprodu10","ref":"notify","title":"Shall we tell you when it launches?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_newprodu11","ref":"email","title":"What''s the best email for that?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_newprodu01","ref":"end_thanks","title":"Thank you, that helps a lot","bodyMd":"Every answer shapes what goes into the first release, including the ones that tell us what isn''t working.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_newprodu02","ref":"end_not_for_you","title":"Thanks, that''s useful to know","bodyMd":"It sounds like this isn''t a problem you have, so we won''t keep you. Thanks for stopping by.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_newprodu03","ref":"end_launch","title":"You''ll be the first to know 🚀","bodyMd":"Thanks for helping shape it. We''ll send one email when it launches.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_newprodu01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"why_skip","target":"end_thanks","targetKind":"ending"},{"id":"rl_newprodu02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"email","target":"end_launch","targetKind":"ending"},{"id":"rl_newprodu03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"problem_frequency"},"op":"eq","value":"opt_never"}],"groups":[]},"from":"problem_frequency","target":"end_not_for_you","targetKind":"ending","branch":"true"},{"id":"rl_newprodu04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"intent"},"op":"eq","value":"opt_buy_it_straight"}],"groups":[]},"from":"intent","target":"notify","targetKind":"block","branch":"true"},{"id":"rl_newprodu05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"intent"},"op":"eq","value":"opt_try_a_free"}],"groups":[]},"from":"intent","target":"notify","targetKind":"block","branch":"true"},{"id":"rl_newprodu06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"intent"},"op":"eq","value":"opt_wait_to_hear"}],"groups":[]},"from":"intent","target":"notify","targetKind":"block","branch":"true"},{"id":"rl_newprodu07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"intent"},"op":"eq","value":"opt_probably_skip_it"}],"groups":[]},"from":"intent","target":"why_skip","targetKind":"block","branch":"true"},{"id":"rl_newprodu08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"notify"},"op":"eq","value":false}],"groups":[]},"from":"notify","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":