VALUES ('tpl_productsatisfactionsurve', 'product-satisfaction-survey', 'Product satisfaction survey', 'Survey', 'Find out whether the product lived up to what buyers expected, and why.', 'One question splits the survey: did the product turn out better, about the same or worse than expected? Buyers it pleased say what they like most, and buyers it disappointed say what fell short and can ask to be contacted so you can put it right.', '["product","product satisfaction survey","product feedback","customer satisfaction","post-purchase survey","product review"]', 'ThumbsUp', 'number', 4, 12, '{"schemaVersion":9,"title":"Product satisfaction","description":"Find out whether the product lived up to what buyers expected, and why.","blocks":[{"id":"blk_products00","ref":"welcome","title":"Thanks for your purchase. Now that you''ve had some time with it, how is it going?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_products01","ref":"product","title":"Which product are you reviewing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_products02","ref":"time_used","title":"How long have you been using it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_less_than_a","label":"Less than a week","image_key":null},{"id":"opt_a_few_weeks","label":"A few weeks","image_key":null},{"id":"opt_a_few_months","label":"A few months","image_key":null},{"id":"opt_more_than_six","label":"More than six months","image_key":null}],"allowOther":false},{"id":"blk_products03","ref":"satisfaction","title":"Overall, how satisfied are you with it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_products04","ref":"aspects","title":"How would you rate each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_quality","label":"Quality"},{"id":"opt_row_ease_of","label":"Ease of use"},{"id":"opt_row_reliability","label":"Reliability"},{"id":"opt_row_value_for","label":"Value for money"},{"id":"opt_row_look_and","label":"Look and feel"}],"columns":[{"id":"opt_col_poor","label":"Poor"},{"id":"opt_col_fair","label":"Fair"},{"id":"opt_col_good","label":"Good"},{"id":"opt_col_excellent","label":"Excellent"}],"multiplePerRow":false},{"id":"blk_products05","ref":"expectations","title":"Compared with what you expected, the product has been...","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_better_than_i","label":"Better than I expected","image_key":null},{"id":"opt_about_what_i","label":"About what I expected","image_key":null},{"id":"opt_worse_than_i","label":"Worse than I expected","image_key":null}],"allowOther":false},{"id":"blk_products06","ref":"best_part","title":"What do you like most about it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_products07","ref":"fell_short","title":"What fell short of what you expected?","required":true,"visibility":null,"image_key":null,"agentHints":{"askStyle":"Ask for the specific moment or feature that disappointed them.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_products08","ref":"contact_ok","title":"Would you like someone from our team to get in touch to help?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_products09","ref":"contact_email","title":"Which email should we use?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_products10","ref":"recommend","title":"How likely are you to recommend it to a friend or colleague?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_products11","ref":"improvements","title":"What would make it better?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_better_quality_or","label":"Better quality or durability","image_key":null},{"id":"opt_easier_to_use","label":"Easier to use","image_key":null},{"id":"opt_clearer_instructions","label":"Clearer instructions","image_key":null},{"id":"opt_more_features","label":"More features","image_key":null},{"id":"opt_a_lower_price","label":"A lower price","image_key":null},{"id":"opt_nothing_it_s","label":"Nothing, it''s great as it is","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":true},{"id":"blk_products12","ref":"anything_else","title":"Anything else you''d like us to know?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false}],"endings":[{"id":"end_products01","ref":"end_thanks","title":"Thanks for the feedback 🙌","bodyMd":"We read every response. If you asked us to get in touch, we''ll email you soon.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_products01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"best_part","target":"recommend","targetKind":"block"},{"id":"rl_products02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"expectations"},"op":"eq","value":"opt_better_than_i"}],"groups":[]},"from":"expectations","target":"best_part","targetKind":"block","branch":"true"},{"id":"rl_products03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"expectations"},"op":"eq","value":"opt_about_what_i"}],"groups":[]},"from":"expectations","target":"best_part","targetKind":"block","branch":"true"},{"id":"rl_products04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"expectations"},"op":"eq","value":"opt_worse_than_i"}],"groups":[]},"from":"expectations","target":"fell_short","targetKind":"block","branch":"true"},{"id":"rl_products05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"contact_ok"},"op":"eq","value":false}],"groups":[]},"from":"contact_ok","target":"recommend","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffe4d3","surface":"#ffffff","text":"#3a2418","accent":"#c2410c","accentText":"#fffaf5","botBubble":"#ffffff","userBubble":"#c2410c","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
