VALUES ('tpl_producttestingsurvey', 'product-testing-survey', 'Product testing survey', 'Survey', 'Find out what testers tried, where they struggled and what they expected instead.', 'Anchored to the task you set: testers who finished easily move on, testers who struggled say which step was hardest, and testers who got stuck say where and can attach a screenshot. Everyone then says what they expected to happen, rates ease and quality, and reports any bugs they spotted.', '["product","product testing survey","user testing","beta test feedback","usability testing","bug reports"]', 'FlaskConical', 'number', 4, 13, '{"schemaVersion":9,"title":"Product testing survey","description":"Find out what testers tried, where they struggled and what they expected instead.","blocks":[{"id":"blk_productt00","ref":"welcome","title":"Thanks for testing for us. Tell us what happened while it''s fresh; the problems are the most useful part.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_productt01","ref":"tester","title":"What''s your name or tester ID?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_productt02","ref":"device","title":"What did you test it on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_phone","label":"Phone","image_key":null},{"id":"opt_tablet","label":"Tablet","image_key":null},{"id":"opt_laptop_or_desktop","label":"Laptop or desktop","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}]},{"id":"blk_productt03","ref":"task_result","title":"Were you able to finish the task we gave you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_easily","label":"Yes, easily","image_key":null},{"id":"opt_yes_but_it","label":"Yes, but it took some effort","image_key":null},{"id":"opt_no_i_got","label":"No, I got stuck","image_key":null}],"allowOther":false},{"id":"blk_productt04","ref":"hardest_step","title":"Which step was hardest, and why?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productt05","ref":"stuck_where","title":"Where did you get stuck? Tell us what you were trying to do and what happened.","required":true,"visibility":null,"image_key":null,"agentHints":{"askStyle":"Ask them to walk through the steps in order, including what they clicked or pressed last.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_productt06","ref":"screenshot","title":"Got a screenshot or recording of the moment? Add it here.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*","video/*"],"maxFiles":3,"maxSizeMB":25},{"id":"blk_productt07","ref":"expected","title":"What did you expect to happen instead?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productt08","ref":"ease","title":"Overall, how easy was it to use?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":7,"startAt":1,"labelLow":"Very difficult","labelHigh":"Very easy"},{"id":"blk_productt09","ref":"quality","title":"How would you rate the quality of what you tested?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_productt10","ref":"bugs","title":"Did you notice anything broken or behaving oddly?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"