INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_productmarketfit', 'product-market-fit', 'Product-market fit survey', 'Survey', 'The disappointment question, a different follow-up for each answer, and who your fans are.', 'Asks how disappointed people would be if the product disappeared, then gives each answer its own conversation: fans describe the benefit in their own words, the somewhat disappointed say what''s missing, and the rest say why it isn''t useful. Everyone then names their alternative and where it falls short, and the role and team questions show who your fans are.', '["product","product market fit survey","pmf survey","startup research","customer research","product market fit questions"]', 'Target', 'number', 3, 10, '{"schemaVersion":9,"title":"Product-market fit survey","description":"The disappointment question, a different follow-up for each answer, and who your fans are.","blocks":[{"id":"blk_productm00","ref":"welcome","title":"A few questions about how you use us. Honest answers help most, including critical ones.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_productm01","ref":"usage","title":"How often do you use the product?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_day","label":"Every day","image_key":null},{"id":"opt_a_few_times","label":"A few times a week","image_key":null},{"id":"opt_a_few_times_2","label":"A few times a month","image_key":null},{"id":"opt_rarely","label":"Rarely","image_key":null}],"allowOther":false},{"id":"blk_productm02","ref":"disappointment","title":"How would you feel if you could no longer use this product?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_very_disappointed","label":"Very disappointed","image_key":null},{"id":"opt_somewhat_disappointed","label":"Somewhat disappointed","image_key":null},{"id":"opt_not_disappointed","label":"Not disappointed","image_key":null}],"allowOther":false},{"id":"blk_productm03","ref":"main_benefit","title":"What''s the main benefit you get from it?","description":"In your own words. We often learn the best way to describe us from answers like yours.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productm04","ref":"who_benefits","title":"What type of person do you think would benefit most from it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_productm05","ref":"whats_missing","title":"What would have to be true for you to be very disappointed without it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productm06","ref":"not_useful","title":"What stops it being useful to you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_productm07","ref":"alternative","title":"If it disappeared tomorrow, what would you use instead?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_productm08","ref":"falls_short","title":"Where does it still fall short for you?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_productm09","ref":"role","title":"What best describes your role?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_founder_or_exec","label":"Founder or exec","image_key":null},{"id":"opt_engineering","label":"Engineering","image_key":null},{"id":"opt_design","label":"Design","image_key":null},{"id":"opt_marketing","label":"Marketing","image_key":null},{"id":"opt_operations","label":"Operations","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"allowOther":false},{"id":"blk_productm10","ref":"team_size","title":"How big is the team you work in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_2_10","label":"2–10","image_key":null},{"id":"opt_11_50","label":"11–50","image_key":null},{"id":"opt_51_200","label":"51–200","image_key":null},{"id":"opt_200","label":"200+","image_key":null}],"allowOther":false}],"endings":[{"id":"end_productm01","ref":"end_thanks","title":"Really useful, thank you 🙏","bodyMd":"We read every answer, and the critical ones shape what we build next.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_productm01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"who_benefits","target":"alternative","targetKind":"block"},{"id":"rl_productm02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"whats_missing","target":"alternative","targetKind":"block"},{"id":"rl_productm03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"disappointment"},"op":"eq","value":"opt_very_disappointed"}],"groups":[]},"from":"disappointment","target":"main_benefit","targetKind":"block","branch":"true"},{"id":"rl_productm04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"disappointment"},"op":"eq","value":"opt_somewhat_disappointed"}],"groups":[]},"from":"disappointment","target":"whats_missing","targetKind":"block","branch":"true"},{"id":"rl_productm05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"disappointment"},"op":"eq","value":"opt_not_disappointed"}],"groups":[]},"from":"disappointment","target":"not_useful","targetKind":"block","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f3e6ff","surface":"#ffffff","text":"#2b1638","accent":"#9333ea","accentText":"#fdf9ff","botBubble":"#ffffff","userBubble":"#9333ea","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"confetti","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
