VALUES ('tpl_seanellistestproductmark', 'sean-ellis-test-product-market-fit-survey', 'Sean Ellis test survey', 'Survey', 'The four classic Sean Ellis questions, asked only of people who have really used the product.', 'Keeps the standard Sean Ellis questions and asks them of everyone in the same order, so your result is comparable from one round to the next. A first question thanks and releases people who have barely used the product, and anyone happy to talk more can leave an email for a follow-up interview.', '["product","sean ellis test","40 percent test","product market fit","pmf survey","startup metrics"]', 'Gauge', 'number', 3, 8, '{"schemaVersion":9,"title":"Sean Ellis test","description":"The four classic Sean Ellis questions, asked only of people who have really used the product.","blocks":[{"id":"blk_seanelli00","ref":"welcome","title":"We''d love your honest take on the product. A handful of short questions, about two minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_seanelli01","ref":"recent_use","title":"How much have you used the product recently?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_regularly_in_the","label":"Regularly in the past couple of weeks","image_key":null},{"id":"opt_a_few_times","label":"A few times in the past month","image_key":null},{"id":"opt_not_for_a","label":"Not for a while","image_key":null},{"id":"opt_i_only_tried","label":"I only tried it once","image_key":null}],"allowOther":false},{"id":"blk_seanelli02","ref":"disappointment","title":"How would you feel if you could no longer use the product?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_very_disappointed","label":"Very disappointed","image_key":null},{"id":"opt_somewhat_disappointed","label":"Somewhat disappointed","image_key":null},{"id":"opt_not_disappointed_it","label":"Not disappointed, it isn''t that useful","image_key":null}],"allowOther":false},{"id":"blk_seanelli03","ref":"alternative","title":"What would you use instead if it were no longer available?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":200},{"id":"blk_seanelli04","ref":"main_benefit","title":"What is the main benefit you get from the product?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_seanelli05","ref":"ideal_user","title":"What type of people do you think would benefit most from it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false},{"id":"blk_seanelli06","ref":"improve","title":"How could we improve the product to better meet your needs?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_seanelli07","ref":"interview","title":"Would you be up for a short follow-up chat about how you use it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_seanelli08","ref":"interview_email","title":"Great. Which email should we use to set it up?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_seanelli01","ref":"end_thanks","title":"Thank you 🙏","bodyMd":"Your answers go straight to the team deciding what to build next.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_seanelli02","ref":"end_not_yet","title":"Thanks for letting us know","bodyMd":"This survey is for people who use the product regularly, so we won''t take more of your time. We''d still love to hear from you if you come back to it.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_seanelli03","ref":"end_interview","title":"Thank you, we''ll be in touch 📅","bodyMd":"Someone from the team will email you to find a time that suits you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_seanelli01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"interview_email","target":"end_interview","targetKind":"ending"},{"id":"rl_seanelli02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"recent_use"},"op":"eq","value":"opt_not_for_a"}],"groups":[]},"from":"recent_use","target":"end_not_yet","targetKind":"ending","branch":"true"},{"id":"rl_seanelli03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"recent_use"},"op":"eq","value":"opt_i_only_tried"}],"groups":[]},"from":"recent_use","target":"end_not_yet","targetKind":"ending","branch":"true"},{"id":"rl_seanelli04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"interview"},"op":"eq","value":false}],"groups":[]},"from":"interview","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
