VALUES ('tpl_studentdemographicssurve', 'student-demographics-survey', 'Student demographics survey', 'Survey', 'Background questions that help you plan support, each one optional and easy to skip.', 'Sticks to background that changes how you plan: how people study, whether they work or care for someone, and whether they are first in their family to study at this level. Every sensitive question is optional with a prefer-not-to-say answer, and anyone who would like a word with student support can ask for one at the end.', '["school","student demographics survey","student background survey","education research","student profile","enrolment data"]', 'PieChart', 'choice', 4, 11, '{"schemaVersion":9,"title":"Student demographics","description":"Background questions that help you plan support, each one optional and easy to skip.","blocks":[{"id":"blk_studentd00","ref":"welcome","title":"Welcome! A few quick questions about you help us plan support that fits. Everything personal is optional.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_studentd01","ref":"purpose","title":"Why we''re asking","description":"We use these answers to understand our student group as a whole and to plan support, timetables and resources. Results are reported in groups, never by name. Edit this to say who will see the answers.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Continue","type":"statement"},{"id":"blk_studentd02","ref":"programme","title":"Which course or programme are you on?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_studentd03","ref":"year","title":"Which year of study are you in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_first_year","label":"First year","image_key":null},{"id":"opt_second_year","label":"Second year","image_key":null},{"id":"opt_third_year","label":"Third year","image_key":null},{"id":"opt_fourth_year_or","label":"Fourth year or later","image_key":null},{"id":"opt_postgraduate","label":"Postgraduate","image_key":null},{"id":"opt_other","label":"Other","image_key":null}]},{"id":"blk_studentd04","ref":"study_mode","title":"How are you studying?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_full_time_in","label":"Full-time, in person","image_key":null},{"id":"opt_part_time_in","label":"Part-time, in person","image_key":null},{"id":"opt_mostly_online","label":"Mostly online","image_key":null},{"id":"opt_a_mix_of","label":"A mix of online and in person","image_key":null}],"allowOther":false},{"id":"blk_studentd05","ref":"age_range","title":"Which age range are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_18","label":"Under 18","image_key":null},{"id":"opt_18_20","label":"18–20","image_key":null},{"id":"opt_21_24","label":"21–24","image_key":null},{"id":"opt_25_34","label":"25–34","image_key":null},{"id":"opt_35_or_over","label":"35 or over","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false},{"id":"blk_studentd06","ref":"gender","title":"How do you describe your gender?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_woman","label":"Woman","image_key":null},{"id":"opt_man","label":"Man","image_key":null},{"id":"opt_non_binary","label":"Non-binary","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":true},{"id":"blk_studentd07","ref":"first_generation","title":"Are you the first in your immediate family to study at this level?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_no","label":"No","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false},{"id":"blk_studentd08","ref":"first_language","title":"Is the language you''re taught in your first language?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_studentd09","ref":"work_hours","title":"Do you work alongside your studies?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_no","label":"No","image_key":null},{"id":"opt_yes_under_10","label":"Yes, under 10 hours a week","image_key":null},{"id":"opt_yes_10_20","label":"Yes, 10–20 hours a week","image_key":null},{"id":"opt_yes_more_than","label":"Yes, more than 20 hours a week","image_key":null},{"id":"opt_prefer_not_to","label":"Prefer not to say","image_key":null}],"allowOther":false},{"id":"blk_studentd10","ref":"responsibilities","title":"Do any of these apply to you?","description":"Pick any that fit, or none.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_i_care_for","label":"I care for a child","image_key":null},{"id":"opt_i_care_for_2","label":"I care for an adult family member","image_key":null},{"id":"opt_i_have_a","label":"I have a disability or long-term health condition","image_key":null},{"id":"opt_i_commute_more","label":"I commute more than an hour each way","image_key":null},{"id":"opt_i_ve_moved","label":"I''ve moved here from another country to study","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_studentd11","ref":"support_contact","title":"Would you like someone from student support to get in touch about any of this?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, please","noLabel":"No, thanks"},{"id":"blk_studentd12","ref":"contact_email","title":"What email should they use?","description":"This is only shared with the student support team.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_studentd01","ref":"end_thanks","title":"Thank you 🎓","bodyMd":"Your answers help us plan support around the students we actually have.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_studentd02","ref":"end_support","title":"Thanks, we''ll be in touch","bodyMd":"Someone from student support will email you. You don''t need to explain anything until you''re ready.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_studentd01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"contact_email","target":"end_support","targetKind":"ending"},{"id":"rl_studentd02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"support_contact"},"op":"eq","value":false}],"groups":[]},"from":"support_contact","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
