VALUES ('tpl_studentmentalhealthcheck', 'student-mental-health-check-in-survey', 'Student mental health check-in survey', 'Survey', 'A short, kind check-in that lets students ask for support without having to say it out loud.', 'Opens by saying who reads the answers and where to go if help is needed right away. The questions cover mood, sleep, workload and belonging in plain words, and the last one asks whether the student would like to talk to someone: only those who say yes are asked for contact details, and they get their own reassuring ending.', '["school","student mental health survey","wellbeing check-in","student wellbeing","pastoral care","school counselling"]', 'HeartHandshake', 'choice', 3, 9, '{"schemaVersion":9,"title":"Student wellbeing check-in","description":"A short, kind check-in that lets students ask for support without having to say it out loud.","blocks":[{"id":"blk_studentm00","ref":"welcome","title":"Hi. This is a quick check-in on how things are going for you. There are no right answers, and it takes about three minutes.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_studentm01","ref":"about","title":"Before you start","description":"Your answers are read by the student support team, usually within two school days. This isn''t monitored all the time, so if you need help right now, speak to a trusted adult or contact your local emergency services. Edit this to name your team and how to reach them.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Continue","type":"statement"},{"id":"blk_studentm02","ref":"year_group","title":"Which year group are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_year_7","label":"Year 7","image_key":null},{"id":"opt_year_8","label":"Year 8","image_key":null},{"id":"opt_year_9","label":"Year 9","image_key":null},{"id":"opt_year_10","label":"Year 10","image_key":null},{"id":"opt_year_11","label":"Year 11","image_key":null},{"id":"opt_sixth_form","label":"Sixth form","image_key":null}]},{"id":"blk_studentm03","ref":"mood","title":"Overall, how have you been feeling over the past two weeks?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Really low","labelHigh":"Really good"},{"id":"blk_studentm04","ref":"statements","title":"Over the past two weeks, how often has each of these been true for you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_i_ve","label":"I''ve been able to keep up with schoolwork"},{"id":"opt_row_i_ve_2","label":"I''ve slept well enough to feel rested"},{"id":"opt_row_i_ve_3","label":"I''ve had someone I can talk to"},{"id":"opt_row_i_ve_4","label":"I''ve felt like I belong at school"},{"id":"opt_row_i_ve_5","label":"I''ve had time for things I enjoy"}],"columns":[{"id":"opt_col_rarely","label":"Rarely"},{"id":"opt_col_sometimes","label":"Sometimes"},{"id":"opt_col_often","label":"Often"},{"id":"opt_col_almost_always","label":"Almost always"}],"multiplePerRow":false},{"id":"blk_studentm05","ref":"weighing","title":"Is anything weighing on you at the moment?","description":"Pick any that fit.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_schoolwork_or_deadlines","label":"Schoolwork or deadlines","image_key":null},{"id":"opt_exams","label":"Exams","image_key":null},{"id":"opt_friendships","label":"Friendships","image_key":null},{"id":"opt_things_at_home","label":"Things at home","image_key":null},{"id":"opt_money","label":"Money","image_key":null},{"id":"opt_sleep","label":"Sleep","image_key":null},{"id":"opt_my_health","label":"My health","image_key":null},{"id":"opt_things_online","label":"Things online","image_key":null},{"id":"opt_nothing_much_right","label":"Nothing much right now","image_key":null}],"minSelections":1,"maxSelections":9,"allowOther":true},{"id":"blk_studentm06","ref":"helps","title":"What has helped you get through a tough day lately?","required":false,"visibility":null,"image_key":null,"agentHints":{"askStyle":"Keep it light and optional. Accept a short answer and never push for more on a sensitive topic.","examples":[]},"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_studentm07","ref":"school_support","title":"Is there anything school could do that would make things a bit easier?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_studentm08","ref":"talk","title":"Would you like to talk to someone from the support team?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_soon_please","label":"Yes, soon please","image_key":null},{"id":"opt_maybe_but_not","label":"Maybe, but not urgently","image_key":null},{"id":"opt_no_thanks","label":"No, thanks","image_key":null}],"allowOther":false},{"id":"blk_studentm09","ref":"name","title":"What''s your name, so the right person can find you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_studentm10","ref":"reach_by","title":"How would you prefer they reach you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_find_me_quietly","label":"Find me quietly during the school day","image_key":null},{"id":"opt_send_me_a","label":"Send me a message on the school system","image_key":null},{"id":"opt_email_me","label":"Email me","image_key":null}],"allowOther":false}],"endings":[{"id":"end_studentm01","ref":"end_thanks","title":"Thanks for checking in","bodyMd":"If you ever want to talk, you can fill this in again or speak to any member of staff you trust.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_studentm02","ref":"end_talk","title":"Thank you for telling us 💛","bodyMd":"Someone from the support team will reach out the way you asked. If things feel worse before then, talk to a trusted adult straight away.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_studentm01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"reach_by","target":"end_talk","targetKind":"ending"},{"id":"rl_studentm02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"talk"},"op":"eq","value":"opt_no_thanks"}],"groups":[]},"from":"talk","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffe4d3","surface":"#ffffff","text":"#3a2418","accent":"#c2410c","accentText":"#fffaf5","botBubble":"#ffffff","userBubble":"#c2410c","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
