VALUES ('tpl_schoolclimatesurvey', 'school-climate-survey', 'School climate survey', 'Survey', 'One survey for students, parents and staff on safety, respect, belonging and support.', 'Everyone rates the same statements about respect, safety and fairness, so you can compare how students, parents and staff see the school. Each group then gets one question of its own, and anyone who has seen or experienced bullying is asked what happened, with the option to leave it anonymous.', '["school","school climate survey","school culture survey","student safety survey","parent survey","staff survey"]', 'School', 'choice', 3, 11, '{"schemaVersion":9,"title":"School climate survey","description":"One survey for students, parents and staff on safety, respect, belonging and support.","blocks":[{"id":"blk_schoolcl00","ref":"welcome","title":"We want to know what our school really feels like from the inside. It takes about five minutes, and answers are anonymous.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_schoolcl01","ref":"statements","title":"How much do you agree with each of these?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"matrix","rows":[{"id":"opt_row_people_here","label":"People here treat each other with respect"},{"id":"opt_row_students_feel","label":"Students feel safe at school"},{"id":"opt_row_adults_here","label":"Adults here care about students"},{"id":"opt_row_rules_are","label":"Rules are fair and applied consistently"},{"id":"opt_row_bullying_is","label":"Bullying is dealt with when it''s reported"},{"id":"opt_row_it_s","label":"It''s clear who to go to with a problem"}],"columns":[{"id":"opt_col_strongly_disagree","label":"Strongly disagree"},{"id":"opt_col_disagree","label":"Disagree"},{"id":"opt_col_agree","label":"Agree"},{"id":"opt_col_strongly_agree","label":"Strongly agree"}],"multiplePerRow":false},{"id":"blk_schoolcl02","ref":"belonging","title":"How much do you feel you belong in this school community?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Not at all","labelHigh":"Completely"},{"id":"blk_schoolcl03","ref":"role","title":"And which of these describes you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_student","label":"Student","image_key":null},{"id":"opt_parent_or_carer","label":"Parent or carer","image_key":null},{"id":"opt_member_of_staff","label":"Member of staff","image_key":null}],"allowOther":false},{"id":"blk_schoolcl04","ref":"learning_support","title":"When you''re stuck with your learning, how easy is it to get help?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_schoolcl05","ref":"communication","title":"How well does the school keep you informed about your child?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_schoolcl06","ref":"staff_support","title":"How well supported do you feel when dealing with behaviour?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"rating","scale":5,"shape":"star"},{"id":"blk_schoolcl07","ref":"less_safe","title":"Are there places or times when students feel less safe?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_corridors_between_lessons","label":"Corridors between lessons","image_key":null},{"id":"opt_toilets","label":"Toilets","image_key":null},{"id":"opt_playground_or_outdoor","label":"Playground or outdoor areas","image_key":null},{"id":"opt_lunchtime","label":"Lunchtime","image_key":null},{"id":"opt_the_journey_to","label":"The journey to or from school","i