gh":"Completely"},{"id":"blk_studentf11","ref":"recommend","title":"How likely are you to recommend this course to another student?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"nps","labelLow":"Not likely","labelHigh":"Extremely likely"},{"id":"blk_studentf12","ref":"what_would_change_it","title":"What would have to be different for you to recommend it?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false},{"id":"blk_studentf13","ref":"quote_ok","title":"May we quote your feedback on the course page?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, with my first name","noLabel":"Please don''t"},{"id":"blk_studentf14","ref":"quote_name","title":"What first name should we put next to your quote?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40}],"endings":[{"id":"end_studentf01","ref":"end_thanks","title":"Thank you 📚","bodyMd":"Every group that follows gets a better course because of answers like these.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_studentf01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"slow_where","target":"most_useful","targetKind":"block"},{"id":"rl_studentf02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"what_would_change_it","target":"end_thanks","targetKind":"ending"},{"id":"rl_studentf03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"pace"},"op":"eq","value":"opt_too_slow"}],"groups":[]},"from":"pace","target":"slow_where","targetKind":"block","branch":"true"},{"id":"rl_studentf04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind"