VALUES ('tpl_facebookleadgeneration', 'facebook-lead-generation', 'Facebook lead generation quiz', 'Quiz', 'A plan-finder quiz for ad traffic that scores fit and flags who wants to start now.', 'People who click an ad want the thing the ad promised, not a contact form. This quiz gives them a starting plan matched to their answers, scored on how active and experienced they already are. Anyone who says they want to start this week is asked for a phone number, so your hottest leads are easy to call first.', '["lead generation","facebook lead generation","lead quiz","facebook ads","qualifying leads","fitness coaching"]', 'Target', 'advanced', 3, 9, '{"schemaVersion":9,"title":"Facebook lead quiz","description":"A plan-finder quiz for ad traffic that scores fit and flags who wants to start now.","blocks":[{"id":"blk_facebook00","ref":"welcome","title":"You came from our ad about getting fit at home. Answer a few quick questions and we''ll match you to a starting plan.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_facebook01","ref":"goal","title":"What''s the main thing you want to change?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_lose_some_weight","label":"Lose some weight","image_key":null},{"id":"opt_get_stronger","label":"Get stronger","image_key":null},{"id":"opt_have_more_energy","label":"Have more energy","image_key":null},{"id":"opt_train_for_an","label":"Train for an event","image_key":null}],"allowOther":false},{"id":"blk_facebook02","ref":"activity","title":"How often do you exercise right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_hardly_at_all","label":"Hardly at all","image_key":null,"score":0},{"id":"opt_once_or_twice","label":"Once or twice a week","image_key":null,"score":1},{"id":"opt_three_or_four","label":"Three or four times a week","image_key":null,"score":2},{"id":"opt_five_times_or","label":"Five times or more","image_key":null,"score":3}],"allowOther":false},{"id":"blk_facebook03","ref":"strength_experience","title":"Have you done strength training before?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_never_tried_it","label":"Never tried it","image_key":null,"score":0},{"id":"opt_a_bit_on","label":"A bit, on and off","image_key":null,"score":1},{"id":"opt_yes_regularly","label":"Yes, regularly","image_key":null,"score":2}],"allowOther":false},{"id":"blk_facebook04","ref":"session_time","title":"How long could a typical workout be?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_15_20_minutes","label":"15–20 minutes","image_key":null,"score":0},{"id":"opt_30_45_minutes","label":"30–45 minutes","image_key":null,"score":1},{"id":"opt_an_hour_or","label":"An hour or more","image_key":null,"score":2}],"allowOther":false},{"id":"blk_facebook05","ref":"obstacles","title":"What has got in the way before?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_not_enough_time","label":"Not enough time","image_key":null},{"id":"opt_losing_motivation","label":"Losing motivation","image_key":null},{"id":"opt_not_knowing_what","label":"Not knowing what to do","image_key":null},{"id":"opt_injuries_or_pain","label":"Injuries or pain","image_key":null},{"id":"opt_getting_bored","label":"Getting bored","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_facebook06","ref":"start_when","title":"When would you like to get going?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_this_week","label":"This week","image_key":null},{"id":"opt_within_the_next","label":"Within the next month","image_key":null},{"id":"opt_just_looking_for","label":"Just looking for now","image_key":null}],"allowOther":false},{"id":"blk_facebook07","ref":"phone","title":"What''s the best number for a short call with a coach?","description":"Ten minutes to set up your first week. You can skip this if you''d rather use email.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"phone","unique":false,"verify":false},{"id":"blk_facebook08","ref":"contact","title":"Where should we send your plan?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","email"]},{"id":"blk_facebook09","ref":"consent","title":"Hearing from us","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"Send me my plan and occasional emails about coaching. I can unsubscribe at any time.","allowDecline":false,"agreeLabel":"I agree","declineLabel":"I do not agree"}],"endings":[{"id":"end_facebook01","ref":"end_thanks","title":"Your plan: Fresh start 🌱","bodyMd":"Short, simple home sessions you can fit into a busy day, with no equipment needed at first. The aim is to make moving a habit before making it hard. Your full plan is on its way to your inbox.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_facebook02","ref":"end_performance","title":"Your plan: Performance block 🏋️","bodyMd":"You already train regularly and have a base to build on, so this plan adds structure and progression: four focused sessions a week that build on each other. Your full plan is on its way to your inbox.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_facebook03","ref":"end_build","title":"Your plan: Build-up programme 💪","bodyMd":"You have some habits to build on. Three sessions a week mix strength and cardio, with a small step up every fortnight so it never feels like starting over. Your full plan is on its way to your inbox.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_facebook01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":5}],"groups":[]},"target":"end_performance","targetKind":"ending"},{"id":"rs_facebook02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":2}],"groups":[]},"target":"end_build","targetKind":"ending"}],"logic":[{"id":"rl_facebook01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_facebook02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"activity"},"op":"eq","value":"opt_once_or_twice"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_facebook03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"activity"},"op":"eq","value":"opt_three_or_four"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_facebook04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"activity"},"op":"eq","value":"opt_five_times_or"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_facebook05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"strength_experience"},"op":"eq","value":"opt_a_bit_on"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_facebook06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"strength_experience"},"op":"eq","value":"opt_yes_regularly"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_facebook07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"session_time"},"op":"eq","value":"opt_30_45_minutes"}],"groups":[]},"variable":"score"