INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_personalityquiz', 'personality-quiz', 'Personality quiz', 'Quiz', 'Six everyday scenarios that place people on a planner to improviser scale, with four result types.', 'Six everyday situations, from a free Saturday to a looming deadline, each with four honest answers and no wrong one. Every answer adds to a score from planner to improviser, and the total lands on one of four types with a short explanation. Players who want the longer profile leave an email, which makes it a friendly lead magnet.', '["lead generation","personality quiz","work style quiz","personality test","fun quiz","quiz lead magnet"]', 'Brain', 'advanced', 3, 10, '{"schemaVersion":9,"title":"Work style personality quiz","description":"Six everyday scenarios that place people on a planner to improviser scale, with four result types.","blocks":[{"id":"blk_personal00","ref":"welcome","title":"Do you plan the week on Sunday or decide on Monday morning? Answer six everyday situations to find your work style.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_personal01","ref":"first_name","title":"Whose work style are we reading today?","description":"A first name is plenty.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_personal02","ref":"saturday","title":"A free Saturday opens up. What happens?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_s_planned","label":"It''s planned by Friday night","image_key":null,"score":3},{"id":"opt_i_jot_down","label":"I jot down a loose list","image_key":null,"score":2},{"id":"opt_i_pick_one","label":"I pick one thing and see where it goes","image_key":null,"score":1},{"id":"opt_i_wake_up","label":"I wake up and decide","image_key":null,"score":0}],"allowOther":false},{"id":"blk_personal03","ref":"new_project","title":"You''re handed a new project. What''s your first move?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_write_out_every","label":"Write out every step and a timeline","image_key":null,"score":3},{"id":"opt_sketch_the_big","label":"Sketch the big milestones","image_key":null,"score":2},{"id":"opt_start_on_the","label":"Start on the part that excites me","image_key":null,"score":1},{"id":"opt_dive_in_and","label":"Dive in and work it out as I go","image_key":null,"score":0}],"allowOther":false},{"id":"blk_personal04","ref":"plans_change","title":"Plans change at the last minute. How do you feel?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_thrown_until_i","label":"Thrown, until I have a new plan","image_key":null,"score":3},{"id":"opt_a_little_annoyed","label":"A little annoyed, then I adjust","image_key":null,"score":2},{"id":"opt_fine_it_happens","label":"Fine, it happens","image_key":null,"score":1},{"id":"opt_quietly_pleased_something","label":"Quietly pleased, something new","image_key":null,"score":0}],"allowOther":false},{"id":"blk_personal05","ref":"desk","title":"Be honest: what does your desk or inbox look like right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_sorted_into_folders","label":"Sorted into folders","image_key":null,"score":3},{"id":"opt_mostly_tidy","label":"Mostly tidy","image_key":null,"score":2},{"id":"opt_organised_chaos","label":"Organised chaos","image_key":null,"score":1},{"id":"opt_best_not_to","label":"Best not to ask","image_key":null,"score":0}],"allowOther":false},{"id":"blk_personal06","ref":"packing","title":"How do you pack for a trip?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_from_a_checklist","label":"From a checklist, days ahead","image_key":null,"score":3},{"id":"opt_the_night_before","label":"The night before, from memory","image_key":null,"score":2},{"id":"opt_an_hour_before","label":"An hour before I leave","image_key":null,"score":1},{"id":"opt_i_ll_buy","label":"I''ll buy whatever I forget","image_key":null,"score":0}],"allowOther":false},{"id":"blk_personal07","ref":"deadlines","title":"Which sounds most like you and deadlines?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_finish_days","label":"I finish days early","image_key":null,"score":3},{"id":"opt_i_finish_right","label":"I finish right on time","image_key":null,"score":2},{"id":"opt_the_pressure_helps","label":"The pressure helps me focus","image_key":null,"score":1},{"id":"opt_the_deadline_is","label":"The deadline is when I really start","image_key":null,"score":0}],"allowOther":false},{"id":"blk_personal08","ref":"want_profile","title":"Want your full profile by email, with tips for working with the other three types?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes, send it","noLabel":"Just show me my type"},{"id":"blk_personal09","ref":"email","title":"Where should we send it?","description":"Your profile, plus the occasional note from us. Unsubscribe any time.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_personal10","ref":"self_guess","title":"Before the reveal: where do you think you''ll land?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Total improviser","labelHigh":"Total planner"}],"endings":[{"id":"end_personal01","ref":"end_thanks","title":"You''re the Improviser ⚡","bodyMd":"You think best on your feet and some of your best ideas arrive at the last minute. Pair up with a planner on big projects and you''ll bring the spark while they keep the dates.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_personal02","ref":"end_architect","title":"You''re the Architect 📐","bodyMd":"You like to see the whole plan before you start, and it shows: things get done early and properly. Your growth edge is leaving a little room for the plan to change without it feeling like a setback.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_personal03","ref":"end_steady","title":"You''re the Steady Hand","bodyMd":"You plan enough to feel in control but not so much that a change throws you. Teams lean on you because you are reliable without being rigid.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_personal04","ref":"end_adapter","title":"You''re the Adapter","bodyMd":"You set a direction and then follow the energy, adjusting as you learn. You do well when things are moving fast, and a short checklist for the boring parts keeps you on time.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_personal01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":14}],"groups":[]},"target":"end_architect","targetKind":"ending"},{"id":"rs_personal02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":9}],"groups":[]},"target":"end_steady","targetKind":"ending"},{"id":"rs_personal03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":5}],"groups":[]},"target":"end_adapter","targetKind":"ending"}],"logic":[{"id":"rl_personal01","action_kind":