VALUES ('tpl_flagsoftheworldquiz', 'flags-of-the-world-quiz', 'Flags of the world quiz', 'Quiz', 'Nine scored flag questions, each flag described in words, from maple leaves to dragons.', 'Every flag is described in words, so players have to picture it rather than spot it, which makes a familiar topic feel fresh. Correct answers carry a point, the Southern Cross round takes one away for a wrong pick, and the total lands on one of three results.', '["marketing","flags of the world quiz","flag quiz","vexillology trivia","geography trivia","classroom quiz","pub quiz"]', 'Flag', 'scale', 4, 11, '{"schemaVersion":9,"title":"Flags of the world quiz","description":"Nine scored flag questions, each flag described in words, from maple leaves to dragons.","blocks":[{"id":"blk_flagsof00","ref":"welcome","title":"Think you know your flags? I''ll describe each one, you name the country. Nine rounds, and a result at the end.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_flagsof01","ref":"player","title":"What name should go on the scoreboard?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_flagsof02","ref":"maple_leaf","title":"A red maple leaf on a white square, with a red band on each side. Whose flag is it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_canada","label":"Canada","image_key":null,"score":1},{"id":"opt_peru","label":"Peru","image_key":null},{"id":"opt_austria","label":"Austria","image_key":null},{"id":"opt_lebanon","label":"Lebanon","image_key":null}],"allowOther":false},{"id":"blk_flagsof03","ref":"not_rectangle","title":"Only one national flag is not a rectangle. It is two stacked red triangles with a blue border. Which country?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_bhutan","label":"Bhutan","image_key":null},{"id":"opt_nepal","label":"Nepal","image_key":null,"score":1},{"id":"opt_sri_lanka","label":"Sri Lanka","image_key":null},{"id":"opt_maldives","label":"Maldives","image_key":null}],"allowOther":false},{"id":"blk_flagsof04","ref":"cedar","title":"Which country''s flag has a green cedar tree between two red stripes?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_cyprus","label":"Cyprus","image_key":null},{"id":"opt_jordan","label":"Jordan","image_key":null},{"id":"opt_lebanon","label":"Lebanon","image_key":null,"score":1},{"id":"opt_israel","label":"Israel","image_key":null}],"allowOther":false},{"id":"blk_flagsof05","ref":"nordic_cross","title":"A white cross on a red background, with the upright pushed toward the pole. Which country?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_switzerland","label":"Switzerland","image_key":null},{"id":"opt_norway","label":"Norway","image_key":null},{"id":"opt_denmark","label":"Denmark","image_key":null,"score":1},{"id":"opt_finland","label":"Finland","image_key":null}],"allowOther":false},{"id":"blk_flagsof06","ref":"red_disc","title":"Japan''s flag is a red disc on white. Which country flies a red disc on dark green?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_bangladesh","label":"Bangladesh","image_key":null,"score":1},{"id":"opt_pakistan","label":"Pakistan","image_key":null},{"id":"opt_palau","label":"Palau","image_key":null},{"id":"opt_laos","label":"Laos","image_key":null}],"allowOther":false},{"id":"blk_flagsof07","ref":"southern_cross","title":"Which of these flags show the Southern Cross constellation? Pick all that apply.","required":true,"visibility":null,"image_key"