VALUES ('tpl_harrypottertriviaquiz', 'harry-potter-trivia-quiz', 'Harry Potter trivia quiz', 'Quiz', 'Nine scored questions on the seven books, spoilers included.', 'Written from the books, not the films, and it says so up front so nobody argues about a scene that was cut. The questions start gentle and end deep in Deathly Hallows, a Horcrux round takes a point for each wrong pick, and the total picks one of three results.', '["marketing","harry potter trivia","harry potter quiz","book club quiz","fan quiz","trivia night"]', 'Sparkles', 'scale', 4, 11, '{"schemaVersion":9,"title":"Harry Potter trivia quiz","description":"Nine scored questions on the seven books, spoilers included.","blocks":[{"id":"blk_harrypot00","ref":"welcome","title":"Welcome to the Harry Potter trivia quiz. Every question comes from the seven books, and there are spoilers for all of them. Ready?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_harrypot01","ref":"player","title":"What name should go on the scoreboard?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_harrypot02","ref":"house","title":"Just for fun, no points: which house would the Sorting Hat put you in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_gryffindor","label":"Gryffindor","image_key":null},{"id":"opt_hufflepuff","label":"Hufflepuff","image_key":null},{"id":"opt_ravenclaw","label":"Ravenclaw","image_key":null},{"id":"opt_slytherin","label":"Slytherin","image_key":null}],"allowOther":false},{"id":"blk_harrypot03","ref":"platform","title":"Which platform at King''s Cross does the Hogwarts Express leave from?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_platform_7","lab