VALUES ('tpl_irishquiz', 'irish-quiz', 'Irish quiz', 'Quiz', 'Ten scored questions on Ireland''s places, words, books and history.', 'Mixes four kinds of knowledge so no single expert runs away with it: geography, history, the Irish language and literature. A provinces round takes a point for each county picked by mistake, and the total lands on one of three results.', '["marketing","irish quiz","ireland trivia","st patrick''s day quiz","irish culture quiz","pub quiz"]', 'Leaf', 'scale', 4, 12, '{"schemaVersion":9,"title":"Irish quiz","description":"Ten scored questions on Ireland''s places, words, books and history.","blocks":[{"id":"blk_irishqui00","ref":"welcome","title":"Fáilte! Ten questions about Ireland, from rivers to writers. Let''s see how you get on.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_irishqui01","ref":"player","title":"What name should go on the scoreboard?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_irishqui02","ref":"st_patricks","title":"An easy one to start. On what date is St Patrick''s Day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_1_march","label":"1 March","image_key":null},{"id":"opt_17_march","label":"17 March","image_key":null,"score":1},{"id":"opt_23_april","label":"23 April","image_key":null},{"id":"opt_30_november","label":"30 November","image_key":null}],"allowOther":false},{"id":"blk_irishqui03","ref":"easter_rising","title":"In which year did the Easter Rising take place in Dublin?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_1798","label":"1798","image_key":null},{"id":"opt_1845","label":"1845","image_key":null},{"id":"opt_1916","label":"1916","image_key":null