INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_leadershipstylequiz', 'leadership-style-quiz', 'Leadership style quiz', 'Quiz', 'Six workplace situations that place you on a scale from directing to delegating.', 'Instead of asking people to pick a label, it puts them in six real situations: a missed deadline, a new starter, a big decision. Each answer scores how much control you hand to the team, and the total lands on one of four styles with a strength and a blind spot for each.', '["marketing","leadership style quiz","management style quiz","leadership assessment","manager training","team leadership"]', 'Compass', 'scale', 3, 10, '{"schemaVersion":9,"title":"Leadership style quiz","description":"Six workplace situations that place you on a scale from directing to delegating.","blocks":[{"id":"blk_leadersh00","ref":"welcome","title":"What kind of leader are you on a normal Tuesday? Six quick situations, no right or wrong answers. Pick what you would actually do, not what sounds best.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_leadersh01","ref":"name","title":"What''s your first name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_leadersh02","ref":"team_size","title":"How many people report to you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_none_yet_i","label":"None yet, I''m preparing to lead","image_key":null},{"id":"opt_1_to_3","label":"1 to 3","image_key":null},{"id":"opt_4_to_8","label":"4 to 8","image_key":null},{"id":"opt_9_to_15","label":"9 to 15","image_key":null},{"id":"opt_more_than_15","label":"More than 15","image_key":null}]},{"id":"blk_leadersh03","ref":"new_project","title":"A new project lands on your team. What do you do first?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_share_the_goal","label":"Share the goal and ask who wants to own it","image_key":null,"score":3},{"id":"opt_write_the_plan","label":"Write the plan and hand out the tasks","image_key":null,"score":0},{"id":"opt_run_a_session","label":"Run a session so the team shapes the plan together","image_key":null,"score":2},{"id":"opt_draft_a_plan","label":"Draft a plan, then walk the team through why","image_key":null,"score":1}],"allowOther":false},{"id":"blk_leadersh04","ref":"missed_deadline","title":"A reliable teammate misses a deadline. How do you handle it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_ask_what_got","label":"Ask what got in the way and what they need from me","image_key":null,"score":2},{"id":"opt_set_a_new","label":"Set a new date and check in daily until it''s done","image_key":null,"score":0},{"id":"opt_trust_them_to","label":"Trust them to sort it and mention it at our next one-to-one","image_key":null,"score":3},{"id":"opt_go_through_the","label":"Go through the work with them and show where it slipped","image_key":null,"score":1}],"allowOther":false},{"id":"blk_leadersh05","ref":"new_starter","title":"Someone new joins the team. How do you get them up to speed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_give_them_a","label":"Give them a clear checklist and review each step","image_key":null,"score":0},{"id":"opt_pair_them_with","label":"Pair them with a teammate and let them find their way","image_key":null,"score":3},{"id":"opt_meet_often_explain","label":"Meet often, explain the reasons behind how we work","image_key":null,"score":1},{"id":"opt_ask_how_they","label":"Ask how they like to learn and build the plan with them","image_key":null,"score":2}],"allowOther":false},{"id":"blk_leadersh06","ref":"big_decision","title":"A decision needs making that affects the whole team. How is it made?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_gather_views","label":"I gather views, then make the call and explain it","image_key":null,"score":1},{"id":"opt_we_talk_it","label":"We talk it through and agree together","image_key":null,"score":2},{"id":"opt_i_decide_quickly","label":"I decide quickly and let everyone know","image_key":null,"score":0},{"id":"opt_the_people_closest","label":"The people closest to the work decide","image_key":null,"score":3}],"allowOther":false},{"id":"blk_leadersh07","ref":"disagreement","title":"Two teammates disagree on how to do a task. What do you do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_leave_it_with","label":"Leave it with them; they''ll work it out","image_key":null,"score":3},{"id":"opt_pick_the_approach","label":"Pick the approach and move them on","image_key":null,"score":0},{"id":"opt_help_them_talk","label":"Help them talk it through until they agree","image_key":null,"score":2},{"id":"opt_hear_both_sides","label":"Hear both sides, choose, and explain my reasoning","image_key":null,"score":1}],"allowOther":false},{"id":"blk_leadersh08","ref":"feedback","title":"How does your team usually hear how they''re doing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_tell_them","label":"I tell them straight away when something needs fixing","image_key":null,"score":0},{"id":"opt_regular_coaching_conversat","label":"Regular coaching conversations with examples","image_key":null,"score":1},{"id":"opt_they_ask_for","label":"They ask for it when they want it","image_key":null,"score":3},{"id":"opt_two_way_check","label":"Two-way check-ins where they rate themselves first","image_key":null,"score":2}],"allowOther":false},{"id":"blk_leadersh09","ref":"delegation_comfort","title":"How comfortable are you handing over work you could do faster yourself?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"I''d rather do it","labelHigh":"Happy to let go"},{"id":"blk_leadersh10","ref":"growth","title":"What''s one thing about how you lead that you''d like to get better at?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":600,"aiQualityCheck":false}],"endings":[{"id":"end_leadersh01","ref":"end_thanks","title":"You lead by directing","bodyMd":"You give clear instructions and keep a close eye on the work, which helps in a crisis or with new starters. Try handing one decision a week to the team and see who grows into it.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_leadersh02","ref":"end_delegating","title":"You lead by delegating 🪁","bodyMd":"You hand real ownership to your team and trust them to run with it. That works best with experienced people; with newer ones, agree how and when you''ll check in so freedom doesn''t feel like being left alone.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_leadersh03","ref":"end_supporting","title":"You lead by supporting","bodyMd":"You share decisions and help people find their own answers, which builds commitment. Watch for slow calls when the team needs a quick one; sometimes the kindest move is to decide.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_leadersh04","ref":"end_coaching","title":"You lead by coaching","bodyMd":"You set the direction but explain the why and invite ideas, which is a strong fit for growing teams. The next step is letting people own a decision end to end, even if they''d do it differently.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_leadersh01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":14}],"groups":[]},"target":"end_delegating","targetKind":"ending"},{"id":"rs_leadersh02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":9}],"groups":[]},"target":"end_supporting","targetKind":"ending"},{"id":"rs_leadersh03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":5}],"groups":[]},"target":"end_coaching","targetKind":"ending"}],"logic":[{"id":"rl_leadersh01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_leadersh02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"new_project"},"op":"eq","value":"opt_share_the_goal"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_leadersh03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"new_project"},"op":"eq","value":"opt_run_a_session"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_leadersh04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"new_project"},"op":"eq","value":"opt_draft_a_plan"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_leadersh05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"missed_deadline"},"op":"eq","value":"opt_ask_what_got"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_leadersh06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"missed_deadline"},"op":"eq","value":"opt_trust_them_to"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_leadersh07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"missed_deadline"},"op":"eq","value":"opt_go_through_the"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_leadersh08","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"new_starter"},"op":"eq","value":"opt_pair_them_with"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_leadersh09","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"new_starter"},"op":"eq","value":"opt_meet_often_explain"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_leadersh10","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"new_starter"},"op":"eq","value":"opt_ask_how_they"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_leadersh11","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"big_decision"},"op":"eq","value":"opt_i_gather_views"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_leadersh12","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"big_decision"},"op":"eq","value":"opt_we_talk_it"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_leadersh13","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"big_decision"},"op":"eq","value":"opt_the_people_closest"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_leadersh14","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"disagreement"},"op":"eq","value":"opt_leave_it_with"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_leadersh15","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"disagreement"},"op":"eq","value":"opt_help_them_talk"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_leadersh16","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"disagreement"},"op":"eq","value":"opt_hear_both_sides"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_leadersh17","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feedback"},"op":"eq","value":"opt_regular_coaching_conversat"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_leadersh18","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feedback"},"op":"eq","value":"opt_they_ask_for"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_leadersh19","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feedback"},"op":"eq","value":"opt_two_way_check"}],"groups":[]},"variable":"score","amount":2}],"layout":{},"variables":[{"name":"score","type":"number","initial":0}],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
