INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_logoquiz', 'logo-quiz', 'Logo quiz', 'Quiz', 'Ten scored questions about the hidden details in logos people see every day.', 'Instead of asking players to name a logo from a picture, it asks what is hidden in it, so even people who see these marks daily have to think. A prancing horse round costs a point for each wrong pick, and the total lands on one of three results.', '["marketing","logo quiz","brand logo trivia","design quiz","marketing trivia","branding quiz"]', 'Palette', 'scale', 4, 12, '{"schemaVersion":9,"title":"Logo quiz","description":"Ten scored questions about the hidden details in logos people see every day.","blocks":[{"id":"blk_logoquiz00","ref":"welcome","title":"You see these logos every day. But do you know what''s hidden in them? Ten questions, then your result.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_logoquiz01","ref":"player","title":"What name should go on the scoreboard?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_logoquiz02","ref":"fedex","title":"What''s hidden in the white space between the ''E'' and the ''x'' of the FedEx logo?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_key","label":"A key","image_key":null},{"id":"opt_an_arrow","label":"An arrow","image_key":null,"score":1},{"id":"opt_a_plane","label":"A plane","image_key":null},{"id":"opt_a_letter_f","label":"A letter F","image_key":null}],"allowOther":false},{"id":"blk_logoquiz03","ref":"amazon","title":"The curved arrow under the Amazon wordmark runs between which two letters?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_to_z","label":"A to Z","image_key":null,"score":1},{"id":"opt_m_to_n","label":"M to N","image_key":null},{"id":"opt_a_to_n","label":"A to N","image_key":null},{"id":"opt_z_to_a","label":"Z to A","image_key":null}],"allowOther":false},{"id":"blk_logoquiz04","ref":"starbucks","title":"Who is the figure in the Starbucks logo?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_norse_sea","label":"A Norse sea goddess","image_key":null},{"id":"opt_a_twin_tailed","label":"A twin-tailed siren","image_key":null,"score":1},{"id":"opt_poseidon_s_daughter","label":"Poseidon''s daughter","image_key":null},{"id":"opt_a_ship_s","label":"A ship''s figurehead","image_key":null}],"allowOther":false},{"id":"blk_logoquiz05","ref":"tostitos","title":"In the Tostitos wordmark, what do the two t''s either side of the ''i'' form?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_two_people_sharing","label":"Two people sharing a chip over a bowl of salsa","image_key":null,"score":1},{"id":"opt_a_pair_of","label":"A pair of corn stalks","image_key":null},{"id":"opt_a_sombrero","label":"A sombrero","image_key":null},{"id":"opt_two_hands_waving","label":"Two hands waving","image_key":null}],"allowOther":false},{"id":"blk_logoquiz06","ref":"horses","title":"Which of these car makers have a horse in their badge? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_ferrari","label":"Ferrari","image_key":null,"score":1},{"id":"opt_lamborghini","label":"Lamborghini","image_key":null,"score":-1},{"id":"opt_porsche","label":"Porsche","image_key":null,"score":1},{"id":"opt_peugeot","label":"Peugeot","image_key":null,"score":-1}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_logoquiz07","ref":"maserati","title":"Which car maker uses a trident as its badge?","required":true,"visibility":null,"image_key":null,"