":"single_select","options":[{"id":"opt_three_diamonds","label":"Three diamonds","image_key":null,"score":1},{"id":"opt_three_mountains","label":"Three mountains","image_key":null},{"id":"opt_three_arrows","label":"Three arrows","image_key":null},{"id":"opt_three_petals","label":"Three petals","image_key":null}],"allowOther":false},{"id":"blk_logoquiz12","ref":"favourite","title":"No points here: which logo do you think is the cleverest, and why?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":400,"aiQualityCheck":false}],"endings":[{"id":"end_logoquiz01","ref":"end_thanks","title":"You''ll never unsee them now","bodyMd":"Next time you pass a FedEx van or open a Toblerone, look again. Then come back and beat your score.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_logoquiz02","ref":"end_expert","title":"Brand detective 🔍","bodyMd":"Hidden arrows, star clusters, a bear in a mountain: you spotted nearly all of it. Designers would enjoy talking to you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_logoquiz03","ref":"end_spotter","title":"Good eye","bodyMd":"A solid score. A couple of hidden details slipped past, but you notice more than most.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_logoquiz01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":10}],"groups":[]},"target":"end_expert","targetKind":"ending"},{"id":"rs_logoquiz02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":6}],"groups":[]},"target":"end_spotter","targetKind":"ending"}],"logic":[{"id":"rl_logoquiz01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_logoquiz02","actio