INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_marketingresearchquiz', 'marketing-research-quiz', 'Marketing research quiz', 'Quiz', 'Ten scored scenario questions on sampling, question wording and reading results.', 'Every question is a small research decision rather than a definition to recite, so it tests judgement, not memory. A spot-the-open-question round takes a point for each wrong pick, and the total lands on one of three results with a pointer on what to study next.', '["marketing","marketing research quiz","market research test","survey design quiz","marketing students","research methods"]', 'FileSearch', 'scale', 4, 12, '{"schemaVersion":9,"title":"Marketing research quiz","description":"Ten scored scenario questions on sampling, question wording and reading results.","blocks":[{"id":"blk_marketin00","ref":"welcome","title":"Let''s see how you''d run a real research project. Ten scenarios on sampling, questions and results. Take your time with each one.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_marketin01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_marketin02","ref":"secondary","title":"You read a government census report to size your market. What kind of data is that?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_primary_data","label":"Primary data","image_key":null},{"id":"opt_secondary_data","label":"Secondary data","image_key":null,"score":1},{"id":"opt_qualitative_data","label":"Qualitative data","image_key":null},{"id":"opt_panel_data","label":"Panel data","image_key":null}],"allowOther":false},{"id":"blk_marketin03","ref":"why_churn","title":"You don''t yet know why customers are leaving. What''s the best first step?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_large_multiple","label":"A large multiple-choice survey","image_key":null},{"id":"opt_in_depth_interviews","label":"In-depth interviews with people who left","image_key":null,"score":1},{"id":"opt_an_a_b","label":"An A/B test on the pricing page","image_key":null},{"id":"opt_counting_website_visits","label":"Counting website visits","image_key":null}],"allowOther":false},{"id":"blk_marketin04","ref":"bad_question","title":"What''s wrong with asking ''How happy are you with our fast and friendly service?''","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_nothing_it_s","label":"Nothing, it''s clear","image_key":null},{"id":"opt_it_s_too","label":"It''s too short","image_key":null},{"id":"opt_it_asks_about","label":"It asks about two things and suggests the answer","image_key":null,"score":1},{"id":"opt_it_should_be","label":"It should be a yes/no question","image_key":null}],"allowOther":false},{"id":"blk_marketin05","ref":"random_sample","title":"Every customer on your list has an equal chance of being picked. What is that called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_convenience_sample","label":"A convenience sample","image_key":null},{"id":"opt_a_quota_sample","label":"A quota sample","image_key":null},{"id":"opt_a_simple_random","label":"A simple random sample","image_key":null,"score":1},{"id":"opt_a_snowball_sample","label":"A snowball sample","image_key":null}],"allowOther":false},{"id":"blk_marketin06","ref":"selection_bias","title":"You survey only people who visited your shop last Saturday about your brand as a whole. What''s the main risk?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_sample_may","label":"The sample may not represent all your customers","image_key":null,"score":1},{"id":"opt_the_questions_will","label":"The questions will be too long","image_key":null},{"id":"opt_the_data_will","label":"The data will be secondary","image_key":null},{"id":"opt_there_is_no","label":"There is no risk if the sample is large","image_key":null}],"allowOther":false},{"id":"blk_marketin07","ref":"open_questions","title":"Which of these are open-ended questions? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_what_made_you","label":"What made you choose us over other options?","image_key":null,"score":1},{"id":"opt_did_you_buy","label":"Did you buy from us in the last month?","image_key":null,"score":-1},{"id":"opt_what_would_you","label":"What would you change about the checkout?","image_key":null,"score":1},{"id":"opt_rate_us_from","label":"Rate us from 1 to 5","image_key":null,"score":-1},{"id":"opt_tell_us_about","label":"Tell us about the last time you used the app","image_key":null,"score":1}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_marketin08","ref":"ab_test","title":"Half your visitors see a green button and half see a blue one. What can this test show?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_why_people_prefer","label":"Why people prefer one colour","image_key":null},{"id":"opt_whether_the_colour","label":"Whether the colour change causes a difference in clicks","image_key":null,"score":1},{"id":"opt_which_colour_your","label":"Which colour your whole market likes","image_key":null},{"id":"opt_nothing_without_a","label":"Nothing without a focus group","image_key":null}],"allowOther":false},{"id":"blk_marketin09","ref":"correlation","title":"Customers who read your newsletter spend more. What can you safely conclude?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_newsletter_makes","label":"The newsletter makes people spend more","image_key":null},{"id":"opt_reading_and_spending","label":"Reading and spending are linked, but the cause is unclear","image_key":null,"score":1},{"id":"opt_high_spenders_never","label":"High spenders never unsubscribe","image_key":null},{"id":"opt_you_should_stop","label":"You should stop other marketing","image_key":null}],"allowOther":false},{"id":"blk_marketin10","ref":"focus_group","title":"What''s a common weakness of focus groups?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_one_loud_voice","label":"One loud voice can sway the rest","image_key":null,"score":1},{"id":"opt_they_only_produce","label":"They only produce numbers","image_key":null},{"id":"opt_they_always_need","label":"They always need thousands of people","image_key":null},{"id":"opt_they_can_t","label":"They can''t be recorded","image_key":null}],"allowOther":false},{"id":"blk_marketin11","ref":"nps","title":"A Net Promoter Score question asks customers about what?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_how_much_they","label":"How much they paid","image_key":null},{"id":"opt_how_likely_they","label":"How likely they are to recommend you","image_key":null,"score":1},{"id":"opt_how_often_they","label":"How often they buy","image_key":null},{"id":"opt_how_they_found","label":"How they found you","image_key":null}],"allowOther":false},{"id":"blk_marketin12","ref":"hardest","title":"No points here: which topic felt hardest?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_types_of_data","label":"Types of data","image_key":null},{"id":"opt_sampling","label":"Sampling","image_key":null},{"id":"opt_writing_good_que