VALUES ('tpl_productrecommendationqui', 'product-recommendation-quiz', 'Product recommendation quiz', 'Quiz', 'Pets, light and space in, one houseplant that will survive the spot out.', 'Built around a plant shop so you can see the pattern working, then swap in your own range. A must-have filter comes first in the logic: anyone with pets goes straight to a pet-safe pick. Everyone else is matched on the light their spot gets, and an unsure shopper gets the hardest plant to kill rather than a guess.', '["marketing","product recommendation quiz","product finder quiz","houseplant quiz","plant shop quiz","shopping quiz"]', 'ShoppingBag', 'scale', 3, 8, '{"schemaVersion":9,"title":"Houseplant finder quiz","description":"Pets, light and space in, one houseplant that will survive the spot out.","blocks":[{"id":"blk_productr00","ref":"welcome","title":"Looking for a plant that will actually last? Tell me a little about your home and I''ll pick one for the spot you have in mind.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_productr01","ref":"name","title":"First, what should I call you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_productr02","ref":"gift","title":"Is this plant a gift for someone else?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_productr03","ref":"experience","title":"How have houseplants gone for you so far?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"I''ve lost a few","labelHigh":"Everything thrives"},{"id":"blk_productr04","ref":"size","title":"Where will it live?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_shelf_or","label":"A shelf or desk, so something small","image_key":null},{"id":"opt_a_tabletop_or","label":"A tabletop or windowsill","image_key":null},{"id":"opt_on_the_floor","label":"On the floor, as a statement plant","image_key":null}],"allowOther":false},{"id":"blk_productr05","ref":"watering","title":"Be honest: how often will it get watered?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_few_days","label":"Every few days, I like looking after plants","image_key":null},{"id":"opt_about_once_a","label":"About once a week","image_key":null},{"id":"opt_whenever_i_remember","label":"Whenever I remember","image_key":null},{"id":"opt_i_travel_a","label":"I travel a lot","image_key":null}],"allowOther":false},{"id":"blk_productr06","ref":"email","title":"Want a care card for your match? Leave your email and we''ll send it over.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_productr07","ref":"pets","title":"Are there cats or dogs at home that might chew on leaves?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_productr08","ref":"light","title":"Last one. How much light does that spot get?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_direct_sun_for","label":"Direct sun for part of the day","image_key":null},{"id":"opt_bright_but_out","label":"Bright, but out of direct sun","image_key":null},{"id":"opt_not_much_it","label":"Not much, it''s away from the window","image_key":null},{"id":"opt_i_m_not","label":"I''m not sure","image_key":null}],"allowOther":false}],"endings":[{"id":"end_productr01","ref":"end_thanks","title":"Your match: Snake Plant","bodyMd":"Not sure about the light is fine. A snake plant copes with almost any spot, from a bright window to a dim hallway, and only needs water every couple of weeks.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_productr02","ref":"end_pet_safe","title":"Your match: Parlour Palm 🌿","bodyMd":"It is widely listed as safe for cats and dogs, so a curious nibble is no emergency. It copes with low to medium light and likes to dry out a little between drinks; just keep it out of hot afternoon sun.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_productr03","ref":"end_sun","title":"Your match: Jade Plant","bodyMd":"A succulent that loves a sunny sill and stores water in its thick leaves, so a missed week does it no harm. Water only when the soil is dry all the way down.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_productr04","ref":"end_bright","title":"Your match: Monstera","bodyMd":"Bright, indirect light is exactly what it wants, and it rewards you with big split leaves. Water about once a week when the top few centimetres are dry, and give it room to spread.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_productr05","ref":"end_low","title":"Your match: ZZ Plant","bodyMd":"Its glossy leaves keep going in dim corners where most plants give up, and it stores water in its roots, so it forgives long gaps between watering.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_productr01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"pets"},"op":"eq","value":true}],"groups":[]},"from":"pets","target":"end_pet_safe","targetKind":"ending","branch":"true"},{"id":"rl_productr02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"light"},"op":"eq","value":"opt_direct_sun_for"}],"groups":[]},"from":"light","target":"end_sun","targetKind":"ending","branch":"true"},{"id":"rl_productr03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"light"},"op":"eq","value":"opt_bright_but_out"}],"groups":[]},"from":"light","target":"end_bright","targetKind":"ending","branch":"true"},{"id":"rl_productr04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"light"},"op":"eq","value":"opt_not_much_it"}],"groups":[]},"from":"light","target":"end_low","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
