VALUES ('tpl_leadgenerationquiz', 'lead-generation-quiz', 'Lead generation quiz', 'Quiz', 'Nine quick questions that end in a tailored growth recommendation.', 'Visitors answer questions about their business, marketing channels and lead flow, then pick the one problem they would fix first. That answer routes them to one of four specific results, so the lead gets real advice and you get a qualified contact with context attached.', '["marketing","lead generation quiz","lead magnet quiz","marketing assessment","growth quiz","agency quiz"]', 'Target', 'scale', 3, 9, '{"schemaVersion":9,"title":"Growth check quiz","description":"Nine quick questions that end in a tailored growth recommendation.","blocks":[{"id":"blk_leadgene00","ref":"welcome","title":"Where is your growth getting stuck? Answer nine quick questions and you''ll get a recommendation for what to fix first.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_leadgene01","ref":"business_type","title":"What kind of business do you run?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_service_business_or","label":"Service business or consultancy","image_key":null},{"id":"opt_online_store","label":"Online store","image_key":null},{"id":"opt_software_or_app","label":"Software or app","image_key":null},{"id":"opt_local_shop_studio","label":"Local shop, studio or clinic","image_key":null},{"id":"opt_nonprofit","label":"Nonprofit","image_key":null}],"allowOther":true},{"id":"blk_leadgene02","ref":"team_size","title":"How many people work on the business, including you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_just_me","label":"Just me","image_key":null},{"id":"opt_2_5","label":"2–5","image_key":null},{"id":"opt_6_20","label":"6–20","image_key":null},{"id":"opt_21_100","label":"21–100","image_key":null},{"id":"opt_more_than_100","label":"More than 100","image_key":null}]},{"id":"blk_leadgene03","ref":"channels","title":"Which channels bring you customers today? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_word_of_mouth","label":"Word of mouth and referrals","image_key":null},{"id":"opt_search_engines","label":"Search engines","image_key":null},{"id":"opt_social_media","label":"Social media","image_key":null},{"id":"opt_paid_ads","label":"Paid ads","image_key":null},{"id":"opt_email_newsletter","label":"Email newsletter","image_key":null},{"id":"opt_events_or_networking","label":"Events or networking","image_key":null},{"id":"opt_partners_or_marketplaces","label":"Partners or marketplaces","image_key":null},{"id":"opt_honestly_i_m","label":"Honestly, I''m not sure","image_key":null}],"minSelections":1,"maxSelections":8,"allowOther":false},{"id":"blk_leadgene04","ref":"lead_flow","title":"How steady is the flow of new enquiries from month to month?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Feast or famine","labelHigh":"Like clockwork"},{"id":"blk_leadgene05","ref":"tracking","title":"Could you say which channel brought in each of your last ten customers?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_leadgene06","ref":"timeline","title":"When do you want to see a change?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_this_month","label":"This month","image_key":null},{"id":"opt_in_the_next","label":"In the next three months","image_key":null},{"id":"opt_this_year","label":"This year","image_key":null},{"id":"opt_just_exploring_for","label":"Just exploring for now","image_key":null}],"allowOther":false},{"id":"blk_leadgene07","ref":"contact","title":"Where should we send a copy of your result?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","email"]},{"id":"blk_leadgene08","ref":"wants_call","title":"Would a short call to talk through your result be useful?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_leadgene09","ref":"priority","title":"Last one, and it decides your result. Which of these would you fix first?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_not_enough_people","label":"Not enough people find us","description":"Visibility","image_key":null},{"id":"opt_people_visit_but","label":"People visit but don''t get in touch","description":"Conversion","image_key":null},{"id":"opt_enquiries_come_in","label":"Enquiries come in but don''t turn into customers","description":"Follow-up","image_key":null},{"id":"opt_customers_buy_once","label":"Customers buy once and don''t come back","description":"Retention","image_key":null}],"allowOther":false}],"endings":[{"id":"end_leadgene01","ref":"end_thanks","title":"Your next step: bring customers back 🔁","bodyMd":"A repeat sale is usually easier to win than a new customer. Start with a check-in message a few weeks after purchase and a reason to return, like early access or a reorder reminder.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_leadgene02","ref":"end_visibility","title":"Your next step: get found 🔎","bodyMd":"Pick the one channel where your best customers already spend time and show up there every week for a quarter. Steady effort on one channel beats a thin presence on five.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_leadgene03","ref":"end_conversion","title":"Your next step: make it easy to say yes","bodyMd":"People are already arriving, so the gap is on the page. Put one clear offer and one way to get in touch near the top, and add proof from real customers right beside it.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_leadgene04","ref":"end_followup","title":"Your next step: tighten the follow-up","bodyMd":"Interest is there, but it cools off. Reply to every enquiry within a working day, and write a simple three-message follow-up so nobody falls through the cracks.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_leadgene01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"priority"},"op":"eq","value":"opt_not_enough_people"}],"groups":[]},"from":"priority","target":"end_visibility","targetKind":"ending","branch":"true"},{"id":"rl_leadgene02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"priority"},"op":"eq","value":"opt_people_visit_but"}],"groups":[]},"from":"priority","target":"end_conversion","targetKind":"ending","branch":"true"},{"id":"rl_leadgene03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"priority"},"op":"eq","value":"opt_enquiries_come_in"}],"groups":[]},"from":"priority","target":"end_followup","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffdce8","surface":"#ffffff","text":"#3d1424","accent":"#be185d","accentText":"#fff7fa","botBubble":"#ffffff","userBubble":"#be185d","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"scallops","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
