INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_digitalmarketingquiz', 'digital-marketing-quiz', 'Digital marketing quiz', 'Quiz', 'Eight scored questions on the basics every online marketer should know.', 'Covers the terms people use every day but often mix up, from click-through rate to first-party data, plus one small calculation. Each right answer earns a point, a wrong pick in the data round costs one, and the total lands on one of three results.', '["marketing","digital marketing quiz","marketing trivia","SEO quiz","marketing training","scored quiz"]', 'Laptop', 'scale', 3, 10, '{"schemaVersion":9,"title":"Digital marketing quiz","description":"Eight scored questions on the basics every online marketer should know.","blocks":[{"id":"blk_digitalm00","ref":"welcome","title":"Think you know your CTR from your UTM? Eight questions, and a result at the end.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_digitalm01","ref":"player","title":"What name should go on your result?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_digitalm02","ref":"seo","title":"What does SEO stand for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_search_engine_optimisation","label":"Search engine optimisation","image_key":null,"score":1},{"id":"opt_social_engagement_output","label":"Social engagement output","image_key":null},{"id":"opt_sales_efficiency_overview","label":"Sales efficiency overview","image_key":null},{"id":"opt_site_entry_order","label":"Site entry order","image_key":null}],"allowOther":false},{"id":"blk_digitalm03","ref":"ctr","title":"Click-through rate is clicks divided by what?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_conversions","label":"Conversions","image_key":null},{"id":"opt_impressions","label":"Impressions","image_key":null,"score":1},{"id":"opt_followers","label":"Followers","image_key":null},{"id":"opt_total_ad_spend","label":"Total ad spend","image_key":null}],"allowOther":false},{"id":"blk_digitalm04","ref":"owned_media","title":"Which of these is owned media?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_sponsored_post","label":"A sponsored post","image_key":null},{"id":"opt_a_news_article","label":"A news article about your company","image_key":null},{"id":"opt_your_company_blog","label":"Your company blog","image_key":null,"score":1},{"id":"opt_a_customer_sharing","label":"A customer sharing your product","image_key":null}],"allowOther":false},{"id":"blk_digitalm05","ref":"conversion_rate","title":"A landing page gets 1,000 visitors and 30 of them sign up. What is its conversion rate?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_0_3","label":"0.3%","image_key":null},{"id":"opt_3_2","label":"3%","image_key":null,"score":1},{"id":"opt_30","label":"30%","image_key":null},{"id":"opt_33","label":"33%","image_key":null}],"allowOther":false},{"id":"blk_digitalm06","ref":"first_party","title":"Which of these count as first-party data? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_newsletter_sign_ups","label":"Newsletter sign-ups on your own site","image_key":null,"score":1},{"id":"opt_purchase_history_from","label":"Purchase history from your own shop","image_key":null,"score":1},{"id":"opt_a_contact_list","label":"A contact list bought from a data broker","image_key":null,"score":-1},{"id":"opt_interest_segments_from","label":"Interest segments from a third-party data provider","image_key":null,"score":-1}],"minSelections":1,"maxSe