VALUES ('tpl_billionairequiz', 'billionaire-quiz', 'Billionaire quiz', 'Quiz', 'Eight scored trivia questions about famous founders and their companies.', 'A light trivia game about who built which company, from Walmart to Spanx, with a pick-all-that-apply round on co-founders where a wrong pick costs a point. The total lands on one of three results, and a just-for-fun last question gives people something to talk about.', '["marketing","billionaire quiz","business trivia","founders quiz","team building quiz","fun quiz"]', 'Gem', 'scale', 3, 10, '{"schemaVersion":9,"title":"Billionaire founders quiz","description":"Eight scored trivia questions about famous founders and their companies.","blocks":[{"id":"blk_billiona00","ref":"welcome","title":"How well do you know the founders behind some famous fortunes? Eight questions, then your result.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_billiona01","ref":"player","title":"What name should go on the scoreboard?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_billiona02","ref":"amazon","title":"Who founded Amazon?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_jeff_bezos","label":"Jeff Bezos","image_key":null,"score":1},{"id":"opt_elon_musk","label":"Elon Musk","image_key":null},{"id":"opt_larry_ellison","label":"Larry Ellison","image_key":null},{"id":"opt_michael_dell","label":"Michael Dell","image_key":null}],"allowOther":false},{"id":"blk_billiona03","ref":"berkshire","title":"Which investor is famous for running Berkshire Hathaway?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_george_soros","label":"George Soros","image_key":null},{"id":"opt_warren_buffett","l