"left":{"kind":"ref","ref":"ikea"},"op":"eq","value":"opt_sweden"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_billiona06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"ortega"},"op":"eq","value":"opt_inditex"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_billiona07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"google"},"op":"eq","value":"opt_larry_page_and"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_billiona08","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cofounded"},"op":"includes","value":"opt_airbnb"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_billiona09","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cofounded"},"op":"includes","value":"opt_dell"}],"groups":[]},"variable":"score","amount":-1},{"id":"rl_billiona10","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cofounded"},"op":"includes","value":"opt_nike"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_billiona11","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cofounded"},"op":"includes","value":"opt_ben_jerry_s"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_billiona12","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cofounded"},"op":"includes","value":"opt_spanx"}],"groups":[]},"variable":"score","amount":-1},{"id":"rl_billiona13","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"walmart"},"op":"eq","value":"opt_sam_walton"}],"groups":[]},"variable":"score","amount":1}],"layout":{},"variables":[{"name":"score","type":"number","initial":0}],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer 