VALUES ('tpl_brandingquiz', 'branding-quiz', 'Branding quiz', 'Quiz', 'Eight scored questions on what a brand is and how it stays consistent.', 'Moves past logos to the ideas that hold a brand together: its promise, voice, positioning and the guidelines that keep it consistent. A pick-all-that-apply visual identity round takes a point for each wrong pick, and the total chooses one of three results.', '["marketing","branding quiz","brand identity quiz","marketing workshop","brand training","scored quiz"]', 'Palette', 'scale', 3, 10, '{"schemaVersion":9,"title":"Branding quiz","description":"Eight scored questions on what a brand is and how it stays consistent.","blocks":[{"id":"blk_branding00","ref":"welcome","title":"A brand is more than a logo. Eight questions to see how well you know the rest.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_branding01","ref":"player","title":"What name should go on your result?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_branding02","ref":"promise","title":"What is a brand promise?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_legal_terms","label":"The legal terms on the website","image_key":null},{"id":"opt_the_experience_customers","label":"The experience customers can count on every time they deal with you","image_key":null,"score":1},{"id":"opt_the_discount_offered","label":"The discount offered to new customers","image_key":null},{"id":"opt_the_company_s","label":"The company''s sales target","image_key":null}],"allowOther":false},{"id":"blk_branding03","ref":"voice","title":"What does brand voice describe?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_music_in","label":"The music in your ads","image_key":null},{"id":"opt_the_consistent_personality","label":"The consistent personality in how the brand writes and speaks","image_key":null,"score":1},{"id":"opt_who_presents_your","label":"Who presents your videos","image_key":null},{"id":"opt_how_many_channels","label":"How many channels you post on","image_key":null}],"allowOther":false},{"id":"blk_branding04","ref":"visual_identity","title":"Which of these are part of a visual identity? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_logo","label":"Logo","image_key":null,"score":1},{"id":"opt_colour_palette","label":"Colour palette","image_key":null,"score":1},{"id":"opt_typefaces","label":"Typefaces","image_key":null,"score":1},{"id":"opt_refund_policy","label":"Refund policy","image_key":null,"score":-1},{"id":"opt_office_address","label":"Office address","image_key":null,"score":-1}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_branding05","ref":"nike","title":"Which brand uses the tagline \"Just Do It\"?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_adidas","label":"Adidas","image_key":null},{"id":"opt_puma","label":"Puma","image_key":null},{"id":"opt_nike","label":"Nike","image_key":null,"score":1},{"id":"opt_reebok","label":"Reebok","image_key":null}],"allowOther":false},{"id":"blk_branding06","ref":"positioning","title":"What does a positioning statement set out?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_where_your_products","label":"Where your products sit on a shop shelf","image_key":null},{"id":"opt_who_the_brand","label":"Who the brand is for and why it is the better choice for them than the alternatives","image_key":null,"score":1},{"id":"opt_the_order_of","label":"The order of pages on your website","image_key":null},{"id":"opt_your_team_s","label":"Your team''s job titles","image_key":null}],"allowOther":false},{"id":"blk_branding07","ref":"guidelines","title":"What are brand guidelines mainly for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_proving_the_logo","label":"Proving the logo is trademarked","image_key":null},{"id":"opt_helping_anyone_who","label":"Helping anyone who creates for the brand keep it consistent","image_key":null,"score":1},{"id":"opt_listing_the_company","label":"Listing the company''s competitors","image_key":null},{"id":"opt_setting_prices","label":"Setting prices","image_key":null}],"allowOther":false},{"id":"blk_branding08","ref":"consistency","title":"Why do brands keep their look and tone the same across every channel?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_it_is_cheaper","label":"It is cheaper to print","image_key":null},{"id":"opt_repetition_helps_people","label":"Repetition helps people recognise and remember them","image_key":null,"score":1},{"id":"opt_search_engines_require","label":"Search engines require it","image_key":null},{"id":"opt_it_stops_competitors","label":"It stops competitors copying them","image_key":null}],"allowOther":false},{"id":"blk_branding09","ref":"refresh","title":"What usually separates a brand refresh from a full rebrand?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_refresh_updates","label":"A refresh updates the look but keeps the core identity","image_key":null,"score":1},{"id":"opt_a_refresh_always","label":"A refresh always changes the company name","image_key":null},{"id":"opt_there_is_no","label":"There is no difference","image_key":null},{"id":"opt_a_rebrand_only","label":"A rebrand only changes the colours","image_key":null}],"allowOther":false},{"id":"blk_branding10","ref":"brand_admire","title":"Which brand do you think gets it right, and why?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false}],"endings":[{"id":"end_branding01","ref":"end_thanks","title":"Brand explorer","bodyMd":"Start with three ideas: the promise you make, the voice you use and the look you keep consistent. The rest of branding builds on them.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_branding02","ref":"end_strategist","title":"Brand strategist 🎨","bodyMd":"You see a brand as a promise and a voice, not just a logo. You could run the next brand workshop.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_branding03","ref":"end_builder","title":"Brand builder","bodyMd":"You have the essentials. Positioning and the difference between a refresh and a rebrand are worth another look.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_branding01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":9}],"groups":[]},"target":"end_strategist","targetKind":"ending"},{"id":"rs_branding02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":6}],"groups":[]},"target":"end_builder","targetKind":"ending"}],"logic":[{"id":"rl_branding01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_branding02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"promise"},"op":"eq","value":"opt_the_experience_customers"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_branding03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"ki