VALUES ('tpl_consumerbehaviorquiz', 'consumer-behavior-quiz', 'Consumer behavior quiz', 'Quiz', 'Eight scored questions on why people buy what they buy.', 'Built around everyday buying situations rather than textbook definitions: a cinema popcorn menu, a sale countdown, a survey that sales never matched. A scarcity round takes a point for each wrong pick, and the total chooses one of three results.', '["marketing","consumer behavior quiz","buyer psychology","marketing psychology quiz","behavioral economics","scored quiz"]', 'ShoppingCart', 'scale', 3, 10, '{"schemaVersion":9,"title":"Consumer behaviour quiz","description":"Eight scored questions on why people buy what they buy.","blocks":[{"id":"blk_consumer00","ref":"welcome","title":"Why do people buy what they buy? Eight questions on the psychology behind every basket.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_consumer01","ref":"player","title":"What name should go on your result?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_consumer02","ref":"say_do","title":"Most people in a survey say they would pay more for eco-friendly packaging, but sales barely change. What is this called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_brand_loyalty","label":"Brand loyalty","image_key":null},{"id":"opt_the_say_do","label":"The say-do gap, or intention-behaviour gap","image_key":null,"score":1},{"id":"opt_price_elasticity","label":"Price elasticity","image_key":null},{"id":"opt_market_saturation","label":"Market saturation","image_key":null}],"allowOther":false},{"id":"blk_consumer03","ref":"social_proof","title":"A product page shows hundreds of five-star reviews. Which influence is it using?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_scarcity","label":"Scarcity","image_key":null},{"id":"opt_anchoring","label":"Anchoring","image_key":null},{"id":"opt_social_proof","label":"Social proof","image_key":null,"score":1},{"id":"opt_reciprocity","label":"Reciprocity","image_key":null}],"allowOther":false},{"id":"blk_consumer04","ref":"anchoring","title":"A shop shows the original price crossed out beside the sale price. Which effect makes the sale price feel like a bargain?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_anchoring","label":"Anchoring","image_key":null,"score":1},{"id":"opt_the_halo_effect","label":"The halo effect","image_key":null},{"id":"opt_the_bandwagon_effect","label":"The bandwagon effect","image_key":null},{"id":"opt_habit","label":"Habit","image_key":null}],"allowOther":false},{"id":"blk_consumer05","ref":"loss_aversion","title":"What does loss aversion describe?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_people_avoid_shops","label":"People avoid shops that lose money","image_key":null},{"id":"opt_a_loss_feels","label":"A loss feels bigger than a gain of the same size","image_key":null,"score":1},{"id":"opt_people_forget_purchases","label":"People forget purchases they regret","image_key":null},{"id":"opt_customers_leave_after","label":"Customers leave after one bad experience","image_key":null}],"allowOther":false},{"id":"blk_consumer06","ref":"decoy","title":"A cinema sells small popcorn for 3, medium for 6.50 and large for 7. Which one is there mainly to make another look like a better deal?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_small","label":"Small","image_key":null},{"id":"opt_medium","label":"Medium","image_key":null,"score":1},{"id":"opt_large","label":"Large","image_key":null},{"id":"opt_none_of_them","label":"None of them","image_key":null}],"allowOther":false},{"id":"blk_consumer07","ref":"first_stage","title":"In the classic buying decision process, what comes first?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_comparing_brands","label":"Comparing brands","image_key":null},{"id":"opt_searching_for_information","label":"Searching for information","image_key":null},{"id":"opt_recognising_a_need","label":"Recognising a need or problem","image_key":null,"score":1},{"id":"opt_making_the_purchase","label":"Making the purchase","image_key":null}],"allowOther":false},{"id":"blk_consumer08","ref":"dissonance","title":"Someone buys an expensive laptop and starts doubting the choice a day later. What is this called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_post_purchase_dissonance","label":"Post-purchase dissonance","image_key":null,"score":1},{"id":"opt_impulse_buying","label":"Impulse buying","image_key":null},{"id":"opt_brand_switching","label":"Brand switching","image_key":null},{"id":"opt_choice_overload","label":"Choice overload","image_key":null}],"allowOther":false},{"id":"blk_consumer09","ref":"scarcity","title":"Which of these messages use scarcity or urgency? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_only_3_left","label":"Only 3 left in stock","image_key":null,"score":1},{"id":"opt_sale_ends_at","label":"Sale ends at midnight","image_key":null,"score":1},{"id":"opt_rated_4_8","label":"Rated 4.8 by our customers","image_key":null,"score":-1},{"id":"opt_free_returns_within","label":"Free returns within 30 days","image_key":null,"score":-1}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_consumer10","ref":"own_habit","title":"Be honest: how often does a countdown timer or \"almost gone\" message make you buy sooner?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Never","labelHigh":"Every time"}],"endings":[{"id":"end_consumer01","ref":"end_thanks","title":"Curious shopper","bodyMd":"Next time you shop, look for the crossed-out price, the review count and the countdown. Once you notice them, you''ll see them everywhere.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_consumer02","ref":"end_expert","title":"Mind reader 🧠","bodyMd":"You can spot the psychology behind a price tag and a product page. The decoy question catches most people, and it didn''t catch you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_consumer03","ref":"end_observer","title":"Sharp observer","bodyMd":"You know the main influences on buyers. Anchoring and the decoy effect look alike at first glance and are worth a closer look.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_consumer01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":8}],"groups":[]},"target":"end_expert","targetKind":"ending"},{"id":"rs_consumer02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":5}],"groups":[]},"target":"end_observer","targetKind":"ending"}],"logic":[{"id":"rl_consumer01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_consumer02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"say_do"},"op":"eq","value":"opt_the_say_do"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_consumer03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"social_proof"},"op":"eq","value":"opt_social_proof"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_consumer04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"anchoring"},"op":"eq","value":"opt_anchoring"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_consumer05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"loss_aversion"},"op":"eq","value":"opt_a_loss_feels"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_consumer06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"decoy"},"op":"eq","value":"opt_medium"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_consumer07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"first_stage"},"op":"eq","value":"opt_recognising_a_need"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_consumer08","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"dissonance"},"op":"eq","value":"opt_post_purchase_dissonance"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_consumer09","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"scarcity"},"op":"includes","value":"opt_only_3_left"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_consumer10","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"scarcity"},"op":"includes","value":"opt_sale_ends_at"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_consumer11","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"scarcity"},"op":"includes","value":"opt_rated_4_8"}],"groups":[]},"variable":"score","amount":-1},{"id":"rl_consumer12","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"scarcity"},"op":"includes","value":"opt_free_returns_within"}],"groups":[]},"variable":"score","amount":-1}],"layout":{},"variables":[{"name":"score","type":"number","initial":0}],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ece3ff","surface":"#ffffff","text":"#2a1f3d","accent":"#6d3fc7","accentText":"#fbf8ff","botBubble":"#ffffff","userBubble":"#6d3fc7","userBubbleText":