INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_culturalfitquiz', 'cultural-fit-quiz', 'Cultural fit quiz', 'Quiz', 'Six team situations that point to the culture someone works best in, plus room to explain.', 'Instead of asking people to rate themselves, it asks what they would do when a new tool is on the table, a deadline moves or a mistake ships, and how they like decisions and updates to happen. Each answer adds to a score from process-led to fast-moving, which picks one of three team cultures, and a ranking and an open question capture what a score can''t.', '["marketing","cultural fit quiz","culture fit assessment","team culture quiz","work preferences","team onboarding"]', 'Users', 'scale', 3, 10, '{"schemaVersion":9,"title":"Team culture fit quiz","description":"Six team situations that point to the culture someone works best in, plus room to explain.","blocks":[{"id":"blk_cultural00","ref":"welcome","title":"What kind of team do you do your best work in? Six everyday situations, no right or wrong answers, and a team culture match at the end.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_cultural01","ref":"name","title":"What''s your first name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_cultural02","ref":"new_tool","title":"Your team is thinking about switching to a new tool. How should that happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_quick_demo","label":"A quick demo, then the team decides together","image_key":null,"score":1},{"id":"opt_agree_what_it","label":"Agree what it needs to do, then compare the options","image_key":null},{"id":"opt_try_it_on","label":"Try it on one live project and see","image_key":null,"score":2}],"allowOther":false},{"id":"blk_cultural03","ref":"decisions","title":"How do you like team decisions to be made?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_try_one_option","label":"Try one option and change course if it doesn''t work","image_key":null,"score":2},{"id":"opt_after_the_options","label":"After the options are written up and compared","image_key":null},{"id":"opt_in_a_quick","label":"In a quick discussion, then someone decides","image_key":null,"score":1}],"allowOther":false},{"id":"blk_cultural04","ref":"updates","title":"How would you rather keep the team up to date?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_written_update","label":"A written update everyone can read in their own time","image_key":null},{"id":"opt_as_things_happen","label":"As things happen, in the team chat","image_key":null,"score":2},{"id":"opt_a_short_regular","label":"A short regular check-in","image_key":null,"score":1}],"allowOther":false},{"id":"blk_cultural05","ref":"deadline","title":"A deadline moves forward by a week. What''s your instinct?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_talk_it_through","label":"Talk it through with the team and find a middle ground","image_key":null,"score":1},{"id":"opt_pick_up_the","label":"Pick up the pace and figure out the rest on the way","image_key":null,"score":2},{"id":"opt_re_plan_properly","label":"Re-plan properly and agree what to cut","image_key":null}],"allowOther":false},{"id":"blk_cultural06","ref":"mistake","title":"Something the team shipped has a mistake in it. What should happen next?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_fix_it_fast","label":"Fix it fast and move on","image_key":null,"score":2},{"id":"opt_fix_it_then","label":"Fix it, then write down what went wrong so it doesn''t happen again","image_key":null},{"id":"opt_fix_it_and","label":"Fix it and talk it over at the next team meeting","image_key":null,"score":1}],"allowOther":false},{"id":"blk_cultural07","ref":"feedback","title":"How do you prefer to get feedback on your work?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_a_short_chat","label":"A short chat the same day","image_key":null,"score":1},{"id":"opt_written_notes_i","label":"Written notes I can think over","image_key":null},{"id":"opt_right_there_in","label":"Right there in the moment, while I''m working on it","image_key":null,"score":2}],"allowOther":false},{"id":"blk_cultural08","ref":"work_setting","title":"Where do you work best?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_in_the_office","label":"In the office with the team","image_key":null},{"id":"opt_a_mix_of","label":"A mix of office and home","image_key":null},{"id":"opt_fully_remote","label":"Fully remote","image_key":null},{"id":"opt_no_strong_preference","label":"No strong preference","image_key":null}]},{"id":"blk_cultural09","ref":"team_values","title":"Put these in order of how much they matter to you in a team.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_clear_goals","label":"Clear goals"},{"id":"opt_item_freedom_to","label":"Freedom to decide how I work"},{"id":"opt_item_honest_feedback","label":"Honest feedback"},{"id":"opt_item_time_for","label":"Time for focused work"},{"id":"opt_item_friendly_people","label":"Friendly people"}]},{"id":"blk_cultural10","ref":"context","title":"Is there anything about the teams you''ve enjoyed most that these questions missed?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1000,"aiQualityCheck":false}],"endings":[{"id":"end_cultural01","ref":"end_thanks","title":"Your match: a process-led team","bodyMd":"You do your best work with clear goals, written briefs and time to think. Look for teams that document decisions and plan ahead, where your eye for gaps stops problems early.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_cultural02","ref":"end_fast","title":"Your match: a fast-moving team 🚀","bodyMd":"You do well where decisions are quick, plans change often and people learn by shipping. You''ll add most in a team that also has someone capturing what gets learned along the way.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_cultural03","ref":"end_collaborative","title":"Your match: a collaborative, flexible team","bodyMd":"You like a plan but hold it loosely, and you prefer to talk things through. Teams with regular check-ins and shared decisions suit you, and you often bridge the planners and the experimenters.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_cultural01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":9}],"groups":[]},"target":"end_fast","targetKind":"ending"},{"id":"rs_cultural02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":4}],"groups":[]},"target":"end_collaborative","targetKind":"ending"}],"logic":[{"id":"rl_cultural01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_cultural02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"new_tool"},"op":"eq","value":"opt_a_quick_demo"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_cultural03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"new_tool"},"op":"eq","value":"opt_try_it_on"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_cultural04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"decisions"},"op":"eq","value":"opt_try_one_option"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_cultural05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"decisions"},"op":"eq","value":"opt_in_a_quick"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_cultural06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"updates"},"op":"eq","value":"opt_as_things_happen"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_cultural07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"updates"},"op":"eq","value":"opt_a_short_regular"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_cultural08","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"deadline"},"op":"eq","value":"opt_talk_it_through"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_cultural09","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"deadline"},"op":"eq","value":"opt_pick_up_the"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_cultural10","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"mistake"},"op":"eq","value":"opt_fix_it_fast"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_cultural11","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"mistake"},"op":"eq","value":"opt_fix_it_and"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_cultural12","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feedback"},"op":"eq","value":"opt_a_short_chat"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_cultural13","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feedback"},"op":"eq","value":"opt_right_there_in"}],"groups":[]},"variable":"score","amount":2}],"layout":{},"variables":[{"name":"score","type":"number","initial":0}],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#f