INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_entrepreneurquiz', 'entrepreneur-quiz', 'Entrepreneur quiz', 'Quiz', 'Questions about where an idea really stands, and a next step to match.', 'Asks about what people have actually done, like how many potential customers they''ve spoken to and how they would test demand, rather than whether they feel like a born founder. Each answer adds points, and the total picks one of three practical next steps.', '["marketing","entrepreneur quiz","startup quiz","business idea quiz","founder quiz","small business"]', 'Rocket', 'scale', 3, 10, '{"schemaVersion":9,"title":"Founder readiness quiz","description":"Questions about where an idea really stands, and a next step to match.","blocks":[{"id":"blk_entrepre00","ref":"welcome","title":"Got a business idea? A few questions about where it stands, and a practical next step at the end.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_entrepre01","ref":"idea","title":"Describe your idea in a sentence or two.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":500,"aiQualityCheck":false},{"id":"blk_entrepre02","ref":"stage","title":"Where is the idea right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_just_a_thought","label":"Just a thought","image_key":null},{"id":"opt_some_notes_and","label":"Some notes and research","image_key":null},{"id":"opt_a_prototype_or","label":"A prototype or first version","image_key":null},{"id":"opt_already_selling_a","label":"Already selling a little","image_key":null}]},{"id":"blk_entrepre03","ref":"conversations","title":"How many people who have the problem you solve have you talked to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_none_yet","label":"None yet","image_key":null},{"id":"opt_mostly_friends_and","label":"Mostly friends and family","image_key":null,"score":1},{"id":"opt_a_handful_who","label":"A handful who actually have the problem","image_key":null,"score":1},{"id":"opt_ten_or_more","label":"Ten or more who actually have the problem","image_key":null,"score":2}],"allowOther":false},{"id":"blk_entrepre04","ref":"problem","title":"Could you explain the problem you solve in one sentence, and have people nod?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_not_yet","label":"Not yet","image_key":null},{"id":"opt_roughly_but_it","label":"Roughly, but it changes each time","image_key":null,"score":1},{"id":"opt_yes_and_people","label":"Yes, and people recognise it straight away","image_key":null,"score":2}],"allowOther":false},{"id":"blk_entrepre05","ref":"test","title":"What''s the first thing you''d do to see if people want it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_offer_a_simple","label":"Offer a simple version or pre-order and see who commits","image_key":null,"score":2},{"id":"opt_build_the_full","label":"Build the full product, then launch","image_key":null},{"id":"opt_ask_around_and","label":"Ask around and see what people think","image_key":null,"score":1}],"allowOther":false},{"id":"blk_entrepre06","ref":"time","title":"How much time can you give it each week?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_an_hour_or","label":"An hour or two","image_key":null},{"id":"opt_a_few_evenings","label":"A few evenings","image_key":null,"score":1},{"id":"opt_a_full_day","label":"A full day or more","image_key":null,"score":2}],"allowOther":false},{"id":"blk_entrepre07","ref":"runway","title":"If it earned nothing for six months, could you keep going?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_no_i_d","label":"No, I''d need income from it quickly","image_key":null},{"id":"opt_just_about","label":"Just about","image_key":null,"score":1},{"id":"opt_yes_comfortably","label":"Yes, comfortably","image_key":null,"score":2}],"allowOther":false},{"id":"blk_entrepre08","ref":"setback","title":"Your first attempt gets a lukewarm response. What do you do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_ask_the_people","label":"Ask the people who said no why, and change one thing","image_key":null,"score":2},{"id":"opt_push_on_with","label":"Push on with the plan as it is","image_key":null},{"id":"opt_take_a_break","label":"Take a break and rethink the whole thing","image_key":null,"score":1}],"allowOther":false},{"id":"blk_entrepre09","ref":"support","title":"Who could you ask for help along the way? Pick all that apply.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_someone_who_has","label":"Someone who has started a business","image_key":null},{"id":"opt_a_co_founder","label":"A co-founder or partner","image_key":null},{"id":"opt_friends_and_family","label":"Friends and family","image_key":null},{"id":"opt_a_local_business","label":"A local business group or course","image_key":null},{"id":"opt_no_one_yet","label":"No one yet","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_entrepre10","ref":"email","title":"Want a copy of your next step? Leave your email.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_entrepre01","ref":"end_thanks","title":"Still exploring","bodyMd":"That''s a fine place to be. Write down who has this problem and what they do about it today, then find three of them to talk to. You''ll learn more in a week than from months of planning.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_entrepre02","ref":"end_ready","title":"Ready to run a small test 🚀","bodyMd":"You''ve done the groundwork. Your next step is a small, real test: a simple offer or pre-order in front of the people you''ve spoken to, so their actions tell you what their words can''t.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_entrepre03","ref":"end_talk","title":"Talk to customers first","bodyMd":"The idea has promise, but it needs more evidence. Before you build anything, have ten honest conversations with people who have the problem, and ask about the last time it happened.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_entrepre01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":9}],"groups":[]},"target":"end_ready","targetKind":"ending"},{"id":"rs_entrepre02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":5}],"groups":[]},"target":"end_talk","targetKind":"ending"}],"logic":[{"id":"rl_entrepre01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_entrepre02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"conversations"},"op":"eq","value":"opt_mostly_friends_and"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_entrepre03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"conversations"},"op":"eq","value":"opt_a_handful_who"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_entrepre04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"conversations"},"op":"eq","value":"opt_ten_or_more"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_entrepre05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"problem"},"op":"eq","value":"opt_roughly_but_it"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_entrepre06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"problem"},"op":"eq","value":"opt_yes_and_people"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_entrepre07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"test"},"op":"eq","value":"opt_offer_a_simple"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_entrepre08","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"test"},"op":"eq","value":"opt_ask_around_and"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_entrepre09","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"time"},"op":"eq","value":"opt_a_few_evenings"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_entrepre10","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"time"},"op":"eq","value":"opt_a_full_day"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_entrepre11","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"runway"},"op":"eq","value":"opt_just_about"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_entrepre12","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"runway"},"op":"eq","value":"opt_yes_comfortably"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_entrepre13","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"setback"},"op":"eq","value":"opt_ask_the_people"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_entrepre14","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"setback"},"op":"eq","value":"opt_take_a_break"}],"groups":[]},"variable":"score","amount":1}],"layout":{},"variables":[{"name":"score","type":"number","initial":0}],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f3e6ff","surface":"#ffffff","text":"#2b1638","accent":"#9333ea","accentText":"#fdf9ff","botBubble":"#ffffff","userBubble":"#9333ea","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"confetti","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
