VALUES ('tpl_triviaquiz', 'trivia-quiz', 'Trivia quiz', 'Quiz', 'Eight scored general knowledge questions, a tiebreaker and three results.', 'Science, art, history and language in one short round, so no single specialist runs away with it. Every right answer is worth a point, the botanical fruit question takes one away for a wrong pick, and a closest-guess tiebreaker settles a draw without a replay.', '["popular","trivia quiz","general knowledge quiz","quiz night","team building quiz","scored quiz"]', 'Lightbulb', 'choice', 3, 10, '{"schemaVersion":9,"title":"General knowledge trivia","description":"Eight scored general knowledge questions, a tiebreaker and three results.","blocks":[{"id":"blk_triviaqu00","ref":"welcome","title":"Trivia time. Eight questions from all over the map, one tiebreaker, and your result at the end.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_triviaqu01","ref":"player","title":"What name or team name should go on the scoreboard?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_triviaqu02","ref":"octopus","title":"How many hearts does an octopus have?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_one","label":"One","image_key":null},{"id":"opt_two","label":"Two","image_key":null},{"id":"opt_three","label":"Three","image_key":null,"score":1},{"id":"opt_eight","label":"Eight","image_key":null}],"allowOther":false},{"id":"blk_triviaqu03","ref":"hardest","title":"What is the hardest natural substance on Earth?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_quartz","label":"Quartz","image_key":null},{"id":"opt_diamond","label":"Diamond","image_key":null,"score":1},{"id":"opt_granite","label":"Granite","image_key":null},{"id":"opt_titanium","label":"Titanium","image_key":null}],"allowOther":false},{"id":"blk_triviaqu04","ref":"fruits","title":"Botanically speaking, which of these are fruits? Pick all that apply.","description":"A wrong pick costs a point, so only choose the ones you''re sure of.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_tomato","label":"Tomato","image_key":null,"score":1},{"id":"opt_carrot","label":"Carrot","image_key":null,"score":-1},{"id":"opt_cucumber","label":"Cucumber","image_key":null,"score":1},{"id":"opt_potato","label":"Potato","image_key":null,"score":-1}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_triviaqu05","ref":"sistine","title":"Who painted the ceiling of the Sistine Chapel?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_leonardo_da_vinci","label":"Leonardo da Vinci","image_key":null},{"id":"opt_raphael","label":"Raphael","image_key":null},{"id":"opt_michelangelo","label":"Michelangelo","image_key":null,"score":1},{"id":"opt_botticelli","label":"Botticelli","image_key":null}],"allowOther":false},{"id":"blk_triviaqu06","ref":"sodium","title":"What is the chemical symbol for sodium?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_so","label":"So","image_key":null},{"id":"opt_sd","label":"Sd","image_key":null},{"id":"opt_na","label":"Na","image_key":null,"score":1},{"id":"opt_s_4","label":"S","image_key":null}],"allowOther":false},{"id":"blk_triviaqu07","ref":"lightning","title":"True or false: lightning never strikes the same place twice.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_true","label":"True","image_key":null},{"id":"opt_false","label":"False","image_key":null,"score":1}],"allowOther":false},{"id":"blk_triviaqu08","ref":"berlin_wall","title":"In which year did the Berlin Wall fall?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_1985","label":"1985","image_key":null},{"id":"opt_1987","label":"1987","image_key":null},{"id":"opt_1989","label":"1989","image_key":null,"score":1},{"id":"opt_1991","label":"1991","image_key":null}]},{"id":"blk_triviaqu09","ref":"native_speakers","title":"Which language has the most native speakers in the world?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_english","label":"English","image_key":null},{"id":"opt_spanish","label":"Spanish","image_key":null},{"id":"opt_mandarin_chinese","label":"Mandarin Chinese","image_key":null,"score":1},{"id":"opt_hindi","label":"Hindi","image_key":null}],"allowOther":false},{"id":"blk_triviaqu10","ref":"tiebreaker","title":"Tiebreaker: how many keys are there on a standard piano?","description":"Not scored. If two players draw, the closest guess wins.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":500,"integerOnly":true}],"endings":[{"id":"end_triviaqu01","ref":"end_thanks","title":"Warm-up round 🎲","bodyMd":"Trivia rewards odd facts, and now you have eight new ones. Octopuses have three hearts, by the way. Have another go.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_triviaqu02","ref":"end_champion","title":"Quiz night champion 🏆","bodyMd":"Almost a clean sweep. The botanical fruits and the lightning myth are where most players slip, and you got through.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_triviaqu03","ref":"end_contender","title":"Strong contender 💡","bodyMd":"A good score with a couple of traps along the way. The octopus and the lightning question catch plenty of people out.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_triviaqu01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":8}],"groups":[]},"target":"end_champion","targetKind":"ending"},{"id":"rs_triviaqu02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":5}],"groups":[]},"target":"end_contender","targetKind":"ending"}],"logic":[{"id":"rl_triviaqu01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_triviaqu02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"octopus"},"op":"eq","value":"opt_three"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_triviaqu03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"hardest"},"op":"eq","value":"opt_diamond"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_triviaqu04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"fruits"},"op":"includes","value":"opt_tomato"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_triviaqu05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"fruits"},"op":"includes","value":"opt_carrot"}],"groups":[]},"variable":"score","amount":-1},{"id":"rl_triviaqu06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"fruits"},"op":"includes","value":"opt_cucumber"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_triviaqu07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"fruits"},"op":"includes","value":"opt_potato"}],"groups":[]},"variable":"score","amount":-1},{"id":"rl_triviaqu08","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"sistine"},"op":"eq","value":"opt_michelangelo"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_triviaqu09","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"sodium"},"op":"eq","value":"opt_na"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_triviaqu10","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"lightning"},"op":"eq","value":"opt_false"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_triviaqu11","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"berlin_wall"},"op":"eq","value":"opt_1989"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_triviaqu12","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"native_speakers"},"op":"eq","value":"opt_mandarin_chinese"}],"groups":[]},"variable":"score","amount":1}],"layout":{},"variables":[{"name":"score","type":"number","initial":0}],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffdce8","surface":"#ffffff","text":"#3d1424","accent":"#be185d","accentText":"#fff7fa","botBubble":"#ffffff","userBubble":"#be185d","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"scallops","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
