INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_quickstartpersonalityqui', 'quick-start-personality-quiz', 'Quick personality quiz', 'Quiz', 'Six everyday scenarios and three results: introvert, ambivert or extrovert.', 'A small, focused personality quiz built on one idea: where you get your energy. Each scenario offers a social, a middle and a quiet answer worth two, one or nothing, and the total lands on one of three results, so mixed answers get their own outcome instead of being forced to a side.', '["popular","personality quiz","introvert or extrovert quiz","ambivert quiz","fun quiz","short quiz"]', 'Sparkles', 'choice', 3, 7, '{"schemaVersion":9,"title":"Introvert or extrovert quiz","description":"Six everyday scenarios and three results: introvert, ambivert or extrovert.","blocks":[{"id":"blk_quicksta00","ref":"welcome","title":"Six quick scenarios, no right or wrong answers. Pick what you''d honestly do, and we''ll tell you where you get your energy.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_quicksta01","ref":"name","title":"First, what should we call you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_quicksta02","ref":"rainy_saturday","title":"It''s Saturday night and it''s pouring with rain. Your friends still want to go out. You...","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_grab_an_umbrella","label":"Grab an umbrella. A night in would be a waste","image_key":null,"score":2},{"id":"opt_go_but_suggest","label":"Go, but suggest somewhere close by","image_key":null,"score":1},{"id":"opt_take_the_rain","label":"Take the rain as a sign to stay in with tea and a film","image_key":null,"score":0}],"allowOther":false},{"id":"blk_quicksta03","ref":"cafe_table","title":"The only free seat in the café is across from a stranger. What happens next?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_you_sit_down","label":"You sit down and ask what they''re reading","image_key":null,"score":2},{"id":"opt_you_smile_sit","label":"You smile, sit, and see if they start chatting","image_key":null,"score":1},{"id":"opt_you_take_your","label":"You take your coffee to go","image_key":null,"score":0}],"allowOther":false},{"id":"blk_quicksta04","ref":"new_job","title":"It''s your first week somewhere new. How do you get to know people?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_introduce_myself_to","label":"Introduce myself to everyone on day one","image_key":null,"score":2},{"id":"opt_get_to_know","label":"Get to know the people I work closest with first","image_key":null,"score":1},{"id":"opt_let_people_come","label":"Let people come to me over time","image_key":null,"score":0}],"allowOther":false},{"id":"blk_quicksta05","ref":"party","title":"At a party, where are you usually found?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_the_middle","label":"In the middle of the loudest group","image_key":null,"score":2},{"id":"opt_moving_between_a","label":"Moving between a few small conversations","image_key":null,"score":1},{"id":"opt_in_the_kitchen","label":"In the kitchen with one good friend","image_key":null,"score":0}],"allowOther":false},{"id":"blk_quicksta06","ref":"long_week","title":"After a long, busy week, what actually recharges you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_seeing_as_many","label":"Seeing as many people as possible","image_key":null,"score":2},{"id":"opt_dinner_with_one","label":"Dinner with one or two close friends","image_key":null,"score":1},{"id":"opt_a_whole_day","label":"A whole day with nobody to talk to","image_key":null,"score":0}],"allowOther":false},{"id":"blk_quicksta07","ref":"phone_call","title":"Your phone rings with a number you don''t know. You...","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_answer_straight_away","label":"Answer straight away. Could be interesting","image_key":null,"score":2},{"id":"opt_answer_if_you","label":"Answer if you''re not busy","image_key":null,"score":1},{"id":"opt_let_it_ring","label":"Let it ring and wait for a message","image_key":null,"score":0}],"allowOther":false}],"endings":[{"id":"end_quicksta01","ref":"end_thanks","title":"You''re an introvert 📚","bodyMd":"You recharge on your own or with a trusted few. That usually comes with a talent for listening and for deep, one-to-one friendships.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_quicksta02","ref":"end_extrovert","title":"You''re an extrovert 🎉","bodyMd":"You get your energy from other people. Busy rooms, new faces and last-minute plans leave you buzzing rather than drained.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_quicksta03","ref":"end_ambivert","title":"You''re an ambivert ⚖️","bodyMd":"You sit in the middle. You enjoy company and can hold a room, but you also know when you need a quiet night to recover.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_quicksta01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":9}],"groups":[]},"target":"end_extrovert","targetKind":"ending"},{"id":"rs_quicksta02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":5}],"groups":[]},"target":"end_ambivert","targetKind":"ending"}],"logic":[{"id":"rl_quicksta01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_quicksta02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"rainy_saturday"},"op":"eq","value":"opt_grab_an_umbrella"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_quicksta03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"rainy_saturday"},"op":"eq","value":"opt_go_but_suggest"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_quicksta04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cafe_table"},"op":"eq","value":"opt_you_sit_down"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_quicksta05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cafe_table"},"op":"eq","value":"opt_you_smile_sit"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_quicksta06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"new_job"},"op":"eq","value":"opt_introduce_myself_to"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_quicksta07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"new_job"},"op":"eq","value":"opt_get_to_know"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_quicksta08","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"party"},"op":"eq","value":"opt_in_the_middle"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_quicksta09","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"party"},"op":"eq","value":"opt_moving_between_a"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_quicksta10","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"long_week"},"op":"eq","value":"opt_seeing_as_many"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_quicksta11","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"long_week"},"op":"eq","value":"opt_dinner_with_one"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_quicksta12","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"phone_call"},"op":"eq","value":"opt_answer_straight_away"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_quicksta13","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"phone_call"},"op":"eq","value":"opt_answer_if_you"}],"groups":[]},"variable":"score","amount":1}],"layout":{},"variables":[{"name":"score","type":"number","initial":0}],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
