VALUES ('tpl_socialmediaquiz', 'social-media-quiz', 'Social media quiz', 'Quiz', 'Eight scored questions on social media basics that don''t go out of date.', 'Built around ideas that stay true when platforms change features: engagement, organic reach, calls to action and handling a public complaint. The pick-all engagement question takes a point off for impressions, which is the mistake people most often make, and the score lands on one of three results.', '["popular","social media quiz","social media marketing quiz","marketing training quiz","digital marketing test","team quiz"]', 'MessagesSquare', 'choice', 3, 10, '{"schemaVersion":9,"title":"Social media know-how quiz","description":"Eight scored questions on social media basics that don''t go out of date.","blocks":[{"id":"blk_socialme00","ref":"welcome","title":"How well do you know social media? Eight questions on the ideas behind the posts, then your result.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_socialme01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_socialme02","ref":"experience","title":"Which describes you best?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_just_scroll","label":"I just scroll","image_key":null},{"id":"opt_i_post_for","label":"I post for my own business","image_key":null},{"id":"opt_i_manage_social","label":"I manage social media at work","image_key":null},{"id":"opt_i_m_studying","label":"I''m studying marketing","image_key":null}],"allowOther":false},{"id":"blk_socialme03","ref":"engagement_rate","title":"What does an engagement rate usually measure?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_how_many_followers","label":"How many followers an account gained this month","image_key":null},{"id":"opt_interactions_with_a","label":"Interactions with a post compared with how many people saw it or follow the account","image_key":null,"score":1},{"id":"opt_how_many_posts","label":"How many posts an account publishes a week","image_key":null},{"id":"opt_how_long_people","label":"How long people spend on the platform","image_key":null}],"allowOther":false},{"id":"blk_socialme04","ref":"engagement_types","title":"Which of these count as engagement on a post? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_comments","label":"Comments","image_key":null,"score":1},{"id":"opt_shares","label":"Shares","image_key":null,"score":1},{"id":"opt_saves","label":"Saves","image_key":null,"score":1},{"id":"opt_impressions","label":"Impressions","image_key":null,"score":-1}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_socialme05","ref":"organic_reach","title":"What is organic reach?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_people_who_saw","label":"People who saw a post without it being paid to promote","image_key":null,"score":1},{"id":"opt_everyone_who_follows","label":"Everyone who follows the account","image_key":null},{"id":"opt_followers_who_have","label":"Followers who have never unfollowed","image_key":null},{"id":"opt_reach_from_an","label":"Reach from an influencer partnership","image_key":null}],"allowOther":false},{"id":"blk_socialme06","ref":"cta","title":"In a social media post, what does CTA stand for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_content_tracking_analysis","label":"Content tracking analysis","image_key":null},{"id":"opt_call_to_action","label":"Call to action","image_key":null,"score":1},{"id":"opt_click_through_average","label":"Click-through average","image_key":null},{"id":"opt_community_tone_agreement","label":"Community tone agreement","image_key":null}],"allowOther":false},{"id":"blk_socialme07","ref":"angry_comment","title":"A customer leaves an angry public comment about a late order. What''s the best first move?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_delete_it_before","label":"Delete it before others see it","image_key":null},{"id":"opt_reply_publicly_acknowledge","label":"Reply publicly, acknowledge the problem, and move the details to a private message","image_key":null,"score":1},{"id":"opt_ignore_it_replying","label":"Ignore it; replying draws attention","image_key":null},{"id":"opt_reply_explaining_it","label":"Reply explaining it was the courier''s fault","image_key":null}],"allowOther":false},{"id":"blk_socialme08","ref":"ugc","title":"What is user-generated content?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_posts_the_brand","label":"Posts the brand writes with a scheduling tool","image_key":null},{"id":"opt_content_created_by","label":"Content created by customers or fans rather than the brand","image_key":null,"score":1},{"id":"opt_automated_replies_to","label":"Automated replies to comments","image_key":null},{"id":"opt_ads_targeted_at","label":"Ads targeted at existing users","image_key":null}],"allowOther":false},{"id":"blk_socialme09","ref":"disclosure","title":"A creator is paid to feature your product. What should their post do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_clearly_say_it","label":"Clearly say it''s a paid partnership or ad","image_key":null,"score":1},{"id":"opt_look_as_natural","label":"Look as natural as possible, with no mention of payment","image_key":null},{"id":"opt_only_mention_it","label":"Only mention it if someone asks in the comments","image_key":null},{"id":"opt_tag_the_brand","label":"Tag the brand, which counts as disclosure","image_key":null}],"allowOther":false},{"id":"blk_socialme10","ref":"ab_test","title":"You post two versions of the same ad with different images to see which does better. What is this called?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_retargeting","label":"Retargeting","image_key":null},{"id":"opt_a_b_testing","label":"A/B testing","image_key":null,"score":1},{"id":"opt_boosting","label":"Boosting","image_key":null},{"id":"opt_cross_posting","label":"Cross-posting","image_key":null}],"allowOther":false}],"endings":[{"id":"end_socialme01","ref":"end_thanks","title":"Room to grow 🌱","bodyMd":"Social media has its own language, and now you''ve met the key terms. Try again after a look at engagement, organic reach and disclosure rules.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_socialme02","ref":"end_pro","title":"Social media pro 📣","bodyMd":"You know the numbers and the etiquette. Knowing that impressions are not engagement is the detail that separates people who post from people who plan.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_socialme03","ref":"end_solid","title":"Solid foundations 👍","bodyMd":"You have the basics down. Brush up on how engagement is measured and you''ll read your own results with a lot more confidence.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_socialme01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":9}],"groups":[]},"target":"end_pro","targetKind":"ending"},{"id":"rs_socialme02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":6}],"groups":[]},"target":"end_solid","targetKind":"ending"}],"logic":[{"id":"rl_socialme01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_socialme02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"engagement_rate"},"op":"eq","value":"opt_interactions_with_a"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialme03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"engagement_types"},"op":"includes","value":"opt_comments"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialme04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"engagement_types"},"op":"includes","value":"opt_shares"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialme05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"engagement_types"},"op":"includes","value":"opt_saves"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialme06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"engagement_types"},"op":"includes","value":"opt_impressions"}],"groups":[]},"variable":"score","amount":-1},{"id":"rl_socialme07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"organic_reach"},"op":"eq","value":"opt_people_who_saw"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialme08","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cta"},"op":"eq","value":"opt_call_to_action"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialme09","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"angry_comment"},"op":"eq","value":"opt_reply_publicly_acknowledge"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialme10","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"ugc"},"op":"eq","value":"opt_content_created_by"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialme11","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"disclosure"},"op":"eq","value":"opt_clearly_say_it"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialme12","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"ab_test"},"op":"eq","value":"opt_a_b_testing"}],"groups":[]},"variable":"score","amount":1}],"layout":{},"variables":[{"name":"score","type":"number","initial":0}],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#fff1bf","surface":"#ffffff","text":"#3a2e0b","accent":"#1c1917","accentText":"#fff1bf","botBubble":"#ffffff","userBubble":"#1c1917","userBubbleText":"#fff1bf","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"dots-offset","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
