VALUES ('tpl_personalizedproductrecom', 'personalized-product-recommendation-quiz', 'Personalized product recommendation quiz', 'Quiz', 'Brewing method, taste and priorities in, one clear coffee recommendation out.', 'Written for a coffee roaster, but the pattern fits any shop with a handful of products: ask how people will use it, what they like and what matters to them, then recommend one thing with a reason. The final taste question routes to four distinct results, and the answers before it tell you how to grind and what to say in a follow-up.', '["popular","product recommendation quiz","product finder quiz","coffee quiz","shopping quiz","ecommerce quiz"]', 'Coffee', 'choice', 3, 8, '{"schemaVersion":9,"title":"Find your coffee quiz","description":"Brewing method, taste and priorities in, one clear coffee recommendation out.","blocks":[{"id":"blk_personal00","ref":"welcome","title":"Not sure which coffee to try? Answer a few quick questions and we''ll point you to the one that suits how you drink it.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_personal01","ref":"brew_method","title":"How do you usually make coffee at home?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_espresso_machine","label":"Espresso machine","image_key":null},{"id":"opt_filter_or_pour","label":"Filter or pour-over","image_key":null},{"id":"opt_french_press","label":"French press","image_key":null},{"id":"opt_moka_pot","label":"Moka pot","image_key":null},{"id":"opt_i_m_buying","label":"I''m buying for someone else","image_key":null}],"allowOther":false},{"id":"blk_personal02","ref":"milk","title":"How do you take it?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_black","label":"Black","image_key":null},{"id":"opt_with_a_splash","label":"With a splash of milk","image_key":null},{"id":"opt_milky_like_a","label":"Milky, like a latte or flat white","image_key":null},{"id":"opt_iced","label":"Iced","image_key":null}],"allowOther":false},{"id":"blk_personal03","ref":"cups_per_day","title":"How many cups do you drink on a normal day?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":0,"max":15,"integerOnly":true},{"id":"blk_personal04","ref":"flavour_notes","title":"Which of these flavours do you enjoy? Pick any that apply.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_chocolate","label":"Chocolate","image_key":null},{"id":"opt_caramel","label":"Caramel","image_key":null},{"id":"opt_nuts","label":"Nuts","image_key":null},{"id":"opt_berries","label":"Berries","image_key":null},{"id":"opt_citrus","label":"Citrus","image_key":null},{"id":"opt_smoky_or_roasted","label":"Smoky or roasted","image_key":null}],"minSelections":0,"maxSelections":6,"allowOther":false},{"id":"blk_personal05","ref":"priorities","title":"Put these in order of what matters most when you buy coffee.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_flavour","label":"Flavour"},{"id":"opt_item_freshness","label":"Freshness"},{"id":"opt_item_ethical_sourcing","label":"Ethical sourcing"},{"id":"opt_item_value_for","label":"Value for money"}]},{"id":"blk_personal06","ref":"grind","title":"Do you want whole beans or ground coffee?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_whole_beans_i","label":"Whole beans, I grind my own","image_key":null},{"id":"opt_ground_to_suit","label":"Ground to suit my brewer","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}],"allowOther":false},{"id":"blk_personal07","ref":"email","title":"Want brewing tips for your match? Leave your email and we''ll send them over.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_personal08","ref":"slow_morning","title":"Last one. Which cup would you reach for on a slow Sunday morning?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_bright_and_fruity","label":"Bright and fruity, almost like tea","image_key":null},{"id":"opt_smooth_balanced_and","label":"Smooth, balanced and a little chocolatey","image_key":null},{"id":"opt_dark_rich_and","label":"Dark, rich and bold","image_key":null},{"id":"opt_something_gentle_with","label":"Something gentle with little or no caffeine","image_key":null}],"allowOther":false}],"endings":[{"id":"end_personal01","ref":"end_thanks","title":"Your match: our house blend","bodyMd":"You like balance: chocolate, caramel and no sharp edges. The house blend works in almost any brewer and is just as good black as with milk.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_personal02","ref":"end_light","title":"Your match: a light roast single origin ☕","bodyMd":"You like brightness and fruit, and a light roast keeps both. It shines as filter or pour-over, and it''s best black so you taste every note. On an espresso machine it makes a bright, lively shot.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_personal03","ref":"end_dark","title":"Your match: our dark roast","bodyMd":"You want body and a roasted edge that stands up to milk. Our dark roast is made for espresso and moka pots, and holds its flavour black or in a big milky cup.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_personal04","ref":"end_decaf","title":"Your match: our Swiss water decaf","bodyMd":"You want the ritual without the buzz. Our decaf keeps a smooth, chocolatey flavour, so an afternoon or evening cup still tastes like proper coffee.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_personal01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"slow_morning"},"op":"eq","value":"opt_bright_and_fruity"}],"groups":[]},"from":"slow_morning","target":"end_light","targetKind":"ending","branch":"true"},{"id":"rl_personal02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"slow_morning"},"op":"eq","value":"opt_dark_rich_and"}],"groups":[]},"from":"slow_morning","target":"end_dark","targetKind":"ending","branch":"true"},{"id":"rl_personal03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"slow_morning"},"op":"eq","value":"opt_something_gentle_with"}],"groups":[]},"from":"slow_morning","target":"end_decaf","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#f26b1d","surface":"#fff7f0","text":"#1c1917","accent":"#1c1917","accentText":"#ffffff","botBubble":"#fff7f0","userBubble":"#1c1917","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundPatternColor":"#1c1917","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
