VALUES ('tpl_socialquiz', 'social-quiz', 'What kind of friend are you quiz', 'Quiz', 'Five group-chat scenarios that sort people into one of four friend types.', 'A light quiz people want to send to their friends. Each scenario has four answers, one per friend type, and the scores sit on a scale from calm to spontaneous, so the total lands on the listener, the planner, the hype person or the adventurer. Every result is flattering and easy to screenshot.', '["popular","social quiz","friendship quiz","what kind of friend are you","shareable quiz","fun quiz"]', 'Users', 'choice', 3, 7, '{"schemaVersion":9,"title":"What kind of friend are you?","description":"Five group-chat scenarios that sort people into one of four friend types.","blocks":[{"id":"blk_socialqu00","ref":"welcome","title":"Every friend group has a listener, a planner, a hype person and an adventurer. Five scenarios and we''ll tell you which one you are.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_socialqu01","ref":"name","title":"What''s your first name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_socialqu02","ref":"group_chat","title":"What''s your role in the group chat?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_reply_properly","label":"I reply properly when someone needs to talk","image_key":null,"score":0},{"id":"opt_i_m_the","label":"I''m the one setting a date and a place","image_key":null,"score":1},{"id":"opt_i_send_voice","label":"I send voice notes and far too many reactions","image_key":null,"score":2},{"id":"opt_i_m_offline","label":"I''m offline, but I show up with a story later","image_key":null,"score":3}],"allowOther":false},{"id":"blk_socialqu03","ref":"birthday","title":"A friend''s birthday is coming up. You...","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_write_a_card","label":"Write a card that makes them cry a little","image_key":null,"score":0},{"id":"opt_book_the_table","label":"Book the table and remind everyone twice","image_key":null,"score":1},{"id":"opt_plan_a_surprise","label":"Plan a surprise and make sure it''s loud","image_key":null,"score":2},{"id":"opt_take_them_somewhere","label":"Take them somewhere they''ve never been","image_key":null,"score":3}],"allowOther":false},{"id":"blk_socialqu04","ref":"cancelled","title":"Friday plans fall through at the last minute. What happens?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_check_the","label":"I check the person who cancelled is OK","image_key":null,"score":0},{"id":"opt_i_have_a","label":"I have a backup plan ready in five minutes","image_key":null,"score":1},{"id":"opt_i_rally_everyone","label":"I rally everyone else to come to mine","image_key":null,"score":2},{"id":"opt_perfect_excuse_for","label":"Perfect excuse for something spontaneous","image_key":null,"score":3}],"allowOther":false},{"id":"blk_socialqu05","ref":"holiday","title":"Your friends are planning a trip together. Your job is...","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_making_sure_the","label":"Making sure the quieter ones get a say","image_key":null,"score":0},{"id":"opt_the_spreadsheet_the","label":"The spreadsheet, the budget and the bookings","image_key":null,"score":1},{"id":"opt_the_playlist_and","label":"The playlist and the group photos","image_key":null,"score":2},{"id":"opt_finding_the_thing","label":"Finding the thing nobody else would try","image_key":null,"score":3}],"allowOther":false},{"id":"blk_socialqu06","ref":"bad_news","title":"A friend texts you some bad news. Your first move is to...","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_call_them_and","label":"Call them and mostly listen","image_key":null,"score":0},{"id":"opt_work_out_what","label":"Work out what practical help they need","image_key":null,"score":1},{"id":"opt_tell_them_how","label":"Tell them how brilliant they are until they believe it","image_key":null,"score":2},{"id":"opt_get_them_out","label":"Get them out of the house for a change of scene","image_key":null,"score":3}],"allowOther":false},{"id":"blk_socialqu07","ref":"tag_friend","title":"Who''s the first friend you''d send this quiz to?","description":"Just for fun. We won''t contact them.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60}],"endings":[{"id":"end_socialqu01","ref":"end_thanks","title":"You''re the listener 💛","bodyMd":"You''re the friend people call first when something goes wrong. You notice who''s gone quiet and you make room for them.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_socialqu02","ref":"end_adventurer","title":"You''re the adventurer 🧭","bodyMd":"You''re the reason your friends have stories to tell. When things get routine, you''re the one who says yes to something new.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_socialqu03","ref":"end_hype","title":"You''re the hype person 🎉","bodyMd":"You bring the energy. Your friends feel celebrated around you, and every good moment gets louder when you''re there.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_socialqu04","ref":"end_planner","title":"You''re the planner 🗓️","bodyMd":"Without you, the group chat would still be saying \"we should do something\". You turn ideas into dates, and your friends quietly rely on it.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_socialqu01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":12}],"groups":[]},"target":"end_adventurer","targetKind":"ending"},{"id":"rs_socialqu02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":8}],"groups":[]},"target":"end_hype","targetKind":"ending"},{"id":"rs_socialqu03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":4}],"groups":[]},"target":"end_planner","targetKind":"ending"}],"logic":[{"id":"rl_socialqu01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_socialqu02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"group_chat"},"op":"eq","value":"opt_i_m_the"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialqu03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"group_chat"},"op":"eq","value":"opt_i_send_voice"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_socialqu04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"group_chat"},"op":"eq","value":"opt_i_m_offline"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_socialqu05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"birthday"},"op":"eq","value":"opt_book_the_table"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialqu06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"birthday"},"op":"eq","value":"opt_plan_a_surprise"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_socialqu07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"birthday"},"op":"eq","value":"opt_take_them_somewhere"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_socialqu08","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cancelled"},"op":"eq","value":"opt_i_have_a"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialqu09","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cancelled"},"op":"eq","value":"opt_i_rally_everyone"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_socialqu10","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"cancelled"},"op":"eq","value":"opt_perfect_excuse_for"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_socialqu11","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"holiday"},"op":"eq","value":"opt_the_spreadsheet_the"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialqu12","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"holiday"},"op":"eq","value":"opt_the_playlist_and"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_socialqu13","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"holiday"},"op":"eq","value":"opt_finding_the_thing"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_socialqu14","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"bad_news"},"op":"eq","value":"opt_work_out_what"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_socialqu15","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"bad_news"},"op":"eq","value":"opt_tell_them_how"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_socialqu16","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"bad_news"},"op":"eq","value":"opt_get_them_out"}],"groups":[]},"variable":"score","amount":3}],"layout":{},"variables":[{"name":"score","type":"number","initial":0}],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ece3ff","surface":"#ffffff","text":"#2a1f3d","accent":"#6d3fc7","accentText":"#fbf8ff","botBubble":"#ffffff","userBubble":"#6d3fc7","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque",