VALUES ('tpl_ecommerceleadgenerationq', 'e-commerce-lead-generation-quiz', 'Ecommerce lead generation quiz', 'Quiz', 'A running shoe finder for online shops that earns the email instead of demanding it.', 'Shoppers get something useful first: the kind of running shoe that suits where, how far and how they run. The email and a plain marketing opt-in are both optional, and the opt-in is skipped for anyone who leaves no address. Trail runners go straight to a trail pick, and everyone else is matched on the feel they want underfoot.', '["popular","ecommerce quiz","lead generation quiz","online store quiz","email capture quiz","running shoe finder"]', 'Store', 'choice', 3, 9, '{"schemaVersion":9,"title":"Running shoe finder quiz","description":"A running shoe finder for online shops that earns the email instead of demanding it.","blocks":[{"id":"blk_ecommerc00","ref":"welcome","title":"Shopping for running shoes? Tell us a little about how you run and we''ll point you to the pair that suits you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_ecommerc01","ref":"first_name","title":"What''s your first name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_ecommerc02","ref":"running_level","title":"Where are you with running right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_starting_or","label":"Just starting, or coming back after a break","image_key":null},{"id":"opt_running_a_few","label":"Running a few times a week","image_key":null},{"id":"opt_training_for_a","label":"Training for a race","image_key":null}],"allowOther":false},{"id":"blk_ecommerc03","ref":"weekly_distance","title":"Roughly how far do you run in a typical week?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_under_10_km","label":"Under 10 km","image_key":null},{"id":"opt_10_30_km","label":"10–30 km","image_key":null},{"id":"opt_more_than_30","label":"More than 30 km","image_key":null},{"id":"opt_i_don_t","label":"I don''t track it","image_key":null}]},{"id":"blk_ecommerc04","ref":"priorities","title":"Put these in order of what matters most in a running shoe.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_comfort_and","label":"Comfort and cushioning"},{"id":"opt_item_light_weight","label":"Light weight"},{"id":"opt_item_grip","label":"Grip"},{"id":"opt_item_lasting_a","label":"Lasting a long time"}]},{"id":"blk_ecommerc05","ref":"niggles","title":"Have any of these bothered you on runs? Pick any that apply.","description":"It helps us steer you away from shoes that make them worse.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_sore_knees","label":"Sore knees","image_key":null},{"id":"opt_shin_pain","label":"Shin pain","image_key":null},{"id":"opt_blisters_or_rubbing","label":"Blisters or rubbing","image_key":null},{"id":"opt_tired_feet_on","label":"Tired feet on longer runs","image_key":null}],"minSelections":0,"maxSelections":4,"allowOther":false},{"id":"blk_ecommerc06","ref":"email","title":"Where should we send your match, with a sizing guide and a welcome discount?","description":"Optional. You''ll see your result either way.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_ecommerc07","ref":"marketing_consent","title":"Would you also like to hear about new shoes and offers?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"legal_consent","consentText":"I''d like to receive emails about new arrivals and offers. I can unsubscribe at any time using the link in every email.","allowDecline":true,"agreeLabel":"Yes, keep me posted","declineLabel":"No thanks"},{"id":"blk_ecommerc08","ref":"surface","title":"Where do you do most of your running?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_roads_and_pavements","label":"Roads and pavements","image_key":null},{"id":"opt_trails_grass_or","label":"Trails, grass or mud","image_key":null},{"id":"opt_on_a_treadmill","label":"On a treadmill","image_key":null},{"id":"opt_a_mix_of","label":"A mix of everything","image_key":null}],"allowOther":false},{"id":"blk_ecommerc09","ref":"feel","title":"Last question: what do you want your shoes to feel like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_soft_and_cushioned","label":"Soft and cushioned, easy on my legs","image_key":null},{"id":"opt_steady_and_supportive","label":"Steady and supportive, my feet tend to roll inward","image_key":null},{"id":"opt_light_and_fast","label":"Light and fast, for quicker runs","image_key":null}],"allowOther":false}],"endings":[{"id":"end_ecommerc01","ref":"end_thanks","title":"Your match: a cushioned daily trainer","bodyMd":"A well-cushioned everyday shoe takes the sting out of road miles and suits new runners and high mileage alike. It''s the pair most runners wear for most of their runs.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_ecommerc02","ref":"end_trail","title":"Your match: a trail running shoe 🌲","bodyMd":"Off-road ground needs grip and protection. Trail shoes have deeper lugs for mud and loose paths and a tougher upper that stands up to roots and stones.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_ecommerc03","ref":"end_stability","title":"Your match: a stability shoe","bodyMd":"Stability shoes have a firmer section under the arch that helps keep feet rolling in from tipping too far. They suit steady everyday miles when you want a little more support.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_ecommerc04","ref":"end_light","title":"Your match: a lightweight tempo shoe","bodyMd":"A lighter, more responsive shoe makes faster runs and race days feel quicker. If you run most days, keep a cushioned pair for the easy ones too.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_ecommerc01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"email"},"op":"is_empty"}],"groups":[]},"from":"email","target":"surface","targetKind":"block","branch":"true"},{"id":"rl_ecommerc02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"surface"},"op":"eq","value":"opt_trails_grass_or"}],"groups":[]},"from":"surface","target":"end_trail","targetKind":"ending","branch":"true"},{"id":"rl_ecommerc03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feel"},"op":"eq","value":"opt_steady_and_supportive"}],"groups":[]},"from":"feel","target":"end_stability","targetKind":"ending","branch":"true"},{"id":"rl_ecommerc04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feel"},"op":"eq","value":"opt_light_and_fast"}],"groups":[]},"from":"feel","target":"end_light","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#ffdce8","surface":"#ffffff","text":"#3d1424","accent":"#be185d","accentText":"#fff7fa","botBubble":"#ffffff","userBubble":"#be185d","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"scallops","backgroundShape":"rings","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
