VALUES ('tpl_englishplacementtest', 'english-placement-test', 'English placement test', 'Quiz', 'Twelve graded questions, a short writing task and a suggested starting level.', 'The grammar questions climb from beginner to advanced in five steps, each worth a point, and the total suggests a starting level from A1 to C1. A short writing task gives your teachers something real to check before confirming the placement, and the result screens say so.', '["popular","english placement test","english level test","esl placement test","grammar test","language school"]', 'Languages', 'choice', 5, 17, '{"schemaVersion":9,"title":"English placement test","description":"Twelve graded questions, a short writing task and a suggested starting level.","blocks":[{"id":"blk_englishp00","ref":"welcome","title":"Welcome! This short test helps us find the right class for you. It starts easy and gets harder, so don''t worry if the last questions feel difficult.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_englishp01","ref":"name","title":"What''s your full name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":80},{"id":"blk_englishp02","ref":"email","title":"What email address should we send your result to?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_englishp03","ref":"first_language","title":"What is your first language?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_englishp04","ref":"goal","title":"Why are you learning English?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_for_work","label":"For work","image_key":null},{"id":"opt_for_study","label":"For study","image_key":null},{"id":"opt_for_travel","label":"For travel","image_key":null},{"id":"opt_to_pass_an","label":"To pass an exam","image_key":null},{"id":"opt_for_everyday_life","label":"For everyday life","image_key":null}],"allowOther":false},{"id":"blk_englishp05","ref":"grammar_intro","title":"Now twelve grammar and vocabulary questions. Choose the best answer to complete each sentence. If you don''t know, make your best guess.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Continue","type":"statement"},{"id":"blk_englishp06","ref":"q_be","title":"She ___ a teacher.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_am","label":"am","image_key":null},{"id":"opt_is","label":"is","image_key":null,"score":1},{"id":"opt_are","label":"are","image_key":null},{"id":"opt_be","label":"be","image_key":null}],"allowOther":false},{"id":"blk_englishp07","ref":"q_present","title":"I ___ to work by bus every day.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_go","label":"go","image_key":null,"score":1},{"id":"opt_goes","label":"goes","image_key":null},{"id":"opt_going","label":"going","image_key":null},{"id":"opt_gone","label":"gone","image_key":null}],"allowOther":false},{"id":"blk_englishp08","ref":"q_past","title":"Yesterday we ___ to the cinema.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_go","label":"go","image_key":null},{"id":"opt_gone","label":"gone","image_key":null},{"id":"opt_went","label":"went","image_key":null,"score":1},{"id":"opt_going","label":"going","image_key":null}],"allowOther":false},{"id":"blk_englishp09","ref":"q_comparative","title":"This book is ___ than the film.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_most_interesting","label":"most interesting","image_key":null},{"id":"opt_more_interesting","label":"more interesting","image_key":null,"score":1},{"id":"opt_interestinger","label":"interestinger","image_key":null},{"id":"opt_as_interesting","label":"as interesting","image_key":null}],"allowOther":false},{"id":"blk_englishp10","ref":"q_present_perfect","title":"How long ___ you lived in this city?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_do","label":"do","image_key":null},{"id":"opt_are","label":"are","image_key":null},{"id":"opt_did","label":"did","image_key":null},{"id":"opt_have","label":"have","image_key":null,"score":1}],"allowOther":false},{"id":"blk_englishp11","ref":"q_first_conditional","title":"If it rains tomorrow, we ___ at home.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_will_stay","label":"will stay","image_key":null,"score":1},{"id":"opt_would_stay","label":"would stay","image_key":null},{"id":"opt_stayed","label":"stayed","image_key":null},{"id":"opt_had_stayed","label":"had stayed","image_key":null}],"allowOther":false},{"id":"blk_englishp12","ref":"q_passive","title":"The bridge ___ in 1932.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_built","label":"built","image_key":null},{"id":"opt_has_built","label":"has built","image_key":null},{"id":"opt_was_built","label":"was built","image_key":null,"score":1},{"id":"opt_is_building","label":"is building","image_key":null}],"allowOther":false},{"id":"blk_englishp13","ref":"q_second_conditional","title":"If I ___ you, I would accept the offer.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_am","label":"am","image_key":null},{"id":"opt_were","label":"were","image_key":null,"score":1},{"id":"opt_will_be","label":"will be","image_key":null},{"id":"opt_would_be","label":"would be","image_key":null}],"allowOther":false},{"id":"blk_englishp14","ref":"q_suggest","title":"She suggested ___ a taxi to the airport.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_to_take","label":"to take","image_key":null},{"id":"opt_take","label":"take","image_key":null},{"id":"opt_taking","label":"taking","image_key":null,"score":1},{"id":"opt_to_taking","label":"to taking","image_key":null}],"allowOther":false},{"id":"blk_englishp15","ref":"q_deduction","title":"His car is still outside, so he ___ have taken the train.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_must","label":"must","image_key":null,"score":1},{"id":"opt_should","label":"should","image_key":null},{"id":"opt_would","label":"would","image_key":null},{"id":"opt_ought","label":"ought","image_key":null}],"allowOther":false},{"id":"blk_englishp16","ref":"q_inversion","title":"Not only ___ late, but he also forgot the tickets.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_he_was","label":"he was","image_key":null},{"id":"opt_was_he","label":"was he","image_key":null,"score":1},{"id":"opt_he_did","label":"he did","image_key":null},{"id":"opt_did_he_be","label":"did he be","image_key":null}],"allowOther":false},{"id":"blk_englishp17","ref":"q_vocab","title":"Which word means \"to make something bad less serious\"?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_exacerbate","label":"exacerbate","image_key":null},{"id":"opt_instigate","label":"instigate","image_key":null},{"id":"opt_mitigate","label":"mitigate","image_key":null,"score":1},{"id":"opt_relegate","label":"relegate","image_key":null}],"allowOther":false},{"id":"blk_englishp18","ref":"writing_sample","title":"Finally, in three to five sentences, tell us about your job, your studies or a place you love.","description":"This part isn''t scored automatically. A teacher reads it to confirm your level.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":40,"maxLength":1500,"aiQualityCheck":false}],"endings":[{"id":"end_englishp01","ref":"end_thanks","title":"Suggested level: A1, beginner","bodyMd":"A beginner class is the best place to start, and you''ll move up fast. A teacher will read your answers and contact you about next steps.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_englishp02","ref":"end_c1","title":"Suggested level: C1, advanced 🏆","bodyMd":"You handled the hardest structures with ease. A teacher will read your writing and confirm your class by email.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_englishp03","ref":"end_b2","title":"Suggested level: B2, upper intermediate","bodyMd":"You''re comfortable with most everyday grammar and some complex structures. A teacher will check your writing and confirm your class.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_englishp04","ref":"end_b1","title":"Suggested level: B1, intermediate","bodyMd":"You have a solid base and are ready to work on conditionals, the passive and more natural phrasing. We''ll confirm your class after reading your writing.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_englishp05","ref":"end_a2","title":"Suggested level: A2, elementary","bodyMd":"You know the basics of present and past. An elementary class will build your confidence quickly. We''ll confirm by email.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_englishp01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":11}],"groups":[]},"target":"end_c1","targetKind":"ending"},{"id":"rs_englishp02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":9}],"groups":[]},"target":"end_b2","targetKind":"ending"},{"id":"rs_englishp03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":6}],"groups":[]},"target":"end_b1","targetKind":"ending"},{"id":"rs_englishp04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":3}],"groups":[]},"target":"end_a2","targetKind":"ending"}],"logic":[{"id":"rl_englishp01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_englishp02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"q_be"},"op":"eq","value":"opt_is"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_englishp03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"q_present"},"op":"eq","value":"opt_go"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_englishp04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"q_past"},"op":"eq","value":"opt_went"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_englishp05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"q_comparative"},"op":"eq","value":"opt_more_interesting"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_englishp06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"q_present_perfect"},"op":"eq","value":"opt