VALUES ('tpl_mathquiz', 'math-quiz', 'Math quiz', 'Quiz', 'Ten scored problems across the core topics, plus a show-your-working question.', 'Ten problems that each check one skill, with distractors built from the usual mistakes, like 36 for 7 + 5 × 3. The prime numbers question takes a point off for each wrong pick so guessing doesn''t pay, and a written question asks students to explain one method so you can see how they think, not only what they got.', '["popular","math quiz","maths quiz","math practice test","classroom quiz","homework quiz"]', 'Calculator', 'choice', 4, 14, '{"schemaVersion":9,"title":"Math practice quiz","description":"Ten scored problems across the core topics, plus a show-your-working question.","blocks":[{"id":"blk_mathquiz00","ref":"welcome","title":"Ready for some math? Ten questions, no calculator needed, and your score at the end.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_mathquiz01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_mathquiz02","ref":"class_group","title":"Which class or group are you in?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_mathquiz03","ref":"order_ops","title":"What is 7 + 5 × 3?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_36","label":"36","image_key":null},{"id":"opt_22","label":"22","image_key":null,"score":1},{"id":"opt_26","label":"26","image_key":null},{"id":"opt_15","label":"15","image_key":null}],"allowOther":false},{"id":"blk_mathquiz04","ref":"percent","title":"What is 15% of 80?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_8_1","label":"8","image_key":null},{"id":"opt_12","label":"12","image_key":null,"score":1},{"id":"opt_15","label":"15","image_key":null},{"id":"opt_18","label":"18","image_key":null}],"allowOther":false},{"id":"blk_mathquiz05","ref":"equation","title":"Solve for x: 3x − 7 = 11","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_x_3","label":"x = 3","image_key":null},{"id":"opt_x_4","label":"x = 4","image_key":null},{"id":"opt_x_6","label":"x = 6","image_key":null,"score":1},{"id":"opt_x_12","label":"x = 12","image_key":null}],"allowOther":false},{"id":"blk_mathquiz06","ref":"area","title":"A rectangle is 8 cm long and 5 cm wide. What is its area?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_13_cm","label":"13 cm²","image_key":null},{"id":"opt_26_cm","label":"26 cm²","image_key":null},{"id":"opt_40_cm","label":"40 cm²","image_key":null,"score":1},{"id":"opt_45_cm","label":"45 cm²","image_key":null}],"allowOther":false},{"id":"blk_mathquiz07","ref":"fraction","title":"Write 18/24 in its simplest form.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_2_3","label":"2/3","image_key":null},{"id":"opt_3_4","label":"3/4","image_key":null,"score":1},{"id":"opt_4_5","label":"4/5","image_key":null},{"id":"opt_5_6","label":"5/6","image_key":null}],"allowOther":false},{"id":"blk_mathquiz08","ref":"discount","title":"A jacket costs 40 and is reduced by 25%. What is the sale price?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_10","label":"10","image_key":null},{"id":"opt_15","label":"15","image_key":null},{"id":"opt_30","label":"30","image_key":null,"score":1},{"id":"opt_35","label":"35","image_key":null}],"allowOther":false},{"id":"blk_mathquiz09","ref":"primes","title":"Which of these are prime numbers? Pick all that apply.","description":"A wrong pick takes a point away.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_2_1","label":"2","image_key":null,"score":1},{"id":"opt_9_2","label":"9","image_key":null,"score":-1},{"id":"opt_17","label":"17","image_key":null,"score":1},{"id":"opt_21","label":"21","image_key":null,"score":-1},{"id":"opt_23","label":"23","image_key":null,"score":1}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_mathquiz10","ref":"mean","title":"What is the mean of 4, 8, 6, 10 and 7?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_6_1","label":"6","image_key":null},{"id":"opt_7_2","label":"7","image_key":null,"score":1},{"id":"opt_8_3","label":"8","image_key":null},{"id":"opt_35","label":"35","image_key":null}],"allowOther":false},{"id":"blk_mathquiz11","ref":"triangle","title":"Two angles of a triangle are 50° and 60°. What is the third angle?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_70","label":"70°","image_key":null,"score":1},{"id":"opt_80","label":"80°","image_key":null},{"id":"opt_90","label":"90°","image_key":null},{"id":"opt_110","label":"110°","image_key":null}],"allowOther":false},{"id":"blk_mathquiz12","ref":"probability","title":"You roll a fair six-sided die. What is the probability of rolling an even number?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_1_6","label":"1/6","image_key":null},{"id":"opt_1_3","label":"1/3","image_key":null},{"id":"opt_1_2","label":"1/2","image_key":null,"score":1},{"id":"opt_2_3","label":"2/3","image_key":null}],"allowOther":false},{"id":"blk_mathquiz13","ref":"explain_method","title":"Pick one question and explain, step by step, how you worked it out.","description":"Not scored. Your teacher reads this to see your method.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":1500,"aiQualityCheck":false},{"id":"blk_mathquiz14","ref":"difficulty","title":"How hard did that feel?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Easy","labelHigh":"Really hard"}],"endings":[{"id":"end_mathquiz01","ref":"end_thanks","title":"Keep practising 📐","bodyMd":"Some of these topics need another look, and that''s what practice is for. Your teacher will go over the tricky ones with you.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_mathquiz02","ref":"end_top","title":"Math star ⭐","bodyMd":"Nearly everything right, primes included. Your teacher will look at your method, so make sure it''s as tidy as your answers.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_mathquiz03","ref":"end_good","title":"Good work","bodyMd":"You got most of them. Check order of operations and percentages again, since those are where small slips happen.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_mathquiz01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":11}],"groups":[]},"target":"end_top","targetKind":"ending"},{"id":"rs_mathquiz02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":7}],"groups":[]},"target":"end_good","targetKind":"ending"}],"logic":[{"id":"rl_mathquiz01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_mathquiz02","action_kind":"add_score","when":{"o