INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_onlinesciencequiz', 'online-science-quiz', 'Online science quiz', 'Quiz', 'Ten scored questions that ask why things happen, plus a topic to revisit.', 'Most questions describe something students have seen, like lightning before thunder or a spoon heating up in soup, and ask why it happens. The chemical change question takes a point off for each wrong pick, and a final question asks which topic they''d like to go over again, which gives you a lesson plan as well as a score.', '["popular","science quiz","online science quiz","science test","classroom quiz","physics and biology quiz"]', 'FlaskConical', 'choice', 4, 12, '{"schemaVersion":9,"title":"Science understanding quiz","description":"Ten scored questions that ask why things happen, plus a topic to revisit.","blocks":[{"id":"blk_onlinesc00","ref":"welcome","title":"Time for some science. These questions ask why things happen, so think it through before you pick.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_onlinesc01","ref":"name","title":"What''s your name?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":60},{"id":"blk_onlinesc02","ref":"lightning","title":"During a storm, why do you see lightning before you hear thunder?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_lightning_happens_first","label":"Lightning happens first and thunder follows later","image_key":null},{"id":"opt_light_travels_much","label":"Light travels much faster than sound","image_key":null,"score":1},{"id":"opt_sound_is_blocked","label":"Sound is blocked by the clouds","image_key":null},{"id":"opt_our_eyes_react","label":"Our eyes react faster than our ears","image_key":null}],"allowOther":false},{"id":"blk_onlinesc03","ref":"conduction","title":"A metal spoon left in hot soup gets hot all the way up the handle. How does the heat travel?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_radiation","label":"Radiation","image_key":null},{"id":"opt_convection","label":"Convection","image_key":null},{"id":"opt_conduction","label":"Conduction","image_key":null,"score":1},{"id":"opt_evaporation","label":"Evaporation","image_key":null}],"allowOther":false},{"id":"blk_onlinesc04","ref":"ice_floats","title":"Why does ice float on water?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_ice_is_less","label":"Ice is less dense than liquid water","image_key":null,"score":1},{"id":"opt_ice_has_air","label":"Ice has air trapped inside it","image_key":null},{"id":"opt_cold_things_always","label":"Cold things always rise","image_key":null},{"id":"opt_ice_is_lighter","label":"Ice is lighter than water in every amount","image_key":null}],"allowOther":false},{"id":"blk_onlinesc05","ref":"dark_plant","title":"A plant kept in a dark cupboard for a week turns pale and weak. What couldn''t it do?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_respiration","label":"Respiration","image_key":null},{"id":"opt_photosynthesis","label":"Photosynthesis","image_key":null,"score":1},{"id":"opt_transpiration","label":"Transpiration","image_key":null},{"id":"opt_pollination","label":"Pollination","image_key":null}],"allowOther":false},{"id":"blk_onlinesc06","ref":"seasons","title":"What causes the seasons on Earth?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_earth_moving_closer","label":"Earth moving closer to and further from the Sun","image_key":null},{"id":"opt_the_tilt_of","label":"The tilt of Earth''s axis","image_key":null,"score":1},{"id":"opt_changes_in_the","label":"Changes in the Sun''s temperature","image_key":null},{"id":"opt_the_moon_s","label":"The Moon''s orbit","image_key":null}],"allowOther":false},{"id":"blk_onlinesc07","ref":"chemical_change","title":"Which of these are chemical changes? Pick all that apply.","description":"A wrong pick takes a point away.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_burning_wood","label":"Burning wood","image_key":null,"score":1},{"id":"opt_melting_ice","label":"Melting ice","image_key":null,"score":-1},{"id":"opt_iron_rusting","label":"Iron rusting","image_key":null,"score":1},{"id":"opt_dissolving_sugar_in","label":"Dissolving sugar in water","image_key":null,"score":-1},{"id":"opt_baking_a_cake","label":"Baking a cake","image_key":null,"score":1}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_onlinesc08","ref":"falling","title":"Ignoring air resistance, you drop a heavy ball and a light ball of the same size from the same height. Which lands first?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_heavy_ball","label":"The heavy ball","image_key":null},{"id":"opt_the_light_ball","label":"The light ball","image_key":null},{"id":"opt_they_land_at","label":"They land at the same time","image_key":null,"score":1},{"id":"opt_it_depends_on","label":"It depends on the colour","image_key":null}],"allowOther":false},{"id":"blk_onlinesc09","ref":"red_blood","title":"What is the main job of red blood cells?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_fighting_infections","label":"Fighting infections","image_key":null},{"id":"opt_carrying_oxygen_around","label":"Carrying oxygen around the body","image_key":null,"score":1},{"id":"opt_helping_blood_clot","label":"Helping blood clot","image_key":null},{"id":"opt_digesting_food","label":"Digesting food","image_key":null}],"allowOther":false},{"id":"blk_onlinesc10","ref":"breathe_out","title":"Which gas do you breathe out more of than you breathe in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_oxygen","label":"Oxygen","image_key":null},{"id":"opt_nitrogen","label":"Nitrogen","image_key":null},{"id":"opt_carbon_dioxide","label":"Carbon dioxide","image_key":null,"score":1},{"id":"opt_hydrogen","label":"Hydrogen","image_key":null}],"allowOther":false},{"id":"blk_onlinesc11","ref":"light_year","title":"What does a light-year measure?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_time","label":"Time","image_key":null},{"id":"opt_distance","label":"Distance","image_key":null,"score":1},{"id":"opt_brightness","label":"Brightness","image_key":null},{"id":"opt_speed","label":"Speed","image_key":null}],"allowOther":false},{"id":"blk_onlinesc12","ref":"revisit","title":"Which topics would you like to go over again?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_heat_and_energy","label":"Heat and energy","image_key":null},{"id":"opt_forces_and_motion","label":"Forces and motion","image_key":null},{"id":"opt_living_things","label":"Living things","image_key":null},{"id":"opt_earth_and_space","label":"Earth and space","image_key":null},{"id":"opt_materials_and_chemical","label":"Materials and chemical change","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false}],"endings":[{"id":"end_onlinesc01","ref":"end_thanks","title":"Keep exploring 🌍","bodyMd":"Science is full of answers that surprise people. Your teacher will go over the topics you picked, and you can try again after.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]