VALUES ('tpl_geographyquiz', 'geography-quiz', 'Geography quiz', 'Quiz', 'Seven scored questions, from easy capitals to a tricky borders round.', 'A mix of question styles so it never feels like a worksheet: multiple choice, a pick-all-that-apply round and a confidence check before the reveal. Each right answer carries a point, and the total picks one of three results.', '["popular","geography quiz","trivia","scored quiz","classroom","team quiz"]', 'Globe', 'choice', 3, 9, '{"schemaVersion":9,"title":"Geography quiz","description":"Seven scored questions, from easy capitals to a tricky borders round.","blocks":[{"id":"blk_geograph00","ref":"welcome","title":"Ready to test your geography? Seven questions, and you''ll get a result at the end.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_geograph01","ref":"player","title":"What name should go on the scoreboard?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":40},{"id":"blk_geograph02","ref":"capital_au","title":"What is the capital of Australia?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_sydney","label":"Sydney","image_key":null},{"id":"opt_canberra","label":"Canberra","image_key":null,"score":1},{"id":"opt_melbourne","label":"Melbourne","image_key":null},{"id":"opt_perth","label":"Perth","image_key":null}],"allowOther":false},{"id":"blk_geograph03","ref":"longest_river","title":"Which river is usually named the longest in the world?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_amazon","label":"Amazon","image_key":null},{"id":"opt_yangtze","label":"Yangtze","image_key":null},{"id":"opt_nile","label":"Nile","image_key":null,"score":1},{"id":"opt_mississippi","label":"Mississippi","image_key":null}],"allowOther":false},{"id":"blk_geograph04","ref":"landlocked","title":"Which of these countries have no coastline? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_bolivia","label":"Bolivia","image_key":null,"score":1},{"id":"opt_portugal","label":"Portugal","image_key":null,"score":-1},{"id":"opt_nepal","label":"Nepal","image_key":null,"score":1},{"id":"opt_chile","label":"Chile","image_key":null,"score":-1},{"id":"opt_switzerland","label":"Switzerland","image_key":null,"score":1}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_geograph05","ref":"largest_desert","title":"Not counting the polar ones, which is the largest desert?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_gobi","label":"Gobi","image_key":null},{"id":"opt_kalahari","label":"Kalahari","image_key":null},{"id":"opt_sahara","label":"Sahara","image_key":null,"score":1},{"id":"opt_atacama","label":"Atacama","image_key":null}],"allowOther":false},{"id":"blk_geograph06","ref":"most_countries","title":"Which continent has the most countries?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_asia","label":"Asia","image_key":null},{"id":"opt_africa","label":"Africa","image_key":null,"score":1},{"id":"opt_europe","label":"Europe","image_key":null},{"id":"opt_south_america","label":"South America","image_key":null}],"allowOther":false},{"id":"blk_geograph07","ref":"everest","title":"Mount Everest sits on the border of Nepal and which other country?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_india","label":"India","image_key":null},{"id":"opt_bhutan","label":"Bhutan","image_key":null},{"id":"opt_china","label":"China","image_key":null,"score":1},{"id":"opt_pakistan","label":"Pakistan","image_key":null}],"allowOther":false},{"id":"blk_geograph08","ref":"smallest","title":"What is the smallest country in the world by area?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_monaco","label":"Monaco","image_key":null},{"id":"opt_vatican_city","label":"Vatican City","image_key":null,"score":1},{"id":"opt_san_marino","label":"San Marino","image_key":null},{"id":"opt_malta","label":"Malta","image_key":null}],"allowOther":false},{"id":"blk_geograph09","ref":"confidence","title":"Before you see your result: how well do you think you did?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Guessed it all","labelHigh":"Nailed it"}],"endings":[{"id":"end_geograph01","ref":"end_thanks","title":"Tourist in training 🧭","bodyMd":"Geography is full of traps like Canberra and the Vatican. Have another go and see how much you improve.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_geograph02","ref":"end_expert","title":"Atlas-level knowledge 🌍","bodyMd":"You got nearly everything right, landlocked countries included. That round catches most people out.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_geograph03","ref":"end_traveller","title":"Seasoned traveller ✈️","bodyMd":"A solid score. A couple of capitals and borders tripped you up, but you clearly know your way around a map.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_geograph01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":8}],"groups":[]},"target":"end_expert","targetKind":"ending"},{"id":"rs_geograph02","action_kind":"goto","when":