VALUES ('tpl_3dscannerrecommendationq', '3d-scanner-recommendation-quiz', '3D scanner recommendation quiz', 'Quiz', 'Ask what they scan, how precisely and where, then point them to one of four scanner types.', 'Written the way a good sales engineer qualifies a scanner enquiry: object size, the detail the job needs, surfaces that defeat most scanners, and where the work happens. The last answer about what the scans are for routes each buyer to one of four results, and every earlier answer lands in your dashboard for the follow-up.', '["product recommendation","3d scanner quiz","product finder","scanner buying guide","reverse engineering","3d printing"]', 'Camera', 'content', 3, 10, '{"schemaVersion":9,"title":"3D scanner finder","description":"Ask what they scan, how precisely and where, then point them to one of four scanner types.","blocks":[{"id":"blk_3dscanne00","ref":"welcome","title":"Not sure which 3D scanner fits your work? A few questions about what you scan, and we''ll point you to the right kind.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_3dscanne01","ref":"object_size","title":"What size are the objects you''ll scan most often?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_small_enough_to","label":"Small enough to hold in one hand","description":"Jewellery, dental models, small parts","image_key":null},{"id":"opt_shoebox_to_suitcase","label":"Shoebox to suitcase sized","description":"Tools, shoes, housings, busts","image_key":null},{"id":"opt_large_items","label":"Large items","description":"Car panels, furniture, sculptures","image_key":null},{"id":"opt_whole_rooms_buildings","label":"Whole rooms, buildings or outdoor sites","image_key":null}],"allowOther":false},{"id":"blk_3dscanne02","ref":"detail","title":"How fine does the detail need to be?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Rough shape is fine","labelHigh":"Every edge and texture"},{"id":"blk_3dscanne03","ref":"surfaces","title":"Will any of these surfaces come up? Pick all that apply.","description":"These are the ones that trip scanners up, so they change what we''d suggest.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_shiny_or_reflective","label":"Shiny or reflective metal","image_key":null},{"id":"opt_black_or_very","label":"Black or very dark","image_key":null},{"id":"opt_clear_glass_or","label":"Clear glass or plastic","image_key":null},{"id":"opt_people_skin_or","label":"People, skin or hair","image_key":null},{"id":"opt_none_of_these","label":"None of these","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_3dscanne04","ref":"colour","title":"Do you need the scan to capture colour and texture, not just shape?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_3dscanne05","ref":"environment","title":"Where will most of the scanning happen?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_on_a_desk","label":"On a desk or bench","image_key":null},{"id":"opt_in_a_workshop","label":"In a workshop or on a factory floor","image_key":null},{"id":"opt_on_site_carried","label":"On site, carried from place to place","image_key":null},{"id":"opt_outdoors","label":"Outdoors","image_key":null}],"allowOther":false},{"id":"blk_3dscanne06","ref":"priorities","title":"Put these in order, most important first.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_accuracy","label":"Accuracy"},{"id":"opt_item_speed_of","label":"Speed of scanning"},{"id":"opt_item_ease_of","label":"Ease of use"},{"id":"opt_item_portability","label":"Portability"},{"id":"opt_item_price","label":"Price"}]},{"id":"blk_3dscanne07","ref":"experience","title":"Have you worked with 3D scan data before?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_no_this_is","label":"No, this is my first scanner","image_key":null},{"id":"opt_a_little_mostly","label":"A little, mostly for 3D printing","image_key":null},{"id":"opt_yes_in_cad","label":"Yes, in CAD or inspection software every week","image_key":null}],"allowOther":false},{"id":"blk_3dscanne08","ref":"budget","title":"Roughly what budget are you working with?","description":"Swap these ranges for the price points in your own range.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_entry_level","label":"Entry level","image_key":null},{"id":"opt_mid_range","label":"Mid range","image_key":null},{"id":"opt_professional","label":"Professional","image_key":null},{"id":"opt_industrial_if_it","label":"Industrial, if it''s the right tool","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}]},{"id":"blk_3dscanne09","ref":"email","title":"Where should we send the specs for your match?","description":"Optional. Leave it blank if you just want the answer on screen.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_3dscanne10","ref":"use","title":"Last one: what will the scans mainly be used for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_3d_printing_hobby","label":"3D printing, hobby projects or personal use","image_key":null},{"id":"opt_product_design_or","label":"Product design or reverse engineering","image_key":null},{"id":"opt_quality_inspection_and","label":"Quality inspection and measurement","image_key":null},{"id":"opt_recording_buildings_rooms","label":"Recording buildings, rooms or heritage sites","image_key":null}],"allowOther":false}],"endings":[{"id":"end_3dscanne01","ref":"end_thanks","title":"An entry-level desktop or handheld scanner 🖨️","bodyMd":"For printing and personal projects, a desktop turntable scanner for small objects, or an entry-level handheld for anything bigger, is the easiest place to start. They give you print-ready models without a steep learning curve. If you scan shiny or dark objects, a light coat of scanning spray makes a big difference.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_3dscanne02","ref":"end_design","title":"A professional handheld scanner 🛠️","bodyMd":"For reverse engineering you need clean, accurate meshes that drop straight into CAD. A handheld laser or blue-light scanner copes with shiny and dark parts better than entry-level models, and it goes to the part instead of the part coming to the desk. We''ll follow up with the models that fit the sizes you scan.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_3dscanne03","ref":"end_metrology","title":"A metrology-grade scanner 📐","bodyMd":"Inspection work needs measured, repeatable accuracy with a calibration certificate behind it, not just a nice-looking model. A metrology-grade blue-light or laser scanner, paired with inspection software, lets you compare every part to its CAD file. Our team will get in touch to talk through tolerances before you buy.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_3dscanne04","ref":"end_large","title":"A long-range scanner 🏛️","bodyMd":"Rooms, buildings and sites are a different job from objects on a bench. A long-range laser scanner captures whole spaces from a few set-ups and stitches them together, and works outdoors where handheld scanners struggle. We''ll send the options that suit the size of the spaces you record.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_3dscanne01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"use"},"op":"eq","value":"opt_product_design_or"}],"groups":[]},"from":"use","target":"end_design","targetKind":"ending","branch":"true"},{"id":"rl_3dscanne02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"use"},"op":"eq","value":"opt_quality_inspection_and"}],"groups":[]},"from":"use","target":"end_metrology","targetKind":"ending","branch":"true"},{"id":"rl_3dscanne03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"use"},"op":"eq","value":"opt_recording_buildings_rooms"}],"groups":[]},"from":"use","target":"end_large","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#d9f2e6","surface":"#ffffff","text":"#12342a","accent":"#0f766e","accentText":"#f5fffb","botBubble":"#ffffff","userBubble":"#0f766e","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"plus","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
