INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_acrylicnailrecommendatio', 'acrylic-nail-recommendation-quiz', 'Acrylic nail quiz', 'Quiz', 'Suggest a length and shape that suits how a client lives, and flag sensitivities before the appointment.', 'Asks what a good nail tech asks at the start of a consultation: how hands-on their day is, the length and shape they like, how often they can come back for infills. Those answers are scored into one of three style results, and anyone who mentions a past reaction is asked for details your tech can read before the booking.', '["product recommendation","acrylic nail quiz","nail shape quiz","nail salon","nail consultation","beauty quiz"]', 'Sparkles', 'content', 3, 10, '{"schemaVersion":9,"title":"Acrylic nail style quiz","description":"Suggest a length and shape that suits how a client lives, and flag sensitivities before the appointment.","blocks":[{"id":"blk_acrylicn00","ref":"welcome","title":"Let''s find your nail style. A few quick questions and we''ll suggest a length and shape that suits you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_acrylicn01","ref":"experience","title":"Have you had acrylics before?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_never_this_would","label":"Never, this would be my first set","image_key":null},{"id":"opt_a_few_times","label":"A few times","image_key":null},{"id":"opt_i_wear_them","label":"I wear them most of the time","image_key":null}],"allowOther":false},{"id":"blk_acrylicn02","ref":"hands_on","title":"How hands-on is your usual day?","description":"Typing, cooking, lifting, looking after little ones: it all counts.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_very_my_hands","label":"Very, my hands are busy all day","image_key":null,"score":0},{"id":"opt_somewhere_in_the","label":"Somewhere in the middle","image_key":null,"score":1},{"id":"opt_not_very_i","label":"Not very, I can be careful with them","image_key":null,"score":2}],"allowOther":false},{"id":"blk_acrylicn03","ref":"length","title":"What length feels right?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_short_just_past","label":"Short, just past the fingertip","image_key":null,"score":0},{"id":"opt_medium","label":"Medium","image_key":null,"score":1},{"id":"opt_long","label":"Long","image_key":null,"score":2},{"id":"opt_as_long_as","label":"As long as possible","image_key":null,"score":3}],"allowOther":false},{"id":"blk_acrylicn04","ref":"shape","title":"Which shape do you like the look of?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_round_or_oval","label":"Round or oval","description":"Soft and natural","image_key":null,"score":0},{"id":"opt_squoval","label":"Squoval","description":"A square with softened corners","image_key":null,"score":0},{"id":"opt_almond","label":"Almond","description":"Slim with a rounded point","image_key":null,"score":1},{"id":"opt_coffin_or_ballerina","label":"Coffin or ballerina","description":"Tapered with a flat tip","image_key":null,"score":2},{"id":"opt_stiletto","label":"Stiletto","description":"Long and pointed","image_key":null,"score":3}],"allowOther":false},{"id":"blk_acrylicn05","ref":"colours","title":"What colours and finishes are you drawn to?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_nudes_and_soft","label":"Nudes and soft pinks","image_key":null},{"id":"opt_french_tips","label":"French tips","image_key":null},{"id":"opt_bright_bold_colours","label":"Bright, bold colours","image_key":null},{"id":"opt_dark_and_moody","label":"Dark and moody","image_key":null},{"id":"opt_chrome_glitter_or","label":"Chrome, glitter or shimmer","image_key":null},{"id":"opt_hand_painted_nail","label":"Hand-painted nail art","image_key":null}],"minSelections":0,"maxSelections":6,"allowOther":false},{"id":"blk_acrylicn06","ref":"occasion","title":"Are these for everyday or a special occasion?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_everyday","label":"Everyday","image_key":null},{"id":"opt_a_holiday","label":"A holiday","image_key":null},{"id":"opt_a_wedding_party","label":"A wedding, party or event","image_key":null}],"allowOther":false},{"id":"blk_acrylicn07","ref":"infills","title":"How often could you come back for infills?","description":"Acrylics usually need filling as your natural nail grows out.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_every_two_to","label":"Every two to three weeks","image_key":null},{"id":"opt_about_once_a","label":"About once a month","image_key":null},{"id":"opt_i_m_not","label":"I''m not sure I can keep up with that","image_key":null}],"allowOther":false},{"id":"blk_acrylicn08","ref":"reaction","title":"Have you ever had a reaction or sore skin from nail products?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_acrylicn09","ref":"reaction_detail","title":"Sorry to hear it. What happened, and roughly when?","description":"Your nail tech will read this before your appointment.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"long_text","minLength":0,"maxLength":800,"aiQualityCheck":false},{"id":"blk_acrylicn10","ref":"contact","title":"Who should we send your result and booking link to?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","email","phone"]}],"endings":[{"id":"end_acrylicn01","ref":"end_thanks","title":"Short squoval or oval 🌸","bodyMd":"Your hands work hard, so a short squoval or oval set gives you a finished look without getting in the way. Short acrylics are also the easiest to wear for a first set, and they chip less on busy days.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_acrylicn02","ref":"end_statement","title":"Long coffin or stiletto 💅","bodyMd":"You want nails people notice. A long coffin or stiletto set shows off colour, chrome and nail art best. Plan on regular infills to keep the length strong, and on a little extra care on busy days.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_acrylicn03","ref":"end_everyday_glam","title":"Medium almond ✨","bodyMd":"Almond at a medium length is the sweet spot: it lengthens your fingers and looks polished, but it''s still easy to type and live in. It suits almost any colour, from nudes to French tips.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_acrylicn01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":6}],"groups":[]},"target":"end_statement","targetKind":"ending"},{"id":"rs_acrylicn02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":3}],"groups":[]},"target":"end_everyday_glam","targetKind":"ending"}],"logic":[{"id":"rl_acrylicn01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_acrylicn02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"hands_on"},"op":"eq","value":"opt_somewhere_in_the"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_acrylicn03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"hands_on"},"op":"eq","value":"opt_not_very_i"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_acrylicn04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"length"},"op":"eq","value":"opt_medium"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_acrylicn05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"length"},"op":"eq","value":"opt_long"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_acrylicn06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"length"},"op":"eq","value":"opt_as_long_as"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_acrylicn07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"shape"},"op":"eq","value":"opt_almond"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_acrylicn08","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"shape"},"op":"eq","value":"opt_coffin_or_ballerina"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_acrylicn09","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"shape"},"op":"eq","value":"opt_stiletto"}],"groups":[]},"variable":"score","amount":3},{"id":"rl_acrylicn10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reaction"},"op":"eq","value":true}],"groups":[]},"from":"reaction","target":"reaction_detail","targetKind":"block","branch":"true"},{"id":"rl_acrylicn11","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"reaction"},"op":"eq","value":false}],"groups":[]},"from":"reaction","target":"contact","targetKind":"block","branch":"true"},{"id":"rl_acrylicn12","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":6}],"groups":[]},"from":"reaction_detail","target":"end_statement","targetKind":"ending","branch":"true"},{"id":"rl_acrylicn13","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":3}],"groups":[]},"from":"reaction_detail","target":"end_everyday_glam","targetKind":"ending","branch":"true"},{"id":"rl_acrylicn14","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"reaction_detail","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[{"name":"score","type":"number","initial":0}],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
