INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_beddingrecommendationqui', 'bedding-recommendation-quiz', 'Bedding quiz', 'Quiz', 'Score how warm someone sleeps and the feel they like, then suggest cool, all-season or cosy bedding.', 'The questions that actually decide bedding: whether they sleep hot or cold, how warm the room gets, and whether they like crisp or soft sheets. Each answer adds to a warmth score that picks one of three results, while bed size, mattress depth and allergy details go to your dashboard so the order fits first time.', '["product recommendation","bedding quiz","sheet finder","duvet quiz","home store","sleep quiz"]', 'Home', 'content', 3, 11, '{"schemaVersion":9,"title":"Bedding finder","description":"Score how warm someone sleeps and the feel they like, then suggest cool, all-season or cosy bedding.","blocks":[{"id":"blk_beddingr00","ref":"welcome","title":"Let''s find bedding you''ll sleep well in. Tell us how you sleep and we''ll suggest a set.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_beddingr01","ref":"bed_size","title":"What size is your bed?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_single_or_twin","label":"Single or twin","image_key":null},{"id":"opt_double_or_full","label":"Double or full","image_key":null},{"id":"opt_queen","label":"Queen","image_key":null},{"id":"opt_king","label":"King","image_key":null},{"id":"opt_super_king_or","label":"Super king or California king","image_key":null}]},{"id":"blk_beddingr02","ref":"mattress_depth","title":"How deep is your mattress, including any topper?","description":"Optional, in centimetres. It tells us how deep a fitted sheet you need.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":5,"max":60,"integerOnly":true},{"id":"blk_beddingr03","ref":"sleep_temp","title":"How do you usually sleep?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_hot_i_kick","label":"Hot, I kick the covers off","image_key":null,"score":0},{"id":"opt_somewhere_in_between","label":"Somewhere in between","image_key":null,"score":1},{"id":"opt_cold_i_m","label":"Cold, I''m the one stealing the duvet","image_key":null,"score":2}],"allowOther":false},{"id":"blk_beddingr04","ref":"room_temp","title":"How warm is your bedroom at night?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_warm_even_in","label":"Warm, even in winter","image_key":null,"score":0},{"id":"opt_comfortable_most_of","label":"Comfortable most of the year","image_key":null,"score":1},{"id":"opt_chilly_especially_in","label":"Chilly, especially in winter","image_key":null,"score":2}],"allowOther":false},{"id":"blk_beddingr05","ref":"feel","title":"Which feel do you like against your skin?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_crisp_and_cool","label":"Crisp and cool, like a fresh shirt","image_key":null,"score":0},{"id":"opt_smooth_and_silky","label":"Smooth and silky","image_key":null,"score":1},{"id":"opt_soft_and_brushed","label":"Soft and brushed, almost fuzzy","image_key":null,"score":2}],"allowOther":false},{"id":"blk_beddingr06","ref":"season","title":"When will you use this bedding most?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_mostly_in_summer","label":"Mostly in summer","image_key":null,"score":0},{"id":"opt_all_year_round","label":"All year round","image_key":null,"score":1},{"id":"opt_mostly_in_winter","label":"Mostly in winter","image_key":null,"score":2}],"allowOther":false},{"id":"blk_beddingr07","ref":"pieces","title":"What do you need?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_fitted_sheet","label":"Fitted sheet","image_key":null},{"id":"opt_flat_sheet","label":"Flat sheet","image_key":null},{"id":"opt_duvet_cover","label":"Duvet cover","image_key":null},{"id":"opt_pillowcases","label":"Pillowcases","image_key":null},{"id":"opt_duvet_or_comforter","label":"Duvet or comforter","image_key":null},{"id":"opt_pillows","label":"Pillows","image_key":null},{"id":"opt_mattress_protector","label":"Mattress protector","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_beddingr08","ref":"ironing","title":"How do you feel about ironing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Never going to happen","labelHigh":"Happy to iron"},{"id":"blk_beddingr09","ref":"allergies","title":"Does anyone sleeping here have allergies or sensitive skin?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_beddingr10","ref":"allergy_detail","title":"Which of these should we avoid or look for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_dust_mite_allergy","label":"Dust mite allergy","image_key":null},{"id":"opt_feather_or_down","label":"Feather or down allergy","image_key":null},{"id":"opt_wool_sensitivity","label":"Wool sensitivity","image_key":null},{"id":"opt_eczema_or_easily","label":"Eczema or easily irritated skin","image_key":null},{"id":"opt_something_else","label":"Something else","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_beddingr11","ref":"email","title":"Want your picks sent over so you can shop later?","description":"Optional.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false}],"endings":[{"id":"end_beddingr01","ref":"end_thanks","title":"Cool and breathable ❄️","bodyMd":"Cotton percale or linen with a lightweight duvet. Percale is crisp and matte, and linen gets softer with every wash; both breathe well, which is what a hot sleeper needs. If you''d rather not iron, linen looks good a little rumpled.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_beddingr02","ref":"end_cosy","title":"Warm and cosy 🧣","bodyMd":"Brushed cotton or flannel sheets with a heavier winter duvet. Brushed cotton traps a little warmth and feels soft from the first night, which is exactly what a cold sleeper in a chilly room wants.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_beddingr03","ref":"end_all_season","title":"Cotton sateen, all season 🛏️","bodyMd":"Smooth cotton sateen sheets with a medium-weight duvet. Sateen feels silky and a touch warmer than crisp cotton, so it works across the year without swapping sets each season.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[{"id":"rs_beddingr01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":6}],"groups":[]},"target":"end_cosy","targetKind":"ending"},{"id":"rs_beddingr02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":3}],"groups":[]},"target":"end_all_season","targetKind":"ending"}],"logic":[{"id":"rl_beddingr01","action_kind":"set_variable","when":null,"variable":"score","expr":0},{"id":"rl_beddingr02","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"sleep_temp"},"op":"eq","value":"opt_somewhere_in_between"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_beddingr03","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"sleep_temp"},"op":"eq","value":"opt_cold_i_m"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_beddingr04","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"room_temp"},"op":"eq","value":"opt_comfortable_most_of"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_beddingr05","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"room_temp"},"op":"eq","value":"opt_chilly_especially_in"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_beddingr06","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feel"},"op":"eq","value":"opt_smooth_and_silky"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_beddingr07","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"feel"},"op":"eq","value":"opt_soft_and_brushed"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_beddingr08","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"season"},"op":"eq","value":"opt_all_year_round"}],"groups":[]},"variable":"score","amount":1},{"id":"rl_beddingr09","action_kind":"add_score","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"season"},"op":"eq","value":"opt_mostly_in_winter"}],"groups":[]},"variable":"score","amount":2},{"id":"rl_beddingr10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"allergies"},"op":"eq","value":true}],"groups":[]},"from":"allergies","target":"allergy_detail","targetKind":"block","branch":"true"},{"id":"rl_beddingr11","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"allergies"},"op":"eq","value":false}],"groups":[]},"from":"allergies","target":"email","targetKind":"block","branch":"true"},{"id":"rl_beddingr12","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":6}],"groups":[]},"from":"allergy_detail","target":"end_cosy","targetKind":"ending","branch":"true"},{"id":"rl_beddingr13","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"variable","name":"score"},"op":"gte","value":3}],"groups":[]},"from":"allergy_detail","target":"end_all_season","targetKind":"ending","branch":"true"},{"id":"rl_beddingr14","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"allergy_detail","target":"end_thanks","targetKind":"ending","branch":"true"}],"layout":{},"variables":[{"name":"score","type":"number","initial":0}],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
