VALUES ('tpl_bikewheelrecommendationq', 'bike-wheel-recommendation-quiz', 'Bike wheel quiz', 'Quiz', 'Check compatibility first, then match road, gravel, mountain or commuter riders to the right wheels.', 'Compatibility comes first, because the wrong brake type or axle makes any wheel useless. Riders who don''t know their brake type are asked for a photo so your shop can check, and the final question about where they ride sends them to a road, gravel, mountain or commuter result.', '["product recommendation","bike wheel quiz","wheelset finder","bike shop","cycling quiz","wheel compatibility"]', 'Bike', 'content', 3, 10, '{"schemaVersion":9,"title":"Bike wheel finder","description":"Check compatibility first, then match road, gravel, mountain or commuter riders to the right wheels.","blocks":[{"id":"blk_bikewhee00","ref":"welcome","title":"Looking for new wheels? Let''s check what fits your bike, then find what suits your riding.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_bikewhee01","ref":"wheel_size","title":"What wheel size does your bike use?","description":"It''s usually printed on the side of the tyre.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_700c","label":"700c","image_key":null},{"id":"opt_650b","label":"650b","image_key":null},{"id":"opt_29_inch","label":"29 inch","image_key":null},{"id":"opt_27_5_inch","label":"27.5 inch","image_key":null},{"id":"opt_26_inch","label":"26 inch","image_key":null},{"id":"opt_20_inch_or","label":"20 inch or smaller","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null}]},{"id":"blk_bikewhee02","ref":"brakes","title":"What kind of brakes does your bike have?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_rim_brakes","label":"Rim brakes","description":"Pads squeeze the edge of the wheel","image_key":null},{"id":"opt_disc_brakes","label":"Disc brakes","description":"A metal rotor sits at the centre of the wheel","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null}],"allowOther":false},{"id":"blk_bikewhee03","ref":"bike_photo","title":"No problem. Could you send a photo of the front wheel''s centre and brake?","description":"We''ll check the brake and axle type for you.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"file_upload","accept":["image/*"],"maxFiles":2,"maxSizeMB":10},{"id":"blk_bikewhee04","ref":"axle","title":"How is the wheel held in the frame?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_quick_release_lever","label":"Quick release lever","image_key":null},{"id":"opt_thru_axle","label":"Thru-axle","description":"A thick axle that screws through the frame","image_key":null},{"id":"opt_nuts_on_the","label":"Nuts on the axle","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null}],"allowOther":false},{"id":"blk_bikewhee05","ref":"tubeless","title":"Do you want to run tubeless tyres?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes","label":"Yes","image_key":null},{"id":"opt_no_i_ll","label":"No, I''ll stick with tubes","image_key":null},{"id":"opt_not_sure_what","label":"Not sure what that means","image_key":null}],"allowOther":false},{"id":"blk_bikewhee06","ref":"load","title":"Will the wheels carry extra load, like panniers, a child seat or a heavier rider?","description":"Stronger builds with more spokes are worth it here.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_bikewhee07","ref":"priorities","title":"Rank what matters most in your new wheels.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"ranking","items":[{"id":"opt_item_durability","label":"Durability"},{"id":"opt_item_low_weight","label":"Low weight"},{"id":"opt_item_speed_and","label":"Speed and aerodynamics"},{"id":"opt_item_comfort","label":"Comfort"},{"id":"opt_item_price","label":"Price"}]},{"id":"blk_bikewhee08","ref":"budget","title":"What budget do you have in mind for the pair?","description":"Replace these tiers with the price ranges you sell.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_budget_friendly","label":"Budget friendly","image_key":null},{"id":"opt_mid_range","label":"Mid range","image_key":null},{"id":"opt_high_end","label":"High end","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}]},{"id":"blk_bikewhee09","ref":"email","title":"Where should we send the wheels that fit?","description":"Optional, but we need it to reply if you sent a photo.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_bikewhee10","ref":"riding","title":"Last question: where do you ride most?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_tarmac_training_and","label":"Tarmac, training and fast group rides","image_key":null},{"id":"opt_gravel_towpaths_and","label":"Gravel, towpaths and mixed surfaces","image_key":null},{"id":"opt_mountain_bike_trails","label":"Mountain bike trails","image_key":null},{"id":"opt_commuting_and_getting","label":"Commuting and getting around town","image_key":null}],"allowOther":false}],"endings":[{"id":"end_bikewhee01","ref":"end_thanks","title":"A durable commuter wheelset 🏙️","bodyMd":"For daily riding, a strong wheel with more spokes and reliable sealed bearings will outlast lighter options and needs less truing. Pair it with puncture-resistant tyres and it''ll handle potholes and kerbs for years.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bikewhee02","ref":"end_road","title":"A lightweight road wheelset 🚴","bodyMd":"Lighter rims spin up faster and deeper profiles hold speed on flat roads, which is where road wheels earn their money. We''ll match the brake type and axle you gave us, and suggest a stronger build if you''re carrying extra load.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bikewhee03","ref":"end_gravel","title":"A tough, wide gravel wheelset 🪨","bodyMd":"Wider rims support bigger tyres at lower pressure, which means more grip and comfort on rough surfaces. Tubeless-ready gravel wheels also shrug off the small punctures that come with it.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bikewhee04","ref":"end_mtb","title":"A trail-ready mountain bike wheelset 🌲","bodyMd":"Trail wheels need to take hits more than save grams, so look for strong rims, a solid hub and tubeless compatibility. We''ll check your wheel size and axle standard before suggesting a pair.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_bikewhee01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"brakes"},"op":"eq","value":"opt_rim_brakes"}],"groups":[]},"from":"brakes","target":"axle","targetKind":"block","branch":"true"},{"id":"rl_bikewhee02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"brakes"},"op":"eq","value":"opt_disc_brakes"}],"groups":[]},"from":"brakes","target":"axle","targetKind":"block","branch":"true"},{"id":"rl_bikewhee03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"brakes"},"op":"eq","value":"opt_not_sure"}],"groups":[]},"from":"brakes","target":"bike_photo","targetKind":"block","branch":"true"},{"id":"rl_bikewhee04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"riding"},"op":"eq","value":"opt_tarmac_training_and"}],"groups":[]},"from":"riding","target":"end_road","targetKind":"ending","branch":"true"},{"id":"rl_bikewhee05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"riding"},"op":"eq","value":"opt_gravel_towpaths_and"}],"groups":[]},"from":"riding","target":"end_gravel","targetKind":"ending","branch":"true"},{"id":"rl_bikewhee06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"riding"},"op":"eq","value":"opt_mountain_bike_trails"}],"groups":[]},"from":"riding","target":"end_mtb","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
