INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_boardgamerecommendationq', 'board-game-recommendation-quiz', 'Board game recommendation quiz', 'Quiz', 'Match a group to a party, co-op, gateway, strategy or two-player game.', 'Asks the questions a good game shop assistant asks: how long you have, who''s at the table, what puts them off and what they''ve enjoyed before. Pairs get their own question about competing or cooperating, so nobody playing as two is sent a party game, and larger groups pick the evening they want from four results, each with well-known games to try.', '["product recommendation","board game quiz","game recommendation","game night","board game shop","gift finder"]', 'Dices', 'content', 3, 10, '{"schemaVersion":9,"title":"Board game finder","description":"Match a group to a party, co-op, gateway, strategy or two-player game.","blocks":[{"id":"blk_boardgam00","ref":"welcome","title":"Looking for your next favourite game? Tell us about your table and we''ll suggest where to start.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_boardgam01","ref":"time","title":"How long do you want a game to last?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_under_30_minutes","label":"Under 30 minutes","image_key":null},{"id":"opt_30_minutes_to","label":"30 minutes to an hour","image_key":null},{"id":"opt_one_to_two","label":"One to two hours","image_key":null},{"id":"opt_as_long_as","label":"As long as it takes","image_key":null}],"allowOther":false},{"id":"blk_boardgam02","ref":"ages","title":"Who''s at the table? Pick all that apply.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_children_under_8","label":"Children under 8","image_key":null},{"id":"opt_children_8_to","label":"Children 8 to 12","image_key":null},{"id":"opt_teenagers","label":"Teenagers","image_key":null},{"id":"opt_adults","label":"Adults","image_key":null}],"minSelections":1,"maxSelections":4,"allowOther":false},{"id":"blk_boardgam03","ref":"experience","title":"How experienced is your group with board games?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Monopoly is about it","labelHigh":"We have a shelf full"},{"id":"blk_boardgam04","ref":"avoid","title":"Anything that puts your group off?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_lots_of_rules","label":"Lots of rules to learn","image_key":null},{"id":"opt_taking_things_from","label":"Taking things from other players","image_key":null},{"id":"opt_dice_deciding_who","label":"Dice deciding who wins","image_key":null},{"id":"opt_lots_of_reading","label":"Lots of reading","image_key":null},{"id":"opt_long_setup","label":"Long setup","image_key":null}],"minSelections":0,"maxSelections":5,"allowOther":false},{"id":"blk_boardgam05","ref":"themes","title":"Which themes sound fun?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_fantasy_and_adventure","label":"Fantasy and adventure","image_key":null},{"id":"opt_space_and_science","label":"Space and science fiction","image_key":null},{"id":"opt_nature_and_animals","label":"Nature and animals","image_key":null},{"id":"opt_trains_trade_and","label":"Trains, trade and building","image_key":null},{"id":"opt_mystery_and_deduction","label":"Mystery and deduction","image_key":null},{"id":"opt_no_preference","label":"No preference","image_key":null}],"minSelections":0,"maxSelections":6,"allowOther":false},{"id":"blk_boardgam06","ref":"favourite","title":"Name a game your group already loves, if you have one.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":120},{"id":"blk_boardgam07","ref":"email","title":"Want us to send your recommendations?","description":"Optional.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_boardgam08","ref":"players","title":"Nearly done. How many people usually play?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_just_two","label":"Just two","image_key":null},{"id":"opt_three_or_four","label":"Three or four","image_key":null},{"id":"opt_five_or_six","label":"Five or six","image_key":null},{"id":"opt_seven_or_more","label":"Seven or more","image_key":null}],"allowOther":false},{"id":"blk_boardgam09","ref":"duo_style","title":"Two players it is. How do you like to play?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_head_to_head","label":"Head to head, may the best player win","image_key":null},{"id":"opt_on_the_same","label":"On the same side, against the game","image_key":null}],"allowOther":false},{"id":"blk_boardgam10","ref":"evening","title":"Finally, which game night sounds best?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_loud_silly_and","label":"Loud, silly and full of laughs","image_key":null},{"id":"opt_working_together_to","label":"Working together to beat the game","image_key":null},{"id":"opt_a_friendly_contest","label":"A friendly contest with easy rules","image_key":null},{"id":"opt_a_deep_thinky","label":"A deep, thinky game with long-term plans","image_key":null}],"allowOther":false}],"endings":[{"id":"end_boardgam01","ref":"end_thanks","title":"Gateway strategy games 🚂","bodyMd":"Easy to learn, with enough choices to keep everyone interested. Ticket to Ride, Carcassonne and Azul are favourites for a reason: they suit mixed groups and new players pick them up in one game.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_boardgam02","ref":"end_party","title":"Party games 🎉","bodyMd":"Quick rules, big groups and plenty of shouting. Try Codenames, Just One or Wavelength: each one is taught in a couple of minutes and works with a crowd.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_boardgam03","ref":"end_coop","title":"Cooperative games 🤝","bodyMd":"Everyone wins or loses together, so nobody goes home sore. Forbidden Island is a gentle start, Pandemic is the classic, and The Crew turns a card game into a team puzzle.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_boardgam04","ref":"end_heavy","title":"Heavy strategy games 🧠","bodyMd":"Your group wants decisions that pay off an hour later. Terraforming Mars and Brass: Birmingham reward planning and repeat plays, so set aside a full evening for the first game.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_boardgam05","ref":"end_duo","title":"Two-player games ⚔️","bodyMd":"Games designed for two are tighter than big games played with two. 7 Wonders Duel, Patchwork and Jaipur each play in under an hour and stay tense to the end.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_boardgam01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"evening"},"op":"eq","value":"opt_loud_silly_and"}],"groups":[]},"from":"evening","target":"end_party","targetKind":"ending","branch":"true"},{"id":"rl_boardgam02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"evening"},"op":"eq","value":"opt_working_together_to"}],"groups":[]},"from":"evening","target":"end_coop","targetKind":"ending","branch":"true"},{"id":"rl_boardgam03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"evening"},"op":"eq","value":"opt_a_deep_thinky"}],"groups":[]},"from":"evening","target":"end_heavy","targetKind":"ending","branch":"true"},{"id":"rl_boardgam04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"players"},"op":"eq","value":"opt_just_two"}],"groups":[]},"from":"players","target":"duo_style","targetKind":"block","branch":"true"},{"id":"rl_boardgam05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"players"},"op":"eq","value":"opt_three_or_four"}],"groups":[]},"from":"players","target":"evening","targetKind":"block","branch":"true"},{"id":"rl_boardgam06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"players"},"op":"eq","value":"opt_five_or_six"}],"groups":[]},"from":"players","target":"evening","targetKind":"block","branch":"true"},{"id":"rl_boardgam07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"players"},"op":"eq","value":"opt_seven_or_more"}],"groups":[]},"from":"players","target":"evening","targetKind":"block","branch":"true"},{"id":"rl_boardgam08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"duo_style"},"op":"eq","value":"opt_head_to_head"}],"groups":[]},"from":"duo_style","target":"end_duo","targetKind":"ending","branch":"true"},{"id":"rl_boardgam09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"duo_style"},"op":"eq","value":"opt_on_the_same"}],"groups":[]},"from":"duo_style","target":"end_coop","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#dbeafe","surface":"#ffffff","text":"#13263f","accent":"#1d4ed8","accentText":"#f7faff","botBubble":"#ffffff","userBubble":"#1d4ed8","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
