INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_bookrecommendationquiz', 'book-recommendation-quiz', 'Book recommendation quiz', 'Quiz', 'Ask about mood and reading habits, then suggest a genre with titles to try next.', 'Starts with the reader rather than the genre shelf: a book they loved, how long they like a book to be and how they read. Their mood then opens a short follow-up of its own, such as how dark a thriller can get, before landing on one of six results with titles to try. Someone who wants a gripping read but nothing grim gets a cosy mystery, not a dark thriller.', '["product recommendation","book recommendation quiz","what to read next","bookshop","library","reading quiz"]', 'BookOpen', 'content', 3, 11, '{"schemaVersion":9,"title":"What should I read next?","description":"Ask about mood and reading habits, then suggest a genre with titles to try next.","blocks":[{"id":"blk_bookreco00","ref":"welcome","title":"Stuck on what to read next? Answer a few questions and we''ll suggest a book to pick up.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_bookreco01","ref":"loved_book","title":"What''s a book you loved recently?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_bookreco02","ref":"length","title":"How long do you like a book to be?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_short_something_i","label":"Short, something I can finish in a weekend","image_key":null},{"id":"opt_any_length_is","label":"Any length is fine","image_key":null},{"id":"opt_long_i_want","label":"Long, I want to live in it","image_key":null}],"allowOther":false},{"id":"blk_bookreco03","ref":"format","title":"How do you like to read?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_print","label":"Print","image_key":null},{"id":"opt_e_reader","label":"E-reader","image_key":null},{"id":"opt_audiobook","label":"Audiobook","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":false},{"id":"blk_bookreco04","ref":"pace","title":"Do you prefer a slow burn or a fast pace?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Slow and immersive","labelHigh":"Can''t stop turning pages"},{"id":"blk_bookreco05","ref":"email","title":"Where should we send your reading list?","description":"Optional.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_bookreco06","ref":"mood","title":"What are you in the mood for right now?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_something_gripping_i","label":"Something gripping I can''t put down","image_key":null},{"id":"opt_a_story_that","label":"A story that takes me somewhere else entirely","image_key":null},{"id":"opt_something_warm_that","label":"Something warm that makes me smile","image_key":null},{"id":"opt_real_life_true","label":"Real life: true stories and big ideas","image_key":null},{"id":"opt_beautiful_writing_that","label":"Beautiful writing that stays with me","image_key":null}],"allowOther":false},{"id":"blk_bookreco07","ref":"darkness","title":"How dark can it get?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_keep_it_cosy","label":"Keep it cosy, nothing grim","image_key":null},{"id":"opt_tense_is_good","label":"Tense is good, but not too gory","image_key":null},{"id":"opt_dark_and_twisty","label":"Dark and twisty is fine","image_key":null}],"allowOther":false},{"id":"blk_bookreco08","ref":"world","title":"Magic or science?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_magic_and_other","label":"Magic and other worlds","image_key":null},{"id":"opt_science_and_the","label":"Science and the future","image_key":null},{"id":"opt_either_works","label":"Either works","image_key":null}],"allowOther":false},{"id":"blk_bookreco09","ref":"warm_kind","title":"Which sounds more like you?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_laugh_out_loud","label":"Laugh-out-loud funny","image_key":null},{"id":"opt_gentle_and_heartwarming","label":"Gentle and heartwarming","image_key":null},{"id":"opt_a_love_story","label":"A love story","image_key":null}],"allowOther":false},{"id":"blk_bookreco10","ref":"topics","title":"Which topics pull you in?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_memoir_and_life","label":"Memoir and life stories","image_key":null},{"id":"opt_history","label":"History","image_key":null},{"id":"opt_science_and_nature","label":"Science and nature","image_key":null},{"id":"opt_psychology_and_how","label":"Psychology and how people think","image_key":null},{"id":"opt_true_crime","label":"True crime","image_key":null}],"minSelections":1,"maxSelections":5,"allowOther":false},{"id":"blk_bookreco11","ref":"literary_setting","title":"Where would you like the story to be set?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_past","label":"The past","image_key":null},{"id":"opt_the_present_day","label":"The present day","image_key":null},{"id":"opt_somewhere_slightly_off","label":"Somewhere slightly off from our world","image_key":null},{"id":"opt_anywhere","label":"Anywhere","image_key":null}],"allowOther":false}],"endings":[{"id":"end_bookreco01","ref":"end_thanks","title":"Literary fiction 📖","bodyMd":"You read for the writing and the characters that stay with you. Try Never Let Me Go by Kazuo Ishiguro or Tomorrow, and Tomorrow, and Tomorrow by Gabrielle Zevin.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bookreco02","ref":"end_thriller","title":"A page-turning thriller 🔪","bodyMd":"You want momentum and a twist you didn''t see coming. Try Gone Girl by Gillian Flynn or The Silent Patient by Alex Michaelides: both are hard to put down once they get going.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bookreco03","ref":"end_cosy_mystery","title":"A cosy mystery 🫖","bodyMd":"All the fun of a whodunnit without the grim parts. Try The Thursday Murder Club by Richard Osman, where four friends in a retirement village take on a real murder case.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bookreco04","ref":"end_speculative","title":"Fantasy or science fiction 🚀","bodyMd":"You want a whole new world to get lost in. For science, Project Hail Mary by Andy Weir is clever and funny. For magic, The Name of the Wind by Patrick Rothfuss is a long, rich read.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bookreco05","ref":"end_feelgood","title":"A feel-good novel ☀️","bodyMd":"Warmth and humour it is. A Man Called Ove by Fredrik Backman and The House in the Cerulean Sea by TJ Klune are both funny, kind and quietly moving. If it''s romance you''re after, Beach Read by Emily Henry is a warm, witty place to start.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bookreco06","ref":"end_nonfiction","title":"Narrative nonfiction 🧭","bodyMd":"True stories told as well as any novel. Educated by Tara Westover is a gripping memoir, and Sapiens by Yuval Noah Harari is a big-picture read that sparks conversations.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_bookreco01","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"world","target":"end_speculative","targetKind":"ending"},{"id":"rl_bookreco02","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"warm_kind","target":"end_feelgood","targetKind":"ending"},{"id":"rl_bookreco03","action_kind":"goto","when":{"op":"and","conditions":[],"groups":[]},"from":"topics","target":"end_nonfiction","targetKind":"ending"},{"id":"rl_bookreco04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"mood"},"op":"eq","value":"opt_something_gripping_i"}],"groups":[]},"from":"mood","target":"darkness","targetKind":"block","branch":"true"},{"id":"rl_bookreco05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"mood"},"op":"eq","value":"opt_a_story_that"}],"groups":[]},"from":"mood","target":"world","targetKind":"block","branch":"true"},{"id":"rl_bookreco06","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"mood"},"op":"eq","value":"opt_something_warm_that"}],"groups":[]},"from":"mood","target":"warm_kind","targetKind":"block","branch":"true"},{"id":"rl_bookreco07","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"mood"},"op":"eq","value":"opt_real_life_true"}],"groups":[]},"from":"mood","target":"topics","targetKind":"block","branch":"true"},{"id":"rl_bookreco08","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"mood"},"op":"eq","value":"opt_beautiful_writing_that"}],"groups":[]},"from":"mood","target":"literary_setting","targetKind":"block","branch":"true"},{"id":"rl_bookreco09","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"darkness"},"op":"eq","value":"opt_keep_it_cosy"}],"groups":[]},"from":"darkness","target":"end_cosy_mystery","targetKind":"ending","branch":"true"},{"id":"rl_bookreco10","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"darkness"},"op":"eq","value":"opt_tense_is_good"}],"groups":[]},"from":"darkness","target":"end_thriller","targetKind":"ending","branch":"true"},{"id":"rl_bookreco11","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"darkness"},"op":"eq","value":"opt_dark_and_twisty"}],"groups":[]},"from":"darkness","target":"end_thriller","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
