VALUES ('tpl_boulepatanquerecommendat', 'boule-patanque-recommendation-quiz', 'Pétanque boules quiz', 'Quiz', 'Send leisure players to a garden set and match club players to boules for pointing or shooting.', 'Splits early between people playing for fun and people playing in a club, because they need different boules. Leisure players are asked where and with whom they play, while club players answer about hand size, grip and weight before their playing position picks a pointer, shooter or all-round result.', '["product recommendation","petanque boules quiz","boules buying guide","petanque shop","competition boules","garden games"]', 'Target', 'content', 4, 11, '{"schemaVersion":9,"title":"Pétanque boule finder","description":"Send leisure players to a garden set and match club players to boules for pointing or shooting.","blocks":[{"id":"blk_boulepat00","ref":"welcome","title":"Choosing pétanque boules? A few questions about how you play and we''ll suggest the right set.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_boulepat01","ref":"experience","title":"How long have you been playing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_i_m_just","label":"I''m just starting out","image_key":null},{"id":"opt_a_few_seasons","label":"A few seasons, casually","image_key":null},{"id":"opt_years_i_play","label":"Years, I play in a club","image_key":null}],"allowOther":false},{"id":"blk_boulepat02","ref":"for_whom","title":"Who are the boules for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_me","label":"Me","image_key":null},{"id":"opt_a_gift_for","label":"A gift for someone else","image_key":null},{"id":"opt_a_club_or","label":"A club or group","image_key":null}],"allowOther":false},{"id":"blk_boulepat03","ref":"email","title":"Where should we send your suggestion?","description":"Optional.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"email","unique":false,"businessOnly":false,"allowedDomains":[],"verify":false},{"id":"blk_boulepat04","ref":"competition","title":"Will the boules be used in club matches or competitions?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_yes_club_or","label":"Yes, club or competition play","image_key":null},{"id":"opt_no_just_for","label":"No, just for fun","image_key":null}],"allowOther":false},{"id":"blk_boulepat05","ref":"hand_size","title":"How would you describe your hand size?","description":"Your boule should sit comfortably in your palm with your fingers wrapped around it.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_small","label":"Small","image_key":null},{"id":"opt_medium","label":"Medium","image_key":null},{"id":"opt_large","label":"Large","image_key":null},{"id":"opt_not_sure","label":"Not sure","image_key":null}],"allowOther":false},{"id":"blk_boulepat06","ref":"grip","title":"Which surface do you prefer?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_smooth","label":"Smooth","image_key":null},{"id":"opt_lightly_grooved","label":"Lightly grooved","image_key":null},{"id":"opt_deeply_grooved","label":"Deeply grooved","image_key":null},{"id":"opt_no_preference","label":"No preference","image_key":null}],"allowOther":false},{"id":"blk_boulepat07","ref":"weight_feel","title":"Do you like a boule that feels light or heavy in the hand?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"Light","labelHigh":"Heavy"},{"id":"blk_boulepat08","ref":"engraving","title":"Would you like your initials or a name engraved on the set?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"yes_no","yesLabel":"Yes","noLabel":"No"},{"id":"blk_boulepat09","ref":"position","title":"Which role do you usually play on your team?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_pointer","label":"Pointer","description":"I roll close to the jack","image_key":null},{"id":"opt_shooter","label":"Shooter","description":"I knock opponents'' boules away","image_key":null},{"id":"opt_a_bit_of","label":"A bit of both","image_key":null}],"allowOther":false},{"id":"blk_boulepat10","ref":"where","title":"Where will you mostly play?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_in_the_garden","label":"In the garden or on a lawn","image_key":null},{"id":"opt_on_the_beach","label":"On the beach","image_key":null},{"id":"opt_on_gravel_in","label":"On gravel in a park","image_key":null},{"id":"opt_all_over_the","label":"All over the place","image_key":null}],"allowOther":false},{"id":"blk_boulepat11","ref":"who_plays","title":"Who will be playing?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_adults","label":"Adults","image_key":null},{"id":"opt_children","label":"Children","image_key":null},{"id":"opt_older_players","label":"Older players","image_key":null}],"minSelections":1,"maxSelections":3,"allowOther":false}],"endings":[{"id":"end_boulepat01","ref":"end_thanks","title":"A leisure set for fun 🏖️","bodyMd":"For garden, beach and park games you don''t need competition boules. A leisure set in a carry bag with a jack and a measuring tape is ideal, and lighter sets are easier for children and older players to throw.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_boulepat02","ref":"end_pointer","title":"Competition boules for pointing 🎯","bodyMd":"Pointers often choose a slightly smaller, heavier boule that stays where it lands, with grooves for a sure grip. We''ll suggest competition-approved sets in the size that fits your hand.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_boulepat03","ref":"end_shooter","title":"Competition boules for shooting 💥","bodyMd":"Shooters often prefer a slightly larger, lighter boule that is easier to throw hard and accurately. We''ll suggest competition-approved sets that suit your hand and the grip you like.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_boulepat04","ref":"end_allround","title":"An all-round competition set ⚖️","bodyMd":"If you point and shoot, a mid-weight boule in a size that fits your hand is the safe choice. It won''t be the specialist''s pick for either role, but it lets you play both without switching sets.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_boulepat01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"competition"},"op":"eq","value":"opt_yes_club_or"}],"groups":[]},"from":"competition","target":"hand_size","targetKind":"block","branch":"true"},{"id":"rl_boulepat02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"competition"},"op":"eq","value":"opt_no_just_for"}],"groups":[]},"from":"competition","target":"where","targetKind":"block","branch":"true"},{"id":"rl_boulepat03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"position"},"op":"eq","value":"opt_pointer"}],"groups":[]},"from":"position","target":"end_pointer","targetKind":"ending","branch":"true"},{"id":"rl_boulepat04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"position"},"op":"eq","value":"opt_shooter"}],"groups":[]},"from":"position","target":"end_shooter","targetKind":"ending","branch":"true"},{"id":"rl_boulepat05","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"position"},"op":"eq","value":"opt_a_bit_of"}],"groups":[]},"from":"position","target":"end_allround","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"dark","background":"#f26b1d","surface":"#fff7f0","text":"#1c1917","accent":"#1c1917","accentText":"#ffffff","botBubble":"#fff7f0","userBubble":"#1c1917","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"wave","backgroundPatternColor":"#1c1917","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
