VALUES ('tpl_bridalaccessoriesrecomme', 'bridal-accessories-recommendation-quiz', 'Bridal accessories quiz', 'Quiz', 'Match accessories to the dress, hair and wedding style, then suggest a coordinated look.', 'Asks about the dress first, because neckline and detail decide most accessory choices, then hair, metals, comfort and what''s still missing. The bride''s overall style picks one of four coordinated looks, and her wedding date and budget go to your dashboard for the follow-up.', '["product recommendation","bridal accessories quiz","wedding veil quiz","bridal jewellery","bridal boutique","wedding style"]', 'Gem', 'content', 3, 10, '{"schemaVersion":9,"title":"Bridal accessories finder","description":"Match accessories to the dress, hair and wedding style, then suggest a coordinated look.","blocks":[{"id":"blk_bridalac00","ref":"welcome","title":"Congratulations! Let''s find the finishing touches for your wedding look.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_bridalac01","ref":"wedding_date","title":"When''s the wedding?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_bridalac02","ref":"neckline","title":"What neckline does your dress have?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_strapless_or_sweetheart","label":"Strapless or sweetheart","image_key":null},{"id":"opt_v_neck","label":"V-neck","image_key":null},{"id":"opt_off_the_shoulder","label":"Off the shoulder","image_key":null},{"id":"opt_high_neck_or","label":"High neck or halter","image_key":null},{"id":"opt_square_or_straight","label":"Square or straight","image_key":null},{"id":"opt_still_choosing_my","label":"Still choosing my dress","image_key":null}]},{"id":"blk_bridalac03","ref":"dress_detail","title":"How much detail does the dress have?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_lots_of_beading","label":"Lots of beading, lace or sparkle","image_key":null},{"id":"opt_some_detail","label":"Some detail","image_key":null},{"id":"opt_clean_and_simple","label":"Clean and simple","image_key":null}],"allowOther":false},{"id":"blk_bridalac04","ref":"hair","title":"How are you planning to wear your hair?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_up","label":"Up","image_key":null},{"id":"opt_half_up","label":"Half up","image_key":null},{"id":"opt_down","label":"Down","image_key":null},{"id":"opt_not_decided","label":"Not decided","image_key":null}],"allowOther":false},{"id":"blk_bridalac05","ref":"needs","title":"Which accessories are you still looking for?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_veil","label":"Veil","image_key":null},{"id":"opt_headpiece_or_hair","label":"Headpiece or hair accessory","image_key":null},{"id":"opt_earrings","label":"Earrings","image_key":null},{"id":"opt_necklace","label":"Necklace","image_key":null},{"id":"opt_bracelet","label":"Bracelet","image_key":null},{"id":"opt_belt_or_sash","label":"Belt or sash","image_key":null},{"id":"opt_cover_up_or","label":"Cover-up or shawl","image_key":null}],"minSelections":1,"maxSelections":7,"allowOther":false},{"id":"blk_bridalac06","ref":"metal","title":"Which metal or finish do you wear most?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_silver_or_white","label":"Silver or white gold","image_key":null},{"id":"opt_gold","label":"Gold","image_key":null},{"id":"opt_rose_gold","label":"Rose gold","image_key":null},{"id":"opt_pearls","label":"Pearls","image_key":null},{"id":"opt_a_mix","label":"A mix","image_key":null}],"allowOther":false},{"id":"blk_bridalac07","ref":"comfort","title":"How much do you mind wearing something you can feel all day?","description":"Think heavy earrings, a long veil or a snug headpiece.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"opinion_scale","steps":5,"startAt":1,"labelLow":"I want to forget it''s there","labelHigh":"Worth it for the look"},{"id":"blk_bridalac08","ref":"budget","title":"What budget do you have for accessories?","description":"Replace these with the ranges that fit your boutique.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_keeping_it_modest","label":"Keeping it modest","image_key":null},{"id":"opt_mid_range","label":"Mid range","image_key":null},{"id":"opt_happy_to_splurge","label":"Happy to splurge on the right piece","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}]},{"id":"blk_bridalac09","ref":"contact","title":"Who should we send your look to?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","email","phone"]},{"id":"blk_bridalac10","ref":"style","title":"Last one: which word best describes your wedding style?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_classic_and_timeless","label":"Classic and timeless","image_key":null},{"id":"opt_boho_and_romantic","label":"Boho and romantic","image_key":null},{"id":"opt_modern_and_minimal","label":"Modern and minimal","image_key":null},{"id":"opt_glamorous","label":"Glamorous","image_key":null}],"allowOther":false}],"endings":[{"id":"end_bridalac01","ref":"end_thanks","title":"Classic and timeless 🕊️","bodyMd":"Pearl or diamond-style studs, a fine necklace or none if your neckline is high, and a fingertip or cathedral veil. Classic pieces photograph well and still look right when you look back at the pictures years later.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bridalac02","ref":"end_boho","title":"Soft and romantic 🌿","bodyMd":"A hair vine or floral comb, delicate gold drops and a soft, simple veil, or no veil at all. Loose, natural pieces suit flowing dresses and look lovely with hair worn down or half up.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bridalac03","ref":"end_modern","title":"Clean and modern 🤍","bodyMd":"One strong piece instead of many: sculptural earrings or a sleek bow, with a raw-edge or single-layer veil if you want one. A simple dress lets a single statement accessory stand out.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bridalac04","ref":"end_glam","title":"Full glamour ✨","bodyMd":"Crystal earrings, a sparkling headpiece and a long veil with a beaded or lace edge. If your dress already has a lot of sparkle, pick one of these to shine and keep the rest quiet.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_bridalac01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"neckline"},"op":"eq","value":"opt_still_choosing_my"}],"groups":[]},"from":"neckline","target":"hair","targetKind":"block","branch":"true"},{"id":"rl_bridalac02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"style"},"op":"eq","value":"opt_boho_and_romantic"}],"groups":[]},"from":"style","target":"end_boho","targetKind":"ending","branch":"true"},{"id":"rl_bridalac03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"style"},"op":"eq","value":"opt_modern_and_minimal"}],"groups":[]},"from":"style","target":"end_modern","targetKind":"ending","branch":"true"},{"id":"rl_bridalac04","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"style"},"op":"eq","value":"opt_glamorous"}],"groups":[]},"from":"style","target":"end_glam","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#f1e8dc","surface":"#ffffff","text":"#33271a","accent":"#9a3412","accentText":"#fffaf3","botBubble":"#ffffff","userBubble":"#9a3412","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"grid-fine","backgroundShape":"wave","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
