INSERT INTO form_templates (id, slug, title, category, description, blurb, tags, icon, accent, est_minutes, block_count, schema_json, thumbnail_r2_key, official, organization_id, usage_count, created_at)
VALUES ('tpl_bridesmaiddressrecommend', 'bridesmaid-dress-recommendation-quiz', 'Bridesmaid dress quiz', 'Quiz', 'Suggest matching, same-colour or mix-and-match dresses for the whole bridal party.', 'Collects what a bridal stylist needs before an appointment: the date, how many bridesmaids, the wedding style, colours, length and fit needs across the group. The answer about how matched the party should look sends them to one of three approaches, with a clear suggestion for anyone still unsure.', '["product recommendation","bridesmaid dress quiz","bridal party","bridesmaid colours","bridal boutique","wedding planning"]', 'Users', 'content', 4, 11, '{"schemaVersion":9,"title":"Bridesmaid dress finder","description":"Suggest matching, same-colour or mix-and-match dresses for the whole bridal party.","blocks":[{"id":"blk_bridesma00","ref":"welcome","title":"Dressing the bridal party? Let''s work out an approach that looks great and works for everyone.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"buttonLabel":"Start","type":"welcome"},{"id":"blk_bridesma01","ref":"role","title":"Who''s taking the quiz?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_bride_or","label":"The bride or couple","image_key":null},{"id":"opt_maid_of_honour","label":"Maid of honour","image_key":null},{"id":"opt_a_bridesmaid","label":"A bridesmaid","image_key":null},{"id":"opt_a_wedding_planner","label":"A wedding planner","image_key":null}],"allowOther":false},{"id":"blk_bridesma02","ref":"wedding_date","title":"When''s the wedding?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"date","disablePast":true,"dateFormat":"YYYY-MM-DD","includeTime":false,"timeStepMinutes":30,"timeMin":"09:00","timeMax":"18:00"},{"id":"blk_bridesma03","ref":"party_size","title":"How many bridesmaids need dresses?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"number","unique":false,"min":1,"max":20,"integerOnly":true},{"id":"blk_bridesma04","ref":"wedding_style","title":"What''s the wedding like?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_formal_black_tie","label":"Formal, black tie","image_key":null},{"id":"opt_rustic_or_outdoors","label":"Rustic or outdoors","image_key":null},{"id":"opt_beach_or_destination","label":"Beach or destination","image_key":null},{"id":"opt_city_and_modern","label":"City and modern","image_key":null},{"id":"opt_relaxed_and_boho","label":"Relaxed and boho","image_key":null}],"allowOther":false},{"id":"blk_bridesma05","ref":"colours","title":"What colours are you thinking of?","description":"A colour, a palette, or even a flower you''re matching.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"short_text","unique":false,"minLength":0,"maxLength":150},{"id":"blk_bridesma06","ref":"length","title":"Which length do you want?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_floor_length","label":"Floor length","image_key":null},{"id":"opt_midi","label":"Midi","image_key":null},{"id":"opt_short","label":"Short","image_key":null},{"id":"opt_each_bridesmaid_can","label":"Each bridesmaid can choose","image_key":null}],"allowOther":false},{"id":"blk_bridesma07","ref":"fit_needs","title":"Any fit needs across the group? Pick all that apply.","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"multi_select","options":[{"id":"opt_a_wide_range","label":"A wide range of sizes","image_key":null},{"id":"opt_someone_will_be","label":"Someone will be pregnant","image_key":null},{"id":"opt_sleeves_or_straps","label":"Sleeves or straps wanted","image_key":null},{"id":"opt_pockets_please","label":"Pockets, please","image_key":null},{"id":"opt_different_heights","label":"Different heights","image_key":null},{"id":"opt_none_of_these","label":"None of these","image_key":null}],"minSelections":0,"maxSelections":6,"allowOther":false},{"id":"blk_bridesma08","ref":"who_pays","title":"Who''s paying for the dresses?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_the_couple","label":"The couple","image_key":null},{"id":"opt_each_bridesmaid","label":"Each bridesmaid","image_key":null},{"id":"opt_we_re_splitting","label":"We''re splitting it","image_key":null}],"allowOther":false},{"id":"blk_bridesma09","ref":"budget","title":"What''s the budget per dress?","description":"Replace these tiers with your own price ranges.","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"dropdown","options":[{"id":"opt_budget_friendly","label":"Budget friendly","image_key":null},{"id":"opt_mid_range","label":"Mid range","image_key":null},{"id":"opt_designer","label":"Designer","image_key":null},{"id":"opt_not_sure_yet","label":"Not sure yet","image_key":null}]},{"id":"blk_bridesma10","ref":"contact","title":"Who should we send the suggestions to?","required":false,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"contact_info","fields":["first_name","email","phone"]},{"id":"blk_bridesma11","ref":"matching","title":"Last question: how matched should the bridal party look?","required":true,"visibility":null,"image_key":null,"agentHints":null,"media":null,"type":"single_select","options":[{"id":"opt_identical_dresses","label":"Identical dresses","image_key":null},{"id":"opt_same_colour_each","label":"Same colour, each in her own style","image_key":null},{"id":"opt_a_palette_of","label":"A palette of related colours","image_key":null},{"id":"opt_i_m_not","label":"I''m not sure yet","image_key":null}],"allowOther":false}],"endings":[{"id":"end_bridesma01","ref":"end_thanks","title":"Mix and match a palette 🎨","bodyMd":"Choose three or four related shades and let each bridesmaid pick a dress within them. Keeping the length or fabric the same ties it together, and it suits relaxed, boho and outdoor weddings especially well.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bridesma02","ref":"end_matching","title":"Matching dresses 👗","bodyMd":"One style in one colour gives the neatest photos and suits formal weddings. Choose a forgiving cut, such as a wrap or A-line, in a fabric with a little stretch so every bridesmaid is comfortable. Order early so there''s time for alterations.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]},{"id":"end_bridesma03","ref":"end_same_colour","title":"Same colour, different styles 💐","bodyMd":"Everyone wears the same colour and fabric but picks the neckline and cut that suits her. It still looks planned in photos, and it''s the easiest way to make a group of different shapes and sizes feel good. If you''re unsure, this is the one we''d start with.","imageUrl":null,"redirectDelaySec":4,"showSummary":false,"kind":"success","requirements":[]}],"endingRules":[],"logic":[{"id":"rl_bridesma01","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"matching"},"op":"eq","value":"opt_identical_dresses"}],"groups":[]},"from":"matching","target":"end_matching","targetKind":"ending","branch":"true"},{"id":"rl_bridesma02","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"matching"},"op":"eq","value":"opt_same_colour_each"}],"groups":[]},"from":"matching","target":"end_same_colour","targetKind":"ending","branch":"true"},{"id":"rl_bridesma03","action_kind":"goto","when":{"op":"and","conditions":[{"left":{"kind":"ref","ref":"matching"},"op":"eq","value":"opt_i_m_not"}],"groups":[]},"from":"matching","target":"end_same_colour","targetKind":"ending","branch":"true"}],"layout":{},"variables":[],"hiddenFields":[],"settings":{"language":"en","rtl":false,"progressBar":"percent","navigation":{"allowBack":true,"allowSkip":true},"closeRules":{"closedMessageMd":"This form is no longer accepting responses.","showCountdown":true,"showRemaining":false},"requireAuth":{"enabled":false,"method":"google","message":"Before we start, could you verify who you are? It only takes a moment.","afterBlocks":0},"password":{"enabled":false,"value":""},"captcha":{"enabled":true,"provider":"turnstile","mode":"adaptive"},"allowResubmissions":true,"onComplete":{"requireSubmit":true,"delaySec":4,"notificationEmails":[],"autoReplyEmail":{"enabled":true,"subject":"Thanks for your response","bodyMd":"Thanks for taking the time to fill in {{form.title}}. We''ve got your response, and this email is your copy of it.","includeAnswers":true}},"followUp":{"enabled":false,"channel":"email","steps":[{"delayHours":4,"subject":"You''re {{remaining}} questions from finishing","bodyMd":"Everything you answered is saved, and picking up where you left off takes about a minute."},{"delayHours":24,"subject":"Your {{form.title}} is still open","bodyMd":"Just a nudge in case it slipped. Your answers are still here whenever you''re ready."}],"showProgress":true,"holdoutPercent":0,"quietHours":true},"meta":{"ogImageKey":null,"faviconKey":null,"noIndex":false},"branding":{"hidePoweredBy":false},"embed":{"allowedOrigins":[]},"agent":{"mode":"hybrid","tone":"friendly","language":"en","rephraseQuestions":true,"guardrails":{"answerOffTopic":true,"refusalMessage":"I''m not sure about that one, but I can pass it on. Back to the form:","forbiddenTopics":[]},"maxClarificationsPerBlock":2,"escalateAfterInvalid":3,"responseMaxTokens":400}},"theme":{"colorScheme":"light","background":"#e8f0d8","surface":"#ffffff","text":"#1f2a17","accent":"#4d7c0f","accentText":"#f8fcf3","botBubble":"#ffffff","userBubble":"#4d7c0f","userBubbleText":"#ffffff","radius":"lg","fontHeading":"Bricolage Grotesque","fontBody":"Inter","avatarKey":null,"backgroundImageKey":null,"backgroundBrightness":1,"backgroundPattern":"diagonal","backgroundShape":"blob","logoUrl":null,"logoKey":null}}', NULL, 1, NULL, 0, 1770000000000)
